# Last-resort Bloom level for LO->targets-concept synthesis. When an LO carries
# key_concepts but neither an explicit canonical bloom_level nor a detectable
# verb in its statement, we fall back to this level so the LO's targetedConcepts
# (and the downstream targets-concept edges) are NOT silently dropped. "apply"
# is the median/most-common course-objective level and a safe neutral default.
_FALLBACK_BLOOM_LEVEL = "apply"

# Derived paths
SEMANTIK_BATCH_OUTPUT_DIR = PROJECT_ROOT / "SemantiK" / "batch_output"
COURSEFORGE_INPUTS = PROJECT_ROOT / "Courseforge" / "inputs" / "textbooks"
TRAINING_CAPTURES = PROJECT_ROOT / "training-captures"


# Snapshot of the project root at import time so ``courseforge_exports_dir`` can
# detect which test seam (``PROJECT_ROOT`` / ``_PROJECT_ROOT``) was monkeypatched.
_IMPORT_PROJECT_ROOT = PROJECT_ROOT


def courseforge_exports_dir() -> Path:
    """Resolve the Courseforge exports dir for this module.

    Honors the ED4ALL_HOME relocatable data root via ``lib.paths`` when set;
    otherwise resolves against this module's project root. ``PROJECT_ROOT`` and
    ``_PROJECT_ROOT`` are identical at import time but are two distinct
    long-standing test seams — different phase-handler tests monkeypatch one or
    the other to redirect project exports into a ``tmp_path``. To honor both, we
    use whichever has been patched away from the import-time default
    (``_IMPORT_PROJECT_ROOT``); when neither is patched they're equal so the
    choice is moot. Byte-stable to ``<root> / "Courseforge" / "exports"`` when
    ED4ALL_HOME is unset.
    """
    from lib.paths import ed4all_home  # noqa: PLC0415

    if ed4all_home() is not None:
        return _lib_courseforge_exports_dir()
    # Prefer whichever seam a test redirected; default to PROJECT_ROOT.
    if PROJECT_ROOT != _IMPORT_PROJECT_ROOT:
        root = PROJECT_ROOT
    elif _PROJECT_ROOT != _IMPORT_PROJECT_ROOT:
        root = _PROJECT_ROOT
    else:
        root = PROJECT_ROOT
    return root / "Courseforge" / "exports"

# Backstop regex to scrub Qwen-invented `data-cf-objective-id` values.
# Byte-identical to `_DATA_CF_OBJECTIVE_ID_RE` in
# `Courseforge/router/inter_tier_gates.py` (the validator's read-side
# regex). The rewrite-phase loop substitutes the canonical
# `Block.objective_ids` into emitted content so packaging sees the
# upstream-supplied IDs.
_OBJ_ID_RE = re.compile(r'data-cf-objective-id=["\']([^"\']*)["\']')

# Matches a model-hallucinated STANDALONE ``<data-cf-source-ids="...">``
# element (the 7B rewrite tier occasionally emits the source-ids ATTRIBUTE
# as if it were its own tag, carrying a raw non-``dart:`` chunk id). It is
# never a valid emit — ``data-cf-source-ids`` is an attribute on a real
# wrapper. The bogus element trips both the source-ref shape gate and the
# html_shape parser (unbalanced tag). Stripped in the rewrite backstop.
_BOGUS_SOURCE_ID_EL_RE = re.compile(
    r'<\s*/?\s*data-cf-source-ids\b[^>]*>', re.IGNORECASE
)

# Matches a ``data-cf-source-ids="..."`` ATTRIBUTE (any element). The 7B
# rewrite tier stamps this attribute with concept CURIEs
# (``slug:concept_name``) instead of the canonical ``dart:{slug}#{chunk}``
# source refs the rewrite_source_refs gate requires. The rewrite backstop
# scrapes the offending value (to preserve the CURIEs as the curie-anchoring
# signal) and OVERWRITES the attribute with canonical dart: refs resolved from
# the block's real source chunks. Capture group 1 is the raw attribute value.
_SOURCE_IDS_ATTR_RE = re.compile(
    r'\s*data-cf-source-ids=["\']([^"\']*)["\']'
)

# Canonical ``{dart|semantik}:{slug}#{block_id}`` source-id shape — mirrors
# ``Courseforge/router/inter_tier_gates._SOURCE_ID_RE`` (the validator's
# read-side check). A scraped attribute token already matching this shape is a
# legitimate source ref and is preserved; anything else (a CURIE) is replaced.
# DART->semantik purge Stage 1 (dual-READ): accepts the legacy ``dart:`` prefix
# AND the ratified ``semantik:`` prefix. Emitters unchanged this stage.
_CANONICAL_DART_SOURCE_ID_RE = re.compile(
    r"^(?:dart|semantik):[a-z0-9_-]+#[a-z0-9_-]+$"
)

# First HTML start tag, capturing the tag name and the rest of the open
# tag (used to inject a dropped ``data-cf-block-id`` attribute).
_FIRST_START_TAG_RE = re.compile(r'<\s*([a-zA-Z][\w-]*)((?:\s[^>]*)?)(/?)>')


def _inject_block_id_attr(html: str, block_id: str) -> str:
    """Stamp ``data-cf-block-id="{block_id}"`` onto the first start tag.

    The rewrite tier sometimes drops the ``data-cf-block-id`` attribute the
    html_shape gate requires per block_type even though the id is canonical
    and known. Deterministically inject it onto the first element rather than
    re-rolling the slow local model purely for a missing attribute. No-op when
    no start tag is found (leaves the content unchanged so the gate still
    fails closed on genuinely non-HTML emit).
    """
    if not block_id:
        return html

    def _repl(match: "re.Match") -> str:
        tag, attrs, closing = match.group(1), match.group(2), match.group(3)
        return f'<{tag}{attrs} data-cf-block-id="{block_id}"{closing}>'

    return _FIRST_START_TAG_RE.sub(_repl, html, count=1)


def _html_has_block_id_attr(html: str) -> bool:
    """True iff ``data-cf-block-id`` parses as a real attribute on some element.

    The rewrite-tier block-id backstop must mirror what
    ``RewriteHtmlShapeValidator`` actually checks: the gate scrapes every
    parsed start/self-closing tag's ``data-cf-*`` attribute NAMES into its
    ``found_attrs`` set (see ``rewrite_html_shape._ShapeParser.handle_starttag``)
    and fails ``REWRITE_MISSING_REQUIRED_ATTR`` when ``data-cf-block-id`` is
    absent from that set. A naive ``"data-cf-block-id" in html`` substring test
    is WRONG here — the literal token can appear in prose / comment / CDATA text
    (the 7B sometimes narrates the contract) without ever landing as a parseable
    attribute, so the substring guard skips injection while the gate still sees
    a missing attribute → critical ``REWRITE_MISSING_REQUIRED_ATTR`` on a block
    whose id is known. This helper parses with the stdlib ``HTMLParser`` (same
    engine the gate uses) and returns True only when the attribute is genuinely
    present on an element. On a parser exception it falls back to the substring
    check (best-effort; never crashes the backstop).
    """
    if "data-cf-block-id" not in html:
        return False
    from html.parser import HTMLParser  # noqa: PLC0415

    class _AttrProbe(HTMLParser):
        def __init__(self) -> None:
            super().__init__(convert_charrefs=True)
            self.found = False

        def _scan(self, attrs: "list") -> None:
            for name, _value in attrs:
                if name and name.lower() == "data-cf-block-id":
                    self.found = True

        def handle_starttag(self, tag: str, attrs: "list") -> None:
            self._scan(attrs)

        def handle_startendtag(self, tag: str, attrs: "list") -> None:
            self._scan(attrs)

    probe = _AttrProbe()
    try:
        probe.feed(html)
        probe.close()
    except Exception:  # noqa: BLE001 — defensive: fall back to substring
        return "data-cf-block-id" in html
    return probe.found


def _inject_source_ids_attr(html: str, source_ids_value: str) -> str:
    """Stamp ``data-cf-source-ids="{value}"`` onto the first start tag.

    Used by the rewrite backstop when a block resolves to canonical
    ``dart:`` source refs but the rewrite-tier HTML carried no
    ``data-cf-source-ids`` attribute at all (the 7B sometimes omits it on a
    prose block). Mirrors :func:`_inject_block_id_attr`. No-op when no start
    tag is found or the value is empty.
    """
    if not source_ids_value:
        return html

    def _repl(match: "re.Match") -> str:
        tag, attrs, closing = match.group(1), match.group(2), match.group(3)
        return (
            f'<{tag}{attrs} data-cf-source-ids="{source_ids_value}"{closing}>'
        )

    return _FIRST_START_TAG_RE.sub(_repl, html, count=1)


# Rewrite-tier block_type -> canonical ChunkType content-type label. The
# rewrite LLM stamps ``data-cf-content-type`` on prose block types
# (explanation / example) via their ``<h2>`` heading, but the bloom-diversity
# component block types (``self_check_question`` / ``activity``) render as a
# ``<div class="self-check">`` / ``<div class="activity">`` wrapper carrying
# component/purpose/bloom attributes but NO content-type — so
# ``BlockContentTypeValidator`` (which audits every non-scaffolding block for a
# ``data-cf-content-type`` in the canonical taxonomy) fires
# OUTLINE_BLOCK_MISSING_CONTENT_TYPE on every one of them. Values MUST be
# members of ``lib/validators/content_type.py::get_valid_chunk_types`` (the
# Trainforge ChunkType enum): ``self_check_question`` is a formative-assessment
# item → ``assessment_item``; ``activity`` is hands-on practice → ``exercise``.
# Block types absent from this map keep whatever content-type the rewrite LLM
# authored (or are scaffolding the gate skips). Mirrors the canonical
# value choices in ``Courseforge/scripts/blocks.py::_self_check_question_attrs``
# / ``_activity_attrs`` (which themselves carry no content-type — the
# templated-emit path the rewrite tier replaces).
# block_type -> canonical ChunkType label backstop. The COMPLETE map (every
# non-scaffolding BLOCK_TYPES member) lives in the single-source-of-truth module
# ``lib/ontology/content_types.py``; this alias keeps the historical symbol name
# (referenced by the drift-guard test) pointing at the canonical map so the
# str-rewrite backstop and the ``generate_course.py`` renderer never drift.
# Before the SoT this map carried only the component / new-block-type tokens, so
# the backstop could not fill a content-type for the rest of the palette
# (``scenario`` / ``problem`` / ``concept`` / …) when the rewrite LLM omitted it
# → BlockContentTypeValidator fired OUTLINE_BLOCK_MISSING_CONTENT_TYPE on
# a calibration run. The scaffolding skip set (objective / chrome / recap) is NOT
# keyed — the gate skips those.
from lib.ontology.content_types import (  # noqa: E402
    BLOCK_TYPE_CONTENT_TYPE as _REWRITE_BLOCK_TYPE_CONTENT_TYPE,
    resolve_block_content_type as _resolve_block_content_type,
    get_valid_content_types as _get_valid_content_types_for_backstop,
)

# Valid ChunkType labels resolved ONCE at import. The content-type backstop
# REPAIRS an invalid data-cf-content-type value (one not in this set) — not just
# fills a missing one — so a rewrite-LLM-authored ``data-cf-content-type=
# "expression"`` (a domain term the planner / LLM wrote into the content-type
# slot, which fails BlockContentTypeValidator's enum check with
# OUTLINE_BLOCK_INVALID_CONTENT_TYPE) is replaced with the block_type's canonical
# default rather than left to fail.
_VALID_CONTENT_TYPES: "frozenset[str]" = _get_valid_content_types_for_backstop()


# Matches the data-cf-content-type attribute (value captured) for the
# repair-invalid pass. Mirrors the str-path scrape regex in
# ``Courseforge/router/inter_tier_gates.py::_DATA_CF_CONTENT_TYPE_RE``.
_DATA_CF_CONTENT_TYPE_ATTR_RE = re.compile(
    r'data-cf-content-type=["\']([^"\']*)["\']'
)


def _repair_invalid_content_type_attr(html: str, block_type: Optional[str]) -> str:
    """Replace an INVALID ``data-cf-content-type`` value with the canonical one.

    Idempotent + surgical: only the data-cf-content-type attribute value is
    touched, and ONLY when the present value is NOT a member of the ChunkType
    enum. A missing attribute is left to :func:`_inject_content_type_attr` (this
    function never adds the attribute). A valid value is preserved verbatim. A
    block_type with no canonical default (or an empty valid-type set) is a
    no-op. Re-running finds a now-valid value and does nothing.
    """
    if "data-cf-content-type" not in html or not _VALID_CONTENT_TYPES:
        return html
    canonical = _resolve_block_content_type(block_type)
    if not canonical:
        return html

    def _repl(match: "re.Match") -> str:
        current = match.group(1).strip()
        if current in _VALID_CONTENT_TYPES:
            return match.group(0)
        return f'data-cf-content-type="{canonical}"'

    return _DATA_CF_CONTENT_TYPE_ATTR_RE.sub(_repl, html)


def _apply_content_type_backstop(
    html: str, block_type: Optional[str]
) -> "Tuple[str, bool, bool]":
    """Fill a missing content-type OR repair an invalid one in one shot.

    Returns ``(new_html, filled, repaired)``. ``filled`` is True when the
    attribute was absent and the canonical default was injected; ``repaired`` is
    True when a present-but-invalid value was replaced. At most one of the two
    fires per block (fill only happens when the attr is absent; repair only when
    it is present). A block_type with no canonical default leaves the HTML
    untouched (returns the original + both flags False).
    """
    canonical = _resolve_block_content_type(block_type)
    if not canonical:
        return html, False, False
    if "data-cf-content-type" not in html:
        return _inject_content_type_attr(html, canonical), True, False
    repaired_html = _repair_invalid_content_type_attr(html, block_type)
    return repaired_html, False, repaired_html != html


def _inject_content_type_attr(html: str, content_type_value: str) -> str:
    """Stamp ``data-cf-content-type="{value}"`` onto the first start tag.

    Used by the rewrite backstop for component block types
    (``self_check_question`` / ``activity``) whose rewrite-tier HTML carries
    no ``data-cf-content-type`` attribute (the LLM stamps component/purpose
    attributes instead). Mirrors :func:`_inject_source_ids_attr`. No-op when
    the value is empty, the attribute is already present (idempotent — a
    re-run finds the attribute and does not double-stamp), or no start tag is
    found.
    """
    if not content_type_value:
        return html
    if "data-cf-content-type" in html:
        return html

    def _repl(match: "re.Match") -> str:
        tag, attrs, closing = match.group(1), match.group(2), match.group(3)
        return (
            f'<{tag}{attrs} data-cf-content-type="{content_type_value}"'
            f'{closing}>'
        )

    return _FIRST_START_TAG_RE.sub(_repl, html, count=1)


# Matches the appended hidden ``<span ... data-cf-curie="...">...</span>`` the
# rewrite backstop injects as the curie-anchoring signal. Used to STRIP a junk
# span (one whose text content carried only bare chunk ids, which are not
# extractable CURIEs) so the minting path can re-inject a real CURIE span.
# Non-greedy body; idempotent (a re-run with no junk span finds nothing).
_CURIE_SPAN_EL_RE = re.compile(
    r'<\s*span\b[^>]*\bdata-cf-curie\b[^>]*>.*?<\s*/\s*span\s*>',
    re.IGNORECASE | re.DOTALL,
)

# Matches an ORPHAN (unterminated) junk curie-span open tag plus its immediate
# text run. Observed on a real rewrite export: the forced-inject path emitted
# ``<span hidden data-cf-curie="some-tag" data-cf-curie-forced="true">some-tag
# </div>`` — the span is never closed by ``</span>`` (a stray ``</div>``
# "terminates" it), so ``_CURIE_SPAN_EL_RE`` cannot strip it. The literal
# ``data-cf-curie`` substring then survives in the HTML and the minting
# idempotence guard (``"data-cf-curie" not in new_content``) permanently
# REFUSES to append a freshly-minted real CURIE span — the block stays
# curieless even though its prose names a vocabulary concept. This pattern
# removes only the orphan open tag + its token text (up to the next ``<``);
# any stray close tag that "terminated" the span belongs to the surrounding
# block markup and is deliberately left intact (removal-only, tag-balance is
# the HTML-shape repairer's job). Applied ONLY after ``_CURIE_SPAN_EL_RE``
# has removed every well-formed span, so remaining matches are unterminated
# by construction.
_CURIE_SPAN_ORPHAN_OPEN_RE = re.compile(
    r'<\s*span\b[^>]*\bdata-cf-curie\b[^>]*>[^<]*',
    re.IGNORECASE,
)

# Matches an orphan ``data-cf-curie-forced="true"`` junk-marker attribute that
# survived OUTSIDE a strippable span. Observed on a real rewrite export: the
# forced-inject markup got fused into a host tag's attribute area (no ``<span``
# at all — e.g. ``...#s862"messaging" data-cf-curie-forced="true">messaging
# </section>``), so neither span regex fires, yet the surviving literal
# ``data-cf-curie`` substring (inside ``data-cf-curie-forced``) still trips
# the minting idempotence guard. The marker is emitted ONLY by the forced-
# inject path, so removing the bare attribute residue is always junk removal.
_CURIE_FORCED_MARKER_RE = re.compile(
    r'\s*\bdata-cf-curie-forced\s*=\s*(["\'])true\1',
    re.IGNORECASE,
)


def _strip_junk_curie_spans(html: str) -> str:
    """Strip junk ``data-cf-curie`` markup, including UNTERMINATED spans.

    Three-stage removal shared by every junk-span strip site (the restamp
    helper, the in-loop rewrite backstop, and the final anchoring sweep):

    1. ``_CURIE_SPAN_EL_RE`` removes every well-formed
       ``<span ... data-cf-curie ...>...</span>`` element.
    2. If a ``data-cf-curie`` occurrence survives (an orphan open tag whose
       span was never closed by ``</span>``),
       ``_CURIE_SPAN_ORPHAN_OPEN_RE`` removes the open tag plus its
       immediate text run. Stray close tags are left for the HTML-shape
       repairer (removal-only contract).
    3. If an occurrence STILL survives, it is the forced-inject junk marker
       fused into a host tag's attribute area;
       ``_CURIE_FORCED_MARKER_RE`` removes the bare
       ``data-cf-curie-forced="true"`` residue so the minting idempotence
       guard is no longer tripped by a marker that anchors nothing.

    Idempotent: HTML with no junk markup round-trips unchanged.
    """
    if not html or "data-cf-curie" not in html:
        return html
    out = _CURIE_SPAN_EL_RE.sub("", html)
    if "data-cf-curie" in out:
        out = _CURIE_SPAN_ORPHAN_OPEN_RE.sub("", out)
    if "data-cf-curie" in out:
        out = _CURIE_FORCED_MARKER_RE.sub("", out)
    return out

# ---------------------------------------------------------------------------
# P0 — CURIE / LO-id leak sanitizer (7B→Sonnet parity, Wave 1).
# ---------------------------------------------------------------------------
#
# The two-pass rewrite tier leaks two synthetic-token classes into VISIBLE
# prose that a learner should never read:
#
#   1. Minted CURIEs (``prefix:localname`` — e.g. ``samplecourse:integers``)
#      that the dynamic-CURIE-minting pass attaches as an anchoring signal. The
#      ANCHORING signal belongs in the hidden ``<span data-cf-curie>`` ONLY;
#      every visible occurrence (bare token, ``<code>prefix:localname</code>``,
#      ``data-cf-term="<full CURIE>"``) must be replaced by the CURIE's natural
#      surface term so the published prose reads cleanly.
#   2. Bare ``TO-NN`` / ``CO-NN`` objective ids rendered as the visible body of
#      an objectives ``<li>`` (instead of the objective STATEMENT).
#
# These helpers are standalone + pure so the post-hoc regex path can re-run
# them over an already-emitted export without re-dispatching the LLM.

# Matches a bare CURIE-shaped token (``prefix:localname``) anywhere in prose.
# Prefix is a lowercase alnum word; localname allows ``_`` and ``-`` so a
# minted ``samplecourse:least_common_multiple`` matches. Built per-CURIE at
# call time (escaped) rather than a single broad regex, so we only ever rewrite
# the SPECIFIC minted tokens for this course (never an unrelated ``foo:bar``).


def _curie_visible_to_surface(html: str, curie: str, surface: str) -> str:
    """Replace every VISIBLE occurrence of ``curie`` in ``html`` with ``surface``.

    Rewrites three leak shapes, leaving the hidden ``<span data-cf-curie>``
    (whose tokens are the anchoring signal) untouched:

      * ``<code>prefix:localname</code>`` (and ``<kbd>`` / ``<samp>``) → the
        surface term as plain text (the wrapping tag is dropped — a surface
        term is prose, not code voice).
      * ``data-cf-term="<full CURIE>"`` → ``data-cf-term="<localname>"`` (the
        canonical inline-term attribute carries the local slug, not the full
        synthetic CURIE).
      * a bare ``prefix:localname`` token in running prose → ``surface``.

    Idempotent: a body already carrying only the surface term is unchanged.
    The hidden curie span is protected by temporarily masking it out before
    the substitution and restoring it after.
    """
    if not html or not curie or ":" not in curie:
        return html
    surface = surface or curie.split(":", 1)[1].replace("_", " ").replace("-", " ")
    local = curie.split(":", 1)[1]

    # Protect the hidden anchoring span(s) from the bare-token substitution.
    _shields: List[str] = []

    def _shield(m: "re.Match") -> str:
        _shields.append(m.group(0))
        return f"\x00CURIESPAN{len(_shields) - 1}\x00"

    masked = _CURIE_SPAN_EL_RE.sub(_shield, html)

    # 1. <code>/<kbd>/<samp> wrapping the bare CURIE -> plain surface term.
    for _tag in ("code", "kbd", "samp"):
        masked = re.sub(
            rf"<{_tag}\b[^>]*>\s*{re.escape(curie)}\s*</{_tag}>",
            surface,
            masked,
            flags=re.IGNORECASE,
        )
    # 2. data-cf-term="<full CURIE>" -> data-cf-term="<localname>".
    masked = re.sub(
        rf'(data-cf-term=)(["\']){re.escape(curie)}\2',
        rf'\1\2{local}\2',
        masked,
        flags=re.IGNORECASE,
    )
    # 3. bare token in prose -> surface term.
    masked = re.sub(re.escape(curie), surface, masked)

    # Restore the protected hidden span(s).
    for _i, _orig in enumerate(_shields):
        masked = masked.replace(f"\x00CURIESPAN{_i}\x00", _orig)
    return masked


def _objective_id_to_statement(objectives_doc: Any) -> Dict[str, str]:
    """Build an ``{id: statement}`` map from a synthesized-objectives doc.

    Accepts both the Courseforge synthesized form
    (``terminal_objectives[]`` flat + ``chapter_objectives[].objectives[]``
    nested) and the LibV2 archive form (``terminal_outcomes[]`` +
    ``component_objectives[]``). Defensive: any non-conforming shape yields an
    empty / partial map (callers fall back to rendering the bare id).
    """
    out: Dict[str, str] = {}
    if not isinstance(objectives_doc, dict):
        return out

    def _add(entry: Any) -> None:
        if not isinstance(entry, dict):
            return
        _id = entry.get("id")
        _stmt = entry.get("statement")
        if isinstance(_id, str) and _id and isinstance(_stmt, str) and _stmt:
            out.setdefault(_id, _stmt)

    for _key in ("terminal_objectives", "terminal_outcomes",
                 "component_objectives", "learning_outcomes"):
        for _e in objectives_doc.get(_key) or []:
            _add(_e)
    # Courseforge nested chapter form.
    for _chap in objectives_doc.get("chapter_objectives") or []:
        if isinstance(_chap, dict):
            _add(_chap)  # flat chapter row (rare)
            for _e in _chap.get("objectives") or []:
                _add(_e)
    return out


def _index_objective_records(
    objectives_doc: Any,
) -> Tuple[Dict[str, Dict[str, Any]], Dict[str, Dict[str, Any]]]:
    """Index a synthesized-objectives doc into ``(to_map, co_map)``.

    Each map is ``{id: full_objective_dict}``. ``to_map`` holds terminal
    objectives (``terminal_objectives`` / ``terminal_outcomes``); ``co_map``
    holds chapter objectives (``chapter_objectives[].objectives[]`` /
    ``component_objectives``). Used by findings 9 (TO statement → human page
    title) and 18 (overview enumerates the TO + its child COs). Defensive: any
    non-conforming shape yields empty / partial maps.
    """
    to_map: Dict[str, Dict[str, Any]] = {}
    co_map: Dict[str, Dict[str, Any]] = {}
    if not isinstance(objectives_doc, dict):
        return to_map, co_map

    def _put(target: Dict[str, Dict[str, Any]], entry: Any) -> None:
        if not isinstance(entry, dict):
            return
        _id = entry.get("id")
        if isinstance(_id, str) and _id:
            target.setdefault(_id, entry)

    for _key in ("terminal_objectives", "terminal_outcomes"):
        for _e in objectives_doc.get(_key) or []:
            _put(to_map, _e)
    for _e in objectives_doc.get("component_objectives") or []:
        _put(co_map, _e)
    for _chap in objectives_doc.get("chapter_objectives") or []:
        if isinstance(_chap, dict):
            for _e in _chap.get("objectives") or []:
                _put(co_map, _e)
    # Per-CO coverage: also harvest the flat
    # ``learning_outcomes[]`` universe so a CO/TO present only there (not in
    # the chapter/component arrays) still enters the objective maps — the W10
    # assessment tier iterates ``co_map`` as the CO universe and drops items
    # whose objective_id falls outside it (anti-fabrication filter), so a
    # learning_outcomes-only CO would otherwise silently lose coverage.
    # ``setdefault`` semantics via ``_put``: the richer chapter/component
    # records above always win; this pass only fills gaps. Classification
    # mirrors the archival validator's course.json fallback
    # (``lib/validators/libv2/packet_integrity.py::_load_objectives``):
    # hierarchy_level first, id-prefix fallback.
    for _e in objectives_doc.get("learning_outcomes") or []:
        if not isinstance(_e, dict):
            continue
        _lvl = str(_e.get("hierarchy_level") or "").lower()
        _lo_id = _e.get("id") if isinstance(_e.get("id"), str) else ""
        if _lvl == "terminal" or (_lo_id or "").upper().startswith("TO-"):
            _put(to_map, _e)
        elif _lvl in ("chapter", "component") or (
            (_lo_id or "").upper().startswith("CO-")
        ):
            _put(co_map, _e)
    return to_map, co_map


# ===========================================================================
# W10 — assessment-surface (QTI / discussion / assignment) emit helpers.
#
# Pure deterministic helpers consumed by the ``_run_assessment_synthesis``
# phase handler (``run_assessment_synthesis`` registry tool). Factored to
# module scope so they unit-test WITHOUT an LLM call, a pipeline run, or a
# course slug: given fixture ``AssessmentData`` + discussion/assignment
# dicts they write ``06_assessments/*.xml`` + a ``manifest.json`` matching
# the packager's pinned contract. Spec: ``plans/finegrain/
# w10-assessments-qti-discussions-2026-06.md`` §§3-4.
# ===========================================================================

# Matches a filesystem-safe basename token: alnum / underscore / hyphen / dot,
# no path separators (anti path-traversal for the manifest ``file`` field).
_ASSESSMENT_FILENAME_RE = re.compile(r"[^0-9A-Za-z._-]+")


def _safe_assessment_basename(stem: str, *, fallback: str) -> str:
    """Coerce an arbitrary title/id into a path-safe XML basename (no ext).

    Strips path separators + illegal chars to ``_`` so the manifest ``file``
    field can never contain ``..`` / ``/`` (the packager joins it under
    ``06_assessments/``). Returns ``<fallback>`` when nothing usable remains.
    """
    text = (stem or "").strip().lower().replace(" ", "_")
    text = _ASSESSMENT_FILENAME_RE.sub("_", text).strip("._-")
    return text or fallback


def _assessment_manifest_entry(
    *,
    basename: str,
    kind: str,
    title: str,
    week: Optional[int],
    identifier: str,
) -> Dict[str, Any]:
    """Build one ``06_assessments/manifest.json`` ``assessments[]`` entry.

    Emits the EXACT shape the already-landed packager consumes
    (``file`` / ``type`` / ``title`` / ``week`` / ``identifier``). ``file`` is
    the basename under ``06_assessments/`` (``<basename>.xml``); ``week`` is
    omitted when ``None`` (some assessments aren't week-scoped). ``type`` is
    one of ``qti`` / ``discussion`` / ``assignment``.
    """
    entry: Dict[str, Any] = {
        "file": f"{basename}.xml",
        "type": kind,
        "title": title or basename,
        "identifier": identifier or f"RES_{basename}",
    }
    if week is not None:
        entry["week"] = int(week)
    return entry


def _item_bank_enabled() -> bool:
    """Resolve the QTI item-BANK sidecar flag (parse-with-fallback).

    ``ED4ALL_ASSESSMENT_ITEM_BANK`` gates the additive
    ``06_assessments/item_bank.xml`` ``<objectbank>`` emit. Default off →
    byte-identical ``06_assessments`` (no extra file, no extra manifest key).
    """
    return (
        os.environ.get("ED4ALL_ASSESSMENT_ITEM_BANK", "") or ""
    ).strip().lower() in {"1", "true", "yes", "on"}


def _write_assessment_artifacts(
    out_dir: Path,
    artifacts: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Write each assessment XML + the ``manifest.json`` into ``out_dir``.

    PURE I/O — no LLM, no pipeline state. ``artifacts`` is a list of dicts,
    each carrying::

        {
            "xml": str,            # serialized XML document
            "basename": str,       # path-safe stem (no extension)
            "kind": str,           # qti | discussion | assignment
            "title": str,
            "week": Optional[int],
            "identifier": str,
        }

    Anti-collision: a duplicate basename gets a ``_NN`` suffix so two
    artifacts never clobber one file. Writes ``<basename>.xml`` for each,
    then a ``manifest.json`` with the pinned ``schema_version: "v1"`` +
    ``assessments[]`` shape. Returns the manifest dict actually written.
    """
    out_dir.mkdir(parents=True, exist_ok=True)
    manifest_entries: List[Dict[str, Any]] = []
    used: set = set()
    for art in artifacts:
        xml = str(art.get("xml") or "")
        if not xml.strip():
            continue
        base = _safe_assessment_basename(
            str(art.get("basename") or ""), fallback="assessment"
        )
        # De-collide.
        candidate = base
        n = 1
        while candidate in used:
            candidate = f"{base}_{n:02d}"
            n += 1
        used.add(candidate)

        (out_dir / f"{candidate}.xml").write_text(xml, encoding="utf-8")
        manifest_entries.append(
            _assessment_manifest_entry(
                basename=candidate,
                kind=str(art.get("kind") or "qti"),
                title=str(art.get("title") or candidate),
                week=art.get("week"),
                identifier=str(art.get("identifier") or f"RES_{candidate}"),
            )
        )

    manifest = {"schema_version": "v1", "assessments": manifest_entries}
    (out_dir / "manifest.json").write_text(
        json.dumps(manifest, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    return manifest


def _filter_questions_to_objective_universe(
    questions: List[Any],
    valid_objective_ids: set,
) -> Tuple[List[Any], List[Any]]:
    """Split questions into (kept, dropped) by objective-id grounding.

    Anti-fabrication contract (spec §3 / §6): an emitted assessment item's
    ``objective_id`` MUST come from the real synthesized-objectives universe.
    A question whose ``objective_id`` resolves to none of
    ``valid_objective_ids`` is DROPPED (never emitted) rather than shipping
    an item that points at a phantom objective. Accepts ``QuestionData``
    dataclasses (``.objective_id``) or plain dicts (``["objective_id"]``).
    """
    kept: List[Any] = []
    dropped: List[Any] = []
    for q in questions:
        oid = getattr(q, "objective_id", None)
        if oid is None and isinstance(q, dict):
            oid = q.get("objective_id")
        if isinstance(oid, str) and oid.strip() in valid_objective_ids:
            kept.append(q)
        else:
            dropped.append(q)
    return kept, dropped


_STEM_TAG_RE = re.compile(r"<[^>]+>")


def _normalize_stem_for_dedup(stem: Any) -> str:
    """Canonicalize a question stem for exact-duplicate comparison.

    HTML tags stripped, whitespace collapsed, lowercased. PURE — no I/O.
    An empty result means "no comparable stem" (never treated as a
    duplicate key).
    """
    text = _STEM_TAG_RE.sub(" ", str(stem or ""))
    return re.sub(r"\s+", " ", text).strip().lower()


def _dedup_assessment_stems(
    assessments: List[Any],
) -> Tuple[List[Any], Dict[str, Any]]:
    """Collapse exact-duplicate stems across the WHOLE emitted quiz set.

    Deterministic pre-emit guard: the W10 phase hands the same corpus-wide
    chunk pool to every per-TO quiz, so deterministic templates can mint the
    SAME stem in many quizzes (book-1 canary: 325/765 items in exact-duplicate
    groups). First occurrence (quiz-list order, i.e. week order) wins; every
    later exact duplicate is DROPPED — an honest count reduction beats salad
    duplication. A quiz whose questions all collapse is dropped entirely
    (never emit an empty QTI document).

    Accepts both ``AssessmentData``-shaped objects (``.questions`` of
    ``QuestionData``) and their cached ``to_dict()`` form (``["questions"]``
    of dicts). Returns ``(surviving_assessments, report)`` where ``report``
    carries ``total_before`` / ``total_after`` / ``duplicates_removed`` /
    ``duplicate_groups`` / ``dropped_assessments`` /
    ``objectives_losing_coverage`` (objective_ids whose ONLY item(s) were
    dropped as duplicates — reported, not silently papered over).
    """
    seen_stems: Dict[str, int] = {}
    kept_objectives: set = set()
    dropped_by_objective: Dict[str, int] = {}
    total_before = 0
    total_after = 0
    duplicates_removed = 0
    dropped_assessments: List[str] = []
    survivors: List[Any] = []

    def _questions_of(a: Any) -> List[Any]:
        qs = getattr(a, "questions", None)
        if qs is None and isinstance(a, dict):
            qs = a.get("questions")
        return list(qs or [])

    def _field(q: Any, name: str) -> Any:
        val = getattr(q, name, None)
        if val is None and isinstance(q, dict):
            val = q.get(name)
        return val

    for assessment in assessments:
        questions = _questions_of(assessment)
        kept: List[Any] = []
        for q in questions:
            total_before += 1
            key = _normalize_stem_for_dedup(_field(q, "stem"))
            oid = str(_field(q, "objective_id") or "").strip()
            if key and key in seen_stems:
                seen_stems[key] += 1
                duplicates_removed += 1
                if oid:
                    dropped_by_objective[oid] = (
                        dropped_by_objective.get(oid, 0) + 1
                    )
                continue
            if key:
                seen_stems[key] = 1
            kept.append(q)
            total_after += 1
            if oid:
                kept_objectives.add(oid)
        if not kept:
            ident = getattr(assessment, "assessment_id", None)
            if ident is None and isinstance(assessment, dict):
                ident = assessment.get("assessment_id")
            dropped_assessments.append(str(ident or "unknown"))
            continue
        if isinstance(assessment, dict):
            assessment["questions"] = kept
        else:
            assessment.questions = kept
        survivors.append(assessment)

    report = {
        "total_before": total_before,
        "total_after": total_after,
        "duplicates_removed": duplicates_removed,
        "duplicate_groups": sum(1 for n in seen_stems.values() if n > 1),
        "dropped_assessments": dropped_assessments,
        "objectives_losing_coverage": sorted(
            o for o in dropped_by_objective if o not in kept_objectives
        ),
    }
    return survivors, report


def _build_assessment_artifacts_from_data(
    assessments: List[Any],
    discussions: List[Dict[str, Any]],
    assignments: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Map AssessmentData + discussion/assignment dicts → emit-ready artifacts.

    PURE — imports the already-landed ``Courseforge.scripts.qti_emitter`` and
    serializes each input to its canonical CC resource XML. ``assessments``
    are ``AssessmentData`` instances (or their ``to_dict()`` form) → one QTI
    document each; ``discussions`` → ``imsdt`` topic docs; ``assignments`` →
    learning-application-resource docs. Each artifact dict is ready for
    :func:`_write_assessment_artifacts`. ``week`` is pulled from an optional
    ``week`` attr/key on the input (None when absent).

    No fabrication: the emitter only reshapes its input; an empty input list
    yields an empty artifact list (→ a clean empty ``06_assessments``).
    """
    from Courseforge.scripts.qti_emitter import (
        assessment_to_qti,
        discussion_to_imsdt,
        assignment_to_resource,
    )

    def _week_of(obj: Any) -> Optional[int]:
        w = getattr(obj, "week", None)
        if w is None and isinstance(obj, dict):
            w = obj.get("week")
        try:
            return int(w) if w is not None else None
        except (TypeError, ValueError):
            return None

    def _attr(obj: Any, name: str, default: str = "") -> str:
        val = getattr(obj, name, None)
        if val is None and isinstance(obj, dict):
            val = obj.get(name)
        return str(val) if val is not None else default

    artifacts: List[Dict[str, Any]] = []

    for a in assessments:
        ident = _attr(a, "assessment_id", "assessment")
        title = _attr(a, "title", ident) or ident
        week = _week_of(a)
        base = _safe_assessment_basename(
            f"week_{week:02d}_quiz" if week is not None else ident,
            fallback="quiz",
        )
        artifacts.append({
            "xml": assessment_to_qti(a),
            "basename": base,
            "kind": "qti",
            "title": title,
            "week": week,
            "identifier": f"RES_{base}",
        })

    for d in discussions:
        ident = str(d.get("discussion_id") or d.get("objective_id") or "discussion")
        title = str(d.get("title") or d.get("objective_id") or "Discussion")
        week = _week_of(d)
        base = _safe_assessment_basename(
            f"week_{week:02d}_discussion" if week is not None else ident,
            fallback="discussion",
        )
        artifacts.append({
            "xml": discussion_to_imsdt(d),
            "basename": base,
            "kind": "discussion",
            "title": title,
            "week": week,
            "identifier": f"RES_{base}",
        })

    for t in assignments:
        ident = str(t.get("assignment_id") or t.get("objective_id") or "assignment")
        title = str(t.get("title") or t.get("objective_id") or "Assignment")
        week = _week_of(t)
        base = _safe_assessment_basename(
            f"week_{week:02d}_assignment" if week is not None else ident,
            fallback="assignment",
        )
        artifacts.append({
            "xml": assignment_to_resource(t),
            "basename": base,
            "kind": "assignment",
            "title": title,
            "week": week,
            "identifier": f"RES_{base}",
        })

    return artifacts


# ---------------------------------------------------------------------------
# W10 per-CO coverage — QTI → assessment_item
# chunk harvest. The strict archival gate
# (``lib/validators/libv2/packet_integrity.py`` — OBJECTIVE_NO_ASSESSMENT /
# UNCOVERED_TERMINAL_OUTCOME) requires an ``assessment_item`` CHUNK whose
# ``learning_outcome_refs`` cover every TO/CO, but ``_run_imscc_chunking``
# historically chunked ONLY the ``.html`` payloads inside the packaged IMSCC —
# the QTI quiz XML the W10 ``assessment_synthesis`` phase emits under
# ``06_assessments/`` was never chunked, so per-CO quiz items produced zero
# per-CO coverage. These helpers close that gap: each QTI ``<item>`` (whose
# ``title`` attribute carries the item's objective_id, set by
# ``Courseforge/scripts/qti_emitter.py::question_to_qti_item``) becomes one
# ``assessment_item`` chunk routed through the SAME ``_create_chunk`` callback
# (→ ``Trainforge.chunker.extract_learning_outcome_refs`` arm 3 via
# ``item["objective_refs"]``) so ref normalization / case policy
# (``TRAINFORGE_PRESERVE_LO_CASE``) is byte-identical to the HTML path.
# Anti-fabrication: an item whose title does not normalize to a canonical LO
# id is SKIPPED (never emits an unanchored assessment chunk).
# ---------------------------------------------------------------------------

def _parse_qti_assessment_items(
    xml_text: str,
) -> Tuple[str, List[Dict[str, Any]]]:
    """Parse one QTI 1.2 document into ``(assessment_title, items)``.

    Namespace-agnostic (matches on local names). Each returned item dict
    carries ``ident`` / ``objective_ref`` (the ``<item title=...>`` attr) /
    ``stem_html`` (the presentation mattext OUTSIDE response labels) /
    ``choice_texts`` (response_label mattexts, document order). A non-QTI
    root (imsdt topic / assignment) or a parse error returns ``("", [])`` —
    the caller simply harvests nothing from that document.
    """
    import xml.etree.ElementTree as _ET

    def _local(tag: Any) -> str:
        return tag.rsplit("}", 1)[-1] if isinstance(tag, str) and "}" in tag else str(tag)

    try:
        root = _ET.fromstring(xml_text)
    except _ET.ParseError:
        return "", []
    if _local(root.tag) != "questestinterop":
        return "", []

    title = ""
    items: List[Dict[str, Any]] = []
    for el in root.iter():
        lt = _local(el.tag)
        if lt == "assessment" and not title:
            title = (el.get("title") or "").strip()
        elif lt == "item":
            stem_html = ""
            choice_texts: List[str] = []
            label_matt_ids: set = set()
            for lab in el.iter():
                if _local(lab.tag) != "response_label":
                    continue
                for m in lab.iter():
                    if _local(m.tag) == "mattext":
                        label_matt_ids.add(id(m))
                        if m.text and m.text.strip():
                            choice_texts.append(m.text.strip())
            for m in el.iter():
                if _local(m.tag) == "mattext" and id(m) not in label_matt_ids:
                    if m.text and m.text.strip():
                        stem_html = m.text.strip()
                        break
            items.append({
                "ident": (el.get("ident") or "").strip(),
                "objective_ref": (el.get("title") or "").strip(),
                "stem_html": stem_html,
                "choice_texts": choice_texts,
            })
    return title, items


def _harvest_qti_assessment_chunks(
    qti_entries: List[Dict[str, str]],
    *,
    create_chunk: Any,
    existing_chunks: List[Dict[str, Any]],
    course_code: str,
) -> List[Dict[str, Any]]:
    """Mint one ``assessment_item`` chunk per objective-anchored QTI item.

    ``qti_entries`` is ``[{"path": <zip inner path>, "content": <xml>}, ...]``
    (the ``06_assessments/*.xml`` payloads read out of the packaged IMSCC).
    ``create_chunk`` is ``_run_imscc_chunking``'s v4 chunk-emit callback, so
    every emitted chunk carries the full canonical shape (source block,
    concept tags, bloom heuristics, IRT stamps) and its
    ``learning_outcome_refs`` flow through the canonical
    ``extract_learning_outcome_refs`` normalization (arm 3,
    ``item["objective_refs"]``). Chunk ids CONTINUE the numeric sequence of
    ``existing_chunks`` via the canonical ``_generate_chunk_id`` (so
    ``TRAINFORGE_CONTENT_HASH_IDS`` is honored and the chunk_v4 id pattern
    holds). Items whose ``title`` does not normalize to a canonical LO id
    are skipped — never an unanchored assessment chunk. Pure w.r.t. the
    pipeline; any per-item failure skips that item only.
    """
    from Trainforge.chunker import (
        extract_learning_outcome_refs as _harvest_lo_refs,
        extract_plain_text as _harvest_plain_text,
    )
    try:
        from Trainforge.chunker.chunker import (
            _generate_chunk_id as _mint_chunk_id,
        )
    except Exception:  # noqa: BLE001 — canonical helper unavailable
        def _mint_chunk_id(prefix, start_id, text, source_locator):  # type: ignore
            return f"{prefix}{start_id:05d}"

    prefix = f"{str(course_code).lower()}_chunk_"
    # Continue after the highest positional suffix already minted so the
    # unique_chunk_ids archival rule can never collide.
    next_idx = 1
    _suffix_re = re.compile(r"_chunk_(\d{5})$")
    for _c in existing_chunks:
        _m = _suffix_re.search(str(_c.get("id") or ""))
        if _m:
            next_idx = max(next_idx, int(_m.group(1)) + 1)

    out: List[Dict[str, Any]] = []
    for entry in sorted(qti_entries, key=lambda e: e.get("path") or ""):
        inner_path = str(entry.get("path") or "")
        quiz_title, items = _parse_qti_assessment_items(
            str(entry.get("content") or "")
        )
        if not items:
            continue
        doc_stem = Path(inner_path).stem.lower().replace(" ", "-")
        skipped_unanchored = 0
        for pos, qti_item in enumerate(items):
            obj_ref = qti_item.get("objective_ref") or ""
            probe_item = {"objective_refs": [obj_ref]}
            if not _harvest_lo_refs(probe_item, None):
                skipped_unanchored += 1
                continue
            stem_html = qti_item.get("stem_html") or ""
            text_parts: List[str] = []
            stem_text = _harvest_plain_text(stem_html).strip() if stem_html else ""
            if stem_text:
                text_parts.append(stem_text)
            for choice in qti_item.get("choice_texts") or []:
                choice_text = _harvest_plain_text(choice).strip()
                if choice_text:
                    text_parts.append(choice_text)
            text = "\n".join(text_parts).strip()
            if not text:
                skipped_unanchored += 1
                continue
            item_dict: Dict[str, Any] = {
                "item_id": doc_stem,
                "item_path": inner_path,
                "title": quiz_title or doc_stem,
                "resource_type": "quiz",
                "module_id": doc_stem,
                "module_title": quiz_title or doc_stem,
                "week_num": 0,
                "sections": [],
                "learning_objectives": [],
                "key_concepts": [],
                "objective_refs": [obj_ref],
                "misconceptions": [],
            }
            try:
                chunk = create_chunk(
                    chunk_id=_mint_chunk_id(
                        prefix, next_idx, text,
                        f"{inner_path}#{qti_item.get('ident') or pos}",
                    ),
                    text=text,
                    html=stem_html,
                    item=item_dict,
                    section_heading=quiz_title or doc_stem,
                    chunk_type="assessment_item",
                    position_in_module=pos,
                )
            except Exception as exc:  # noqa: BLE001 — per-item fail-soft
                logger.warning(
                    "qti-assessment-chunk harvest: create_chunk failed for "
                    "%s item %r (%s); skipping item.",
                    inner_path, qti_item.get("ident"), exc,
                )
                continue
            if isinstance(chunk, dict):
                # D1: the harvested end-of-section assessment_item chunks are
                # VERBATIM source-textbook exercises, so they are DEMOTED to an
                # internal practice bank. They stay in the chunkset so
                # archival coverage stands, but are tagged so the graded-QTI /
                # SFT-source / answer paths exclude them by default (the
                # assessment_sft_generator's grounding filter refuses to source
                # any chunk carrying this marker).
                chunk["practice_bank"] = True
                out.append(chunk)
                next_idx += 1
        if skipped_unanchored:
            logger.info(
                "qti-assessment-chunk harvest: skipped %d unanchored/empty "
                "item(s) in %s (no canonical LO ref on <item title>).",
                skipped_unanchored, inner_path,
            )
    return out


def _synthesize_prose_prompt(
    provider: Any,
    *,
    kind: str,
    objective_id: str,
    statement: str,
    chunks: List[Dict[str, Any]],
    grounded_chunk_ids: List[str],
    max_chars: int = 1200,
) -> str:
    """Author one assignment/discussion prose task via the assessment seat.

    Routes a SINGLE bounded prompt through the supplied provider's
    ``_dispatch_call`` (the same OpenAI-compatible / Anthropic plumbing the
    Trainforge assessment generator uses), grounded ONLY in the supplied
    chunks (anti-fabrication: the prompt enumerates real grounded chunk
    text; the model writes a learner-facing prompt, not new source facts).

    Returns the cleaned prose string, or ``""`` on any dispatch / empty
    response so the caller can fall back to a deterministic prompt. Pure
    w.r.t. the pipeline — the only side effect is the provider's own
    per-call decision capture.
    """
    kind_label = "discussion prompt" if kind == "discussion" else "short assignment task"
    # Build a small grounded-context block from the chunks the objective
    # cites (cap each body so a 7B window stays comfortable).
    grounded_set = {str(c) for c in grounded_chunk_ids}
    ctx_lines: List[str] = []
    for c in chunks:
        cid = str(c.get("id") or c.get("chunk_id") or "")
        if grounded_set and cid not in grounded_set:
            continue
        text = str(c.get("text") or "").strip()
        if not text:
            continue
        if len(text) > 600:
            text = text[:597] + "..."
        ctx_lines.append(f"  - [{cid}] {text}")
        if len(ctx_lines) >= 3:
            break
    ctx_block = "\n".join(ctx_lines) if ctx_lines else "  (no grounded chunks)"

    user_prompt = (
        f"Author ONE {kind_label} for learners, grounded in the source "
        f"material below. Target this learning objective:\n"
        f"  [{objective_id}] {statement}\n\n"
        f"Source material (ground the prompt in THIS content; do not "
        f"invent facts):\n{ctx_block}\n\n"
        f"Respond with ONLY the {kind_label} prose (no preamble, no JSON, "
        f"no markdown fences). Keep it under 120 words."
    )

    try:
        text, _retry = provider._dispatch_call(user_prompt)
    except Exception:
        return ""
    text = (text or "").strip()
    if not text:
        return ""
    # Strip accidental markdown fences.
    if text.startswith("```"):
        import re as _re
        m = _re.search(r"```(?:\w+)?\s*\n?(.*?)```", text, _re.DOTALL)
        if m:
            text = m.group(1).strip()
    return text[:max_chars]


# Matches an objectives ``<li ... data-cf-objective-id="ID">BODY</li>`` whose
# visible BODY needs resolving to the objective statement. Group 1 = the full
# attribute block before the body; group 2 = the resolved id; group 3 = body.
_OBJECTIVE_LI_RE = re.compile(
    r'(<li\b[^>]*\bdata-cf-objective-id=["\']([A-Za-z]{2,}-\d{2,})["\'][^>]*>)'
    r'(.*?)(</li>)',
    re.IGNORECASE | re.DOTALL,
)


def _resolve_objective_li_statements(
    html: str, id_to_statement: Dict[str, str]
) -> str:
    """Rewrite objective ``<li>`` bodies from a bare id to the LO statement.

    For each ``<li data-cf-objective-id="CO-NN">CO-NN</li>`` whose body is the
    bare id (or empty), replace the body with
    ``<strong>CO-NN:</strong> {statement}`` (mirroring
    ``generate_course.py::_render_objectives``). The id stays in the
    ``data-cf-objective-id`` attribute. A body already carrying real prose
    (longer than the id, not just the id) is left untouched.
    """
    if not html or not id_to_statement:
        return html
    import html as _html_mod

    def _repl(m: "re.Match") -> str:
        open_tag, oid, body, close_tag = (
            m.group(1), m.group(2), m.group(3), m.group(4),
        )
        statement = id_to_statement.get(oid) or id_to_statement.get(oid.upper())
        if not statement:
            return m.group(0)
        body_stripped = re.sub(r"<[^>]+>", "", body).strip()
        # Only rewrite when the body is empty or just the bare id (any case).
        if body_stripped and body_stripped.lower() not in (
            oid.lower(), f"{oid.lower()}:",
        ):
            return m.group(0)
        return (
            f"{open_tag}<strong>{oid}:</strong> "
            f"{_html_mod.escape(statement)}{close_tag}"
        )

    return _OBJECTIVE_LI_RE.sub(_repl, html)


# ---------------------------------------------------------------------------
# P0 — VISIBLE provenance-id leak sanitizer (identifier leakage into prose).
# ---------------------------------------------------------------------------
#
# The 7B course leaks raw provenance ids into VISIBLE learner text in three
# classes. These helpers strip them from visible prose ONLY — never from a
# ``data-cf-*`` attribute value (where the ids legitimately live as the
# anchoring / provenance signal) nor from a hidden ``data-cf-curie`` span. The
# attribute-safety guarantee for each is documented at its regex.
#
# CLASS 1 — a ``<cite class="source-attribution">`` whose body is just raw
# ``dart:<source>#<hash>`` ids (and ``;``-joined runs of them). Strip the whole
# element. The emit sites no longer author this cite; the sanitizer cleans an
# EXISTING export. Attribute-safe: a ``<cite ...>`` element never appears inside
# an attribute VALUE.
_LEAKED_SOURCE_ATTR_CITE_RE = re.compile(
    r'<cite\s+class=(["\'])source-attribution\1[^>]*>.*?</cite>',
    re.IGNORECASE | re.DOTALL,
)

# CLASS 1 (bare) — a raw ``dart:<source>#<hash>`` id sitting in VISIBLE prose
# (not wrapped in the source-attribution cite, and not inside an attribute).
# Shape mirrors the canonical ``dart:{slug}#{block_id}`` emit contract (slug =
# lowercase + digits + hyphen; block_id = lowercase/digit/underscore/hyphen).
# A ``;``/``,`` + whitespace separated RUN of such ids is consumed together so
# the whole leaked list collapses (not just the head). Attribute-safe: the
# ``data-cf-source-ids="dart:...#..."`` attribute is protected by the
# attribute-mask in :func:`_strip_visible_provenance_ids` before this runs.
_LEAKED_DART_ID_RUN_RE = re.compile(
    r'dart:[a-z0-9][a-z0-9_-]*#[0-9a-f]+'
    r'(?:\s*[;,]\s*dart:[a-z0-9][a-z0-9_-]*#[0-9a-f]+)*'
)

# CLASS 2 — a model-authored chunk-id ``<cite>...<course>_chunk_<NN></cite>``
# plus the "According to the source[ chunk][,] " lead-in phrasing the 7B writes
# before it. Two regexes:
#   (a) the lead-in + cite together: ``According to the source, <cite>X</cite>,``
#       / ``According to the source chunk <cite>X</cite>,`` / ``According to
#       <cite>X</cite>,`` — stripped whole, with the trailing comma+space so the
#       remaining sentence reads naturally (the following word is re-capitalized
#       only if it began lowercase mid-strip — left as-is, low risk).
#   (b) a bare ``<cite>...chunk_NN...</cite>`` not preceded by the lead-in —
#       drop the cite element (and one leading space) but keep surrounding prose.
# A ``<cite>`` element never appears inside an attribute value, so both are
# attribute-safe.
_LEAKED_ACCORDING_CHUNK_CITE_RE = re.compile(
    r'According to (?:the source(?:\s+chunk)?[, ]?\s*)?'
    r'<cite>\s*[a-z0-9_]*_chunk_\d+\s*</cite>\s*,?\s*',
    re.IGNORECASE,
)
_LEAKED_BARE_CHUNK_CITE_RE = re.compile(
    r' ?<cite>\s*[a-z0-9_]*_chunk_\d+\s*</cite>',
    re.IGNORECASE,
)

# CLASS 3 — an inline parenthetical objective ref ``(CO-NN)`` / ``(TO-NN)`` in
# body prose, including the U+2011 non-breaking-hyphen variant and stray inner
# whitespace. The objective ``<li>`` rendering "CO-NN: <statement>" is INTENDED
# and is NOT a parenthetical, so it is never matched. A single leading space is
# consumed so mid-sentence stripping leaves no double space. Attribute-safe: the
# parenthesized ``(CO-NN)`` form never appears inside an attribute value.
_LEAKED_OBJECTIVE_PARENTHETICAL_RE = re.compile(
    r' ?\(\s*(?:CO|TO)\s*[-‑]\s*\d+\s*\)'
)

# Any ``data-cf-*="..."`` (or single-quoted) attribute — masked out before the
# visible-prose substitutions run so provenance ids living in
# ``data-cf-source-ids`` / ``data-cf-term`` / etc. are NEVER touched. Also masks
# a hidden ``<span ... data-cf-curie=...>...</span>`` whole element (its body is
# the literal anchoring token and must survive).
_DATA_CF_ATTR_RE = re.compile(r'data-cf-[a-z-]+=(["\']).*?\1', re.IGNORECASE)


def _strip_visible_provenance_ids(html: str) -> str:
    """Strip CLASS 1/2/3 provenance-id leaks from VISIBLE prose only.

    Masks every ``data-cf-*`` attribute value and the hidden
    ``<span data-cf-curie>`` element out FIRST, runs the visible-prose strips,
    then restores the masked regions verbatim — so a provenance id that lives in
    an attribute (the legitimate home) or in the hidden anchoring span is never
    altered. Idempotent: a clean page is byte-identical out; a second pass finds
    nothing left to strip.
    """
    if not isinstance(html, str) or not html:
        return html

    shields: List[str] = []

    def _shield(m: "re.Match") -> str:
        shields.append(m.group(0))
        return f"\x00CFMASK{len(shields) - 1}\x00"

    # Mask hidden curie spans (whole element) then every data-cf-* attribute.
    masked = _CURIE_SPAN_EL_RE.sub(_shield, html)
    masked = _DATA_CF_ATTR_RE.sub(_shield, masked)

    # CLASS 1: drop the visible source-attribution cite, then any bare dart-id
    # runs that survived outside a cite.
    masked = _LEAKED_SOURCE_ATTR_CITE_RE.sub("", masked)
    masked = _LEAKED_DART_ID_RUN_RE.sub("", masked)
    # CLASS 2: drop the "According to the source <cite>chunk</cite>," lead-in,
    # then any bare leftover chunk-id cite.
    masked = _LEAKED_ACCORDING_CHUNK_CITE_RE.sub("", masked)
    masked = _LEAKED_BARE_CHUNK_CITE_RE.sub("", masked)
    # CLASS 3: drop inline (CO-NN)/(TO-NN) parentheticals from body prose.
    masked = _LEAKED_OBJECTIVE_PARENTHETICAL_RE.sub("", masked)

    # Restore masked regions verbatim.
    for _i, _orig in enumerate(shields):
        masked = masked.replace(f"\x00CFMASK{_i}\x00", _orig)
    return masked


# ---------------------------------------------------------------------------
# P2 — block_type -> teaching-role resolution (7B→Sonnet parity, Wave 1).
# ---------------------------------------------------------------------------
#
# The single-pass ``generate_course.py`` stamps ``data-cf-teaching-role`` on
# every component wrapper via the canonical ``(component, purpose) -> role``
# mapper (``lib/ontology/teaching_roles.map_role``). The two-pass rewrite tier
# emits a bare ``<section>`` carrying no teaching-role, so chunk extraction
# downstream sees a null role. This table maps each prose / component
# block_type to the ``(component, purpose)`` pair the
# ``schemas/taxonomies/teaching_role.json`` x-component-mapping resolves — so
# the rewrite tier inherits the SAME deterministic role lookup. Block types
# absent from the table get no teaching-role attribute (the mapper would return
# None anyway). Resolved through ``map_role`` (never hardcoded) so a schema
# drift surfaces at load time.
_BLOCK_TYPE_TEACHING_ROLE_KEY: Dict[str, Tuple[str, str]] = {
    "concept": ("concept", "introduce-concept"),
    "definition": ("definition", "introduce-concept"),
    "explanation": ("explanation", "elaborate-concept"),
    "example": ("example", "demonstrate"),
    "summary_takeaway": ("summary", "consolidate"),
    "recap": ("recap", "review"),
    "flip_card_grid": ("flip-card", "term-definition"),
    "self_check_question": ("self-check", "formative-assessment"),
    "activity": ("activity", "practice"),
}


def _teaching_role_for_block_type(block_type: str) -> str:
    """Return the canonical teaching-role for ``block_type`` (or "").

    Resolves the block_type to a ``(component, purpose)`` pair and routes it
    through the single-source-of-truth ``lib.ontology.teaching_roles.map_role``
    mapper. Returns "" when the block_type has no mapping (the section wrapper
    then carries no ``data-cf-teaching-role`` — mirrors the mapper's None
    fallback contract).
    """
    key = _BLOCK_TYPE_TEACHING_ROLE_KEY.get(block_type)
    if not key:
        return ""
    try:
        from lib.ontology.teaching_roles import map_role as _map_role
        return _map_role(key[0], key[1]) or ""
    except Exception:  # noqa: BLE001 — schema unavailable -> no attribute
        return ""


# ---------------------------------------------------------------------------
# Deterministic styled-template fallback (7B/NVIDIA runaway-block recovery).
# ---------------------------------------------------------------------------
#
# On a full course run the rewrite-tier model (Nemotron / 7B) rambles / repeats
# on ~20-30% of blocks, exhausting the ``max_tokens`` budget so the block
# truncates and ships as degraded / broken HTML — losing the P2 styled
# component classes and breaking the page. When a block exhausts its
# parse-retry budget (``escalation_marker`` set, no usable str content), we DO
# NOT keep the degraded output. Instead we render a deterministic, LLM-free,
# styled HTML block from the OUTLINE block's ``content.key_claims`` (a list of
# concise ``{claim, source_chunk_ids}`` dicts) using the SAME styled component
# classes + ``data-cf-*`` metadata the successful rewrite path emits. Every
# block is therefore styled, concise, complete, and grounded — even when the
# model misbehaves.
#
# The key_claims are ALREADY concise (one claim ≈ one sentence-or-two) — the
# renderer NEVER pads or expands: one claim → one styled element.

# A definition claim opens with a defined-term phrasing the source authored.
_DEFINITION_CLAIM_RE = re.compile(
    r"\b(is defined as|is the|are the|refers to|means that|is a |are a |"
    r"is called|are called|definition[:]?)\b",
    re.IGNORECASE,
)
# A rule / law / property claim states an invariant the learner must apply.
_RULE_CLAIM_RE = re.compile(
    r"\b(rule|law|property|theorem|principle|must|always|never|"
    r"if and only if|equals|is equal to|the formula)\b",
    re.IGNORECASE,
)


def _fallback_claim_texts(block: Any) -> List[str]:
    """Extract the outline block's concise ``key_claims`` claim strings.

    Reads ``block.content["key_claims"]`` (the W2 outline form — a list of
    ``{claim, source_chunk_ids}`` dicts). Tolerant of a bare ``[str]`` list or
    a string ``content`` (rare degraded outline shape). Returns the
    already-concise claim strings in order; an empty list when nothing is
    extractable (caller emits a minimal grounded ``<p>`` instead of crashing).
    """
    content = getattr(block, "content", None)
    claims: List[str] = []
    if isinstance(content, dict):
        raw = content.get("key_claims") or content.get("claims") or []
        if isinstance(raw, list):
            for entry in raw:
                if isinstance(entry, dict):
                    txt = entry.get("claim") or entry.get("text")
                    if isinstance(txt, str) and txt.strip():
                        claims.append(txt.strip())
                elif isinstance(entry, str) and entry.strip():
                    claims.append(entry.strip())
        # Fall back to a prose ``body`` / ``text`` field split on sentences.
        if not claims:
            for key in ("body", "text", "prose"):
                val = content.get(key)
                if isinstance(val, str) and val.strip():
                    claims = [
                        s.strip()
                        for s in re.split(r"(?<=[.!?])\s+", val.strip())
                        if s.strip()
                    ]
                    break
    elif isinstance(content, str) and content.strip():
        # A degraded str outline body — split into sentences as last resort.
        claims = [
            s.strip()
            for s in re.split(r"(?<=[.!?])\s+", content.strip())
            if s.strip()
        ]
    return claims


# rewrite-overflow-fix-2026-06: the same ``<li data-cf-distractor-index="N">``
# sibling pattern the CRITICAL ``rewrite_assessment_item_payload`` gate scans
# (``lib/validators/assessment_item_payload.py::_DATA_CF_DISTRACTOR_INDEX_LI_RE``).
# Used to detect a PARSED-but-structurally-empty assessment_item MCQ (a real
# 7B item that omitted the canonical option markup) so it routes to the
# deterministic MCQ-completion fallback BEFORE the gate can BLOCK the run.
_ASSESSMENT_ITEM_DISTRACTOR_LI_RE = re.compile(
    r'<li[^>]*data-cf-distractor-index=["\'](\d+)["\'][^>]*>',
    re.IGNORECASE,
)


def _assessment_item_payload_structurally_empty(content: str) -> bool:
    """Return True when an assessment_item HTML body would FAIL the gate.

    Mirrors the CRITICAL ``rewrite_assessment_item_payload`` floor: a valid
    item carries >= 2 ``<li data-cf-distractor-index="N">`` siblings. Fewer
    than 2 means the rewrite tier authored an item missing the canonical
    MCQ option markup (a `<strong>` marker or bare "Correct answer: …" line
    the validator can't parse) — which would BLOCK the whole run. Such an
    item is routed to the deterministic MCQ-completion fallback instead.
    """
    if not content or not content.strip():
        return False  # empty content is handled by the escalation path.
    return len(_ASSESSMENT_ITEM_DISTRACTOR_LI_RE.findall(content)) < 2


# W6.6 — default confidence-capture prompt stamped on a content-tier
# ``assessment_item`` (B14) block when ``ED4ALL_REFLECTION_CALIBRATION`` is on.
# A graded item has a KNOWN correct answer, so capturing the learner's stated
# confidence lets ``generate_course._render_confidence_capture`` append the
# calibration-comparison reveal (confidence vs correctness). Deterministic
# generic text (no per-item content) so it never fabricates.
_ASSESSMENT_CONFIDENCE_PROMPT = "How confident are you in your answer?"


def _assessment_confidence_capture_html(block: Any) -> str:
    """Return the confidence-capture HTML for an ``assessment_item`` block, else "".

    W6.6 (flag ``ED4ALL_REFLECTION_CALIBRATION``, reused). When the flag is off
    (default) returns ``""`` so the assessment_item emit is BYTE-IDENTICAL. When
    on, stamps a default ``confidence_prompt`` on the block (only when it carries
    none — a hash-excluded Optional field) and delegates to
    ``generate_course._render_confidence_capture``, which renders the
    "how sure are you?" scale PLUS the graded-B14 calibration-comparison reveal.
    No-op for every non-``assessment_item`` block type. Fail-soft: any
    import/render error yields ``""`` (additive; never breaks the page render).
    """
    if getattr(block, "block_type", "") != "assessment_item":
        return ""
    try:
        from lib.generation.reflection_calibration import (  # noqa: PLC0415
            resolve_reflection_calibration,
        )

        if not resolve_reflection_calibration():
            return ""
        import dataclasses as _dc_conf  # noqa: PLC0415
        from Courseforge.scripts.generate_course import (  # noqa: PLC0415
            _render_confidence_capture,
        )

        existing = getattr(block, "confidence_prompt", None)
        blk = block
        if not (isinstance(existing, str) and existing.strip()):
            blk = _dc_conf.replace(
                block, confidence_prompt=_ASSESSMENT_CONFIDENCE_PROMPT
            )
        return _render_confidence_capture(blk)
    except Exception:  # noqa: BLE001 — additive; never break render
        return ""


def _render_block_fallback_html(
    block: Any,
    *,
    objective_statements: Optional[Dict[str, str]] = None,
    minted_curie_map: Optional[Dict[str, Any]] = None,
    source_ids: Optional[List[str]] = None,
) -> str:
    """Render a deterministic, styled, grounded HTML body for one Block.

    LLM-free. Maps ``block.block_type`` to the SAME styled component classes
    the successful rewrite path emits (mirrors the P2 contracts in
    ``Courseforge/generators/_rewrite_provider.py::_BLOCK_TYPE_OUTPUT_CONTRACTS``
    and the CSS in ``Courseforge/scripts/generate_course.py::COURSEFORGE_CSS``).
    Wraps everything in a ``<section>`` carrying the same ``data-cf-*``
    attributes (content-type via the rewrite content-type table, teaching-role
    via ``lib.ontology.teaching_roles``, bloom-level, source-ids) plus a
    ``data-cf-fallback="template"`` marker so fallback-rendered blocks are
    auditable. The P0 visible-token sanitizer runs over the result so no
    minted CURIE / bare ``TO-NN`` id leaks into visible prose. SHORT by
    construction — one concise key_claim → one styled element; never padded.
    """
    import html as _h

    objective_statements = objective_statements or {}
    block_type = getattr(block, "block_type", "") or ""
    claims = _fallback_claim_texts(block)

    def esc(s: str) -> str:
        return _h.escape(s)

    body_parts: List[str] = []

    if block_type == "objective":
        # Resolve the objective STATEMENTS (never the bare TO-NN / CO-NN).
        oids = list(getattr(block, "objective_ids", ()) or ())
        lis: List[str] = []
        for oid in oids:
            stmt = objective_statements.get(oid) or \
                objective_statements.get(oid.upper())
            if stmt:
                lis.append(
                    f'<li data-cf-objective-id="{esc(oid)}">'
                    f"<strong>{esc(oid)}:</strong> {esc(stmt)}</li>"
                )
            else:
                lis.append(
                    f'<li data-cf-objective-id="{esc(oid)}">{esc(oid)}</li>'
                )
        if not lis:
            # No objective_ids — render the key_claims as objective text.
            for claim in claims:
                lis.append(f"<li>{esc(claim)}</li>")
        body_parts.append(f"<ul>{''.join(lis)}</ul>")

    elif block_type in ("explanation", "concept"):
        for claim in claims:
            if _DEFINITION_CLAIM_RE.search(claim):
                body_parts.append(
                    f'<div class="definition-box">{esc(claim)}</div>'
                )
            elif _RULE_CLAIM_RE.search(claim):
                body_parts.append(
                    f'<div class="key-rule">{esc(claim)}</div>'
                )
            else:
                body_parts.append(f"<p>{esc(claim)}</p>")

    elif block_type == "example":
        steps: List[str] = []
        # All but the last claim are steps; the last is the solution line.
        step_claims = claims[:-1] if len(claims) > 1 else claims
        for idx, claim in enumerate(step_claims, start=1):
            steps.append(
                f'<div class="step-row">'
                f'<span class="step-label">Step {idx}</span> '
                f"{esc(claim)}</div>"
            )
        solution = ""
        if len(claims) > 1:
            solution = (
                f'<div class="solution-line">{esc(claims[-1])}</div>'
            )
        body_parts.append(
            '<div class="example-box"><div class="worked-example">'
            f"{''.join(steps)}{solution}</div></div>"
        )

    elif block_type == "self_check_question":
        # The first claim is the question; any remainder goes behind a reveal.
        question = claims[0] if claims else "Check your understanding."
        answer = " ".join(claims[1:]) if len(claims) > 1 else ""
        reveal = ""
        if answer:
            reveal = (
                "<details><summary>Show answer</summary>"
                f"<p>{esc(answer)}</p></details>"
            )
        body_parts.append(
            '<div class="self-check self-check-item" '
            'data-cf-component="self-check" '
            'data-cf-purpose="formative-assessment">'
            f"<p>{esc(question)}</p>{reveal}</div>"
        )

    elif block_type == "activity":
        items = "".join(f"<li>{esc(c)}</li>" for c in claims)
        instruction = claims[0] if claims else "Complete the following practice."
        practice = "".join(f"<li>{esc(c)}</li>" for c in claims[1:]) or items
        body_parts.append(
            '<div class="activity-card" data-cf-component="activity" '
            'data-cf-purpose="practice">'
            f"<p>{esc(instruction)}</p><ol>{practice}</ol></div>"
        )

    elif block_type == "table":
        # Issue I6: deterministic, WCAG-correct table — <caption> + a
        # scoped <th scope="col"> header + one <tr> per claim. Each claim
        # becomes a single-column row (the fallback has no column structure
        # to mine, so a one-column accessible table is the honest shape).
        caption = claims[0] if claims else "Comparison"
        rows = claims[1:] if len(claims) > 1 else claims
        row_html = "".join(f"<tr><td>{esc(c)}</td></tr>" for c in rows)
        body_parts.append(
            "<table>"
            f"<caption>{esc(caption)}</caption>"
            '<thead><tr><th scope="col">Detail</th></tr></thead>'
            f"<tbody>{row_html}</tbody></table>"
        )

    elif block_type == "acronym":
        # Issue I6: deterministic <dl> with matched <dt>/<dd> pairs. The
        # first claim is the mnemonic; each remaining claim is a letter→term
        # mapping (split on the first ':' / '-' / '=' when present, else the
        # claim's leading letter maps to the whole claim).
        mnemonic = claims[0] if claims else "Acronym"
        pairs = claims[1:] if len(claims) > 1 else claims
        dl_items: List[str] = []
        for c in pairs:
            letter, term = c, c
            for sep in (":", "—", "-", "="):
                if sep in c:
                    head, _, tail = c.partition(sep)
                    letter = head.strip() or (c[:1])
                    term = tail.strip() or c
                    break
            else:
                letter = c[:1]
                term = c
            dl_items.append(f"<dt>{esc(letter)}</dt><dd>{esc(term)}</dd>")
        body_parts.append(
            '<div class="acronym-card">'
            f"<p><strong>{esc(mnemonic)}</strong></p>"
            f'<dl class="acronym-list">{"".join(dl_items)}</dl></div>'
        )

    elif block_type == "key_idea":
        # Issue I6: deterministic <aside> with a "Key Idea" framing label.
        principle = claims[0] if claims else "Key Idea."
        extra = "".join(f"<p>{esc(c)}</p>" for c in claims[1:])
        body_parts.append(
            '<aside class="key-idea">'
            f"<p><strong>Key Idea:</strong> {esc(principle)}</p>{extra}</aside>"
        )

    elif block_type == "assessment_item":
        # GAP D triangle floor (+ any escalated assessment_item): the rewrite
        # tier exhausted its retry budget, so emit a deterministic, gate-VALID
        # MCQ payload rather than the generic <p> else-branch (which carries zero
        # <li data-cf-distractor-index> markup and FAILS the CRITICAL
        # rewrite_assessment_item_payload gate → blocks the whole run).
        #
        # Contract enforced by
        # ``lib/validators/assessment_item_payload.py::_audit_rewrite_block``
        # (rewrite/str mode): >= 2 ``<li data-cf-distractor-index="N">`` siblings
        # with NON-EMPTY body text and indices CONTIGUOUS from 0. We additionally
        # mark exactly one option ``data-cf-correct="true"`` (the answer marker
        # the success-path emit uses) so the payload is well-formed for the
        # broader distractor validators too. Grounded/minimal: the question stem
        # is the first key_claim; option bodies reuse the remaining claims
        # (padded only to reach the 2-option floor), never invented content.
        stem = claims[0] if claims else "Which statement is best supported by this material?"
        # Option bodies: prefer the block's remaining grounded claims; the
        # correct option leads, distractors follow. Pad to >= 3 options (1
        # correct + 2 distractors) only when the block supplied too few claims —
        # the padding is an honest "needs review" placeholder, never a fabricated
        # plausible-looking wrong answer.
        correct_body = claims[1] if len(claims) > 1 else stem
        distractor_bodies = [c for c in claims[2:] if c]
        while len(distractor_bodies) < 2:
            distractor_bodies.append(
                f"Not supported by the source (option {len(distractor_bodies) + 1})."
            )
        option_bodies = [(correct_body, True)] + [
            (b, False) for b in distractor_bodies
        ]
        li_html = "".join(
            f'<li data-cf-distractor-index="{idx}"'
            + (' data-cf-correct="true"' if is_correct else "")
            + f">{esc(body)}</li>"
            for idx, (body, is_correct) in enumerate(option_bodies)
        )
        body_parts.append(
            '<div class="assessment-item">'
            f"<p>{esc(stem)}</p>"
            f"<ol>{li_html}</ol></div>"
        )
        # W6.6 — graded-B14 confidence capture + calibration-comparison reveal
        # (ED4ALL_REFLECTION_CALIBRATION, reused). "" when the flag is off →
        # byte-identical (mirrors the misconception productive-failure scaffold).
        _conf_html = _assessment_confidence_capture_html(block)
        if _conf_html:
            body_parts.append(_conf_html)

    elif block_type == "misconception":
        # Deterministic misconception-card render (the rewrite tier is the
        # primary author; this is the exhausted-budget / LLM-free fallback).
        # ``content`` is the ``{misconception, correction}`` dict, NOT a
        # ``key_claims`` list, so read it directly (``_fallback_claim_texts``
        # returns [] for this shape). When ``ED4ALL_MISCONCEPTION_RICH`` is on
        # AND the planner stamped the mc_* fields, append the predict-then-
        # reconcile productive-failure scaffold (mirrors how the recall body
        # render hooks into the deterministic self-check render). Off / no
        # fields → the scaffold returns "" and the card is byte-stable.
        _mc_content = getattr(block, "content", None)
        _mis_text = ""
        _cor_text = ""
        if isinstance(_mc_content, dict):
            _mis_text = str(_mc_content.get("misconception") or "").strip()
            _cor_text = str(_mc_content.get("correction") or "").strip()
        if not _mis_text and claims:
            _mis_text = claims[0]
        card_parts: List[str] = ['<div class="misconception-card">']
        if _mis_text:
            card_parts.append(
                f'<p class="misconception-claim">{esc(_mis_text)}</p>'
            )
        if _cor_text:
            card_parts.append(
                f'<p class="misconception-correction">{esc(_cor_text)}</p>'
            )
        if not _mis_text and not _cor_text:
            card_parts.append("<p>Content unavailable.</p>")
        card_parts.append("</div>")
        body_parts.append("".join(card_parts))
        try:
            from Courseforge.scripts.generate_course import (  # noqa: PLC0415
                _render_misconception_productive_failure,
            )

            scaffold = _render_misconception_productive_failure(block)
            if scaffold:
                body_parts.append(scaffold)
        except Exception:  # noqa: BLE001 — scaffold is additive; never break render
            pass

    else:
        # Generic styled fallback: each concise claim as a paragraph.
        for claim in claims:
            body_parts.append(f"<p>{esc(claim)}</p>")
        if not body_parts:
            body_parts.append("<p>Content unavailable.</p>")

    body_html = "".join(body_parts)

    # ---- Wrap in the canonical <section> with the same data-cf-* set ----
    attrs = f' data-cf-block-id="{esc(getattr(block, "block_id", ""))}"'
    attrs += ' data-cf-fallback="template"'

    src_ids = list(source_ids or getattr(block, "source_ids", ()) or ())
    if src_ids:
        attrs += f' data-cf-source-ids="{esc(",".join(src_ids))}"'

    oids = list(getattr(block, "objective_ids", ()) or ())
    if oids:
        attrs += f' data-cf-objective-id="{esc(",".join(oids))}"'

    # Content-type: the component-only rewrite table covers
    # self_check_question / activity; for the prose / styled block types the
    # success path stamps the content-type on the <h2>/<h3> heading (which the
    # fallback omits), so map those here too — same canonical values the
    # rewrite contracts use (``explanation`` / ``example`` / ``concept`` /
    # ``definition``).
    content_type = _REWRITE_BLOCK_TYPE_CONTENT_TYPE.get(block_type) or {
        "explanation": "explanation",
        "concept": "concept",
        "example": "example",
        "objective": "objective",
    }.get(block_type)
    if content_type:
        attrs += f' data-cf-content-type="{esc(content_type)}"'

    role = getattr(block, "teaching_role", None) or \
        _teaching_role_for_block_type(block_type)
    if role:
        attrs += f' data-cf-teaching-role="{esc(role)}"'

    bloom = getattr(block, "bloom_level", None)
    if bloom:
        attrs += f' data-cf-bloom-level="{esc(bloom)}"'

    # Source attribution — provenance ids live ONLY in the hidden
    # ``data-cf-source-ids`` attribute (stamped above). A VISIBLE
    # ``<cite class="source-attribution">`` whose body is the raw
    # ``dart:...#hash`` ids leaks machine identifiers into learner prose
    # (P0 identifier-leak defect). Emit no visible id-bearing cite.
    html_out = f"<section{attrs}>{body_html}</section>"

    # P0 — strip any visible minted-CURIE / bare-objective-id leakage and
    # resolve objective <li> bodies to statements (idempotent, lossless on a
    # clean page). The fallback authors no CURIEs in visible prose, but a
    # key_claim could contain a domain term that matches a minted surface —
    # run the sanitizer for parity with the success path.
    html_out = sanitize_leaked_tokens_in_html(
        html_out,
        minted_curie_map=minted_curie_map,
        objective_statements=objective_statements,
    )
    return html_out


def sanitize_leaked_tokens_in_html(
    html: str,
    minted_curie_map: Optional[Dict[str, Any]] = None,
    objective_statements: Optional[Dict[str, str]] = None,
) -> str:
    """Post-hoc P0 sanitizer over a single already-emitted HTML page.

    Standalone (no LLM, no Block dataclass) so an EXISTING two-pass export
    can be cleaned in place without re-running the rewrite tier. Applies:

      * visible minted-CURIE → surface-term replacement (``minted_curie_map``
        shape: ``{curie: {"surface_forms": [...]}}`` from
        ``lib.ontology.curie_discovery.build_minted_curie_map``);
      * objective ``<li>`` bare-id → ``<strong>ID:</strong> statement``
        (``objective_statements`` shape: ``{id: statement}`` from
        :func:`_objective_id_to_statement`).
      * VISIBLE provenance-id leaks (P0 identifier leakage) via
        :func:`_strip_visible_provenance_ids`: CLASS 1 ``dart:<source>#<hash>``
        ids + source-attribution cites, CLASS 2 ``<chunk_id>`` cites + the
        "According to the source" lead-in, CLASS 3 inline ``(CO-NN)``/``(TO-NN)``
        parentheticals — never touching ``data-cf-*`` attributes or hidden
        ``data-cf-curie`` spans.

    Idempotent and lossless on a clean page (returns it unchanged). The
    objective ``<li>`` resolution runs LAST so its emitted ``CO-NN:`` strong
    prefix is never mistaken for an inline parenthetical (it is not parenthesized
    anyway).
    """
    out = html or ""
    for _curie, _meta in (minted_curie_map or {}).items():
        _sf = _meta.get("surface_forms") if isinstance(_meta, dict) else None
        _surface = (
            _sf[0] if isinstance(_sf, list) and _sf
            else _curie.split(":", 1)[-1].replace("_", " ")
        )
        out = _curie_visible_to_surface(out, _curie, _surface)
    # P0 identifier-leak strip (CLASS 1/2/3) — attribute- + hidden-span-safe.
    out = _strip_visible_provenance_ids(out)
    if objective_statements:
        out = _resolve_objective_li_statements(out, objective_statements)
    return out


def sanitize_export_pages(export_dir: str) -> int:
    """Sanitize every ``03_content_development/*.html`` page IN PLACE.

    Applies the full extended P0 leak sanitizer
    (:func:`sanitize_leaked_tokens_in_html`) to each rendered content page of an
    EXISTING Courseforge project export, rewriting the file in place ONLY when
    its bytes change. Lets an already-emitted export be cleaned with NO re-gen
    (the operator runs this, then re-packages).

    ``export_dir`` may be the project root (containing
    ``03_content_development/``) or the ``03_content_development`` directory
    itself. Objective ``<li>`` statements are resolved from a sibling
    ``01_learning_objectives/synthesized_objectives.json`` when present (so an
    objective page whose ``<li>`` body is the bare id is filled with its
    statement too); the minted-CURIE map is not persisted in an export, so that
    arm is a no-op here (a separate, already-handled leak class).

    Returns the number of pages actually rewritten (byte-changed).
    """
    import json as _json
    from pathlib import Path as _Path

    root = _Path(export_dir)
    content_dir = root if root.name == "03_content_development" else (
        root / "03_content_development"
    )
    if not content_dir.is_dir():
        return 0

    # Best-effort objective-statement map from the sibling objectives doc.
    objective_statements: Dict[str, str] = {}
    obj_doc_path = content_dir.parent / "01_learning_objectives" \
        / "synthesized_objectives.json"
    if obj_doc_path.is_file():
        try:
            objective_statements = _objective_id_to_statement(
                _json.loads(obj_doc_path.read_text(encoding="utf-8"))
            )
        except Exception:  # noqa: BLE001 — missing/garbage doc -> no LI fill
            objective_statements = {}

    cleaned = 0
    for page in sorted(content_dir.glob("*.html")):
        try:
            original = page.read_text(encoding="utf-8")
        except Exception:  # noqa: BLE001
            continue
        sanitized = sanitize_leaked_tokens_in_html(
            original,
            minted_curie_map=None,
            objective_statements=objective_statements or None,
        )
        if sanitized != original:
            try:
                page.write_text(sanitized, encoding="utf-8")
                cleaned += 1
            except Exception:  # noqa: BLE001
                continue
    return cleaned


# Matches a hallucinated standalone ``<data-cf-block-id=...>...</data-cf-block-id>``
# element — the 7B rewrite tier occasionally emits the block-id ATTRIBUTE as if it
# were its own tag (week_04 malformation). It is never a valid emit; the bogus
# element trips the html_shape parser (unbalanced / unknown tag). Stripped (open
# + close, attributes and all) in the HTML repair pass.
_BOGUS_BLOCK_ID_EL_RE = re.compile(
    r'<\s*/?\s*data-cf-block-id\b[^>]*>', re.IGNORECASE
)

# CB-SCRIPT: a stray ``<script>...</script>`` fragment the 7B rewrite tier leaks
# into the rendered BODY of a content block — most often a JSON-LD
# ``<script type="application/ld+json">{...}</script>`` blob duplicating the
# block's own metadata. The Sonnet-vs-7B comparison on a real algebra corpus
# fractions corpus captured an ``explanation`` block (block index 1 of
# ``inputs/contentgen/alg_blocks.json``) whose emit appends, AFTER the legitimate
# ``</section>``, a ``<script type="application/ld+json">...</script>`` blob.
# A content block is rendered prose — it must NEVER carry a ``<script>``; the
# JSON-LD survives the existing block-id strip (which only targets the
# ``data-cf-block-id`` pseudo-element, NOT ``<script>``), and the escape step
# treats ``<script ...>`` as a VALID tag opener, so the whole blob (incl. its
# escaped/visible JSON body) leaks into the learner output.
#
# Two regexes strip the whole element (open tag + body + close), both the REAL
# tag form and the entity-escaped ``&lt;script&gt;...&lt;/script&gt;`` form the
# rewrite tier sometimes emits when it double-escapes its own HTML. Non-greedy
# bodies so two separate stray scripts are each stripped (not collapsed into
# one). ``re.DOTALL`` so a multi-line JSON-LD body is matched. Conservative:
# matches ONLY a complete ``script`` element — a block with no stray script is
# byte-identical out and a second pass finds nothing to strip (idempotent). A
# single leading run of inter-element whitespace/newlines is consumed with the
# element so stripping a trailing script does not leave dangling blank lines.
# Attribute-safe by construction: ``<script`` / ``&lt;script`` never appears
# inside an HTML attribute VALUE on a legitimate content block.
_LEAKED_SCRIPT_EL_RE = re.compile(
    r'\s*<\s*script\b[^>]*>.*?<\s*/\s*script\s*>',
    re.IGNORECASE | re.DOTALL,
)
_LEAKED_SCRIPT_EL_ESCAPED_RE = re.compile(
    r'\s*&lt;\s*script\b.*?&lt;\s*/\s*script\s*&gt;',
    re.IGNORECASE | re.DOTALL,
)

# A ``<`` that begins neither a valid HTML start/end tag, a comment, a CDATA, nor
# a processing instruction. The 7B occasionally emits a CURIE token as a tag
# (``<samplecourse:fraction>``) or a bare ``<`` it meant as a literal. The
# repair pass HTML-escapes these so the document parses. A valid tag name starts
# with an ASCII letter and contains only ``[A-Za-z0-9-]`` before whitespace, ``>``,
# or ``/``; a CURIE-as-tag (``name:local``) has a ``:`` and so is NOT matched as a
# valid tag and gets escaped.
_VALID_TAG_OPENER_RE = re.compile(r'</?[A-Za-z][A-Za-z0-9-]*(?=[\s/>])')

# Void / self-closing HTML elements that never need a close tag.
_VOID_HTML_ELEMENTS = frozenset({
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
})

# Element tag names the rewrite-tier 7B unbalances (unclosed span/cite/code or
# stray </code> closers). The balance pass only ever auto-closes / drops these.
_BALANCE_REPAIR_TAGS = frozenset({"span", "cite", "code"})

# CB2: visible bracketed chunk-id tokens the 7B leaks into learner prose
# (e.g. ``[samplecourse_chunk_00043]``, ``[chunk_12]``). Stripped from
# the rendered HTML in the repair pass. The bracketed form is safe to strip with
# a plain string regex because HTML attribute values never contain a literal
# ``[`` ... ``]`` pair around a chunk id (``data-cf-source-ids`` carries the bare
# token ``samplecourse_..._chunk_00043``, never the bracketed form), so this regex
# can NEVER match inside an attribute value. A single leading space is consumed
# with the token so stripping mid-sentence does not leave a double space.
_LEAKED_CHUNK_TOKEN_RE = re.compile(r' ?\[\s*(?:[a-z0-9_]*_)?chunk_\d+\s*\]')

# CB2 (broadened): visible bracketed SOURCE-ID-LIKE tokens the 7B leaks into
# learner prose that the chunk-only regex above misses — e.g.
# ``[clean_simplify_fractions_01]`` (a source id ending in ``_NN`` with no
# "chunk" segment). Matches a bracketed token that LOOKS like a source
# identifier: lowercase/digit/underscore/hyphen content that contains at least
# one ASCII letter AND ends in a ``_<digits>`` segment (the embedded/trailing
# numeric/hash that distinguishes a source id from ordinary bracketed prose).
# Deliberately NOT matched (kept verbatim):
#   * short numeric reference markers ``[1]`` / ``[12]`` — no letter, no ``_``;
#   * ordinary bracketed words ``[note]`` / ``[important]`` — no ``_<digits>``.
# Attribute-safe by the same reasoning as ``_LEAKED_CHUNK_TOKEN_RE``: the
# bracketed ``[`` ... ``]`` form never appears inside an HTML attribute value
# (``data-cf-source-ids="clean_simplify_fractions_01"`` carries the BARE token,
# no brackets), so this can never match inside an attribute. A single leading
# space is consumed with the token so mid-sentence stripping leaves no double
# space. Subsumes ``_LEAKED_CHUNK_TOKEN_RE`` (which is retained above so its
# pinned behavior is independently preserved); both run in the repair pass.
_LEAKED_SOURCE_ID_TOKEN_RE = re.compile(
    r' ?\[\s*[a-z0-9_-]*[a-z][a-z0-9_-]*_\d+\s*\]'
)

# CB2 (dart-shaped): visible bracketed canonical DART source-id tokens the 7B
# leaks into learner prose — e.g. ``[dart:photosynthesis#sec_01]``. The
# ``_<digits>``-suffix regex above cannot match these (the ``dart:`` prefix and
# the ``#`` separator are not ``[a-z0-9_-]``), so a leaked dart id survives into
# rendered prose. Shape mirrors the canonical ``dart:{slug}#{block_id}`` emit
# contract (slug = lowercase + hyphen per the DART slug rule; block_id =
# lowercase/digit/underscore/hyphen). Attribute-safe for the same reason as the
# regexes above — the bracketed ``[`` ... ``]`` form never appears inside an
# attribute value (``data-cf-source-ids="dart:...#..."`` carries the BARE token,
# no brackets). A single leading space is consumed so mid-sentence stripping
# leaves no double space.
_LEAKED_DART_SOURCE_ID_TOKEN_RE = re.compile(
    r' ?\[\s*dart:[a-z0-9][a-z0-9-]*#[a-z0-9_-]+\s*\]'
)

# CB-FENCE: a markdown code fence the 7B rewrite tier sometimes wraps the WHOLE
# HTML block in (e.g. a leading ```` ```html ```` line and a trailing ```` ``` ````
# line). The fence tokens are NOT HTML, so they leak into the rendered learner
# output as visible ```` ```html ```` / ```` ``` ```` text. Real captured example
# (an ``assessment_item`` block from ``inputs/contentgen/alg_blocks.json``):
# the emitted string literally STARTS with ```` ```html ```` on its own line and
# ENDS with a closing ```` ``` ````.
#
# Two anchored regexes strip ONLY a fence that wraps the entire block — never a
# backtick run mid-content (legitimate inline code / prose):
#   * the OPEN regex is anchored at the very START (``^``): optional leading
#     whitespace, then a ```` ``` ```` (three-or-more backticks) optionally
#     followed by a lowercase language token (``html``/``xml``/…) on its own
#     line. A consumed trailing newline keeps the inner HTML flush-left.
#   * the CLOSE regex is anchored at the very END (``$``): an optional leading
#     newline, a ```` ``` ```` (three-or-more backticks), then optional trailing
#     whitespace.
# Anchoring guarantees a block with no wrapping fence is byte-identical out, and
# the pass is idempotent (a second run finds no anchored fence to strip). A
# mid-content backtick run is never anchored at ``^``/``$`` so it survives.
_LEAKED_OPEN_FENCE_RE = re.compile(r'^\s*`{3,}[a-z]*[ \t]*\n?')
_LEAKED_CLOSE_FENCE_RE = re.compile(r'\n?[ \t]*`{3,}\s*$')

# CB-LEAK: the 7B rewrite tier sometimes leaks its REASONING PREAMBLE — the
# chain-of-thought it should keep private — into the emitted block, BEFORE (or
# mid-stream in front of) the real HTML. Two captured shapes:
#   * a NON-ENGLISH (CJK) chain-of-thought line. Real captured ``flip_card_grid``
#     output (a real algebra ch3 capture)
#     emitted a TRUNCATED first attempt, then the literal Chinese reasoning line
#     ``相反地，我将根据要求重新构造HTML内容：`` ("Conversely, I will restructure the
#     HTML content as required:"), then a ```` ```html ```` fence wrapping a
#     COMPLETE second copy of the block (so the leak doubled as a restart).
#   * a common ENGLISH preamble ("Here is the…", "Conversely, I will…",
#     "Sure, here's…") on the model's own preface line.
#
# These are reasoning, never legitimate learner content, so the leading run up to
# and including the preamble line (plus an immediately-following code fence) is
# stripped — but ONLY when a real BLOCK-LEVEL HTML opener follows it, so a clean
# block is byte-identical and legitimate intro prose is never eaten. Two anchored
# arms, each with the SAME block-opener lookahead:
#   * ``_LEAKED_CJK_PREAMBLE_RE`` (mid-stream-safe): a lazy run from the very
#     START consuming anything up to and including a line that CONTAINS a CJK
#     character (CJK is never legitimate algebra-course content, so it is safe to
#     drop a truncated HTML head that precedes it — which simultaneously de-dupes
#     the doubled-block restart). DOTALL so the lazy head spans the truncated
#     first attempt's newlines.
#   * ``_LEAKED_ENGLISH_PREAMBLE_RE`` (LEADING-only): a leading ``[^<]*?`` run
#     (no ``<`` permitted before the preamble) then a known preamble phrase. The
#     ``[^<]`` guard means this arm can ONLY fire on a genuinely-leading preamble
#     (no HTML has started yet); it will NOT match "Here is" inside an already-
#     open ``<p>…</p>`` followed by a ``<div>`` (which would corrupt valid prose).
#     English prose is sometimes legitimate before the first tag, so this arm is
#     deliberately gated to a SHORT allowlist of model-preface phrases.
# Both lookaheads require one of ``<div|section|p|ul|ol|table|h1..6|details``
# (block-level openers); a block that already starts with HTML, or whose leading
# non-HTML segment is neither CJK nor an allowlisted preamble (ordinary intro
# prose), is byte-identical out. Any trailing ```` ``` ```` left after the strip
# is removed by ``_LEAKED_CLOSE_FENCE_RE`` (this step runs BEFORE the fence step).
# Idempotent: after the strip the string starts with the block opener, so the
# ``\A``-anchored lazy heads have nothing to consume on a second pass. Stdlib
# ``re`` only, no LLM.
#
# DELIBERATE non-repair (documented limitation): the DOUBLED-block case is only
# de-duped when it coincides with a CJK/preamble restart marker (the captured
# shape — the marker is the join). A bare doubled block with NO leak marker
# between the two copies is NOT de-duped here: there is no deterministic,
# false-positive-safe boundary between "block emitted twice" and "two sibling
# blocks of the same type" (a 3-card flip grid legitimately repeats its
# ``flip-card`` subtree), so de-duping it would risk eating valid content. Left
# to upstream prompt mitigation rather than over-engineered here.
_CJK_CHAR_CLASS = (
    '　-〿'   # CJK symbols & punctuation (、。「」 etc.)
    '぀-ヿ'   # hiragana + katakana
    '㐀-䶿'   # CJK ext-A
    '一-鿿'   # CJK unified ideographs
    '豈-﫿'   # CJK compatibility ideographs
    '＀-￯'   # halfwidth/fullwidth forms
)
_BLOCK_OPENER_LOOKAHEAD = (
    r'(?=<(?:div|section|p|ul|ol|table|h[1-6]|details)\b)'
)
# Optional trailing code fence + whitespace between the preamble line and the
# block opener (the captured leak put a ```` ```html ```` fence here).
_LEAK_FENCE_GAP = r'(?:[ \t\r\n]*`{3,}[a-z]*[ \t]*)?[ \t\r\n]*'
_LEAKED_CJK_PREAMBLE_RE = re.compile(
    r'\A.*?[' + _CJK_CHAR_CLASS + r'][^\n]*' + _LEAK_FENCE_GAP
    + _BLOCK_OPENER_LOOKAHEAD,
    re.IGNORECASE | re.DOTALL,
)
# Short allowlist of model-preface phrases (case-insensitive); straight or curly
# apostrophe in the contracted forms.
_LEAK_ENGLISH_PREAMBLE = (
    r'(?:Here(?:’|\')?s|Here is|Sure,?[ \t]*here(?:’|\')?s|'
    r'Conversely,?[ \t]*I will|'
    r'I will(?:[ \t]+now)?[ \t]+(?:re)?(?:write|construct|structure|restructure))'
)
_LEAKED_ENGLISH_PREAMBLE_RE = re.compile(
    r'\A[^<]*?' + _LEAK_ENGLISH_PREAMBLE + r'[^\n<]*' + _LEAK_FENCE_GAP
    + _BLOCK_OPENER_LOOKAHEAD,
    re.IGNORECASE,
)


class _TagBalanceScanner:
    """Stdlib tolerant scan to detect unbalanced ``_BALANCE_REPAIR_TAGS``.

    Walks the HTML with :class:`html.parser.HTMLParser` (lenient — never
    raises), counting open vs. close for each repair tag. Reports, per tag,
    the net unclosed-open count and the net stray-close count so the repair
    pass can deterministically append missing closers / strip stray ones.
    """

    def __init__(self, html_text: str) -> None:
        from html.parser import HTMLParser

        open_counts: Dict[str, int] = {t: 0 for t in _BALANCE_REPAIR_TAGS}
        stray_close: Dict[str, int] = {t: 0 for t in _BALANCE_REPAIR_TAGS}

        class _Scanner(HTMLParser):
            def handle_starttag(self, tag, attrs):  # noqa: ANN001
                t = tag.lower()
                if t in _BALANCE_REPAIR_TAGS:
                    open_counts[t] += 1

            def handle_startendtag(self, tag, attrs):  # noqa: ANN001
                # Self-closed (<span/>) — balanced, do not count.
                return

            def handle_endtag(self, tag):  # noqa: ANN001
                t = tag.lower()
                if t in _BALANCE_REPAIR_TAGS:
                    if open_counts[t] > 0:
                        open_counts[t] -= 1
                    else:
                        stray_close[t] += 1

        parser = _Scanner(convert_charrefs=False)
        try:
            parser.feed(html_text)
            parser.close()
        except Exception:  # noqa: BLE001 - parser is lenient; never abort
            pass
        # Whatever remains in open_counts after the full feed is unclosed.
        self.unclosed = {t: c for t, c in open_counts.items() if c > 0}
        self.stray_close = {t: c for t, c in stray_close.items() if c > 0}


def _repair_rewrite_html(html: str) -> str:
    """Deterministically repair the 7B rewrite-tier HTML malformations (NO LLM).

    Targets exactly the PARSE-FAIL classes the rewrite tier emits, in order:

    -2. Strip a leaked REASONING PREAMBLE preceding the real HTML (CB-LEAK): a
       leading run of model chain-of-thought — a CJK reasoning line (e.g. the
       captured ``相反地，我将根据要求重新构造HTML内容：``) or a short English preface
       ("Here is the…", "Conversely, I will…", "Sure, here's…") — that the 7B
       leaks BEFORE the first block-level HTML opener. Anchored to a following
       ``<div|section|p|ul|ol|table|h1..6|details`` opener; a block that already
       starts with HTML, or whose leading non-HTML segment is ordinary intro
       prose (no CJK, no allowlisted preface), is byte-identical out. The CJK arm
       is mid-stream-safe (it also drops a truncated first attempt + de-dupes the
       captured doubled-block restart, whose join is the CJK line); the English
       arm is leading-only (cannot fire once HTML has started). Runs FIRST so the
       fence step below cleans any trailing ``` ``` ``` the restart left behind.
    -1. Strip a markdown code fence WRAPPING the whole block (CB-FENCE): a
       leading ``` ```html ``` / ``` ``` ``` opener and a trailing ``` ``` ```
       closer the 7B sometimes wraps the entire HTML string in. The fence tokens
       are not HTML and otherwise render as visible ``` ```html ``` / ``` ``` ```
       text. Anchored at the very start/end of the string, so a backtick run
       mid-content (legitimate inline code/prose) is left untouched and a block
       with no wrapping fence is byte-identical. Runs FIRST so the tag-balance
       and escape steps below see clean HTML.
    0. Strip visible leaked bracketed source-id tokens (CB2) the 7B drops into
       learner prose (e.g. ``[samplecourse_chunk_00043]`` and the
       broader ``[clean_simplify_fractions_01]`` source-id form), along with a
       single leading space so the surrounding prose is not double-spaced.
       Operates on the bracketed form only, which never appears inside an HTML
       attribute value, so ``data-cf-source-ids="..."`` is left untouched.
       Short numeric reference markers (``[1]``, ``[12]``) and ordinary
       bracketed words (``[note]``) are NOT stripped.
    1. Strip the bogus standalone ``<data-cf-block-id=...>`` pseudo-element.
       This already covers the attribute-style form ``<data-cf-block-id="..."
       data-cf-content-type="...">...</data-cf-block-id>`` the 7B emits with a
       space + attrs (the ``[^>]*>`` tail matches the attribute region).
    1b. Strip a stray ``<script>...</script>`` fragment (CB-SCRIPT) leaked into
       the rendered body — most often a ``<script type="application/ld+json">``
       JSON-LD blob the 7B appends after the legitimate ``</section>``. Both the
       real-tag form and the entity-escaped ``&lt;script&gt;...&lt;/script&gt;``
       form. A content block is rendered prose and must never carry a script.
    2. HTML-escape any ``<token:...>`` / bare ``<`` / stray ``>`` the model
       meant as literal text (CURIE-as-tag, e.g. ``<samplecourse:fraction>``).
       A ``<`` opening a genuine valid HTML tag is left intact.

    CB3 (deliberate non-repair — documented limitation): a valid tag opener
    whose ``>`` is MISSING (e.g. a ``<li ...text`` opener where the next ``<``
    arrives before any ``>``) is NOT auto-repaired. Inserting a synthetic ``>``
    at the next-``<`` boundary would absorb the visible text content into the
    start tag (``<li class="y"Item two...>``), corrupting valid prose — there is
    no deterministic boundary between attribute region and text once the ``>`` is
    gone. Per the never-corrupt-valid-HTML contract, this malformed-OPENER class
    degrades to graceful escaping / tolerant-parser handling and is mitigated
    upstream by CB1's "emit well-formed HTML" prompt directive. The unbalanced-
    CLOSE case for list elements (``li`` / ``ul`` / ``ol``) is likewise NOT added
    to ``_BALANCE_REPAIR_TAGS`` — a flat open/close count cannot safely
    reconstruct nested lists.

    3. Balance the three repair tags (``span`` / ``cite`` / ``code``): append a
       close tag for each net-unclosed open, and strip net stray closers.

    Idempotent: re-running over already-valid HTML is a no-op (no leaked token
    remains, no bogus element remains, no bare ``<`` survives, and the repair
    tags are balanced so nothing is added or stripped). Uses only the stdlib
    (``html.parser`` + ``html.escape``); no new heavy deps, no LLM. Out of scope
    by design: semantic ``<code>`` -> ``<span>`` rewriting — only PARSE-FAIL
    repair.
    """
    import html as _html

    if not isinstance(html, str) or not html:
        return html

    # -2. CB-LEAK: strip a leaked reasoning preamble (CJK chain-of-thought or a
    # short English preface) that precedes the first block-level HTML opener.
    # The CJK arm runs first (mid-stream-safe: it drops a truncated first attempt
    # + de-dupes the captured doubled-block restart joined by the CJK line); the
    # English arm is leading-only (the ``[^<]`` lead means it cannot fire once
    # HTML has started, so a legit ``<p>Here is …</p>`` is never eaten). Anchored
    # to a following block opener, so a clean block is byte-identical. Runs BEFORE
    # the fence step so any trailing ``` ``` ``` the restart left is then cleaned.
    out = _LEAKED_CJK_PREAMBLE_RE.sub("", html, count=1)
    out = _LEAKED_ENGLISH_PREAMBLE_RE.sub("", out, count=1)

    # -1. CB-FENCE: strip a markdown code fence WRAPPING the whole block (a
    # leading ``` ```html ``` opener + a trailing ``` ``` ``` closer the 7B
    # sometimes wraps the entire HTML string in). Anchored at start/end only, so
    # a mid-content backtick run survives and a fence-free block is byte-
    # identical. Runs first so the steps below see clean HTML.
    out = _LEAKED_OPEN_FENCE_RE.sub("", out)
    out = _LEAKED_CLOSE_FENCE_RE.sub("", out)

    # 0. CB2: strip visible leaked bracketed chunk-id tokens (and a leading
    # space) from the rendered HTML. Bracketed-only, so attribute values such as
    # ``data-cf-source-ids="...chunk_00043..."`` (bare token, no brackets) are
    # never matched.
    out = _LEAKED_CHUNK_TOKEN_RE.sub("", out)
    # Broadened CB2: also strip other bracketed source-id-like tokens (e.g.
    # ``[clean_simplify_fractions_01]``) the chunk-only regex misses. Same
    # attribute-safety guarantee (bracketed form only).
    out = _LEAKED_SOURCE_ID_TOKEN_RE.sub("", out)
    # CB2 (dart-shaped): strip bracketed canonical DART ids (e.g.
    # ``[dart:photosynthesis#sec_01]``) the suffix-based regex above misses.
    out = _LEAKED_DART_SOURCE_ID_TOKEN_RE.sub("", out)

    # 1. Drop the bogus standalone data-cf-block-id pseudo-element.
    out = _BOGUS_BLOCK_ID_EL_RE.sub("", out)

    # 1b. CB-SCRIPT: strip a stray ``<script>...</script>`` fragment leaked into
    # the rendered body (e.g. a JSON-LD blob the 7B appends after ``</section>``).
    # Both the real-tag and the entity-escaped form. Runs BEFORE the escape step
    # so the real ``<script ...>`` opener (which the escape step would otherwise
    # treat as a valid tag and copy verbatim) is removed whole.
    out = _LEAKED_SCRIPT_EL_RE.sub("", out)
    out = _LEAKED_SCRIPT_EL_ESCAPED_RE.sub("", out)

    # 2. HTML-escape stray ``<``/``>`` the model meant as literal text. Walk the
    # string; a ``<`` that opens a valid HTML tag (start/end), comment, CDATA, or
    # processing instruction is left intact, everything else is escaped to
    # ``&lt;``. A ``>`` that does NOT close a tag we just passed is escaped to
    # ``&gt;``.
    repaired: List[str] = []
    i = 0
    n = len(out)
    while i < n:
        ch = out[i]
        if ch == "<":
            rest = out[i:]
            if rest.startswith("<!--") or rest.startswith("<!") or rest.startswith("<?"):
                # Comment / declaration / PI — copy verbatim to its terminator.
                repaired.append(ch)
                i += 1
                continue
            if _VALID_TAG_OPENER_RE.match(rest):
                # A genuine tag opener: copy the whole tag verbatim up to the
                # matching ``>`` so its attributes / ``>`` are not escaped.
                #
                # CB3 (deliberate non-repair): a valid tag opener whose ``>`` is
                # MISSING (e.g. a ``<li ...text`` opener where the next ``<`` —
                # the ``</li>`` closer or the next ``<li>`` — arrives before any
                # ``>``) is NOT auto-repaired. Inserting a ``>`` at the next-``<``
                # boundary would absorb the visible text content into the start
                # tag (``<li class="y"Item two...>``), CORRUPTING valid prose,
                # because there is no deterministic boundary between "attribute
                # region" and "text content" once the ``>`` is gone. Per the
                # function's PARSE-FAIL-only / never-corrupt-valid-HTML contract,
                # this class degrades to the graceful ``&lt;`` escape below
                # (handled by the ``close == -1`` branch when no ``>`` follows;
                # when a later ``>`` exists the opener is copied up to it, which
                # the html parser then tolerates) and is mitigated upstream by
                # CB1's "emit well-formed HTML" prompt directive.
                close = out.find(">", i)
                if close == -1:
                    # Unterminated ``<tag`` — escape the lone ``<`` literally.
                    repaired.append("&lt;")
                    i += 1
                    continue
                repaired.append(out[i:close + 1])
                i = close + 1
                continue
            # Bare ``<`` or a CURIE/pseudo tag (``<name:local>``) — escape it.
            repaired.append("&lt;")
            i += 1
            continue
        if ch == ">":
            # A ``>`` reached here is not the terminator of a tag we copied
            # verbatim (those were consumed whole above) — escape it.
            repaired.append("&gt;")
            i += 1
            continue
        repaired.append(ch)
        i += 1
    out = "".join(repaired)

    # 3. Balance span / cite / code.
    scan = _TagBalanceScanner(out)
    for tag, stray in scan.stray_close.items():
        # Strip net stray closers (e.g. week_17's 18 orphan </code>). Remove from
        # the RIGHT so an earlier legitimately-matched closer is preserved.
        pattern = re.compile(rf'</\s*{tag}\s*>', re.IGNORECASE)
        matches = list(pattern.finditer(out))
        # Only the LAST ``stray`` closers are surplus; strip those.
        for m in reversed(matches[-stray:] if stray <= len(matches) else matches):
            out = out[:m.start()] + out[m.end():]
    # Append missing closers for net-unclosed opens (re-scan after stray strip).
    scan2 = _TagBalanceScanner(out)
    suffix_parts: List[str] = []
    for tag, count in scan2.unclosed.items():
        suffix_parts.extend(f"</{tag}>" for _ in range(count))
    if suffix_parts:
        out += "".join(suffix_parts)
    return out


def _canonical_source_ids_for_chunks(
    source_chunks: Any,
    slug: str,
    chunk_source_id_map: Optional[Dict[str, List[str]]] = None,
) -> List[str]:
    """Resolve canonical ``dart:{module_id}#{hash}`` source refs for a block.

    ``source_chunks`` is the block's resolved chunk universe rehydrated from
    the W2 ``outline_chunks.json`` sidecar — a list of ``{id, text, heading}``
    dicts. Only entries carrying BOTH a non-empty ``id`` and a real ``text``
    field are eligible: a topic-paragraph fallback entry (no ``text`` key) is
    NOT grounded provenance, so it contributes nothing.

    ``chunk_source_id_map`` maps each DART chunk ``id`` to the list of REAL,
    resolvable ``dart:{module_id}#{hash}`` source ids carried in that chunk's
    ``source.source_references[].sourceId`` (harvested at rewrite time from the
    LibV2 ``chunks.jsonl``). These are the ids the ``content_grounding`` gate
    resolves against the DART staging HTML's ``data-dart-block-id`` set — they
    are NOT a synthetic ``dart:{course-slug}#{chunk_id}`` mint (that form never
    resolves and was the root cause of the all-blocks-UNRESOLVED failure).

    Anti-fabrication contract (fail closed; NEVER invent a ref):

    * No ``chunk_source_id_map`` supplied (legacy / test callers) -> empty list.
    * A chunk entry with no grounded ``text`` -> contributes nothing.
    * A chunk ``id`` absent from the map -> contributes nothing.
    * A chunk ``id`` whose map entry resolves to zero (validated) sourceIds ->
      contributes nothing.

    Each resolved id is re-validated through the canonical shape regex
    (``^dart:[a-z0-9_-]+#[a-z0-9_-]+$``) so a malformed sourceId can never
    poison the attribute. Returns a de-duplicated, discovery-order list. When a
    block resolves to zero grounded sourceIds it legitimately gets an empty
    list and fails closed on the rewrite_source_refs gate (deferred / empty
    attribution) rather than carrying an invented ref.
    """
    if not slug or not isinstance(source_chunks, list):
        return []
    if not isinstance(chunk_source_id_map, dict) or not chunk_source_id_map:
        # No real-sourceId map -> never mint a synthetic ref (fail closed).
        return []
    seen: set = set()
    out: List[str] = []
    for entry in source_chunks:
        if not isinstance(entry, dict):
            continue
        cid = entry.get("id")
        txt = entry.get("text")
        if not (isinstance(cid, str) and cid.strip()):
            continue
        if not (isinstance(txt, str) and txt.strip()):
            # No grounded text -> not provenance; never emit a ref.
            continue
        real_ids = chunk_source_id_map.get(cid.strip())
        if not isinstance(real_ids, list) or not real_ids:
            # Chunk absent from the map or resolves to zero sourceIds ->
            # emit nothing for this chunk (fail closed, no fabrication).
            continue
        for source_id in real_ids:
            if not (isinstance(source_id, str) and source_id.strip()):
                continue
            source_id = source_id.strip()
            if source_id in seen:
                continue
            if not _CANONICAL_DART_SOURCE_ID_RE.match(source_id):
                continue
            seen.add(source_id)
            out.append(source_id)
    return out


def _build_chunk_source_id_map(
    dart_chunks_path: Optional[Path],
) -> Dict[str, List[str]]:
    """Build a ``chunk_id -> [real dart: sourceId]`` map from chunks.jsonl.

    Reads the LibV2 ``dart_chunks/chunks.jsonl`` for the course and harvests,
    per chunk, the REAL resolvable ``dart:{module_id}#{hash}`` source ids from
    ``source.source_references[].sourceId`` — the same ids the
    ``content_grounding`` gate resolves against the DART staging HTML. Mirrors
    the read pattern in :func:`_build_manifest_chunk_resolver`.

    Each harvested sourceId must pass ``_CANONICAL_DART_SOURCE_ID_RE``; a chunk
    with no valid sourceId gets no map entry (so the caller fails closed rather
    than fabricating a ref). Best-effort: a missing / unreadable chunkset
    yields an empty map.
    """
    out: Dict[str, List[str]] = {}
    if dart_chunks_path is None or not dart_chunks_path.exists():
        return out
    try:
        with dart_chunks_path.open("r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    chunk = json.loads(line)
                except ValueError:
                    continue
                if not isinstance(chunk, dict):
                    continue
                chunk_id = chunk.get("id")
                if not (isinstance(chunk_id, str) and chunk_id.strip()):
                    continue
                chunk_id = chunk_id.strip()
                source = chunk.get("source")
                if not isinstance(source, dict):
                    continue
                src_refs = source.get("source_references") or []
                if not isinstance(src_refs, list):
                    continue
                seen: set = set()
                ids: List[str] = []
                for ref in src_refs:
                    if not isinstance(ref, dict):
                        continue
                    sid = ref.get("sourceId")
                    if not (isinstance(sid, str) and sid.strip()):
                        continue
                    sid = sid.strip()
                    if sid in seen:
                        continue
                    if not _CANONICAL_DART_SOURCE_ID_RE.match(sid):
                        continue
                    seen.add(sid)
                    ids.append(sid)
                if ids:
                    out.setdefault(chunk_id, ids)
    except OSError as exc:
        logger.warning(
            "chunk_source_id_map: failed to read chunks.jsonl at %s: %s",
            dart_chunks_path,
            exc,
        )
    return out


def _ensure_directories():
    """Ensure required directories exist."""
    for path in [COURSEFORGE_INPUTS, TRAINING_CAPTURES]:
        path.mkdir(parents=True, exist_ok=True)


_ensure_directories()


# ---------------------------------------------------------------------------
# Wave 74 cleanup: pluggable staging modes.
#
# stage_dart_outputs originally deep-copied every DART HTML, *_synthesized.json,
# *.quality.json, and `{stem}_figures/` directory into
# ``Courseforge/inputs/textbooks/{run_id}/``. For an 8-PDF / 768-page corpus
# this cost ~70MB per run; the staging dir is gitignored and never garbage
# collected. Symlinks (or hardlinks on platforms that disallow user symlinks)
# preserve every downstream behaviour because all known consumers go through
# Path().read_text() / read_bytes() rather than os.path.realpath().
#
# Modes:
#   - "copy"     : shutil.copy2 / shutil.copytree (legacy behaviour)
#   - "symlink"  : os.symlink for files AND directories (single tree-symlink
#                  for the figures dir, NOT a deep walk)
#   - "hardlink" : os.link for files; for directories, recreate the tree and
#                  hardlink each file. Falls back when symlinks are blocked
#                  (e.g., Windows without SeCreateSymbolicLinkPrivilege).
#
# Default for runs with no override is ``symlink``: the staging tree is
# gitignored test infrastructure, the source DART output is the durable copy,
# and downstream phases never write to the staged paths so symlink rot is not
# a concern.
# ---------------------------------------------------------------------------

VALID_STAGE_MODES = ("copy", "symlink", "hardlink")
DEFAULT_STAGE_MODE = "symlink"


def _resolve_stage_mode(explicit: Optional[str] = None) -> str:
    """Resolve the active staging mode.

    Precedence:
        1. ``explicit`` parameter (passed through from the tool kwargs).
        2. ``ED4ALL_STAGE_MODE`` environment variable.
        3. :data:`DEFAULT_STAGE_MODE` (``"symlink"``).

    Unknown values fall back to the default with a warning so a typo never
    silently disables staging.
    """
    candidate = explicit or os.environ.get("ED4ALL_STAGE_MODE") or DEFAULT_STAGE_MODE
    candidate = candidate.strip().lower()
    if candidate not in VALID_STAGE_MODES:
        logger.warning(
            "Unknown stage_mode %r — falling back to %r. Valid: %s",
            candidate, DEFAULT_STAGE_MODE, VALID_STAGE_MODES,
        )
        candidate = DEFAULT_STAGE_MODE
    return candidate


def _stage_file(src: Path, dest: Path, mode: str) -> None:
    """Stage a single file at ``src`` into ``dest`` using the given mode.

    Always replaces an existing ``dest`` (file or symlink) so re-runs are
    idempotent. Falls back from symlink/hardlink to copy on OSError so a
    locked-down platform can never break a staging phase outright.
    """
    if dest.exists() or dest.is_symlink():
        dest.unlink()
    if mode == "copy":
        shutil.copy2(src, dest)
        return
    if mode == "symlink":
        try:
            os.symlink(os.fspath(src.resolve()), os.fspath(dest))
            return
        except OSError as e:
            logger.warning(
                "symlink failed for %s -> %s (%s); falling back to copy", src, dest, e,
            )
            shutil.copy2(src, dest)
            return
    if mode == "hardlink":
        try:
            os.link(os.fspath(src), os.fspath(dest))
            return
        except OSError as e:
            logger.warning(
                "hardlink failed for %s -> %s (%s); falling back to copy", src, dest, e,
            )
            shutil.copy2(src, dest)
            return
    # Should never hit — _resolve_stage_mode guards the enum.
    shutil.copy2(src, dest)


def _stage_tree(src_dir: Path, dest_dir: Path, mode: str) -> None:
    """Stage a directory tree from ``src_dir`` into ``dest_dir``.

    - ``copy``     : shutil.copytree (deep copy)
    - ``symlink``  : a single tree-level os.symlink at ``dest_dir`` pointing at
                     ``src_dir``. Cheap (one inode, no walk).
    - ``hardlink`` : recreate the directory structure and hardlink every file.
    """
    if dest_dir.exists() or dest_dir.is_symlink():
        if dest_dir.is_symlink() or dest_dir.is_file():
            dest_dir.unlink()
        else:
            shutil.rmtree(dest_dir)
    if mode == "copy":
        shutil.copytree(src_dir, dest_dir)
        return
    if mode == "symlink":
        try:
            os.symlink(
                os.fspath(src_dir.resolve()),
                os.fspath(dest_dir),
                target_is_directory=True,
            )
            return
        except OSError as e:
            logger.warning(
                "tree symlink failed for %s -> %s (%s); falling back to copytree",
                src_dir, dest_dir, e,
            )
            shutil.copytree(src_dir, dest_dir)
            return
    if mode == "hardlink":
        try:
            for src_path in src_dir.rglob("*"):
                rel = src_path.relative_to(src_dir)
                target = dest_dir / rel
                if src_path.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    if target.exists():
                        target.unlink()
                    try:
                        os.link(os.fspath(src_path), os.fspath(target))
                    except OSError:
                        shutil.copy2(src_path, target)
            return
        except OSError as e:
            logger.warning(
                "hardlink tree failed for %s -> %s (%s); falling back to copytree",
                src_dir, dest_dir, e,
            )
            if dest_dir.exists():
                shutil.rmtree(dest_dir)
            shutil.copytree(src_dir, dest_dir)
            return
    shutil.copytree(src_dir, dest_dir)


def _course_chunk_id_prefix(course_name: str) -> str:
    """Return the ``{course_code}_chunk_`` prefix Trainforge writes.

    Mirrors ``Trainforge.process_course.CourseProcessor`` — the chunk
    prefix is ``f"{self.course_code.lower()}_chunk_"`` (see
    ``Trainforge/process_course.py:1106``). We lowercase here too so the
    archival gate matches the on-disk IDs exactly. Spaces / dashes get
    normalised to underscores so values that have already been slugified
    (e.g. ``"demo-101"``) still produce the right prefix
    (``"demo_101_chunk_"``).
    """
    code = (course_name or "").strip().lower()
    if not code:
        return ""
    # Trainforge keeps underscores in the prefix; if the caller passed a
    # slug-shaped name (``demo-101``), normalise back to underscores.
    code = code.replace("-", "_").replace(" ", "_")
    return f"{code}_chunk_"


def _normalize_chunk_course_code(course_name: str) -> str:
    """Return the ``course_code`` the chunker prefixes chunk IDs with.

    W0.6: the two chunking helpers (``_run_dart_chunking`` /
    ``_run_imscc_chunking``) computed ``course_name.upper().replace("-", "_")``
    — which OMITS the space→underscore replacement the adjacent ``course_slug``
    line does — so a space-bearing course name (``"My Course"``) produced a
    course_code carrying a literal space (``"MY COURSE"``) and therefore chunk
    IDs like ``"my course_chunk_00000"`` with whitespace baked into the id (the
    id-prefix gate ``^{course_code_lower}_chunk_`` then can't match, and the
    whitespace breaks downstream slug/path assumptions).

    This routes both sites through one helper that mirrors
    :func:`_course_chunk_id_prefix`'s normalisation in upper-case: dashes →
    underscores, every whitespace RUN → a single underscore, then collapse
    repeated underscores so ``"My - Course"`` → ``"MY_COURSE"`` rather than
    ``"MY___COURSE"``. Empty / whitespace-only input falls back to
    ``"UNKNOWN"`` (the historical sentinel the call sites already used).
    """
    raw = (course_name or "").strip().upper()
    if not raw:
        return "UNKNOWN"
    code = raw.replace("-", "_")
    code = re.sub(r"\s+", "_", code)
    code = re.sub(r"_+", "_", code).strip("_")
    return code or "UNKNOWN"


def _assert_no_whitespace_chunk_ids(chunks: List[Dict[str, Any]]) -> List[str]:
    """Return the list of emitted chunk IDs that contain whitespace.

    W0.6 emit-time tripwire: a non-empty return means the chunk-ID
    normalisation upstream let whitespace leak into an id. Callers log a loud
    warning and stamp a manifest field so the defect is observable post-hoc
    instead of silently corrupting the id-prefix grounding gate.
    """
    offenders: List[str] = []
    for chunk in chunks:
        cid = chunk.get("id") or chunk.get("chunk_id")
        if isinstance(cid, str) and re.search(r"\s", cid):
            offenders.append(cid)
    return offenders


def _atomic_write_text(path: Path, text: str, *, encoding: str = "utf-8") -> None:
    """Write ``text`` to ``path`` atomically (temp file + ``os.replace``).

    W0.7: per-course + pipeline ``manifest.json`` writes were a bare
    ``write_text`` / ``open("w")`` — a crash (or a concurrent reader) mid-write
    leaves a truncated, unparseable manifest on disk. Writing to a sibling temp
    file and ``os.replace``-ing it onto the target makes the swap atomic on
    POSIX (same-directory rename), so a reader sees either the old or the new
    manifest, never a half-written one.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
    try:
        with open(tmp, "w", encoding=encoding) as fh:
            fh.write(text)
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except OSError:
                pass
        os.replace(tmp, path)
    finally:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:
            pass


def _check_chunks_freshness(
    *,
    chunks_path: Path,
    course_name: str,
    run_start_ts: float,
    had_prior_chunks: bool,
) -> dict:
    """Wave 74: classify chunks.jsonl at the archive destination.

    Returns a dict with ``status`` ∈ {``"absent"``, ``"fresh"``,
    ``"stale"``} plus diagnostic fields. The archival caller fails closed
    on ``"stale"``.

    Decision rules:

    * ``absent`` — no file at ``chunks_path``. Trainforge was
      intentionally skipped (DART-only batch) OR the copy block deleted
      the prior file and never wrote a fresh one. Either way, archival
      proceeds without chunks; feature flags fall back to ``false``.
    * ``fresh`` — file exists; either every line decodes to a chunk
      whose ``id`` starts with ``{course_code_lower()}_chunk_`` OR the
      file's ``mtime`` is at or after ``run_start_ts`` (mtime check is
      a fallback for callers that don't follow the prefix convention).
    * ``stale`` — file exists, but at least one chunk's ``id`` carries
      a prefix that doesn't match the current course AND the file
      pre-dates ``run_start_ts``. Caught the RDF/SHACL calibration corpus leak.

    Args:
        chunks_path: Where chunks.jsonl lives in the LibV2 archive
            (``course_dir / "imscc_chunks" / "chunks.jsonl"`` post-Phase
            7c, or legacy ``course_dir / "corpus" / "chunks.jsonl"``).
        course_name: The current run's course code / name. Used to
            derive the expected ``{prefix}_chunk_`` ID pattern.
        run_start_ts: ``time.time()`` captured at archival entry. Files
            with ``mtime >= run_start_ts`` are by definition fresh.
        had_prior_chunks: ``True`` when the destination already had a
            chunks file before the copy block ran. Used to disambiguate
            the ``absent`` outcome — when we deleted a prior file but
            never re-wrote, the absent-after-delete state is OK as long
            as Trainforge was intentionally absent. (We don't fail
            closed on it because the existing flow was always fine with
            no chunks for DART-only runs.)
    """
    if not chunks_path.exists() or not chunks_path.is_file():
        return {"status": "absent", "reason": "no chunks.jsonl present"}

    expected_prefix = _course_chunk_id_prefix(course_name)
    if not expected_prefix:
        # No course name → can't validate. Treat as absent so we don't
        # fail closed on a caller-side bug; the missing-course-name
        # branch above already short-circuits with a clearer error.
        return {"status": "absent", "reason": "no course_name to validate against"}

    # mtime check — files written this run pass unconditionally.
    try:
        mtime = chunks_path.stat().st_mtime
    except OSError:
        mtime = 0.0
    if mtime >= run_start_ts:
        return {
            "status": "fresh",
            "reason": "chunks.jsonl mtime is at/after run start",
        }

    # mtime predates run-start → inspect the IDs. We sample a bounded
    # number of lines so a multi-GB chunks.jsonl doesn't blow the
    # archival path's runtime.
    #
    # Decision rule: chunks landing in a LibV2 archive are produced by
    # ``Trainforge.process_course`` which writes IDs as
    # ``{course_code.lower()}_chunk_{N}`` (process_course.py:1106). The
    # ``_chunk_`` substring is the recognizable production signature.
    # When at least one chunk on disk has a recognizable course prefix
    # (i.e. ``{head}_chunk_...``) that DOESN'T match the current course,
    # we have positive evidence the chunks file is from a different
    # run/course → stale. When chunks have no recognizable
    # ``{head}_chunk_`` shape at all (synthetic test fixtures,
    # malformed inputs), we treat as unverifiable rather than stale —
    # the pre-Wave-74 behaviour was to write the archive anyway, and a
    # purely-synthetic IMSCC pipeline is allowed to keep working.
    observed_prefixes: dict[str, int] = {}
    matched = 0
    unrecognized = 0
    inspected = 0
    sample_limit = 50
    try:
        with open(chunks_path, encoding="utf-8") as fh:
            for raw_line in fh:
                line = raw_line.strip()
                if not line:
                    continue
                inspected += 1
                try:
                    chunk = json.loads(line)
                except (json.JSONDecodeError, ValueError):
                    unrecognized += 1
                    continue
                if not isinstance(chunk, dict):
                    unrecognized += 1
                    continue
                cid = chunk.get("id") or ""
                if not isinstance(cid, str):
                    unrecognized += 1
                    continue
                if cid.startswith(expected_prefix):
                    matched += 1
                elif "_chunk_" in cid:
                    # Recognizable production-shape ID but wrong course.
                    head = cid.split("_chunk_", 1)[0]
                    if head:
                        observed_prefixes[head] = (
                            observed_prefixes.get(head, 0) + 1
                        )
                    else:
                        unrecognized += 1
                else:
                    # No ``_chunk_`` marker at all — synthetic / minimal
                    # test fixture or unknown shape. No positive evidence
                    # of staleness; tolerate.
                    unrecognized += 1
                if inspected >= sample_limit:
                    break
    except OSError as exc:
        return {
            "status": "stale",
            "reason": f"could not read chunks.jsonl ({exc})",
            "expected_prefix": expected_prefix,
            "observed_prefixes": {},
        }

    if inspected == 0:
        # File exists but is empty / all blank lines — treat as absent
        # so DART-only smoke tests that touch an empty chunks file
        # don't get a false-positive failure.
        return {
            "status": "absent",
            "reason": "chunks.jsonl is empty",
        }

    if matched > 0:
        return {
            "status": "fresh",
            "reason": (
                f"found {matched}/{inspected} chunks matching prefix "
                f"{expected_prefix!r}"
            ),
        }

    if observed_prefixes:
        # Recognizable production IDs from a DIFFERENT course → stale.
        return {
            "status": "stale",
            "reason": (
                f"chunks.jsonl carries IDs from a different course "
                f"(expected prefix {expected_prefix!r}, observed "
                f"{sorted(observed_prefixes.items(), key=lambda x: -x[1])[:3]})"
            ),
            "expected_prefix": expected_prefix,
            "observed_prefixes": observed_prefixes,
        }

    # No recognizable course prefix at all (synthetic / minimal test
    # fixture). No positive evidence of staleness — tolerate so we
    # don't fail closed on perfectly fine non-production inputs.
    return {
        "status": "fresh",
        "reason": (
            f"chunks.jsonl carries unrecognized IDs ({unrecognized}/"
            f"{inspected} lines) — no positive staleness evidence"
        ),
    }


def _resolve_libv2_root(explicit: Optional[str] = None) -> Path:
    """Phase 8 ST 3: resolve the LibV2 root directory used by Phase 6/7
    helpers (`_run_concept_extraction`, `_run_dart_chunking`,
    `_run_imscc_chunking`) when persisting per-course artifacts under
    ``<libv2_root>/courses/<course_slug>/``.

    Resolution chain (high → low priority):
        1. Explicit ``libv2_root`` kwarg (typically threaded by the
           workflow runner via ``inputs_from`` from
           ``workflow_params.libv2_root`` — see
           ``config/workflows.yaml::textbook_to_course`` and
           ``MCP/core/workflow_runner.py::_LEGACY_PHASE_PARAM_ROUTING``).
        2. ``ED4ALL_LIBV2_ROOT`` env var (deployment-level override —
           useful for ops topologies that mount LibV2 at a non-default
           location, e.g. Docker volume / NFS / ConfigMap).
        3. ``_PROJECT_ROOT / "LibV2"`` legacy default (unchanged from
           pre-Phase-8 behaviour — every existing run continues to write
           to the in-tree ``LibV2/`` directory).

    Returns a ``Path`` (existence is NOT enforced — callers create the
    target ``courses/<slug>/...`` subdir as needed). Empty / whitespace-
    only ``explicit`` argument falls through as if unset, mirroring the
    ``or ""`` → falsy treatment in the call sites.
    """
    if explicit:
        cand = explicit.strip() if isinstance(explicit, str) else ""
        if cand:
            return Path(cand)
    env_val = os.environ.get("ED4ALL_LIBV2_ROOT", "").strip()
    if env_val:
        return Path(env_val)
    # W0.3: honor the relocatable ``ED4ALL_HOME`` data root BEFORE the in-tree
    # default, matching the centralized precedence in
    # ``lib.paths.libv2_path`` (ED4ALL_LIBV2_ROOT > ED4ALL_HOME/libv2 >
    # repo-relative). The previous inline resolver ignored ``ED4ALL_HOME``
    # entirely, so an ``ED4ALL_HOME`` deployment archived a course under one
    # tree (``$ED4ALL_HOME/libv2`` via every other consumer's ``libv2_path``)
    # while these chunking/archival helpers wrote under another
    # (``_PROJECT_ROOT/LibV2``) — a split-brain across two trees for the same
    # course. We keep ``_PROJECT_ROOT`` as the bare default (so the legacy
    # in-tree behaviour is byte-identical when no env var is set).
    from lib.paths import ed4all_home as _ed4all_home  # noqa: PLC0415
    _home = _ed4all_home()
    if _home is not None:
        return _home / "libv2"
    return _PROJECT_ROOT / "LibV2"


def _project_synthesized_objectives_to_course_json(
    synthesized_objectives_path: Path,
    course_json_path: Path,
    *,
    course_code: str,
    course_title: str,
) -> Optional[Dict[str, Any]]:
    """Project ``synthesized_objectives.json`` to a packaging-shaped
    ``course.json`` at ``<project>/03_content_development/course.json``.

    Wave2-I3 (Finding 3 of plans/dispatch-7-execution-inspection-2026-05.md):
    closes ``PAGE_OBJECTIVES_PATH_MISSING`` blocker. The
    ``PageObjectivesValidator`` (``lib/validators/page_objectives.py:192-249``)
    auto-discovers ``content_dir / "course.json"`` and fails closed
    critical-severity when absent; ``package_multifile_imscc.package_imscc``
    has the same auto-discovery contract via ``load_canonical_objectives``
    (``Courseforge/scripts/generate_course.py:615-646``), which reads
    ``terminal_objectives`` + ``chapter_objectives``.

    Projection is idempotent: when ``course_json_path`` already exists
    (e.g. ``--reuse-objectives`` ran or Trainforge's ``_build_course_json``
    emitted), this function logs INFO and returns ``None`` without
    overwriting. Returns the on-disk dict on a fresh emit.

    Source-shape handling is defensive: ``synthesized_objectives.json``
    normally carries the Courseforge synthesized form
    (``terminal_objectives[]`` + ``chapter_objectives[]`` per
    ``MCP/tools/pipeline_tools.py::_plan_course_structure`` at line
    ~4948); the root ``CLAUDE.md`` ``--reuse-objectives`` doc says the
    runner normalizes the LibV2 archive form
    (``terminal_outcomes[]`` + ``component_objectives[]``) to the
    former on disk, but we handle both forms here so a hand-edited
    legacy file doesn't silently emit an empty course.json.

    Args:
        synthesized_objectives_path: Path to the input JSON
            (``01_learning_objectives/synthesized_objectives.json``).
        course_json_path: Path to the target packaging-shaped
            ``course.json`` (``03_content_development/course.json``).
        course_code: Stable course identifier (e.g. ``PHYS_101``).
        course_title: Human-readable course title.

    Returns:
        The emitted course.json dict on a fresh write, or ``None`` if
        the target already exists (idempotent skip) or the synthesized
        objectives file is missing / malformed.
    """
    if course_json_path.exists():
        logger.info(
            "_project_synthesized_objectives_to_course_json: target "
            "%s already exists; skipping idempotent emit.",
            course_json_path,
        )
        return None
    if not synthesized_objectives_path.exists():
        logger.warning(
            "_project_synthesized_objectives_to_course_json: synthesized "
            "objectives not found at %s; cannot emit course.json. "
            "PageObjectivesValidator will fail closed with "
            "PAGE_OBJECTIVES_PATH_MISSING at the packaging gate.",
            synthesized_objectives_path,
        )
        return None
    try:
        synthesized = json.loads(
            synthesized_objectives_path.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError) as exc:
        logger.warning(
            "_project_synthesized_objectives_to_course_json: failed to "
            "parse %s (%s); skipping course.json emit.",
            synthesized_objectives_path, exc,
        )
        return None
    if not isinstance(synthesized, dict):
        logger.warning(
            "_project_synthesized_objectives_to_course_json: %s did not "
            "parse to a dict (got %s); skipping course.json emit.",
            synthesized_objectives_path, type(synthesized).__name__,
        )
        return None

    # Defensive: accept three shapes for ``chapter_objectives``:
    # (1) the Courseforge synthesized list-of-groups form,
    # (2) the LibV2 archive form (``component_objectives``), and
    # (3) the vendor dict-of-lists form (Wave2b — see
    # ``_normalize_chapter_objectives_to_groups`` docstring).
    # ``terminal_objectives`` accepts both the Courseforge name and
    # the LibV2 ``terminal_outcomes`` alias.
    terminal = (
        synthesized.get("terminal_objectives")
        or synthesized.get("terminal_outcomes")
        or []
    )
    chapter_groups_raw = (
        synthesized.get("chapter_objectives")
        or synthesized.get("component_objectives")
        or []
    )
    chapter_groups = _normalize_chapter_objectives_to_groups(chapter_groups_raw)
    # The pre-emitted ``learning_outcomes`` flat list (Courseforge
    # form) is the canonical Trainforge-shaped roll-up. Reuse when
    # present; reconstruct from terminal + chapter otherwise so the
    # LibV2 archive form (which doesn't pre-emit the flat list)
    # still produces a usable course.json.
    learning_outcomes_raw = synthesized.get("learning_outcomes")
    if not isinstance(learning_outcomes_raw, list) or not learning_outcomes_raw:
        learning_outcomes_raw = []
        for t in terminal if isinstance(terminal, list) else []:
            if isinstance(t, dict):
                lo = dict(t)
                lo.setdefault("hierarchy_level", "terminal")
                learning_outcomes_raw.append(lo)
        for grp in chapter_groups:
            for c in grp.get("objectives") or []:
                if isinstance(c, dict):
                    lo = dict(c)
                    lo.setdefault("hierarchy_level", "chapter")
                    learning_outcomes_raw.append(lo)

    duration_weeks = synthesized.get("duration_weeks")

    course_json: Dict[str, Any] = {
        # Required by schemas/knowledge/course.schema.json + consumed by
        # Trainforge's load_course_outcomes.
        "course_code": course_code,
        "title": course_title,
        # PageObjectivesValidator (lib/validators/page_objectives.py:192-249)
        # auto-discovers content_dir / "course.json" then routes to
        # load_canonical_objectives (Courseforge/scripts/generate_course.py:615)
        # which reads these two keys verbatim.
        "terminal_objectives": list(terminal)
        if isinstance(terminal, list) else [],
        # Persist the normalized list-of-groups shape so
        # ``load_canonical_objectives`` (which reads ``chapter`` +
        # ``objectives`` keys per group) sees a uniform structure
        # across input shapes — the vendor dict-of-lists shape
        # previously emitted as a dict on disk and dropped every CO
        # silently at the downstream walk.
        "chapter_objectives": chapter_groups,
        # LibV2 course.json shape (schemas/knowledge/course.schema.json:32-87):
        # flat learning_outcomes[] with id/statement/hierarchy_level. Carries
        # bloom_level/bloom_verb/key_concepts/cognitive_domain when synthesizer
        # populated them so downstream Trainforge consumers (process_course
        # _build_course_json) keep parity with the synthesized payload.
        "learning_outcomes": learning_outcomes_raw,
        # Provenance: chunker_version mirrors course_manifest.json so
        # downstream Trainforge consumers don't graceful-degrade on a
        # missing version field.
        "chunker_version": _resolve_chunker_version(),
    }
    if duration_weeks is not None:
        course_json["duration_weeks"] = duration_weeks

    course_json_path.parent.mkdir(parents=True, exist_ok=True)
    course_json_path.write_text(
        json.dumps(course_json, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    logger.info(
        "_project_synthesized_objectives_to_course_json: emitted %s "
        "with %d terminal_objectives + %d chapter_objective groups + "
        "%d learning_outcomes (closes PAGE_OBJECTIVES_PATH_MISSING "
        "blocker; Wave2-I3).",
        course_json_path,
        len(course_json["terminal_objectives"]),
        len(course_json["chapter_objectives"]),
        len(course_json["learning_outcomes"]),
    )
    return course_json


def _resolve_chunker_version() -> str:
    """Resolve the chunker-schema-contract version stamped on chunkset
    sidecar manifests + ``course_manifest.json``.

    Migration drift (post-Phase-8 review): the ``ed4all-chunker``
    workspace package was folded back into ``Trainforge/chunker/``;
    ``importlib.metadata.version("ed4all-chunker")`` is no longer the
    source of truth. The field's semantics also shifted: it used to
    carry the Python-package release version (e.g. ``"0.1.0"``); it
    now carries the chunker-schema-contract version
    (``Trainforge.chunker.CHUNKER_SCHEMA_VERSION``, currently
    ``"v4"``) — bumped only when the emit shape or semantics change,
    decoupled from any Python-package release cadence.

    Returns the in-repo constant directly: the chunker now lives
    inside Trainforge so the import is a hot-path-cheap module
    attribute lookup. Both the chunkset sidecar schema (`schemas/
    library/chunkset_manifest.schema.json::chunker_version`) and the
    course manifest schema (`schemas/library/course_manifest.schema
    .json::chunker_version`) accept BOTH the old ``^\\d+\\.\\d+\\.\\d+``
    semver shape and the new ``^v\\d+$`` schema-version shape, so any
    pre-migration manifest on disk continues to validate.
    """
    return CHUNKER_SCHEMA_VERSION


def _resolve_extraction_contract() -> int:
    """Resolve the chunk-TEXT extraction-contract version stamped as
    ``extraction_contract`` on chunkset sidecar manifests +
    ``course_manifest.json``.

    ORTHOGONAL to ``_resolve_chunker_version`` (the emit-SHAPE contract):
    this integer versions the semantics of WHAT TEXT lands in a chunk's
    ``text`` field — the always-on
    ``Trainforge/parsers/html_content_parser.py::HTMLTextExtractor``
    contract (screen-reader-scaffolding suppression + structural
    delimiters). ``CHUNKER_SCHEMA_VERSION`` deliberately stays ``"v4"``
    across extraction-text changes, so this finer marker is what a
    provenance consumer (e.g. the tier-2 citation-anchoring floor gate)
    reads to tell whether a corpus was chunked under the CURRENT
    extraction-text contract vs. an earlier one. Returns the in-repo
    constant ``Trainforge.chunker.EXTRACTION_TEXT_CONTRACT_VERSION``.
    """
    return EXTRACTION_TEXT_CONTRACT_VERSION


# OP4: the on-disk LibV2 course-layout contract version stamped on every
# freshly emitted ``course_manifest.json`` (``library_format_version``). This
# is DISTINCT from ``libv2_version`` (the manifest-document schema version) and
# ``chunker_version`` (the chunk-emit contract). Starts at "1.0"; bump only when
# the course-directory layout / manifest contract changes in a way that requires
# a migration. The migration framework has SHIPPED as the ``libv2 migrate``
# subcommand (LibV2/tools/libv2/migrate.py — dry-run by default, ``--apply`` to
# execute, with the ``legacy -> 1.0`` baseline step registered); its ordered
# registry's target_version() tracks this constant (drift-guarded by
# LibV2/tools/libv2/tests/test_libv2_migrate_framework.py). See
# docs/operations/library-versioning.md for the upgrade CONTRACT.
LIBRARY_FORMAT_VERSION = "1.0"


def _normalize_license_field(license_note: Any) -> Optional[Dict[str, str]]:
    """Normalize the ``--license-note`` input into the manifest ``license``
    object (``schemas/library/course_manifest.schema.json::license``).

    B3: accepts either a plain string (the common CLI shape — the value of
    ``--license-note``, mapped to ``spdx_or_name``) or a pre-shaped dict
    carrying ``spdx_or_name`` / ``note``. Returns ``None`` when nothing usable
    is present so callers can omit the field entirely (absent ==
    byte-identical manifest).
    """
    if license_note is None:
        return None
    if isinstance(license_note, str):
        s = license_note.strip()
        return {"spdx_or_name": s} if s else None
    if isinstance(license_note, dict):
        out: Dict[str, str] = {}
        for key in ("spdx_or_name", "note"):
            val = license_note.get(key)
            if isinstance(val, str) and val.strip():
                out[key] = val.strip()
        return out or None
    return None


def _normalize_attribution_field(attribution: Any) -> Optional[Dict[str, str]]:
    """Normalize the ``--attribution`` input into the manifest ``attribution``
    object (``schemas/library/course_manifest.schema.json::attribution``).

    B3: accepts either a plain string (the common CLI shape — the value of
    ``--attribution``, mapped to ``statement``) or a pre-shaped dict carrying
    ``source_title`` / ``source_url`` / ``statement``. Returns ``None`` when
    nothing usable is present (absent == byte-identical manifest).
    """
    if attribution is None:
        return None
    if isinstance(attribution, str):
        s = attribution.strip()
        return {"statement": s} if s else None
    if isinstance(attribution, dict):
        out: Dict[str, str] = {}
        for key in ("source_title", "source_url", "statement"):
            val = attribution.get(key)
            if isinstance(val, str) and val.strip():
                out[key] = val.strip()
        return out or None
    return None


def _write_course_notice(
    course_dir: Path,
    slug: str,
    course_title: Optional[str],
    license_field: Optional[Dict[str, str]],
    attribution_field: Optional[Dict[str, str]],
) -> Optional[Path]:
    """Write a human-readable ``NOTICE`` file into the course dir when a
    license or attribution declaration is present (B3).

    No-op (returns ``None``) when neither field is present — so an archival
    call without ``--license-note`` / ``--attribution`` leaves the course dir
    byte-identical to the pre-B3 layout. The NOTICE is a plain-text
    redistribution/attribution record intended to ship alongside a bundled
    course (e.g. the demo bundle). Written atomically.
    """
    if not license_field and not attribution_field:
        return None

    heading = f"NOTICE — {course_title or slug}"
    lines: List[str] = [heading, "=" * len(heading), ""]
    lines.append(f"Course: {course_title or slug}")
    lines.append(f"Slug: {slug}")
    lines.append("")

    if license_field:
        lines.append("License")
        lines.append("-------")
        name = license_field.get("spdx_or_name")
        if name:
            lines.append(name)
        note = license_field.get("note")
        if note:
            lines.append(note)
        lines.append("")

    if attribution_field:
        lines.append("Attribution")
        lines.append("-----------")
        title = attribution_field.get("source_title")
        if title:
            lines.append(f"Source: {title}")
        url = attribution_field.get("source_url")
        if url:
            lines.append(f"URL: {url}")
        statement = attribution_field.get("statement")
        if statement:
            lines.append(statement)
        lines.append("")

    lines.append(
        "This NOTICE was generated automatically at archive time from the "
        "license/attribution metadata recorded in course_manifest.json. "
        "Redistribute this file with the course bundle."
    )

    notice_path = course_dir / "NOTICE"
    _atomic_write_text(notice_path, "\n".join(lines).rstrip() + "\n")
    return notice_path


def _normalize_chapter_objectives_to_groups(raw: Any) -> List[Dict[str, Any]]:
    """Normalize ``chapter_objectives`` (any shape) to the canonical
    list-of-groups form: ``[{"chapter": <label>, "objectives": [...]}, ...]``.

    Wave2b (``plans/wave2-smoke-verification-2026-05.md`` "Surprises"):
    a vendor dict-of-lists-shaped ``synthesized_objectives.json`` carries
    ``chapter_objectives`` as a dict-of-lists keyed on chapter labels
    (e.g. ``{"1": [...], "2": [...]}``). Both Wave 2 helpers
    (``_project_synthesized_objectives_to_course_json`` from Wave2-I3
    + ``_collect_lo_ids`` inside ``_plan_course_structure`` from
    Wave2-I7) previously handled only the list-of-groups form and the
    flat-list form; the dict-of-lists branch silently dropped every
    CO-NN id from the projection + the ``objective_ids`` rollup.
    Normalizing once here keeps both call sites byte-stable on the
    legacy shapes and adds the dict-of-lists branch.

    Accepts three shapes:

    1. **List-of-groups** (Courseforge synthesized form, the canonical
       on-disk shape emitted by ``_plan_course_structure``):
       ``[{"chapter": N, "objectives": [{"id": "CO-NN", ...}, ...]}, ...]``.
       Returned verbatim.
    2. **Flat list** (LibV2 archive ``component_objectives`` form when
       not pre-grouped): ``[{"id": "CO-NN", "chapter": <opt>, ...}, ...]``.
       Wrapped in a single synthetic group keyed
       ``chapter="(ungrouped)"`` so the downstream walk still yields
       every CO-NN id.
    3. **Dict-of-lists** (vendor dict-of-lists shape):
       ``{"1": [{"id": "CO-NN", ...}, ...], "2": [...], ...}``.
       Iterates keys in sorted order so the emitted group ordering is
       deterministic across runs; each value becomes the
       ``objectives`` array of a group whose ``chapter`` is the dict
       key.

    Any other shape returns ``[]`` — caller's responsibility to log
    + degrade gracefully.
    """
    if isinstance(raw, dict):
        groups: List[Dict[str, Any]] = []
        for chapter_key in sorted(raw.keys(), key=str):
            items = raw[chapter_key]
            if not isinstance(items, list):
                continue
            objectives: List[Dict[str, Any]] = []
            for item in items:
                if isinstance(item, dict):
                    objectives.append(dict(item))
            groups.append({
                "chapter": str(chapter_key),
                "objectives": objectives,
            })
        return groups
    if isinstance(raw, list):
        groups = []
        flat_buffer: List[Dict[str, Any]] = []
        for entry in raw:
            if not isinstance(entry, dict):
                continue
            if isinstance(entry.get("objectives"), list):
                # List-of-groups shape — preserve group dict verbatim,
                # but coerce ``objectives`` entries to plain dicts.
                inner = [
                    dict(obj)
                    for obj in entry.get("objectives") or []
                    if isinstance(obj, dict)
                ]
                groups.append({
                    "chapter": entry.get("chapter"),
                    "objectives": inner,
                })
            else:
                # Flat-list shape — collect into a single synthetic group.
                flat_buffer.append(dict(entry))
        if flat_buffer:
            groups.append({
                "chapter": "(ungrouped)",
                "objectives": flat_buffer,
            })
        return groups
    return []


def _assign_terminal_objectives_to_weeks(
    terminal_objectives: List[Dict[str, Any]],
    duration_weeks: int,
) -> Dict[int, List[Dict[str, Any]]]:
    """Map each 1-based week → the terminal objective(s) it teaches.

    Finding 11 fix. The legacy per-week slice
    ``terminal_objectives[(w-1)*step : (w-1)*step + step]`` with
    ``step = ceil(num_tos / weeks)`` leaves TRAILING weeks objective-less
    whenever ``num_tos < weeks`` (e.g. 9 TOs over a pinned ``--weeks 12``
    yields ``step = 1`` so weeks 10/11/12 slice the empty tail and ship an
    empty objectives block). This helper guarantees **every** week in
    ``range(1, weeks + 1)`` carries at least one TO:

    * ``weeks <= num_tos`` — contiguous ceil-stride slice (the legacy
      shape; every week claims ``step`` TOs, no TO dropped).
    * ``weeks > num_tos`` — round-robin wrap so each TO is reused across
      the surplus weeks (week ``w`` → ``TO[(w-1) % num_tos]``); no week is
      left empty and every TO still appears.

    Pure / deterministic. Returns ``{}`` when there are no TOs (the caller
    falls back to its chapter-objective / topic path).
    """
    weeks = max(1, int(duration_weeks))
    tos = [t for t in (terminal_objectives or []) if isinstance(t, dict)]
    n = len(tos)
    if n == 0:
        return {}
    assignment: Dict[int, List[Dict[str, Any]]] = {}
    if weeks <= n:
        step = max(1, (n + weeks - 1) // weeks)  # ceil-stride
        for w in range(1, weeks + 1):
            start = (w - 1) * step
            week_slice = tos[start:start + step]
            # The last week absorbs any TOs the ceil-stride leaves unplaced
            # past its slice end (guards num_tos not divisible by weeks).
            if w == weeks and start + step < n:
                week_slice = tos[start:]
            assignment[w] = list(week_slice) if week_slice else [tos[-1]]
    else:
        # More weeks than TOs: round-robin so no week is objective-less.
        for w in range(1, weeks + 1):
            assignment[w] = [tos[(w - 1) % n]]
    return assignment


def _build_objectives_section_html(
    *,
    objective_lis: str,
    page_type: str,
    page_tos: Optional[List[Dict[str, Any]]] = None,
    page_cos: Optional[List[Dict[str, Any]]] = None,
) -> str:
    """Finding 11 + 18 — render the rewrite-tier page objectives ``<section>``.

    Returns the empty string (OMIT the block) when the page carries NO
    objectives (``objective_lis`` empty AND no TO records) — a week whose
    objective slice is empty must NOT render a blank ``Objectives`` heading
    over an empty ``<ul>`` (Finding 11). When present:

    * an OVERVIEW page with ≥1 terminal-objective record enumerates the TO
      AND all its child COs (each with its statement) via the shared
      ``render_objective_list`` builder (Finding 18);
    * every other page keeps the compact ``<ul>`` of the page's objective ids.

    Pure / deterministic / fail-soft: a ``render_objective_list`` failure
    falls back to the compact ``<ul>``; the function never raises.
    """
    _lis = (objective_lis or "").strip()
    _tos = list(page_tos or [])
    # Finding 11: nothing to render → OMIT the block entirely (no blank heading).
    if not _lis and not _tos:
        return ""
    section = (
        f'<section class="objectives"><h2>Objectives</h2>'
        f'<ul>{objective_lis}</ul></section>'
    )
    if page_type == "overview" and _tos:
        try:
            from lib.objectives.lo_map_builder import (  # noqa: PLC0415
                render_objective_list,
            )

            _obj_list_html = render_objective_list(
                _tos, list(page_cos or []), heading_level=3,
            )
            if _obj_list_html and _obj_list_html.strip():
                section = (
                    f'<section class="objectives"><h2>Objectives</h2>'
                    f"{_obj_list_html}</section>"
                )
        except Exception as _ol_exc:  # noqa: BLE001 — keep the legacy <ul>
            logger.warning(
                "objectives section: render_objective_list failed (%s); "
                "falling back to the compact objectives <ul>.", _ol_exc,
            )
    return section


_PAGE_TYPE_LABELS: Dict[str, str] = {
    "overview": "Overview",
    "content": "Core Concepts",
    "application": "Applying the Skills",
    "self_check": "Check Your Understanding",
    "summary": "Summary",
    # Feature I5 — deterministic per-TO "Key Terms" page (opt-in via
    # ED4ALL_KEY_TERMS_PAGE; default OFF keeps the five-type list intact).
    "key_terms": "Key Terms",
    # W6.4 — deterministic per-week "FAQ" page (opt-in via ED4ALL_FAQ_PAGE;
    # default OFF keeps the five-type list intact). Builder + renderer are
    # owned by Lane B (lib/generation/faq_page.py + generate_course.py); this
    # is the page-type REGISTRATION half.
    "faq": "Frequently Asked Questions",
}

_PAGE_ID_TYPE_RE = re.compile(
    r"^week[_-]?\d+(?:_(?P<ptype>overview|content|application|self_check|summary|key_terms|faq))?",
    re.IGNORECASE,
)


def _humanize_page_title(
    page_id: str,
    week_num: int,
    page_type: str,
    week_objectives: Optional[List[Dict[str, Any]]] = None,
) -> str:
    """Finding 9 — derive a human page ``<h1>`` from the week's TO/topic.

    The legacy ``<h1>`` was the raw ``page_id`` (e.g. ``"week_01_summary"``).
    Instead, build ``"Week N: <human-label>"`` where the label is the week's
    leading terminal-objective statement (trimmed to a phrase) when available,
    else the page-type's friendly label. Deterministic; never raises.
    """
    label = _PAGE_TYPE_LABELS.get(page_type, "")
    _to_stmt = ""
    for _obj in week_objectives or []:
        if isinstance(_obj, dict):
            _s = _obj.get("statement")
            if isinstance(_s, str) and _s.strip():
                _to_stmt = _s.strip()
                break
    if _to_stmt:
        # Trim a long objective statement to a leading phrase (first clause).
        _phrase = re.split(r"[.;:]", _to_stmt, maxsplit=1)[0].strip()
        if len(_phrase) > 80:
            _phrase = _phrase[:77].rstrip() + "…"
        # The overview/summary frame the whole week's TO; content/application/
        # self_check append the page-type label so siblings stay distinct.
        if page_type in ("overview", "summary") or not label:
            label = _phrase
        else:
            label = f"{_phrase} — {label}"
    if not label:
        # Last-resort: a humanized page_id (never the raw snake-case id).
        label = page_id.replace("_", " ").strip().title() or page_id
    return f"Week {week_num}: {label}"


def _ws5_resolve_objective_weeks(
    num_tos: int,
    num_cos: int,
    duration_weeks: int,
    duration_explicit: bool,
    mint_method: str,
) -> int:
    """WS5 §3.2 — resolve the objective-driven course duration in weeks.

    Single-sourced pacing formula consumed by ``_plan_course_structure`` (and
    directly testable). After WS1's clustering, ``num_tos`` is the genuine
    ~8-12 terminal-objective / theme count — the authoritative pacing signal:
    one week-block per TO, floored at 8. The COs then distribute WITHIN each
    TO's block via the §2.2 coverage-safe ceil-stride slicer, so no grounded CO
    is dropped regardless of week count.

    Override guards (preserved verbatim from the Wave-1.8 rescale):

    * ``duration_explicit`` (``--weeks N`` passed) → operator pacing wins; the
      supplied ``duration_weeks`` is returned unchanged (no rescale).
    * ``mint_method == "user_supplied_objectives_json"`` (``--reuse-objectives``)
      → the hand-curated LO list pre-encodes pacing; return unchanged.

    Resolution when neither guard fires:

    * ``num_tos > 0`` → ``max(8, num_tos)`` (one week-block per TO).
    * else if ``WAVE18_COS_PER_WEEK > 0`` and ``num_cos`` → legacy CO-count
      fallback ``max(8, ceil(num_cos / WAVE18_COS_PER_WEEK))``.
    * else → ``duration_weeks`` (no signal to rescale on).

    ``WAVE18_COS_PER_WEEK`` is REPURPOSED to the within-theme CO-distribution /
    legacy fallback divisor — it is no longer the primary week divisor when
    WS1 supplies real TOs.
    """
    if duration_explicit or mint_method == "user_supplied_objectives_json":
        return duration_weeks
    try:
        cos_per_week = int(os.environ.get("WAVE18_COS_PER_WEEK", "2") or "2")
    except (TypeError, ValueError):
        cos_per_week = 2
    if num_tos > 0:
        return max(8, num_tos)
    if cos_per_week > 0 and num_cos > 0:
        return max(8, (num_cos + cos_per_week - 1) // cos_per_week)
    return duration_weeks


def _normalize_objectives_payload_to_course(
    payload: Any,
    course_code: str,
) -> Tuple[Optional[Dict[str, Any]], Optional[List[Dict[str, Any]]]]:
    """Normalize an objectives doc to the ``course.json`` graph-input shape.

    NVIDIA-KG item 1: ``build_semantic_graph``'s LO-dependent rules need a
    ``course`` dict carrying ``learning_outcomes: [{"id": "TO-NN"|"CO-NN",
    ...}, ...]`` in canonical order (the list POSITION is the LO-ordering
    signal ``prerequisite_from_lo_order::_lo_order_map`` consumes). This
    helper accepts any of:

    1. The canonical Trainforge ``course.json`` form — non-empty flat
       ``learning_outcomes[]`` (``schemas/knowledge/course.schema.json``).
       Used verbatim (order preserved).
    2. The Courseforge synthesized form — ``terminal_objectives[]`` +
       ``chapter_objectives`` (any of the three shapes handled by
       :func:`_normalize_chapter_objectives_to_groups`). Flattened
       terminal-first then chapter-groups in document order — the same
       canonical order :func:`_project_synthesized_objectives_to_course_json`
       emits.
    3. The LibV2 archive aliases — ``terminal_outcomes[]`` +
       ``component_objectives``.

    LO identity is validated via the canonical
    ``lib.ontology.learning_objectives.validate_lo_id`` helper (no local
    re-derivation of the ID pattern); entries with missing / non-canonical
    IDs are dropped. Duplicate IDs keep the first occurrence so the
    ordering signal stays stable.

    Also derives the ``objectives_metadata`` list consumed by the
    ``targets_concept_from_lo`` rule: one ``{"id", "targetedConcepts":
    [{"concept", "bloomLevel"}]}`` entry per LO that carries
    ``key_concepts`` — mirroring the canonical Courseforge JSON-LD emit
    (``Courseforge/scripts/blocks.py::Block._objective_jsonld`` slugifies
    ``key_terms`` and stamps the LO's Bloom level). Bloom level resolution:
    explicit ``bloom_level`` when canonical, else
    ``lib.ontology.bloom.detect_bloom_level`` over the statement, else the
    neutral ``_FALLBACK_BLOOM_LEVEL`` ("apply") with a logged warning — so an
    LO that carries key_concepts but no resolvable Bloom level still
    contributes its targetedConcepts instead of being silently dropped. LOs
    without concepts contribute no entry.

    Returns:
        ``(course, objectives_metadata)`` — both ``None`` when the payload
        yields zero canonical LOs. ``objectives_metadata`` may be ``None``
        while ``course`` is populated (no key_concepts anywhere).
    """
    from lib.ontology.bloom import BLOOM_LEVELS, detect_bloom_level
    from lib.ontology.learning_objectives import validate_lo_id
    from lib.ontology.slugs import canonical_slug

    if not isinstance(payload, dict):
        return None, None

    lo_entries_raw: List[Dict[str, Any]] = []
    flat = payload.get("learning_outcomes")
    if isinstance(flat, list) and flat:
        lo_entries_raw = [dict(e) for e in flat if isinstance(e, dict)]
    else:
        terminal = (
            payload.get("terminal_objectives")
            or payload.get("terminal_outcomes")
            or []
        )
        chapter_raw = (
            payload.get("chapter_objectives")
            or payload.get("component_objectives")
            or []
        )
        for t in terminal if isinstance(terminal, list) else []:
            if isinstance(t, dict):
                entry = dict(t)
                entry.setdefault("hierarchy_level", "terminal")
                lo_entries_raw.append(entry)
        for group in _normalize_chapter_objectives_to_groups(chapter_raw):
            for c in group.get("objectives") or []:
                if isinstance(c, dict):
                    entry = dict(c)
                    entry.setdefault("hierarchy_level", "chapter")
                    lo_entries_raw.append(entry)

    canonical_levels = set(BLOOM_LEVELS)
    learning_outcomes: List[Dict[str, Any]] = []
    objectives_metadata: List[Dict[str, Any]] = []
    seen_ids: set = set()
    for entry in lo_entries_raw:
        lo_id = str(entry.get("id") or "").strip().upper()
        if not validate_lo_id(lo_id) or lo_id in seen_ids:
            continue
        seen_ids.add(lo_id)
        normalized = dict(entry)
        normalized["id"] = lo_id
        learning_outcomes.append(normalized)

        # targets-concept metadata (best-effort per LO).
        statement = str(
            entry.get("statement") or entry.get("description") or ""
        )
        key_concepts = entry.get("key_concepts") or entry.get("keyConcepts")
        if not isinstance(key_concepts, list) or not key_concepts:
            continue
        bloom_level = str(entry.get("bloom_level") or "").strip().lower()
        if bloom_level not in canonical_levels:
            bloom_level, _verb = detect_bloom_level(statement)  # type: ignore[assignment]
        if not bloom_level or bloom_level not in canonical_levels:
            # Neither an explicit canonical level nor a detectable verb. Rather
            # than drop the LO's targetedConcepts (and the targets-concept edges
            # that depend on them), fall back to a neutral default level. Loud
            # warning so an audit can see which LOs took the fallback.
            logger.warning(
                "objectives normalize: LO %s has no resolvable bloom_level "
                "(statement=%r, key_concepts=%d); falling back to %r so its "
                "targetedConcepts are not dropped",
                lo_id,
                statement[:80],
                len(key_concepts),
                _FALLBACK_BLOOM_LEVEL,
            )
            bloom_level = _FALLBACK_BLOOM_LEVEL
        targeted = [
            {"concept": canonical_slug(str(c)), "bloomLevel": bloom_level}
            for c in key_concepts
            if isinstance(c, str) and canonical_slug(c)
        ]
        if targeted:
            objectives_metadata.append(
                {"id": lo_id, "targetedConcepts": targeted}
            )

    if not learning_outcomes:
        return None, None
    course: Dict[str, Any] = {
        "course_id": course_code,
        "course_code": payload.get("course_code") or course_code,
        "learning_outcomes": learning_outcomes,
    }
    return course, (objectives_metadata or None)


def _resolve_course_objectives_for_graph(
    *,
    objectives_path_kw: str = "",
    synthesized_objectives_path_kw: str = "",
    project_path: Optional[Path] = None,
    libv2_course_dir: Optional[Path] = None,
    course_code: str = "",
) -> Tuple[Optional[Dict[str, Any]], Optional[List[Dict[str, Any]]], str]:
    """Resolve + normalize the course objectives doc for the semantic graph.

    Resolution chain (first parseable candidate that yields >=1 canonical
    LO wins):

    1. ``objectives_path_kw`` — explicit kwarg, routed from the
       ``reuse_objectives_path`` workflow param via the
       ``concept_extraction`` phase's ``inputs_from`` block. A reuse run
       pins the LO-dependent typed-edge rules to the operator's verbatim
       objectives doc.
    2. ``synthesized_objectives_path_kw`` — the
       ``synthesized_objectives.json`` emitted by ``course_planning``,
       routed via the ``concept_extraction`` phase's ``inputs_from``
       block. Phase-ordering fix (Option A1): ``concept_extraction`` now
       runs AFTER ``course_planning``, so this candidate exists on a
       FRESH ``textbook_to_course`` run (objectives are minted in the
       prior phase) — it is the fresh-run objectives source.
    3. ``<project export>/01_learning_objectives/synthesized_objectives.json``
       — present on re-runs / Phase-5 stage subcommands (also where
       candidate #2 normally points; kept as a path-independent fallback).
    4. ``<project export>/03_content_development/course.json`` — the
       packaging-shaped projection emitted by
       :func:`_project_synthesized_objectives_to_course_json`.
    5. ``LibV2/courses/<slug>/course.json`` — the canonical
       Trainforge-archived form.

    Fail-soft by contract: unreadable / malformed / LO-less candidates log
    a warning and fall through; an empty chain returns ``(None, None, "")``
    so the caller degrades to the legacy ``course=None`` build.

    Returns:
        ``(course, objectives_metadata, resolved_source_path)``.
    """
    candidates: List[Path] = []
    if objectives_path_kw:
        candidates.append(Path(objectives_path_kw))
    if synthesized_objectives_path_kw:
        candidates.append(Path(synthesized_objectives_path_kw))
    if project_path is not None:
        candidates.append(
            project_path / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        candidates.append(
            project_path / "03_content_development" / "course.json"
        )
    if libv2_course_dir is not None:
        candidates.append(libv2_course_dir / "course.json")

    for cand in candidates:
        if not cand.is_file():
            continue
        try:
            payload = json.loads(cand.read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            logger.warning(
                "concept_extraction: objectives candidate %s is unreadable "
                "or malformed (%s); trying next candidate.",
                cand, exc,
            )
            continue
        course, objectives_metadata = _normalize_objectives_payload_to_course(
            payload, course_code,
        )
        if course is None:
            logger.warning(
                "concept_extraction: objectives candidate %s parsed but "
                "yielded zero canonical learning outcomes; trying next "
                "candidate.",
                cand,
            )
            continue
        return course, objectives_metadata, str(cand)
    return None, None, ""


_BLOOM_TO_DIFFICULTY: Dict[str, str] = {
    "remember": "foundational",
    "understand": "foundational",
    "apply": "intermediate",
    "analyze": "intermediate",
    "evaluate": "advanced",
    "create": "advanced",
}

# Resource types that cap difficulty at "foundational" (overviews / summaries
# never sit at advanced). Mirrors
# ``Trainforge/process_course.py::INTRODUCTORY_RESOURCE_TYPES``.
_INTRODUCTORY_RESOURCE_TYPES = {"overview", "summary"}


def _resolve_chunk_bloom_level(
    item: Dict[str, Any],
    text: str,
) -> Tuple[str, str]:
    """Resolve ``bloom_level`` for a chunk via the canonical cascade.

    Returns a ``(bloom_level, bloom_source)`` tuple. ``bloom_source`` is one
    of ``page_jsonld`` / ``lo_inherited`` / ``verbs`` / ``default`` (mirroring
    the values in ``schemas/knowledge/chunk_v4.schema.json::bloom_level_source``).
    The two highest-fidelity sources from the schema cascade
    (``section_jsonld`` and the per-section JSON-LD ``blocks[]`` match) are
    not reachable from this stripped-down callback — the chunking phase's
    parsed_item dict carries page-level ``courseforge_metadata`` but no
    section-keyed metadata index — so this helper picks up the cascade at
    ``page_jsonld`` and below. Callers that need section-level granularity
    should still go through ``CourseProcessor._create_chunk``.

    Cascade:
      1. ``item["courseforge_metadata"]["learningObjectives"][*]["bloomLevel"]``
         (page-level JSON-LD; first non-empty wins).
      2. ``item["learning_objectives"][*].bloom_level`` (parsed LO objects;
         falls through ``LearningObjective.bloom_level``).
      3. Text-verb heuristic via ``lib.ontology.bloom.detect_bloom_level``.
      4. Hardcoded ``"understand"`` default (per the schema's documented
         resolution cascade).
    """
    # 1. Page-level JSON-LD learningObjectives[].bloomLevel.
    cf_meta = item.get("courseforge_metadata")
    if cf_meta:
        for lo in (cf_meta.get("learningObjectives") or []):
            bl = (lo or {}).get("bloomLevel")
            if isinstance(bl, str) and bl.strip():
                return (bl.strip().lower(), "page_jsonld")

    # 2. Parsed LearningObjective dataclass list. Each entry exposes
    #    ``.bloom_level`` (the parser normalizes JSON-LD camelCase /
    #    data-cf-bloom-level / regex matches to this snake_case field).
    for lo in (item.get("learning_objectives") or []):
        bl = getattr(lo, "bloom_level", None)
        if bl is None and isinstance(lo, dict):
            bl = lo.get("bloom_level")
        if isinstance(bl, str) and bl.strip():
            return (bl.strip().lower(), "lo_inherited")

    # 3. Verb heuristic via the canonical detector.
    try:
        from lib.ontology.bloom import detect_bloom_level
    except Exception:  # noqa: BLE001 — import guard mirrors other lazy imports
        detect_bloom_level = None  # type: ignore[assignment]
    if detect_bloom_level is not None:
        level, _verb = detect_bloom_level(text or "")
        if level:
            return (level, "verbs")

    # 4. Default per the schema cascade.
    return ("understand", "default")


def _resolve_chunk_difficulty(
    item: Dict[str, Any],
    text: str,
    bloom_level: Optional[str] = None,
) -> str:
    """Resolve ``difficulty`` for a chunk via the canonical cascade.

    Mirrors ``Trainforge/process_course.py::_determine_difficulty``. Returns
    one of the chunk_v4 enum values: ``foundational`` / ``intermediate`` /
    ``advanced``.

    Cascade:
      1. JSON-LD ``learningObjectives[].bloomLevel`` via ``_BLOOM_TO_DIFFICULTY``
         (first hit wins).
      2. Parsed ``LearningObjective.bloom_level`` via ``_BLOOM_TO_DIFFICULTY``.
      3. Already-resolved ``bloom_level`` argument via ``_BLOOM_TO_DIFFICULTY``
         (the chunk's own bloom_level — closes the loop for chunks where
         the bloom signal came from the verb heuristic).
      4. Keyword heuristic over chunk text (introductory verbs ->
         foundational, advanced verbs -> advanced, else intermediate).

    Introductory resource types (``overview`` / ``summary``) cap at
    ``foundational`` regardless of cascade.
    """
    difficulty: Optional[str] = None

    # 1. Page-level JSON-LD learningObjectives.
    cf_meta = item.get("courseforge_metadata")
    if cf_meta:
        for lo in (cf_meta.get("learningObjectives") or []):
            bl = (lo or {}).get("bloomLevel")
            if isinstance(bl, str) and bl.strip().lower() in _BLOOM_TO_DIFFICULTY:
                difficulty = _BLOOM_TO_DIFFICULTY[bl.strip().lower()]
                break

    # 2. Parsed LearningObjective list.
    if difficulty is None:
        for lo in (item.get("learning_objectives") or []):
            bl = getattr(lo, "bloom_level", None)
            if bl is None and isinstance(lo, dict):
                bl = lo.get("bloom_level")
            if isinstance(bl, str) and bl.strip().lower() in _BLOOM_TO_DIFFICULTY:
                difficulty = _BLOOM_TO_DIFFICULTY[bl.strip().lower()]
                break

    # 3. Resolved bloom_level (closes the loop for verb-heuristic chunks).
    if (
        difficulty is None
        and isinstance(bloom_level, str)
        and bloom_level.strip().lower() in _BLOOM_TO_DIFFICULTY
    ):
        difficulty = _BLOOM_TO_DIFFICULTY[bloom_level.strip().lower()]

    # 4. Keyword heuristic over chunk text.
    if difficulty is None:
        text_lower = (text or "").lower()
        if any(
            kw in text_lower
            for kw in ("basic", "introduction", "overview", "what is", "define")
        ):
            difficulty = "foundational"
        elif any(
            kw in text_lower
            for kw in ("evaluate", "create", "design", "critique", "justify")
        ):
            difficulty = "advanced"
        else:
            difficulty = "intermediate"

    # Cap introductory resource types.
    if item.get("resource_type") in _INTRODUCTORY_RESOURCE_TYPES:
        if difficulty == "advanced":
            difficulty = "intermediate"
        elif difficulty == "intermediate":
            difficulty = "foundational"

    return difficulty


# Canonical sourceId shape: dart:{slug}#{block_id} (lowercase slug + block;
# mirrors schemas/knowledge/source_reference.schema.json). The validator owns
# the canonical pattern + the slug-derivation rule; we import both rather than
# re-spell them so the emitter and the source_refs validator can never drift
# (MCP/tools depending on lib/validators is the allowed layering direction).
# Used to drop any harvested block whose minted id wouldn't validate so a
# malformed DART attribute can't poison a chunk's source_references[].
from lib.validators.source_refs import (
    SOURCE_ID_RE as _DART_SOURCE_ID_RE,
    semantik_slug_from_filename as _semantik_slug_from_filename,
)


# SemantiK migration §4 — enrichment enums + figure-alt recovery for the
# INLINE chunk emitters (``_run_dart_chunking`` / the IMSCC sibling). These
# mirror the canonical P2b ``CourseProcessor`` constants + ``_recover_figure_alt``
# so the inline chunk path stamps the SAME 6 chunk-root fields. Kept here (not
# imported from process_course) so the inline path has no CourseProcessor
# instance dependency.
_SEMANTIK_WCAG_BLOCK_STATUSES = frozenset({"passed", "flagged", "skipped"})


def _emit_irt_difficulty_calibration_event(
    *,
    chunks: List[Dict[str, Any]],
    course_code: str,
    phase: str,
    calibrated_map: Optional[Dict[str, Any]],
    response_present: bool,
) -> None:
    """Emit exactly one ``difficulty_calibration`` decision event for an
    IRT-scaffold chunk-emit run (the DART ``_run_dart_chunking`` + IMSCC
    ``_run_imscc_chunking`` paths).

    Mirrors the canonical ``Trainforge.process_course.CourseProcessor.
    _maybe_add_difficulty_descriptor`` emit so the
    ``TRAINFORGE_IRT_DIFFICULTY_SCAFFOLD`` flag-row claim ("emitted ... by the
    chunk-emit path") is TRUE for the pipeline_tools chunk emitters too. The
    rationale interpolates the run's dynamic signals (chunks tagged, the
    calibrated-vs-heuristic split, the min-responses floor, whether a learner-
    response seam file was present). Best-effort — any failure is logged at
    debug and never breaks chunk emit. The caller guards on ``_irt_enabled`` so
    this is never reached on the byte-stable flag-off path.
    """
    try:
        from lib.assessment.irt_difficulty import (
            DEFAULT_MIN_RESPONSES,
            DIFFICULTY_PROVENANCE_CALIBRATED,
            describe_difficulty_distribution,
        )
        from lib.decision_capture import DecisionCapture

        total = len(chunks)
        counts: Dict[str, int] = {}
        calibrated_count = 0
        for _ch in chunks:
            _band = _ch.get("difficulty")
            if isinstance(_band, str) and _band:
                counts[_band] = counts.get(_band, 0) + 1
            if _ch.get("difficulty_provenance") == DIFFICULTY_PROVENANCE_CALIBRATED:
                calibrated_count += 1
        calibrated_fraction = (calibrated_count / total) if total else 0.0
        descriptor = describe_difficulty_distribution(counts, calibrated_fraction)
        capture = DecisionCapture(
            course_code=course_code,
            phase=phase,
            tool="trainforge",
        )
        capture.log_decision(
            decision_type="difficulty_calibration",
            decision=f"provenance={descriptor['provenance']}",
            rationale=(
                f"IRT difficulty scaffold ({phase}): chunks_tagged={total}, "
                f"calibrated_chunk_count={calibrated_count}, "
                f"heuristic_chunk_count={total - calibrated_count}, "
                f"calibrated_fraction={calibrated_fraction:.4f}, "
                f"calibrated_item_count={len(calibrated_map or {})}, "
                f"response_file_present={response_present}, "
                f"min_responses={DEFAULT_MIN_RESPONSES}, "
                f"modal_level={descriptor['modal_level']}."
            ),
        )
    except Exception as exc:  # noqa: BLE001 — capture must never break chunking
        logger.debug("difficulty_calibration decision capture failed: %s", exc)


def _recover_figure_alt(html: str) -> Optional[str]:
    """Best-effort DOM-side recovery of a figure chunk's alt / caption (§4).

    Prefers a ``<figcaption>`` text, falling back to an ``<img alt="...">``
    value. Returns ``None`` when neither resolves (anti-fabrication — never
    invents alt text). Pure regex; no bs4 dependency added. Byte-identical to
    ``Trainforge.process_course.CourseProcessor._recover_figure_alt``.
    """
    if not html:
        return None
    cap = re.search(
        r"<figcaption\b[^>]*>(.*?)</figcaption>",
        html,
        re.IGNORECASE | re.DOTALL,
    )
    if cap:
        text = re.sub(r"<[^>]+>", " ", cap.group(1))
        text = " ".join(text.split()).strip()
        if text:
            return text
    alt = re.search(
        r"<img\b[^>]*\balt\s*=\s*([\"'])(.*?)\1",
        html,
        re.IGNORECASE | re.DOTALL,
    )
    if alt:
        text = " ".join(alt.group(2).split()).strip()
        if text:
            return text
    return None


def _semantik_block_source_references(
    dart_source_refs: Optional[List[Dict[str, Any]]],
    slug: str,
) -> List[Dict[str, Any]]:
    """Mint canonical SourceReference dicts from harvested SemantiK block refs.

    ``dart_source_refs`` (the load-bearing create_chunk callback kwarg name)
    is the chunker's harvest output — an ordered list of
    ``{"block_id": str, "pages": List[int]}`` pairs read off
    ``data-semantik-block-id`` / ``data-semantik-pages`` attributes (legacy
    corpora carry the ``data-dart-*`` spelling, dual-read; see
    ``Trainforge.chunker.helpers.harvest_semantik_source_refs``). ``slug`` is
    the staged-HTML file stem (passed as ``item["item_id"]`` by
    ``_run_dart_chunking``). We re-run the canonical
    ``semantik_slug_from_filename`` rule over it here — the multi-source
    strategy emits ``{stem}_synthesized.html``, so ``item_id`` can carry a
    trailing ``_synthesized`` that the source_refs validator + source-router
    strip when they key ``semantik:{slug}#...``. Stripping only at mint time
    keeps the sourceId join key resolvable WITHOUT mutating ``item_id``
    itself (it also flows into the chunk's ``module_id`` / ``lesson_id``,
    which must stay the literal file stem).

    Returns SourceReference dicts in the shape
    ``schemas/knowledge/source_reference.schema.json`` requires:
    ``{"sourceId": "semantik:{slug}#{block_id}", "role": "primary",
    "extractor": "synthesized", "pages": [N, ...]}``. ``role`` is
    ``primary`` — a chunk built from a SemantiK block IS that source. ``pages``
    is omitted when empty (schema requires ``pages`` items ``minimum: 1``).
    Any minted sourceId that fails the canonical pattern is dropped so a
    malformed attribute never produces an unresolvable ref.

    Returns ``[]`` when ``dart_source_refs`` or ``slug`` is empty — the
    additive contract: chunks from HTML without ``data-semantik-*`` attributes
    keep ``source.source_references`` unset (legacy corpora byte-stable).
    """
    if not dart_source_refs or not slug:
        return []
    # Canonicalize the slug (strip ``_synthesized``, lowercase, spaces→hyphens)
    # so minted sourceIds match the validator's / source-router's join keys on
    # real multi-source corpora; ``item_id`` itself is left untouched upstream.
    slug = _semantik_slug_from_filename(slug)
    if not slug:
        return []
    out: List[Dict[str, Any]] = []
    seen: set = set()
    for ref in dart_source_refs:
        if not isinstance(ref, dict):
            continue
        block_id = str(ref.get("block_id") or "").strip()
        if not block_id:
            continue
        source_id = f"semantik:{slug}#{block_id}"
        if source_id in seen or not _DART_SOURCE_ID_RE.match(source_id):
            continue
        seen.add(source_id)
        entry: Dict[str, Any] = {
            "sourceId": source_id,
            "role": "primary",
            "extractor": "synthesized",
        }
        pages = [int(p) for p in (ref.get("pages") or []) if int(p) > 0]
        if pages:
            entry["pages"] = sorted(set(pages))
        out.append(entry)
    return out


def _backfill_dart_chunk_lo_refs(
    *,
    course_slug: str,
    objective_ids: List[str],
    libv2_root: Optional[str] = None,
    objectives: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    """Wave3-Anew3 — back-fill ``learning_outcome_refs`` on DART chunks.

    Closes auditor Finding F3 of
    ``plans/dispatch-7-final-product-audit-2026-05.md``: the DART
    ``_run_dart_chunking`` phase emits chunks BEFORE
    ``_plan_course_structure`` synthesizes the TO-NN / CO-NN ID set, so
    every chunk's ``learning_outcome_refs[]`` is empty on initial emit.
    This helper runs after course planning publishes ``objective_ids``
    (Wave2-I7 plumbing), re-opens the on-disk chunks JSONL, text-scans
    each chunk's ``text`` + ``html`` for canonical LO IDs via
    :func:`lib.ontology.learning_objectives.scan_lo_refs`, and writes
    matches back into ``learning_outcome_refs`` — but only IDs that
    appear in ``objective_ids`` (the false-positive guard the brief
    mandates).

    Args:
        course_slug: Course slug used to locate
            ``<libv2>/courses/<slug>/dart_chunks/chunks.jsonl``.
        objective_ids: Allowlist of canonical TO-NN / CO-NN IDs minted
            by course planning. Empty list → no-op (cannot back-fill
            without an allowlist; preserves false-positive guard).
        libv2_root: Optional override for the LibV2 root; resolution
            chain follows :func:`_resolve_libv2_root`.
        objectives: Optional list of ``{"id", "statement"}`` dicts (the
            already-minted objective universe). When supplied AND
            ``ED4ALL_CHUNK_LO_HEURISTIC`` is truthy, an additive-only
            W1b.5 heuristic arm runs AFTER the exact ``scan_lo_refs``
            pass: chunks still carrying no refs are content-token-matched
            to an objective STATEMENT (existing-ids-only,
            ``only_when_empty=True``). Default ``None`` / flag off →
            byte-identical to the exact-scan-only baseline.

    Returns:
        Summary dict with ``chunks_path``, ``chunks_scanned``,
        ``chunks_updated``, ``new_refs_total``, and (when the chunks
        file is missing) ``skipped`` + ``reason``. When the heuristic
        arm runs it adds ``heuristic_chunks_linked`` +
        ``heuristic_refs_added``.

    Best-effort: missing chunks file / unreadable JSONL line / write
    error each emit a logger.warning and continue rather than crash the
    workflow. Existing non-empty ``learning_outcome_refs`` are preserved
    (additive union semantics — never destructive).
    """
    from lib.ontology.learning_objectives import scan_lo_refs

    if not objective_ids:
        return {
            "chunks_path": None,
            "chunks_scanned": 0,
            "chunks_updated": 0,
            "new_refs_total": 0,
            "skipped": True,
            "reason": "empty_objective_ids_allowlist",
        }

    # Dual-read the staged chunkset dir (semantik_chunks/ -> dart_chunks/ ->
    # corpus/) so a current course and an un-migrated archive both resolve.
    from lib.libv2_storage import resolve_staged_chunks_path
    chunks_path = resolve_staged_chunks_path(
        _resolve_libv2_root(libv2_root) / "courses" / course_slug
    )
    if not chunks_path.exists() or not chunks_path.is_file():
        return {
            "chunks_path": str(chunks_path),
            "chunks_scanned": 0,
            "chunks_updated": 0,
            "new_refs_total": 0,
            "skipped": True,
            "reason": "chunks_jsonl_missing",
        }

    allow = list(objective_ids)
    chunks_scanned = 0
    chunks_updated = 0
    new_refs_total = 0
    updated_lines: List[str] = []

    try:
        raw_lines = chunks_path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        logger.warning(
            "Wave3-Anew3: failed to read %s (%s); skipping LO back-fill.",
            chunks_path, exc,
        )
        return {
            "chunks_path": str(chunks_path),
            "chunks_scanned": 0,
            "chunks_updated": 0,
            "new_refs_total": 0,
            "skipped": True,
            "reason": f"read_error:{exc}",
        }

    for line in raw_lines:
        if not line.strip():
            updated_lines.append(line)
            continue
        try:
            chunk = json.loads(line)
        except (json.JSONDecodeError, ValueError) as exc:
            logger.warning(
                "Wave3-Anew3: malformed chunk JSONL line in %s (%s); "
                "preserving verbatim.",
                chunks_path, exc,
            )
            updated_lines.append(line)
            continue

        chunks_scanned += 1
        existing = chunk.get("learning_outcome_refs") or []
        existing_set = {str(r).upper() for r in existing if r}
        scanned = scan_lo_refs(
            text=chunk.get("text") or "",
            html=chunk.get("html") or "",
            allowed_ids=allow,
        )
        # Union semantics — preserve any pre-existing refs.
        merged = sorted(existing_set | set(scanned))
        added = len(merged) - len(existing_set)
        if added > 0:
            chunks_updated += 1
            new_refs_total += added
            chunk["learning_outcome_refs"] = merged
            updated_lines.append(json.dumps(chunk, ensure_ascii=False))
        else:
            # No new refs — keep original bytes / order intact.
            updated_lines.append(line)

    # W1b.5 (opt-in ``ED4ALL_CHUNK_LO_HEURISTIC``, default OFF) — additive-only
    # heuristic rescue AFTER the exact scan. A DART chunk rarely contains the
    # literal ``TO-03`` string, so the exact pass links very few chunks; this
    # arm content-token-matches an un-linked chunk to an objective STATEMENT,
    # drawing ids EXCLUSIVELY from the supplied objective universe. Default off
    # (or no objectives) ⇒ this whole block is skipped and ``updated_lines`` is
    # byte-identical to the exact-only baseline.
    heuristic_linked = 0
    heuristic_refs_added = 0
    from lib.ontology.lo_heuristic_link import (
        heuristic_link_chunks,
        resolve_lo_heuristic_enabled,
    )
    if objectives and resolve_lo_heuristic_enabled():
        # Re-parse the (in-memory) post-exact-scan lines, collect chunks that
        # are STILL un-linked, and let the helper mutate them in place.
        line_chunks: List[tuple] = []  # (line_index, chunk_dict)
        for idx, line in enumerate(updated_lines):
            if not line.strip():
                continue
            try:
                parsed = json.loads(line)
            except (json.JSONDecodeError, ValueError):
                continue
            if not isinstance(parsed, dict):
                continue
            refs = parsed.get("learning_outcome_refs") or []
            if refs:
                continue  # exact scan already linked it — leave bytes intact
            line_chunks.append((idx, parsed))

        if line_chunks:
            # Exception-guarded capture construction (best-effort contract —
            # capture failure must never break the back-fill).
            heuristic_capture: Optional[Any] = None
            try:
                from lib.decision_capture import DecisionCapture

                heuristic_capture = DecisionCapture(
                    course_code=course_slug,
                    phase="course_planning",
                    tool="pipeline",
                )
            except Exception:  # noqa: BLE001 — capture is best-effort
                heuristic_capture = None

            summary = heuristic_link_chunks(
                [c for _, c in line_chunks],
                objectives,
                capture=heuristic_capture,
                only_when_empty=True,
            )
            heuristic_linked = int(summary.get("chunks_linked", 0))
            heuristic_refs_added = int(summary.get("refs_added", 0))
            # Re-serialize only the chunks the heuristic actually mutated.
            for idx, chunk in line_chunks:
                if chunk.get("learning_outcome_refs"):
                    updated_lines[idx] = json.dumps(chunk, ensure_ascii=False)

    needs_write = chunks_updated > 0 or heuristic_refs_added > 0
    if needs_write:
        try:
            chunks_path.write_text(
                "\n".join(updated_lines) + ("\n" if updated_lines else ""),
                encoding="utf-8",
            )
        except OSError as exc:
            logger.warning(
                "Wave3-Anew3: failed to write back-filled chunks to %s "
                "(%s); leaving original on disk.",
                chunks_path, exc,
            )
            return {
                "chunks_path": str(chunks_path),
                "chunks_scanned": chunks_scanned,
                "chunks_updated": 0,
                "new_refs_total": 0,
                "skipped": True,
                "reason": f"write_error:{exc}",
            }

    result: Dict[str, Any] = {
        "chunks_path": str(chunks_path),
        "chunks_scanned": chunks_scanned,
        "chunks_updated": chunks_updated,
        "new_refs_total": new_refs_total,
        "skipped": False,
    }
    if objectives and resolve_lo_heuristic_enabled():
        result["heuristic_chunks_linked"] = heuristic_linked
        result["heuristic_refs_added"] = heuristic_refs_added
    return result


def _load_semantik_chunkset_for_planning(
    *,
    course_slug: str,
    kwargs: Dict[str, Any],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    """Load the DART chunkset for the window-map (Pass B).

    Resolves the staged chunkset under
    ``<libv2>/courses/<slug>/`` (via :func:`resolve_staged_chunks_path`, which
    dual-reads ``semantik_chunks/`` -> ``dart_chunks/`` -> legacy ``corpus/``)
    and returns ``(chunks_by_id, all_chunks)`` in document order. Missing /
    unreadable chunkset → ``({}, [])`` so the caller falls back to the
    chapter-grained path (``grounding_mode="chapter_fallback"``) — never a hard
    crash on a legacy run.

    ``course_slug`` is resolved robustly: callers pass the RAW course name
    (upper-case, underscore-separated) but the LibV2 course directory is created
    with the SLUGIFIED name (lower-case, hyphen-separated, via
    :meth:`LibV2Storage._generate_slug`). Try the name as given first (a caller
    may already pass a correct slug), then fall back to the LibV2 slug
    transform, using whichever resolves to an existing file.

    Each chunk record is annotated in-memory with a ``chapter_id`` (resolved via
    the sourceId-slug join against the loaded ``textbook_structure`` chapters) so
    Pass C's re-ground rescue can scope to the candidate's chapter pool. The
    annotation is best-effort: chunks that don't join carry no ``chapter_id``.
    """
    # Dual-read the staged chunkset (semantik -> dart -> corpus) so both
    # current and un-migrated archives ground correctly. Try the raw
    # course_slug first, then the LibV2 _generate_slug transform (lower +
    # '_'/' ' -> '-'), so a RAW course name resolves to its slugified dir.
    from lib.libv2_storage import LibV2Storage, resolve_staged_chunks_path
    libv2_courses_root = _resolve_libv2_root(kwargs.get("libv2_root")) / "courses"
    slug_candidates: List[str] = [course_slug]
    libv2_slug = LibV2Storage._generate_slug(course_slug)
    if libv2_slug not in slug_candidates:
        slug_candidates.append(libv2_slug)

    chunks_path = resolve_staged_chunks_path(libv2_courses_root / course_slug)
    for candidate in slug_candidates:
        candidate_path = resolve_staged_chunks_path(libv2_courses_root / candidate)
        chunks_path = candidate_path
        if candidate_path.exists() and candidate_path.is_file():
            break

    if not chunks_path.exists() or not chunks_path.is_file():
        logger.warning(
            "plan_course_structure: DART chunkset missing at %s; Stage-2 "
            "degrades to chapter_fallback (empty source_chunk_ids).",
            chunks_path,
        )
        return {}, []

    all_chunks: List[Dict[str, Any]] = []
    chunks_by_id: Dict[str, Any] = {}
    try:
        raw_lines = chunks_path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        logger.warning(
            "plan_course_structure: failed to read DART chunkset %s (%s); "
            "degrading to chapter_fallback.", chunks_path, exc,
        )
        return {}, []

    for line in raw_lines:
        if not line.strip():
            continue
        try:
            chunk = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            continue
        if not isinstance(chunk, dict):
            continue
        cid = str(chunk.get("id") or chunk.get("chunk_id") or "")
        if not cid:
            continue
        all_chunks.append(chunk)
        chunks_by_id[cid] = chunk
    return chunks_by_id, all_chunks


def _mean_intra_cluster_cosine(
    vecs: List[List[float]], member_idxs: List[int]
) -> float:
    """WS1 — mean pairwise cosine among one cluster's member vectors.

    Singleton / empty clusters → ``1.0`` (a lone CO is trivially "cohesive").
    A calibration signal: a high mean intra-cluster cosine means the cluster is
    a tight theme, a low one means the threshold over-merged.
    """
    from lib.embedding._math import cosine_similarity

    idxs = [i for i in member_idxs if 0 <= i < len(vecs)]
    if len(idxs) < 2:
        return 1.0
    total = 0.0
    pairs = 0
    for a in range(len(idxs)):
        for b in range(a + 1, len(idxs)):
            total += cosine_similarity(vecs[idxs[a]], vecs[idxs[b]])
            pairs += 1
    return total / pairs if pairs else 1.0


def _clamp_cluster_count(
    clusters: List[List[int]],
    vecs: List[List[float]],
    *,
    target_lo: int = 3,
    target_hi: int = 15,
) -> List[List[int]]:
    """WS1 §3.3 — clamp the cluster count into ``[target_lo, target_hi]``.

    Deterministic; NEVER drops a CO (partition invariant: every input index
    appears in exactly one returned cluster). ``target_lo`` is an UPPER-BOUND
    target — when there are fewer COs than ``target_lo`` we return the natural
    clusters rather than fabricating empty ones.

    - ``len in [lo, hi]``: unchanged.
    - ``len > hi``: merge the smallest cluster (ties → highest min-index) into
      the cluster with the nearest centroid cosine, until ``hi``.
    - ``len < lo``: split the largest cluster by re-clustering its members at a
      higher threshold (``threshold + 0.1``, capped at 0.99); repeat until
      ``>= lo`` or no further split is possible.
    """
    from lib.embedding._math import cosine_similarity
    from lib.objectives.objective_dedup import (
        cluster_by_cosine,
        resolve_to_cluster_threshold,
    )

    work = [list(c) for c in clusters if c]
    if not work:
        return work

    def _centroid(member_idxs: List[int]) -> List[float]:
        idxs = [i for i in member_idxs if 0 <= i < len(vecs)]
        if not idxs:
            return []
        dim = len(vecs[idxs[0]])
        acc = [0.0] * dim
        for i in idxs:
            v = vecs[i]
            for d in range(min(dim, len(v))):
                acc[d] += v[d]
        return [x / len(idxs) for x in acc]

    # ---- Over-target: merge smallest into nearest-centroid neighbor. -----
    while len(work) > target_hi:
        # Smallest cluster (ties → highest min-index for determinism).
        small_pos = min(
            range(len(work)),
            key=lambda p: (len(work[p]), -min(work[p])),
        )
        small_centroid = _centroid(work[small_pos])
        best_pos = -1
        best_cos = -2.0
        for p in range(len(work)):
            if p == small_pos:
                continue
            other_centroid = _centroid(work[p])
            cos = (
                cosine_similarity(small_centroid, other_centroid)
                if small_centroid and other_centroid
                else -1.0
            )
            if cos > best_cos:
                best_cos = cos
                best_pos = p
        if best_pos < 0:
            break
        work[best_pos] = sorted(work[best_pos] + work[small_pos])
        work.pop(small_pos)
        work.sort(key=lambda g: min(g))

    # ---- Under-target: split the largest cluster at a higher threshold. --
    if len(work) < target_lo:
        base_threshold = resolve_to_cluster_threshold()
        # Iterate; each pass tries to split the largest splittable cluster.
        guard = 0
        while len(work) < target_lo and guard < len(vecs) + 5:
            guard += 1
            # Largest cluster with ≥2 members (ties → lowest min-index).
            candidates = [p for p in range(len(work)) if len(work[p]) >= 2]
            if not candidates:
                break
            big_pos = max(
                candidates, key=lambda p: (len(work[p]), -min(work[p]))
            )
            members = work[big_pos]
            split_threshold = min(0.99, base_threshold + 0.1)
            member_vecs = [vecs[i] for i in members]
            sub_clusters, _, _ = cluster_by_cosine(
                member_vecs, split_threshold
            )
            if len(sub_clusters) <= 1:
                # Cannot split this one any further; try the next-largest by
                # removing it from consideration this pass.
                # (Move it aside by marking via a sentinel: re-cluster at an
                # even higher threshold once before giving up.)
                higher = min(0.99, split_threshold + 0.1)
                sub_clusters, _, _ = cluster_by_cosine(member_vecs, higher)
                if len(sub_clusters) <= 1:
                    # Genuinely unsplittable (e.g. identical vectors) — stop.
                    break
            # Map sub-cluster local indices back to global CO indices.
            new_groups = [
                sorted(members[i] for i in sub) for sub in sub_clusters
            ]
            work.pop(big_pos)
            work.extend(new_groups)
            work.sort(key=lambda g: min(g))

    work.sort(key=lambda g: min(g))
    return work


def _fallback_terminal_from_cluster(
    cluster_cos: List[Dict[str, Any]]
) -> Dict[str, Any]:
    """WS1 §3.4 — per-cluster fail-soft TO from the longest-statement CO.

    Summary-layer fallback (no chunk grounding required, §7); copies a verbatim
    CO subset → never invents. Used when the author call returns ``None``.
    """
    if not cluster_cos:
        return {
            "statement": "",
            "bloom_level": "understand",
            "source_refs": [],
            "to_synthesis": "cluster_rep_fallback",
        }
    rep = max(
        cluster_cos, key=lambda c: len(str(c.get("statement") or ""))
    )
    return {
        "statement": str(rep.get("statement") or "").strip(),
        "bloom_level": str(rep.get("bloom_level") or "understand"),
        "source_refs": [],
        "to_synthesis": "cluster_rep_fallback",
    }


# W5 Defect-F one-owner lift: ``_co_parent_terminal_id`` +
# ``_annotate_terminals_with_children`` now live in
# ``lib/objectives/terminal_children.py`` so the offline
# ``ed4all objectives restructure`` CLI (lib/objectives/restructure.py) can
# compose the SAME TO→CO→chunk back-annotation without importing pipeline_tools.
# Re-exported here (byte-identical behaviour) at module scope so every existing
# call site (``_week_co_groups``, the course_planning persist path) and the
# stage-2 tests (``pt._annotate_terminals_with_children`` /
# ``pt._co_parent_terminal_id``) keep resolving these names unchanged.
from lib.objectives.terminal_children import (  # noqa: E402
    _annotate_terminals_with_children,
    _co_parent_terminal_id,
)


_WEEK_TO_GROUPS_ENV = "ED4ALL_WEEK_TO_GROUPS"
_WEEK_TO_GROUPS_TRUTHY = frozenset({"1", "true", "yes", "on"})


def resolve_week_to_groups(value: Optional[bool] = None) -> bool:
    """Resolve the ``ED4ALL_WEEK_TO_GROUPS`` gate (default OFF).

    Explicit arg > env. Truthy tokens ``1``/``true``/``yes``/``on`` (any case)
    enable; falsey / garbage / unset → off (parse-with-fallback, mirroring
    ``lib.objectives.citation_reselect.resolve_citation_reselect``).
    """
    if value is not None:
        return bool(value)
    return (
        os.environ.get(_WEEK_TO_GROUPS_ENV, "").strip().lower()
        in _WEEK_TO_GROUPS_TRUTHY
    )


def _week_co_groups(
    cos: List[Dict[str, Any]],
    terminal_objectives: List[Dict[str, Any]],
    duration_weeks: int,
    *,
    enabled: Optional[bool] = None,
) -> Dict[int, List[Dict[str, Any]]]:
    """SINGLE-SOURCE the per-week chapter-objective (CO) grouping for the
    outline tier's ``"Week N"`` groups.

    Returns ``{week_num (1-based): [CO dict, ...]}`` for weeks
    ``1..duration_weeks``. BOTH the persist path (``_plan_course_structure`` →
    ``synthesized_objectives.json``'s ``chapter_objectives``) and the emit path
    (``_generate_course_content`` → ``week_chapter_cos``) call THIS helper so
    the on-disk groups the validator reads and the emitted week membership stay
    identical by construction.

    Two modes:

    * **TO-membership** (``ED4ALL_WEEK_TO_GROUPS`` on AND
      ``duration_weeks == len(terminal_objectives)``): week ``N``'s group is
      TO-``N``'s child COs — every CO in ``cos`` whose parent-terminal id
      (resolved via :func:`_co_parent_terminal_id`, case-insensitive) matches
      the ``N``-th terminal objective. TO order = ``terminal_objectives`` order;
      CO order within a group = stable ``cos`` order. A CO whose parent TO does
      not resolve among the TOs is appended to the FINAL week (never dropped —
      coverage-preserving) with a logged warning.

    * **ceil-stride fallback** (flag off, OR weeks != num_tos): the legacy
      single-sourced ``_slice_cos_for_week`` slicer with a shared cross-week
      ``placed_ids`` set — byte-identical to the prior inline calls. When the
      flag is ON but ``weeks != num_tos`` a warning naming BOTH counts is logged
      before falling back.
    """
    groups: Dict[int, List[Dict[str, Any]]] = {
        w: [] for w in range(1, max(duration_weeks, 0) + 1)
    }
    if not cos or duration_weeks < 1:
        return groups

    flag_on = resolve_week_to_groups(enabled)
    num_tos = len([t for t in (terminal_objectives or []) if isinstance(t, dict)])

    if flag_on and duration_weeks == num_tos and num_tos > 0:
        # TO-membership grouping. Map each TO id (lower) → its 1-based week.
        to_week_by_lower: Dict[str, int] = {}
        for idx, to in enumerate(terminal_objectives, start=1):
            if not isinstance(to, dict):
                continue
            tid = to.get("id")
            if isinstance(tid, str) and tid.strip():
                to_week_by_lower.setdefault(tid.strip().lower(), idx)
        orphans: List[Dict[str, Any]] = []
        for co in cos:
            if not isinstance(co, dict):
                continue
            parent = _co_parent_terminal_id(co).lower()
            wk = to_week_by_lower.get(parent)
            if wk is None:
                orphans.append(co)
            else:
                groups[wk].append(co)
        if orphans:
            logger.warning(
                "_week_co_groups: %d of %d CO(s) have no resolvable parent "
                "terminal among the %d TO(s) (ED4ALL_WEEK_TO_GROUPS on); "
                "appending them to the final week to preserve coverage.",
                len(orphans), len(cos), num_tos,
            )
            groups[duration_weeks].extend(orphans)
        return groups

    if flag_on and duration_weeks != num_tos:
        logger.warning(
            "ED4ALL_WEEK_TO_GROUPS is on but duration_weeks (%d) != number of "
            "terminal objectives (%d); falling back to ceil-stride CO slicing "
            "for the per-week groups.",
            duration_weeks, num_tos,
        )

    # ceil-stride fallback (also the default flag-off path). Single-sourced via
    # the Courseforge slicer + a shared placed-ids set (M5 Fix B) — byte-stable.
    from Courseforge.scripts.generate_course import (  # noqa: PLC0415
        _slice_cos_for_week as _cf_slice_cos_for_week,
    )

    placed_ids: set = set()
    for w in range(1, duration_weeks + 1):
        groups[w] = _cf_slice_cos_for_week(
            cos, duration_weeks, w, placed_ids=placed_ids
        )
    return groups


def _derive_terminals_bottom_up(
    *,
    provider: Any,
    chapter_cos: List[Dict[str, Any]],
    embed: Any,
    course_name: str,
    mint_lo_id: Any,
    capture: Optional[Any] = None,
    checkpoint_path: Optional[Path] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """WS1 KEYSTONE — derive terminal objectives bottom-up by clustering COs.

    Cluster the grounded CO statement vectors (lower threshold than dedup) and
    author one TO per cluster (fail-soft per cluster). Each CO's ``terminal_id``
    is set DIRECTLY in-loop (clustering determined the parent) so the legacy
    argmax-backlink is a no-op for ASSIGNMENT — see the call site for why the
    backlink is still invoked (WS2 instrumentation proof signal).

    Returns ``(terminals, cluster_signals)``. Returns ``([], {})`` on embed
    failure so the caller degrades to the legacy draft-TO reconcile (R4).
    """
    from lib.objectives.objective_dedup import (
        cluster_to_target_k,
        resolve_to_cluster_k,
    )

    statements = [
        str(c.get("statement") or c.get("text") or "").strip() or " "
        for c in chapter_cos
    ]
    try:
        vecs = embed.encode_batch(statements)
    except Exception:  # noqa: BLE001 — degrade to legacy reconcile
        return [], {}

    # WS1.1 — TARGET-K Ward agglomerative clustering supersedes WS1's single-link
    # cosine-threshold + _clamp_cluster_count path (which collapsed cosine-dense
    # CO embeddings into a 67-member catch-all). The target-K result is already
    # bounded to [3, 15] and balanced, so no post-clamp is needed; the partition
    # invariant (every CO index in exactly one cluster) is preserved.
    to_cluster_k = resolve_to_cluster_k(len(vecs))
    clusters = cluster_to_target_k(vecs, to_cluster_k)
    # Detect whether the sklearn (ward) path or the no-sklearn single-link
    # fallback produced the clusters (for provenance in cluster_signals).
    try:
        import sklearn.cluster as _sk_cluster  # noqa: F401

        to_cluster_linkage = "ward"
    except Exception:  # noqa: BLE001 — sklearn absent → fallback path ran
        to_cluster_linkage = "single_link_fallback"

    # P1 — CLUSTER GUARDS (default-OFF, opt-in). The fixed target-K Ward result
    # can leave (1) a semantic-OUTLIER CO as its own singleton TO (a wholesale-
    # hallucinated terminal competency), (2) tiny 1-2-CO runt clusters too thin
    # to be standalone TOs, and (3) near-duplicate TOs because distinct clusters'
    # centroids are highly similar (an over-split theme). ``apply_cluster_guards``
    # consolidates undersize / outlier clusters into their nearest neighbor and
    # collapses near-duplicate-centroid clusters — ALL pre-id-mint (re-partitions
    # existing CO indices only; partition invariant preserved → downstream
    # ``learning_outcome_refs`` continuity holds). Default-OFF → byte-identical
    # to the prior K-result; the operator opts in via the ED4ALL_TO_* guard
    # flags. Defensive import so this is a no-op if the helper isn't present.
    guard_signals: Dict[str, Any] = {}
    try:
        from lib.objectives.objective_dedup import (  # noqa: PLC0415
            apply_cluster_guards,
        )

        clusters, guard_signals = apply_cluster_guards(clusters, vecs)
    except Exception:  # noqa: BLE001 — never break TO derivation on the guards
        guard_signals = {}

    # UNCONDITIONAL anti-hallucinated-TO backstop (runs even when the opt-in
    # ED4ALL_TO_CLUSTER_GUARDS above are OFF). A terminal objective is
    # definitionally an AGGREGATE of >=2 chapter objectives; a size-1 cluster
    # that survives clustering (and the guards, which DELIBERATELY leave a
    # genuinely-distinct singleton standing) would be promoted into a standalone
    # course-wide TERMINAL objective that content generation weaves through many
    # pages — even though it rests on a single idiosyncratic CO. Fold every
    # remaining singleton into its nearest-centroid neighbor (pre-id-mint,
    # partition-preserving → downstream learning_outcome_refs continuity holds).
    # Default ON (correctness); the operator restores the legacy keep-singleton
    # behavior via ED4ALL_TO_ALLOW_SINGLETON_TO. try/except like the guard block
    # so it never breaks TO derivation.
    singletons_dissolved = 0
    _singleton_targets: List[int] = []
    try:
        from lib.objectives.objective_dedup import (  # noqa: PLC0415
            _nearest_centroid_neighbor,
            dissolve_singletons,
            resolve_to_allow_singleton_to,
        )

        if not resolve_to_allow_singleton_to():
            # Record each singleton's pre-dissolve nearest-neighbor cluster
            # min-index for the decision-capture rationale (approximate — the
            # iterative fold shifts centroids; used only for the audit string).
            for _si, _sc in enumerate(clusters):
                if len(_sc) == 1:
                    _nidx, _ = _nearest_centroid_neighbor(
                        _sc, clusters, vecs, skip_index=_si
                    )
                    if _nidx >= 0 and clusters[_nidx]:
                        _singleton_targets.append(min(clusters[_nidx]))
            clusters, singletons_dissolved = dissolve_singletons(clusters, vecs)
    except Exception:  # noqa: BLE001 — never break TO derivation on the backstop
        singletons_dissolved = 0
        _singleton_targets = []
    singletons_remaining = sum(1 for c in clusters if len(c) == 1)

    terminals: List[Dict[str, Any]] = []
    intra_cosines: List[float] = []
    # W7.5 (M-TO) — surface the REAL cluster->source-chunk assignment so the
    # TerminalObjectiveSourceGroundingValidator can score each TO statement
    # against the chunks its cluster's COs actually cite (anti-fabrication:
    # union of the member COs' own ``source_chunk_ids`` — never invented).
    to_source_chunk_assignments: Dict[str, List[str]] = {}
    # Per-cluster resume checkpoint (shared llm_checkpoint store; default ON,
    # ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT > ED4ALL_GENERATION_CHECKPOINT).
    # Each authored TO is one 7B call; the fingerprint (sorted member CO
    # statements + model + course) invalidates whenever clustering / inputs
    # shift, so a stale cluster never reuses another cluster's TO. Fallback
    # (author-failed) terminals are deterministic + cheap → NOT checkpointed.
    _cluster_store = _stage2_cluster_store(checkpoint_path)
    _cluster_cache = _cluster_store.load() if _cluster_store.enabled else {}
    _clusters_reused = 0
    for c_idx, member_idxs in enumerate(clusters, start=1):
        # Graceful stop at the cluster boundary (sequential — plain raise): the
        # previous cluster's authored TO is already appended to the sidecar, so
        # a raise here loses at most the one in-flight author call.
        check_stop("stage2_clusters", c_idx - 1)
        cluster_cos = [chapter_cos[i] for i in member_idxs]
        _cl_unit = f"cluster{c_idx:02d}"
        _cl_fp_inputs: Dict[str, Any] = {
            "site": "stage2_clusters",
            "member_statements": sorted(
                str(c.get("statement") or c.get("text") or "")
                for c in cluster_cos
            ),
            "model": str(getattr(provider, "_model", "") or ""),
            "course_name": course_name,
        }
        # Gate-retry re-roll salt: key present ONLY when the runner's
        # course_planning gate-retry loop set it, so legacy fingerprints
        # stay byte-identical and a salted retry attempt never reuses a
        # prior attempt's cached TO.
        _reroll_salt = _planning_reroll_salt()
        if _reroll_salt:
            _cl_fp_inputs["reroll_salt"] = _reroll_salt
        # Failure-directed feedback digest (same contract as the salt): a
        # DIFFERENT digest → different fingerprint → no stale-cache reuse.
        _reroll_feedback = _planning_reroll_feedback()
        if _reroll_feedback:
            _cl_fp_inputs["reroll_feedback_sha"] = _llm_hash_text(
                _reroll_feedback
            )
        _cl_fp = _llm_compute_fingerprint(_cl_fp_inputs)
        authored: Optional[Dict[str, Any]] = None
        if _cluster_store.enabled:
            _cl_cached = _cluster_store.reuse(
                _cl_unit, _cl_fp, cache=_cluster_cache
            )
            if _cl_cached is not None and isinstance(
                _cl_cached.get("authored"), dict
            ):
                authored = dict(_cl_cached["authored"])
                _clusters_reused += 1
        if authored is None:
            authored = provider.author_terminal_for_cluster(
                cluster_cos, course_name=course_name, cluster_index=c_idx
            )
            if authored is not None and _cluster_store.enabled:
                _cluster_store.append(
                    _cl_unit, _cl_fp, {"authored": dict(authored)}
                )
        if authored is None:
            authored = _fallback_terminal_from_cluster(cluster_cos)
        authored["id"] = mint_lo_id("terminal", c_idx)
        terminals.append(authored)
        _cluster_chunk_ids: List[str] = []
        _seen_chunk_ids: set = set()
        for i in member_idxs:
            chapter_cos[i]["terminal_id"] = authored["id"]
            _raw = chapter_cos[i].get("source_chunk_ids")
            if isinstance(_raw, list):
                for _ch in _raw:
                    _cs = str(_ch).strip()
                    if _cs and _cs not in _seen_chunk_ids:
                        _seen_chunk_ids.add(_cs)
                        _cluster_chunk_ids.append(_cs)
        to_source_chunk_assignments[authored["id"]] = _cluster_chunk_ids
        intra_cosines.append(_mean_intra_cluster_cosine(vecs, member_idxs))

    cluster_signals: Dict[str, Any] = {
        "to_derivation": "bottom_up",
        "cluster_count": len(clusters),
        "to_cluster_k": int(to_cluster_k),
        "to_cluster_linkage": to_cluster_linkage,
        "mean_intra_cluster_cosine": (
            round(sum(intra_cosines) / len(intra_cosines), 6)
            if intra_cosines
            else 0.0
        ),
        "min_intra_cluster_cosine": (
            round(min(intra_cosines), 6) if intra_cosines else 0.0
        ),
        # W7.5 (M-TO) — REAL cluster->chunk assignment ({to_id: [chunk_ids]})
        # consumed by TerminalObjectiveSourceGroundingValidator.
        "to_source_chunk_assignments": to_source_chunk_assignments,
        # Per-cluster resume-checkpoint reuse (0 when the sidecar is absent /
        # disabled). Rides the existing objective_grounding_filter event.
        "to_clusters_reused_from_checkpoint": _clusters_reused,
    }
    if _clusters_reused:
        logger.info(
            "plan_course_structure: bottom-up TO derivation reused %d/%d "
            "cluster TO(s) from sidecar (skipped their 7B author calls).",
            _clusters_reused, len(clusters),
        )
    # P1 — surface the cluster-guard counters (outliers_absorbed /
    # undersize_merged / near_dup_clusters_merged / clusters_before /
    # clusters_after) onto the run's grounding_signals (all-zero when the
    # guards are OFF, the default). Mirrors how the WS1/WS2 signals are
    # surfaced for calibration.
    if guard_signals:
        for _gk, _gv in guard_signals.items():
            cluster_signals[f"to_guard_{_gk}"] = _gv
    if capture is not None and guard_signals and (
        guard_signals.get("outliers_absorbed")
        or guard_signals.get("undersize_merged")
        or guard_signals.get("near_dup_clusters_merged")
    ):
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    "to_cluster_guards:"
                    f"{guard_signals.get('clusters_before', 0)}->"
                    f"{guard_signals.get('clusters_after', len(clusters))} TOs"
                ),
                rationale=(
                    "P1 cluster-guards consolidated the fixed-K Ward TO "
                    "clusters (pre-id-mint, partition-preserving): absorbed "
                    f"{guard_signals.get('outliers_absorbed', 0)} outlier / "
                    f"merged {guard_signals.get('undersize_merged', 0)} "
                    "undersize runt cluster(s) into their nearest neighbor and "
                    "collapsed "
                    f"{guard_signals.get('near_dup_clusters_merged', 0)} "
                    "near-duplicate-centroid cluster pair(s), taking the TO "
                    f"count {guard_signals.get('clusters_before', 0)} -> "
                    f"{guard_signals.get('clusters_after', len(clusters))} so a "
                    "hallucinated singleton TO / over-split duplicate theme no "
                    "longer survives id-minting. Every CO keeps a cluster "
                    "(never dropped)."
                ),
                alternatives_considered=[
                    "keep the raw fixed-K Ward clusters (singleton outlier "
                    "becomes a hallucinated TO; runts + duplicate themes "
                    "survive)",
                ],
            )
        except Exception:  # noqa: BLE001 — capture must not break derivation
            pass

    # Surface the unconditional singleton-dissolve backstop counters onto the
    # run's grounding_signals (singletons_dissolved == 0 when the opt-out env is
    # set or the K-result carried no singletons).
    cluster_signals["singletons_dissolved"] = int(singletons_dissolved)
    cluster_signals["singletons_remaining"] = int(singletons_remaining)
    if capture is not None and singletons_dissolved:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"dissolve_singletons:{singletons_dissolved} lone-CO "
                    f"cluster(s) folded -> {len(clusters)} TOs"
                ),
                rationale=(
                    "Unconditional anti-hallucinated-TO backstop: a terminal "
                    "objective aggregates >=2 chapter objectives, so "
                    f"{singletons_dissolved} size-1 cluster(s) that would each "
                    "author a standalone course-wide terminal objective were "
                    "folded into their nearest-centroid neighbor cluster(s) "
                    f"(min member indices {sorted(_singleton_targets)}), "
                    "pre-id-mint and partition-preserving, taking the TO count "
                    f"to {len(clusters)} with {singletons_remaining} singleton(s) "
                    "remaining (tiny-course floor). Every CO keeps a cluster "
                    "(never dropped/invented)."
                ),
                alternatives_considered=[
                    "keep the size-1 cluster (a lone outlier CO becomes a "
                    "hallucinated course-wide terminal objective)",
                ],
            )
        except Exception:  # noqa: BLE001 — capture must not break derivation
            pass
    return terminals, cluster_signals


# ---------------------------------------------------------------------------
# Defect A — chapter-anchored TO derivation (opt-in; default OFF).
# ---------------------------------------------------------------------------
#
# Terminal objectives are chapter-grained by definition; the bottom-up statement
# clustering above scattered a chapter's COs across theme clusters (Defect A).
# When ``ED4ALL_TO_CHAPTER_ANCHOR`` is on, TOs are derived by anchoring each CO
# to the DART module (== one staged HTML == one chapter) its cited chunks come
# from — one module → one TO, authored via the SAME existing 7B call site,
# sidecar, and stop check as bottom-up. Default OFF ⇒ byte-identical to today.
_TO_CHAPTER_ANCHOR_ENV = "ED4ALL_TO_CHAPTER_ANCHOR"
_TO_CHAPTER_ANCHOR_REORDER_ENV = "ED4ALL_TO_CHAPTER_ANCHOR_REORDER"
_TO_CHAPTER_MIN_MODULES_ENV = "ED4ALL_TO_CHAPTER_MIN_MODULES"
_TO_CHAPTER_MIN_CO_COVERAGE_ENV = "ED4ALL_TO_CHAPTER_MIN_CO_COVERAGE"
_TO_CHAPTER_ANCHOR_TRUTHY = frozenset({"1", "true", "yes", "on"})
# Hard ceiling on module count (per-section files → module finer than chapter →
# too many singleton TOs; degrade to bottom-up). Not operator-tunable (§A step 2).
_TO_CHAPTER_MAX_MODULES = 30


def _resolve_to_chapter_anchor(value: Optional[bool] = None) -> bool:
    """Resolve the ``ED4ALL_TO_CHAPTER_ANCHOR`` master gate (default OFF).

    Explicit arg > env. Truthy tokens ``1``/``true``/``yes``/``on`` (any case)
    enable; falsey / garbage / unset → off (parse-with-fallback, mirroring
    :func:`resolve_week_to_groups`).
    """
    if value is not None:
        return bool(value)
    return (
        os.environ.get(_TO_CHAPTER_ANCHOR_ENV, "").strip().lower()
        in _TO_CHAPTER_ANCHOR_TRUTHY
    )


def _resolve_to_chapter_anchor_reorder(value: Optional[bool] = None) -> bool:
    """Resolve the ``ED4ALL_TO_CHAPTER_ANCHOR_REORDER`` satellite (default ON).

    Default ON *when the master is on* (§A step 6): the CO re-order pass makes
    ceil-stride weeks chapter-contiguous even without ``ED4ALL_WEEK_TO_GROUPS``.
    Explicit arg > env; only the falsey tokens ``0``/``false``/``no``/``off``
    disable it, everything else (incl. unset) → ON.
    """
    if value is not None:
        return bool(value)
    raw = os.environ.get(_TO_CHAPTER_ANCHOR_REORDER_ENV, "").strip().lower()
    if raw in {"0", "false", "no", "off"}:
        return False
    return True


def _resolve_to_chapter_min_modules(value: Optional[int] = None) -> int:
    """Resolve the ``ED4ALL_TO_CHAPTER_MIN_MODULES`` floor (default 2).

    Below this module count the anchor mode degrades to bottom-up (a monolithic
    single-HTML corpus has 1 module → nothing to anchor). Garbage / non-positive
    env values fall back to the default (parse-with-fallback).
    """
    if value is not None:
        return max(1, int(value))
    raw = os.environ.get(_TO_CHAPTER_MIN_MODULES_ENV)
    if raw:
        try:
            parsed = int(raw)
            if parsed >= 1:
                return parsed
        except (TypeError, ValueError):
            pass
    return 2


def _resolve_to_chapter_min_co_coverage(value: Optional[float] = None) -> float:
    """Resolve the ``ED4ALL_TO_CHAPTER_MIN_CO_COVERAGE`` floor (default 0.80).

    The min fraction of COs that must resolve ≥1 module from their own cited
    chunks for the anchor mode to fire; below it, degrade to bottom-up. Garbage /
    out-of-[0,1] env values fall back to the default (parse-with-fallback).
    """
    if value is not None:
        return min(1.0, max(0.0, float(value)))
    raw = os.environ.get(_TO_CHAPTER_MIN_CO_COVERAGE_ENV)
    if raw:
        try:
            parsed = float(raw)
            if 0.0 <= parsed <= 1.0:
                return parsed
        except (TypeError, ValueError):
            pass
    return 0.80


def _chapter_anchor_degrade_reason(
    result: Any, *, min_modules: int, min_coverage: float
) -> Optional[str]:
    """Graceful-degrade eligibility probe (§A step 2). ``None`` ⇒ eligible.

    Returns a short machine-readable reason string (surfaced as the
    ``to_derivation_degraded_reason`` signal + logged at WARNING) when the corpus
    can't support chapter-anchored TOs, so the caller falls through to bottom-up.
    """
    n_modules = int(getattr(result, "n_modules", 0))
    if n_modules < min_modules:
        return f"too_few_modules:{n_modules}<{min_modules}"
    if n_modules > _TO_CHAPTER_MAX_MODULES:
        return f"too_many_modules:{n_modules}>{_TO_CHAPTER_MAX_MODULES}"
    coverage = float(getattr(result, "co_coverage", 0.0))
    if coverage < min_coverage:
        return f"low_co_coverage:{coverage:.3f}<{min_coverage:.3f}"
    return None


def _most_common_bloom_verb(cluster_cos: List[Dict[str, Any]]) -> str:
    """Most-common member ``bloom_verb`` (capitalized) for a fallback TO stem.

    Falls back to detecting the main Bloom verb off each CO's statement when the
    field is absent, then to a neutral ``"Master"`` when nothing resolves. Pure /
    deterministic; used only for the author-failed fallback statement (§A step 4).
    """
    from collections import Counter as _Counter

    verbs: List[str] = []
    for co in cluster_cos:
        if not isinstance(co, dict):
            continue
        verb = str(co.get("bloom_verb") or "").strip().lower()
        if not verb:
            try:
                from lib.ontology.bloom import detect_bloom_level  # noqa: PLC0415

                _lvl, detected = detect_bloom_level(
                    str(co.get("statement") or "")
                )
                verb = str(detected or "").strip().lower()
            except Exception:  # noqa: BLE001 — best-effort verb detection
                verb = ""
        if verb:
            verbs.append(verb)
    if not verbs:
        return "Master"
    return _Counter(verbs).most_common(1)[0][0].capitalize()


def _reorder_cos_by_anchor(
    chapter_cos: List[Dict[str, Any]],
    chunks_by_id: Dict[str, Any],
    all_chunks: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """§A step 6 — stable book-order re-sort of pre-mint COs (chapter-contiguous).

    Runs the pure anchor assignment on the pre-id-mint candidates and stable-sorts
    by ``(module_order_index, min position_in_module over cited chunks, existing
    index)`` so a subsequent ceil-stride week slice is chapter-contiguous even
    without ``ED4ALL_WEEK_TO_GROUPS``. A no-op (returns the input list unchanged)
    when the corpus is ineligible for anchoring — mirrors the TO-derivation
    degrade so the reorder never scatters a corpus the anchor path would reject.
    """
    from lib.objectives.chapter_anchor import assign_cos_to_modules

    result = assign_cos_to_modules(chapter_cos, chunks_by_id, all_chunks)
    reason = _chapter_anchor_degrade_reason(
        result,
        min_modules=_resolve_to_chapter_min_modules(),
        min_coverage=_resolve_to_chapter_min_co_coverage(),
    )
    if reason is not None:
        return chapter_cos
    order_pos = {mid: i for i, mid in enumerate(result.module_order)}
    indexed = list(enumerate(chapter_cos))
    indexed.sort(
        key=lambda pair: (
            order_pos.get(result.assignment.get(pair[0], ""), len(order_pos)),
            result.min_position_by_co.get(pair[0], 1_000_000_000),
            pair[0],
        )
    )
    return [co for _idx, co in indexed]


def _derive_terminals_chapter_anchored(
    *,
    provider: Any,
    chapter_cos: List[Dict[str, Any]],
    chunks_by_id: Dict[str, Any],
    all_chunks: List[Dict[str, Any]],
    embed: Any,
    course_name: str,
    mint_lo_id: Any,
    capture: Optional[Any] = None,
    checkpoint_path: Optional[Path] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Defect A — derive terminal objectives by ANCHORING COs to DART modules.

    Every CO is assigned (deterministically) to the module its cited chunks
    predominantly come from (one module == one staged HTML == one chapter); one
    TO is authored per module, in book order, via the EXISTING
    ``provider.author_terminal_for_cluster`` call, the EXISTING
    ``_stage2_cluster_store`` sidecar (fingerprint extended with the anchor
    module id), and the EXISTING ``check_stop("stage2_clusters")`` boundary — NO
    new LLM call site, graceful-stop parity with the bottom-up loop.

    Returns ``(terminals, cluster_signals)``. Returns ``([], {reason})`` on a
    graceful degrade (too few / too many modules, or low CO coverage) so the
    caller falls through to ``_derive_terminals_bottom_up`` untouched.
    """
    from lib.objectives.chapter_anchor import assign_cos_to_modules

    result = assign_cos_to_modules(chapter_cos, chunks_by_id, all_chunks)
    reason = _chapter_anchor_degrade_reason(
        result,
        min_modules=_resolve_to_chapter_min_modules(),
        min_coverage=_resolve_to_chapter_min_co_coverage(),
    )
    if reason is not None:
        logger.warning(
            "plan_course_structure: chapter-anchored TO derivation degraded "
            "(%s) — falling through to bottom-up clustering.", reason,
        )
        return [], {"to_derivation_degraded_reason": reason}

    logger.info(
        "plan_course_structure: chapter-anchored TO derivation — %d module(s), "
        "%d CO(s), coverage=%.3f (cluster-K/guards/merge/singleton knobs IGNORED "
        "in anchor mode).",
        result.n_modules, len(chapter_cos), result.co_coverage,
    )

    # Zero-resolve COs default to the last module (never dropped). When an embed
    # client is available, re-home each to the module of its NEAREST resolved CO
    # by statement cosine (§A step 3) — a strictly better home than "last".
    assignment: Dict[int, str] = dict(result.assignment)
    if result.unresolved_co_indices and embed is not None:
        try:
            _rehome_unresolved_by_cosine(
                chapter_cos, assignment, result.unresolved_co_indices, embed
            )
        except Exception:  # noqa: BLE001 — cosine re-home is best-effort
            logger.warning(
                "plan_course_structure: chapter-anchor cosine re-home of %d "
                "zero-resolve CO(s) failed; keeping last-module default.",
                len(result.unresolved_co_indices), exc_info=True,
            )

    # Rebuild the book-ordered, non-empty module groups from the (possibly
    # re-homed) assignment.
    from lib.objectives.chapter_anchor import _build_groups  # noqa: PLC0415

    groups = _build_groups(assignment, result.module_order)

    terminals: List[Dict[str, Any]] = []
    to_source_chunk_assignments: Dict[str, List[str]] = {}
    _cluster_store = _stage2_cluster_store(checkpoint_path)
    _cluster_cache = _cluster_store.load() if _cluster_store.enabled else {}
    _modules_reused = 0

    for m_idx, (module_id, member_idxs) in enumerate(groups, start=1):
        # Graceful stop at the module boundary — SAME site id + sequential
        # semantics as the bottom-up cluster loop (previous module's authored TO
        # is already on the sidecar, so a raise loses ≤1 in-flight author call).
        check_stop("stage2_clusters", m_idx - 1)
        cluster_cos = [chapter_cos[i] for i in member_idxs]
        module_title = result.module_title_by_id.get(module_id) or module_id
        _cl_unit = f"cluster{m_idx:02d}"
        # Fingerprint EXTENDED with the anchor module id so a stale assignment
        # never reuses another module's TO (mirrors the bottom-up fingerprint).
        _cl_fp_inputs: Dict[str, Any] = {
            "site": "stage2_clusters",
            "anchor_module_id": module_id,
            "member_statements": sorted(
                str(c.get("statement") or c.get("text") or "")
                for c in cluster_cos
            ),
            "model": str(getattr(provider, "_model", "") or ""),
            "course_name": course_name,
        }
        # Gate-retry re-roll salt (mirrors the bottom-up site): present only
        # when the runner's course_planning gate-retry loop set it — legacy
        # fingerprints stay byte-identical.
        _reroll_salt = _planning_reroll_salt()
        if _reroll_salt:
            _cl_fp_inputs["reroll_salt"] = _reroll_salt
        # Failure-directed feedback digest (mirrors the bottom-up site): a
        # DIFFERENT digest → different fingerprint → no stale-cache reuse.
        _reroll_feedback = _planning_reroll_feedback()
        if _reroll_feedback:
            _cl_fp_inputs["reroll_feedback_sha"] = _llm_hash_text(
                _reroll_feedback
            )
        _cl_fp = _llm_compute_fingerprint(_cl_fp_inputs)
        authored: Optional[Dict[str, Any]] = None
        if _cluster_store.enabled:
            _cl_cached = _cluster_store.reuse(
                _cl_unit, _cl_fp, cache=_cluster_cache
            )
            if _cl_cached is not None and isinstance(
                _cl_cached.get("authored"), dict
            ):
                authored = dict(_cl_cached["authored"])
                _modules_reused += 1
        if authored is None:
            authored = provider.author_terminal_for_cluster(
                cluster_cos, course_name=course_name, cluster_index=m_idx
            )
            if authored is not None and _cluster_store.enabled:
                _cluster_store.append(
                    _cl_unit, _cl_fp, {"authored": dict(authored)}
                )
        if authored is None:
            # §A step 4 — deterministic module-titled fallback (never invents;
            # the verb is the members' most-common Bloom verb).
            authored = _fallback_terminal_from_cluster(cluster_cos)
            authored["statement"] = (
                f"{_most_common_bloom_verb(cluster_cos)} the concepts and "
                f"skills of {module_title}."
            )
            authored["to_synthesis"] = "chapter_anchor_fallback"
        authored["id"] = mint_lo_id("terminal", m_idx)
        # Stamp the anchor provenance on every TO (§A step 4).
        authored["anchor_module_id"] = module_id
        authored["anchor_module_title"] = module_title
        terminals.append(authored)

        # Set terminal_id on members in-loop + union their cited chunks for the
        # TerminalObjectiveSourceGroundingValidator parity (§A step 5).
        _cluster_chunk_ids: List[str] = []
        _seen_chunk_ids: set = set()
        for i in member_idxs:
            chapter_cos[i]["terminal_id"] = authored["id"]
            _raw = chapter_cos[i].get("source_chunk_ids")
            if isinstance(_raw, list):
                for _ch in _raw:
                    _cs = str(_ch).strip()
                    if _cs and _cs not in _seen_chunk_ids:
                        _seen_chunk_ids.add(_cs)
                        _cluster_chunk_ids.append(_cs)
        to_source_chunk_assignments[authored["id"]] = _cluster_chunk_ids

    cluster_signals: Dict[str, Any] = {
        "to_derivation": "chapter_anchored",
        "chapter_anchor_modules": len(groups),
        "chapter_anchor_ties": result.ties,
        "chapter_anchor_multi_module_cos": result.multi_module_cos,
        "chapter_anchor_unresolved_cos": len(result.unresolved_co_indices),
        "to_source_chunk_assignments": to_source_chunk_assignments,
        "to_clusters_reused_from_checkpoint": _modules_reused,
    }
    if _modules_reused:
        logger.info(
            "plan_course_structure: chapter-anchored TO derivation reused "
            "%d/%d module TO(s) from sidecar (skipped their 7B author calls).",
            _modules_reused, len(groups),
        )
    if capture is not None:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"chapter_anchored_tos:{len(groups)} module(s) -> "
                    f"{len(terminals)} TO(s) over {len(chapter_cos)} CO(s)"
                ),
                rationale=(
                    "Defect-A chapter-anchored TO derivation: assigned "
                    f"{len(chapter_cos)} CO(s) to {result.n_modules} DART "
                    "module(s) (one staged HTML == one chapter) by cited-chunk "
                    f"plurality (coverage={result.co_coverage:.3f}, "
                    f"{result.ties} tie(s), {result.multi_module_cos} "
                    "multi-module, "
                    f"{len(result.unresolved_co_indices)} zero-resolve), then "
                    f"authored one book-ordered TO per module ({len(groups)} "
                    "non-empty) via the existing per-cluster 7B author call + "
                    "resume sidecar — recovering the chapter grain the bottom-up "
                    "statement clustering scattered."
                ),
                alternatives_considered=[
                    "bottom-up statement clustering (scatters a chapter's COs "
                    "across theme clusters — Defect A prerequisite inversions)",
                ],
            )
        except Exception:  # noqa: BLE001 — capture must not break derivation
            pass

    return terminals, cluster_signals


def _rehome_unresolved_by_cosine(
    chapter_cos: List[Dict[str, Any]],
    assignment: Dict[int, str],
    unresolved_idxs: List[int],
    embed: Any,
) -> None:
    """Re-home zero-resolve COs to the module of their nearest resolved CO.

    Mutates ``assignment`` in place. ``unresolved_idxs`` COs have no cited-chunk
    module vote; each is re-pointed to the module of the resolved CO with the
    highest statement cosine (a strictly better home than the last-module
    default). A no-op when there is no resolved CO to compare against.
    """
    import numpy as np

    unresolved_set = set(unresolved_idxs)
    resolved_idxs = [i for i in range(len(chapter_cos)) if i not in unresolved_set]
    if not resolved_idxs:
        return

    def _stmt(i: int) -> str:
        c = chapter_cos[i]
        return str(c.get("statement") or c.get("text") or "").strip() or " "

    all_idxs = resolved_idxs + list(unresolved_idxs)
    vecs = np.asarray(embed.encode_batch([_stmt(i) for i in all_idxs]), dtype=float)
    norms = np.linalg.norm(vecs, axis=1, keepdims=True)
    norms[norms == 0] = 1.0
    unit = vecs / norms
    n_res = len(resolved_idxs)
    res_unit = unit[:n_res]
    for local, co_idx in enumerate(unresolved_idxs):
        sims = res_unit @ unit[n_res + local]
        best_local = int(np.argmax(sims))
        assignment[co_idx] = assignment[resolved_idxs[best_local]]


# ---------------------------------------------------------------------------
# Stage-2 per-window resume checkpoint sidecar.
# ---------------------------------------------------------------------------
#
# A full-book ``course_planning`` phase dispatches one (expensive, minutes-long)
# 7B ``synthesize_window_objectives`` call per chunk-window. A kill / timeout
# mid-phase historically lost EVERY completed window (candidates lived only in
# memory), so a resume re-ran the whole ~20-minute set. This sidecar mirrors the
# training-synthesis ``.synthesis_pairs_checkpoint.jsonl`` per-item resume
# contract: each successful window flushes one JSONL record carrying its
# synthesized candidate objectives + a deterministic WINDOW FINGERPRINT. On
# phase re-entry a record is REUSED only when its fingerprint matches the
# recomputed one for the same (chapter_id, window_index); any mismatch (changed
# chunkset / chunk text / draft block / model / num_ctx / system prompt) silently
# re-runs that window — a changed input therefore invalidates the whole cache
# (correct). Default ON; site override ``ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT``
# > the family ``ED4ALL_GENERATION_CHECKPOINT`` flag (parse-with-fallback). The
# sidecar lives in the phase's OUTPUT dir (``01_learning_objectives/``), which
# the workflow ``--resume`` path reuses verbatim (the same dir the phase already
# reads ``textbook_structure.json`` from), so it survives resume.
#
# The mechanism is the shared fingerprinted unit-checkpoint store
# (``lib/generation/llm_checkpoint.py``); the helpers below are thin site
# wrappers preserving the stage-2 record shape + call signatures.
from lib.generation.llm_checkpoint import (  # noqa: E402
    SCHEMA_VERSION as _LLM_CHECKPOINT_SCHEMA_VERSION,
    CheckpointStore as _LlmCheckpointStore,
    checkpoint_enabled as _llm_checkpoint_enabled,
    compute_fingerprint as _llm_compute_fingerprint,
    hash_text as _llm_hash_text,
)
from lib.generation.stop_control import (  # noqa: E402
    GLOBAL_SENTINEL_NAME as _STOP_GLOBAL_SENTINEL_NAME,
    RUN_SENTINEL_NAME as _STOP_RUN_SENTINEL_NAME,
    STOP_MARKER,
    GracefulStopRequested,
    check_stop,
    stop_requested,
)

_OBJECTIVE_SYNTHESIS_CHECKPOINT_ENV = "ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT"
_STAGE2_WINDOWS_CHECKPOINT_NAME = ".stage2_windows_checkpoint.jsonl"
_STAGE2_CLUSTERS_CHECKPOINT_NAME = ".stage2_clusters_checkpoint.jsonl"
_STAGE2_CHECKPOINT_SCHEMA_VERSION = _LLM_CHECKPOINT_SCHEMA_VERSION


def _stage2_window_store(path: Optional[Path]) -> _LlmCheckpointStore:
    return _LlmCheckpointStore(
        path,
        site_id="stage2_windows",
        site_env=_OBJECTIVE_SYNTHESIS_CHECKPOINT_ENV,
    )


def _stage2_cluster_store(path: Optional[Path]) -> _LlmCheckpointStore:
    """Sidecar for the bottom-up per-cluster TO authoring (one 7B call each)."""
    return _LlmCheckpointStore(
        path,
        site_id="stage2_clusters",
        site_env=_OBJECTIVE_SYNTHESIS_CHECKPOINT_ENV,
    )


def _objective_synthesis_checkpoint_enabled() -> bool:
    """Stage-2 site gate: site flag (when set) > family flag; default ON."""
    return _llm_checkpoint_enabled(_OBJECTIVE_SYNTHESIS_CHECKPOINT_ENV)


def _planning_reroll_salt() -> str:
    """Per-attempt course_planning gate-retry re-roll salt.

    Set to ``attempt-N`` by ``WorkflowRunner._retry_course_planning_gates``
    before each gate-failure re-dispatch of the ``course_planning`` phase;
    empty on every normal run. Folded into the
    cluster-stage sidecar FINGERPRINT (both TO-derivation call sites) — and,
    independently, into the ``TextbookSynthesisProvider`` system prompt — so
    a retry attempt genuinely differs from the cached/previous attempt
    instead of reproducing byte-identical output. Empty → the fingerprint
    dicts carry no salt key (byte-identical to legacy).
    """
    return os.environ.get("ED4ALL_PLANNING_REROLL_SALT", "").strip()


def _planning_reroll_feedback() -> str:
    """Failure-directed remediation digest for the gate-retry loop.

    Set (alongside the salt) by
    ``WorkflowRunner._retry_course_planning_gates`` — a compact per-issue
    digest of the failing critical gates (``_planning_failure_digest``);
    empty on every normal run. Folded (as a hash) into the cluster-stage
    sidecar FINGERPRINT at both TO-derivation call sites — and,
    independently, into the ``TextbookSynthesisProvider`` system prompt as
    a delimited REMEDIATION section — so a retry attempt is DIRECTED at
    the observed failure modes and a changed digest never reuses a stale
    cached TO. Empty → no feedback key in the fingerprint dicts
    (byte-identical to legacy).
    """
    return os.environ.get("ED4ALL_PLANNING_REROLL_FEEDBACK", "").strip()


def _stage2_window_key(chapter_id: str, window_index: int) -> str:
    return f"{chapter_id}#w{int(window_index)}"


def _stage2_window_fingerprint(
    *,
    chunk_ids: List[Any],
    chunks: List[Dict[str, Any]],
    draft_block: str,
    model: str,
    num_ctx: int,
    system_prompt: str,
    heading_skeleton: str = "",
    window_mode: str = "",
    max_candidates: Optional[int] = None,
) -> str:
    """Deterministic fingerprint of a stage-2 window's synthesis inputs.

    Hashes over (sorted chunk ids, the window chunk texts, the shared draft-TO
    block, the model id, the resolved ``num_ctx``, and the synthesis system
    prompt) so ANY change to what the model would see re-runs the window on
    resume. The chunk texts are the truncated bodies fed to the model (the
    ``window['chunks'][*]['text']`` render input), so a re-chunk that changes a
    body invalidates the cache even when the id set is unchanged.

    ``heading_skeleton`` (``ED4ALL_SYNTHESIS_SKELETON``): the rendered per-window
    chapter heading skeleton the provider injects into the prompt. When empty
    (flag off / no chapter) NO key is added → the fingerprint dict is
    byte-identical to legacy. When non-empty its hash is folded in, so flipping
    the flag (or changing textbook_structure) invalidates the window resume
    sidecar and those windows re-run on ``--resume`` — mirroring the
    ``ED4ALL_OBJECTIVE_SEED_SANITIZE`` window-render-fingerprint contract.

    ``window_mode`` (``ED4ALL_OBJECTIVE_WINDOW_PER_SECTION``): the window-build
    mode tag (``"per_section:<label>"``) folded in only when non-empty, so a
    resume never serves a chapter-packed sidecar to a per-section run (or vice
    versa). ``max_candidates`` (``ED4ALL_OBJECTIVE_WINDOW_MAX_CANDIDATES``):
    the per-window candidate budget, folded in only when not ``None`` — a
    budget change re-rolls the window (the "1-N" line is user-prompt text the
    legacy fingerprint never saw). Both default-absent → byte-identical legacy
    fingerprints.
    """
    _text_parts: List[str] = []
    for _c in chunks:
        if isinstance(_c, dict):
            _text_parts.append(
                f"{_c.get('id')}\x1f{_c.get('text')}"
            )
    _fp_inputs: Dict[str, Any] = {
        "v": _STAGE2_CHECKPOINT_SCHEMA_VERSION,
        "chunk_ids": sorted(str(c) for c in (chunk_ids or [])),
        "chunk_texts_sha": _llm_hash_text("\x1e".join(_text_parts)),
        "draft_block": draft_block,
        "model": model,
        "num_ctx": int(num_ctx),
        "system_prompt_sha": _llm_hash_text(system_prompt or ""),
    }
    # Empty → no key (byte-identical legacy fingerprint); non-empty → folded in.
    if heading_skeleton:
        _fp_inputs["heading_skeleton_sha"] = _llm_hash_text(heading_skeleton)
    # Default-absent → no key (byte-identical legacy fingerprint).
    if window_mode:
        _fp_inputs["window_mode"] = str(window_mode)
    if max_candidates is not None:
        _fp_inputs["max_candidates"] = int(max_candidates)
    return _llm_compute_fingerprint(_fp_inputs)


def _load_stage2_windows_checkpoint(
    path: Optional[Path],
) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """Tolerant loader for the stage-2 per-window resume sidecar.

    Returns a ``{(chapter_id, window_index): record}`` map (last-line-wins,
    torn-trailing-line tolerant — the shared store's contract). A missing /
    unreadable sidecar returns an empty map (first-run case).
    """
    out: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for rec in _stage2_window_store(path).load().values():
        cid = rec.get("chapter_id")
        if not isinstance(cid, str):
            continue
        try:
            widx = int(rec.get("window_index"))
        except (TypeError, ValueError):
            continue
        out[(cid, widx)] = rec
    return out


def _append_stage2_window_checkpoint(
    path: Optional[Path],
    *,
    chapter_id: str,
    window_index: int,
    fingerprint: str,
    candidate_objectives: List[Dict[str, Any]],
) -> None:
    """Append one completed-window record to the sidecar with flush+fsync.

    Best-effort (the shared store's contract): an OSError only costs a re-run
    of that one window on resume. No-op when ``path`` is None or the site /
    family flag is off.
    """
    _stage2_window_store(path).append(
        _stage2_window_key(chapter_id, window_index),
        fingerprint,
        {
            "chapter_id": chapter_id,
            "window_index": int(window_index),
            "candidate_objectives": candidate_objectives,
        },
    )


# ---------------------------------------------------------------------------
# course_planning Stage-2 chapter_fallback per-chapter resume checkpoint (P4).
#
# The chunk_window path (above) checkpoints per WINDOW; the legacy
# chapter_fallback path (chunkset missing) dispatches one 7B call per CHAPTER
# via ``synthesize_chapter_objectives``. Same fingerprinted-JSONL contract as
# the window sidecar, unit = one CHAPTER (keyed by ``chapter_id``). On resume a
# completed chapter's candidate objectives splice back into ``_flat_candidates``
# in ORIGINAL chapter order (byte-equivalent to an uninterrupted run); any
# change to what the model saw — the bounded chapter_text, the course name, the
# shared draft-TO block, the model id, the resolved num_ctx, or the synthesis
# system prompt — flips the fingerprint and re-runs that chapter. Default ON via
# the shared ``ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT`` > family flag. The sidecar
# lives in the SAME phase OUTPUT dir as the window sidecar (a sibling file).
_STAGE2_CHAPTER_FALLBACK_CHECKPOINT_NAME = (
    ".stage2_chapter_fallback_checkpoint.jsonl"
)


def _stage2_chapter_fallback_store(path: Optional[Path]) -> _LlmCheckpointStore:
    """Sidecar for the legacy per-chapter fallback authoring (one call each)."""
    return _LlmCheckpointStore(
        path,
        site_id="stage2_chapter_fallback",
        site_env=_OBJECTIVE_SYNTHESIS_CHECKPOINT_ENV,
    )


def _stage2_chapter_fallback_fingerprint(
    *,
    chapter_text: str,
    course_name: str,
    draft_block: str,
    model: str,
    num_ctx: int,
    system_prompt: str,
) -> str:
    """Deterministic fingerprint of a chapter_fallback chapter's inputs.

    Hashes over the bounded chapter prose the model actually sees plus every
    other axis that changes the per-chapter synthesis output (course name, the
    shared draft-TO block, model id, resolved num_ctx, synthesis system prompt).
    A re-extract that changes the chapter_text invalidates the cache even when
    the chapter id is unchanged.
    """
    return _llm_compute_fingerprint({
        "v": _STAGE2_CHECKPOINT_SCHEMA_VERSION,
        "chapter_text_sha": _llm_hash_text(chapter_text or ""),
        "course_name": course_name or "",
        "draft_block": draft_block or "",
        "model": model or "",
        "num_ctx": int(num_ctx),
        "system_prompt_sha": _llm_hash_text(system_prompt or ""),
    })


def _load_stage2_chapter_fallback_checkpoint(
    path: Optional[Path],
) -> Dict[str, Dict[str, Any]]:
    """Tolerant loader for the chapter_fallback resume sidecar.

    Returns a ``{chapter_id: record}`` map (last-line-wins, torn-trailing-line
    tolerant — the shared store's contract). A missing / unreadable sidecar
    returns an empty map (first-run case).
    """
    out: Dict[str, Dict[str, Any]] = {}
    for rec in _stage2_chapter_fallback_store(path).load().values():
        cid = rec.get("chapter_id")
        if isinstance(cid, str) and cid:
            out[cid] = rec
    return out


def _append_stage2_chapter_fallback_checkpoint(
    path: Optional[Path],
    *,
    chapter_id: str,
    fingerprint: str,
    chapter_objectives: List[Dict[str, Any]],
) -> None:
    """Append one completed-chapter record to the sidecar with flush+fsync.

    Best-effort (the shared store's contract): an OSError only costs a re-run
    of that one chapter on resume. No-op when ``path`` is None or the site /
    family flag is off.
    """
    _stage2_chapter_fallback_store(path).append(
        chapter_id,
        fingerprint,
        {
            "chapter_id": chapter_id,
            "chapter_objectives": chapter_objectives,
        },
    )


# ---------------------------------------------------------------------------
# W10 assessment_synthesis per-unit resume checkpoint (P4).
#
# The ``assessment_synthesis`` phase runs three sequential per-TERMINAL-OBJECTIVE
# loops (quiz / discussion / assignment), then a single atomic end-write
# (``_write_assessment_artifacts`` → ``06_assessments/manifest.json`` + XML).
# ONE fingerprinted-JSONL sidecar covers all three, keyed on the composite unit
# ``(kind, terminal_id)``; on resume a completed unit is REPLAYED from the
# sidecar and its generation (the quiz ``AssessmentGenerator.generate`` call or
# the prose ``_synthesize_prose_prompt`` LLM dispatch) is SKIPPED. The stored
# quiz payload is the assessment's ``to_dict()`` form, which flows through
# ``_build_assessment_artifacts_from_data`` / ``assessment_to_qti`` identically
# to the live dataclass (both serialize via ``to_dict()`` before XML emit), so
# the emitted artifacts are byte-identical to an uninterrupted run. The fingerprint
# captures the TO statement, the chunkset sha, the provider/model, the prompt
# version, and per-kind knobs (bloom levels / question count for quizzes) so any
# change re-runs the affected unit. Family-flag-only (``site_env=None``); default
# ON. The sidecar lives in the phase OUTPUT dir ``<export>/06_assessments/`` and
# is removed only AFTER the manifest write succeeds (a stop raises before that
# write, so the sidecar survives for the resume).
_ASSESSMENTS_CHECKPOINT_NAME = ".assessments_checkpoint.jsonl"
# v2: relationship-template clause-grab fix (term-like concept guard +
# relationship/procedure/example rotation) + footnote-apparatus strip changed
# what the deterministic generator emits — invalidate pre-fix quiz sidecars so
# a resumed run re-rolls under the fixed templater instead of replaying salad.
_ASSESSMENT_PROMPT_VERSION = "v2"


def _assessments_store(path: Optional[Path]) -> _LlmCheckpointStore:
    return _LlmCheckpointStore(
        path,
        site_id="assessment_synthesis",
        site_env=None,
    )


def _assessment_unit_key(kind: str, terminal_id: str) -> str:
    return f"{kind}#{terminal_id}"


def _assessment_chunkset_sha(chunks: List[Dict[str, Any]]) -> str:
    """sha over the loaded chunks' (id, text) so a re-chunk re-runs the units."""
    parts: List[str] = []
    for c in chunks:
        if isinstance(c, dict):
            cid = c.get("id") or c.get("chunk_id") or ""
            parts.append(f"{cid}\x1f{c.get('text') or ''}")
    return _llm_hash_text("\x1e".join(parts))


def _assessment_unit_fingerprint(
    *,
    kind: str,
    terminal_id: str,
    statement: str,
    chunkset_sha: str,
    provider: str,
    model: str,
    prompt_version: str,
    knobs: str = "",
) -> str:
    """Deterministic fingerprint of one (kind, terminal_id) assessment unit."""
    return _llm_compute_fingerprint({
        "v": _LLM_CHECKPOINT_SCHEMA_VERSION,
        "kind": kind,
        "terminal_id": terminal_id,
        "statement_sha": _llm_hash_text(statement or ""),
        "chunkset_sha": chunkset_sha or "",
        "provider": provider or "",
        "model": model or "",
        "prompt_version": prompt_version or "",
        "knobs": knobs or "",
    })


# ---------------------------------------------------------------------------
# concept_extraction Stage-3 per-window resume checkpoint.
#
# Same fingerprinted-JSONL unit-checkpoint contract as the stage-2 window
# sidecar above (``lib/generation/llm_checkpoint.py``), applied to the
# ``concept_extraction`` phase's Stage-3 ``synthesize_concepts`` dispatch loop.
# The natural unit of one 7B call there is one WINDOW (one per-window pseudo-
# chapter), so the sidecar keys on ``(chapter_id, window_index)`` and caches
# that window's synthesized ``concepts[]`` list. On phase re-entry a record is
# REUSED only when its stored fingerprint matches the recomputed one for the
# same window; any change to what the model saw (chunk id set / joined window
# text / course name / model / num_ctx / max_tokens / system prompt) silently
# re-runs that window. Default ON; site override
# ``ED4ALL_CONCEPT_EXTRACTION_CHECKPOINT`` > the family
# ``ED4ALL_GENERATION_CHECKPOINT`` flag (parse-with-fallback). The sidecar
# lives in the phase's OUTPUT dir (``<libv2>/courses/<slug>/concept_graph/``,
# the same dir the phase writes ``concept_graph_semantic.json`` +
# ``domain_concept_vocabulary.json`` into) so a workflow ``--resume`` finds it.
_CONCEPT_EXTRACTION_CHECKPOINT_ENV = "ED4ALL_CONCEPT_EXTRACTION_CHECKPOINT"
_CONCEPT_EXTRACTION_CHECKPOINT_NAME = ".concept_extraction_checkpoint.jsonl"


def _concept_extraction_store(path: Optional[Path]) -> _LlmCheckpointStore:
    return _LlmCheckpointStore(
        path,
        site_id="concept_extraction",
        site_env=_CONCEPT_EXTRACTION_CHECKPOINT_ENV,
    )


def _concept_extraction_checkpoint_enabled() -> bool:
    """Stage-3 site gate: site flag (when set) > family flag; default ON."""
    return _llm_checkpoint_enabled(_CONCEPT_EXTRACTION_CHECKPOINT_ENV)


def _concept_window_key(chapter_id: str, window_index: int) -> str:
    return f"{chapter_id}#w{int(window_index)}"


def _concept_window_fingerprint(
    *,
    chapter_id: str,
    window_index: int,
    chunk_ids: List[Any],
    chapter_text: str,
    course_name: str,
    model: str,
    num_ctx: int,
    max_tokens: int,
    system_prompt: str,
) -> str:
    """Deterministic fingerprint of a Stage-3 window's synthesis inputs.

    Hashes over EVERYTHING the model sees for that ``synthesize_concepts``
    call: the window's real chapter id, its window index, the sorted chunk-id
    set, the joined window CHUNK TEXT (the ``chapter_text`` field the provider
    renders — a re-chunk that changes a body invalidates the cache even when
    the id set is unchanged), the course name (prompt-interpolated), the model
    id, the resolved ``num_ctx`` + ``max_tokens`` serving-window knobs, and the
    synthesis system prompt. Any change to any axis re-runs the window.
    """
    return _llm_compute_fingerprint({
        "v": _STAGE2_CHECKPOINT_SCHEMA_VERSION,
        "chapter_id": str(chapter_id),
        "window_index": int(window_index),
        "chunk_ids": sorted(str(c) for c in (chunk_ids or [])),
        "chapter_text_sha": _llm_hash_text(chapter_text or ""),
        "course_name": str(course_name or ""),
        "model": str(model or ""),
        "num_ctx": int(num_ctx),
        "max_tokens": int(max_tokens),
        "system_prompt_sha": _llm_hash_text(system_prompt or ""),
    })


def _load_concept_windows_checkpoint(
    path: Optional[Path],
) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """Tolerant loader for the Stage-3 per-window resume sidecar.

    Returns a ``{(chapter_id, window_index): record}`` map (last-line-wins,
    torn-trailing-line tolerant — the shared store's contract). A missing /
    unreadable sidecar returns an empty map (first-run case).
    """
    out: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for rec in _concept_extraction_store(path).load().values():
        cid = rec.get("chapter_id")
        if not isinstance(cid, str):
            continue
        try:
            widx = int(rec.get("window_index"))
        except (TypeError, ValueError):
            continue
        out[(cid, widx)] = rec
    return out


def _append_concept_window_checkpoint(
    path: Optional[Path],
    *,
    chapter_id: str,
    window_index: int,
    fingerprint: str,
    concepts: List[Dict[str, Any]],
) -> None:
    """Append one completed-window record to the sidecar with flush+fsync.

    Best-effort (the shared store's contract): an OSError only costs a re-run
    of that one window on resume. No-op when ``path`` is None or the site /
    family flag is off.
    """
    _concept_extraction_store(path).append(
        _concept_window_key(chapter_id, window_index),
        fingerprint,
        {
            "chapter_id": chapter_id,
            "window_index": int(window_index),
            "concepts": concepts,
        },
    )


def _drop_apparatus_seeded_candidates(
    pool: List[Dict[str, Any]],
    capture: Optional[Any] = None,
) -> List[Dict[str, Any]]:
    """Defect-C backstop: drop Pass-C survivors whose STATEMENT is apparatus text.

    A candidate objective whose ``statement`` matches any exercise-/practice-
    apparatus marker from the shared lexicon profile (``lib/objectives/
    apparatus_lexicon.compile_profile``) is a seed the window sanitation missed
    (or a chapter-fallback candidate that never saw window prep). Drop it
    pre-dedup so a non-instructional banner never becomes a canonical CO.

    keep-≥1 protection: when EVERY candidate is flagged, the longest-statement
    one is rescued so the pool is never emptied (the deterministic synthesizer
    fallback only fires on a genuinely empty pool). Order is preserved. Emits one
    ``content_selection`` decision with dynamic counts. Caller gates on the flag.
    """
    if not pool:
        return pool
    from lib.objectives.apparatus_lexicon import compile_profile

    profile = compile_profile()
    flagged: set = set()
    for i, co in enumerate(pool):
        if not isinstance(co, dict):
            continue
        stmt = str(co.get("statement") or "").strip()
        # Statement-scoped matcher: callout labels ("how to", "learning
        # objectives") are legitimate statement English and never flag.
        if stmt and profile.statement_has_apparatus_marker(stmt):
            flagged.add(i)
    if not flagged:
        return pool
    # keep-≥1: if all candidates are flagged, rescue the longest-statement one.
    if len(flagged) == len(pool):
        rescue_i = max(
            range(len(pool)),
            key=lambda i: len(str(pool[i].get("statement") or "")),
        )
        flagged.discard(rescue_i)
    kept = [co for i, co in enumerate(pool) if i not in flagged]
    dropped_count = len(flagged)
    if dropped_count and capture is not None:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"apparatus_seed_backstop:dropped {dropped_count} of "
                    f"{len(pool)} Pass-C survivor objective(s)"
                ),
                rationale=(
                    "Defect-C apparatus-seed backstop: "
                    f"{dropped_count} of {len(pool)} Pass-C survivor objective "
                    "statement(s) matched an exercise-/practice-apparatus marker "
                    "from the shared lexicon profile (e.g. 'In the following "
                    "exercises' / 'Practice Makes Perfect' / readiness-quiz "
                    "banners / answer-key glyphs) and were dropped pre-dedup so a "
                    "non-instructional exercise banner never seeds a canonical "
                    "CO. keep->=1 protection retained the longest-statement "
                    "candidate when every survivor was flagged so the pool is "
                    "never emptied."
                ),
                alternatives_considered=[
                    "keep the apparatus-seeded survivors (a 'In the following "
                    "exercises' banner becomes a vacuous canonical CO)",
                    "drop unconditionally (risks emptying a window's pool when "
                    "every survivor is apparatus text)",
                ],
            )
        except Exception:  # noqa: BLE001 — capture must not break synthesis
            pass
    return kept


async def _run_stage2_window_synthesis(
    *,
    provider: Any,
    provider_error: type,
    chapters: List[Dict[str, Any]],
    draft_tos: List[Dict[str, Any]],
    chunks_by_id: Dict[str, Any],
    all_chunks: List[Dict[str, Any]],
    grounding_mode: str,
    course_name: str,
    provider_env: str,
    chapter_synthesis_failures: List[str],
    mint_lo_id: Any,
    kwargs: Dict[str, Any],
    capture: Optional[Any] = None,
    checkpoint_path: Optional[Path] = None,
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], str, Dict[str, Any]]:
    """W2 §1.6 + §4.4 — orchestrate Pass B → C → D → E.

    ``grounding_mode == "chunk_window"`` (chunkset present): per-WINDOW dispatch
    (``synthesize_window_objectives``) collects candidates with cited
    ``source_chunk_ids``, then Pass C (NLI filter, drops ungrounded) + Pass D
    (embedding dedup). ``grounding_mode == "chapter_fallback"`` (chunkset
    missing): the legacy per-CHAPTER dispatch path
    (``synthesize_chapter_objectives``) — candidates carry empty
    ``source_chunk_ids``; Pass C runs advisory-only (nothing dropped, since there
    are no chunks to ground against) and Pass D still collapses dupes.

    CO-NN ids are minted AFTER Pass C + D over the survivors. Then one
    reconciliation call (fail-loud on exhaustion) and the deterministic CO→TO
    backlink (Pass E). Returns ``(chapter_cos, terminal_tos, mint_method,
    grounding_signals)``; ``([], [], "", {})``-shaped empties on an all-fail so
    the caller falls through to the deterministic synthesizer.
    """
    import asyncio as _asyncio

    from lib.objectives.chunk_window import (
        chunks_for_chapter,
        group_chunks_into_section_windows,
        group_chunks_into_windows,
        resolve_seed_sanitize,
        resolve_window_per_section,
    )
    from lib.objectives.objective_grounding import ground_candidates
    from lib.objectives.objective_dedup import dedup_candidates
    from lib.ontology.lo_backlink import backlink_cos_to_tos
    from Courseforge.generators._textbook_synthesis_provider import (
        _SYNTHESIS_NUM_CTX_ENV,
        _TEXTBOOK_SYNTHESIS_SYSTEM_PROMPT,
    )
    from lib.retrieval._prompts import resolve_num_ctx
    from lib.embedding.providers import (
        EmbeddingBackendUnavailable,
        allow_fake_enabled,
        build_embedding_client,
    )

    # Real (un-patchable) run-scoped stop-sentinel probe for the rolling-window
    # DISPATCH BOUNDARY. Referenced through the module so it stays distinct from
    # the module-global ``stop_requested`` an in-flight ``_one_window`` consults
    # (the P3.0 marker path) — mirroring the legacy check_stop/_one_window split.
    from lib.generation import stop_control as _stop_control
    _loop = _asyncio.get_running_loop()
    candidates_synthesized = 0
    _flat_candidates: List[Dict[str, Any]] = []
    # Per-window resume-checkpoint counters (0 on the chapter_fallback path).
    _windows_total = 0
    _windows_reused = 0

    # Draft-TO grounding block shared per chapter (statements only).
    _draft_block_lines = [
        f"  - {str(d.get('statement') or '').strip()}"
        for d in draft_tos
        if isinstance(d, dict) and str(d.get("statement") or "").strip()
    ]
    _draft_block = "\n".join(_draft_block_lines) if _draft_block_lines else "  (none)"

    if grounding_mode == "chunk_window":
        # ---- Pass B: per-window dispatch. -----------------------------
        _num_ctx_env = os.environ.get(_SYNTHESIS_NUM_CTX_ENV)
        _num_ctx = resolve_num_ctx()
        if _num_ctx_env:
            try:
                _maybe = int(_num_ctx_env)
                if _maybe > 0:
                    _num_ctx = _maybe
            except (TypeError, ValueError):
                pass
        _max_tokens = int(getattr(provider, "_max_tokens", 4096) or 4096)

        # Vendor-depth per-SECTION windows (ED4ALL_OBJECTIVE_WINDOW_PER_SECTION,
        # default OFF): one stage-2 map unit per textbook_structure SECTION
        # instead of chapter-greedy packing. The resolved candidate budget
        # (ED4ALL_OBJECTIVE_WINDOW_MAX_CANDIDATES; 12 in per-section mode) is
        # folded into the window fingerprint below so a mode/budget flip never
        # serves a cross-mode resume sidecar.
        _per_section = resolve_window_per_section()
        _max_cands: Optional[int] = None
        try:
            from Courseforge.generators._textbook_synthesis_provider import (
                resolve_window_max_candidates as _resolve_window_max_cands,
            )
            _max_cands = _resolve_window_max_cands()
        except Exception:  # noqa: BLE001 — budget resolver is best-effort
            _max_cands = None

        # Build the flat ordered window list across all chapters, annotating
        # joined chunks with their chapter_id for Pass C's rescue pool.
        _windows: List[Dict[str, Any]] = []
        _dropped_chunks = 0
        _joined_ids = set()
        for chapter in chapters:
            chapter_chunks, join_method = chunks_for_chapter(
                chapter, all_chunks, all_chapters=chapters,
            )
            cid = str(chapter.get("id") or "")
            for ck in chapter_chunks:
                _cid = str(ck.get("id") or ck.get("chunk_id") or "")
                if _cid:
                    _joined_ids.add(_cid)
                    # Annotate the in-memory chunk record for the rescue pool.
                    rec = chunks_by_id.get(_cid)
                    if isinstance(rec, dict):
                        rec.setdefault("chapter_id", cid)
            _window_builder = (
                group_chunks_into_section_windows
                if _per_section
                else group_chunks_into_windows
            )
            ch_windows = _window_builder(
                chapter,
                chapter_chunks,
                num_ctx=_num_ctx,
                system_prompt=_TEXTBOOK_SYNTHESIS_SYSTEM_PROMPT,
                draft_block=_draft_block,
                max_tokens=_max_tokens,
                join_method=join_method,
            )
            for w in ch_windows:
                _windows.append(w.to_dict())
        if _per_section:
            logger.info(
                "plan_course_structure: Stage-2 per-SECTION window mode ON "
                "(ED4ALL_OBJECTIVE_WINDOW_PER_SECTION) — %d window(s) across "
                "%d chapter(s); candidate budget/window=%s.",
                len(_windows), len(chapters),
                _max_cands if _max_cands is not None else "legacy(1-3)",
            )
        _dropped_chunks = len(all_chunks) - len(_joined_ids)
        if _dropped_chunks > 0:
            logger.info(
                "plan_course_structure: %d/%d DART chunk(s) matched no "
                "chapter (dropped from the window map).",
                _dropped_chunks, len(all_chunks),
            )

        def _one_window(window_dict: Dict[str, Any]) -> Optional[Dict[str, Any]]:
            label = (
                f"{window_dict.get('chapter_id')}"
                f"#w{window_dict.get('window_index')}"
            )
            # Graceful stop (P3.0 marker pattern): a stop armed WHILE this batch
            # is in flight refuses a not-yet-started window by RETURNING
            # STOP_MARKER — never raising. A raise would propagate through
            # asyncio.gather (no return_exceptions) before the post-gather
            # append loop runs, losing every already-completed window in this
            # batch. In-flight calls finish; the caller appends them, skips
            # markers, then raises GracefulStopRequested.
            if stop_requested():
                return STOP_MARKER
            try:
                return provider.synthesize_window_objectives(
                    window_dict,
                    course_name=course_name,
                    draft_terminal_objectives=draft_tos,
                )
            except provider_error as exc:
                logger.warning(
                    "plan_course_structure: Stage-2 window %s exhausted "
                    "(%s); degrading per §5.4.", label, exc,
                )
                return None
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "plan_course_structure: Stage-2 window %s raised (%s); "
                    "degrading per §5.4.", label, exc,
                )
                return None

        # ---- Per-window resume checkpoint (default ON). ----------------
        # Load any prior sidecar and partition windows into REUSE (fingerprint
        # matches a completed record) vs DISPATCH. The reuse splice keeps the
        # ORIGINAL window order so _flat_candidates is byte-equivalent to an
        # uninterrupted run.
        _windows_total = len(_windows)
        _cp_enabled = (
            checkpoint_path is not None
            and _objective_synthesis_checkpoint_enabled()
        )
        _cp_model = str(getattr(provider, "_model", "") or "")
        _cp_cache = (
            _load_stage2_windows_checkpoint(checkpoint_path)
            if _cp_enabled else {}
        )
        if _cp_cache:
            logger.info(
                "plan_course_structure: Stage-2 loaded %d checkpointed "
                "window record(s) from %s.",
                len(_cp_cache), checkpoint_path,
            )

        def _window_key(wd: Dict[str, Any]) -> Tuple[str, int]:
            try:
                _wi = int(wd.get("window_index") or 0)
            except (TypeError, ValueError):
                _wi = 0
            return (str(wd.get("chapter_id") or ""), _wi)

        # Structure-aware synthesis (ED4ALL_SYNTHESIS_SKELETON): the provider
        # renders the per-window chapter heading skeleton it injects into the
        # prompt. Folding it into the fingerprint makes a flag flip (or a
        # changed textbook_structure) invalidate the window resume sidecar so
        # those windows re-run on --resume. Empty when the flag is off → the
        # fingerprint stays byte-identical to legacy.
        _skeleton_fn = getattr(provider, "_build_window_heading_skeleton", None)
        _fp_by_key: Dict[Tuple[str, int], str] = {}
        _reused: Dict[Tuple[str, int], List[Dict[str, Any]]] = {}
        _to_dispatch: List[Dict[str, Any]] = []
        for _wd in _windows:
            _key = _window_key(_wd)
            _wd_skeleton = ""
            if callable(_skeleton_fn):
                try:
                    _wd_skeleton = _skeleton_fn(
                        str(_wd.get("chapter_id") or "")
                    ) or ""
                except Exception:  # noqa: BLE001 — skeleton is best-effort
                    _wd_skeleton = ""
            _wd_mode = ""
            if _per_section:
                _wd_mode = (
                    f"per_section:{str(_wd.get('section_label') or '')}"
                )
            _fp = _stage2_window_fingerprint(
                chunk_ids=_wd.get("chunk_ids") or [],
                chunks=_wd.get("chunks") or [],
                draft_block=_draft_block,
                model=_cp_model,
                num_ctx=_num_ctx,
                system_prompt=_TEXTBOOK_SYNTHESIS_SYSTEM_PROMPT,
                heading_skeleton=_wd_skeleton,
                window_mode=_wd_mode,
                max_candidates=_max_cands,
            )
            _fp_by_key[_key] = _fp
            _rec = _cp_cache.get(_key) if _cp_enabled else None
            if isinstance(_rec, dict) and _rec.get("fingerprint") == _fp:
                _reused[_key] = [
                    c
                    for c in (_rec.get("candidate_objectives") or [])
                    if isinstance(c, dict)
                ]
            else:
                _to_dispatch.append(_wd)

        # Dispatch ONLY the un-cached windows, keyed by window. ROLLING WINDOW
        # (not a batch BARRIER): instead of gathering each batch of N and idling
        # the pool on the slowest window per batch, keep ``_width`` window
        # futures IN FLIGHT at all times and refill from the queue the instant
        # one resolves (``asyncio.wait(FIRST_COMPLETED)``). ``_width`` is the
        # provider's configured batch size (still 10 by default, via
        # ``batch_chapters``) capped at the window count — the SAME effective
        # concurrency as the barrier, never raised. Each completed window is
        # appended to the sidecar AS ITS OWN FUTURE RESOLVES (finer than the old
        # per-batch append: a kill / power-loss mid-phase now only costs the
        # ``≤_width`` in-flight windows on resume, never a whole batch). Results
        # are keyed by window identity and reassembled in the ORIGINAL window
        # order below, so the emitted objectives are deterministic regardless of
        # completion order (the barrier's gather already could not guarantee
        # in-batch completion order — this reassembly always was key-based).
        _dispatched: Dict[Tuple[str, int], Optional[Dict[str, Any]]] = {}
        _batches = provider.batch_chapters(_to_dispatch)
        _width = max((len(_b) for _b in _batches), default=1)
        _queue = [_w for _b in _batches for _w in _b]
        _qi = 0
        _inflight: Dict[Any, Dict[str, Any]] = {}
        _stop_seen = False

        # Graceful stop (checkpoint on command). Two independent probes,
        # mirroring the legacy check_stop/_one_window split:
        #   * the DISPATCH-BOUNDARY probe below uses the REAL run-scoped sentinel
        #     (``_stop_control.stop_requested`` — NOT the module-global
        #     ``stop_requested`` an in-flight ``_one_window`` consults) before
        #     EVERY new submission, so no new window is dispatched once a stop is
        #     pending; and
        #   * a stop armed WHILE a window is in flight surfaces as a STOP_MARKER
        #     return from ``_one_window`` (the P3.0 marker pattern), skipped on
        #     drain so resume re-runs that not-attempted window.
        # On a stop we STOP submitting, let the in-flight windows finish +
        # checkpoint, then raise AFTER the drain — worst-case loss ``≤_width``
        # in-flight windows (unchanged from the barrier).
        while _qi < len(_queue) and len(_inflight) < _width:
            if _stop_control.stop_requested():
                _stop_seen = True
                break
            _w = _queue[_qi]
            _qi += 1
            _inflight[_loop.run_in_executor(None, _one_window, _w)] = _w

        while _inflight:
            _done, _ = await _asyncio.wait(
                set(_inflight), return_when=_asyncio.FIRST_COMPLETED
            )
            for _fut in _done:
                _wd = _inflight.pop(_fut)
                # ``_one_window`` fail-softs to None / STOP_MARKER — never raises.
                _res = _fut.result()
                _dkey = _window_key(_wd)
                if _res is STOP_MARKER:
                    # Not-attempted (stop refused pre-dispatch): skip append so
                    # resume re-runs it. Do NOT record in _dispatched.
                    _stop_seen = True
                    continue
                _dispatched[_dkey] = _res
                if _cp_enabled and _res is not None:
                    _append_stage2_window_checkpoint(
                        checkpoint_path,
                        chapter_id=_dkey[0],
                        window_index=_dkey[1],
                        fingerprint=_fp_by_key[_dkey],
                        candidate_objectives=[
                            _c
                            for _c in (_res.get("candidate_objectives") or [])
                            if isinstance(_c, dict)
                        ],
                    )
            # Refill to ``_width`` (each freshly-resolved window's sidecar append
            # above is already durable), probing the boundary stop before each.
            while (
                not _stop_seen
                and _qi < len(_queue)
                and len(_inflight) < _width
            ):
                if _stop_control.stop_requested():
                    _stop_seen = True
                    break
                _w = _queue[_qi]
                _qi += 1
                _inflight[_loop.run_in_executor(None, _one_window, _w)] = _w

        if _stop_seen:
            # Every window that COMPLETED before the stop is in _dispatched AND
            # checkpointed; not-attempted windows were never submitted (boundary
            # probe) or returned STOP_MARKER. Raise AFTER the drain so resume
            # re-runs only the un-attempted windows (P3.0).
            raise GracefulStopRequested("stage2_windows", len(_dispatched))

        # Reassemble candidates in ORIGINAL window order (byte-equivalent to an
        # uninterrupted run; the dispatch loop above already checkpointed each
        # freshly-dispatched window).
        # REAL-GROUNDING fix (opt-in): stamp each candidate with the REAL chunk
        # ids of the window it was synthesized from — the pool the model
        # actually SAW (Pass-B provenance) — so the later citation re-selection
        # can ground a candidate whose model-emitted citations are wholly
        # fabricated (topic-labels that resolve against nothing). Gated by
        # ``ED4ALL_OBJECTIVE_CITATION_RESELECT`` so it is byte-identical when
        # the reselect gate is off (nothing is stamped). Stamped AFTER the
        # window checkpoint append above, so the resume sidecar stays clean.
        from lib.objectives.citation_reselect import (
            resolve_citation_reselect as _resolve_reselect_gate,
        )
        _stamp_window_pool = _resolve_reselect_gate()

        _reused_per_chapter: Dict[str, int] = {}
        _total_per_chapter: Dict[str, int] = {}
        for _wd in _windows:
            _key = _window_key(_wd)
            _cid = _key[0]
            _label = f"{_cid}#w{_key[1]}"
            _wd_pool = (
                [str(c) for c in (_wd.get("chunk_ids") or [])]
                if _stamp_window_pool else None
            )
            _total_per_chapter[_cid] = _total_per_chapter.get(_cid, 0) + 1
            if _key in _reused:
                candidates_synthesized += 1
                _windows_reused += 1
                _reused_per_chapter[_cid] = _reused_per_chapter.get(_cid, 0) + 1
                _reused_cands = _reused[_key]
                if _wd_pool is not None:
                    for _c in _reused_cands:
                        if isinstance(_c, dict):
                            _c["_reselect_window_pool"] = list(_wd_pool)
                _flat_candidates.extend(_reused_cands)
                continue
            _res = _dispatched.get(_key)
            if _res is None:
                chapter_synthesis_failures.append(_label)
                continue
            candidates_synthesized += 1
            _cands = [
                _c
                for _c in (_res.get("candidate_objectives") or [])
                if isinstance(_c, dict)
            ]
            if _wd_pool is not None:
                for _c in _cands:
                    _c["_reselect_window_pool"] = list(_wd_pool)
            _flat_candidates.extend(_cands)

        for _cid, _tot in _total_per_chapter.items():
            _reused_n = _reused_per_chapter.get(_cid, 0)
            if _reused_n:
                logger.info(
                    "plan_course_structure: Stage-2 reused %d/%d window(s) "
                    "from sidecar for chapter %s (skipped their 7B calls).",
                    _reused_n, _tot, _cid,
                )
    else:
        # ---- chapter_fallback: legacy per-chapter dispatch. -----------
        # Per-chapter resume checkpoint (P4). Unit = one CHAPTER. Sidecar is a
        # sibling of the window sidecar in the phase OUTPUT dir; default ON via
        # the shared ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT > family flag. A
        # completed chapter's candidate objectives splice back into
        # _flat_candidates in ORIGINAL chapter order on resume.
        _cf_path = (
            checkpoint_path.parent / _STAGE2_CHAPTER_FALLBACK_CHECKPOINT_NAME
            if checkpoint_path is not None else None
        )
        _cf_num_ctx = resolve_num_ctx()
        _cf_model = str(getattr(provider, "_model", "") or "")
        _cf_enabled = (
            _cf_path is not None
            and _objective_synthesis_checkpoint_enabled()
        )
        _cf_cache = (
            _load_stage2_chapter_fallback_checkpoint(_cf_path)
            if _cf_enabled else {}
        )
        if _cf_cache:
            logger.info(
                "plan_course_structure: Stage-2 loaded %d checkpointed "
                "chapter_fallback record(s) from %s.",
                len(_cf_cache), _cf_path,
            )

        def _cf_fingerprint(chapter_dict: Dict[str, Any]) -> str:
            return _stage2_chapter_fallback_fingerprint(
                chapter_text=str(chapter_dict.get("chapter_text") or ""),
                course_name=course_name,
                draft_block=_draft_block,
                model=_cf_model,
                num_ctx=_cf_num_ctx,
                system_prompt=_TEXTBOOK_SYNTHESIS_SYSTEM_PROMPT,
            )

        # Partition chapters into REUSE (fingerprint matches a completed
        # record) vs DISPATCH.
        _cf_fp_by_id: Dict[str, str] = {}
        _cf_reused: Dict[str, List[Dict[str, Any]]] = {}
        _cf_to_dispatch: List[Dict[str, Any]] = []
        for _ch in chapters:
            _cid = str(_ch.get("id") or "")
            _fp = _cf_fingerprint(_ch)
            _cf_fp_by_id[_cid] = _fp
            _rec = _cf_cache.get(_cid) if _cf_enabled else None
            if isinstance(_rec, dict) and _rec.get("fingerprint") == _fp:
                _cf_reused[_cid] = [
                    c
                    for c in (_rec.get("chapter_objectives") or [])
                    if isinstance(c, dict)
                ]
            else:
                _cf_to_dispatch.append(_ch)

        def _one_chapter(chapter_dict: Dict[str, Any]) -> Optional[Dict[str, Any]]:
            cid = str(chapter_dict.get("id") or "")
            # Graceful stop (P3.0 marker pattern): a stop armed WHILE this batch
            # is in flight refuses a not-yet-started chapter by RETURNING
            # STOP_MARKER — never raising (a raise would propagate through
            # asyncio.gather before the post-gather append loop, losing every
            # already-completed chapter in this batch).
            if stop_requested():
                return STOP_MARKER
            try:
                return provider.synthesize_chapter_objectives(
                    chapter_dict,
                    course_name=course_name,
                    draft_terminal_objectives=draft_tos,
                )
            except provider_error as exc:
                logger.warning(
                    "plan_course_structure: Stage-2 chapter %r exhausted "
                    "(%s); degrading per §5.4.", cid, exc,
                )
                return None
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "plan_course_structure: Stage-2 chapter %r raised (%s); "
                    "degrading per §5.4.", cid, exc,
                )
                return None

        # Dispatch ONLY the un-cached chapters; append each completed chapter to
        # the sidecar AS ITS BATCH LANDS so a mid-phase kill only costs the
        # in-flight batch on resume.
        _cf_dispatched: Dict[str, Optional[Dict[str, Any]]] = {}
        _cf_stop_marker_seen = False
        _batches = provider.batch_chapters(_cf_to_dispatch)
        for _batch in _batches:
            # Graceful stop BETWEEN batches: every prior batch's completed
            # chapter is already appended, so this plain raise loses nothing
            # (mid-batch arming is handled by the STOP_MARKER return above).
            check_stop("stage2_chapter_fallback", len(_cf_dispatched))
            _results = await _asyncio.gather(*[
                _loop.run_in_executor(None, _one_chapter, ch) for ch in _batch
            ])
            for _chapter_dict, _res in zip(_batch, _results):
                _cid = str(_chapter_dict.get("id") or "")
                if _res is STOP_MARKER:
                    # Not-attempted (stop refused pre-dispatch): skip append so
                    # resume re-runs it. Do NOT record in _cf_dispatched.
                    _cf_stop_marker_seen = True
                    continue
                _cf_dispatched[_cid] = _res
                if _cf_enabled and _res is not None:
                    _append_stage2_chapter_fallback_checkpoint(
                        _cf_path,
                        chapter_id=_cid,
                        fingerprint=_cf_fp_by_id.get(_cid, ""),
                        chapter_objectives=[
                            _co
                            for _co in (_res.get("chapter_objectives") or [])
                            if isinstance(_co, dict)
                        ],
                    )
        if _cf_stop_marker_seen:
            # Every chapter that COMPLETED before the stop is in _cf_dispatched
            # AND checkpointed; the markers were never dispatched. Raise AFTER
            # the sidecar append so resume re-runs only the un-attempted
            # chapters (P3.0).
            raise GracefulStopRequested(
                "stage2_chapter_fallback", len(_cf_dispatched)
            )

        # Reassemble in ORIGINAL chapter order (reused + freshly dispatched).
        # The chapter path emits no source_chunk_ids; mark empty so Pass C
        # treats each CO as no_resolved_chunk.
        for _ch in chapters:
            _cid = str(_ch.get("id") or "")
            if _cid in _cf_reused:
                candidates_synthesized += 1
                for _co in _cf_reused[_cid]:
                    if isinstance(_co, dict):
                        _co.setdefault("source_chunk_ids", [])
                        _flat_candidates.append(_co)
                continue
            _res = _cf_dispatched.get(_cid)
            if _res is None:
                chapter_synthesis_failures.append(_cid)
                continue
            candidates_synthesized += 1
            for _co in _res.get("chapter_objectives") or []:
                if isinstance(_co, dict):
                    _co.setdefault("source_chunk_ids", [])
                    _flat_candidates.append(_co)

    if candidates_synthesized == 0 or not _flat_candidates:
        logger.warning(
            "plan_course_structure: Stage-2 produced no candidate objectives "
            "(grounding_mode=%s); falling back to deterministic synthesizer.",
            grounding_mode,
        )
        return [], [], "", {}

    # ---- Pass C: NLI-grounding filter. --------------------------------
    require_strict = str(
        os.environ.get("TRAINFORGE_REQUIRE_EMBEDDINGS", "")
    ).strip().lower() in {"1", "true", "yes", "on"}
    ground = ground_candidates(
        _flat_candidates, chunks_by_id, require=require_strict,
    )
    if grounding_mode == "chapter_fallback":
        # §5.6 — fallback keeps ALL candidates (no chunk citations to ground
        # against; Pass C only stamps). Combine grounded + ungrounded.
        _co_pool: List[Dict[str, Any]] = list(ground.grounded) + list(
            ground.ungrounded
        )
        ungrounded_dropped = 0
    else:
        _co_pool = list(ground.grounded)
        ungrounded_dropped = ground.dropped_count

    # ---- Defect C: apparatus-seed backstop (flag-gated, pre-dedup). ---
    # Drop any Pass-C survivor whose STATEMENT is exercise-/practice-apparatus
    # text the window sanitation missed (or a chapter-fallback candidate that
    # never saw window prep). keep-≥1; decision-captured. Same
    # ``ED4ALL_OBJECTIVE_SEED_SANITIZE`` flag as the window render sanitation.
    if resolve_seed_sanitize():
        _co_pool = _drop_apparatus_seeded_candidates(_co_pool, capture=capture)

    # ---- Build the embed client once (Pass D + Pass E backlink). ------
    _embed = None
    try:
        _embed = build_embedding_client(offline=True)
        _resolved = getattr(_embed, "resolved", None)
        if getattr(_resolved, "kind", None) == "fake" and not allow_fake_enabled():
            _embed = None
    except EmbeddingBackendUnavailable:
        if require_strict:
            raise
        _embed = None
    except Exception:  # noqa: BLE001
        if require_strict:
            raise
        _embed = None

    # ---- Pass D: embedding dedup (+ Fix 1A union cap/relevance-prune;
    #      I3 PRONG A distinct-skill split is gated inside dedup_candidates). -
    dedup = dedup_candidates(
        _co_pool,
        embed=_embed,
        allow_fake=allow_fake_enabled(),
        chunks_by_id=chunks_by_id,
        capture=capture,
    )
    chapter_cos = dedup.canonical

    if not chapter_cos:
        logger.warning(
            "plan_course_structure: Stage-2 Pass C/D left no canonical COs "
            "(grounding_mode=%s); falling back to deterministic synthesizer.",
            grounding_mode,
        )
        return [], [], "", {}

    # ---- I3 PRONG B: source-richness BACKFILL (opt-in). ---------------
    # Retain the PRE-DEDUP grounded pool (``_co_pool``): for any content-bearing
    # chunk left uncited by the post-dedup/split canonical set, PROMOTE the
    # best-grounded DISCARDED pre-dedup candidate citing that chunk into a new
    # CO. Promotion only (no re-synthesis); each promoted CO's source_chunk_ids
    # SUBSET the candidate's (anti-fabrication). Default off → no-op.
    from lib.objectives.source_backfill import backfill_uncovered_chunks
    _backfill = backfill_uncovered_chunks(
        canonical=chapter_cos,
        pre_dedup_candidates=_co_pool,
        chunks_by_id=chunks_by_id,
        capture=capture,
    )
    if _backfill.available and _backfill.cos_promoted:
        logger.info(
            "plan_course_structure: I3 PRONG B backfilled %d CO(s); content "
            "chunk coverage %d->%d uncovered (of %d content-bearing).",
            _backfill.cos_promoted,
            _backfill.uncovered_before,
            _backfill.uncovered_after,
            _backfill.content_bearing_chunks,
        )

    # ---- Feature 1: deterministic Bloom-level RELEVEL (opt-in). ----------
    # ED4ALL_OBJECTIVE_BLOOM_RELEVEL: for every canonical CO whose declared
    # bloom_level disagrees with the level its MAIN VERB belongs to in the
    # canonical verb table (lib/ontology/bloom.py — the same table
    # abcd_verb_alignment validates against), re-derive bloom_level from the
    # verb. STATEMENTS are never touched (only the bloom_level field).
    # Deterministic, no LLM. Default off → no-op (bloom_levels byte-identical).
    from lib.objectives.bloom_relevel import relevel_objectives
    _relevel = relevel_objectives(chapter_cos, capture=capture)
    if _relevel.available and _relevel.releveled_count:
        logger.info(
            "plan_course_structure: Feature 1 releveled %d/%d CO bloom_level(s) "
            "to match the canonical verb table.",
            _relevel.releveled_count,
            _relevel.scanned_count,
        )

    # ---- Feature 2 / PRONG C: Bloom-profile COMPLEMENT (opt-in, LLM). ---
    # ED4ALL_OBJECTIVE_BLOOM_COMPLEMENT: corpus-scoped (mirrors PRONG B). If the
    # share of analyze+evaluate+create COs is below MIN_SHARE, synthesize
    # grounded analyze/evaluate complement COs from the already-cited
    # instructional chunks via the SAME provider path stage-2 uses
    # (TEXTBOOK_SYNTHESIS_PROVIDER seat), until the share is met or MAX
    # additions are made. Runs AFTER dedup + split + backfill + relevel and
    # BEFORE citation re-selection / CO-id minting, so the appended complements
    # get minted, re-selected, and clustered into TOs like any other CO.
    # Anti-fabrication: each complement cites ONLY offered chunk ids, survives
    # the dedup threshold, and names a distinct skill. Default off → no-op.
    from lib.objectives.bloom_complement import complement_bloom_profile
    _complement = complement_bloom_profile(
        canonical=chapter_cos,
        chunks_by_id=chunks_by_id,
        provider=provider,
        course_name=course_name,
        capture=capture,
        embed=_embed,
    )
    if _complement.available and _complement.cos_added:
        logger.info(
            "plan_course_structure: PRONG C added %d analyze/evaluate "
            "complement CO(s); higher-order share %.2f -> %.2f.",
            _complement.cos_added,
            _complement.share_before,
            _complement.share_after,
        )

    # ---- Post-hoc citation RE-SELECTION (opt-in, deterministic). --------
    # ED4ALL_OBJECTIVE_CITATION_RESELECT: for each CO, re-rank the chunk pool
    # the model actually SAW — its synthesis window(s) (resolved via the
    # cited-chunk -> window map since windows partition the joined chunkset)
    # UNIONED with the CO's chapter bucket and its currently-cited ids — by
    # cosine(statement, chunk text) and re-cite the strongest supporters,
    # recovering from neighbor-citation sloppiness that a prune-only pass
    # cannot reach. Runs HERE (after dedup + split + backfill, BEFORE CO-id
    # minting / TO derivation) so the backlink, TO source_refs union, and
    # learning_outcome_refs all see the improved citations — and runs whether
    # the window candidates came from a live call or the resume sidecar (pure
    # post-processing).
    from lib.objectives.citation_reselect import (
        reselect_citations,
        resolve_citation_reselect,
    )
    _reselect = None
    if resolve_citation_reselect() and grounding_mode == "chunk_window":
        _window_ids_by_chunk: Dict[str, List[str]] = {}
        for _w in _windows:
            _w_ids = [str(c) for c in (_w.get("chunk_ids") or [])]
            for _cid in _w_ids:
                _window_ids_by_chunk[_cid] = _w_ids
        _chunks_by_chapter: Dict[str, List[str]] = {}
        for _cid, _rec in chunks_by_id.items():
            if isinstance(_rec, dict):
                _ch = str(_rec.get("chapter_id") or "")
                if _ch:
                    _chunks_by_chapter.setdefault(_ch, []).append(str(_cid))
        # Per-CO REAL candidate pool, built INDEPENDENTLY of what the model
        # cited so a wholly-fabricated (or empty) citation still resolves to a
        # real, cosine-relevant chunk (the "0 real grounding" fix). Sources, in
        # stable order:
        #   1. the CO's STAMPED synthesis-window chunk ids (Pass-B provenance —
        #      the real pool the model SAW, present even when every cited id is
        #      fabricated);
        #   2. windows reachable from any REAL cited id (legacy widening so a
        #      dedup-merged CO whose right-window citation was stripped by the
        #      Fix 1A prune can still reach its true same-chapter supporter);
        #   3. the CO's OWN chapter bucket (via its ``chapter_id`` — robust even
        #      when 100% of cited ids are fabricated), plus the chapter bucket
        #      of any real cited id.
        # reselect_citations then unions the currently-cited ids and applies the
        # anti-fabrication resolve-in-chunks_by_id filter (dropping fabricated
        # ids as pool_misses) + top-K cosine re-cite.
        def _extend_pool(
            pool: List[str], seen: set, ids: Any
        ) -> None:
            for _pid in ids or []:
                _p = str(_pid).strip()
                if _p and _p not in seen:
                    seen.add(_p)
                    pool.append(_p)

        _win_pool_by_co: Dict[int, List[str]] = {}
        for _i, _co_r in enumerate(chapter_cos):
            _cited_r = [
                str(c).strip()
                for c in (_co_r.get("source_chunk_ids") or [])
                if str(c).strip()
            ]
            _seen: set = set()
            _pool: List[str] = []
            # 1. stamped window provenance (real ids the model SAW).
            _extend_pool(_pool, _seen, _co_r.get("_reselect_window_pool"))
            # 2. windows reachable from real cited ids.
            for _cid in _cited_r:
                _extend_pool(_pool, _seen, _window_ids_by_chunk.get(_cid, []))
            # 3a. the CO's own chapter bucket (robust to fabricated citations).
            _extend_pool(
                _pool, _seen,
                _chunks_by_chapter.get(str(_co_r.get("chapter_id") or ""), []),
            )
            # 3b. chapter buckets of real cited ids.
            for _cid in _cited_r:
                _rec = chunks_by_id.get(_cid)
                if isinstance(_rec, dict):
                    _extend_pool(
                        _pool, _seen,
                        _chunks_by_chapter.get(
                            str(_rec.get("chapter_id") or ""), []
                        ),
                    )
            if _pool:
                _win_pool_by_co[_i] = _pool
        _reselect = reselect_citations(
            chapter_cos,
            chunks_by_id,
            _embed,
            window_chunk_ids_by_co=_win_pool_by_co,
            capture=capture,
        )
        # Strip the transient Pass-B provenance stamp so it never lands in the
        # serialized objectives (present only while reselect is enabled).
        for _co_r in chapter_cos:
            _co_r.pop("_reselect_window_pool", None)
        if _reselect.available:
            logger.info(
                "plan_course_structure: citation re-selection re-cited "
                "%d/%d CO(s); citation density %d -> %d distinct chunks "
                "(pool_misses=%d, kept_original_below_floor=%d).",
                _reselect.reselected_count,
                _reselect.scanned_count,
                _reselect.citation_density_before,
                _reselect.citation_density_after,
                _reselect.pool_misses,
                _reselect.kept_original_below_floor,
            )

    # ---- Defect A §A step 6 — chapter-contiguous CO re-order BEFORE minting.
    # When the chapter-anchor master + reorder satellite are on (and we have a
    # chunk-window grounding), stable-sort the survivors into book order (module
    # first-occurrence, then within-module position) so ceil-stride weeks are
    # chapter-contiguous even without ED4ALL_WEEK_TO_GROUPS. No-op / byte-
    # identical when the master flag is off (the default).
    if (
        _resolve_to_chapter_anchor()
        and _resolve_to_chapter_anchor_reorder()
        and grounding_mode == "chunk_window"
    ):
        chapter_cos = _reorder_cos_by_anchor(chapter_cos, chunks_by_id, all_chunks)

    # ---- Mint CO-NN AFTER Pass C + D over the survivors. --------------
    for _idx, _co in enumerate(chapter_cos, start=1):
        _co["id"] = mint_lo_id("chapter", _idx)

    # ---- WS1 KEYSTONE: derive TOs BOTTOM-UP by clustering the grounded COs.
    # The legacy top-down draft-TO reconcile argmax-backlinked every CO to one
    # of 3-4 blinded drafts with no floor → ~87% wrong (WS2 measures this as
    # weak_to_link_rate). WS1 derives TOs by clustering the CO statement
    # vectors and authoring one TO per cluster, setting each CO's terminal_id
    # DIRECTLY from its cluster (correct by construction).
    #
    # Defect A — when ED4ALL_TO_CHAPTER_ANCHOR is on AND we have a chunk-window
    # grounding, TOs are derived by ANCHORING COs to DART modules first; the
    # anchor path may gracefully degrade (returns []), in which case the
    # bottom-up path runs UNTOUCHED. Default OFF ⇒ bottom-up only (byte-identical).
    terminal: List[Dict[str, Any]] = []
    used_bottom_up = False
    cluster_signals: Dict[str, Any] = {}
    _cluster_cp = (
        checkpoint_path.parent / _STAGE2_CLUSTERS_CHECKPOINT_NAME
        if checkpoint_path is not None
        else None
    )
    if _resolve_to_chapter_anchor() and grounding_mode == "chunk_window":
        terminal, cluster_signals = _derive_terminals_chapter_anchored(
            provider=provider,
            chapter_cos=chapter_cos,
            chunks_by_id=chunks_by_id,
            all_chunks=all_chunks,
            embed=_embed,
            course_name=course_name,
            mint_lo_id=mint_lo_id,
            capture=capture,
            checkpoint_path=_cluster_cp,
        )
    if not terminal and _embed is not None:
        # Anchor mode off / degraded → bottom-up clustering (UNTOUCHED). Preserve
        # any degrade-reason signal for observability, then let bottom-up own
        # the rest of cluster_signals.
        _degrade_reason = cluster_signals.get("to_derivation_degraded_reason")
        terminal, cluster_signals = _derive_terminals_bottom_up(
            provider=provider,
            chapter_cos=chapter_cos,
            embed=_embed,
            course_name=course_name,
            mint_lo_id=mint_lo_id,
            capture=capture,
            # Per-cluster TO-author resume sidecar, sibling of the window
            # sidecar in the phase OUTPUT dir (same flag gating).
            checkpoint_path=_cluster_cp,
        )
        if _degrade_reason and terminal:
            cluster_signals["to_derivation_degraded_reason"] = _degrade_reason
    used_bottom_up = bool(terminal)

    if not used_bottom_up:
        # ---- FALLBACK (R4, load-bearing): legacy draft-TO reconcile + backlink.
        # _embed absent (extras missing / fake-provider) OR bottom-up degraded
        # (encode_batch raised → []). Reconcile doesn't pre-set terminal_id, so
        # the backlink does the real argmax assignment here.
        try:
            _recon = provider.reconcile_terminal_objectives(
                draft_tos, chapter_cos, course_name=course_name,
            )
            terminal = list(_recon.get("terminal_objectives") or [])
        except provider_error:
            logger.exception(
                "plan_course_structure: Stage-2 reconciliation exhausted "
                "(provider=%s); failing loud.", provider_env,
            )
            raise

    # ---- Pass E: deterministic CO→TO backlink (+ WS2 weak-link signal). ----
    # WS1/WS2 integration: on the BOTTOM-UP path every CO already carries a
    # resolvable terminal_id (pre-set in _derive_terminals_bottom_up), so
    # backlink_cos_to_tos is a NO-OP for ASSIGNMENT (it honors a resolvable
    # pre-set terminal_id before cosine — lo_backlink.py). We STILL call it on
    # BOTH paths because WS2's weak_to_link_* signals depend on the returned
    # BacklinkResult: scored against the NEW good TO set, weak_to_link_rate
    # should drop toward ~0 (vs ~0.87 legacy) — the success metric that PROVES
    # WS1 worked. The redundant encode on the bottom-up path is accepted for
    # that proof signal. The fallback path needs the backlink for the real
    # argmax assignment (reconcile doesn't pre-set ids).
    # M5 Fix A — reassign mode (env ED4ALL_TO_BACKLINK_REASSIGN) re-scores
    # hint-honored COs (validator parity → weak_to_link_rate matches
    # co_terminal_alignment) and re-points cosine-junk links to a better TO.
    # Defect A — reassign is SUPPRESSED in chapter-anchor mode (a CO's parent TO
    # is chosen by cited-chunk plurality, not cosine, so re-pointing to a
    # cosine-argmax TO would UNDO the anchor). The backlink still runs (WS2
    # weak-link measurement), just with reassign forced off; WARN if the env is
    # set so the operator knows it was ignored this run.
    _reassign_override: Optional[bool] = None
    if cluster_signals.get("to_derivation") == "chapter_anchored":
        from lib.ontology.lo_backlink import resolve_reassign_mode  # noqa: PLC0415

        if resolve_reassign_mode():
            logger.warning(
                "plan_course_structure: ED4ALL_TO_BACKLINK_REASSIGN is set but "
                "SUPPRESSED in chapter-anchor mode (kept for WS2 weak-link "
                "measurement only — reassign would undo the chapter anchor).",
            )
        _reassign_override = False
    _backlink = backlink_cos_to_tos(
        terminal, chapter_cos, embed=_embed, reassign=_reassign_override
    )

    # The window-map path stamps a distinct ``_window`` label so an audit can
    # tell chunk-grounded synthesis apart from the chapter-grained fallback,
    # which keeps the legacy ``textbook_synthesis:`` mint_method value verbatim.
    mint_method = (
        f"textbook_synthesis_window:{provider_env}"
        if grounding_mode == "chunk_window"
        else f"textbook_synthesis:{provider_env}"
    )
    logger.info(
        "plan_course_structure: Stage-2 (%s) synthesized %d candidate(s) → "
        "%d grounded → %d canonical CO(s); reconciled to %d TO(s).",
        grounding_mode,
        len(_flat_candidates),
        len(ground.grounded),
        len(chapter_cos),
        len(terminal),
    )

    grounding_signals: Dict[str, Any] = {
        "grounding_mode": grounding_mode,
        "candidate_count": len(_flat_candidates),
        "grounded_count": len(ground.grounded),
        "ungrounded_dropped": ungrounded_dropped,
        "reground_count": ground.reground_count,
        "nli_available": ground.available,
        "dedup_clusters": len(dedup.clusters),
        "max_pairwise_cosine": round(float(dedup.max_pairwise_cosine), 6),
        "near_dup_pairs": dedup.near_dup_pairs,
        "embed_available": dedup.available,
        # Fix 1A — union cap/relevance-prune calibration signals (mirror how
        # max_pairwise_cosine / near_dup_pairs are surfaced for pinning).
        "max_chunks_per_objective": dedup.max_chunks_per_objective,
        "pruned_chunk_total": dedup.pruned_chunk_total,
        # W2 (Defect E) — lexical cross-window restatement-merge telemetry.
        # Present only when the lexical-merge pass actually merged ≥1 cluster
        # (guarded so the legacy signal shape is unchanged when it no-ops).
        **(
            {"lexical_merge_pairs": dedup.lexical_merge_pairs}
            if getattr(dedup, "lexical_merge_pairs", 0)
            else {}
        ),
        **(
            {"lexical_clusters_merged": dedup.lexical_clusters_merged}
            if getattr(dedup, "lexical_clusters_merged", 0)
            else {}
        ),
        # I3 PRONG A — distinct-skill split signals.
        "clusters_split_for_distinct_skill": (
            dedup.clusters_split_for_distinct_skill
        ),
        "distinct_skill_count": dedup.distinct_skill_count,
        # I3 PRONG B — source-richness backfill signals.
        "backfill_available": _backfill.available,
        "backfill_cos_promoted": _backfill.cos_promoted,
        "backfill_uncovered_before": _backfill.uncovered_before,
        "backfill_uncovered_after": _backfill.uncovered_after,
        "backfill_content_chunks": _backfill.content_bearing_chunks,
        "canonical_co_count": len(chapter_cos),
        "terminal_count": len(terminal),
        # WS1 — bottom-up TO derivation signals. ``cluster_signals`` is {} on
        # the legacy fallback path → downstream reads
        # grounding_signals.get("to_derivation", "legacy_reconcile").
        **cluster_signals,
        # WS2 — CO→TO weak-backlink instrumentation. PURE MEASUREMENT.
        "weak_to_link_count": _backlink.weak_link_count,
        "weak_to_link_rate": round(_backlink.weak_link_rate, 6),
        "weak_to_link_scored": _backlink.scored_count,
        "weak_to_link_used_embeddings": _backlink.used_embeddings,
        "weak_to_link_cosine_floor": _backlink.cosine_floor,
        "weak_to_link_min_score": _backlink.min_best_score,
        "weak_to_link_mean_score": _backlink.mean_best_score,
        # M5 Fix A — count of COs re-pointed off a junk-drawer TO (0 unless
        # ED4ALL_TO_BACKLINK_REASSIGN is on).
        "weak_to_link_reassigned": _backlink.reassigned_count,
        # Per-window resume-checkpoint reuse (0/0 on the chapter_fallback path).
        # Rides the existing objective_grounding_filter decision event at the
        # call site — no new decision_type.
        "windows_total": _windows_total,
        "windows_reused_from_checkpoint": _windows_reused,
        # Post-hoc citation re-selection counters (all-zero / before==after
        # when ED4ALL_OBJECTIVE_CITATION_RESELECT is off or the pass no-ops).
        "citations_reselected": (
            _reselect.reselected_count if _reselect is not None else 0
        ),
        "citation_density_before": (
            _reselect.citation_density_before if _reselect is not None else 0
        ),
        "citation_density_after": (
            _reselect.citation_density_after if _reselect is not None else 0
        ),
        "reselect_pool_misses": (
            _reselect.pool_misses if _reselect is not None else 0
        ),
        # Feature 1 — deterministic Bloom-relevel signals (0 when off / no-op).
        "bloom_releveled_count": (
            _relevel.releveled_count if _relevel is not None else 0
        ),
        "bloom_relevel_scanned": (
            _relevel.scanned_count if _relevel is not None else 0
        ),
        # Feature 2 / PRONG C — Bloom-complement signals (0 when off / no-op).
        "bloom_complement_added": (
            _complement.cos_added if _complement is not None else 0
        ),
        "bloom_complement_share_before": (
            round(float(_complement.share_before), 6)
            if _complement is not None else 0
        ),
        "bloom_complement_share_after": (
            round(float(_complement.share_after), 6)
            if _complement is not None else 0
        ),
        "bloom_complement_llm_calls": (
            _complement.llm_calls if _complement is not None else 0
        ),
        "bloom_complement_rejected": (
            _complement.candidates_rejected if _complement is not None else 0
        ),
    }
    return chapter_cos, terminal, mint_method, grounding_signals


def _detect_source_provenance(course_dir: Path) -> bool:
    """Wave 10: scan archived chunks.jsonl for chunks with source_references[].

    Returns True when at least one chunk in ``<course_dir>/corpus/chunks.jsonl``
    carries ``source.source_references[]`` populated with at least one entry.
    Returns False on missing file, read errors, malformed JSONL lines, or
    when no chunks carry refs (pre-Wave-9 corpus). The manifest then advertises
    ``features.source_provenance: false`` so LibV2 retrieval callers can
    fast-skip source-grounded queries.
    """
    # Phase 7c: prefer imscc_chunks/, fall back to legacy corpus/ via shim.
    from lib.libv2_storage import resolve_imscc_chunks_path
    chunks_path = resolve_imscc_chunks_path(course_dir, "chunks.jsonl")
    if not chunks_path.exists() or not chunks_path.is_file():
        return False
    try:
        with open(chunks_path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    chunk = json.loads(line)
                except (json.JSONDecodeError, ValueError):
                    continue
                if not isinstance(chunk, dict):
                    continue
                source = chunk.get("source")
                if not isinstance(source, dict):
                    continue
                refs = source.get("source_references")
                if isinstance(refs, list) and len(refs) > 0:
                    return True
    except OSError:
        return False
    return False


def _detect_evidence_source_provenance(course_dir: Path) -> bool:
    """Wave 11: scan archived concept_graph_semantic.json for evidence-level refs.

    Returns True when at least one edge in the archived concept graph's
    ``edges[].provenance.evidence`` carries a populated ``source_references[]``
    array. False on missing file, read errors, malformed JSON, or when no
    edges carry evidence refs. The manifest then advertises
    ``features.evidence_source_provenance: true/false`` so LibV2 retrieval
    callers can distinguish chunk-level (Wave 10) from evidence-level (Wave 11)
    provenance.

    The scan looks in candidate locations under ``<course_dir>``:
    ``graph/concept_graph_semantic.json``, ``imscc_chunks/concept_graph_semantic.json``,
    or legacy ``corpus/concept_graph_semantic.json``, or any ``*.json``
    file shaped like a semantic graph (``kind == "concept_semantic"``)
    sitting inside the chunkset dir. First match wins.
    """
    candidates = [
        course_dir / "graph" / "concept_graph_semantic.json",
        course_dir / "imscc_chunks" / "concept_graph_semantic.json",
        course_dir / "corpus" / "concept_graph_semantic.json",
    ]
    for path in candidates:
        if path.exists() and path.is_file():
            try:
                with open(path, encoding="utf-8") as f:
                    graph = json.load(f)
            except (OSError, json.JSONDecodeError, ValueError):
                continue
            if _graph_has_evidence_refs(graph):
                return True
            # First readable candidate wins — don't fall through to others
            # if this one was valid shape but carried no refs.
            return False
    return False


def _graph_has_evidence_refs(graph: object) -> bool:
    """Return True iff the graph has at least one edge whose
    ``provenance.evidence.source_references`` is a non-empty list.

    Tolerates partial / legacy shapes: silently returns False on any
    structural surprise rather than raising.
    """
    if not isinstance(graph, dict):
        return False
    edges = graph.get("edges")
    if not isinstance(edges, list):
        return False
    for edge in edges:
        if not isinstance(edge, dict):
            continue
        provenance = edge.get("provenance")
        if not isinstance(provenance, dict):
            continue
        evidence = provenance.get("evidence")
        if not isinstance(evidence, dict):
            continue
        refs = evidence.get("source_references")
        if isinstance(refs, list) and len(refs) > 0:
            return True
    return False


# Wave 32 Deliverable C: phase-level empty-content guard for
# content_generation. Runs inline at the end of _generate_course_content
# so a dispatcher that returned zero real body content fails the phase
# loudly rather than passing with ``gates=pass`` on template skeletons.
# Reuses the Wave 31 ContentGroundingValidator's 30-word floor for
# behavioural consistency with the content_grounding gate — this check
# catches the strict "every page is an empty skeleton" failure mode the
# gate considers a warning when partial (< 25 %). Independent of the
# gate: gates require routing + inputs to fire, and when routing skips
# we want a phase-level guarantee that the dispatcher produced at least
# one non-trivial page.
_CONTENT_BODY_TAGS = ("p", "li", "blockquote", "figcaption")
_CONTENT_NONTRIVIAL_WORD_FLOOR = 30


def _check_content_nonempty(page_paths: list) -> "Optional[str]":
    """Return an error message when every emitted page is an empty template.

    Parses each page and counts words in body-text tags
    (``<p>``/``<li>``/``<blockquote>``/``<figcaption>``) inside
    ``<main>`` (or the document body when no main wrapper exists).
    Returns ``None`` when at least one page clears
    :data:`_CONTENT_NONTRIVIAL_WORD_FLOOR` words — otherwise returns an
    actionable error string that mentions the LOCAL_DISPATCHER_ALLOW_STUB
    bypass and the missing agent_tool wiring.

    Contract:
      * Empty ``page_paths`` → returns ``None`` (nothing to check —
        upstream already bailed out with an error when it mattered).
      * Unreadable / missing files are counted as empty.
    """
    if not page_paths:
        return None

    try:
        from bs4 import BeautifulSoup  # type: ignore
    except ImportError:  # pragma: no cover — bs4 is a hard dep in this repo
        # Without BeautifulSoup we can't reliably parse body content, so
        # fall back to a plain word-count heuristic on the raw file.
        def _plain_word_count(text: str) -> int:
            import re as _re_inner
            return len(_re_inner.findall(r"\b\w+\b", text))

        for p in page_paths:
            try:
                raw = Path(p).read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            if _plain_word_count(raw) >= _CONTENT_NONTRIVIAL_WORD_FLOOR * 2:
                return None
        return (
            "CONTENT_GENERATION_EMPTY: All "
            f"{len(page_paths)} generated pages have <"
            f"{_CONTENT_NONTRIVIAL_WORD_FLOOR} body words each. "
            "This indicates the content-gen dispatcher produced template "
            "skeletons without filling them. Likely cause: --mode local "
            "dispatcher not wired to an actual agent_tool. See "
            "LOCAL_DISPATCHER_ALLOW_STUB for the bypass."
        )

    total = len(page_paths)
    nonempty = 0
    for p in page_paths:
        try:
            raw = Path(p).read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        try:
            soup = BeautifulSoup(raw, "html.parser")
        except Exception:  # noqa: BLE001
            continue
        # Scope to <main> when present; otherwise the whole body.
        scope = soup.find("main")
        if scope is None:
            scope = soup.find(attrs={"role": "main"})
        if scope is None:
            scope = soup.body or soup
        # Strip nav/header/footer from the scope so their paragraphs
        # don't pollute the count (mirrors ContentGroundingValidator).
        for tag in scope.find_all(["nav", "header", "footer"]):
            tag.decompose()
        for el in scope.find_all(_CONTENT_BODY_TAGS):
            text = el.get_text(separator=" ", strip=True)
            if len(text.split()) >= _CONTENT_NONTRIVIAL_WORD_FLOOR:
                nonempty += 1
                break
        else:
            continue
        # Early exit once we see any non-trivial page — the phase
        # guarantee is "at least one page with real content".
        if nonempty >= 1:
            return None

    if nonempty >= 1:
        return None
    return (
        "CONTENT_GENERATION_EMPTY: All "
        f"{total} generated pages have <"
        f"{_CONTENT_NONTRIVIAL_WORD_FLOOR} body words each. "
        "This indicates the content-gen dispatcher produced template "
        "skeletons without filling them. Likely cause: --mode local "
        "dispatcher not wired to an actual agent_tool. See "
        "LOCAL_DISPATCHER_ALLOW_STUB for the bypass."
    )


async def create_textbook_pipeline(
    pdf_paths: str,
    course_name: str,
    objectives_path: Optional[str] = None,
    duration_weeks: int = 12,
    generate_assessments: bool = True,
    assessment_count: int = 50,
    bloom_levels: str = "remember,understand,apply,analyze",
    priority: str = "normal",
    duration_weeks_explicit: bool = True,
    skip_dart: bool = False,
    dart_output_dir: Optional[str] = None,
    reuse_objectives_path: Optional[str] = None,
    reuse_conversion: bool = False,
    courseforge_stage: Optional[str] = None,
    force_rerun: bool = False,
    skip_training: bool = False,
    stop_after: Optional[str] = None,
    provider: Optional[str] = None,
    target_block_ids: Optional[List[str]] = None,
    target_block_instance_ids: Optional[List[str]] = None,
    target_page_ids: Optional[List[str]] = None,
    auto_name: bool = False,
) -> str:
    """
    Create and orchestrate a textbook-to-course pipeline.

    Chains: DART (PDF->HTML) -> Courseforge (course generation) -> Trainforge (assessments)

    This is a standalone function importable by both the MCP server and CLI.

    Args:
        pdf_paths: Comma-separated PDF paths OR directory containing PDFs
        course_name: Course identifier (e.g., "PHYS_101")
        objectives_path: Optional external objectives file to merge
        duration_weeks: Course duration in weeks (default: 12)
        generate_assessments: Run Trainforge phase (default: True)
        assessment_count: Questions to generate (default: 50)
        bloom_levels: Target Bloom levels (default: remember,understand,apply,analyze)
        priority: Workflow priority (low/normal/high)
        duration_weeks_explicit: Wave 39 follow-up. When ``False`` (the
            caller did NOT pass ``--weeks``), the extractor phase
            (``_extract_textbook_structure``) auto-scales
            ``duration_weeks`` to ``max(8, chapter_count)`` once the
            textbook structure is known. Defaults to ``True`` so legacy
            callers keep the historical fixed-12 behaviour.

    Returns:
        JSON with workflow_id, run_id, and status
    """
    try:
        from MCP.tools.orchestrator_tools import create_workflow_impl

        # Courseforge stage subcommands work off an existing project
        # export — DART / staging / objective_extraction etc. are
        # pre-populated via _synthesize_outline_output, so corpus PDFs
        # are not consumed. Skip PDF validation entirely when
        # courseforge_stage is set.
        if courseforge_stage:
            pdfs = []
        else:
            # Parse PDF paths
            pdf_path = Path(pdf_paths)
            if pdf_path.is_dir():
                pdfs = list(pdf_path.glob("*.pdf"))
                if not pdfs:
                    return json.dumps({"error": f"No PDF files found in directory: {pdf_paths}"})
            else:
                pdfs = [Path(p.strip()) for p in pdf_paths.split(",")]

            # Validate PDF paths are within project root
            for pdf in pdfs:
                try:
                    validate_path_within_root(pdf.resolve(), PROJECT_ROOT)
                except ValueError as e:
                    return json.dumps({"error": f"PDF path validation failed: {e}"})

            # Validate inputs
            missing_pdfs = [str(p) for p in pdfs if not p.exists()]
            if missing_pdfs:
                return json.dumps({"error": f"PDF files not found: {missing_pdfs}"})

        if objectives_path and not Path(objectives_path).exists():
            return json.dumps({"error": f"Objectives file not found: {objectives_path}"})

        # Validate course name format
        if not course_name or len(course_name) < 2:
            return json.dumps({"error": "Course name must be at least 2 characters"})

        # Generate run_id
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        run_id = f"TTC_{course_name}_{timestamp}"

        # Wave 29 Defect 5: compute the canonical course code ONCE
        # from ``course_name`` (the CLI-supplied / caller-supplied
        # value) and pin it on the params dict. Every DecisionCapture
        # instantiated anywhere in this run reads from this field
        # instead of re-deriving from a PDF name, a workflow_id hash,
        # or the workflow type. That keeps captures, archives, and
        # CF/TF phase data tagged with a single consistent code —
        # fixing the SIM_RUN_01 four-codes-in-one-run observation.
        from lib.decision_capture import normalize_course_code as _normalize_cc

        canonical_cc = _normalize_cc(course_name)

        # Build workflow parameters. Wave 39 follow-up: propagate the
        # ``duration_weeks_explicit`` flag so ``_extract_textbook_structure``
        # sees it via kwargs and auto-scales ``duration_weeks`` to
        # ``max(8, chapter_count)`` when the CLI caller omitted
        # ``--weeks``. Pre-Wave-39-follow-up, this function hard-coded
        # ``duration_weeks=12`` into the workflow state regardless of
        # intent, so the auto-scale branch in the extractor was
        # effectively dead code on the real run path.
        params = {
            "pdf_paths": [str(p.resolve()) for p in pdfs],
            "course_name": course_name,
            "canonical_course_code": canonical_cc,
            "objectives_path": str(Path(objectives_path).resolve()) if objectives_path else None,
            "duration_weeks": duration_weeks,
            "duration_weeks_explicit": bool(duration_weeks_explicit),
            "generate_assessments": generate_assessments,
            "assessment_count": assessment_count,
            "bloom_levels": [level.strip() for level in bloom_levels.split(",")],
            "run_id": run_id
        }
        # Wave 74 Session 3: forward --skip-dart so the workflow runner
        # can synthesize the semantik_conversion phase_output from an
        # existing SemantiK/output/ directory instead of re-running the
        # PDF->HTML conversion.
        if skip_dart:
            params["skip_dart"] = True
            if dart_output_dir:
                params["dart_output_dir"] = str(Path(dart_output_dir).resolve())

        # Wave 80 Worker A: forward --reuse-objectives so the workflow
        # runner can synthesize the course_planning phase_output from
        # the user-supplied objectives JSON instead of dispatching the
        # course-outliner subagent. Stable across re-runs (no LLM
        # nondeterminism), preserving chunk learning_outcome_refs
        # continuity.
        if reuse_objectives_path:
            params["reuse_objectives_path"] = str(
                Path(reuse_objectives_path).resolve()
            )

        # SemantiK §3.3a item 2: forward --reuse-conversion so the SemantiK v2
        # conversion seam (``_run_semantik_v2_conversion``) reuses prior
        # ``{stem}_accessible.html`` + sidecars instead of re-running the
        # model-nondeterministic cascade on a re-run. Mirrors
        # ``ED4ALL_REUSE_CONVERSION``; the dispatch is still P3c (this only
        # carries the flag onto the workflow params).
        if reuse_conversion:
            params["reuse_conversion"] = True

        # Phase 5 operator stage subcommands: restrict execution to the
        # named Courseforge stage whitelist, optionally force re-run of
        # checkpointed phases, and optionally skip training_synthesis.
        if courseforge_stage:
            params["courseforge_stage"] = courseforge_stage
        if force_rerun:
            params["force_rerun"] = True
        if skip_training:
            params["skip_training"] = True
        # Phase 5 ST 1 (--blocks) — forward the parsed block-TYPE filter so
        # the content_generation_rewrite phase additively evicts cached
        # blocks of the named types (re-rolling them even when a prior
        # rewrite succeeded). Unset → no key on params → byte-identical.
        if target_block_ids:
            params["target_block_ids"] = list(target_block_ids)
        # I4 stage 2 (--block-ids / --pages) — forward the instance-scoped +
        # page/module-scoped eviction filters so the rewrite phase additively
        # evicts the named block instance(s) + page/module block(s). Unset →
        # no key on params → byte-identical failure-driven reuse.
        if target_block_instance_ids:
            params["target_block_instance_ids"] = list(
                target_block_instance_ids
            )
        if target_page_ids:
            params["target_page_ids"] = list(target_page_ids)
        # --auto-name: the caller-supplied course_name is PROVISIONAL; the
        # workflow runner resolves the FINAL H1-derived, run-timestamped slug
        # post-conversion (``_maybe_apply_auto_name``) and rebinds
        # course_name on these params. Unset -> no key -> byte-identical.
        if auto_name:
            params["auto_name"] = True
        # Hosted-seat build profile GAP-2 fix — forward --stop-after so the workflow
        # runner halts cleanly after the named phase (before later phases run).
        if stop_after:
            params["stop_after"] = stop_after
        # W1 Gap C / hosted-seat build profile — forward the EXPLICIT run provider
        # so ``_apply_authoring_route_env`` resolves the authoring + nvidia
        # routing branch from it (else it falls to LLM_PROVIDER > local).
        if provider:
            params["provider"] = provider

        # Create workflow via orchestrator
        result = await create_workflow_impl(
            workflow_type="textbook_to_course",
            params=json.dumps(params),
            priority=priority
        )

        result_data = json.loads(result)

        if result_data.get("success"):
            # Add run_id to response
            result_data["run_id"] = run_id
            result_data["params"] = params

            # Create training captures directory for this run
            captures_dir = TRAINING_CAPTURES / "textbook-pipeline" / course_name
            captures_dir.mkdir(parents=True, exist_ok=True)

            logger.info(f"Created textbook_to_course pipeline: {result_data.get('workflow_id')}")

        return json.dumps(result_data)

    except Exception as e:
        logger.error(f"Failed to create textbook pipeline: {e}")
        return json.dumps({"error": str(e)})


async def run_textbook_pipeline(workflow_id: str) -> str:
    """
    Execute a textbook-to-course pipeline that was previously created.

    Standalone function importable by both MCP server and CLI.

    Runs all phases in dependency order:
    DART conversion -> Staging -> Objective extraction -> Course planning ->
    Content generation -> IMSCC packaging -> Trainforge assessment ->
    LibV2 archival -> Finalization

    Args:
        workflow_id: The workflow ID returned by create_textbook_pipeline

    Returns:
        JSON with final status, phase results, and output paths
    """
    try:
        from MCP.core.config import OrchestratorConfig
        from MCP.core.executor import TaskExecutor
        from MCP.core.workflow_runner import WorkflowRunner

        # Load orchestrator config
        config = OrchestratorConfig.load()

        # Create executor with tool registry
        tool_registry = _build_tool_registry()

        executor = TaskExecutor(tool_registry=tool_registry)

        # Create and run the workflow runner
        runner = WorkflowRunner(executor, config)
        result = await runner.run_workflow(workflow_id)

        return json.dumps(result, default=str)

    except Exception as e:
        logger.error(f"Pipeline execution failed: {e}")
        import traceback
        return json.dumps({
            "error": str(e),
            "traceback": traceback.format_exc(),
            "workflow_id": workflow_id,
        })


def register_pipeline_tools(mcp):
    """Register pipeline tools with the MCP server."""

    # Wave 28f: create_textbook_pipeline_tool was removed.
    # External MCP clients now route through the workflow API
    # (``create_workflow(workflow_type='textbook_to_course', ...)``) or
    # ``ed4all run textbook-to-course``. The underlying non-tool
    # ``create_textbook_pipeline()`` coroutine above remains for
    # internal callers (e.g. cli/commands/run.py).

    @mcp.tool()
    async def stage_semantik_outputs(
        run_id: str,
        dart_html_paths: str,
        course_name: str,
        stage_mode: Optional[str] = None,
    ) -> str:
        """
        Stage SemantiK outputs to Courseforge inputs directory.

        Stages synthesized HTML and JSON files from the SemantiK conversion
        output to the Courseforge staging area for course generation. The
        default ``stage_mode`` is ``symlink`` (zero-byte references back to
        the conversion outputs) which avoids duplicating ~70MB per
        textbook-to-course run. Set ``stage_mode="copy"`` for a deep copy.

        Args:
            run_id: Pipeline run identifier
            dart_html_paths: Comma-separated paths to SemantiK HTML outputs
            course_name: Course identifier for staging subdirectory
            stage_mode: One of ``"copy"``, ``"symlink"``, ``"hardlink"``.
                Defaults to ``ED4ALL_STAGE_MODE`` env var, then ``"symlink"``.

        Returns:
            JSON with staging_dir, staged_files list, and stage_mode used.
        """
        try:
            mode = _resolve_stage_mode(stage_mode)

            # Create staging directory
            staging_dir = COURSEFORGE_INPUTS / run_id
            staging_dir.mkdir(parents=True, exist_ok=True)

            staged_files = []
            # Wave 8: role-tagged manifest entries for the downstream
            # Courseforge source-router and Trainforge parser. Roles:
            #   "content"             -> the rendered HTML page
            #   "provenance_sidecar"  -> *_synthesized.json with per-block provenance
            #   "quality_sidecar"     -> *.quality.json with WCAG + confidence aggregates
            staged_entries = []
            errors = []

            html_paths = [Path(p.strip()) for p in dart_html_paths.split(",")]

            for html_path in html_paths:
                if not html_path.exists():
                    errors.append(f"DART output not found: {html_path}")
                    continue

                # Stage HTML file (role=content)
                dest = staging_dir / html_path.name
                _stage_file(html_path, dest, mode)
                staged_files.append(str(dest))
                staged_entries.append({"path": html_path.name, "role": "content"})
                logger.info(f"Staged ({mode}): {html_path.name} -> {dest}")

                # Wave 19: stage the sibling ``{stem}_figures/`` directory
                # (persisted PyMuPDF figure bytes from Wave 17) so the
                # Courseforge generator renders ``<img src>`` paths that
                # actually resolve. Missing directory is silently skipped
                # for backward compat with pre-Wave-17 outputs.
                figures_dir_src = html_path.parent / f"{html_path.stem}_figures"
                if figures_dir_src.is_dir():
                    figures_dir_dest = staging_dir / figures_dir_src.name
                    _stage_tree(figures_dir_src, figures_dir_dest, mode)
                    staged_files.append(str(figures_dir_dest))
                    staged_entries.append({
                        "path": figures_dir_src.name,
                        "role": "figures_bundle",
                    })
                    logger.info(
                        f"Staged figures dir ({mode}): {figures_dir_src.name} -> {figures_dir_dest}"
                    )

                # Validate HTML structure
                if html_path.suffix.lower() in ('.html', '.htm'):
                    try:
                        content = dest.read_text(encoding='utf-8', errors='ignore')[:5000]
                        content_lower = content.lower()
                        if '<html' not in content_lower and '<body' not in content_lower:
                            errors.append(
                                f"Warning: {html_path.name} may not be valid HTML "
                                f"(missing <html> and <body> tags)"
                            )
                    except OSError:
                        pass  # File was staged, just can't validate

                # Stage accompanying JSON if exists (DART synthesized metadata)
                json_path = html_path.with_suffix(".json")
                if json_path.exists():
                    json_dest = staging_dir / json_path.name
                    _stage_file(json_path, json_dest, mode)
                    staged_files.append(str(json_dest))
                    staged_entries.append({
                        "path": json_path.name,
                        "role": "provenance_sidecar",
                    })
                    logger.info(f"Staged ({mode}): {json_path.name} -> {json_dest}")

                # Also check for _synthesized.json pattern
                synth_json_name = html_path.stem.replace("_synthesized", "") + "_synthesized.json"
                synth_json_path = html_path.parent / synth_json_name
                if synth_json_path.exists() and str(synth_json_path) != str(json_path):
                    synth_json_dest = staging_dir / synth_json_name
                    _stage_file(synth_json_path, synth_json_dest, mode)
                    staged_files.append(str(synth_json_dest))
                    staged_entries.append({
                        "path": synth_json_name,
                        "role": "provenance_sidecar",
                    })
                    logger.info(f"Staged ({mode}): {synth_json_name} -> {synth_json_dest}")

                # Wave 8: also stage the DART quality sidecar if one exists.
                # Convention: same stem as the HTML, suffix .quality.json.
                # E.g. "science_of_learning.html" -> "science_of_learning.quality.json".
                # The legacy stage_dart_outputs never copied this even though
                # DART's convert_single_pdf has been writing it all along.
                quality_name = html_path.stem + ".quality.json"
                quality_path = html_path.parent / quality_name
                if quality_path.exists():
                    quality_dest = staging_dir / quality_name
                    _stage_file(quality_path, quality_dest, mode)
                    staged_files.append(str(quality_dest))
                    staged_entries.append({
                        "path": quality_name,
                        "role": "quality_sidecar",
                    })
                    logger.info(f"Staged ({mode}): {quality_name} -> {quality_dest}")

            if errors and not staged_files:
                return json.dumps({
                    "success": False,
                    "error": "No files staged",
                    "errors": errors
                })

            # Create manifest (Wave 8: role-tagged entries under "files")
            manifest = {
                "run_id": run_id,
                "course_name": course_name,
                "staged_at": datetime.now().isoformat(),
                "staged_files": staged_files,            # back-compat flat list
                "files": staged_entries,                 # role-tagged entries
                "errors": errors if errors else None,
            }

            manifest_path = staging_dir / "staging_manifest.json"
            with open(manifest_path, "w") as f:
                json.dump(manifest, f, indent=2)

            return json.dumps({
                "success": True,
                "staging_dir": str(staging_dir),
                "staged_files": staged_files,
                "files": staged_entries,
                "file_count": len(staged_files),
                "manifest_path": str(manifest_path),
                "stage_mode": mode,
                "warnings": errors if errors else None
            })

        except Exception as e:
            logger.error(f"Failed to stage SemantiK outputs: {e}")
            return json.dumps({"error": str(e)})

    @mcp.tool()
    async def stage_dart_outputs(
        run_id: str,
        dart_html_paths: str,
        course_name: str,
        stage_mode: Optional[str] = None,
    ) -> str:
        """Legacy pre-SemantiK tool-name alias for ``stage_semantik_outputs``.

        Kept registered so external MCP clients / paused runs that still
        invoke the old tool name continue to resolve. Delegates verbatim.
        """
        return await stage_semantik_outputs(
            run_id, dart_html_paths, course_name, stage_mode
        )

    @mcp.tool()
    async def get_pipeline_status(workflow_id: str) -> str:
        """
        Get status of a textbook-to-course pipeline.

        Args:
            workflow_id: The workflow ID returned by create_textbook_pipeline

        Returns:
            JSON with current phase, progress, and phase outputs
        """
        try:
            # Read workflow state directly (get_workflow_status is a closure
            # inside register_orchestrator_tools, not importable at module level)
            workflow_path = PROJECT_ROOT / "state" / "workflows" / f"{workflow_id}.json"
            if not workflow_path.exists():
                return json.dumps({"error": f"Workflow not found: {workflow_id}"})
            with open(workflow_path) as f:
                workflow = json.load(f)

            # Enhance with pipeline-specific information
            params = workflow.get("params", {})

            pipeline_status = {
                "workflow_id": workflow.get("id"),
                "workflow_type": workflow.get("type"),
                "status": workflow.get("status"),
                "run_id": params.get("run_id"),
                "course_name": params.get("course_name"),
                "progress": workflow.get("progress"),
                "created_at": workflow.get("created_at"),
                "updated_at": workflow.get("updated_at"),
                "phases": {
                    "semantik_conversion": _get_phase_status(
                        workflow, "semantik_conversion"
                    ),
                    "staging": _get_phase_status(workflow, "staging"),
                    "objective_extraction": _get_phase_status(workflow, "objective_extraction"),
                    "course_planning": _get_phase_status(workflow, "course_planning"),
                    "content_generation": _get_phase_status(workflow, "content_generation"),
                    "packaging": _get_phase_status(workflow, "packaging"),
                    "trainforge_assessment": _get_phase_status(workflow, "trainforge_assessment"),
                    "libv2_archival": _get_phase_status(workflow, "libv2_archival"),
                    "finalization": _get_phase_status(workflow, "finalization")
                },
                "params": params
            }

            return json.dumps(pipeline_status)

        except Exception as e:
            logger.error(f"Failed to get pipeline status: {e}")
            return json.dumps({"error": str(e)})

    @mcp.tool()
    async def validate_semantik_markers(html_path: str) -> str:
        """
        Validate that an HTML file has required SemantiK markers.

        SemantiK-processed HTML must have:
        - Skip link (<a class="skip-link">)
        - Main content area (<main role="main">)
        - Semantic sections (<section aria-labelledby="...">)

        Args:
            html_path: Path to HTML file to validate

        Returns:
            JSON with validation results
        """
        try:
            path = Path(html_path)
            if not path.exists():
                return json.dumps({"error": f"File not found: {html_path}"})

            with open(path, encoding="utf-8") as f:
                content = f.read()

            markers = {
                "skip_link": 'class="skip' in content or "class='skip" in content,
                "main_role": 'role="main"' in content or "role='main'" in content,
                "aria_sections": 'aria-labelledby="' in content or "aria-labelledby='" in content,
                # Structural section classes: accept the legacy pre-SemantiK
                # spelling too so already-packaged corpora still validate.
                "semantik_structure_classes": (
                    'semantik-section' in content or 'semantik-document' in content
                    or 'dart-section' in content or 'dart-document' in content
                ),
            }

            all_valid = all(markers.values())

            result = {
                "valid": all_valid,
                "file": str(path),
                "markers": markers,
                "missing": [k for k, v in markers.items() if not v]
            }

            if not all_valid:
                result["message"] = f"Missing SemantiK markers: {result['missing']}"

            return json.dumps(result)

        except Exception as e:
            logger.error(f"Failed to validate SemantiK markers: {e}")
            return json.dumps({"error": str(e)})

    @mcp.tool()
    async def validate_dart_markers(html_path: str) -> str:
        """Legacy pre-SemantiK tool-name alias for ``validate_semantik_markers``.

        Kept registered so external MCP clients / paused runs that still
        invoke the old tool name continue to resolve. Delegates verbatim.
        """
        return await validate_semantik_markers(html_path)


    @mcp.tool()
    async def synthesize_training(
        corpus_dir: str,
        course_code: str,
        provider: str = "mock",
        seed: Optional[int] = None,
        with_kg_metadata: bool = False,
        kg_metadata_max_pairs: int = 2000,
        with_violation_detection: bool = False,
        violation_detection_max_pairs: Optional[int] = None,
        with_abstention: bool = False,
        abstention_max_pairs: int = 1000,
        with_schema_translation: bool = False,
        schema_translation_max_pairs: int = 50,
    ) -> str:
        """Generate SFT + DPO training pairs from a Trainforge corpus.

        Wave 30 Gap 3: exposes
        :func:`Trainforge.synthesize_training.run_synthesis` as an MCP
        tool so external clients + the textbook_to_course pipeline both
        route to the same backing implementation. Reads
        ``{corpus_dir}/corpus/chunks.jsonl`` and writes
        ``{corpus_dir}/training_specs/instruction_pairs.jsonl`` +
        ``{corpus_dir}/training_specs/preference_pairs.jsonl``.

        Args:
            corpus_dir: Trainforge output directory (the one containing
                ``corpus/`` and ``training_specs/``).
            course_code: Course identifier for decision capture.
            provider: Synthesis provider. Accepted values:

                * ``"mock"`` (default) — deterministic template factory.
                * ``"anthropic"`` — Anthropic SDK paraphrase pass
                  (requires ``ANTHROPIC_API_KEY``). Anthropic's ToS
                  forbids using the output as training data, so use only
                  for in-house evaluation, not for SLM training corpora.
                * ``"claude_session"`` — Claude Code session via
                  LocalDispatcher (Claude Max path).
                * ``"together"`` — Together AI's OpenAI-compatible
                  chat-completions endpoint, default model
                  ``meta-llama/Llama-3.3-70B-Instruct-Turbo``
                  (override via ``TOGETHER_SYNTHESIS_MODEL``; requires
                  ``TOGETHER_API_KEY``). Together's ToS explicitly
                  permits using the output as training data — this is
                  the ToS-clean teacher pass for SLM corpora.
                * ``"local"`` — a local OpenAI-compatible model server
                  (Ollama / vLLM / llama.cpp / LM Studio). Default base
                  URL ``http://localhost:11434/v1`` (override via
                  ``LOCAL_SYNTHESIS_BASE_URL``); default model
                  ``qwen2.5:7b-instruct-q4_K_M`` (override via
                  ``LOCAL_SYNTHESIS_MODEL``). API key optional. Zero
                  per-call cost, zero ToS exposure (fully offline /
                  air-gapped friendly); tradeoff is local hardware.
            seed: Optional base seed for determinism.
            with_kg_metadata: Enable the deterministic kg_metadata
                generator (Wave 124a). Reads pedagogy_graph.json. No-op
                when the graph is absent.
            kg_metadata_max_pairs: Cap on kg_metadata pairs (default
                2000).
            with_violation_detection: Enable the deterministic SHACL
                violation generator (Wave 125a; pyshacl-oracle-verified).
            violation_detection_max_pairs: Cap on violation pairs
                (default unset = unlimited; family-balanced round-robin
                trim when set).
            with_abstention: Enable the deterministic abstention
                generator (Wave 124). Emits "the source does not
                establish X" probes from concepts the chunk does NOT
                address. Reads pedagogy_graph.json.
            abstention_max_pairs: Cap on abstention pairs (default
                1000).
            with_schema_translation: Enable the deterministic
                schema-translation generator (Wave 125b). Emits 6
                families × 6 surface forms (definition / usage /
                comparison / reasoning / pitfall / combination).
            schema_translation_max_pairs: Cap on schema-translation
                pairs (default 50).

        Returns:
            JSON with ``success``, the two output paths, and a stats
            summary. When ``chunks.jsonl`` is missing the call returns
            ``{"success": true, "skipped": true}`` so callers never
            crash on the no-LLM-available / no-corpus path.
        """
        try:
            from Trainforge.synthesize_training import (
                DEFAULT_SEED,
                run_synthesis,
            )
        except Exception as exc:
            return json.dumps({
                "error": f"Failed to import synthesize_training: {exc}",
            })

        corpus_dir_path = Path(corpus_dir)
        # Phase 7c: prefer imscc_chunks/, fall back to legacy corpus/.
        from lib.libv2_storage import resolve_imscc_chunks_path
        chunks_path = resolve_imscc_chunks_path(corpus_dir_path, "chunks.jsonl")
        if not chunks_path.exists():
            logger.warning(
                "synthesize_training: chunks.jsonl missing at %s; skipping",
                chunks_path,
            )
            return json.dumps({
                "success": True,
                "skipped": True,
                "reason": "chunks_missing",
                "corpus_dir": str(corpus_dir_path),
            })

        if seed is None:
            seed = DEFAULT_SEED

        try:
            stats = run_synthesis(
                corpus_dir=corpus_dir_path,
                course_code=course_code,
                provider=provider,
                seed=int(seed),
                with_kg_metadata=with_kg_metadata,
                kg_metadata_max_pairs=kg_metadata_max_pairs,
                with_violation_detection=with_violation_detection,
                violation_detection_max_pairs=violation_detection_max_pairs,
                with_abstention=with_abstention,
                abstention_max_pairs=abstention_max_pairs,
                with_schema_translation=with_schema_translation,
                schema_translation_max_pairs=schema_translation_max_pairs,
            )
        except Exception as exc:
            return json.dumps({
                "error": f"synthesize_training failed: {exc}",
                "corpus_dir": str(corpus_dir_path),
            })

        return json.dumps({
            "success": True,
            "corpus_dir": str(corpus_dir_path),
            "instruction_pairs_path": str(
                corpus_dir_path / "training_specs" / "instruction_pairs.jsonl"
            ),
            "preference_pairs_path": str(
                corpus_dir_path / "training_specs" / "preference_pairs.jsonl"
            ),
            "instruction_pairs_count": stats.instruction_pairs_emitted,
            "preference_pairs_count": stats.preference_pairs_emitted,
            "chunks_eligible": stats.chunks_eligible,
            "chunks_total": stats.chunks_total,
            "stats": stats.as_dict(),
        })

    @mcp.tool()
    async def archive_to_libv2(
        course_name: str,
        domain: str,
        division: str = "STEM",
        pdf_paths: Optional[str] = None,
        html_paths: Optional[str] = None,
        imscc_path: Optional[str] = None,
        assessment_path: Optional[str] = None,
        subdomains: Optional[str] = None,
        concept_graph_sha256: Optional[str] = None,
        dart_chunks_sha256: Optional[str] = None,
        imscc_chunks_sha256: Optional[str] = None,
        license_note: Optional[str] = None,
        attribution: Optional[str] = None,
    ) -> str:
        """
        Archive all pipeline artifacts to LibV2 unified repository.

        Stores raw inputs (PDFs), DART outputs (HTML), course packages (IMSCC),
        and RAG corpus together under a single course slug.

        Args:
            course_name: Course identifier (e.g., "PHYS_101")
            domain: Primary domain (e.g., "physics", "computer-science")
            division: Division classification ("STEM" or "ARTS", default: "STEM")
            pdf_paths: Comma-separated paths to original PDF inputs
            html_paths: Comma-separated paths to DART HTML outputs
            imscc_path: Path to Courseforge IMSCC package
            assessment_path: Path to Trainforge assessment JSON
            subdomains: Comma-separated subdomains (e.g., "mechanics,thermodynamics")
            concept_graph_sha256: Phase 8 ST 1 — optional 64-hex SHA256 of the
                ``concept_graph_semantic.json`` produced by ``concept_extraction``.
                When well-formed, persisted to ``manifest.concept_graph_sha256``;
                malformed values silently dropped (mirrors registry variant's
                ``INVALID_*`` fall-through). Default ``None`` for back-compat
                with legacy MCP clients.
            dart_chunks_sha256: Phase 8 ST 1 — optional 64-hex SHA256 of the
                DART chunkset (``dart_chunks/chunks.jsonl``) produced by the
                ``chunking`` phase. Same emit + drop semantics as above.
            imscc_chunks_sha256: Phase 8 ST 1 — optional 64-hex SHA256 of the
                IMSCC chunkset (``imscc_chunks/chunks.jsonl``) produced by the
                ``imscc_chunking`` phase. Same emit + drop semantics as above.

        Returns:
            JSON with course_slug, storage paths, and archival status
        """
        try:
            libv2_root = PROJECT_ROOT / "LibV2"

            # Generate slug from course name. W0.4: route through the
            # canonical archive-directory slug helper (single source of truth
            # used by the LibV2 importer) instead of a raw inline transform, so
            # an archive dir and every other consumer of the slug agree
            # byte-for-byte. ``libv2_course_slug`` is byte-identical to the old
            # inline ``.lower().replace("_","-").replace(" ","-")`` for the
            # common ``PHYS_101`` / spaced-name cases AND additionally
            # normalises punctuation (e.g. a stray ``:``) that the inline
            # transform leaked into the dir name.
            from lib.ontology.slugs import libv2_course_slug as _libv2_course_slug  # noqa: PLC0415
            slug = _libv2_course_slug(course_name)

            # Create course directory structure
            course_dir = libv2_root / "courses" / slug
            for subdir in [
                "source/pdf", "source/html", "source/imscc",
                "corpus", "graph", "pedagogy", "training_specs", "quality"
            ]:
                (course_dir / subdir).mkdir(parents=True, exist_ok=True)

            archived = {"pdfs": [], "html": [], "imscc": None, "assessment": None}

            # Archive raw PDFs
            if pdf_paths:
                for pdf_str in pdf_paths.split(","):
                    pdf = Path(pdf_str.strip())
                    if pdf.exists():
                        dest = course_dir / "source" / "pdf" / pdf.name
                        shutil.copy2(pdf, dest)
                        archived["pdfs"].append(str(dest))

            # Archive DART HTML outputs
            if html_paths:
                for html_str in html_paths.split(","):
                    html_file = Path(html_str.strip())
                    if html_file.exists():
                        dest = course_dir / "source" / "html" / html_file.name
                        shutil.copy2(html_file, dest)
                        archived["html"].append(str(dest))
                        # Also copy quality JSON if present
                        quality_json = html_file.with_suffix(".quality.json")
                        if quality_json.exists():
                            shutil.copy2(
                                quality_json,
                                course_dir / "quality" / quality_json.name
                            )
                        # Wave 19: archive ``{stem}_figures/`` sibling dir
                        # when it exists so LibV2 stores the portable
                        # bundle alongside the HTML.
                        figures_dir_src = (
                            html_file.parent / f"{html_file.stem}_figures"
                        )
                        if figures_dir_src.is_dir():
                            figures_dir_dest = (
                                course_dir / "source" / "html"
                                / figures_dir_src.name
                            )
                            if figures_dir_dest.exists():
                                shutil.rmtree(figures_dir_dest)
                            shutil.copytree(figures_dir_src, figures_dir_dest)

            # Archive IMSCC package
            if imscc_path:
                imscc = Path(imscc_path)
                if imscc.exists():
                    dest = course_dir / "source" / "imscc" / imscc.name
                    shutil.copy2(imscc, dest)
                    archived["imscc"] = str(dest)

            # Archive assessment / RAG corpus output
            # Phase 7c: write to imscc_chunks/ (canonical).
            if assessment_path:
                assess = Path(assessment_path)
                if assess.exists():
                    dest = course_dir / "imscc_chunks" / assess.name
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(assess, dest)
                    archived["assessment"] = str(dest)
                    # Wave 30 Gap 3: when the caller points us at an
                    # assessments.json (or its containing directory), also
                    # pick up the Wave 30 training_synthesis artifacts.
                    # Mirrors the registry variant's copy_map; we keep the
                    # probe cheap so a missing sibling dir stays silent.
                    assess_parent = assess.parent if assess.is_file() else assess
                    for sibling_name in ("training_specs",):
                        sibling_dir = assess_parent / sibling_name
                        if not sibling_dir.is_dir():
                            # trainforge_dir might be the parent of parent.
                            sibling_dir = assess_parent.parent / sibling_name
                        if not sibling_dir.is_dir():
                            continue
                        for fname in (
                            "instruction_pairs.jsonl",
                            "preference_pairs.jsonl",
                            "dataset_config.json",
                        ):
                            src = sibling_dir / fname
                            if src.exists() and src.is_file():
                                dest = (
                                    course_dir / "training_specs" / fname
                                )
                                try:
                                    shutil.copy2(src, dest)
                                    archived.setdefault(
                                        "training_specs", []
                                    ).append(str(dest))
                                except OSError as _exc:
                                    logger.debug(
                                        "archive_to_libv2: failed to copy %s: %s",
                                        src, _exc,
                                    )
                    # Wave 30 Gap 4: course.json is materialised alongside
                    # assessments.json (trainforge_dir / course.json).
                    for _course_root in (
                        assess_parent,
                        assess_parent.parent,
                    ):
                        _cj = _course_root / "course.json"
                        if _cj.exists() and _cj.is_file():
                            try:
                                shutil.copy2(_cj, course_dir / "course.json")
                                archived["course_json"] = str(
                                    course_dir / "course.json"
                                )
                                break
                            except OSError as _exc:
                                logger.debug(
                                    "archive_to_libv2: course.json copy failed: %s",
                                    _exc,
                                )

            # Build manifest
            import hashlib

            def _sha256(filepath: Path) -> str:
                h = hashlib.sha256()
                with open(filepath, "rb") as f:
                    for chunk in iter(lambda: f.read(8192), b""):
                        h.update(chunk)
                return h.hexdigest()

            source_artifacts = {}
            if archived["pdfs"]:
                source_artifacts["pdf"] = [
                    {"path": p, "checksum": _sha256(Path(p)), "size": Path(p).stat().st_size}
                    for p in archived["pdfs"]
                ]
            if archived["html"]:
                source_artifacts["html"] = [
                    {"path": p, "checksum": _sha256(Path(p)), "size": Path(p).stat().st_size}
                    for p in archived["html"]
                ]
            if archived["imscc"]:
                imscc_p = Path(archived["imscc"])
                source_artifacts["imscc"] = {
                    "path": archived["imscc"],
                    "checksum": _sha256(imscc_p),
                    "size": imscc_p.stat().st_size,
                }

            # Wave 10: advisory feature flag — scan the archived corpus's
            # chunks.jsonl (if any) for chunks carrying
            # source.source_references[]. Lets LibV2 retrieval callers
            # fast-skip source-grounded queries on legacy corpora.
            # Defaults false when no chunks file is found, when it can't
            # be read, or when no chunks carry refs.
            source_provenance_flag = _detect_source_provenance(course_dir)

            # Wave 11: companion flag for evidence-arm source_references[].
            # True when the archived concept_graph_semantic.json carries at
            # least one edge with evidence.source_references[]. Lets
            # consumers distinguish chunk-level (Wave 10) from evidence-
            # level (Wave 11) provenance.
            evidence_source_provenance_flag = _detect_evidence_source_provenance(course_dir)

            # B3: optional license/attribution declarations (parity with the
            # registry variant). Absent == byte-identical manifest + no NOTICE.
            license_field = _normalize_license_field(license_note)
            attribution_field = _normalize_attribution_field(attribution)

            manifest = {
                "libv2_version": "1.2.0",
                # OP4: on-disk course-layout contract version (see registry
                # variant + docs/operations/library-versioning.md).
                "library_format_version": LIBRARY_FORMAT_VERSION,
                "chunker_version": _resolve_chunker_version(),
                # Chunk-TEXT extraction-contract version (orthogonal to
                # chunker_version) so a fully-archived corpus carries the
                # same provenance marker as its chunkset sidecars.
                "extraction_contract": _resolve_extraction_contract(),
                "slug": slug,
                "import_timestamp": datetime.now().isoformat(),
                "classification": {
                    "division": division,
                    "primary_domain": domain,
                    "subdomains": [s.strip() for s in subdomains.split(",")] if subdomains else [],
                },
                "source_artifacts": source_artifacts,
                "provenance": {
                    "source_type": "textbook_to_course_pipeline",
                    "import_pipeline_version": "1.0.0",
                },
                "features": {
                    "source_provenance": source_provenance_flag,
                    "evidence_source_provenance": evidence_source_provenance_flag,
                },
            }
            if license_field:
                manifest["license"] = license_field
            if attribution_field:
                manifest["attribution"] = attribution_field

            # Phase 8 ST 1: persist the three SHA256 fields when callers thread
            # them via kwargs. Same ``^[0-9a-f]{64}$`` regex shape as the
            # registry variant at ``:5667-5687, :5720-5727`` — only emit when
            # the kwarg is well-formed so a malformed value falls through to
            # the validator's ``MISSING_*`` critical (the validator owns
            # ``INVALID_*`` shape diagnostics).
            #
            # Intentional asymmetry vs registry variant: this @mcp.tool()
            # surface is kwarg-only — no on-disk recompute fallback for
            # ``concept_graph_sha256``. The recompute path lives only in the
            # registry variant because that surface is workflow-runner-driven
            # and can resolve the on-disk artifact path; external MCP clients
            # call this @mcp.tool() variant directly and pass paths
            # explicitly. See plans/phase8_cleanup.md pre-resolved decision #1.
            import re as _re_sha
            _SHA_RE = r"^[0-9a-f]{64}$"
            if concept_graph_sha256 and _re_sha.match(_SHA_RE, concept_graph_sha256):
                manifest["concept_graph_sha256"] = concept_graph_sha256
            if dart_chunks_sha256 and _re_sha.match(_SHA_RE, dart_chunks_sha256):
                # DART->semantik purge Stage 3c: persist the ratified
                # ``semantik_chunks_sha256`` manifest key (was
                # ``dart_chunks_sha256``). The kwarg name stays ``dart_chunks_sha256``
                # (routed via the workflow-runner param name); the course_manifest
                # schema's top-level anyOf accepts EITHER field and
                # LibV2ManifestValidator._check_dart_chunks_sha256 dual-reads both,
                # so existing dart-form manifests stay valid.
                manifest["semantik_chunks_sha256"] = dart_chunks_sha256
            if imscc_chunks_sha256 and _re_sha.match(_SHA_RE, imscc_chunks_sha256):
                manifest["imscc_chunks_sha256"] = imscc_chunks_sha256

            # GPT Feedback v2 (May 12 / item 3): lineage mirror. Same shape
            # as the registry variant — build a dedup'd index of every
            # source-document SHA from source_artifacts, then mirror the
            # graph-level lineage fields from concept_graph_semantic.json.
            _src_doc_shas: set = set()
            for entry in source_artifacts.get("pdf", []) or []:
                cs = entry.get("checksum") if isinstance(entry, dict) else None
                if isinstance(cs, str) and _re_sha.match(_SHA_RE, cs):
                    _src_doc_shas.add(cs)
            for entry in source_artifacts.get("html", []) or []:
                cs = entry.get("checksum") if isinstance(entry, dict) else None
                if isinstance(cs, str) and _re_sha.match(_SHA_RE, cs):
                    _src_doc_shas.add(cs)
            imscc_entry = source_artifacts.get("imscc")
            if isinstance(imscc_entry, dict):
                cs = imscc_entry.get("checksum")
                if isinstance(cs, str) and _re_sha.match(_SHA_RE, cs):
                    _src_doc_shas.add(cs)
            if _src_doc_shas:
                manifest["source_documents_sha256_index"] = sorted(_src_doc_shas)

            # Mirror graph-level lineage when graph already on disk.
            _cg_path = course_dir / "graph" / "concept_graph_semantic.json"
            if _cg_path.exists() and _cg_path.is_file():
                try:
                    _cg_json = json.loads(_cg_path.read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    _cg_json = None
                if isinstance(_cg_json, dict):
                    _gbh = _cg_json.get("graph_build_hash")
                    if isinstance(_gbh, str) and _re_sha.match(_SHA_RE, _gbh):
                        manifest["graph_build_hash"] = _gbh
                    _rpv = _cg_json.get("rulepack_version")
                    if isinstance(_rpv, str) and _re_sha.match(r"^v[0-9a-f]+$", _rpv):
                        manifest["rulepack_version"] = _rpv
                    if "course_package_version" in _cg_json:
                        _cpv = _cg_json["course_package_version"]
                        if _cpv is None or (
                            isinstance(_cpv, str) and _cpv
                        ):
                            manifest["course_package_version"] = _cpv

            manifest_path = course_dir / "manifest.json"
            # W0.7: atomic temp-then-replace so a crash mid-write never leaves a
            # truncated course manifest (the LibV2ManifestValidator parses it).
            _atomic_write_text(manifest_path, json.dumps(manifest, indent=2))

            # B3: write the human-readable NOTICE when license/attribution set.
            _write_course_notice(
                course_dir, slug, course_name, license_field, attribution_field
            )

            # F6: register the course in the LibV2 master catalog so that
            # ``libv2 catalog list`` / ``libv2 info <slug>`` see it immediately
            # without a separate manual ``index rebuild`` step.
            try:
                from LibV2.tools.libv2.catalog import _register_course_in_catalog
                _register_course_in_catalog(slug, manifest, libv2_root)
            except Exception as _exc:
                logger.warning(
                    "archive_to_libv2: catalog registration failed for %s: %s",
                    slug, _exc,
                )

            return json.dumps({
                "success": True,
                "course_slug": slug,
                "course_dir": str(course_dir),
                "manifest_path": str(manifest_path),
                "archived": archived,
                "artifact_counts": {
                    "pdfs": len(archived["pdfs"]),
                    "html_files": len(archived["html"]),
                    "imscc": 1 if archived["imscc"] else 0,
                    "assessment": 1 if archived["assessment"] else 0,
                },
            })

        except Exception as e:
            logger.error(f"Failed to archive to LibV2: {e}")
            return json.dumps({"error": str(e)})

    # Wave 28f: run_textbook_pipeline_tool was removed. External MCP
    # clients now route through the workflow API. The underlying
    # non-tool ``run_textbook_pipeline()`` coroutine above remains for
    # internal callers.


# ---------------------------------------------------------------------------
# SemantiK v2 conversion seam (Phase P3b).
#
# The chokepoint that runs the SemantiK v2 cascade → chapters-IR →
# output-contract adapter → writes the normalized `{stem}_accessible.html`
# + `{stem}_synthesized.json` + `{stem}.quality.json` sidecars and returns
# the existing Ed4All tool JSON contract (config/workflows.yaml:898 required
# keys + the new SemantiK provenance keys).
#
# Unit-tested with a MOCKED cascade (no models/GPU).
# ---------------------------------------------------------------------------

# `--reuse-conversion` env mirror (analogous to the
# `--reuse-objectives` plumbing). When truthy AND prior artifacts exist at the
# output path, the cascade is skipped and the prior HTML + sidecars are reused
# (model-nondeterminism guarantee on re-runs). Parse-with-fallback truthy set
# (mirrors COURSEFORGE_TWO_PASS / the answer-path knobs).
_REUSE_CONVERSION_ENV = "ED4ALL_REUSE_CONVERSION"
_REUSE_CONVERSION_TRUTHY = frozenset({"1", "true", "yes", "on"})

# §3.7 / Section 9 mock trap — the runtime_mode values that count as a REAL
# cascade run. Anything else (mock / unset) fails closed (R4) so plausible-but-
# fake mock HTML never ships as if it were a real conversion.
_SEMANTIK_REAL_RUNTIME_MODES = frozenset({"real"})

# §5 / Section 8 (M4) — cross-venv subprocess bridge operator env vars. The
# SemantiK v2 cascade's heavy runtime deps (axe-playwright-python /
# llama-cpp-CUDA / torch + the 11GB GGUF/council weights) are NOT installed in
# Ed4All's slim venv. When the in-process ``run_pipeline_v2`` import fails AND
# these are set, the seam shells out to
# ``SemantiK/scripts/run_cascade_json.py`` running in the SemantiK runtime
# venv (it writes a JSON bridge file the seam reads back). NO machine-specific
# default path lives in tracked code — both default to ``None`` (→ fail-closed
# clear error telling the operator to set them).
#   * SEMANTIK_PYTHON      : the SemantiK runtime venv's python interpreter.
#   * SEMANTIK_RUNTIME_DIR : the SemantiK runtime repo root, used as the
#                            subprocess ``cwd`` (the cascade resolves its
#                            model/cache dirs relative to cwd).
_SEMANTIK_PYTHON_ENV = "SEMANTIK_PYTHON"
_SEMANTIK_RUNTIME_DIR_ENV = "SEMANTIK_RUNTIME_DIR"
# Graceful-stop declared-env plumbing for the SemantiK cascade seam (Wave E /
# plan P6). The cascade runs in its OWN venv (in-process on Ed4All's sys.path,
# or the fully out-of-process JSON bridge) and MUST NOT import Ed4All's
# ``lib/generation/stop_control`` — so, exactly like the GPU-lifecycle
# cross-venv twin, Ed4All resolves the active run's stop-sentinel PATH(s) and
# hands them to the cascade's own ``semantik_structure.stop_seam`` via this env var
# (``os.pathsep``-joined). It carries a PATH, selects no provider/model, and is
# a byte-identical no-op when unset → declared-env plumbing, NOT a behavior flag
# (no LICENSING / behavior-flags row). The seam raises the SemantiK-local
# ``CascadeStopRequested`` on observing a listed sentinel, which this module
# translates to ``GracefulStopRequested`` at the conversion boundary.
_SEMANTIK_STOP_SENTINEL_ENV = "SEMANTIK_STOP_SENTINEL"
# Path to the SemantiK-side runner script (vendored under SemantiK/scripts/).
# Resolved relative to the repo root so no absolute path is hardcoded.
_SEMANTIK_RUNNER_SCRIPT = (
    Path(__file__).resolve().parents[2] / "SemantiK" / "scripts" / "run_cascade_json.py"
)
# Generous default subprocess timeout (s) — a real cascade run does 11GB of
# model work; the operator can override with SEMANTIK_BRIDGE_TIMEOUT_SECONDS.
_SEMANTIK_BRIDGE_TIMEOUT_ENV = "SEMANTIK_BRIDGE_TIMEOUT_SECONDS"
_SEMANTIK_BRIDGE_TIMEOUT_DEFAULT = 3600.0

# Opt-in gate for the expandable-segments CUDA allocator conf (see the R7 note
# at the bridge_env block). Mirrors the per-flag frozenset pattern used above.
_SEMANTIK_EXPANDABLE_SEGMENTS_TRUTHY = frozenset({"1", "true", "yes", "on"})


def _semantik_expandable_segments_enabled() -> bool:
    """True iff SEMANTIK_EXPANDABLE_SEGMENTS is truthy (1/true/yes/on)."""
    return (
        (os.environ.get("SEMANTIK_EXPANDABLE_SEGMENTS") or "").strip().lower()
        in _SEMANTIK_EXPANDABLE_SEGMENTS_TRUTHY
    )


def _resolve_semantik_bridge_timeout() -> float:
    """Resolve the subprocess bridge timeout (parse-with-fallback)."""
    raw = (os.environ.get(_SEMANTIK_BRIDGE_TIMEOUT_ENV) or "").strip()
    try:
        val = float(raw)
        if val > 0:
            return val
    except (TypeError, ValueError):
        pass
    return _SEMANTIK_BRIDGE_TIMEOUT_DEFAULT


class _SemantikBridgeResult:
    """Duck-typed ``PipelineV2Result`` reconstructed from the bridge JSON.

    Carries exactly the attributes the rest of the seam reads off the
    cascade result: ``runtime_mode`` (R4 mock-trap), ``region_provenance`` +
    ``heading_tree`` (consumed by ``build_chapters_ir``), and the doc-level
    signals the adapter reads (``exit_action`` / ``wcag_status`` /
    ``theta_score`` / ``flags`` / ``lane_used`` / ``html``). This lets the
    subprocess path re-join the SAME downstream code as the in-process path
    (runtime-mode check → IR → adapter) with no branching.
    """

    def __init__(self, bridge: Dict[str, Any]):
        self.pdf = bridge.get("pdf")
        self.html = bridge.get("html") or ""
        self.region_provenance = list(bridge.get("region_provenance") or [])
        self.heading_tree = [list(e) for e in (bridge.get("heading_tree") or [])]
        self.exit_action = bridge.get("exit_action")
        self.wcag_status = bridge.get("wcag_status")
        self.theta_score = bridge.get("theta_score")
        self.flags = list(bridge.get("flags") or [])
        self.lane_used = bridge.get("lane_used")
        self.runtime_mode = bridge.get("runtime_mode")
        self.lang = bridge.get("lang") or "en"
        # Phase 3 item 7 — the doc-level Stage-5d structure-review verdict list
        # the bridge JSON surfaces at top level (``None`` when the reviewer was
        # off, ``[]`` when it ran and found nothing to correct). The seam reads
        # this to emit ONE ``structure_review`` DecisionCapture per doc.
        sr = bridge.get("structure_review")
        self.structure_review = (
            list(sr) if isinstance(sr, (list, tuple)) else None
        )
        # SEMANTIK_BLOCK_RESEGMENT audit — the doc-level list of block
        # merge/split ops the cascade surfaces at top level (``None`` when the
        # re-segmenter was off, ``[]`` when it ran and made no edits). The seam
        # reads this to emit ONE ``block_resegment`` DecisionCapture per doc.
        br = bridge.get("block_resegment")
        self.block_resegment = (
            list(br) if isinstance(br, (list, tuple)) else None
        )
        # Phase 6/7 — the Stage-9 Pass-2 verify-refine per-round audit arm the
        # cascade surfaces at top level (``None`` when SEMANTIK_SECOND_PASS was
        # off / no round ran). Unlike the structure_review / block_resegment
        # arms (lists), this is a DICT (``{"adopted": ..., "rounds": [...]}``).
        # The seam reads this to emit ONE ``structure_review`` DecisionCapture
        # (``second_pass_verify`` sub-tag) PER verify round.
        spv = bridge.get("second_pass_verify")
        self.second_pass_verify = spv if isinstance(spv, dict) else None
        # SEMANTIK_OCR_CONFUSABLE_REPAIR audit — the doc-level repair-stats DICT
        # the cascade surfaces at top level (``None`` when the pass was off). The
        # seam reads this to emit ONE ``structure_review`` DecisionCapture per
        # converted doc (``ocr_confusable_repair`` metadata discriminator).
        ocr = bridge.get("ocr_repair")
        self.ocr_repair = ocr if isinstance(ocr, dict) else None
        # Stage 9b — the reasoning-QC audit DICT the cascade surfaces at top
        # level (``None`` when SEMANTIK_REASONING_QC was off). Like the
        # second_pass_verify / ocr_repair arms this is a DICT; the seam reads it
        # to emit ONE ``structure_detection`` DecisionCapture per converted doc.
        rqc = bridge.get("reasoning_qc")
        self.reasoning_qc = rqc if isinstance(rqc, dict) else None
        # task #43 — the SEMANTIK_UNIT_COVERAGE_GATE content-loss report DICT the
        # cascade surfaces at top level (``None`` when the gate was off). Threaded
        # into the emitted cascade_ir.json + the quality-sidecar issues; the
        # bridge previously DROPPED it so the operator artifacts never saw it.
        uc = bridge.get("unit_coverage")
        self.unit_coverage = uc if isinstance(uc, dict) else None
        # task #43 — the SEMANTIK_PAGE_ARRANGER scan-lane audit DICT the cascade
        # surfaces at top level (``None`` when the arranger did not own
        # structure). Threaded into the emitted cascade_ir.json.
        pa = bridge.get("page_arranger")
        self.page_arranger = pa if isinstance(pa, dict) else None


def _semantik_stop_sentinel_env_value() -> Optional[str]:
    """Build the ``SEMANTIK_STOP_SENTINEL`` value for the cascade seam (P6).

    Declared-env plumbing (a PATH, not a behavior flag): resolves the active
    run's stop sentinels — the global ``<state_runs>/STOP_ALL`` and, when an
    ``ED4ALL_RUN_ID`` resolves, the run-scoped
    ``<state_runs>/<run_id>/control/STOP_REQUESTED`` — and joins them with
    ``os.pathsep`` so the SemantiK cascade's cross-venv ``semantik_structure.stop_seam``
    twin (which must NOT import Ed4All's ``lib/``) can poll them at a seam
    boundary. Paths are built from ``stop_control``'s public sentinel-name
    constants + ``lib.paths.get_state_runs_dir`` (the SAME resolution
    ``stop_control`` uses — never CWD-relative, read per call), so a servicer /
    bridge launched from a non-repo-root CWD watches exactly the sentinel the
    CLI writes. The global path is always emitted (so ``ed4all stop --all``
    reaches a conversion even with no run_id); returns ``None`` only if the
    state-runs dir cannot be resolved, in which case the caller leaves the env
    unset → every cascade seam is a byte-identical no-op.
    """
    try:
        from lib.paths import get_state_runs_dir  # noqa: PLC0415

        runs_dir = get_state_runs_dir()
    except Exception:  # noqa: BLE001 — path resolution must never crash the seam
        return None
    paths: List[str] = [str(runs_dir / _STOP_GLOBAL_SENTINEL_NAME)]
    run_id = (os.environ.get("ED4ALL_RUN_ID") or "").strip()
    if run_id:
        paths.append(
            str(runs_dir / run_id / "control" / _STOP_RUN_SENTINEL_NAME)
        )
    return os.pathsep.join(paths)


def _run_semantik_bridge_subprocess(
    pdf: str, runtime: str = "auto"
) -> Dict[str, Any]:
    """Shell out to the SemantiK runtime venv via the JSON bridge (§5 / M4).

    Resolves ``SEMANTIK_PYTHON`` + ``SEMANTIK_RUNTIME_DIR`` (operator env, NO
    hardcoded default path). Invokes ``run_cascade_json.py`` with ``cwd`` set
    to the runtime repo root (the cascade resolves models relative to cwd),
    reads the JSON bridge file back, and returns it as a plain dict.

    Fail-closed (NO silent DART fallback). Returns a dict carrying ``error``
    (and never ``region_provenance``) on every failure path:
      * either env var unset            → ``error`` (operator guidance).
      * subprocess timeout / OSError    → ``error``.
      * non-zero exit                   → ``error`` (with stderr tail).
      * unreadable / non-JSON output    → ``error``.
      * JSON itself carries ``error``   → propagated (the runner caught an
                                          import / cascade failure).
    """
    import subprocess
    import tempfile

    semantik_python = (os.environ.get(_SEMANTIK_PYTHON_ENV) or "").strip()
    runtime_dir = (os.environ.get(_SEMANTIK_RUNTIME_DIR_ENV) or "").strip()
    if not semantik_python or not runtime_dir:
        return {
            "error": (
                "SemantiK runtime deps absent in this venv and the subprocess "
                "bridge is not configured: set SEMANTIK_PYTHON=<SemantiK venv "
                "python> and SEMANTIK_RUNTIME_DIR=<SemantiK repo root> to run "
                "the cascade out-of-process (no machine path is hardcoded)."
            )
        }
    if not _SEMANTIK_RUNNER_SCRIPT.is_file():
        return {
            "error": (
                f"SemantiK bridge runner script not found at "
                f"{_SEMANTIK_RUNNER_SCRIPT}; the vendored SemantiK/scripts/ dir "
                f"is required for the subprocess bridge."
            )
        }

    timeout = _resolve_semantik_bridge_timeout()
    with tempfile.TemporaryDirectory(prefix="semantik_bridge_") as tmpdir:
        out_json = Path(tmpdir) / "cascade_bridge.json"
        cmd = [
            semantik_python,
            str(_SEMANTIK_RUNNER_SCRIPT),
            "--pdf",
            str(pdf),
            "--out-json",
            str(out_json),
            "--runtime",
            runtime,
        ]
        # R7 VRAM-OOM mitigation: hand the SemantiK runtime subprocess the
        # theta-device hint so the Stage-12 theta DeBERTa doesn't OOM the
        # shared 8 GB card. theta->CPU (SEMANTIK_THETA_DEVICE=cpu) is the
        # PRIMARY OOM fix and is ALWAYS applied (setdefault — an operator who
        # exported SEMANTIK_THETA_DEVICE=cuda to opt the theta head back onto
        # the GPU keeps their choice). SEMANTIK_THETA_DEVICE is read by
        # semantik_structure.theta.semantic_preservation.load.
        #
        # PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True is OPT-IN via
        # SEMANTIK_EXPANDABLE_SEGMENTS because it can trigger a
        # CUDACachingAllocator INTERNAL ASSERT (!handles_.at(i)) in a council
        # BERT under some driver/torch combos. By default we do NOT touch
        # PYTORCH_CUDA_ALLOC_CONF at all (so the bridge env only carries it if
        # the operator already had it in os.environ). When opted in, setdefault
        # still means an operator's explicit value is never clobbered.
        bridge_env = dict(os.environ)
        bridge_env.setdefault("SEMANTIK_THETA_DEVICE", "cpu")
        # Graceful-stop (P6): hand the child the run's stop-sentinel PATH(s) via
        # declared-env plumbing (alongside SEMANTIK_PYTHON / SEMANTIK_RUNTIME_DIR)
        # so the cascade's cross-venv ``semantik_structure.stop_seam`` twin polls them
        # at a seam boundary and self-terminates instead of running the full
        # (~hours) authoring pass. Unset ⇒ every seam is a byte-identical no-op.
        _stop_sentinel = _semantik_stop_sentinel_env_value()
        if _stop_sentinel:
            bridge_env[_SEMANTIK_STOP_SENTINEL_ENV] = _stop_sentinel
        # LLM-usage-tap plumbing (OP2): the SemantiK-side meter
        # (``semantik_structure/llm_usage_meter.py``) resolves the run ledger
        # ``<state-runs>/<run_id>/llm_usage.jsonl`` from ``ED4ALL_RUN_ID`` +
        # ``ED4ALL_STATE_RUNS_DIR``. ``ED4ALL_RUN_ID`` is inherited from the
        # parent env (the orchestrator exports it), but the SemantiK venv
        # cannot import Ed4All's ``lib.paths`` — so without the explicit dir
        # export every meter row from the bridge subprocess silently fell to
        # the SemantiK data-dir sidecar instead of the run ledger the GUI
        # stats band reads. setdefault: an operator's explicit value wins.
        # Best-effort — path resolution must never break the conversion.
        try:
            from lib.paths import get_state_runs_dir  # noqa: PLC0415

            bridge_env.setdefault(
                "ED4ALL_STATE_RUNS_DIR", str(get_state_runs_dir())
            )
        except Exception:  # noqa: BLE001 — metering plumbing is best-effort
            pass
        if _semantik_expandable_segments_enabled():
            bridge_env.setdefault(
                "PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True"
            )
        try:
            proc = subprocess.run(
                cmd,
                cwd=runtime_dir,
                capture_output=True,
                text=True,
                timeout=timeout,
                env=bridge_env,
            )
        except subprocess.TimeoutExpired:
            return {
                "error": (
                    f"SemantiK bridge subprocess timed out after {timeout:.0f}s "
                    f"on {pdf}; raise {_SEMANTIK_BRIDGE_TIMEOUT_ENV} if the real "
                    f"cascade legitimately needs longer."
                )
            }
        except (OSError, subprocess.SubprocessError) as exc:
            return {
                "error": (
                    f"SemantiK bridge subprocess could not be launched "
                    f"({semantik_python}): {exc}"
                )
            }

        # The runner writes a structured {"error"} JSON on its own internal
        # failures even when it exits non-zero — prefer that over the raw
        # stderr so the operator sees the cascade-side message.
        bridge: Optional[Dict[str, Any]] = None
        if out_json.is_file():
            try:
                bridge = json.loads(out_json.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                bridge = None

        if isinstance(bridge, dict) and bridge.get("error"):
            return {"error": f"SemantiK cascade (bridge): {bridge['error']}"}

        if proc.returncode != 0:
            stderr_tail = (proc.stderr or "").strip()[-2000:]
            return {
                "error": (
                    f"SemantiK bridge subprocess exited {proc.returncode} on "
                    f"{pdf}: {stderr_tail or '(no stderr)'}"
                )
            }

        if not isinstance(bridge, dict):
            return {
                "error": (
                    f"SemantiK bridge wrote no readable JSON to {out_json} "
                    f"(exit 0 but missing/corrupt output)."
                )
            }
        return bridge


def _resolve_reuse_conversion(reuse_conversion: Optional[Any]) -> bool:
    """Resolve the effective `--reuse-conversion` / `ED4ALL_REUSE_CONVERSION`.

    Precedence: an explicit truthy ``reuse_conversion`` arg (a CLI flag value
    threaded through) > the ``ED4ALL_REUSE_CONVERSION`` env var. Parse-with-
    fallback: any non-truthy / garbage value resolves to ``False``.
    """
    if reuse_conversion is not None:
        if isinstance(reuse_conversion, bool):
            if reuse_conversion:
                return True
        else:
            if str(reuse_conversion).strip().lower() in _REUSE_CONVERSION_TRUTHY:
                return True
    env_val = (os.environ.get(_REUSE_CONVERSION_ENV) or "").strip().lower()
    return env_val in _REUSE_CONVERSION_TRUTHY


def _semantik_resolve_runtime_mode(cascade_result: Any) -> Optional[str]:
    """Pull the cascade ``runtime_mode`` off the result (R4 mock-trap input).

    SemantiK auto-derives ``real`` iff the Qwen specialists are loaded; it
    defaults to ``mock`` when GGUFs are absent (the wiring trap, cascade.py).
    The real ``PipelineV2Result.cascade`` carries the resolved mode; we accept
    it from ``.runtime_mode`` directly, from ``.cascade`` (dict or object), or
    from a bare mapping, returning ``None`` when nothing resolves (treated as
    NOT real → fail closed).
    """
    mode = getattr(cascade_result, "runtime_mode", None)
    cascade = getattr(cascade_result, "cascade", None)
    if mode is None:
        if isinstance(cascade, dict):
            mode = cascade.get("runtime_mode")
        elif cascade is not None:
            mode = getattr(cascade, "runtime_mode", None)
    if mode is None and isinstance(cascade_result, dict):
        mode = cascade_result.get("runtime_mode")
    # In-process arm fallback: ``run_full_cascade`` does NOT promote
    # ``runtime_mode`` to a top-level key of its result dict — only the
    # cross-venv bridge (``run_cascade_json.py``) does that. The canonical
    # in-process location is the conformance-audit provenance block
    # (``cascade["conformance_audit"]["provenance"]["runtime_mode"]``). Read it
    # as a fallback so a REAL in-process run is recognized as real; otherwise
    # the R4 mock-trap below fails closed on EVERY in-process conversion even
    # when the council + Qwen specialists generated for real.
    if mode is None:
        audit = None
        if isinstance(cascade, dict):
            audit = cascade.get("conformance_audit")
        elif isinstance(cascade_result, dict):
            audit = cascade_result.get("conformance_audit")
        if isinstance(audit, dict):
            provenance = audit.get("provenance")
            if isinstance(provenance, dict):
                mode = provenance.get("runtime_mode")
    return str(mode) if mode is not None else None


def _semantik_reuse_existing_artifacts(
    output_path: Path, html_path: Path
) -> Optional[Dict[str, Any]]:
    """Build a reuse return dict from prior on-disk artifacts (§3.3a item 2).

    Returns the same tool JSON contract a fresh conversion would, sourced from
    the prior ``{stem}_accessible.html`` + ``{stem}.quality.json`` sidecar
    (success / certification / theta read back from the quality sidecar so a
    reused flagged/non-certified doc keeps its provenance). Returns ``None``
    when the prior HTML is missing — the caller then runs the cascade.
    """
    if not html_path.is_file():
        return None
    try:
        html = html_path.read_text(encoding="utf-8")
    except OSError:
        return None
    quality_path = output_path.with_suffix(".quality.json")
    synth_path = output_path.parent / f"{output_path.with_suffix('').name}_synthesized.json"
    quality: Dict[str, Any] = {}
    if quality_path.is_file():
        try:
            quality = json.loads(quality_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            quality = {}
    exit_action = quality.get("exit_action")
    # Mirror the adapter's exit_action→success mapping so reuse is consistent
    # with a fresh run (a reused ship_with_flag stays success=True, flagged).
    from lib.semantik.adapter import _resolve_success as _semantik_resolve_success

    success, certification_status = _semantik_resolve_success(exit_action)
    # A reused doc whose quality sidecar predates the exit-action enrichment
    # (legacy) still counts as a successful reuse when WCAG passed.
    if exit_action is None:
        success = bool(quality.get("compliant", True))
        certification_status = quality.get("certification_status") or (
            "certified" if success else "error"
        )
    return {
        "success": success,
        "output_path": str(output_path),
        "output_paths": [str(output_path)],
        "html_path": str(html_path),
        "html_paths": [str(html_path)],
        "html_length": len(html),
        "html": html,
        "word_count": len(re.sub(r"<[^>]+>", " ", html).split()),
        "method": "semantik_v2",
        "reused_conversion": True,
        "wcag_status": quality.get("wcag_status"),
        "exit_action": exit_action,
        "theta_score": quality.get("theta_score"),
        "flags": list(quality.get("flags") or []),
        "certification_status": certification_status,
        "synthesized_sidecar_path": str(synth_path) if synth_path.is_file() else None,
        "quality_sidecar_path": str(quality_path) if quality_path.is_file() else None,
    }


def _semantik_resolve_structure_review(result: Any) -> Optional[List[Dict[str, Any]]]:
    """Pull the doc-level Stage-5d ``structure_review`` verdict list off a
    cascade result, from EITHER seam arm (Phase 3 item 9).

    Resolution order:
      1. ``result.structure_review`` — the bridge arm
         (``_SemantikBridgeResult``) surfaces it as a top-level attribute.
      2. ``result.cascade["conformance_audit"]["structure_review"]`` — the
         in-process ``PipelineV2Result`` carries it inside the telemetry dict.

    Returns ``None`` when the reviewer did NOT run (flag off / no audit key) so
    the caller skips the capture cleanly; ``[]`` when it ran and found nothing.
    """
    sr = getattr(result, "structure_review", None)
    if sr is not None:
        return list(sr) if isinstance(sr, (list, tuple)) else None
    cascade = getattr(result, "cascade", None)
    if isinstance(cascade, dict):
        conformance = cascade.get("conformance_audit")
        if isinstance(conformance, dict):
            audit = conformance.get("structure_review")
            if audit is None:
                return None
            return list(audit) if isinstance(audit, (list, tuple)) else None
    return None


def _semantik_structure_review_model() -> str:
    """The reviewer seat model id for the DecisionCapture rationale.

    Mirrors ``SemantiK ... runtime.resolve_structure_review_model`` precedence
    (``SEMANTIK_STRUCTURE_REVIEW_MODEL`` > ``SEMANTIK_SPECIALIST_MODEL``)
    WITHOUT importing the heavy SemantiK runtime (absent from this venv). Used
    only for replay provenance, never to drive a call.
    """
    return (
        (os.environ.get("SEMANTIK_STRUCTURE_REVIEW_MODEL") or "").strip()
        or (os.environ.get("SEMANTIK_SPECIALIST_MODEL") or "").strip()
        or "unspecified"
    )


def _emit_structure_review_capture(
    verdicts: Optional[List[Dict[str, Any]]],
    *,
    canonical_course_code: Optional[str],
    pdf_stem: str,
) -> None:
    """Emit ONE ``structure_review`` DecisionCapture event per converted doc
    when the Stage-5d 70B reviewer ran (Phase 3 item 9).

    Best-effort by contract: ANY failure (DecisionCapture init, write, schema)
    logs a warning and returns — it NEVER breaks the conversion. Skips cleanly
    (no capture) when ``verdicts is None`` (the reviewer was off / provider or
    flag unset). The rationale is DYNAMIC/replayable per the CLAUDE.md contract:
    it interpolates blocks_reviewed / corrected / reverted_for_invariant / model
    so a post-hoc replay can attribute the structure corrections.

    ``decision_type='structure_review'`` is a canonical enum member
    (``schemas/events/decision_event.schema.json``), added for this seam.

    Phase 5 (SEMANTIK_BLOCK_REVIEW): when the windowed full-block reviewer ran,
    the verdicts carry per-window ``block_review_window`` metadata. In that case
    this emitter logs ONE ``structure_review`` capture PER WINDOW (grouped by
    ``window_index``) with a window-scoped replayable rationale, instead of the
    single per-doc row. It falls back to the per-doc row below when only
    heading verdicts exist (no window metadata) — the shipped heading path.
    """
    if verdicts is None:
        return  # reviewer did not run — nothing to capture (skip cleanly)
    # Phase 5: windowed full-block-review path — one capture per window.
    try:
        window_groups = _group_block_review_windows(verdicts)
    except Exception:  # noqa: BLE001 — grouping is best-effort; fall through
        window_groups = []
    if window_groups:
        _emit_block_review_window_captures(
            window_groups,
            canonical_course_code=canonical_course_code,
            pdf_stem=pdf_stem,
        )
        return
    try:
        from lib.decision_capture import DecisionCapture, normalize_course_code

        blocks_reviewed = len(verdicts)
        corrected = sum(
            1
            for v in verdicts
            if isinstance(v, dict)
            and str(v.get("verdict") or "ok") != "ok"
            and not v.get("reverted_for_invariant")
        )
        reverted = sum(
            1
            for v in verdicts
            if isinstance(v, dict) and v.get("reverted_for_invariant")
        )
        model = _semantik_structure_review_model()
        # DART->semantik naming purge (task #19): conversion captures land
        # under the ratified ``semantik`` tool / ``semantik_conversion`` phase
        # (the decision_event schema's ``tool`` enum was widened to include
        # ``semantik``; the legacy ``dart`` member stays for pre-purge capture
        # trees). Course code falls back to the PDF stem via the shared
        # normalizer.
        course_code = (
            (canonical_course_code or "").strip()
            or normalize_course_code(pdf_stem or "unknown")
        )

        capture = DecisionCapture(
            course_code=course_code,
            phase="semantik_conversion",
            tool="semantik",
        )
        # DYNAMIC rationale (>=20 chars) — interpolates the per-doc verdict
        # tallies + the reviewer model so the capture is replayable.
        rationale = (
            f"Stage-5d 70B structure reviewer ({model}) reviewed "
            f"{blocks_reviewed} block(s) on {pdf_stem}: {corrected} structural "
            f"correction(s) applied (kind/level/role), {reverted} verdict(s) "
            f"reverted for the structural-only/verbatim invariant. Text-"
            f"preserving role-only review (no words rewritten)."
        )
        capture.log_decision(
            decision_type="structure_review",
            decision=(
                f"applied={corrected} reverted={reverted} "
                f"reviewed={blocks_reviewed}"
            ),
            rationale=rationale,
            alternatives_considered=[
                {
                    "option": "deterministic-detector-only backstop",
                    "reason_rejected": (
                        "drop_toc_and_frontmatter is the fail-closed floor but "
                        "cannot re-role / re-level / promote a heading the way "
                        "the 70B reviewer does"
                    ),
                },
                {
                    "option": "no structure review (flag off)",
                    "reason_rejected": (
                        "SEMANTIK_STRUCTURE_REVIEW was on; the reviewer ran"
                    ),
                },
            ],
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break conversion
        logger.warning(
            "structure_review DecisionCapture failed (non-fatal) on %s: %s",
            pdf_stem,
            exc,
        )


def _group_block_review_windows(
    verdicts: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Group windowed full-block-review verdicts by their owning window.

    Phase 5: the SemantiK windowed reviewer stamps a shared
    ``block_review_window`` dict (``window_index`` + replayable aggregates) onto
    every verdict produced by the same windowed call. This groups the verdict
    rows by ``window_index`` and returns one ``{"meta": <window dict>,
    "verdicts": [...]}`` entry per window, ordered by window index. Heading-only
    / flag-off verdicts carry NO ``block_review_window`` key and yield an EMPTY
    list, so the caller falls back to the per-doc capture (byte-stable).
    """
    groups: Dict[Any, Dict[str, Any]] = {}
    for v in verdicts or []:
        if not isinstance(v, dict):
            continue
        meta = v.get("block_review_window")
        if not isinstance(meta, dict):
            continue
        wi = meta.get("window_index")
        if wi is None:
            continue
        bucket = groups.setdefault(wi, {"meta": meta, "verdicts": []})
        bucket["verdicts"].append(v)
    return [groups[k] for k in sorted(groups, key=lambda x: (x is None, x))]


def _emit_block_review_window_captures(
    window_groups: List[Dict[str, Any]],
    *,
    canonical_course_code: Optional[str],
    pdf_stem: str,
) -> None:
    """Emit ONE ``structure_review`` DecisionCapture per reviewer WINDOW.

    Phase 5: the per-window successor to the per-doc ``_emit_structure_review_capture``
    body, for the windowed full-block reviewer (``SEMANTIK_BLOCK_REVIEW`` on).
    Best-effort by contract — ANY failure logs a warning and returns, NEVER
    breaking the conversion (mirrors the per-doc emitter). Reuses the canonical
    ``decision_type='structure_review'`` enum member (NO schema/enum edit). The
    per-window rationale is DYNAMIC/replayable: it interpolates the window's
    idx-range, page span, council kinds-in, ops-out tally, resolved model id,
    ``max_tokens``, and the council-confidence distribution — all read off the
    window metadata + the grouped verdict rows (the ops tally is derived here).
    """
    if not window_groups:
        return
    try:
        from lib.decision_capture import DecisionCapture, normalize_course_code

        course_code = (
            (canonical_course_code or "").strip()
            or normalize_course_code(pdf_stem or "unknown")
        )
        capture = DecisionCapture(
            course_code=course_code,
            phase="semantik_conversion",
            tool="semantik",
        )
        for group in window_groups:
            meta = group.get("meta") if isinstance(group, dict) else None
            rows = group.get("verdicts") if isinstance(group, dict) else None
            if not isinstance(meta, dict) or not isinstance(rows, list):
                continue
            wi = meta.get("window_index")
            idx_min = meta.get("idx_min")
            idx_max = meta.get("idx_max")
            page_min = meta.get("page_min")
            page_max = meta.get("page_max")
            model = str(meta.get("model") or "unspecified")
            max_tokens = meta.get("max_tokens")
            kinds = meta.get("council_kinds")
            kinds_str = (
                ", ".join(f"{k}×{n}" for k, n in kinds.items())
                if isinstance(kinds, dict) and kinds
                else "n/a"
            )
            c_min = meta.get("confidence_min")
            c_mean = meta.get("confidence_mean")
            c_max = meta.get("confidence_max")

            reviewed = len(rows)
            corrected = sum(
                1
                for v in rows
                if isinstance(v, dict)
                and str(v.get("verdict") or "ok") != "ok"
                and not v.get("reverted_for_invariant")
                and not v.get("reverted_for_endpoint_failure")
            )
            retyped = sum(
                1
                for v in rows
                if isinstance(v, dict) and v.get("role_after") is not None
            )
            dropped = sum(
                1
                for v in rows
                if isinstance(v, dict) and "drop" in str(v.get("verdict") or "")
            )
            reverted = sum(
                1
                for v in rows
                if isinstance(v, dict) and v.get("reverted_for_invariant")
            )
            endpoint_failures = sum(
                1
                for v in rows
                if isinstance(v, dict) and v.get("reverted_for_endpoint_failure")
            )

            rationale = (
                f"Stage-5d full-block reviewer ({model}) window {wi} "
                f"(blocks {idx_min}-{idx_max}, pages {page_min}-{page_max}, "
                f"max_tokens={max_tokens}, council conf "
                f"min/mean/max {c_min}/{c_mean}/{c_max}) reviewed {reviewed} "
                f"block(s) [council kinds-in: {kinds_str}]: {corrected} "
                f"structural correction(s) applied ({retyped} re-type, "
                f"{dropped} drop), {reverted} reverted for the "
                f"verbatim/partition-immutable invariant, {endpoint_failures} "
                f"kept unreviewed on endpoint failure. Index-keyed op-list, "
                f"text-preserving (no words rewritten)."
            )
            capture.log_decision(
                decision_type="structure_review",
                decision=(
                    f"window={wi} reviewed={reviewed} applied={corrected} "
                    f"retype={retyped} drop={dropped} reverted={reverted}"
                ),
                rationale=rationale,
                alternatives_considered=[
                    {
                        "option": "per-document structure-review capture",
                        "reason_rejected": (
                            "the windowed full-block reviewer dispatches one "
                            "op-list call per window; a per-window capture "
                            "attributes each window's re-type/drop ops to its "
                            "own dispatch for replay"
                        ),
                    },
                    {
                        "option": "deterministic-detector-only backstop",
                        "reason_rejected": (
                            "the always-on front-matter detector cannot re-type "
                            "a mis-classified content block (code_block→prose) "
                            "the way the full-block reviewer does"
                        ),
                    },
                ],
            )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break conversion
        logger.warning(
            "block-review per-window DecisionCapture failed (non-fatal) on %s: %s",
            pdf_stem,
            exc,
        )


def _semantik_resolve_block_resegment(result: Any) -> Optional[List[Dict[str, Any]]]:
    """Pull the doc-level ``block_resegment`` op list off a cascade result,
    from EITHER seam arm (mirrors ``_semantik_resolve_structure_review``).

    Resolution order:
      1. ``result.block_resegment`` — the bridge arm
         (``_SemantikBridgeResult``) surfaces it as a top-level attribute.
      2. ``result.cascade["block_resegment"]`` — the in-process
         ``PipelineV2Result`` carries the audit at the run_full_cascade result
         dict's TOP LEVEL (``cascade.py`` ~L2217), which is the CANONICAL shape
         the real cascade emits (parallel to ``second_pass_verify`` /
         ``ocr_repair``). A conformance-nested runtime is also accepted
         (checked first) for forward-compat, though the cascade never nests it.

    Returns ``None`` when the re-segmenter did NOT run (``SEMANTIK_BLOCK_RESEGMENT``
    off / no audit key) so the caller skips the capture cleanly; ``[]`` when it
    ran and made no edits.
    """
    br = getattr(result, "block_resegment", None)
    if br is not None:
        return list(br) if isinstance(br, (list, tuple)) else None
    cascade = getattr(result, "cascade", None)
    if isinstance(cascade, dict):
        conformance = cascade.get("conformance_audit")
        if isinstance(conformance, dict):
            audit = conformance.get("block_resegment")
            if audit is not None:
                return list(audit) if isinstance(audit, (list, tuple)) else None
        # In-process result-dict TOP-LEVEL arm — where ``cascade.py`` actually
        # emits ``result["block_resegment"]`` (the real PipelineV2Result shape).
        audit = cascade.get("block_resegment")
        if audit is not None:
            return list(audit) if isinstance(audit, (list, tuple)) else None
    return None


def _emit_block_resegment_capture(
    ops: Optional[List[Dict[str, Any]]],
    *,
    canonical_course_code: Optional[str],
    pdf_stem: str,
) -> None:
    """Emit ONE ``block_resegment`` DecisionCapture event per converted doc
    when the ``SEMANTIK_BLOCK_RESEGMENT`` re-segmenter ran.

    Best-effort by contract: ANY failure (DecisionCapture init, write, schema)
    logs a warning and returns — it NEVER breaks the conversion. Skips cleanly
    (no capture) when ``ops is None`` (the re-segmenter was off / flag unset).
    The rationale is DYNAMIC/replayable per the CLAUDE.md contract: it
    interpolates per-op merge/split counts, the Phase-9 regroup /
    fused-title-split counts + folded-region tally + merged-unit semantic
    classes, total regions touched, a bounded sample of touched block
    source_ids, and conservation_verified so a post-hoc replay can attribute
    the block re-segmentation.

    ``decision_type='block_resegment'`` is a canonical enum member
    (``schemas/events/decision_event.schema.json``), added for this seam.
    """
    if ops is None:
        return  # re-segmenter did not run — nothing to capture (skip cleanly)
    try:
        from lib.decision_capture import DecisionCapture, normalize_course_code

        total_ops = len(ops)
        merges = sum(
            1
            for o in ops
            if isinstance(o, dict) and str(o.get("op") or "") == "merge"
        )
        splits = sum(
            1
            for o in ops
            if isinstance(o, dict) and str(o.get("op") or "") == "split"
        )
        # Count the distinct regions/blocks each op touched (merge folds N
        # regions; split fans one region into N) for the audit signal.
        regions_touched = 0
        for o in ops:
            if not isinstance(o, dict):
                continue
            for key in ("region_indices", "block_indices", "regions", "blocks"):
                val = o.get(key)
                if isinstance(val, (list, tuple)):
                    regions_touched += len(val)
                    break
            else:
                regions_touched += 1
        # conservation_verified: the cascade may stamp it per-op or doc-level;
        # the audit is "verified" iff every op that carries the flag is True.
        flagged = [
            bool(o.get("conservation_verified"))
            for o in ops
            if isinstance(o, dict) and "conservation_verified" in o
        ]
        conservation_verified = all(flagged) if flagged else None
        # Phase-9 cross-kind pedagogical-unit REGROUP + fused-title SPLIT signals
        # (build_resegment_audit_rows enriches those rows with op='regroup' +
        # semantic_class + regions_folded, and subtype='fused_title'). Interpolate
        # them so a SEMANTIK_UNIT_REGROUP-only doc surfaces its regroup counts /
        # classes / folded-region tally instead of "0 merge(s) / 0 split(s)".
        from collections import Counter  # noqa: PLC0415 — local, best-effort seam

        regroups = sum(
            1
            for o in ops
            if isinstance(o, dict) and str(o.get("op") or "") == "regroup"
        )
        fused_title_splits = sum(
            1
            for o in ops
            if isinstance(o, dict)
            and str(o.get("subtype") or "") == "fused_title"
        )
        regions_folded = sum(
            int(o.get("regions_folded") or 0)
            for o in ops
            if isinstance(o, dict) and isinstance(o.get("regions_folded"), int)
        )
        # ITEM3 MOVE arm: additive move / shadow-move tallies + reason set + a
        # bounded (src -> dest) source_id sample. Built CONDITIONALLY (the
        # ``move_segment`` is "" when no move op rode this doc), so a doc with NO
        # move op produces a BYTE-IDENTICAL rationale (mirrors the regroup-only
        # enrichment posture). A shadow-mode move row carries mode="shadow" /
        # applied=false; a live-applied move row carries applied=true.
        move_rows = [
            o
            for o in ops
            if isinstance(o, dict) and str(o.get("op") or "") == "move"
        ]
        moves_applied = sum(1 for o in move_rows if o.get("applied") is True)
        moves_shadow = sum(
            1 for o in move_rows if str(o.get("mode") or "") == "shadow"
        )
        move_reasons = sorted(
            {
                str(o.get("reason"))
                for o in move_rows
                if o.get("reason")
            }
        )
        move_pairs: List[str] = []
        for o in move_rows:
            sids = o.get("source_ids")
            src = sids[0] if isinstance(sids, (list, tuple)) and sids else None
            dest = o.get("dest_source_id")
            move_pairs.append(f"{src}->{dest}")
            if len(move_pairs) >= 8:
                break
        move_segment = ""
        if move_rows:
            move_segment = (
                f" MOVE: {moves_applied} applied / {moves_shadow} shadow "
                f"move(s), reasons=[{', '.join(move_reasons) or 'none'}], "
                f"src->dest={move_pairs}."
            )
        class_counter = Counter(
            str(o.get("semantic_class"))
            for o in ops
            if isinstance(o, dict) and o.get("semantic_class")
        )
        semantic_class_summary = ", ".join(
            f"{cls} x{n}" for cls, n in sorted(class_counter.items())
        )
        # Bounded sample of the stable block ids each op touched (the audit rows
        # carry source_ids/origin, not page numbers, so block ids are the correct
        # per-doc replay signal). Capped so the rationale stays terse.
        sample_ids: List[Any] = []
        for o in ops:
            if not isinstance(o, dict):
                continue
            sids = o.get("source_ids")
            if isinstance(sids, (list, tuple)):
                sample_ids.extend(sids)
            if len(sample_ids) >= 8:
                break
        sample_ids = sample_ids[:8]
        # DART->semantik naming purge (task #19): conversion captures land
        # under the ratified ``semantik`` tool / ``semantik_conversion`` phase.
        # Course code falls back to the PDF stem via the shared normalizer.
        course_code = (
            (canonical_course_code or "").strip()
            or normalize_course_code(pdf_stem or "unknown")
        )

        capture = DecisionCapture(
            course_code=course_code,
            phase="semantik_conversion",
            tool="semantik",
        )
        # DYNAMIC rationale (>=20 chars) — interpolates the per-doc op tallies
        # so the capture is replayable.
        rationale = (
            f"SEMANTIK_BLOCK_RESEGMENT applied {total_ops} block re-segmentation "
            f"op(s) on {pdf_stem}: {merges} merge(s) / {splits} split(s) / "
            f"{regroups} regroup(s) ({fused_title_splits} fused-title split(s), "
            f"{regions_folded} region(s) folded) touching {regions_touched} "
            f"region(s); classes=[{semantic_class_summary or 'none'}]; "
            f"source_ids={sample_ids}; conservation_verified="
            f"{conservation_verified}. Structure-only block boundary edits "
            f"(no text rewritten).{move_segment}"
        )
        capture.log_decision(
            decision_type="block_resegment",
            decision=(
                f"ops={total_ops} merges={merges} splits={splits} "
                f"regroups={regroups} regions_touched={regions_touched}"
            ),
            rationale=rationale,
            alternatives_considered=[
                {
                    "option": "no block re-segmentation (flag off)",
                    "reason_rejected": (
                        "SEMANTIK_BLOCK_RESEGMENT was on; the re-segmenter ran"
                    ),
                },
            ],
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break conversion
        logger.warning(
            "block_resegment DecisionCapture failed (non-fatal) on %s: %s",
            pdf_stem,
            exc,
        )


# Mirror of ``SemantiK ... reviewer._SECOND_PASS_VERIFY_MAX_TOKENS`` (2048) —
# the Pass-2 verifier's per-call token budget. Surfaced here only for the
# replay rationale (the heavy SemantiK runtime is absent from this venv), never
# to drive a call; identical posture to ``_semantik_structure_review_model``.
_SEMANTIK_SECOND_PASS_VERIFY_MAX_TOKENS = 2048
# Mirror of ``ocr_repair._OCR_REPAIR_MAX_TOKENS`` (the proposer's output budget)
# for the DecisionCapture rationale — kept as a local constant so the seam never
# imports the SemantiK cascade package just to name it.
_SEMANTIK_OCR_REPAIR_MAX_TOKENS = 1024


def _semantik_resolve_second_pass_verify(result: Any) -> Optional[Dict[str, Any]]:
    """Pull the Stage-9 Pass-2 verify-refine audit arm off a cascade result,
    from EITHER seam arm (Phase 6/7); mirrors ``_semantik_resolve_block_resegment``
    except the arm is a DICT (``{"adopted": ..., "rounds": [...]}``), not a list.

    Resolution order:
      1. ``result.second_pass_verify`` — the bridge arm
         (``_SemantikBridgeResult``) surfaces it as a top-level attribute.
      2. ``result.cascade["conformance_audit"]["second_pass_verify"]`` — the
         in-process telemetry-nested arm (parallel to ``structure_review`` /
         ``block_resegment``).
      3. ``result.cascade["second_pass_verify"]`` — the in-process
         result-dict top-level arm (``cascade.py`` emits the key here at
         ``result["second_pass_verify"]``), read defensively so the resolver
         works regardless of which nesting the runtime chose.

    Returns ``None`` when the verify-refine loop did NOT run (flag off / no
    audit key) so the caller skips the captures cleanly.
    """
    spv = getattr(result, "second_pass_verify", None)
    if spv is not None:
        return spv if isinstance(spv, dict) else None
    cascade = getattr(result, "cascade", None)
    if isinstance(cascade, dict):
        conformance = cascade.get("conformance_audit")
        if isinstance(conformance, dict):
            arm = conformance.get("second_pass_verify")
            if isinstance(arm, dict):
                return arm
        arm = cascade.get("second_pass_verify")
        if isinstance(arm, dict):
            return arm
    return None


def _emit_second_pass_verify_captures(
    signals: Optional[Dict[str, Any]],
    *,
    canonical_course_code: Optional[str],
    pdf_stem: str,
) -> None:
    """Emit ONE ``structure_review`` DecisionCapture per Pass-2 VERIFY ROUND
    when the Stage-9 verify-refine loop ran (Phase 7).

    Reuses the canonical ``decision_type='structure_review'`` enum member (NO
    schema/enum edit, byte-stable under ``DECISION_VALIDATION_STRICT``) but
    carries a STRUCTURED round discriminator in the capture METADATA — a
    ``second_pass_verify=True`` marker + a ``round_index`` field — so
    ``analyze_training_data`` can separate Pass-1 windowed reviewer captures
    (no such marker) from Pass-2 verify rows on a FIELD, not the free text.

    Best-effort by contract: ANY failure (DecisionCapture init, write, schema)
    logs a warning and returns — it NEVER breaks the conversion. Skips cleanly
    (no captures) when ``signals is None`` (the loop was off / flag unset) or
    when no round ran. The per-round rationale is DYNAMIC/replayable per the
    CLAUDE.md contract: it interpolates the round index, blocks-flagged, the
    fixable re-reviewed set, the failure-mode distribution incl. the
    DETECTED-NOT-FIXED deferred backlog (``section_no_body`` /
    ``example_misordered_from_body`` / merge-arm modes the index-keyed reviewer
    cannot fix), converged-bool, adopted-vs-reverted (incl. ``merge_adopted``),
    the resolved model id, and ``max_tokens``.
    """
    if signals is None:
        return  # verify-refine loop did not run — skip cleanly
    rounds = signals.get("rounds") if isinstance(signals, dict) else None
    if not isinstance(rounds, list) or not rounds:
        return  # no round executed — nothing to capture
    try:
        from lib.decision_capture import DecisionCapture, normalize_course_code

        course_code = (
            (canonical_course_code or "").strip()
            or normalize_course_code(pdf_stem or "unknown")
        )
        model = _semantik_structure_review_model()
        max_tokens = _SEMANTIK_SECOND_PASS_VERIFY_MAX_TOKENS
        doc_adopted = bool(signals.get("adopted"))
        doc_merge_adopted = bool(signals.get("merge_adopted"))

        capture = DecisionCapture(
            course_code=course_code,
            phase="semantik_conversion",
            tool="semantik",
        )
        for row in rounds:
            if not isinstance(row, dict):
                continue
            round_index = row.get("round")
            passed = row.get("passed")
            flagged = int(row.get("flagged") or 0)
            fixable_indices = list(row.get("fixable_indices") or [])
            deferred_modes = list(row.get("deferred_modes") or [])
            restrict_to = list(row.get("restrict_to") or [])
            reverify_passed = row.get("reverify_passed")
            better = row.get("better")
            adopted = bool(row.get("adopted"))
            merge_adopted = bool(row.get("merge_adopted"))
            error = row.get("error")
            n_fixable = len(fixable_indices) or len(restrict_to)

            # converged/verdict state for the rationale (verifier verdict on the
            # CURRENT assembled doc at the top of the round).
            if error is not None:
                verdict_word = f"errored ({error})"
            elif passed is True:
                verdict_word = "passed (converged)"
            elif passed is False:
                verdict_word = "failed"
            else:
                verdict_word = "unknown"

            deferred_str = ", ".join(str(m) for m in deferred_modes) or "none"
            disposition = (
                "adopted via merge"
                if merge_adopted
                else "adopted"
                if adopted
                else "reverted/kept-pass1"
            )

            rationale = (
                f"Stage-9 Pass-2 verify-refine ({model}, max_tokens={max_tokens}) "
                f"round {round_index} on {pdf_stem}: verifier {verdict_word}; "
                f"{flagged} region(s) flagged, {n_fixable} re-reviewed "
                f"(fixable indices {fixable_indices or restrict_to}); "
                f"{len(deferred_modes)} detected-not-fixed backlog mode(s) "
                f"[{deferred_str}]; re-verify_passed={reverify_passed} "
                f"better={better}; round {disposition}. Index-keyed verify pass "
                f"(no words rewritten)."
            )
            capture.log_decision(
                decision_type="structure_review",
                decision=(
                    f"second_pass_verify round={round_index} "
                    f"flagged={flagged} fixable={n_fixable} "
                    f"deferred={len(deferred_modes)} adopted={adopted} "
                    f"merge_adopted={merge_adopted}"
                ),
                rationale=rationale,
                alternatives_considered=[
                    {
                        "option": "single forward pass (no Pass-2 verifier)",
                        "reason_rejected": (
                            "the pre-assembly per-block reviewer cannot see "
                            "post-assembly defects (mis-ordered worked examples, "
                            "no-context answer-fragment headings); the verifier "
                            "judges the ASSEMBLED doc and bounces flagged regions"
                        ),
                    },
                    {
                        "option": "re-drive the detected-not-fixed deferred modes",
                        "reason_rejected": (
                            "section_no_body / example_misordered_from_body / the "
                            "merge-arm need a regroup/reorder op the index-keyed "
                            "reviewer lacks; recorded as a ground-truth backlog "
                            "instead of burning a round on the identical op"
                        ),
                    },
                ],
                # STRUCTURED round discriminator (lands in record metadata; the
                # schema's metadata.additionalProperties is open) so downstream
                # analysis separates Pass-2 verify rows from Pass-1 windows on a
                # FIELD, not the free-text decision string.
                second_pass_verify=True,
                round_index=round_index,
                round_passed=passed,
                round_flagged=flagged,
                round_fixable=n_fixable,
                round_deferred_modes=deferred_modes,
                round_adopted=adopted,
                round_merge_adopted=merge_adopted,
                doc_adopted=doc_adopted,
                doc_merge_adopted=doc_merge_adopted,
            )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break conversion
        logger.warning(
            "second_pass_verify DecisionCapture failed (non-fatal) on %s: %s",
            pdf_stem,
            exc,
        )


def _semantik_resolve_ocr_repair(result: Any) -> Optional[Dict[str, Any]]:
    """Pull the SEMANTIK_OCR_CONFUSABLE_REPAIR audit stats off a cascade result,
    from EITHER seam arm (mirrors ``_semantik_resolve_second_pass_verify``).

    Resolution order: ``result.ocr_repair`` (the bridge arm) →
    ``result.cascade["conformance_audit"]["ocr_repair"]`` (in-process nested) →
    ``result.cascade["ocr_repair"]`` (in-process top-level). Returns ``None``
    when the pass did NOT run (flag off / no audit key) so the caller skips.
    """
    ocr = getattr(result, "ocr_repair", None)
    if ocr is not None:
        return ocr if isinstance(ocr, dict) else None
    cascade = getattr(result, "cascade", None)
    if isinstance(cascade, dict):
        conformance = cascade.get("conformance_audit")
        if isinstance(conformance, dict):
            arm = conformance.get("ocr_repair")
            if isinstance(arm, dict):
                return arm
        arm = cascade.get("ocr_repair")
        if isinstance(arm, dict):
            return arm
    return None


def _emit_ocr_repair_capture(
    stats: Optional[Dict[str, Any]],
    *,
    canonical_course_code: Optional[str],
    pdf_stem: str,
) -> None:
    """Emit ONE ``structure_review`` DecisionCapture for the OCR-confusable
    micro-repair pass when it ran (plan Phase 5 channels 2+3).

    Rides the canonical ``decision_type='structure_review'`` enum member (NO
    schema/enum edit — mirrors ``_emit_second_pass_verify_captures``) but carries
    an ``ocr_confusable_repair=True`` metadata discriminator so downstream
    analysis separates repair rows on a FIELD, not the free text. The rationale
    is DYNAMIC/replayable: it interpolates flagged/accepted/rejected counts, the
    top rule_ids, the residual defect density + proxy score, the resolved model,
    and ``max_tokens``. Best-effort by contract — ANY failure logs a warning and
    returns, NEVER breaking the conversion. Skips cleanly on ``stats is None``.
    """
    if not isinstance(stats, dict):
        return
    try:
        from lib.decision_capture import DecisionCapture, normalize_course_code

        course_code = (
            (canonical_course_code or "").strip()
            or normalize_course_code(pdf_stem or "unknown")
        )
        model = _semantik_structure_review_model()
        flagged = int(stats.get("flagged_blocks") or 0)
        proposals = int(stats.get("proposals") or 0)
        accepted = int(stats.get("accepted") or 0)
        rejected_rows = stats.get("rejected") or []
        rejected = len(rejected_rows) if isinstance(rejected_rows, list) else 0
        density = stats.get("unrepairable_defect_density")
        score = stats.get("repair_stats_score")
        windows = int(stats.get("windows_dispatched") or 0)
        windows_failed = int(stats.get("windows_failed") or 0)

        # Top rule_ids across the accepted edits are not on the stats dict (they
        # live in region_provenance); the rejected-reason distribution is the
        # replayable signal we DO have here, so surface it.
        reason_counts: Dict[str, int] = {}
        if isinstance(rejected_rows, list):
            for row in rejected_rows:
                if isinstance(row, dict):
                    r = str(row.get("reason") or "unknown")
                    reason_counts[r] = reason_counts.get(r, 0) + 1
        reason_str = (
            ", ".join(f"{k}×{v}" for k, v in sorted(reason_counts.items()))
            or "none"
        )

        capture = DecisionCapture(
            course_code=course_code,
            phase="semantik_conversion",
            tool="semantik",
        )
        rationale = (
            f"OCR-confusable micro-repair ({model}, max_tokens="
            f"{_SEMANTIK_OCR_REPAIR_MAX_TOKENS}) on {pdf_stem}: {flagged} region(s) "
            f"flagged, {windows} window(s) dispatched ({windows_failed} failed), "
            f"{proposals} proposal(s) → {accepted} accepted / {rejected} rejected "
            f"[reject reasons: {reason_str}]; residual defect density "
            f"{density}, repair-stats proxy score {score}. Deterministic accept "
            f"gate (confusable map, edit-distance ≤ 2, char-class safe, never in "
            f"a number); LLM proposes, auditable code decides. No words rewritten."
        )
        capture.log_decision(
            decision_type="structure_review",
            decision=(
                f"ocr_confusable_repair flagged={flagged} proposals={proposals} "
                f"accepted={accepted} rejected={rejected} score={score}"
            ),
            rationale=rationale,
            alternatives_considered=[
                {
                    "option": "let the 7B rewrite the flagged text directly",
                    "reason_rejected": (
                        "the reviewer-redesign directive makes LLM editors "
                        "structural-only; an unconstrained fixer reopens the "
                        "anti-fabrication hole. The gate accepts only known "
                        "confusable-map micro-edits, annotated data-dart-repair"
                    ),
                },
            ],
            # STRUCTURED discriminator (open metadata) so analysis separates
            # repair rows from Pass-1/Pass-2 reviewer rows on a FIELD.
            ocr_confusable_repair=True,
            ocr_flagged=flagged,
            ocr_proposals=proposals,
            ocr_accepted=accepted,
            ocr_rejected=rejected,
            ocr_defect_density=density,
            ocr_repair_stats_score=score,
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break conversion
        logger.warning(
            "ocr_confusable_repair DecisionCapture failed (non-fatal) on %s: %s",
            pdf_stem,
            exc,
        )


