_ED4ALL_CROSS_WEEK_RETRIEVAL_ENV = "ED4ALL_PLANNER_CROSS_WEEK_RETRIEVAL"
_ED4ALL_CROSS_WEEK_RETRIEVAL_TRUTHY = frozenset({"1", "true", "yes", "on"})


