_ED4ALL_KEY_TERMS_PAGE_ENV = "ED4ALL_KEY_TERMS_PAGE"
_ED4ALL_KEY_TERMS_PAGE_TRUTHY = frozenset({"1", "true", "yes", "on"})
# Mirror of ``lib.generation.key_terms.KEY_TERMS_TEMPLATE_TYPE`` — the
