# Page-per-CO content-emit gate. Default OFF → byte-identical: the content-page
# count stays ``max(topic_count, 1)`` per week (O(sections)). When truthy AND
# COURSEFORGE_TWO_PASS is on, the content-page count is driven by the week's CO
# count (the bounded axis), each CO gets one content page, and that page's
# grounding is token-bounded to fit the authoring window. Resolvers + the token
# budget + the top-K cap live in ``lib.generation.content_page_budget``; this
# wrapper additionally no-ops the feature unless the two-pass surface is on.
def _content_page_per_co_enabled() -> bool:
    """``ED4ALL_CONTENT_PAGE_PER_CO`` AND ``COURSEFORGE_TWO_PASS`` both on.

    Read each call (tests toggle inline). Default OFF / parse-with-fallback.
    The feature only applies on the two-pass outline surface, so the master
    flag is gated behind ``_courseforge_two_pass_enabled()``.
    """
    from lib.generation.content_page_budget import (  # noqa: PLC0415
        content_page_per_co_enabled,
    )

    return content_page_per_co_enabled() and _courseforge_two_pass_enabled()


def _build_block_planner_provider(capture=None):
    """Construct the 70B provider seam for the dynamic block planner.

    Reuses the SAME NVIDIA OpenAI-compatible client plumbing as the rewrite
    tier + objective review (``Courseforge/generators/_base.py`` →
    ``_BaseLLMProvider`` ``nvidia`` branch, key from ``NVIDIA_API_KEY``),
    but with a planning-only system prompt
    (``lib.generation.block_planner.build_planner_provider``). Returns an
    object exposing ``plan_blocks(prompt) -> str`` (the surface
    ``plan_week_blocks`` consumes), or ``None`` on any construction error /
    missing key so the planner falls back to the fixed plan rather than
    breaking the build.
    """
    try:
        from lib.generation.block_planner import build_planner_provider

        # IB7.2 — the planner SEAT is operator-selectable so the
        # framework-aligned path is reachable without the hosted-seat key. The
        # default stays "nvidia" (byte-stable); ED4ALL_DYNAMIC_BLOCK_PLAN_PROVIDER
        # can pick the license-clean local Qwen seat (LOCAL_SYNTHESIS_*).
        seat = (
            os.environ.get("ED4ALL_DYNAMIC_BLOCK_PLAN_PROVIDER", "nvidia").strip()
            or "nvidia"
        )
        return build_planner_provider(provider=seat, capture=capture)
    except Exception as exc:  # noqa: BLE001 — fail-safe to fixed plan
        logger.warning(
            "dynamic block planner: provider construction failed "
            "(%s); the week planner will fall back to the fixed plan.",
            exc,
        )
        return None


# ---------------------------------------------------------------------------
# Phase 3.5 Subtask 13: post_rewrite_validation phase helper
# ---------------------------------------------------------------------------


async def _run_post_rewrite_validation(**kwargs) -> str:
    """Run the four shape-discriminating Block-input validators against
    rewrite-tier blocks loaded from ``blocks_final_path``.

    Phase 3.5 Subtask 13. Mirrors the shape-discriminator wiring that
    ``inter_tier_validation`` does on outline-tier blocks, but consumes
    the rewrite-tier ``blocks_final_path`` (which the rewrite tier emits
    after producing the final HTML body) so a rewrite-tier emit that
    drops a CURIE / content_type / objective_ref / source_id silently
    is caught before packaging consumes it.

    Inputs (kwargs):
        blocks_final_path: Path to the rewrite-tier blocks JSONL/JSON
            sidecar. Each entry is a dict carrying at minimum
            ``{block_id, block_type, page_id, sequence, content,
            objective_ids, source_ids, ...}``. Entries are deserialised
            via :class:`Courseforge.scripts.blocks.Block` field
            assignment; unknown / extra fields are tolerated by dropping
            them (mirrors the to_jsonld_entry() emit shape).
        project_id: Course project slug (used to locate the
            decision-capture sidecar + the synthesized_objectives.json
            that BlockPageObjectivesValidator consumes).

    Outputs (JSON envelope):
        blocks_validated_path: Path to a JSONL file carrying the
            rewrite-tier blocks that passed every gate (subset of input).
        blocks_failed_path: Path to a JSONL file carrying the
            rewrite-tier blocks that tripped at least one gate.
        gate_results: List of per-gate ``GateResult.to_dict()`` payloads
            so a downstream consumer (or operator) can introspect the
            failure distribution without re-running the validators.

    Decision-capture: emits one ``block_validation_action`` decision
    per failed validator with ``ml_features.tier="rewrite"`` so a
    postmortem reader can stratify outline-tier failures (which trigger
    regen / escalate / block in route_with_self_consistency) from
    rewrite-tier failures (which surface here, post-emit).

    Wave B scope: this helper is the standalone callable. The
    ``_PHASE_TOOL_MAPPING`` wiring that lets the executor dispatch
    on phase-name lands in Wave C; until that wave the helper is
    invoked directly by integration tests / operators.
    """
    from pathlib import Path as _Path

    blocks_final_path_raw = kwargs.get("blocks_final_path") or ""
    project_id = kwargs.get("project_id") or ""

    if not blocks_final_path_raw:
        return json.dumps({
            "success": False,
            "error": "blocks_final_path is required",
        })

    blocks_path = _Path(blocks_final_path_raw)
    if not blocks_path.exists():
        return json.dumps({
            "success": False,
            "error": f"blocks_final_path does not exist: {blocks_path}",
        })

    # Lazy-import the Block dataclass + validators so this helper can
    # land without forcing every callsite to import the router surface.
    from Courseforge.scripts.blocks import Block, Touch  # type: ignore[import-not-found]
    from Courseforge.router.inter_tier_gates import (
        BlockContentTypeValidator,
        BlockCurieAnchoringValidator,
        BlockPageObjectivesValidator,
        BlockSourceRefValidator,
    )

    # Deserialise blocks. Accept JSONL (one block per line) and JSON
    # (top-level list, or top-level object with a ``blocks`` key).
    raw_text = blocks_path.read_text(encoding="utf-8")
    raw_entries: list = []
    try:
        if blocks_path.suffix == ".jsonl":
            for line in raw_text.splitlines():
                line = line.strip()
                if not line:
                    continue
                raw_entries.append(json.loads(line))
        else:
            parsed = json.loads(raw_text)
            if isinstance(parsed, list):
                raw_entries = parsed
            elif isinstance(parsed, dict):
                raw_entries = parsed.get("blocks", []) or []
    except json.JSONDecodeError as exc:
        return json.dumps({
            "success": False,
            "error": f"failed to parse {blocks_path}: {exc}",
        })

    # M3 fix: instrument the silent-drop sites the docstring above flags.
    # When a JSON entry's CURIE / content_type_label / objective_ref /
    # source_id values are malformed, we previously dropped them silently
    # via list / tuple coercion. The post_rewrite_validation phase now
    # records each drop in ``metadata_drops`` and emits a
    # ``metadata_field_drop`` decision event so an operator sees the
    # silent-degradation class without re-running the rewrite tier.
    metadata_drops: List[Dict[str, Any]] = []
    _capture_meta = None
    try:
        from lib.decision_capture import DecisionCapture as _DC_meta
        _capture_meta = _DC_meta(
            course_code=project_id or "post_rewrite_validation",
            phase="post_rewrite_validation",
            tool="courseforge",
            streaming=True,
        )
    except Exception as exc:  # noqa: BLE001 — best-effort
        logger.warning(
            "post_rewrite_validation: DecisionCapture init for "
            "metadata_field_drop failed (%s); drops will be tracked "
            "but not persisted.",
            exc,
        )
        _capture_meta = None

    _CURIE_RE = __import__("re").compile(r"^[A-Za-z][A-Za-z0-9_-]*:[A-Za-z0-9_./#:-]+$")
    _LO_REF_RE = __import__("re").compile(r"^[A-Za-z]{2,}-\d{2,}$")
    # Canonical content-type enum — sourced from the single canonical taxonomy
    # (``schemas/taxonomies/content_type.json`` $defs.ChunkType) via
    # ``lib/validators/content_type.py::get_valid_chunk_types``, the SAME source
    # ``Courseforge/generators/_outline_provider.py`` and
    # ``Courseforge/router/inter_tier_gates.py::BlockContentTypeValidator`` use.
    # A stale hardcoded set here silently DROPPED ``content_type_label`` on any
    # block carrying a modern taxonomy value (e.g. ``explanation`` / ``key_idea``),
    # malforming the block and cascading across every post_rewrite gate.
    from lib.validators.content_type import (
        get_valid_chunk_types as _get_valid_chunk_types,
    )
    _CONTENT_TYPE_ENUM = set(_get_valid_chunk_types())

    def _record_metadata_drop(
        field_name: str, reason: str, **fields: Any,
    ) -> None:
        """Append a structured drop record + emit a decision event."""
        rec = {"field_name": field_name, "reason": reason, **fields}
        metadata_drops.append(rec)
        if _capture_meta is None:
            return
        try:
            _capture_meta.log_decision(
                decision_type="metadata_field_drop",
                decision=f"dropped {field_name} reason={reason}",
                rationale=(
                    f"post_rewrite_validation _entry_to_block dropped a "
                    f"malformed {field_name} on a rewrite-tier block. "
                    f"reason={reason}; context={fields!r}. Surfaced via "
                    f"metadata_drops_count in phase output so operators "
                    f"see the silent-degradation class instead of the "
                    f"downstream gate firing on the stripped block."
                ),
                ml_features={
                    "field_name": field_name,
                    "reason": reason,
                    **{
                        k: v for k, v in fields.items()
                        if isinstance(v, (str, int, float, bool))
                    },
                },
            )
        except Exception as exc:  # noqa: BLE001 — best-effort
            logger.warning(
                "post_rewrite_validation: log_decision("
                "metadata_field_drop) failed (%s); drop still recorded.",
                exc,
            )

    def _entry_to_block(entry: dict) -> Optional["Block"]:  # type: ignore[name-defined]
        """Project a JSON entry onto a frozen Block, dropping unknown keys.

        The blocks_final_path emit shape is the canonical
        :func:`Block.to_jsonld_entry` output PLUS the structural
        fields the rewrite tier persists for re-execution. We only
        consume the fields :class:`Block` accepts; everything else
        is dropped.
        """
        accepted = {
            "block_id", "block_type", "page_id", "sequence", "content",
            "template_type", "key_terms", "objective_ids",
            "bloom_level", "bloom_verb", "bloom_range",
            "bloom_levels", "bloom_verbs", "cognitive_domain",
            "teaching_role", "content_type_label", "purpose",
            "component", "source_ids", "source_primary",
            "source_references", "content_hash",
            "validation_attempts", "escalation_marker",
            "anchored_rubric",
            "interaction_type", "fade_state",
        }
        block_id_for_log = (entry or {}).get("block_id") or "<unknown>"
        kwargs_clean: dict = {}
        for k, v in (entry or {}).items():
            if k not in accepted:
                continue
            # M3: validate + filter the four silent-drop classes the
            # docstring at line ~2091 flags.
            if k == "objective_ids":
                if isinstance(v, list):
                    cleaned: List[str] = []
                    for ref in v:
                        if isinstance(ref, str) and _LO_REF_RE.match(ref):
                            cleaned.append(ref)
                        else:
                            _record_metadata_drop(
                                "objective_ref",
                                "malformed_lo_ref",
                                block_id=str(block_id_for_log),
                                value=str(ref)[:64],
                            )
                    v = tuple(cleaned)
            elif k == "source_ids":
                if isinstance(v, list):
                    cleaned_src: List[str] = []
                    for sid in v:
                        if isinstance(sid, str) and sid.strip():
                            cleaned_src.append(sid)
                        else:
                            _record_metadata_drop(
                                "source_id",
                                "empty_or_non_string",
                                block_id=str(block_id_for_log),
                                value=str(sid)[:64],
                            )
                    v = tuple(cleaned_src)
            elif k == "content_type_label":
                if v is not None and (
                    not isinstance(v, str) or v not in _CONTENT_TYPE_ENUM
                ):
                    _record_metadata_drop(
                        "content_type",
                        "out_of_enum",
                        block_id=str(block_id_for_log),
                        value=str(v)[:64],
                    )
                    continue  # drop the field; Block ctor accepts None
            elif k == "key_terms":
                if isinstance(v, list):
                    cleaned_kt: List[str] = []
                    for term in v:
                        if isinstance(term, str) and ":" in term and not _CURIE_RE.match(term):
                            # Looks-like-CURIE that fails CURIE shape.
                            _record_metadata_drop(
                                "curie",
                                "malformed_curie",
                                block_id=str(block_id_for_log),
                                value=str(term)[:64],
                            )
                            continue
                        cleaned_kt.append(term)
                    v = tuple(cleaned_kt)
            # Tuple-typed fields take tuple input; lists from JSON are
            # acceptable to dataclasses.replace via Block.__init__ but
            # the frozen dataclass coerces nothing — pass tuples.
            if k in {
                "bloom_levels", "bloom_verbs", "source_references",
            }:
                if isinstance(v, list):
                    v = tuple(v) if k != "source_references" else tuple(
                        dict(r) if isinstance(r, dict) else r for r in v
                    )
            kwargs_clean[k] = v
        # Required fields with sensible defaults when absent.
        if "block_id" not in kwargs_clean or "block_type" not in kwargs_clean:
            return None
        kwargs_clean.setdefault("page_id", kwargs_clean.get("block_id", ""))
        kwargs_clean.setdefault("sequence", 0)
        kwargs_clean.setdefault("content", "")
        _touches = _touches_from_entry(entry or {})
        if _touches:
            kwargs_clean["touched_by"] = _touches
        try:
            return Block(**kwargs_clean)
        except (TypeError, ValueError) as exc:
            logger.warning(
                "post_rewrite_validation: skipping malformed block entry "
                "block_id=%r: %s",
                entry.get("block_id"),
                exc,
            )
            return None

    blocks: list = []
    for entry in raw_entries:
        if not isinstance(entry, dict):
            continue
        blk = _entry_to_block(entry)
        if blk is not None:
            blocks.append(blk)

    if not blocks:
        return json.dumps({
            "success": False,
            "error": (
                f"no blocks parseable from {blocks_path}; expected JSON-LD "
                f"shape with at least one Block-shaped entry"
            ),
        })

    # Resolve the canonical objectives JSON for BlockPageObjectivesValidator.
    objectives_path: Optional[_Path] = None
    if project_id:
        candidate = (
            courseforge_exports_dir()
            / project_id
            / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        if candidate.exists():
            objectives_path = candidate

    # Instantiate the validators + run each one. We pass tier="rewrite"
    # to the decision capture (Subtask 26's ml_features.tier field) so
    # postmortem readers can stratify outline-tier vs rewrite-tier
    # failures.
    # CB5a: stub-example safety-net gate. Pure HTML/text (no embeddings);
    # fires action="regenerate" on an example block carrying only a
    # problem statement with no worked solution.
    from lib.validators.example_completeness import (  # type: ignore[import-not-found]
        ExampleCompletenessValidator,
    )

    validators = [
        ("rewrite_curie_anchoring", BlockCurieAnchoringValidator()),
        ("rewrite_content_type", BlockContentTypeValidator()),
        ("rewrite_page_objectives", BlockPageObjectivesValidator()),
        ("rewrite_source_refs", BlockSourceRefValidator()),
        ("example_completeness", ExampleCompletenessValidator()),
    ]

    inputs: dict = {"blocks": blocks}
    if objectives_path is not None:
        inputs["objectives_path"] = str(objectives_path)

    # v0.3.0 dynamic CURIE minting: thread the minted-CURIE map into the
    # rewrite-tier gate inputs too so surface-form anchoring is available
    # at the post-rewrite seam. No-op for RDF / legacy corpora.
    minted_curie_map = _resolve_minted_curie_map_for_validation(
        project_id=project_id, kwargs=kwargs,
    )
    if minted_curie_map:
        inputs["minted_curie_map"] = minted_curie_map

    # Objective-refs-concept anchoring: thread the {objective_id: statement}
    # map so a minted CURIE anchors when its concept surface form appears in
    # a declared objective's statement. No-op when objectives_path is
    # absent / unparseable.
    _obj_statements = _load_objective_statements_from_path(objectives_path)
    if _obj_statements:
        inputs["objective_statements"] = _obj_statements

    gate_results: list = []
    failing_gate_ids: set = set()
    for gate_id, validator in validators:
        # Graceful stop (checkpoint on command): non-LLM validator loop, so a
        # stop here just pauses cleanly between validator units (no work to
        # lose). Aggregated ``gate_results`` are re-derivable on resume.
        check_stop("post_rewrite_validation", len(gate_results))
        try:
            result = validator.validate({**inputs, "gate_id": gate_id})
        except Exception as exc:  # pragma: no cover — defensive
            logger.warning(
                "post_rewrite_validation: validator %s raised: %s",
                gate_id, exc,
            )
            continue
        try:
            result_dict = result.to_dict()
        except Exception:  # pragma: no cover — defensive
            result_dict = {
                "gate_id": gate_id,
                "passed": getattr(result, "passed", False),
                "issues": [],
            }
        gate_results.append(result_dict)
        if not result.passed:
            failing_gate_ids.add(gate_id)

    # Decision-capture: emit per-failure ``block_validation_action`` events
    # so postmortem readers see the rewrite-tier failure chain. We
    # reuse the project_id-derived course code for the capture sidecar
    # and surface ``ml_features.tier="rewrite"`` per Subtask 26.
    if failing_gate_ids:
        try:
            from lib.decision_capture import DecisionCapture
            capture = DecisionCapture(
                course_code=project_id or "post_rewrite_validation",
                phase="post_rewrite_validation",
                tool="courseforge",
                streaming=True,
            )
            for result_dict in gate_results:
                if result_dict.get("passed"):
                    continue
                gate_id = result_dict.get("gate_id", "unknown_gate")
                issues = result_dict.get("issues", []) or []
                top_issues = issues[:3]
                summary = "; ".join(
                    f"{i.get('code','?')}({i.get('severity','?')}):"
                    f"{i.get('message','')}"
                    for i in top_issues
                ) or "no_issues"
                capture.log_decision(
                    decision_type="block_validation_action",
                    decision=(
                        f"post_rewrite_validation:{gate_id}:"
                        f"{result_dict.get('passed')}"
                    ),
                    rationale=(
                        f"Post-rewrite gate {gate_id} returned "
                        f"passed={result_dict.get('passed')} on "
                        f"{len(blocks)} rewrite-tier blocks; "
                        f"top_issues=[{summary}]"
                    ),
                    ml_features={
                        "gate_id": gate_id,
                        "passed": result_dict.get("passed"),
                        "issues_count": len(issues),
                        "block_count": len(blocks),
                        # Subtask 26: tier provenance — rewrite-tier
                        # post-emit validator failure (vs outline-tier
                        # in-loop failures).
                        "tier": "rewrite",
                    },
                )
        except Exception as exc:  # pragma: no cover — defensive
            logger.warning(
                "post_rewrite_validation: decision-capture emit failed: %s",
                exc,
            )

    # Persist blocks_validated_path + blocks_failed_path siblings to
    # blocks_final_path. The validated path carries the input list
    # untouched (validators are read-only); the failed path carries
    # block IDs + the gate they tripped so downstream consumers (and
    # the audit trail) can correlate without re-running the validators.
    out_dir = blocks_path.parent
    validated_path = out_dir / "blocks_validated.jsonl"
    failed_path = out_dir / "blocks_failed.jsonl"

    failed_block_ids: set = set()
    for result_dict in gate_results:
        if result_dict.get("passed"):
            continue
        for issue in result_dict.get("issues", []) or []:
            loc = issue.get("location") if isinstance(issue, dict) else None
            if isinstance(loc, str) and loc:
                failed_block_ids.add(loc)

    # Escalated blocks ride through to validated_path regardless of
    # validator outcome — they are marker-bearing by design (Wave-7
    # escalate_immediately) and the rewrite phase needs to see them to
    # author from scratch. Without this, blocks_validated.jsonl is empty
    # when the corpus is all-objective and the workflow halts.
    with validated_path.open("w", encoding="utf-8") as fh:
        for blk in blocks:
            if blk.block_id in failed_block_ids and blk.escalation_marker is None:
                continue
            fh.write(json.dumps(
                _block_to_snake_case_entry(blk), ensure_ascii=False,
            ))
            fh.write("\n")
    with failed_path.open("w", encoding="utf-8") as fh:
        for blk in blocks:
            if blk.block_id not in failed_block_ids:
                continue
            if blk.escalation_marker is not None:
                continue
            # Stamp a REAL failure_reason (was implicitly null) — the failing
            # gate(s) located at this block + the regen attempts consumed. For
            # a CURIE-preservation miss the gate message carries the dropped
            # tokens; for other gates the code+message head is the failure
            # class. Additive field, never breaks a reader.
            _failed_entry = _block_to_snake_case_entry(blk)
            _failed_entry["failure_reason"] = _compose_block_failure_reason(
                blk, gate_results
            )
            fh.write(json.dumps(_failed_entry, ensure_ascii=False))
            fh.write("\n")

    return json.dumps({
        "success": True,
        "blocks_validated_path": str(validated_path),
        "blocks_failed_path": str(failed_path),
        "gate_results": gate_results,
        "block_count": len(blocks),
        "failed_block_count": len(failed_block_ids),
        # M3 fix: surface silent-drop counts from _entry_to_block. The
        # first 10 records are inlined for postmortem readability; the
        # count is authoritative.
        "metadata_drops_count": len(metadata_drops),
        "metadata_drops": metadata_drops[:10],
    })


# ---------------------------------------------------------------------------
# Phase 3.5 Subtask 28-30: snake_case Block JSONL shape helper
# ---------------------------------------------------------------------------
#
# ``Block.to_jsonld_entry()`` emits the legacy camelCase section /
# objective / misconception shape (``heading`` / ``contentType`` for
# explanation blocks, ``blockId`` / ``blockType`` for minimal-shape
# blocks, etc.) — that's the wire shape Trainforge / Courseforge
# JSON-LD consumers expect, but it's NOT round-trippable through
# ``Block(**fields)`` because the field names are camelCase and the
# block-type-specific dispatch drops dataclass fields the constructor
# would otherwise accept.
#
# The two-pass router phase helpers need a JSONL shape that (a)
# round-trips cleanly through ``Block(**snake_case_kwargs)`` so a
# downstream phase can rehydrate the Block, and (b) carries every
# field the Block dataclass exposes (block_id, block_type, page_id,
# sequence, content, objective_ids, source_ids, ...). The helper
# below projects a Block to that snake_case shape, mirroring the
# accepted-keys set ``_entry_to_block`` uses to reconstruct.


def _compose_block_failure_reason(
    block: Any, gate_results: List[Dict[str, Any]]
) -> Optional[str]:
    """Compose a real ``failure_reason`` for a ``blocks_failed.jsonl`` row.

    The rewrite/inter-tier ``blocks_failed.jsonl`` rows previously carried the
    bare Block projection with NO failure attribution (an implicit ``null``
    reason), so a postmortem couldn't tell WHY a block landed in the failed
    set. This builds a compact, real reason from the per-block validation
    signal already in hand:

    * every failing gate's ``GateIssue`` located at THIS block
      (``issue["location"] == block.block_id``) contributes a
      ``"{gate_id}:{code} — {message head}"`` fragment. For a
      CURIE-preservation gate the issue message already names the dropped /
      unanchored tokens, so the missing-token list rides through; for any
      other failure the gate code is the failure class and the message is its
      head (the closest analog to an exception class + message head on a
      gate-failed block).
    * the block's ``validation_attempts`` (regen re-rolls consumed) is
      appended so exhaustion cases are self-evident.

    Returns ``None`` when no located issue is found (e.g. a batch-level
    failure with no per-block ``location``) so the caller can still emit an
    explicit ``failure_reason: null`` — an honest "failed but not per-block
    attributable" signal rather than a fabricated one. Pure + total: never
    raises on a malformed gate-result / issue shape.
    """
    block_id = getattr(block, "block_id", None)
    if not block_id:
        return None
    parts: List[str] = []
    for rd in gate_results or []:
        if not isinstance(rd, dict) or rd.get("passed"):
            continue
        gate_id = rd.get("gate_id", "unknown_gate")
        for issue in rd.get("issues", []) or []:
            if not isinstance(issue, dict):
                continue
            if issue.get("location") != block_id:
                continue
            code = issue.get("code", "?")
            msg = str(issue.get("message") or "").strip().replace("\n", " ")
            head = msg[:200]
            parts.append(
                f"{gate_id}:{code}" + (f" — {head}" if head else "")
            )
    if not parts:
        return None
    reason = "; ".join(parts)
    try:
        attempts = int(getattr(block, "validation_attempts", 0) or 0)
    except (TypeError, ValueError):
        attempts = 0
    if attempts:
        reason = f"{reason} (validation_attempts={attempts})"
    return reason


def _block_to_snake_case_entry(block: Any) -> Dict[str, Any]:
    """Project a :class:`Block` to a snake_case JSONL entry that
    round-trips through ``Block(**entry)``.

    Mirrors the accepted-keys set the helper-internal
    ``_entry_to_block`` consumers (in ``_run_post_rewrite_validation``,
    ``_run_inter_tier_validation``, ``_run_content_generation_rewrite``)
    use to rehydrate. Tuples are projected to lists for JSON
    serialisation; ``source_references`` entries are coerced to plain
    dicts.
    """
    entry: Dict[str, Any] = {
        "block_id": block.block_id,
        "block_type": block.block_type,
        "page_id": block.page_id,
        "sequence": block.sequence,
        "content": block.content,
    }
    optional_scalars = (
        "template_type", "bloom_level", "bloom_verb", "bloom_range",
        "cognitive_domain", "teaching_role", "content_type_label",
        "purpose", "component", "source_primary", "content_hash",
        "escalation_marker",
        # FR-PLAN-01 / FR-INT-01: emit ONLY when present (Optional/None default)
        # so the serializer is byte-stable when the planner flags are off; both
        # survive outline-JSONL → rewrite rehydration.
        "interaction_type", "fade_state",
    )
    for name in optional_scalars:
        value = getattr(block, name, None)
        if value is not None:
            entry[name] = value
    optional_tuples = (
        "key_terms", "objective_ids", "bloom_levels", "bloom_verbs",
        "source_ids",
    )
    for name in optional_tuples:
        value = getattr(block, name, ()) or ()
        if value:
            entry[name] = list(value)
    refs = getattr(block, "source_references", ()) or ()
    if refs:
        entry["source_references"] = [
            dict(r) if isinstance(r, dict) else r for r in refs
        ]
    if getattr(block, "validation_attempts", 0):
        entry["validation_attempts"] = int(block.validation_attempts)
    # FR-11 anchored-rubric producer output: emit ONLY when present so the
    # serializer is byte-stable when ED4ALL_ALIGNMENT_VERB_TRIPLE is off (the
    # producer leaves the field None). Survives outline-JSONL → rewrite
    # rehydration so AnchoredRubricValidator reads it at post_rewrite_validation.
    anchored_rubric = getattr(block, "anchored_rubric", None)
    if anchored_rubric is not None:
        entry["anchored_rubric"] = anchored_rubric
    # Preserve the immutable touch-chain audit trail (snake_case dict per
    # Touch, round-tripping through ``_touches_from_entry`` → ``Touch(**d)``).
    # Without this, a resume run that rehydrates blocks from blocks_final.jsonl
    # loses ``touched_by`` entirely, so the per-block synthesis manifest emits
    # ``synthesis.tiers: []`` and fails MANIFEST_SCHEMA_INVALID (the schema
    # requires minItems:1). The W3 manifest reads the model/provider/tier
    # from this chain, so dropping it silently breaks the manifest-completeness
    # gate on every cached/resumed block.
    touches = getattr(block, "touched_by", ()) or ()
    if touches:
        entry["touched_by"] = [
            {
                "model": t.model,
                "provider": t.provider,
                "tier": t.tier,
                "timestamp": t.timestamp,
                "decision_capture_id": t.decision_capture_id,
                "purpose": t.purpose,
            }
            for t in touches
        ]
    return entry


def _maybe_repair_block_html_balance(
    blocks: List[Any],
) -> Tuple[List[Any], int, Dict[str, int]]:
    """Deterministic HTML tag-balance repair over rewrite-tier blocks.

    Gated on ``COURSEFORGE_REWRITE_HTML_REPAIR`` (default OFF → the input
    list is returned unchanged, byte-identical emit). When ON, every
    str-content block runs through
    :func:`lib.utils.html_balance.repair_html_balance` (drop stray closes /
    insert missing intermediate closes / append missing closes — no LLM, no
    text or attribute edits) so the emitted ``blocks_final.jsonl``
    self-repairs the model's unbalanced-tag emissions before the
    ``rewrite_html_shape`` gate audits them. A repaired block records the op
    summary on its ``touched_by`` chain (``model="html-balance-repair"``,
    ``provider="deterministic"``, ``tier="rewrite_val"``; the compact
    ``op=count`` summary rides in ``decision_capture_id``).

    Returns ``(blocks, n_repaired, op_counts)``. Never raises: a per-block
    repair/replace failure leaves that block untouched.
    """
    from lib.utils.html_balance import (  # noqa: PLC0415
        repair_html_balance,
        resolve_rewrite_html_repair,
        summarize_ops,
    )

    if not resolve_rewrite_html_repair():
        return blocks, 0, {}

    import dataclasses as _dc_repair  # noqa: PLC0415
    from datetime import datetime as _dt, timezone as _tz  # noqa: PLC0415

    from Courseforge.scripts.blocks import Touch  # noqa: PLC0415

    out: List[Any] = []
    n_repaired = 0
    op_counts: Dict[str, int] = {}
    for blk in blocks:
        content = getattr(blk, "content", None)
        if not isinstance(content, str):
            out.append(blk)
            continue
        try:
            fixed, ops = repair_html_balance(content)
        except Exception:  # noqa: BLE001 — repair must never fail the phase
            out.append(blk)
            continue
        if fixed == content:
            out.append(blk)
            continue
        try:
            touch = Touch(
                model="html-balance-repair",
                provider="deterministic",
                tier="rewrite_val",
                timestamp=_dt.now(_tz.utc).isoformat(),
                decision_capture_id=(
                    f"html_repair:{getattr(blk, 'block_id', '?')}:"
                    f"{summarize_ops(ops)}"
                ),
                purpose="html_balance_repair",
            )
            blk = _dc_repair.replace(
                blk,
                content=fixed,
                touched_by=(
                    tuple(getattr(blk, "touched_by", ()) or ()) + (touch,)
                ),
            )
            n_repaired += 1
            for op in ops:
                op_counts[op["op"]] = op_counts.get(op["op"], 0) + 1
        except (TypeError, ValueError):
            pass
        out.append(blk)
    return out, n_repaired, op_counts


def _touches_from_entry(entry: dict) -> tuple:
    """Reconstruct the ``touched_by`` Touch tuple from a snake_case JSONL
    entry emitted by :func:`_block_to_snake_case_entry`.

    Tolerant: drops malformed Touch dicts (a ``Touch(**d)`` that raises on
    the Wave-112 invariants) rather than failing the whole block hydration,
    mirroring the field-coercion tolerance the surrounding ``_entry_to_block``
    helpers already apply. Returns an empty tuple when no ``touched_by`` key
    is present (legacy entries) so callers stay byte-stable.
    """
    raw = entry.get("touched_by")
    if not isinstance(raw, list):
        return ()
    from Courseforge.scripts.blocks import Touch  # noqa: PLC0415

    out = []
    for d in raw:
        if not isinstance(d, dict):
            continue
        try:
            out.append(Touch(
                model=d.get("model", ""),
                provider=d.get("provider", ""),
                tier=d.get("tier", ""),
                timestamp=d.get("timestamp", ""),
                decision_capture_id=d.get("decision_capture_id", ""),
                purpose=d.get("purpose", ""),
            ))
        except (TypeError, ValueError):
            continue
    return tuple(out)


# ---------------------------------------------------------------------------
# Crash-resume checkpoint sidecars for the two-pass content-generation tiers.
# ---------------------------------------------------------------------------
#
# A ~2h local-7B outline run that is killed mid-authoring loses ALL per-block
# work because the tier writes its JSONL once at the very end (open("w")).
# These pure helpers add an append-as-you-go sidecar (mirroring the
# training-synthesis ``.synthesis_pairs_checkpoint.jsonl`` per-item resume
# contract): each authored block is flushed to a dot-prefixed sidecar the
# moment it completes, so a restart rehydrates already-authored blocks and
# skips the expensive LLM dispatch for them.
#
# Default ON (parse-with-fallback). OFF (or no sidecar present) → no sidecar
# is written, the resume path is a no-op, and behaviour is byte-identical to
# the pre-checkpoint emit. The sidecar is deleted on a successful final write
# (resume is only for an INTERRUPTED run).
_COURSEFORGE_OUTLINE_CHECKPOINT_ENV = "COURSEFORGE_OUTLINE_CHECKPOINT"
_COURSEFORGE_REWRITE_CHECKPOINT_ENV = "COURSEFORGE_REWRITE_CHECKPOINT"
_CHECKPOINT_FALSEY = frozenset({"0", "false", "no", "off"})

# Sidecar filenames (dot-prefixed, sitting next to the final tier JSONL).
_OUTLINE_CHECKPOINT_NAME = ".blocks_outline_checkpoint.jsonl"
_REWRITE_CHECKPOINT_NAME = ".blocks_final_checkpoint.jsonl"


def _checkpoint_enabled(env_name: str) -> bool:
    """Read a ``COURSEFORGE_*_CHECKPOINT`` env flag (default ON).

    Parse-with-fallback mirroring the other answer-path / Courseforge knobs:
    an explicit falsey value (``0`` / ``false`` / ``no`` / ``off``, any case)
    disables both write + resume; anything else (incl. unset / garbage) keeps
    the default ON. Read each call so tests can toggle it inline.

    Delegates to the shared ``lib/generation/llm_checkpoint.py`` resolver so
    the family ``ED4ALL_GENERATION_CHECKPOINT`` flag also governs these sites
    (precedence: site flag, when SET, wins over the family flag).
    """
    return _llm_checkpoint_enabled(env_name)


# ------------------------------------------------------------------------- #
# Outline-tier dispatch resilience (dispatch-resilience-2026-07).
# ------------------------------------------------------------------------- #
# The outline per-block loop dispatches ``route_with_self_consistency`` for
# every block. An intermittent infrastructure failure (a flapping local-LLM
# endpoint under VRAM contention, a transport reset, a 429/5xx from a hosted
# seat) must NOT be conflated with SEMANTIC regen-budget exhaustion:
#   * transient errors are RETRYABLE (bounded in-loop retry) per the project
#     error taxonomy, and on give-up stamp the canonical
#     ``outline_dispatch_error`` marker — NOT ``outline_budget_exhausted``,
#     which is reserved for the router's regen-budget exhaustion path;
#   * a PERSISTENT outage would otherwise chew through the whole remaining
#     block list stamping every block escalated in minutes, so a
#     consecutive-failure circuit breaker halts the phase LOUDLY instead
#     (mirrors the batch-level poison-pill pattern in the executor).
_COURSEFORGE_OUTLINE_DISPATCH_BREAKER_ENV = "COURSEFORGE_OUTLINE_DISPATCH_BREAKER"
_OUTLINE_DISPATCH_BREAKER_DEFAULT = 5
_OUTLINE_DISPATCH_MAX_RETRIES = 3
# Modest per-block backoff ladder (seconds). Shorter than the batch-level
# transient ladder (5/30/120) — this is an in-loop per-block retry, not the
# phase retry.
_OUTLINE_DISPATCH_RETRY_BACKOFFS = (2.0, 8.0, 30.0)


def _resolve_outline_dispatch_breaker() -> int:
    """Consecutive-dispatch-failure circuit-breaker threshold (default 5).

    ``COURSEFORGE_OUTLINE_DISPATCH_BREAKER`` overrides the default; ``0``
    disables the breaker (legacy chew-through, but with the CORRECTED
    ``outline_dispatch_error`` marker). Parse-with-fallback: unset / garbage
    / negative → the default. Read each call so tests can toggle it inline.
    """
    raw = os.environ.get(_COURSEFORGE_OUTLINE_DISPATCH_BREAKER_ENV)
    if raw is None or not str(raw).strip():
        return _OUTLINE_DISPATCH_BREAKER_DEFAULT
    try:
        val = int(str(raw).strip())
    except (TypeError, ValueError):
        return _OUTLINE_DISPATCH_BREAKER_DEFAULT
    return val if val >= 0 else _OUTLINE_DISPATCH_BREAKER_DEFAULT


def _outline_dispatch_is_transient(exc: Optional[Exception]) -> bool:
    """True when an outline-tier dispatch exception is transient (retry-safe).

    Reuses the shared MCP error taxonomy (``MCP/hardening/error_classifier``):
    connection resets / 5xx / 429 / timeouts / transport errors classify
    TRANSIENT, and UNKNOWN classifications inherit the taxonomy's
    ``retry_recommended=True`` default so an unclassified endpoint flap still
    gets the bounded retry rather than an instant permanent give-up. PERMANENT
    (bad input / schema) and POISON_PILL (OOM / auth-failed / disk-full) are
    NOT retried. Never lets a classification failure break the loop.
    """
    if exc is None:
        return False
    try:
        from MCP.hardening.error_classifier import classify_error
        return bool(classify_error(exc, "outline_dispatch").retry_recommended)
    except Exception:  # noqa: BLE001 — classification is best-effort
        return False


def _tier_block_fingerprint(
    blk: Any,
    *,
    tier: str,
    chunks_lookup: Any,
    objectives_sha: str,
    router: Any = None,
) -> str:
    """Fingerprint of one outline/rewrite block's LLM-relevant inputs.

    Composes (a) the block's INPUT identity — ``Block.compute_content_hash()``
    (the canonical content+type payload hash) — (b) the source chunks fed to
    the prompt (``chunks_lookup[block_id]``), (c) the objectives payload sha
    (objectives feed the prompt), (d) the ROUTING-resolved provider/model spec
    for ``(block, tier)`` (``router._resolve_spec`` — the same resolution the
    dispatch uses, so a model/provider swap between resume attempts
    invalidates), and (e) the tier's serving-window env knobs. Any resolution
    failure degrades to hashing the raw env knobs (never crashes the loop).

    A checkpoint entry stamped with this fingerprint is reused on resume ONLY
    when the recomputed value matches; entries with NO stamp (pre-upgrade
    sidecars) keep the legacy block_id-only reuse (back-compat).
    """
    try:
        _content_sha = str(blk.compute_content_hash())
    except Exception:  # noqa: BLE001 — never crash the loop on a stub
        _content_sha = _llm_hash_text(str(getattr(blk, "content", "")))
    _chunks = []
    if isinstance(chunks_lookup, dict):
        _chunks = chunks_lookup.get(getattr(blk, "block_id", ""), []) or []
    try:
        _chunks_sha = _llm_hash_text(
            json.dumps(_chunks, sort_keys=True, default=str)
        )
    except (TypeError, ValueError):
        _chunks_sha = _llm_hash_text(str(_chunks))
    _spec_desc: Dict[str, Any] = {}
    if router is not None:
        try:
            _spec = router._resolve_spec(blk, tier)
            _spec_desc = {
                "provider": getattr(_spec, "provider", None),
                "model": getattr(_spec, "model", None),
                "base_url": getattr(_spec, "base_url", None),
                "max_tokens": getattr(_spec, "max_tokens", None),
                "temperature": getattr(_spec, "temperature", None),
            }
        except Exception:  # noqa: BLE001 — degrade to env-knob description
            _spec_desc = {}
    if not _spec_desc:
        _spec_desc = {
            "env_provider": os.environ.get(
                f"COURSEFORGE_{tier.upper()}_PROVIDER", ""
            ),
            "env_model": os.environ.get(
                f"COURSEFORGE_{tier.upper()}_MODEL", ""
            ),
            "env_courseforge_provider": os.environ.get(
                "COURSEFORGE_PROVIDER", ""
            ),
            "env_local_model": os.environ.get("LOCAL_SYNTHESIS_MODEL", ""),
        }
    return _llm_compute_fingerprint({
        "site": f"courseforge_{tier}_block",
        "block_type": str(getattr(blk, "block_type", "")),
        "content_sha": _content_sha,
        "chunks_sha": _chunks_sha,
        "objectives_sha": objectives_sha,
        "spec": _spec_desc,
        "technique": os.environ.get("ED4ALL_GENERATION_TECHNIQUE", ""),
        "num_ctx_env": os.environ.get("ED4ALL_REWRITE_NUM_CTX", ""),
        "fit_window_env": os.environ.get("ED4ALL_REWRITE_FIT_WINDOW", ""),
    })


def _objectives_payload_sha(objectives_payload: Any) -> str:
    """Stable sha of the objectives payload fed to the tier prompts."""
    try:
        return _llm_hash_text(
            json.dumps(objectives_payload, sort_keys=True, default=str)
        )
    except (TypeError, ValueError):
        return _llm_hash_text(str(objectives_payload))


# --------------------------------------------------------------------------- #
# outline-overflow-fix-2026-07: per-block objectives filter.
# --------------------------------------------------------------------------- #
# The outline tier previously passed the ENTIRE course objectives list (often
# ~90 entries, several KB) to EVERY per-block LLM call, so on a small-ctx
# served model the prompt overflowed the window and the local server silently
# head-truncated it — the model saw only the objectives TAIL and authored
# wrong-topic outlines that the downstream gates re-stamped green. Each block
# only needs the objectives RELEVANT to it: its own ``objective_ids`` (TO- or
# CO-level) plus the COs rolling up to those TOs (and a directly-cited CO's
# parent TO + sibling COs). The filter falls back to the FULL list whenever it
# resolves to empty (never an empty objectives section).
def _build_objective_rollup(
    terminal_objectives: List[Dict[str, Any]],
    chapter_objectives: List[Dict[str, Any]],
) -> Dict[str, Any]:
    """Build the TO/CO roll-up maps consumed by the per-block filter.

    Returns a dict with ``co_ids_by_to`` (Dict[to_id, Set[co_id]]),
    ``parent_to_by_co`` (Dict[co_id, to_id]), ``to_ids`` (Set[str]), and
    ``co_ids`` (Set[str]). CO→TO membership is unioned from BOTH the TO's
    ``child_co_ids`` and each CO's parent back-pointer (``parent_to`` /
    ``parent_terminal`` / ``parent_terminal_id`` / ``terminal_id``).
    """
    co_ids_by_to: Dict[str, set] = {}
    parent_to_by_co: Dict[str, str] = {}
    to_ids: set = set()
    co_ids: set = set()
    for _to in terminal_objectives or []:
        _tid = _to.get("id") if isinstance(_to, dict) else None
        if not isinstance(_tid, str) or not _tid:
            continue
        to_ids.add(_tid)
        _kids = co_ids_by_to.setdefault(_tid, set())
        for _cid in (_to.get("child_co_ids") or []):
            if isinstance(_cid, str) and _cid:
                _kids.add(_cid)
    for _co in chapter_objectives or []:
        _cid = _co.get("id") if isinstance(_co, dict) else None
        if not isinstance(_cid, str) or not _cid:
            continue
        co_ids.add(_cid)
        _parent = (
            _co.get("parent_to")
            or _co.get("parent_terminal")
            or _co.get("parent_terminal_id")
            or _co.get("terminal_id")
        )
        if isinstance(_parent, str) and _parent:
            parent_to_by_co[_cid] = _parent
            co_ids_by_to.setdefault(_parent, set()).add(_cid)
    return {
        "co_ids_by_to": co_ids_by_to,
        "parent_to_by_co": parent_to_by_co,
        "to_ids": to_ids,
        "co_ids": co_ids,
    }


def _relevant_objective_ids(
    block_objective_ids: Any,
    rollup: Dict[str, Any],
) -> set:
    """Resolve the set of objective ids relevant to a block.

    For a TO target: the TO + its rolled-up COs. For a CO target: the CO +
    its parent TO + that TO's sibling COs. An unknown id (not in the loaded
    doc) is kept verbatim (may match a payload entry; never silently
    dropped).
    """
    co_ids_by_to = rollup["co_ids_by_to"]
    parent_to_by_co = rollup["parent_to_by_co"]
    to_ids = rollup["to_ids"]
    co_ids = rollup["co_ids"]
    targets = {
        t for t in (block_objective_ids or [])
        if isinstance(t, str) and t
    }
    relevant: set = set()
    for t in targets:
        if t in to_ids:
            relevant.add(t)
            relevant |= co_ids_by_to.get(t, set())
        elif t in co_ids:
            relevant.add(t)
            _parent = parent_to_by_co.get(t)
            if _parent:
                relevant.add(_parent)
                relevant |= co_ids_by_to.get(_parent, set())
        else:
            relevant.add(t)
    return relevant


def _filter_objectives_payload_for_block(
    block_objective_ids: Any,
    objectives_payload: List[Dict[str, Any]],
    rollup: Dict[str, Any],
) -> List[Dict[str, Any]]:
    """Filter ``objectives_payload`` to the ids relevant to a block.

    Preserves the original payload item shape + order. Falls back to the
    FULL payload when the filter resolves to empty (never an empty
    objectives section).
    """
    relevant = _relevant_objective_ids(block_objective_ids, rollup)
    if not relevant:
        return objectives_payload
    filtered = [
        item for item in objectives_payload
        if isinstance(item, dict) and item.get("id") in relevant
    ]
    return filtered or objectives_payload


# --------------------------------------------------------------------------- #
# Dynamic block-planner per-week resume sidecar (plan P4 item 4 / D5).
# --------------------------------------------------------------------------- #
# The outline tier's dynamic block planner (``ED4ALL_DYNAMIC_BLOCK_PLAN``)
# dispatches ONE 70B ``plan_week_blocks`` call per week to choose that week's
# block sequence. That call lives in an EARLIER loop than the per-block outline
# sidecar, so a mid-planning kill re-dispatched every week's plan on resume.
# This sidecar checkpoints each week's plan keyed by ``week_num`` with a
# fingerprint over the planner's full input surface (TO + COs + source chunks +
# model + budget); any mismatch re-runs that week. Family-flag-only
# (``site_env=None``): governed by ``ED4ALL_GENERATION_CHECKPOINT`` alone.
_BLOCK_PLANNER_CHECKPOINT_NAME = ".block_planner_weeks_checkpoint.jsonl"


def _block_planner_store(path: Optional[Path]) -> _LlmCheckpointStore:
    return _LlmCheckpointStore(
        path, site_id="block_planner_weeks", site_env=None,
    )


def _block_planner_week_key(week_num: int) -> str:
    return f"w{int(week_num)}"


def _resolve_block_plan_concurrency() -> int:
    """Resolve the dynamic-block-planner warm-up pool size.

    ``COURSEFORGE_BLOCK_PLAN_CONCURRENCY`` (positive int) wins; garbage / < 1
    falls back to ``COURSEFORGE_OUTLINE_CONCURRENCY`` (positive int, itself
    defaulting to 1), so by DEFAULT the parallel per-week planner warm-up
    inherits the outline concurrency with no new required flag but can be tuned
    independently. Parse-with-fallback throughout (mirrors the inline
    COURSEFORGE_OUTLINE_CONCURRENCY resolver). A resolved value <= 1 means the
    warm-up is skipped entirely (byte-identical legacy sequential loop).
    """
    def _pos_int(name: str) -> Optional[int]:
        try:
            val = int(os.environ.get(name, ""))
        except (TypeError, ValueError):
            return None
        return val if val >= 1 else None

    resolved = _pos_int("COURSEFORGE_BLOCK_PLAN_CONCURRENCY")
    if resolved is not None:
        return resolved
    resolved = _pos_int("COURSEFORGE_OUTLINE_CONCURRENCY")
    if resolved is not None:
        return resolved
    return 1


def _block_planner_week_fingerprint(
    *,
    week_num: int,
    terminal_objective: Dict[str, Any],
    chapter_objectives: List[Dict[str, Any]],
    source_chunks: List[Dict[str, Any]],
    model: str,
    budget: Any,
    course_code: str,
) -> str:
    """Fingerprint every input ``plan_week_blocks`` sees for one week."""
    def _obj_desc(o: Dict[str, Any]) -> str:
        o = o or {}
        return f"{o.get('id')}\x1f{o.get('statement')}\x1f{o.get('bloom_level')}"

    _chunk_parts = [
        f"{c.get('id')}\x1f{c.get('text')}\x1f{c.get('heading')}"
        for c in (source_chunks or []) if isinstance(c, dict)
    ]
    return _llm_compute_fingerprint({
        "site": "block_planner_week",
        "week_num": int(week_num),
        "to": _obj_desc(terminal_objective or {}),
        "cos_sha": _llm_hash_text(
            "\x1e".join(_obj_desc(o) for o in (chapter_objectives or []))
        ),
        "chunks_sha": _llm_hash_text("\x1e".join(_chunk_parts)),
        "model": str(model or ""),
        "budget": str(budget),
        "course_code": str(course_code or ""),
        "new_block_types": os.environ.get("ED4ALL_NEW_BLOCK_TYPES", ""),
    })


def _serialize_week_block_plan(plan: Any) -> Dict[str, Any]:
    """Serialize a ``WeekBlockPlan`` into a JSON-able checkpoint payload."""
    _page_plan: Dict[str, Any] = {}
    for _pk, _entries in (getattr(plan, "page_plan", {}) or {}).items():
        _page_plan[_pk] = [list(_e) for _e in _entries]
    return {
        "page_plan": _page_plan,
        "selected": list(getattr(plan, "selected", []) or []),
        "fallback_used": bool(getattr(plan, "fallback_used", False)),
        "terminal_objective_id": str(
            getattr(plan, "terminal_objective_id", "") or ""
        ),
        "model": str(getattr(plan, "model", "") or ""),
    }


def _deserialize_week_block_plan(payload: Dict[str, Any]) -> Any:
    """Reconstruct a ``WeekBlockPlan`` from a checkpoint payload."""
    from lib.generation.block_planner import WeekBlockPlan  # noqa: PLC0415

    _page_plan: Dict[str, Any] = {}
    for _pk, _entries in (payload.get("page_plan") or {}).items():
        _page_plan[_pk] = [
            (str(_e[0]), str(_e[1]), list(_e[2]) if len(_e) > 2 else [])
            for _e in _entries
        ]
    return WeekBlockPlan(
        page_plan=_page_plan,
        selected=list(payload.get("selected") or []),
        fallback_used=bool(payload.get("fallback_used", False)),
        terminal_objective_id=str(payload.get("terminal_objective_id") or ""),
        model=str(payload.get("model") or ""),
    )


# --------------------------------------------------------------------------- #
# Legacy single-pass content_generation per-week resume sidecar (P4 item 3).
# --------------------------------------------------------------------------- #
# ``_generate_course_content`` (the ``course_generation``-workflow content
# phase) emits one 5-page weekly module per week via ``build_week_data`` (LLM
# authoring when ``COURSEFORGE_PROVIDER`` / ``COURSEFORGE_TWO_PASS`` is set) +
# ``generate_week``. This per-week sidecar records each completed week keyed by
# ``week_num`` with a fingerprint over the week objectives + provider spec +
# prompt version; on resume a week is SKIPPED (its page files re-collected from
# the stored payload) when the record matches AND every page file still exists.
# Family-flag-only (``site_env=None``).
_LEGACY_CONTENTGEN_CHECKPOINT_NAME = ".content_generation_weeks_checkpoint.jsonl"
_LEGACY_CONTENTGEN_PROMPT_VERSION = "v1"


def _legacy_contentgen_store(path: Optional[Path]) -> _LlmCheckpointStore:
    return _LlmCheckpointStore(
        path, site_id="content_generation_legacy", site_env=None,
    )


def _legacy_contentgen_week_key(week_num: int) -> str:
    return f"w{int(week_num)}"


def _legacy_contentgen_week_fingerprint(
    *,
    week_num: int,
    week_objectives: List[Dict[str, Any]],
    provider_spec: str,
    duration_weeks: int,
    course_code: str,
) -> str:
    """Fingerprint the per-week legacy content-gen inputs."""
    _obj_sha = _llm_hash_text(
        "\x1e".join(
            f"{o.get('id')}\x1f{o.get('statement')}"
            for o in (week_objectives or [])
        )
    )
    return _llm_compute_fingerprint({
        "site": "content_generation_legacy_week",
        "week_num": int(week_num),
        "objectives_sha": _obj_sha,
        "provider_spec": str(provider_spec or ""),
        "duration_weeks": int(duration_weeks),
        "course_code": str(course_code or ""),
        "prompt_version": _LEGACY_CONTENTGEN_PROMPT_VERSION,
    })


#: Key under which the per-block input fingerprint is stamped into a tier
#: checkpoint entry (`.blocks_outline_checkpoint.jsonl` /
#: `.blocks_final_checkpoint.jsonl`). Entries lacking it (pre-upgrade
#: sidecars) keep legacy block_id-only reuse.
_BLOCK_CHECKPOINT_FP_KEY = "checkpoint_fingerprint"


def _append_block_checkpoint(path: Path, entry: Dict[str, Any]) -> None:
    """Append one authored-block entry to the checkpoint sidecar and flush.

    ``entry`` is a ``_block_to_snake_case_entry`` projection (carries the
    stable ``block_id`` dedupe key). Best-effort: an OSError flushing the
    sidecar is logged but NEVER aborts the authoring loop — a missing
    checkpoint line only costs a re-author on resume, it never corrupts the
    run. The per-entry flush+fsync is the whole point (surviving a kill).
    """
    try:
        with path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(entry, ensure_ascii=False))
            fh.write("\n")
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except OSError:
                # fsync can fail on some filesystems / pipes; the flush
                # already pushed the line to the OS buffer.
                pass
    except OSError as exc:
        logger.warning(
            "content-generation checkpoint: failed to append block_id=%r "
            "to %s: %s",
            entry.get("block_id"), path, exc,
        )


def _load_block_checkpoint(path: Path) -> Dict[str, Any]:
    """Rehydrate a checkpoint sidecar into a ``{block_id: entry}`` map.

    Last-line-wins per ``block_id`` so a block that was re-authored across
    two interrupted attempts resolves to its most recent entry. Malformed /
    blank lines and entries without a ``block_id`` are skipped (the dedupe
    key is mandatory — an un-keyable entry can't be matched against a fresh
    stub, so it would risk a duplicate). A missing / unreadable sidecar
    returns an empty map (resume is a no-op).
    """
    out: Dict[str, Any] = {}
    if not path.exists():
        return out
    try:
        raw = path.read_text(encoding="utf-8")
    except OSError:
        return out
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            entry = json.loads(line)
        except ValueError:
            continue
        if not isinstance(entry, dict):
            continue
        bid = entry.get("block_id")
        if isinstance(bid, str) and bid:
            out[bid] = entry
    return out


def _remove_block_checkpoint(path: Path) -> None:
    """Delete the checkpoint sidecar after a successful final write.

    Resume is only for an INTERRUPTED run, so a completed tier removes its
    sidecar. Best-effort: a failed unlink is logged but never fails the
    phase (a stale sidecar is harmless — the next run dedupes against it).
    """
    try:
        path.unlink()
    except FileNotFoundError:
        pass
    except OSError as exc:
        logger.warning(
            "content-generation checkpoint: failed to remove sidecar %s: %s",
            path, exc,
        )


def _block_from_checkpoint_entry(entry: Dict[str, Any]) -> Optional[Any]:
    """Rehydrate a checkpoint entry into a frozen :class:`Block`.

    Module-level twin of the nested ``_entry_to_block`` rehydrators: consumes
    only the fields ``Block`` accepts (the same accepted-key set), restores
    tuple-typed fields + the ``touched_by`` provenance chain, and returns
    ``None`` on a malformed entry (the caller then re-authors that block, so a
    corrupt checkpoint line degrades to a re-author, never a crash). Used to
    skip re-authoring already-checkpointed blocks on resume.
    """
    from Courseforge.scripts.blocks import Block  # noqa: PLC0415

    accepted = {
        "block_id", "block_type", "page_id", "sequence", "content",
        "template_type", "key_terms", "objective_ids",
        "bloom_level", "bloom_verb", "bloom_range",
        "bloom_levels", "bloom_verbs", "cognitive_domain",
        "teaching_role", "content_type_label", "purpose",
        "component", "source_ids", "source_primary",
        "source_references", "content_hash",
        "validation_attempts", "escalation_marker",
        "anchored_rubric",
        "interaction_type", "fade_state",
    }
    tuple_fields = {
        "key_terms", "objective_ids", "bloom_levels", "bloom_verbs",
        "source_ids", "source_references",
    }
    kwargs_clean: Dict[str, Any] = {}
    for k, v in (entry or {}).items():
        if k not in accepted:
            continue
        if k in tuple_fields and isinstance(v, list):
            if k == "source_references":
                v = tuple(
                    dict(r) if isinstance(r, dict) else r for r in v
                )
            else:
                v = tuple(v)
        kwargs_clean[k] = v
    if "block_id" not in kwargs_clean or "block_type" not in kwargs_clean:
        return None
    kwargs_clean.setdefault("page_id", kwargs_clean.get("block_id", ""))
    kwargs_clean.setdefault("sequence", 0)
    kwargs_clean.setdefault("content", "")
    _touches = _touches_from_entry(entry or {})
    if _touches:
        kwargs_clean["touched_by"] = _touches
    try:
        return Block(**kwargs_clean)
    except (TypeError, ValueError) as exc:
        logger.warning(
            "content-generation checkpoint: skipping malformed checkpoint "
            "entry block_id=%r: %s",
            (entry or {}).get("block_id"), exc,
        )
        return None


# ---------------------------------------------------------------------------
# Phase 3.5 Subtasks 28-30: two-pass content_generation phase helpers
# ---------------------------------------------------------------------------
#
# These three helpers implement the outline -> validate -> rewrite seam the
# Phase 3 two-pass router introduces. Each is a thin async wrapper that:
#
#   * loads its upstream phase outputs (course_planning_path / staging_path
#     for outline; blocks_outline_path for validation; blocks_validated_path
#     for rewrite),
#   * dispatches the tier-appropriate work via :class:`CourseforgeRouter` or
#     the :mod:`Courseforge.router.inter_tier_gates` validator chain, and
#   * persists the canonical phase outputs declared in
#     ``MCP/core/workflow_runner.py::_LEGACY_PHASE_OUTPUT_KEYS`` (Phase 3
#     Subtask 5).
#
# Wave-N constraints (per Phase 3.5 Wave C scope):
# - Pre-filter the Block list before invoking ``CourseforgeRouter.route_all``
#   instead of widening that method's signature with a ``tier_filter`` kwarg.
#   Worker N2 is concurrently widening ``route_all`` itself for self-
#   consistency dispatch; pre-filtering keeps these helpers disjoint from
#   that change.
# - Decision-capture mirrors the ``_run_post_rewrite_validation`` shape:
#   each helper emits at least one ``phase`` provenance event and one
#   per-failure ``block_validation_action`` event with
#   ``ml_features.tier="outline"`` for inter_tier_validation failures.


def _resolve_inter_tier_validators(
    workflow_type: str,
    capture: Any = None,
) -> List[Any]:
    """Resolve the YAML-declared ``inter_tier_validation`` gate chain
    for ``workflow_type`` into a list of validator instances suitable
    for ``CourseforgeRouter.route_with_self_consistency(validators=...)``.

    Worker W2 (validation-wiring fix): Phase 3's self-consistency loop
    runs the inter-tier validators INSIDE the regen budget so failed
    outline candidates re-roll with remediation suffixes attached. Pre-
    fix, the outline phase called ``router.route()`` once per block and
    let the standalone ``inter_tier_validation`` phase catch failures
    after the fact — by which point the regen budget was already gone.

    Resolution chain:
      1. Load the workflow spec via ``OrchestratorConfig.load()``.
      2. Walk ``wf.phases`` for the ``inter_tier_validation`` phase.
      3. For each gate dict in ``phase.validation_gates``, import the
         dotted ``validator`` path and instantiate.
      4. Skip gates that fail to import; emit a structured warning per
         skip via ``capture`` (decision_type=
         ``inter_tier_validator_import_failed``).

    Returns ``[]`` when ``workflow_type`` is empty / unknown / has no
    ``inter_tier_validation`` phase / has no validation_gates declared
    — matching the pre-W2 ``route()`` semantics so legacy direct
    callers (tests, MCP-tool entry points without a workflow_runner-
    managed run) keep working unchanged.
    """
    import importlib

    if not workflow_type:
        return []

    try:
        from MCP.core.config import OrchestratorConfig  # noqa: PLC0415
        cfg = OrchestratorConfig.load()
        wf = cfg.get_workflow(workflow_type)
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Worker W2: OrchestratorConfig.load() failed for "
            "workflow_type=%r: %s; falling back to empty validator list",
            workflow_type, exc,
        )
        return []

    if wf is None:
        logger.warning(
            "Worker W2: workflow_type=%r not registered; falling back "
            "to empty validator list",
            workflow_type,
        )
        return []

    target_phase = None
    for phase in getattr(wf, "phases", []) or []:
        if getattr(phase, "name", "") == "inter_tier_validation":
            target_phase = phase
            break
    if target_phase is None:
        return []

    gates = getattr(target_phase, "validation_gates", None) or []
    validators: List[Any] = []
    for gate in gates:
        if not isinstance(gate, dict):
            continue
        dotted = gate.get("validator") or ""
        gate_id = gate.get("gate_id") or dotted
        if not dotted:
            continue
        try:
            module_path, _, class_name = dotted.rpartition(".")
            if not module_path or not class_name:
                raise ImportError(f"malformed dotted path: {dotted!r}")
            module = importlib.import_module(module_path)
            validator_cls = getattr(module, class_name)
            validators.append(validator_cls())
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Worker W2: failed to import inter-tier validator "
                "gate_id=%s validator=%s: %s",
                gate_id, dotted, exc,
            )
            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="inter_tier_validator_import_failed",
                        decision=(
                            f"Skipped inter-tier validator {gate_id!r} "
                            f"(dotted path {dotted!r}) — import error."
                        ),
                        rationale=(
                            f"OrchestratorConfig declared the gate at "
                            f"workflow_type={workflow_type!r} phase="
                            f"inter_tier_validation but the validator "
                            f"class did not import: {exc}. Falling "
                            f"through means this gate will NOT fire "
                            f"during the outline-tier self-consistency "
                            f"loop; check the validator dotted path."
                        ),
                        ml_features={
                            "workflow_type": workflow_type,
                            "gate_id": gate_id,
                            "dotted_path": dotted,
                            "error": str(exc),
                        },
                    )
                except Exception:  # noqa: BLE001
                    pass
            continue
    return validators


def _resolve_post_rewrite_validators(
    workflow_type: str,
    capture: Any = None,
) -> List[Any]:
    """Resolve the YAML-declared ``post_rewrite_validation`` gate chain
    for ``workflow_type`` into a list of validator instances suitable
    for ``CourseforgeRouter.route_rewrite_with_remediation(validators=...)``.

    Worker W3 (validation-wiring fix): symmetric mirror of
    :func:`_resolve_inter_tier_validators` — pulls the rewrite-tier
    validator chain from the YAML ``post_rewrite_validation`` phase so
    the rewrite-tier remediation loop runs the same gates that the
    standalone post-rewrite phase would catch (CURIE / content_type /
    page_objectives / source_refs / rewrite_html_shape /
    rewrite_source_grounding) — only INSIDE the regen budget so a
    failed rewrite re-rolls with a remediation suffix instead of being
    persisted as-is and caught downstream.

    Returns ``[]`` on missing workflow_type, missing phase, or absent
    validation_gates — matching pre-W3 ``route(..., tier="rewrite",
    source_chunks=[], objectives=[])`` semantics so legacy direct
    callers (tests, MCP-tool entry points without a workflow_runner-
    managed run) keep working unchanged.
    """
    import importlib

    if not workflow_type:
        return []

    try:
        from MCP.core.config import OrchestratorConfig  # noqa: PLC0415
        cfg = OrchestratorConfig.load()
        wf = cfg.get_workflow(workflow_type)
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Worker W3: OrchestratorConfig.load() failed for "
            "workflow_type=%r: %s; falling back to empty validator list",
            workflow_type, exc,
        )
        return []

    if wf is None:
        logger.warning(
            "Worker W3: workflow_type=%r not registered; falling back "
            "to empty validator list",
            workflow_type,
        )
        return []

    target_phase = None
    for phase in getattr(wf, "phases", []) or []:
        if getattr(phase, "name", "") == "post_rewrite_validation":
            target_phase = phase
            break
    if target_phase is None:
        return []

    gates = getattr(target_phase, "validation_gates", None) or []
    validators: List[Any] = []
    for gate in gates:
        if not isinstance(gate, dict):
            continue
        dotted = gate.get("validator") or ""
        gate_id = gate.get("gate_id") or dotted
        if not dotted:
            continue
        try:
            module_path, _, class_name = dotted.rpartition(".")
            if not module_path or not class_name:
                raise ImportError(f"malformed dotted path: {dotted!r}")
            module = importlib.import_module(module_path)
            validator_cls = getattr(module, class_name)
            validators.append(validator_cls())
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Worker W3: failed to import post-rewrite validator "
                "gate_id=%s validator=%s: %s",
                gate_id, dotted, exc,
            )
            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="post_rewrite_validator_import_failed",
                        decision=(
                            f"Skipped post-rewrite validator {gate_id!r} "
                            f"(dotted path {dotted!r}) — import error."
                        ),
                        rationale=(
                            f"OrchestratorConfig declared the gate at "
                            f"workflow_type={workflow_type!r} phase="
                            f"post_rewrite_validation but the validator "
                            f"class did not import: {exc}. Falling "
                            f"through means this gate will NOT fire "
                            f"during the rewrite-tier remediation "
                            f"loop; check the validator dotted path."
                        ),
                        ml_features={
                            "workflow_type": workflow_type,
                            "gate_id": gate_id,
                            "dotted_path": dotted,
                            "error": str(exc),
                        },
                    )
                except Exception:  # noqa: BLE001
                    pass
            continue
    return validators


def _load_outline_chunks(
    phase_outputs: Dict[str, Any],
    capture: Any = None,
) -> Dict[str, Any]:
    """Rehydrate the W2-persisted ``outline_chunks.json`` sidecar.

    Reads ``phase_outputs["content_generation_outline"]
    ["outline_chunks_path"]`` and returns the deserialized
    ``chunks_lookup`` dict (block_id -> list of chunk dicts) the outline
    phase fed into ``router.route_with_self_consistency(source_chunks=
    ...)``.

    On missing key OR missing file, emits a structured
    ``decision_type="rewrite_grounding_missing"`` warning capture and
    returns an empty dict. Pre-W3 the rewrite phase passed
    ``source_chunks=[]`` unconditionally; the empty-dict fallback
    preserves that behavior so the rewrite phase itself does not crash
    when the upstream sidecar is absent (legacy direct caller, mid-run
    crash before W2's sidecar emit, etc.).
    """
    outline_outputs = (phase_outputs or {}).get(
        "content_generation_outline"
    ) or {}
    chunks_path_raw = outline_outputs.get("outline_chunks_path")
    if not chunks_path_raw:
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="rewrite_grounding_missing",
                    decision=(
                        "Rewrite phase falling through with empty "
                        "source_chunks: outline_chunks_path absent from "
                        "phase_outputs[content_generation_outline]."
                    ),
                    rationale=(
                        "Worker W2 persists outline_chunks.json sidecar "
                        "from the outline phase so W3's rewrite phase "
                        "can rehydrate per-block source chunks for the "
                        "remediation loop. Missing key indicates the "
                        "outline phase ran a pre-W2 build, the run was "
                        "resumed from a checkpoint without the sidecar, "
                        "or this is a legacy direct call without a "
                        "workflow_runner-managed phase_outputs dict. "
                        "Falling through preserves pre-W3 ``source_chunks="
                        "[]`` semantics; downstream gates will surface "
                        "the missing-grounding signal."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "missing_key": "outline_chunks_path",
                        "phase": "content_generation_outline",
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        return {}
    try:
        chunks_path = Path(chunks_path_raw)
        if not chunks_path.exists():
            raise FileNotFoundError(str(chunks_path))
        return json.loads(chunks_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, FileNotFoundError) as exc:
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="rewrite_grounding_missing",
                    decision=(
                        "Rewrite phase falling through with empty "
                        "source_chunks: outline_chunks.json failed "
                        f"to load ({exc})."
                    ),
                    rationale=(
                        "Sidecar path was present in phase_outputs but "
                        "the file did not load. Falling through preserves "
                        "pre-W3 ``source_chunks=[]`` semantics so the "
                        "rewrite phase itself does not crash; downstream "
                        "gates surface the missing-grounding signal."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "missing_key": "outline_chunks_path",
                        "sidecar_path": str(chunks_path_raw),
                        "error": str(exc),
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        return {}


def _load_outline_objectives(
    phase_outputs: Dict[str, Any],
    capture: Any = None,
) -> List[Any]:
    """Rehydrate the W2-persisted ``outline_objectives.json`` sidecar.

    Symmetric mirror of :func:`_load_outline_chunks` for the
    ``objectives`` arg threaded into
    ``router.route_rewrite_with_remediation(objectives=...)``. Returns a
    list (canonical empty default) on missing key / missing file with a
    structured ``rewrite_grounding_missing`` warning capture.
    """
    outline_outputs = (phase_outputs or {}).get(
        "content_generation_outline"
    ) or {}
    objectives_path_raw = outline_outputs.get("outline_objectives_path")
    if not objectives_path_raw:
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="rewrite_grounding_missing",
                    decision=(
                        "Rewrite phase falling through with empty "
                        "objectives: outline_objectives_path absent from "
                        "phase_outputs[content_generation_outline]."
                    ),
                    rationale=(
                        "Worker W2 persists outline_objectives.json "
                        "sidecar from the outline phase so W3's rewrite "
                        "phase can rehydrate the canonical TO-NN/CO-NN "
                        "objectives payload. Missing key indicates a "
                        "pre-W2 build / mid-run resume / legacy direct "
                        "call. Falling through preserves pre-W3 "
                        "``objectives=[]`` semantics; downstream gates "
                        "surface the missing-grounding signal."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "missing_key": "outline_objectives_path",
                        "phase": "content_generation_outline",
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        return []
    try:
        objectives_path = Path(objectives_path_raw)
        if not objectives_path.exists():
            raise FileNotFoundError(str(objectives_path))
        payload = json.loads(objectives_path.read_text(encoding="utf-8"))
        if isinstance(payload, list):
            return payload
        return []
    except (OSError, ValueError, FileNotFoundError) as exc:
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="rewrite_grounding_missing",
                    decision=(
                        "Rewrite phase falling through with empty "
                        "objectives: outline_objectives.json failed "
                        f"to load ({exc})."
                    ),
                    rationale=(
                        "Sidecar path was present in phase_outputs but "
                        "the file did not load. Falling through preserves "
                        "pre-W3 ``objectives=[]`` semantics so the "
                        "rewrite phase itself does not crash; downstream "
                        "gates surface the missing-grounding signal."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "missing_key": "outline_objectives_path",
                        "sidecar_path": str(objectives_path_raw),
                        "error": str(exc),
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        return []


def _vocabulary_threaded_path(kwargs: Dict[str, Any]) -> Optional[str]:
    """Extract the threaded ``domain_concept_vocabulary_path``, if any.

    Reads ``kwargs['phase_outputs'].concept_extraction
    .domain_concept_vocabulary_path`` — the canonical thread the
    workflow runner sets when the Stage-3 textbook-synthesis pass ran.
    Returns ``None`` when absent (resumed / stage-subcommand runs).
    """
    phase_outputs = kwargs.get("phase_outputs") or {}
    if isinstance(phase_outputs, dict):
        ce = phase_outputs.get("concept_extraction") or {}
        candidate = ce.get("domain_concept_vocabulary_path")
        if isinstance(candidate, str) and candidate:
            return candidate
    return None


def _locate_domain_concept_vocabulary(
    course_code: str,
    kwargs: Dict[str, Any],
) -> Optional[Path]:
    """Resolve the ``domain_concept_vocabulary.json`` path for a course.

    R5 — delegates to the single canonical locator
    :func:`lib.ontology.curie_discovery.locate_domain_concept_vocabulary`
    so the threaded-path-then-on-disk-fallback resolution is identical
    across the gate-input router and the validation handlers. The
    ``course_code`` -> slug transform mirrors ``_run_concept_extraction``
    (lower + ``_``/space -> ``-``).

    Returns ``None`` when neither resolves — the natural backward-compat
    gate: an RDF / legacy corpus has no domain-concept vocabulary.
    """
    from lib.ontology.curie_discovery import locate_domain_concept_vocabulary

    course_slug = (course_code or "").lower().replace("_", "-").replace(
        " ", "-"
    )
    return locate_domain_concept_vocabulary(
        threaded_path=_vocabulary_threaded_path(kwargs),
        course_slug=course_slug or None,
        libv2_root=_resolve_libv2_root(kwargs.get("libv2_root")),
    )


def _resolve_minted_curie_map_for_validation(
    *,
    project_id: str,
    kwargs: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    """Build the minted-CURIE map for an inter-tier / post-rewrite gate.

    R5 — delegates to the single canonical resolver
    :func:`lib.ontology.curie_discovery.resolve_minted_curie_map`
    (which INCLUDES the on-disk fallback) so the gate-input router and
    the validation handlers resolve identically. The validation
    handlers carry a Courseforge ``project_id`` (the export folder
    name), not a course code; the course code is read from the
    project's ``project_config.json``.

    Returns ``None`` when no domain vocabulary exists (RDF / legacy
    corpora) or it is unparseable — the gate then runs legacy literal-
    token anchoring, byte-identical to the pre-minting contract.
    """
    from lib.ontology.curie_discovery import resolve_minted_curie_map

    course_code = project_id or ""
    if project_id:
        config_path = (
            courseforge_exports_dir()
            / project_id
            / "project_config.json"
        )
        if config_path.exists():
            try:
                cfg = json.loads(config_path.read_text(encoding="utf-8"))
                course_code = cfg.get("course_name") or course_code
            except (OSError, ValueError):
                pass
    course_slug = (course_code or "").lower().replace("_", "-").replace(
        " ", "-"
    )
    return resolve_minted_curie_map(
        threaded_path=_vocabulary_threaded_path(kwargs),
        course_id=course_code,
        course_slug=course_slug or None,
        libv2_root=_resolve_libv2_root(kwargs.get("libv2_root")),
    )


def _repair_outline_objective_refs(
    *,
    outline_blocks: List[Any],
    canonical_ids: "Set[str]",
    capture: Any,
) -> None:
    """Drop hallucinated objective refs the 7B outline tier emits (FIX 2).

    The 7B outline tier occasionally references an objective id that is
    not in the canonical synthesized set — e.g. ``TO-08`` when only four
    terminal objectives exist, or a stray ``cf:CO-36`` CURIE that leaked
    into ``content["objective_refs"]``. ``BlockPageObjectivesValidator``
    fail-closes (``OUTLINE_BLOCK_UNKNOWN_OBJECTIVE``) on these. This pass
    intersects each block's objective refs (``block.objective_ids`` and
    ``content["objective_refs"]`` / ``content["objective_ids"]``) with the
    canonical id set and DROPS any ref not in it. It never invents a ref.
    The block retains at least its assigned week ``objective_ids`` (which
    ARE canonical) when present.

    No-op when ``canonical_ids`` is empty (no canonical universe to check
    against — preserves the validator's "skip when no universe" contract).

    Mutation is in-place via ``dataclasses.replace`` (frozen Block).
    """
    if not canonical_ids:
        return

    import dataclasses as _dc

    repaired_block_count = 0
    dropped_total = 0
    for idx, block in enumerate(outline_blocks):
        content = getattr(block, "content", None)

        # Structural field.
        struct = [
            o for o in (getattr(block, "objective_ids", None) or ())
            if isinstance(o, str) and o
        ]
        new_struct = [o for o in struct if o in canonical_ids]
        struct_dropped = [o for o in struct if o not in canonical_ids]

        # content["objective_refs"] / content["objective_ids"].
        content_changes: Dict[str, List[str]] = {}
        content_dropped: List[str] = []
        if isinstance(content, dict):
            for key in ("objective_refs", "objective_ids"):
                raw = content.get(key)
                if not isinstance(raw, list):
                    continue
                kept = [
                    o for o in raw
                    if isinstance(o, str) and o in canonical_ids
                ]
                dropped = [
                    o for o in raw
                    if isinstance(o, str) and o and o not in canonical_ids
                ]
                if dropped:
                    content_changes[key] = kept
                    content_dropped.extend(dropped)

        if not struct_dropped and not content_dropped:
            continue

        replace_kwargs: Dict[str, Any] = {}
        if struct_dropped:
            replace_kwargs["objective_ids"] = tuple(new_struct)
        if content_changes:
            new_content = dict(content)
            new_content.update(content_changes)
            replace_kwargs["content"] = new_content

        outline_blocks[idx] = _dc.replace(block, **replace_kwargs)
        repaired_block_count += 1
        n_dropped = len(struct_dropped) + len(content_dropped)
        dropped_total += n_dropped

        if capture is not None:
            try:
                all_dropped = sorted(set(struct_dropped) | set(content_dropped))
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"dropped {n_dropped} hallucinated objective ref(s) "
                        f"from block {block.block_id}"
                    ),
                    rationale=(
                        f"Block {block.block_id} (type={block.block_type}) "
                        f"referenced objective id(s) {all_dropped!r} not in "
                        f"the canonical {len(canonical_ids)}-objective "
                        f"synthesized set; dropped them so the "
                        f"outline_page_objectives gate (OUTLINE_BLOCK_"
                        f"UNKNOWN_OBJECTIVE) is not tripped by a 7B "
                        f"hallucination. Valid week refs preserved verbatim; "
                        f"no ref invented."
                    ),
                    ml_features={
                        "block_id": block.block_id,
                        "dropped_count": n_dropped,
                        "dropped_refs": all_dropped,
                        "canonical_objective_count": len(canonical_ids),
                    },
                )
            except Exception:  # noqa: BLE001
                pass

    if repaired_block_count:
        logger.info(
            "outline phase: repaired objective refs on %d block(s) "
            "(%d hallucinated ref(s) dropped) against %d canonical ids",
            repaired_block_count, dropped_total, len(canonical_ids),
        )


def _block_source_chunk_text(
    block: Any,
    chunks_lookup: Optional[Dict[str, List[Any]]],
) -> str:
    """Concatenate the grounded source-chunk text for one outline block.

    ``chunks_lookup`` is the per-block ``{block_id: [{id, text, ...}]}``
    universe built in :func:`_run_content_generation_outline` (and
    persisted to ``outline_chunks.json``). A block's source chunks ARE
    its grounded provenance and ARE tagged with the domain vocabulary, so
    a vocab concept present in this text is legitimately anchored for the
    block. Only entries carrying real ``text`` count — a topic-paragraph
    fallback entry (no ``text`` key) contributes nothing, preserving the
    fail-closed contract for ungrounded blocks.

    Returns an empty string when the block has no resolved source chunks.
    """
    if not chunks_lookup:
        return ""
    entries = chunks_lookup.get(getattr(block, "block_id", ""), []) or []
    parts: List[str] = []
    for e in entries:
        if isinstance(e, dict):
            txt = e.get("text")
            if isinstance(txt, str) and txt.strip():
                parts.append(txt)
    return "\n".join(parts)


def _resolve_objective_statements_for_minting(
    *,
    course_code: str,
    kwargs: Dict[str, Any],
) -> Dict[str, str]:
    """Load ``{objective_id: statement}`` from synthesized_objectives.json.

    Used by the outline CURIE minter's objective-refs-concept anchoring
    surface: when a block's ``key_claims`` + grounded source-chunk text
    yield no domain CURIE, the minter ALSO matches the vocabulary over the
    statement text of the objectives the block declares. This loads those
    statements once.

    Resolves the path via :func:`_resolve_synthesized_objectives_path`
    (the same locator the rest of pipeline_tools uses). Returns an empty
    map when no objectives file exists / is unparseable — the
    objective-statement surface is then simply unavailable (graceful;
    minting falls back to key_claims + source-chunks only).
    """
    try:
        objectives_path = _resolve_synthesized_objectives_path(
            course_code=course_code, kwargs=kwargs,
        )
    except Exception:  # pragma: no cover — defensive
        objectives_path = None
    if not objectives_path:
        return {}
    try:
        from lib.validators.abcd_objective import _flatten_objectives
        payload = json.loads(Path(objectives_path).read_text(encoding="utf-8"))
        flat = _flatten_objectives(payload)
    except (OSError, ValueError, TypeError, ImportError) as exc:
        logger.debug(
            "outline minter: failed to load objective statements from "
            "%s (%s); objective-refs anchoring unavailable.",
            objectives_path, exc,
        )
        return {}
    statements: Dict[str, str] = {}
    for lo in flat or []:
        if not isinstance(lo, dict):
            continue
        lo_id = lo.get("id") or lo.get("objective_id")
        if not isinstance(lo_id, str) or not lo_id:
            continue
        stmt = lo.get("statement") or lo.get("text")
        if isinstance(stmt, str) and stmt.strip():
            statements[lo_id] = stmt.strip()
    return statements


def _load_objective_statements_from_path(
    objectives_path: Any,
) -> Dict[str, str]:
    """Load ``{objective_id: statement}`` from a synthesized_objectives.json.

    Shared by the inter-tier / post-rewrite validation handlers to thread
    the objective-refs-concept anchoring surface into
    ``BlockCurieAnchoringValidator``. Returns an empty map when the path is
    missing / unparseable (graceful; the objective surface is then
    unavailable and anchoring runs over key_claims + source-chunks only).
    """
    if not objectives_path:
        return {}
    try:
        from lib.validators.abcd_objective import _flatten_objectives
        path = Path(str(objectives_path))
        if not path.exists():
            return {}
        payload = json.loads(path.read_text(encoding="utf-8"))
        flat = _flatten_objectives(payload)
    except (OSError, ValueError, TypeError, ImportError) as exc:
        logger.debug(
            "validation handler: objective_statements load failed from "
            "%s (%s); objective-refs anchoring unavailable.",
            objectives_path, exc,
        )
        return {}
    statements: Dict[str, str] = {}
    for lo in flat or []:
        if not isinstance(lo, dict):
            continue
        lo_id = lo.get("id") or lo.get("objective_id")
        if not isinstance(lo_id, str) or not lo_id:
            continue
        stmt = lo.get("statement") or lo.get("text")
        if isinstance(stmt, str) and stmt.strip():
            statements[lo_id] = stmt.strip()
    return statements


def _block_objective_statement_text(
    block: Any,
    objective_statements: Dict[str, str],
) -> str:
    """Concatenate the resolved objective-statement text for one block.

    Reads the block's declared objective refs (the structural
    ``objective_ids`` field PLUS ``content["objective_refs"]`` /
    ``content["objective_ids"]`` — the 7B outline tier puts its real refs
    in ``content["objective_refs"]``), resolves each against
    ``objective_statements``, and concatenates the statements. An id that
    does not resolve contributes nothing (anti-fabrication).
    """
    if not objective_statements:
        return ""
    refs: List[str] = []
    seen: set = set()
    for oid in getattr(block, "objective_ids", ()) or ():
        if isinstance(oid, str) and oid and oid not in seen:
            refs.append(oid)
            seen.add(oid)
    content = getattr(block, "content", None)
    if isinstance(content, dict):
        for key in ("objective_refs", "objective_ids"):
            for oid in content.get(key) or []:
                if isinstance(oid, str) and oid and oid not in seen:
                    refs.append(oid)
                    seen.add(oid)
    parts: List[str] = []
    for oid in refs:
        stmt = objective_statements.get(oid)
        if isinstance(stmt, str) and stmt.strip():
            parts.append(stmt)
    return "\n".join(parts)


def _build_outline_curie_minter(
    *,
    course_code: str,
    kwargs: Dict[str, Any],
    objective_statements: Optional[Dict[str, str]] = None,
) -> Optional[Any]:
    """Load the domain vocabulary ONCE and return a per-block CURIE minter.

    Factored out of :func:`_mint_outline_curies` so the same minting logic
    can run BOTH (a) as the post-loop list pass (legacy call site) and
    (b) as the in-loop ``pre_validate_hook`` threaded into
    :meth:`CourseforgeRouter.route_with_self_consistency` — without
    re-reading ``domain_concept_vocabulary.json`` / re-compiling the
    concept seeds once per candidate.

    ``objective_statements`` (optional) is the ``{objective_id: statement}``
    map for objective-refs-concept anchoring. When supplied (or
    auto-loaded here when ``None``), a block whose ``key_claims`` +
    grounded source-chunk text yield no domain CURIE ALSO has the vocabulary
    matched over the statement text of the objectives it DECLARES — a block
    is legitimately about the concepts its objectives name. ANTI-FABRICATION
    is preserved: only a concept whose vocabulary surface form genuinely
    appears (word-boundary, via ``extract_concept_tags``) in an objective
    statement is minted; a block that matches nothing on any surface still
    mints nothing.

    Returns ``None`` when no domain vocabulary exists (RDF / legacy
    corpora) or it is unparseable / empty — the COMPLETE no-op backward-
    compat gate (no behavior flag). When present, returns an object
    exposing:

    * ``minted_map`` — the per-course minted-CURIE map (also fed to the
      in-loop validator so it can anchor minted CURIEs via surface forms).
    * ``mint_block(block, chunks_lookup) -> (new_block | None, meta | None)``
      — the single-block minter. ``new_block`` is the
      ``dataclasses.replace``-d block carrying the merged CURIEs (or
      ``None`` when the block needs no minting / matched nothing); ``meta``
      is the decision-capture payload (or ``None``). NEVER fabricates a
      CURIE — an ungrounded / no-match block mints nothing.
    """
    vocab_path = _locate_domain_concept_vocabulary(course_code, kwargs)
    if vocab_path is None:
        # No domain vocabulary — RDF / legacy corpus. No-op.
        return None
    try:
        vocabulary = json.loads(vocab_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        logger.warning(
            "outline phase: failed to load domain_concept_vocabulary.json "
            "at %s (%s); skipping CURIE minting.",
            vocab_path, exc,
        )
        return None

    from lib.ontology.curie_discovery import (
        build_minted_curie_map,
        minted_curie_by_canonical,
    )
    from lib.ontology.concept_tagging import extract_concept_tags
    from Trainforge.process_course import compile_domain_concept_seeds
    # Lazy import (inter_tier_gates lazily imports pipeline_tools, so keep
    # this off the module top level). This is the EXACT anchoring predicate
    # the inter-tier BlockCurieAnchoringValidator uses — the minter verifies
    # every candidate CURIE against it so "minted ⇒ passes the gate" holds by
    # construction (no divergent matching heuristic).
    from Courseforge.router.inter_tier_gates import _curie_anchored

    minted_map = build_minted_curie_map(vocabulary, course_id=course_code)
    if not minted_map:
        return None
    by_canonical = minted_curie_by_canonical(minted_map)

    # Compile the vocabulary concepts into (canonical, [regex]) seed
    # pairs. ``compile_domain_concept_seeds`` expects ``[{id, aliases}]``;
    # the vocabulary's per-concept ``canonical`` field is the seed id.
    seed_input = [
        {
            "id": c.get("canonical"),
            "aliases": c.get("aliases") or [],
        }
        for c in (vocabulary.get("concepts") or [])
        if isinstance(c, dict) and c.get("canonical")
    ]
    domain_concept_seeds = compile_domain_concept_seeds(seed_input)

    # Objective-refs-concept anchoring surface. When the caller did not
    # supply the {objective_id: statement} map, auto-load it from
    # synthesized_objectives.json. Empty map → the objective surface is
    # simply unavailable (graceful) and minting falls back to key_claims +
    # source-chunks only, byte-identical to the pre-fix contract.
    _objective_statements: Dict[str, str] = dict(objective_statements or {})
    if not _objective_statements:
        _objective_statements = _resolve_objective_statements_for_minting(
            course_code=course_code, kwargs=kwargs,
        )

    import dataclasses as _dc

    def mint_block(
        block: Any,
        chunks_lookup: Optional[Dict[str, List[Any]]],
    ) -> "Tuple[Optional[Any], Optional[Dict[str, Any]]]":
        content = getattr(block, "content", None)
        if not isinstance(content, dict):
            return None, None
        existing = [
            c for c in (content.get("curies") or [])
            if isinstance(c, str) and c
        ]
        # A block needs a DOMAIN CURIE when EITHER its curies list is
        # empty OR none of its existing curies is a real per-course
        # minted domain CURIE (it carries only generic / placeholder
        # tokens like ``outline:sample`` / ``cf:CO-36`` that the
        # anchoring gate cannot anchor). A block already carrying a real
        # minted domain CURIE is left untouched (never overwrite real
        # CURIEs) — this is what makes a post-loop re-run idempotent.
        has_domain_curie = any(c in minted_map for c in existing)
        if has_domain_curie:
            return None, None

        # Gather the block's text surface from ``key_claims``, handling
        # both the legacy ``List[str]`` shape and the structured
        # ``List[{claim, source_chunk_ids}]`` shape (mirrors
        # ``BlockCurieAnchoringValidator``'s text_blob assembly).
        claims_raw = content.get("key_claims") or []
        text_parts: List[str] = []
        for c in claims_raw:
            if isinstance(c, str):
                text_parts.append(c)
            elif isinstance(c, dict):
                claim_text = c.get("claim", "")
                if isinstance(claim_text, str):
                    text_parts.append(claim_text)
        claims_text = "\n".join(text_parts)
        # The block's OTHER two anchoring surfaces — computed up front so the
        # anchor-verification below sees the SAME union the inter-tier gate
        # evaluates (key_claims + grounded source-chunk text + declared-
        # objective statement text). source_chunks: the block's real
        # provenance, tagged with the domain vocabulary. objective_refs: the
        # statements of the objectives the block declares.
        source_text = _block_source_chunk_text(block, chunks_lookup)
        objective_text = _block_objective_statement_text(
            block, _objective_statements
        )

        def _resolve_anchored(canonicals: List[str]) -> List[str]:
            """Resolve canonicals → minted CURIEs, KEEPING only those that
            verifiably anchor under the gate's own ``_curie_anchored``
            predicate over the block's three block-local surfaces.

            ANTI-POISONING ROOT FIX: ``extract_concept_tags`` matches a
            concept via ANY compiled alias — including single-character /
            stopword aliases (e.g. ``slope`` alias ``"m"`` matching "meters",
            ``y_intercept`` alias ``"b"`` matching a variable ``b``) that the
            gate's ``_surface_form_can_anchor`` filters OUT. Such a raw match
            yields an UNANCHORED CURIE the gate rejects
            (``OUTLINE_BLOCK_CURIE_NOT_ANCHORED``) — and, if the gate were
            demoted, the rewrite tier would stamp the WRONG concept into
            ``data-cf-curie`` → ``concept_tags[]`` → training data. Filtering
            against the exact gate predicate makes an unanchorable match mint
            NOTHING (empty → correctly re-minted downstream from the actual
            rewritten prose) instead of guessing a wrong concept.
            """
            out: List[str] = []
            for canonical in canonicals:
                curie = by_canonical.get(canonical)
                if not curie or curie in out:
                    continue
                if _curie_anchored(
                    curie,
                    set(),
                    claims_text,
                    minted_map,
                    source_chunk_text=source_text,
                    objective_statement_text=objective_text,
                ):
                    out.append(curie)
            return out

        # Priority-order surface matching (key_claims → source_chunks →
        # objective_refs); the FIRST surface yielding ≥1 gate-ANCHORED CURIE
        # wins. A surface whose only ``extract_concept_tags`` matches are
        # unanchorable (short/stopword-alias hits) is treated as a MISS and
        # the search falls through — so a block that anchors nothing on any
        # surface mints nothing (fails closed; no fabrication). Preserves
        # byte-identical output for blocks that already anchor a concept on
        # key_claims (their anchored CURIE is kept, unchanged).
        matched_canonicals: List[str] = []
        matched_surface = "key_claims"
        minted_curies: List[str] = []
        for _surface_name, _surface_text in (
            ("key_claims", claims_text),
            ("source_chunks", source_text),
            ("objective_refs", objective_text),
        ):
            if not _surface_text.strip():
                continue
            _cands = extract_concept_tags(
                _surface_text, {}, domain_concept_seeds
            )
            _anchored = _resolve_anchored(_cands)
            if _anchored:
                matched_canonicals = _cands
                matched_surface = _surface_name
                minted_curies = _anchored
                break
        if not minted_curies:
            # No vocab concept's surface form verifiably anchors in the
            # block's own text — mint nothing. It fails closed downstream
            # (no fabrication; empties are re-minted from the rewrite prose).
            return None, None

        # Append the minted domain CURIE(s) to any existing generic curies
        # (never delete the existing tokens), deduped.
        merged = list(existing)
        for c in minted_curies:
            if c not in merged:
                merged.append(c)
        new_content = dict(content)
        new_content["curies"] = merged
        new_block = _dc.replace(block, content=new_content)
        meta = {
            "block_id": block.block_id,
            "minted_curies": minted_curies,
            "matched_canonicals": matched_canonicals,
            "matched_surface": matched_surface,
            "existing": existing,
            "minted_map_size": len(minted_map),
        }
        return new_block, meta

    def _domain_curies(block: Any) -> List[str]:
        """Return the block's per-course minted DOMAIN CURIEs (keys of the
        minted map), preserving list order and ignoring generic tokens."""
        content = getattr(block, "content", None)
        if not isinstance(content, dict):
            return []
        return [
            c for c in (content.get("curies") or [])
            if isinstance(c, str) and c in minted_map
        ]

    def _page_prefix(block: Any) -> str:
        """The block's page id — the ``block_id`` prefix before ``#``
        (shape ``{page_id}#{block_type}_{slug}_{idx}``)."""
        bid = getattr(block, "block_id", "") or ""
        return bid.split("#", 1)[0]

    def sibling_fallback_sweep(
        blocks: List[Any],
    ) -> "List[Tuple[int, Any, Dict[str, Any]]]":
        """SECOND-sweep sibling-page CURIE inheritance (order-independent).

        Runs AFTER the per-block ``mint_block`` sweep has populated the
        blocks list, so it observes the FINAL minted state regardless of
        block order. For every block that STILL carries no domain CURIE
        (its key_claims + source-chunks + objective-refs surfaces all
        missed), it inherits the modal (most frequent) minted domain
        CURIE(s) — capped at 2 — from its same-page siblings that DID end
        up with a domain CURIE (pre-existing or minted earlier this pass).
        A page's blocks share the page's chunk universe and objective
        scope, so the page's dominant concept is genuinely the support
        block's subject — grounded inheritance, NOT fabrication. When NO
        same-page sibling carries a domain CURIE, the block inherits
        nothing (unchanged fail-closed behavior).

        Returns ``[(idx, new_block, meta), ...]`` for every block that
        inherited; the caller applies them to its own list representation
        and emits the decision capture. DETERMINISTIC: the modal tie-break
        sorts by (frequency desc, CURIE lexicographically), never by
        dict / set iteration order — so it is stable under PYTHONHASHSEED.
        """
        from collections import Counter, defaultdict

        # Per-page frequency of each domain CURIE (count = number of blocks
        # on that page carrying it) + per-page donor-block count. Built in
        # a FIRST loop over the whole list so per-candidate inheritance is
        # independent of block order.
        page_curie_counts: "Dict[str, Counter]" = defaultdict(Counter)
        page_donor_count: "Dict[str, int]" = defaultdict(int)
        for b in blocks:
            if b is None:
                continue
            dc = _domain_curies(b)
            if not dc:
                continue
            page = _page_prefix(b)
            page_donor_count[page] += 1
            for c in set(dc):
                page_curie_counts[page][c] += 1

        results: "List[Tuple[int, Any, Dict[str, Any]]]" = []
        for idx, b in enumerate(blocks):
            if b is None:
                continue
            content = getattr(b, "content", None)
            if not isinstance(content, dict):
                continue
            if _domain_curies(b):
                # Already anchored (pre-existing or first-sweep mint) —
                # never overwrite a real domain CURIE.
                continue
            page = _page_prefix(b)
            counts = page_curie_counts.get(page)
            if not counts:
                # No same-page sibling carries a domain CURIE — fail
                # closed, mint nothing.
                continue
            # Modal selection, deterministic: frequency descending, then
            # CURIE lexicographically ascending (never dict / set order).
            # Capped at 2 inherited CURIEs.
            ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
            inherited = [c for c, _ in ranked[:2]]
            if not inherited:
                continue
            existing = [
                c for c in (content.get("curies") or [])
                if isinstance(c, str) and c
            ]
            merged = list(existing)
            for c in inherited:
                if c not in merged:
                    merged.append(c)
            new_content = dict(content)
            new_content["curies"] = merged
            new_block = _dc.replace(b, content=new_content)
            meta = {
                "block_id": b.block_id,
                "minted_curies": inherited,
                "matched_canonicals": [],
                "matched_surface": "sibling_page_fallback",
                "existing": existing,
                "minted_map_size": len(minted_map),
                "sibling_count": page_donor_count.get(page, 0),
                "page_id": page,
            }
            results.append((idx, new_block, meta))
        return results

    from types import SimpleNamespace

    return SimpleNamespace(
        minted_map=minted_map,
        mint_block=mint_block,
        sibling_fallback_sweep=sibling_fallback_sweep,
    )


def _mint_outline_curies(
    *,
    outline_blocks: List[Any],
    course_code: str,
    kwargs: Dict[str, Any],
    capture: Any,
    chunks_lookup: Optional[Dict[str, List[Any]]] = None,
) -> None:
    """Mint per-course CURIEs onto curie-less outline blocks (v0.3.0).

    Locates the Stage-3 ``domain_concept_vocabulary.json``; when absent
    this is a complete no-op (RDF / legacy corpora unaffected — the key
    backward-compat contract). When present, builds the minted-CURIE
    map, compiles the vocabulary into ``domain_concept_seeds``, and for
    every outline block whose ``content`` is a dict that NEEDS a domain
    CURIE runs concept-tag extraction over the block's ``key_claims``
    text surface AND — when that misses — over the block's grounded
    SOURCE-CHUNK text (``chunks_lookup``), stamping the matching minted
    CURIEs in.

    A block "needs a domain CURIE" when EITHER its ``content["curies"]``
    is empty OR it carries only GENERIC / non-domain CURIEs (none of the
    existing curies is a key in the per-course minted-CURIE map — e.g.
    ``outline:sample`` / ``cf:CO-36`` placeholders the 7B emits). In
    the generic-curie case the minted domain CURIE is APPENDED (the
    existing curies are never deleted). A block already carrying a real
    minted domain CURIE is left untouched.

    Matching the block's SOURCE-CHUNK text (not only ``key_claims``) is
    rigorous, NOT a relaxation: the source chunks are the block's real
    grounded provenance and carry the domain vocabulary, so a concept in
    them is genuinely the block's subject. Ungrounded blocks (no resolved
    source chunks AND no key_claims match) still mint nothing → fail
    closed downstream; no fabrication.

    Mutation is in-place via ``dataclasses.replace`` on each Block (the
    Block dataclass is frozen).

    IDEMPOTENT: a block already carrying a real per-course minted domain
    CURIE is left untouched, so re-running this AFTER the in-loop
    ``pre_validate_hook`` minted the same blocks is a safe no-op for those
    blocks (it still catches any block the loop never routed / never
    minted).
    """
    minter = _build_outline_curie_minter(
        course_code=course_code, kwargs=kwargs,
    )
    if minter is None:
        # No domain vocabulary — RDF / legacy corpus. No-op.
        return

    minted_block_count = 0
    minted_curie_total = 0
    for idx, block in enumerate(outline_blocks):
        new_block, meta = minter.mint_block(block, chunks_lookup)
        if new_block is None or meta is None:
            continue
        outline_blocks[idx] = new_block
        minted_block_count += 1
        minted_curie_total += len(meta["minted_curies"])
        _emit_curie_minting_capture(capture, block, meta)

    # SECOND sweep: sibling-page fallback. Runs after the per-block sweep
    # so it observes the FINAL minted state (order-independent). A block
    # whose key_claims + source-chunks + objective-refs all missed inherits
    # the modal domain CURIE(s) from its same-page minted siblings.
    for idx, new_block, meta in minter.sibling_fallback_sweep(outline_blocks):
        outline_blocks[idx] = new_block
        minted_block_count += 1
        minted_curie_total += len(meta["minted_curies"])
        _emit_curie_minting_capture(capture, new_block, meta)

    if minted_block_count:
        logger.info(
            "outline phase: minted CURIEs onto %d block(s) "
            "(%d CURIE(s) total) from %d-concept domain vocabulary",
            minted_block_count, minted_curie_total,
            len(minter.minted_map),
        )


def remint_blocks_outline_jsonl(
    *,
    blocks_outline_path: "Union[str, Path]",
    course_code: str,
    libv2_root: "Optional[Union[str, Path]]" = None,
    objectives_path: "Optional[Union[str, Path]]" = None,
    in_place: bool = True,
) -> Dict[str, Any]:
    """Re-mint CURIEs onto an existing ``blocks_outline.jsonl`` IN PLACE.

    Operator-facing reusable entry point for the objective-refs-concept
    anchoring fix: load the 515-block outline JSONL, run the (now
    objective-aware) minter over every block whose ``content["curies"]``
    carries no real domain CURIE, and write the re-minted blocks back to
    disk (round-tripping the same snake-case JSONL shape the outline tier
    emits). DETERMINISTIC — CPU-only, no LLM/GPU.

    The minter's objective-refs surface is auto-resolved from
    ``synthesized_objectives.json`` (sibling ``01_learning_objectives/``
    by default, or ``objectives_path`` when supplied). ANTI-FABRICATION is
    fully preserved — a block matching no vocab surface form on key_claims,
    source-chunks, OR its declared objectives' statements mints nothing.

    Returns a summary dict ``{total, reminted, still_curieless,
    minted_curie_total}``. When ``in_place`` is False, computes the same
    stats without writing (dry-run).
    """
    blocks_path = Path(str(blocks_outline_path))
    if not blocks_path.exists():
        raise FileNotFoundError(f"blocks_outline.jsonl not found: {blocks_path}")

    entries: List[Dict[str, Any]] = []
    blocks: List[Any] = []
    with blocks_path.open("r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            entry = json.loads(line)
            entries.append(entry)
            blocks.append(_block_from_checkpoint_entry(entry))

    kwargs: Dict[str, Any] = {}
    if libv2_root is not None:
        kwargs["libv2_root"] = str(libv2_root)

    objective_statements: Dict[str, str] = {}
    if objectives_path is not None:
        objective_statements = _load_objective_statements_from_path(
            objectives_path
        )
    minter = _build_outline_curie_minter(
        course_code=course_code,
        kwargs=kwargs,
        objective_statements=objective_statements or None,
    )
    if minter is None:
        return {
            "total": len(blocks),
            "reminted": 0,
            "still_curieless": sum(
                1 for b in blocks
                if isinstance(getattr(b, "content", None), dict)
                and not (b.content.get("curies") or [])
            ),
            "minted_curie_total": 0,
            "minter": None,
        }

    reminted = 0
    minted_curie_total = 0
    for idx, block in enumerate(blocks):
        if block is None:
            continue
        new_block, meta = minter.mint_block(block, None)
        if new_block is None or meta is None:
            continue
        blocks[idx] = new_block
        entries[idx] = _block_to_snake_case_entry(new_block)
        reminted += 1
        minted_curie_total += len(meta["minted_curies"])

    # SECOND sweep: sibling-page fallback (shared minter layer, mirrors the
    # in-phase _mint_outline_curies pass). Order-independent — reads the
    # final minted state after the per-block sweep completes.
    for idx, new_block, meta in minter.sibling_fallback_sweep(blocks):
        blocks[idx] = new_block
        entries[idx] = _block_to_snake_case_entry(new_block)
        reminted += 1
        minted_curie_total += len(meta["minted_curies"])

    still_curieless = sum(
        1 for b in blocks
        if b is not None
        and isinstance(getattr(b, "content", None), dict)
        and not (b.content.get("curies") or [])
    )

    if in_place and reminted:
        with blocks_path.open("w", encoding="utf-8") as fh:
            for entry in entries:
                fh.write(json.dumps(entry, ensure_ascii=False) + "\n")

    return {
        "total": len(blocks),
        "reminted": reminted,
        "still_curieless": still_curieless,
        "minted_curie_total": minted_curie_total,
        "minter": minter,
    }


def restamp_blocks_final_jsonl(
    *,
    blocks_final_path: "Union[str, Path]",
    course_code: str,
    libv2_root: "Optional[Union[str, Path]]" = None,
    in_place: bool = False,
) -> Dict[str, Any]:
    """Re-stamp content_type + CURIE anchoring onto a rewrite ``blocks_final.jsonl``.

    Operator-facing reusable entry point that retro-applies the two
    DETERMINISTIC rewrite-tier backstops to a rewrite-tier
    ``blocks_final.jsonl`` produced BEFORE the content_type-map +
    prose-fallback-CURIE-minting fixes landed (so an existing export reaches
    0 critical ``post_rewrite_validation`` failures without a fresh, slow
    7B/GPU re-author). CPU-only, no LLM/GPU. The two passes mirror the
    in-loop rewrite backstops in :func:`_run_content_generation_rewrite`:

    1. **content_type** — for any STR-content block whose ``block_type`` is in
       :data:`_REWRITE_BLOCK_TYPE_CONTENT_TYPE` and whose HTML carries no
       ``data-cf-content-type``, inject the canonical ChunkType label onto the
       first start tag via :func:`_inject_content_type_attr` (idempotent).
    2. **CURIE anchoring** — for any STR-content shipping block whose
       HTML-stripped body carries no extractable CURIE, mint a real domain
       CURIE from the block's OWN published prose against the per-course
       domain-concept vocabulary (the prose-fallback minter) and append it as a
       hidden ``<span data-cf-curie>`` whose TEXT content carries the tokens
       (the only placement the str-path validator can extract). A junk
       ``data-cf-curie`` span carrying no extractable CURIE is stripped first.
       Anti-fabrication: no vocabulary / no surface-form match → mint nothing
       (the block stays curieless and still fails the gate honestly).

    Skips unshipped escalation tombstones (marker + empty content) and
    deterministic-template (``key_terms``) blocks — exactly the blocks
    ``BlockCurieAnchoringValidator`` / ``BlockContentTypeValidator`` skip — so
    the re-stamp universe equals the gate's audit universe.

    ``in_place`` defaults to **False** (dry-run: computes + returns the stats
    without writing, so a caller can preview before overwriting the real
    export). Set ``in_place=True`` to write the re-stamped JSONL back.

    Returns ``{total, audited, content_type_stamped, curie_minted,
    still_curieless, wrote}``.
    """
    import dataclasses as _dc_local
    from Courseforge.router.inter_tier_gates import (
        _strip_html as _strip_html_fn,
        _is_unshipped_escalation_tombstone as _is_tombstone_fn,
        _is_deterministic_template_block as _is_det_template_fn,
    )
    from lib.ontology.curie_extraction import extract_curies as _extract_curies_fn

    blocks_path = Path(str(blocks_final_path))
    if not blocks_path.exists():
        raise FileNotFoundError(f"blocks_final.jsonl not found: {blocks_path}")

    # Build the per-course minted-CURIE resources ONCE (mirrors the in-loop
    # rewrite backstop). No vocabulary (RDF / legacy) -> empty -> curie pass
    # is a complete no-op.
    minted_by_canonical: Dict[str, str] = {}
    domain_seeds: list = []
    kwargs: Dict[str, Any] = {}
    if libv2_root is not None:
        kwargs["libv2_root"] = str(libv2_root)
    try:
        _vocab_path = _locate_domain_concept_vocabulary(course_code, kwargs)
        if _vocab_path is not None:
            _vocabulary = json.loads(_vocab_path.read_text(encoding="utf-8"))
            from lib.ontology.curie_discovery import (
                build_minted_curie_map as _build_map_fn,
                minted_curie_by_canonical as _by_canon_fn,
            )
            from Trainforge.process_course import (
                compile_domain_concept_seeds as _compile_seeds_fn,
            )
            _minted_map = _build_map_fn(_vocabulary, course_id=course_code) or {}
            if _minted_map:
                minted_by_canonical = _by_canon_fn(_minted_map)
                _seed_input = [
                    {"id": c.get("canonical"), "aliases": c.get("aliases") or []}
                    for c in (_vocabulary.get("concepts") or [])
                    if isinstance(c, dict) and c.get("canonical")
                ]
                domain_seeds = _compile_seeds_fn(_seed_input)
    except Exception as _exc:  # noqa: BLE001 — best-effort; no-op on fail
        logger.warning(
            "restamp_blocks_final_jsonl: domain-CURIE resources unavailable "
            "(%s); CURIE re-stamp pass is a no-op.", _exc,
        )
        minted_by_canonical = {}
        domain_seeds = []

    def _mint_from_prose(prose: str) -> List[str]:
        if not domain_seeds or not minted_by_canonical:
            return []
        if not isinstance(prose, str) or not prose.strip():
            return []
        try:
            from lib.ontology.concept_tagging import (
                extract_concept_tags as _tags_fn,
            )
            matched = _tags_fn(prose, {}, domain_seeds)
        except Exception:  # noqa: BLE001
            return []
        out: List[str] = []
        for _canon in matched:
            _curie = minted_by_canonical.get(_canon)
            if _curie and _curie not in out:
                out.append(_curie)
        return out

    entries: List[Dict[str, Any]] = []
    with blocks_path.open("r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            entries.append(json.loads(line))

    total = len(entries)
    audited = 0
    content_type_stamped = 0
    curie_minted = 0
    still_curieless = 0

    for entry in entries:
        if not isinstance(entry, dict):
            continue
        # Rehydrate ONLY for the tombstone / deterministic-template skip
        # predicates (block_type / content / template_type / escalation_marker).
        # ``_block_from_checkpoint_entry`` consumes ``content`` verbatim, so a
        # str-content entry keeps its HTML string (it does NOT reconstruct the
        # outline dict shape). The actual re-stamp operates on the raw
        # ``entry["content"]`` string, not the rehydrated block.
        block = _block_from_checkpoint_entry(entry)
        if block is None:
            continue
        content = entry.get("content")
        if not isinstance(content, str):
            continue
        # Skip the EXACT blocks the gates skip (tombstone / deterministic
        # template) so the re-stamp universe == the gate audit universe.
        if _is_tombstone_fn(block) or _is_det_template_fn(block):
            continue
        audited += 1
        new_content = content
        block_type = entry.get("block_type")

        # ---- content_type pass (fill-missing OR repair-invalid) ----
        _ct_label = _resolve_block_content_type(block_type)
        new_content, _ct_filled, _ct_repaired = _apply_content_type_backstop(
            new_content, block_type,
        )
        if _ct_filled or _ct_repaired:
            content_type_stamped += 1
        # Promote a freshly-filled label onto the structural field; on a repair
        # the existing label may itself be the invalid value, so overwrite it
        # with the canonical default when it is not a valid ChunkType.
        if _ct_label and _ct_filled and not entry.get("content_type_label"):
            entry["content_type_label"] = _ct_label
        elif _ct_label and _ct_repaired:
            _existing = entry.get("content_type_label")
            if not isinstance(_existing, str) or _existing not in _VALID_CONTENT_TYPES:
                entry["content_type_label"] = _ct_label

        # ---- CURIE anchoring pass ----
        try:
            _body_curies = sorted(_extract_curies_fn(_strip_html_fn(new_content)))
        except Exception:  # noqa: BLE001
            _body_curies = []
        if not _body_curies:
            # Strip a junk data-cf-curie span (carries no extractable CURIE).
            # ``_strip_junk_curie_spans`` also removes UNTERMINATED junk spans
            # (open tag never closed by ``</span>``) — otherwise the surviving
            # ``data-cf-curie`` substring makes the idempotence guard below
            # refuse the fresh mint forever (the real root cause of 17/23
            # curieless blocks on a real rewrite export).
            if "data-cf-curie" in new_content:
                new_content = _strip_junk_curie_spans(new_content)
            _tokens: List[str] = []
            try:
                _prose = _strip_html_fn(new_content)
            except Exception:  # noqa: BLE001
                _prose = ""
            for _minted in _mint_from_prose(_prose):
                if _minted not in _tokens:
                    _tokens.append(_minted)
            if _tokens and "data-cf-curie" not in new_content:
                _txt = " ".join(_tokens)
                new_content = (
                    f"{new_content}"
                    f'<span hidden data-cf-curie="{_txt}">{_txt}</span>'
                )
                curie_minted += 1
            else:
                # Recheck after junk-span strip in case the body already
                # carried a real CURIE the strip exposed.
                try:
                    _post = sorted(
                        _extract_curies_fn(_strip_html_fn(new_content))
                    )
                except Exception:  # noqa: BLE001
                    _post = []
                if not _post:
                    still_curieless += 1

        entry["content"] = new_content

    wrote = False
    if in_place and (content_type_stamped or curie_minted):
        with blocks_path.open("w", encoding="utf-8") as fh:
            for entry in entries:
                fh.write(json.dumps(entry, ensure_ascii=False) + "\n")
        wrote = True

    return {
        "total": total,
        "audited": audited,
        "content_type_stamped": content_type_stamped,
        "curie_minted": curie_minted,
        "still_curieless": still_curieless,
        "wrote": wrote,
    }


# Canonical per-block-type interactive-component marker attributes, mirroring
# the templated-emit attr helpers in ``Courseforge/scripts/blocks.py``
# (``_flip_card_grid_attrs`` / ``_self_check_question_attrs`` /
# ``_activity_attrs``). Consumed by the required-attr re-injection helper:
# these values are FIXED per block_type (never content-derived), so injecting
# them is deterministic.
_REWRITE_COMPONENT_PURPOSE_BY_TYPE: Dict[str, "Tuple[str, str]"] = {
    "flip_card_grid": ("flip-card", "term-definition"),
    "self_check_question": ("self-check", "formative-assessment"),
    "activity": ("activity", "practice"),
}

# Recovers an AUTHORED ``data-cf-key-terms`` value trapped inside mangled
# attribute quoting (broken-quote emits swallow the attribute so the gate's
# parser never sees it, but the quoted value itself survives verbatim in the
# raw text). Recovery-only: the captured value is the rewrite LLM's own emit.
_KEY_TERMS_ATTR_VALUE_RE = re.compile(
    r'data-cf-key-terms\s*=\s*"([^"<>]+)"',
    re.IGNORECASE,
)


def _recover_authored_key_terms(html: str) -> Optional[str]:
    """Recover the block's own authored ``data-cf-key-terms`` value.

    Returns the sanitized comma-joined value, or ``None`` when the block's
    raw text carries no recoverable authored value (anti-fabrication: key
    terms are content-authored, never invented by the repairer). Sanitation
    is REMOVAL-ONLY: comma tokens polluted by attribute residue (an ``=`` or
    a ``data-cf`` fragment swallowed by the broken quoting) are dropped.
    """
    m = _KEY_TERMS_ATTR_VALUE_RE.search(html or "")
    if not m:
        return None
    tokens = [t.strip() for t in m.group(1).split(",")]
    clean = [
        t for t in tokens
        if t and "=" not in t and "data-cf" not in t.lower()
    ]
    return ", ".join(clean) if clean else None


def _inject_named_attr(html: str, attr_name: str, value: str) -> str:
    """Stamp ``{attr_name}="{value}"`` onto the first start tag.

    Generic sibling of :func:`_inject_block_id_attr` /
    :func:`_inject_content_type_attr` for the required-attr re-injection
    helper. No-op when the value is empty or no start tag is found. The
    value is attribute-escaped. Idempotence is enforced by the CALLER (it
    injects only attrs the gate's parser reports missing).
    """
    if not attr_name or not value:
        return html
    from html import escape as _esc_attr  # noqa: PLC0415
    safe = _esc_attr(str(value), quote=True)

    def _repl(match: "re.Match") -> str:
        tag, attrs, closing = match.group(1), match.group(2), match.group(3)
        return f'<{tag}{attrs} {attr_name}="{safe}"{closing}>'

    return _FIRST_START_TAG_RE.sub(_repl, html, count=1)


def reinject_required_attrs_blocks_final_jsonl(
    *,
    blocks_final_path: "Union[str, Path]",
    in_place: bool = False,
) -> Dict[str, Any]:
    """Re-inject deterministically-derivable REQUIRED ``data-cf-*`` attrs.

    Operator-facing sibling of :func:`restamp_blocks_final_jsonl` for the
    ``rewrite_html_shape`` gate's ``REWRITE_MISSING_REQUIRED_ATTR`` class.
    For every audited block it runs the gate's OWN parser
    (``lib.validators.rewrite_html_shape._ShapeParser``) to find which
    required attributes (``REQUIRED_ATTRS[block_type]``) the parser cannot
    see, then injects only those whose value is deterministically derivable
    from the block's OWN metadata or the canonical per-type emitter
    constants — never content invented by the repairer:

    * ``data-cf-block-id``      → the block's own ``block_id``.
    * ``data-cf-component`` /
      ``data-cf-purpose``       → fixed per block_type
      (:data:`_REWRITE_COMPONENT_PURPOSE_BY_TYPE`, mirroring
      ``Courseforge/scripts/blocks.py``).
    * ``data-cf-content-type``  → the block_type's canonical ChunkType
      (:func:`_resolve_block_content_type`).
    * ``data-cf-key-terms``     → RECOVERY-ONLY: the block's own authored
      value trapped in mangled attribute quoting
      (:func:`_recover_authored_key_terms`); absent → not derivable.
    * ``data-cf-bloom-level``   → the entry's own ``bloom_level`` field.
    * ``data-cf-objective-id`` /
      ``data-cf-objective-ref`` → the entry's own first ``objective_ids``.

    A non-derivable attr is left missing (reported in ``unrepairable``).
    Each injection is VERIFIED by re-parsing with the gate's parser; if the
    injected attr still cannot be seen (hopelessly mangled first tag) the
    block's content is reverted (reported in ``unrepairable``). Idempotent:
    a re-run finds nothing missing and rewrites nothing. CPU-only, no LLM.

    Returns ``{total, audited, blocks_repaired, attrs_injected,
    unrepairable, wrote}`` where ``unrepairable`` is a list of
    ``{block_id, attrs}`` dicts.
    """
    from lib.validators.rewrite_html_shape import (
        REQUIRED_ATTRS as _REQUIRED_ATTRS_MAP,
        _ShapeParser as _GateShapeParser,
        _is_unshipped_escalation_tombstone as _is_tombstone_shape_fn,
    )

    blocks_path = Path(str(blocks_final_path))
    if not blocks_path.exists():
        raise FileNotFoundError(f"blocks_final.jsonl not found: {blocks_path}")

    def _found_attrs(html: str) -> "Optional[Set[str]]":
        parser = _GateShapeParser()
        try:
            parser.feed(html)
            parser.close()
        except Exception:  # noqa: BLE001 — parse-fail class, not attr class
            return None
        return parser.found_attrs

    entries: List[Dict[str, Any]] = []
    with blocks_path.open("r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            entries.append(json.loads(line))

    total = len(entries)
    audited = 0
    blocks_repaired = 0
    attrs_injected = 0
    unrepairable: List[Dict[str, Any]] = []

    for entry in entries:
        if not isinstance(entry, dict):
            continue
        block = _block_from_checkpoint_entry(entry)
        if block is None:
            continue
        content = entry.get("content")
        if not isinstance(content, str):
            continue
        if _is_tombstone_shape_fn(block):
            continue
        block_type = entry.get("block_type")
        required = _REQUIRED_ATTRS_MAP.get(block_type or "", ())
        if not required:
            continue
        audited += 1
        found = _found_attrs(content)
        if found is None:
            continue
        missing = [a for a in required if a not in found]
        if not missing:
            continue

        # Derive values for the missing attrs (None => not derivable).
        comp_purpose = _REWRITE_COMPONENT_PURPOSE_BY_TYPE.get(block_type or "")
        objective_ids = entry.get("objective_ids") or []
        first_objective = (
            objective_ids[0]
            if objective_ids and isinstance(objective_ids[0], str)
            else None
        )
        bloom_level = entry.get("bloom_level")
        derived: Dict[str, Optional[str]] = {}
        for attr in missing:
            if attr == "data-cf-block-id":
                derived[attr] = entry.get("block_id") or None
            elif attr == "data-cf-component":
                derived[attr] = comp_purpose[0] if comp_purpose else None
            elif attr == "data-cf-purpose":
                derived[attr] = comp_purpose[1] if comp_purpose else None
            elif attr == "data-cf-content-type":
                derived[attr] = _resolve_block_content_type(block_type)
            elif attr == "data-cf-key-terms":
                derived[attr] = _recover_authored_key_terms(content)
            elif attr == "data-cf-bloom-level":
                derived[attr] = (
                    bloom_level.strip()
                    if isinstance(bloom_level, str) and bloom_level.strip()
                    else None
                )
            elif attr in ("data-cf-objective-id", "data-cf-objective-ref"):
                derived[attr] = first_objective
            else:
                derived[attr] = None

        injectable = {a: v for a, v in derived.items() if v}
        not_derivable = sorted(a for a, v in derived.items() if not v)

        new_content = content
        for attr, value in injectable.items():
            new_content = _inject_named_attr(new_content, attr, value)

        injected_ok = False
        if injectable and new_content != content:
            # VERIFY with the gate's own parser: every injected attr must
            # now be visible, or the injection is reverted (a hopelessly
            # mangled first tag can swallow appended attrs).
            post = _found_attrs(new_content)
            if post is not None and all(a in post for a in injectable):
                entry["content"] = new_content
                blocks_repaired += 1
                attrs_injected += len(injectable)
                injected_ok = True

        failed_attrs = sorted(
            set(not_derivable)
            | (set() if injected_ok or not injectable else set(injectable))
        )
        if failed_attrs:
            unrepairable.append(
                {"block_id": entry.get("block_id"), "attrs": failed_attrs}
            )

    wrote = False
    if in_place and blocks_repaired:
        with blocks_path.open("w", encoding="utf-8") as fh:
            for entry in entries:
                fh.write(json.dumps(entry, ensure_ascii=False) + "\n")
        wrote = True

    return {
        "total": total,
        "audited": audited,
        "blocks_repaired": blocks_repaired,
        "attrs_injected": attrs_injected,
        "unrepairable": unrepairable,
        "wrote": wrote,
    }


def _emit_curie_minting_capture(
    capture: Any,
    block: Any,
    meta: Dict[str, Any],
) -> None:
    """Emit the ``curie_minting`` decision event for one minted block.

    Shared by the post-loop list pass (:func:`_mint_outline_curies`) and
    the in-loop ``pre_validate_hook`` so both call sites produce an
    identically-shaped, replayable capture. Best-effort (a capture raise
    never disturbs the minting path).
    """
    if capture is None:
        return
    minted_curies = meta["minted_curies"]
    matched_canonicals = meta["matched_canonicals"]
    matched_surface = meta["matched_surface"]
    existing = meta["existing"]
    minted_map_size = meta["minted_map_size"]
    sibling_count = meta.get("sibling_count")
    page_id = meta.get("page_id")
    if matched_surface == "sibling_page_fallback":
        # Grounded sibling-page inheritance: neither key_claims,
        # source-chunks, nor objective-refs matched a vocab surface form,
        # so the block inherited its page's dominant minted CURIE(s) from
        # same-page siblings. Rationale interpolates the sibling count +
        # inherited CURIEs (dynamic-rationale contract).
        rationale = (
            f"Block {block.block_id} (type={block.block_type}) on page "
            f"{page_id!r} matched no vocab surface form on key_claims, "
            f"source-chunks, or objective-refs; it inherited the modal "
            f"minted domain CURIE(s) {minted_curies} (cap 2) from "
            f"{sibling_count} same-page sibling(s) that carry a minted "
            f"domain CURIE — the page's shared chunk universe makes the "
            f"page's dominant concept the block's grounded subject, so "
            f"the anchoring gate has a prose-corpus-valid CURIE to anchor."
        )
    else:
        rationale = (
            f"Block {block.block_id} (type={block.block_type}) "
            f"carried {'empty' if not existing else 'generic'} "
            f"content['curies']={existing!r}; its {matched_surface} "
            f"text matched {len(matched_canonicals)} of the "
            f"{minted_map_size} domain-concept-vocabulary "
            f"concepts, of which the gate-ANCHORED subset {minted_curies} "
            f"was minted from the per-course CURIE map (candidates whose "
            f"only surface form is a short/stopword alias the gate's "
            f"_surface_form_can_anchor rejects are dropped, never minted) so "
            f"every stamped CURIE passes BlockCurieAnchoringValidator by "
            f"construction and no wrong concept can poison concept_tags."
        )
    ml_features = {
        "block_id": block.block_id,
        "minted_curie_count": len(minted_curies),
        "vocabulary_concept_count": minted_map_size,
        "matched_concept_count": len(matched_canonicals),
        "matched_surface": matched_surface,
        "had_generic_curies": bool(existing),
    }
    if matched_surface == "sibling_page_fallback":
        ml_features["sibling_donor_count"] = sibling_count
        ml_features["page_id"] = page_id
    # Capture-quality contract (proficient floor): reference the REAL
    # inputs the minting decision consumed — the block plus the actual
    # vocabulary concepts its text matched (sibling-fallback consumed the
    # page's donor siblings instead). The genuine alternative every mint
    # weighs is doing nothing: leaving ``content['curies']`` empty/generic
    # fails ``BlockCurieAnchoringValidator`` on a prose corpus — that gate
    # failure is exactly why the minting pass exists. When the anchorability
    # filter dropped matched concepts, minting those too was the other
    # genuinely-rejected option.
    inputs_ref = [
        {"source_type": "block", "path_or_id": str(block.block_id)}
    ]
    if matched_surface == "sibling_page_fallback":
        inputs_ref.append(
            {
                "source_type": "sibling_page_blocks",
                "path_or_id": (
                    f"{page_id}#{sibling_count}_minted_sibling_donor(s)"
                ),
            }
        )
    else:
        inputs_ref.extend(
            {"source_type": "domain_concept", "path_or_id": str(canonical)}
            for canonical in matched_canonicals
        )
    alternatives = [
        (
            f"leave content['curies']={existing!r} unchanged (rejected: "
            "the block then fails BlockCurieAnchoringValidator on a "
            "prose corpus — the gate gap this minting pass closes)"
        ),
    ]
    dropped_count = len(matched_canonicals) - len(minted_curies)
    if matched_surface != "sibling_page_fallback" and dropped_count > 0:
        alternatives.append(
            f"also mint the {dropped_count} matched concept(s) whose only "
            "surface form fails _surface_form_can_anchor (rejected: an "
            "unanchorable short/stopword alias would fail the gate and "
            "poison concept_tags)"
        )
    try:
        capture.log_decision(
            decision_type="curie_minting",
            decision=(
                f"minted {len(minted_curies)} CURIE(s) onto "
                f"block {block.block_id}"
            ),
            rationale=rationale,
            ml_features=ml_features,
            alternatives_considered=alternatives,
            inputs_ref=inputs_ref,
        )
    except Exception:  # noqa: BLE001
        pass


def _align_outline_blocks_to_objectives(
    *,
    outline_blocks: List[Any],
    objectives_payload: List[Dict[str, Any]],
    capture: Any,
) -> List[Any]:
    """W2 §6 — populate each outline block's ``objective_refs`` via embedding.

    Wraps :func:`lib.objectives.block_alignment.align_blocks_to_objectives`,
    building a single offline embedding client and degrading to pass-through
    (the model's outline-tier refs stand) when the ``[embedding]`` extras are
    absent or any backend resolution fails. Strict mode
    (``TRAINFORGE_REQUIRE_EMBEDDINGS``) re-raises rather than silently passing
    through, mirroring the rest of the embedding strict contract.
    """
    if not outline_blocks or not objectives_payload:
        return outline_blocks

    from lib.objectives.block_alignment import align_blocks_to_objectives
    from lib.embedding.providers import (
        EmbeddingBackendUnavailable,
        allow_fake_enabled,
        build_embedding_client,
    )

    require_strict = str(
        os.environ.get("TRAINFORGE_REQUIRE_EMBEDDINGS", "")
    ).strip().lower() in {"1", "true", "yes", "on"}

    embed = None
    try:
        embed = build_embedding_client(offline=True)
        # Refuse a fake-provider client unless explicitly allowed (anti-
        # poisoning gate parity with the dedup pass).
        resolved = getattr(embed, "resolved", None)
        if getattr(resolved, "kind", None) == "fake" and not allow_fake_enabled():
            embed = None
    except EmbeddingBackendUnavailable:
        if require_strict:
            raise
        embed = None
    except Exception as exc:  # noqa: BLE001
        if require_strict:
            raise
        logger.warning(
            "outline phase: block-alignment embed client unavailable (%s); "
            "passing through outline-tier objective_refs unchanged.", exc,
        )
        embed = None

    if embed is None:
        # Pass-through — no fabricated alignment, model refs stand.
        return outline_blocks

    try:
        aligned = align_blocks_to_objectives(
            outline_blocks, objectives_payload, embed=embed, capture=capture,
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never abort the phase
        logger.warning(
            "outline phase: block-alignment pass failed (%s); passing through "
            "outline-tier objective_refs unchanged.", exc,
        )
        return outline_blocks
    return aligned


def _load_semantik_chunkset_text_map(chunks_path: Path) -> Dict[str, str]:
    """Load ``<…>/dart_chunks/chunks.jsonl`` into a ``{chunk_id: text}`` map.

    Each JSONL line is a chunk object carrying its id under ``id``
    (canonical) or ``chunk_id`` (legacy) and its body under ``text``
    (canonical) or ``content`` (legacy). Lines that don't resolve to a
    non-empty (id, text) pair are skipped. Best-effort: a malformed line
    is warning-logged and skipped rather than crashing the phase.

    Returns an empty map when the file is absent / unreadable so the
    caller can fail-SAFE to the existing topic-paragraph behavior.
    """
    text_map: Dict[str, str] = {}
    if not chunks_path.exists() or not chunks_path.is_file():
        return text_map
    try:
        raw = chunks_path.read_text(encoding="utf-8")
    except OSError as exc:
        logger.warning(
            "outline phase: failed to read chunkset at %s: %s",
            chunks_path, exc,
        )
        return text_map
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except (ValueError, TypeError):
            continue
        if not isinstance(obj, dict):
            continue
        cid = obj.get("id") or obj.get("chunk_id")
        body = obj.get("text") or obj.get("content")
        if isinstance(cid, str) and cid and isinstance(body, str) and body:
            text_map.setdefault(cid, body)
    return text_map


def _load_semantik_chunkset_detail_map(
    chunks_path: Path,
) -> Dict[str, Dict[str, Any]]:
    """Load ``dart_chunks/chunks.jsonl`` into a per-chunk DETAIL map.

    Feature I5: the key-terms builder needs more than the body text — it needs
    each chunk's ``item_path`` + ``section_heading`` (to mint a source deep-link)
    and ``concept_tags`` (a term source). Returns
    ``{chunk_id: {text, item_path, heading, concept_tags}}``. Reads the same
    JSONL as :func:`_load_semantik_chunkset_text_map`; provenance fields live under
    the chunk's ``source`` block (chunk_v4 schema). Best-effort: malformed lines
    are skipped, and the map is empty when the file is absent.
    """
    detail: Dict[str, Dict[str, Any]] = {}
    if not chunks_path.exists() or not chunks_path.is_file():
        return detail
    try:
        raw = chunks_path.read_text(encoding="utf-8")
    except OSError:
        return detail
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except (ValueError, TypeError):
            continue
        if not isinstance(obj, dict):
            continue
        cid = obj.get("id") or obj.get("chunk_id")
        body = obj.get("text") or obj.get("content")
        if not (isinstance(cid, str) and cid and isinstance(body, str) and body):
            continue
        source = obj.get("source") if isinstance(obj.get("source"), dict) else {}
        tags = obj.get("concept_tags")
        detail.setdefault(cid, {
            "id": cid,
            "text": body,
            "item_path": source.get("item_path") or obj.get("item_path") or "",
            "heading": (
                source.get("section_heading")
                or obj.get("section_heading")
                or obj.get("heading")
                or ""
            ),
            "concept_tags": list(tags) if isinstance(tags, list) else [],
        })
    return detail


def _chapter_label_to_week_num(label: Any) -> Optional[int]:
    """Map a ``chapter`` label (e.g. ``"Week 3"`` / ``3`` / ``"3"``) to N.

    Returns ``None`` when no week number can be parsed — the caller drops
    the objective from the per-week index (it cannot be attributed to a
    week) rather than guessing.
    """
    if isinstance(label, bool):
        return None
    if isinstance(label, int):
        return label if label >= 1 else None
    if not isinstance(label, str):
        return None
    text = label.strip()
    if not text:
        return None
    # Match a trailing / standalone integer ("Week 3", "Chapter 3", "3").
    match = re.search(r"(\d+)\s*$", text)
    if not match:
        match = re.search(r"(\d+)", text)
    if not match:
        return None
    try:
        n = int(match.group(1))
    except (TypeError, ValueError):
        return None
    return n if n >= 1 else None


def _build_week_chunk_id_index(
    chapter_objective_groups: List[Dict[str, Any]],
    *,
    week_terminal_chunk_ids: Optional[Dict[int, List[str]]] = None,
) -> Dict[int, List[str]]:
    """Build a ``{week_num: [chunk_id, ...]}`` index from grounded objectives.

    Consumes the RAW *grouped* ``chapter_objectives`` shape
    (``[{"chapter": <label>, "objectives": [{..., "source_refs":
    [{"ref", "chunk_ids":[...]}]}, ...]}, ...]``) — NOT the flattened
    loader output. The flattened ``load_objectives_json`` form strips the
    per-group ``chapter``/week label, so the prior label match resolved
    zero chunks for every block. The caller normalizes whatever on-disk
    shape it finds (list-of-groups / flat / dict-of-lists) to the grouped
    form via :func:`_normalize_chapter_objectives_to_groups` before
    calling this.

    Week resolution per group, in order:

    1. Parse ``group["chapter"]`` via :func:`_chapter_label_to_week_num`
       ("Week 3" / 3 / "3" → ``3``).
    2. **Positional fallback** — when the label yields ``None`` (the
       synthesizer-dependent label is not "Week N"), the i-th group
       (0-based) maps to week ``i + 1``. The synthesizer emits groups in
       week order, so position is the reliable signal when the label is
       absent.

    For each resolved week the union of every objective's
    ``source_refs[].chunk_ids`` is taken, then the chunk_ids already
    gathered from the week's terminal objectives are folded in. Order is
    preserved (first-seen wins) and ids are de-duplicated.
    """
    index: Dict[int, List[str]] = {}
    seen: Dict[int, set] = {}

    def _add(week: int, cid: str) -> None:
        if not isinstance(cid, str) or not cid:
            return
        bucket = index.setdefault(week, [])
        seen_set = seen.setdefault(week, set())
        if cid not in seen_set:
            seen_set.add(cid)
            bucket.append(cid)

    for position, group in enumerate(chapter_objective_groups or []):
        if not isinstance(group, dict):
            continue
        week = _chapter_label_to_week_num(group.get("chapter"))
        if week is None:
            # Positional fallback: i-th group → week i+1 (groups are
            # emitted in week order by the synthesizer).
            week = position + 1
        for obj in group.get("objectives") or []:
            if not isinstance(obj, dict):
                continue
            for ref in obj.get("source_refs") or []:
                if not isinstance(ref, dict):
                    continue
                for cid in ref.get("chunk_ids") or []:
                    _add(week, cid)

    for week, cids in (week_terminal_chunk_ids or {}).items():
        for cid in cids:
            _add(week, cid)

    return index


def _clamp_week(week: int, duration_weeks: Optional[int]) -> int:
    """Clamp a resolved CO-group week into ``[1, duration_weeks]``.

    Review fix 2 (page-per-CO). :func:`_chapter_label_to_week_num` returns an
    UNBOUNDED parsed chapter int, so a "Chapter 12" group on a ``--weeks 8`` run
    lands in week 12 — a week the descriptor loop's ``range(1, duration_weeks+1)``
    NEVER iterates, so those COs silently vanish (the documented 15-chapter
    failure mode). Folding overflow into the LAST week keeps every CO reachable
    by some emitted page. ``duration_weeks=None``/``<1`` → identity (the legacy
    builders pass None so OFF behaviour is byte-identical).
    """
    if not isinstance(duration_weeks, int) or duration_weeks < 1:
        return week
    if week < 1:
        return 1
    if week > duration_weeks:
        return duration_weeks
    return week


def _resolve_content_page_count(
    *, topic_count: int, co_count: int, page_per_co: bool,
    uncapped: Optional[bool] = None,
) -> int:
    """Resolve a week's content-page count (page-per-CO review fix 3).

    OFF (``page_per_co`` False) → ``max(topic_count, 1)`` verbatim (the legacy
    O(sections) driver). ON → one content page per CO (``max(co_count, 1)``)
    with the NEVER-INCREASE guard: cap at today's ``max(topic_count, 1)`` so a
    CO-rich / topic-thin week can never emit MORE pages than today. A
    topic-less week (``topic_count == 0``) is NOT capped to zero — it falls
    through to ``max(co_count, 1)`` (the week always emits ≥1 content page).

    ``uncapped`` (``ED4ALL_CONTENT_PAGE_PER_CO_UNCAPPED``, explicit arg > env):
    when truthy AND ``page_per_co`` is on, return ``max(co_count, 1)`` with NO
    topic cap — the operator explicitly chose ONE HTML page per CO, so a
    CO-rich / topic-thin week emits a page for EVERY CO (the slice binding
    then degenerates to exactly the 1:1 page↔CO map). Default unset → the
    guard stays intact (byte-identical). Inert when ``page_per_co`` is off.
    """
    if not page_per_co:
        return max(topic_count, 1)
    co_driven = max(co_count, 1)
    if uncapped is None:
        from lib.generation.content_page_budget import (  # noqa: PLC0415
            content_page_per_co_uncapped,
        )

        uncapped = content_page_per_co_uncapped()
    if uncapped:
        return co_driven
    if topic_count:
        return min(co_driven, max(topic_count, 1))
    return co_driven


def _page_co_slice_bounds(
    *, page_idx: int, n_pages: int, co_count: int
) -> Tuple[int, int]:
    """Contiguous book-order CO slice ``[lo, hi)`` for content page ``page_idx``.

    Coverage-gap fix: the page-per-CO NEVER-INCREASE guard
    (:func:`_resolve_content_page_count`) can resolve FEWER content pages than
    the week has COs (a CO-rich / topic-thin week). A 1:1 positional binding
    (page ``i`` ↔ CO ``i``) then silently strands every CO past index
    ``n_pages - 1``. This helper partitions the week's CO list across pages
    instead: the ``n_pages`` slices exactly tile ``range(co_count)`` (page
    ``i`` gets COs ``floor(i*m/n) .. floor((i+1)*m/n) - 1``), so every CO is
    bound to EXACTLY ONE page (zero-stranded by construction, still book
    order, still deterministic).

    When ``co_count == n_pages`` (the common case) every page gets exactly one
    CO, matching the plain 1:1 binding. Returns
    ``(0, 0)`` for an out-of-range page / empty CO list (no binding — the
    caller's legacy topic path handles it).
    """
    if n_pages < 1 or co_count < 1 or not (0 <= page_idx < n_pages):
        return (0, 0)
    lo = (page_idx * co_count) // n_pages
    hi = ((page_idx + 1) * co_count) // n_pages
    return (lo, hi)


def _content_page_heading_slug(
    *,
    page_bound_co_id: Optional[str],
    page_bound_co_statement: str,
    topic: Optional[Dict[str, Any]],
    page_type: str,
    week_num: int,
    slug_fn: Callable[[str], str],
) -> Tuple[str, str]:
    """Resolve a content page's ``(heading, slug_value)`` (page-per-CO fix).

    When the page is bound 1:1 to a CO (``page_bound_co_id`` truthy AND the CO
    carries a non-empty statement), derive BOTH from the bound CO's statement —
    the slug is the first ~8 words through ``slug_fn`` — instead of the
    positional ``topic.heading`` (which routinely belongs to an unrelated
    section). Otherwise return the exact legacy topic-heading path (byte-stable
    for every non-page-per-CO page and any content page with no resolvable
    bound CO / empty statement).
    """
    if page_bound_co_id and page_bound_co_statement:
        heading = page_bound_co_statement
        slug_value = slug_fn(
            " ".join(page_bound_co_statement.split()[:8]) or page_type
        )
        return heading, slug_value
    heading = (topic or {}).get("heading") or (
        f"week_{week_num:02d} {page_type.replace('_', ' ').title()}"
        if page_type != "content"
        else f"week_{week_num:02d}"
    )
    return heading, slug_fn(heading or page_type)


def _build_week_co_chunk_index(
    chapter_objective_groups: List[Dict[str, Any]],
    *,
    duration_weeks: Optional[int] = None,
    require_id: bool = False,
) -> Dict[int, List[List[str]]]:
    """Build ``{week_num: [[chunk_id, ...] per CO, ...]}`` — the per-objective
    chunk universe parallel to :func:`_build_week_chunk_id_index`'s union.

    Fix 2A (improvement-map Step 2b). The week-wide union offered by
    :func:`_build_week_chunk_id_index` is a "semantic grab-bag": every block
    on every page of a week is offered the UNION of every CO's chunks in that
    week, so a block authored for one objective can cite chunks belonging to
    an unrelated topic on the same week (e.g. a "fractions" block pulling
    prime-factorization / LCM chunks). This index preserves the per-CO split
    so the caller can NARROW each page's offered universe to a single
    objective's chunks (positional page→CO scoping), falling back to the
    week-wide union when a per-CO slice is too thin to ground a block.

    Same RAW *grouped* input + same week-resolution rules as
    :func:`_build_week_chunk_id_index` (parse ``group["chapter"]`` →
    ``"Week N"`` → ``N``; positional ``i+1`` fallback when the label does not
    parse), so a given group lands in the SAME week bucket in both indexes.
    For each week the value is an ORDERED list of per-CO chunk-id lists, one
    inner list per objective (group order preserved). Per-CO chunk_ids are
    de-duplicated WITHIN their own objective; identical ids may recur ACROSS
    objectives (that overlap is exactly what the union collapses and what the
    per-CO split deliberately keeps visible). Objectives that resolve to zero
    chunk_ids contribute an empty inner list (the caller's floor handles it).

    Terminal-objective chunk_ids are intentionally NOT folded in here: they
    are not objective-scoped at the CO grain (the terminal slice is week-
    scoped), so folding them would re-introduce the grab-bag this index
    exists to avoid. They remain available via the week-wide union fallback.
    """
    index: Dict[int, List[List[str]]] = {}

    for position, group in enumerate(chapter_objective_groups or []):
        if not isinstance(group, dict):
            continue
        week = _chapter_label_to_week_num(group.get("chapter"))
        if week is None:
            week = position + 1
        # Review fix 2 (page-per-CO): clamp into [1, duration_weeks] so a
        # chapter-numbered group past the last week is not silently dropped.
        # ``duration_weeks=None`` (the legacy caller) → identity.
        week = _clamp_week(week, duration_weeks)
        week_bucket = index.setdefault(week, [])
        for obj in group.get("objectives") or []:
            if not isinstance(obj, dict):
                continue
            # Predicate-identity with ``_build_week_co_objectives_index``: when
            # ``require_id`` is on (page-per-CO path), SKIP id-less objectives
            # in BOTH builders so the i-th chunk slice positionally aligns with
            # the i-th objective. The legacy caller leaves ``require_id`` off →
            # byte-identical (every objective contributes an inner list).
            if require_id and not obj.get("id"):
                continue
            co_cids: List[str] = []
            co_seen: set = set()
            for ref in obj.get("source_refs") or []:
                if not isinstance(ref, dict):
                    continue
                for cid in ref.get("chunk_ids") or []:
                    if isinstance(cid, str) and cid and cid not in co_seen:
                        co_seen.add(cid)
                        co_cids.append(cid)
            week_bucket.append(co_cids)

    return index


def _build_week_co_objectives_index(
    chapter_objective_groups: List[Dict[str, Any]],
    *,
    duration_weeks: Optional[int] = None,
) -> Dict[int, List[Dict[str, Any]]]:
    """Build ``{week_num: [{id, statement, bloom_level}, ...]}`` per week.

    Wave-2 Part 3: the dynamic block planner needs each week's CHILD chapter
    objectives (id + statement + bloom) so the 70B can choose blocks that
    cover them. Uses the SAME group→week resolution as
    :func:`_build_week_chunk_id_index` / :func:`_build_week_co_chunk_index`
    (parse ``group["chapter"]`` → "Week N", positional ``i+1`` fallback), so a
    group's COs land in the SAME week bucket as its chunk slices.
    """
    index: Dict[int, List[Dict[str, Any]]] = {}
    for position, group in enumerate(chapter_objective_groups or []):
        if not isinstance(group, dict):
            continue
        week = _chapter_label_to_week_num(group.get("chapter"))
        if week is None:
            week = position + 1
        # Review fix 2 (page-per-CO): clamp into [1, duration_weeks] so a
        # chapter-numbered group past the last week lands in the last iterated
        # week instead of an unreachable bucket. ``duration_weeks=None`` (the
        # legacy caller) → identity. Mirrors ``_build_week_co_chunk_index``.
        week = _clamp_week(week, duration_weeks)
        bucket = index.setdefault(week, [])
        for obj in group.get("objectives") or []:
            if not isinstance(obj, dict):
                continue
            oid = obj.get("id")
            if not oid:
                # Predicate shared with ``_build_week_co_chunk_index``'s
                # ``require_id`` path: id-less objectives are skipped here too,
                # so the two indexes stay positionally aligned.
                continue
            bucket.append({
                "id": str(oid),
                "statement": str(obj.get("statement") or ""),
                "bloom_level": str(obj.get("bloom_level") or ""),
            })
    return index


def _resolve_block_objective_ids(
    target_co_ids: Sequence[str],
    week_objective_ids: Tuple[str, ...],
    valid_co_ids: Set[str],
) -> Tuple[str, ...]:
    """Resolve a planned content block's ``objective_ids`` (CO-id fan-out fix).

    Wave-2 Part 3 follow-up. The dynamic block planner stamps a per-block
    ``target_co_ids`` (the SPECIFIC chapter objective(s) the block teaches).
    Historically every block in a week inherited the week's TERMINAL objective
    id(s) (``week_objective_ids``), collapsing the Learning-Objectives-Map
    fan-out to the TO level. This helper repairs that at the root:

    * When the planner gave one or more ``target_co_ids`` that resolve against
      the course's valid CO-id set, stamp the block with THOSE CO ids.
    * When ``target_co_ids`` is empty (a genuinely cross-cutting block — a week
      overview spanning all COs) OR none of the supplied ids are valid, fall
      back to the week-level ``week_objective_ids`` (the TO) — byte-identical
      to the legacy behaviour, and exactly the fixed-plan path's behaviour
      (the fixed plan always supplies empty ``target_co_ids``).

    Pure + slug-agnostic: no I/O, no course-name literals. Order-preserving and
    de-duplicating over the supplied ``target_co_ids``.
    """
    seen: Set[str] = set()
    resolved: List[str] = []
    for cid in target_co_ids or ():
        if isinstance(cid, str) and cid in valid_co_ids and cid not in seen:
            seen.add(cid)
            resolved.append(cid)
    if resolved:
        return tuple(resolved)
    return tuple(week_objective_ids)


def _build_key_terms_blocks(
    *,
    week_num: int,
    objective_ids: Tuple[str, ...],
    week_cos: Sequence[Dict[str, Any]],
    week_chunk_details: Sequence[Dict[str, Any]],
    vocabulary: Optional[Dict[str, Any]],
    course_slug: str,
    capture: Any = None,
) -> List[Any]:
    """Feature I5 — build the per-TO/week deterministic key-terms vocab cards.

    DETERMINISTIC post-pass (no LLM). For the week's terminal objective:

      1. Aggregate terms = union of (the TO's COs' chunk ``concept_tags``)
         ∪ (``domain_concept_vocabulary`` surface-form matches in the TO's
         grounded chunk text) ∪ (objective ``keyConcepts`` when present);
         dedup on canonical slug; sort.
      2. Resolve each term's DEFINITION preferring a source-chunk definition
         sentence, falling back to ``definition_hint``; OMIT the term when
         NEITHER resolves (anti-fabrication — never invent a definition).
      3. Resolve a per-term SOURCE LINK to the defining chunk's ``item_path`` +
         heading fragment via the FROZEN ``heading_slug`` algorithm.

    Each surviving term is emitted as a ``Block(block_type="vocab_card")``
    carrying pre-rendered HTML string ``content`` + ``template_type="key_terms"``
    so the rewrite tier short-circuits the LLM dispatch for it. Returns ``[]``
    when no term resolves (the page is then never emitted — no empty page).
    """
    from Courseforge.scripts.blocks import Block  # noqa: PLC0415
    from lib.generation import key_terms as _kt  # noqa: PLC0415
    from lib.ontology.slugs import canonical_slug as _slug  # noqa: PLC0415

    # Gather the term-source signals from the week's chunks + COs.
    concept_tags: List[str] = []
    chunk_texts: List[str] = []
    for ch in week_chunk_details or ():
        if not isinstance(ch, dict):
            continue
        body = ch.get("text")
        if isinstance(body, str) and body:
            chunk_texts.append(body)
        for t in ch.get("concept_tags") or ():
            if isinstance(t, str) and t:
                concept_tags.append(t)
    key_concepts: List[str] = []
    for co in week_cos or ():
        if not isinstance(co, dict):
            continue
        for kc in co.get("keyConcepts") or co.get("key_concepts") or ():
            if isinstance(kc, str) and kc:
                key_concepts.append(kc)

    terms = _kt.aggregate_terms(
        concept_tags=concept_tags,
        chunk_texts=chunk_texts,
        vocabulary=vocabulary,
        key_concepts=key_concepts,
    )
    cards = _kt.build_key_terms_cards(
        terms=terms,
        chunks=list(week_chunk_details or ()),
        course_slug=course_slug,
    )
    if not cards:
        return []

    # I5 BUG 2 — deterministic per-page cap (ED4ALL_KEY_TERMS_MAX_PER_PAGE,
    # default 15). The aggregation is broad (~40 terms/TO on a real corpus —
    # far too many for a glossary); keep the MOST relevant (source-defined
    # first, then most-frequent in the week's grounded chunks + CO statements).
    # Deterministic + order-stable (page order stays slug-sorted).
    _co_statements: List[str] = []
    for _co in week_cos or ():
        if not isinstance(_co, dict):
            continue
        _stmt = _co.get("statement") or _co.get("text")
        if isinstance(_stmt, str) and _stmt:
            _co_statements.append(_stmt)
    _cards_before_cap = len(cards)
    cards = _kt.select_capped_cards(
        cards,
        max_terms=_kt.resolve_max_terms_per_page(),
        chunk_texts=chunk_texts,
        co_statements=_co_statements,
    )

    page_id = _page_id_for(week_num, "key_terms")
    slug_value = _slug(f"week_{week_num:02d} key terms")
    blocks: List[Any] = []
    for idx, card in enumerate(cards):
        content = _kt.render_term_card(
            display=card["display"],
            definition=card["definition"],
            source_link=card.get("source_link"),
            slug=card["slug"],
        )
        # Resolve the defining chunk's real DART source id (when present) so the
        # block carries grounding the source-ref gate can resolve.
        block_sids: Tuple[str, ...] = ()
        _chunk = card.get("source_chunk")
        if isinstance(_chunk, dict):
            _cid = _chunk.get("id")
            if isinstance(_cid, str) and _cid:
                block_sids = (f"semantik:{course_slug}#{_cid}",)
        try:
            blk = Block(
                block_id=Block.stable_id(
                    page_id, "vocab_card", card["slug"], idx,
                ),
                block_type="vocab_card",
                page_id=page_id,
                sequence=idx,
                content=content,
                # The deterministic-marker the rewrite tier reads to SKIP the
                # LLM dispatch for this pre-authored, grounded card.
                template_type=_kt.KEY_TERMS_TEMPLATE_TYPE,
                key_terms=(card["slug"],),
                objective_ids=objective_ids,
                source_ids=block_sids,
                target_bloom="remember",
            )
        except (TypeError, ValueError) as exc:
            logger.warning(
                "key_terms: skipping malformed vocab_card block for "
                "week=%d term=%s: %s", week_num, card["slug"], exc,
            )
            continue
        blocks.append(blk)

    if capture is not None and blocks:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"Authored {len(blocks)} deterministic key-terms vocab "
                    f"card(s) for week {week_num} (page {page_id})."
                ),
                rationale=(
                    f"Feature I5 key-terms post-pass: aggregated "
                    f"{len(terms)} candidate term(s) from "
                    f"{len(concept_tags)} concept_tag(s), "
                    f"{len(chunk_texts)} grounded chunk(s), and "
                    f"{len(key_concepts)} objective keyConcept(s); "
                    f"{len(blocks)} resolved to a source-sentence or "
                    f"definition_hint definition (the rest OMITTED — never "
                    f"fabricated). No LLM dispatch (template_type="
                    f"{_kt.KEY_TERMS_TEMPLATE_TYPE}); rewrite tier passes the "
                    f"grounded HTML through verbatim."
                ),
                ml_features={
                    "gate_id": "_build_key_terms_blocks",
                    "week_num": week_num,
                    "page_id": page_id,
                    "candidate_terms": len(terms),
                    "cards_before_cap": _cards_before_cap,
                    "max_terms_per_page": _kt.resolve_max_terms_per_page(),
                    "cards_emitted": len(blocks),
                    "concept_tags": len(concept_tags),
                    "grounded_chunks": len(chunk_texts),
                    "key_concepts": len(key_concepts),
                },
            )
        except Exception:  # noqa: BLE001
            pass

    return blocks


async def _run_content_generation_outline(**kwargs) -> str:
    """Run the outline tier of the Phase 3 two-pass content pipeline.

    Phase 3.5 Subtask 28. For each (week, page) tuple derivable from the
    staging manifest + course_planning objectives, build a list of
    :class:`Block` stubs and dispatch them through
    :meth:`CourseforgeRouter.route_all` in outline-only mode (we
    pre-filter the input list here rather than widening route_all's
    signature; Worker N2's self-consistency widening is disjoint).

    Inputs (kwargs):
        project_id: Course project slug. Used to locate the project
            directory under ``Courseforge/exports/``.
        course_planning_path: Optional explicit path to
            ``synthesized_objectives.json``. Falls back to the project's
            canonical ``01_learning_objectives/synthesized_objectives.json``.
        staging_dir: Path to the per-run DART staging directory
            produced by ``stage_dart_outputs``.
        source_module_map_path: Optional path to ``source_module_map.json``
            for Wave 9 source-routing.
        duration_weeks: Optional weeks override (Wave 40 auto-scaling
            still respected via project_config.json).

    Outputs (JSON envelope):
        blocks_outline_path: Path to a JSONL file containing every
            outline-tier Block emitted across all weeks.
        project_id: Pass-through.
        weeks_prepared: Number of weeks for which at least one outline
            Block was emitted.
    """
    from Courseforge.scripts.blocks import Block, BLOCK_TYPES  # noqa: F401
    from MCP.tools import _content_gen_helpers as _cgh

    project_id = kwargs.get("project_id", "")
    if not project_id:
        return json.dumps({
            "success": False,
            "error": "_run_content_generation_outline requires project_id",
        })

    project_path = courseforge_exports_dir() / project_id
    out_dir = project_path / "01_outline"
    out_dir.mkdir(parents=True, exist_ok=True)

    # Resolve duration_weeks via project_config (mirrors _generate_course_content).
    config_path = project_path / "project_config.json"
    config: Dict[str, Any] = {}
    if config_path.exists():
        try:
            config = json.loads(config_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            config = {}
    duration_explicit = bool(kwargs.get("duration_weeks_explicit", False))
    kwarg_duration = kwargs.get("duration_weeks")
    if duration_explicit and kwarg_duration:
        duration_weeks = int(kwarg_duration)
    else:
        duration_weeks = int(
            config.get("duration_weeks") or kwarg_duration or 12
        )
    course_code = config.get("course_name") or project_id

    # Stage + objectives loading (mirrors _generate_course_content).
    staging_kwarg = kwargs.get("staging_dir")
    staging_dir = Path(staging_kwarg) if staging_kwarg else None
    html_files = _cgh.collect_staged_html(staging_dir, COURSEFORGE_INPUTS)
    topics = _cgh.parse_dart_html_files(html_files)
    objectives_path = (
        kwargs.get("course_planning_path")
        or config.get("objectives_path")
        or kwargs.get("objectives_path")
    )
    if not objectives_path:
        candidate = (
            project_path
            / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        if candidate.exists():
            objectives_path = str(candidate)
    terminal_objectives, chapter_objectives = _cgh.load_objectives_json(
        objectives_path
    )
    if not terminal_objectives and not chapter_objectives:
        terminal_objectives, chapter_objectives = (
            _cgh.synthesize_objectives_from_topics(topics, duration_weeks)
        )
    topics_by_week = _cgh._group_topics_by_week(topics, duration_weeks)

    # Decision capture for the outline phase.
    capture = None
    try:
        from lib.decision_capture import DecisionCapture
        capture = DecisionCapture(
            course_code=course_code,
            phase="courseforge-content-generator-outline",
            tool="courseforge",
            streaming=True,
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "DecisionCapture init failed in content_generation_outline: %s",
            exc,
        )
        capture = None

    # Instantiate the router. Fail loud on init errors — the operator
    # opted in via COURSEFORGE_TWO_PASS=true; silent fallback would
    # mask a misconfiguration.
    try:
        from Courseforge.router.router import CourseforgeRouter
        from Courseforge.router.policy import load_block_routing_policy
        router = CourseforgeRouter(
            capture=capture,
            policy=load_block_routing_policy(),
        )
    except Exception as exc:
        logger.exception(
            "CourseforgeRouter init failed in outline phase: %s", exc,
        )
        return json.dumps({
            "success": False,
            "error": f"router init failed: {exc}",
            "project_id": project_id,
        })

    # Build per-week per-page Block stubs. We mirror the page layout
    # ``_generate_course_content`` produces (overview / content_NN /
    # application / self_check / summary) at the Block level.
    all_blocks: List[Any] = []
    chunks_lookup: Dict[str, List[Any]] = {}
    weeks_with_blocks = 0

    from lib.ontology.slugs import canonical_slug as _slug
    from lib.semantic_structure_extractor.semantic_structure_extractor import (
        _is_noncontent_heading,
    )

    # ------------------------------------------------------------------ #
    # Grounded source-chunk resolution (keystone fix).
    # ------------------------------------------------------------------ #
    # The DART-HTML topics carry no chunk ``id`` field, so the legacy
    # ``chunks_lookup`` entries ({heading, paragraphs}) gave the outline
    # prompt + the grounding-repair helper an EMPTY chunk-id universe —
    # every block then failed the strict ``source_chunk_ids: minItems 1``
    # schema. The synthesized objectives ARE fully grounded
    # (``source_refs[].chunk_ids`` referencing the course chunkset), so we
    # resolve each block's source-chunk universe from its week's
    # objectives instead. Load the chunkset into a {chunk_id: text} map;
    # absent chunkset → fall back to the topic-paragraph behavior (warn,
    # never crash). Mirrors the course_slug + libv2_root derivation used
    # by ``_backfill_dart_chunk_lo_refs`` / the CURIE-vocab locator.
    course_slug = (course_code or project_id or "").lower().replace(
        "_", "-"
    ).replace(" ", "-")
    # DART->semantik purge Stage 3c: dual-read staged chunkset (semantik ->
    # dart -> corpus).
    from lib.libv2_storage import resolve_staged_chunks_path
    chunkset_path = resolve_staged_chunks_path(
        _resolve_libv2_root(kwargs.get("libv2_root")) / "courses" / course_slug
    )
    chunk_text_map = _load_semantik_chunkset_text_map(chunkset_path)
    chunkset_present = bool(chunk_text_map)
    if not chunkset_present:
        logger.warning(
            "outline phase: chunkset absent/empty at %s — falling back "
            "to topic-paragraph source_chunks (blocks may fail-closed on "
            "empty grounding).",
            chunkset_path,
        )

    # Feature I5 — the deterministic key-terms page (opt-in via
    # ED4ALL_KEY_TERMS_PAGE) needs the richer per-chunk detail (item_path /
    # heading / concept_tags) + the domain-concept vocabulary. Both load lazily
    # ONLY when the flag is on, so a default-off run is byte-identical.
    _key_terms_on = _key_terms_page_enabled()
    _chunk_detail_map: Dict[str, Dict[str, Any]] = {}
    _key_terms_vocab: Optional[Dict[str, Any]] = None
    _key_terms_blocks: List[Any] = []
    if _key_terms_on:
        _chunk_detail_map = _load_semantik_chunkset_detail_map(chunkset_path)
        _vocab_path = _locate_domain_concept_vocabulary(course_code, kwargs)
        if _vocab_path is not None and Path(_vocab_path).exists():
            try:
                _key_terms_vocab = json.loads(
                    Path(_vocab_path).read_text(encoding="utf-8")
                )
            except (OSError, ValueError) as _kt_exc:
                logger.warning(
                    "key_terms: could not load domain_concept_vocabulary at "
                    "%s: %s", _vocab_path, _kt_exc,
                )
                _key_terms_vocab = None

    # W6.4 — deterministic per-week FAQ page (opt-in via ED4ALL_FAQ_PAGE). Built
    # OUTSIDE the LLM block loop (grounded Q/A cards, no dispatch). Load the
    # per-chunk detail map lazily ONLY when the flag is on (reuse if key_terms
    # already loaded it), so a default-off run is byte-identical.
    _faq_on = _faq_page_enabled()
    _faq_blocks: List[Any] = []
    if _faq_on and not _chunk_detail_map:
        _chunk_detail_map = _load_semantik_chunkset_detail_map(chunkset_path)

    # ------------------------------------------------------------------ #
    # Prerequisite-DAG-driven TO sequencing (opt-in ED4ALL_PREREQ_SEQUENCING).
    # ------------------------------------------------------------------ #
    # Runs BEFORE the per-week assignment + the ceil-stride chunk-id slice so
    # both key off the post-reorder list. Strict no-op (byte-identical) when the
    # flag is off; best-effort when on — a missing/unloadable concept graph
    # keeps the WS1.1 Ward order (logged, never crashes the build).
    try:
        from lib.generation.prereq_sequencer import (
            resolve_prereq_sequencing,
            sequence_terminal_objectives,
        )
        if resolve_prereq_sequencing() and terminal_objectives:
            _cg = None
            _cg_course_dir = (
                _resolve_libv2_root(kwargs.get("libv2_root"))
                / "courses"
                / course_slug
            )
            for _cand in (
                _cg_course_dir / "graph" / "concept_graph_semantic.json",
                _cg_course_dir / "imscc_chunks" / "concept_graph_semantic.json",
                _cg_course_dir / "dart_chunks" / "concept_graph_semantic.json",
                _cg_course_dir / "corpus" / "concept_graph_semantic.json",
            ):
                if _cand.exists() and _cand.is_file():
                    try:
                        _cg = json.loads(_cand.read_text(encoding="utf-8"))
                        break
                    except (OSError, ValueError):
                        continue
            if _cg is None:
                logger.warning(
                    "prereq_sequencing on but no concept_graph_semantic.json "
                    "under %s — keeping WS1.1 Ward order.", _cg_course_dir,
                )
            else:
                terminal_objectives, _seq_signals = sequence_terminal_objectives(
                    terminal_objectives,
                    _cg,
                    capture=capture,
                    course_code=course_code,
                )
                logger.info(
                    "prereq_sequencing: reordered=%s n_reordered=%s "
                    "to_edges=%s cycles_broken=%s",
                    _seq_signals.get("reordered"),
                    _seq_signals.get("n_reordered"),
                    _seq_signals.get("to_edges_used"),
                    _seq_signals.get("cycles_broken"),
                )
                # Persist the post-sequencing TO order to a sidecar so the
                # inter_tier_validation prereq gate audits the EMITTED order
                # (not the pre-reorder Ward order on synthesized_objectives.json,
                # which this phase deliberately does NOT rewrite). The gate's
                # input builder prefers this sidecar. Best-effort: a write error
                # never breaks the build (the gate falls back to the planning
                # artifact). The sidecar lands next to synthesized_objectives.json
                # so the gate's _resolve_objectives_path locates it.
                try:
                    _seq_dir = (
                        Path(objectives_path).parent
                        if objectives_path
                        else (project_path / "01_learning_objectives")
                    )
                    _seq_dir.mkdir(parents=True, exist_ok=True)
                    (_seq_dir / "synthesized_objectives.sequenced.json").write_text(
                        json.dumps(
                            {"terminal_objectives": terminal_objectives},
                            ensure_ascii=False,
                            indent=2,
                        ),
                        encoding="utf-8",
                    )
                except (OSError, TypeError, ValueError) as _seq_write_exc:
                    logger.warning(
                        "prereq_sequencing: failed to persist sequenced TO "
                        "sidecar: %s", _seq_write_exc,
                    )
    except Exception as _seq_exc:  # noqa: BLE001 — never break the build
        logger.warning("prereq_sequencing hook failed: %s", _seq_exc)

    # Build the per-week objective -> chunk_ids index. Terminal-objective
    # chunk_ids are gathered per-week inside the loop below (the terminal
    # slice is week-scoped there); chapter objectives are grouped by their
    # ``chapter`` label / position here. We pre-collect terminal chunk_ids
    # first so the index folds both signals.
    week_terminal_chunk_ids: Dict[int, List[str]] = {}
    # Finding 11: round-robin / ceil-stride assignment guarantees every week
    # (incl. trailing weeks when num_tos < duration_weeks) maps to a TO so no
    # week ships an empty OBJECTIVES block. Always bound (empty when no TOs).
    # NOTE: this drives only the per-week objective-ID assignment below — the
    # terminal CHUNK-ID index keeps the legacy ceil-stride slice so a wrapped
    # (reused) TO does NOT pollute a trailing week's chunk-grounding universe.
    _week_to_assignment: Dict[int, List[Dict[str, Any]]] = (
        _assign_terminal_objectives_to_weeks(
            terminal_objectives, duration_weeks
        )
    )
    if terminal_objectives:
        _t_step = max(
            1,
            (len(terminal_objectives) + duration_weeks - 1) // duration_weeks,
        )
        for _wn in range(1, duration_weeks + 1):
            _start = (_wn - 1) * _t_step
            _bucket: List[str] = []
            for _obj in terminal_objectives[_start:_start + _t_step]:
                if not isinstance(_obj, dict):
                    continue
                for _ref in _obj.get("source_refs") or []:
                    if isinstance(_ref, dict):
                        for _cid in _ref.get("chunk_ids") or []:
                            if isinstance(_cid, str) and _cid:
                                _bucket.append(_cid)
            if _bucket:
                week_terminal_chunk_ids[_wn] = _bucket
    # The flattened ``chapter_objectives`` from ``load_objectives_json``
    # strips the per-group week label, so the week→chunk_ids index MUST be
    # rebuilt from the RAW grouped ``synthesized_objectives.json`` on disk
    # (the same ``objectives_path`` already resolved above). Normalize
    # whatever shape we find (list-of-groups / flat / dict-of-lists) to
    # the canonical grouped form before resolving week numbers. Absent /
    # unreadable file → empty groups → topic-paragraph fallback downstream.
    chapter_objective_groups: List[Dict[str, Any]] = []
    if objectives_path:
        try:
            _raw_obj_doc = json.loads(
                Path(objectives_path).read_text(encoding="utf-8")
            )
            chapter_objective_groups = _normalize_chapter_objectives_to_groups(
                _raw_obj_doc.get("chapter_objectives", []) or []
            )
        except (OSError, ValueError, TypeError) as exc:
            logger.warning(
                "outline phase: could not load grouped chapter_objectives "
                "from %s (%s) — week chunk-id index will rely on terminal "
                "objectives only.",
                objectives_path, exc,
            )
            chapter_objective_groups = []
    # WEEK_TO_GROUPS re-derivation (coverage-gap fix): the persisted
    # ``chapter_objectives`` grouping carries the week slicing of the RUN THAT
    # MINTED THE DOC — a ``--reuse-objectives`` pin (or a stale export re-run
    # via the ``courseforge-outline`` stage subcommand) can carry an OLD
    # ceil-stride "Week N" slicing even though the CURRENT env asks for
    # TO-membership weeks. Never let the on-disk grouping silently win: when
    # ED4ALL_WEEK_TO_GROUPS is on, rebuild the groups live from the SAME
    # single-source helper the persist + emit paths use (``_week_co_groups``
    # over the doc's flat COs + terminal objectives; deterministic, so a
    # fresh flag-on doc re-derives to its own identical groups). Default off →
    # the on-disk grouping is consumed verbatim (byte-identical legacy path).
    if chapter_objective_groups and resolve_week_to_groups():
        _flat_group_cos: List[Dict[str, Any]] = []
        for _grp in chapter_objective_groups:
            if not isinstance(_grp, dict):
                continue
            for _obj in _grp.get("objectives") or []:
                if isinstance(_obj, dict):
                    _flat_group_cos.append(_obj)
        if _flat_group_cos and duration_weeks >= 1:
            _live_week_groups = _week_co_groups(
                _flat_group_cos, terminal_objectives, duration_weeks,
            )
            chapter_objective_groups = [
                {
                    "chapter": f"Week {_wn}",
                    "objectives": list(_live_week_groups.get(_wn, [])),
                }
                for _wn in range(1, duration_weeks + 1)
            ]
            logger.info(
                "outline phase: ED4ALL_WEEK_TO_GROUPS on — re-derived the "
                "per-week CO groups live (%d CO(s) across %d week(s)) from "
                "the doc's terminal objectives; the persisted "
                "chapter_objectives grouping is not trusted for week "
                "membership.",
                len(_flat_group_cos), duration_weeks,
            )
    week_chunk_id_index = _build_week_chunk_id_index(
        chapter_objective_groups,
        week_terminal_chunk_ids=week_terminal_chunk_ids,
    )
    # Page-per-CO content-emit gate. Default OFF → every index builder is called
    # with its legacy (unclamped, ``require_id`` off) signature so the emitted
    # descriptors are byte-identical. ON → clamp CO-group weeks into
    # ``[1, duration_weeks]`` (review fix 2) AND make the two per-CO index
    # builders predicate-identical so the i-th chunk slice aligns with the i-th
    # CO objective.
    _page_per_co = _content_page_per_co_enabled()
    _idx_duration = duration_weeks if _page_per_co else None
    # Gap #11 — per-block-role chunk-order diversification. Resolved ONCE here
    # (env read hoisted out of the per-block loop). Default OFF → the per-block
    # chunk order below is byte-identical (every co-located block leads with the
    # identical page-ranked head chunk). When ON, each block's offered chunk
    # order is rotated by a stable per-role offset so co-located blocks of
    # different roles do not all draw their anchor example from the same chunk.
    from lib.generation.content_page_budget import (  # noqa: PLC0415
        chunk_role_diversify_enabled as _chunk_role_diversify_enabled,
        diversify_block_chunk_order as _diversify_block_chunk_order,
    )
    _chunk_role_diversify = _chunk_role_diversify_enabled()
    # Fix 2A (Step 2b): per-week per-CO chunk universe (parallel to the
    # week-wide union above) so each page can be NARROWED to a single
    # objective's chunks instead of the whole-week grab-bag.
    week_co_chunk_index = _build_week_co_chunk_index(
        chapter_objective_groups,
        duration_weeks=_idx_duration,
        require_id=_page_per_co,
    )
    # Wave-2 Part 3 (keystone): per-week child chapter objectives for the
    # dynamic block planner.
    week_co_objectives_index = _build_week_co_objectives_index(
        chapter_objective_groups,
        duration_weeks=_idx_duration,
    )
    # Review fix 2 (defense-in-depth): the two per-CO indexes MUST be
    # positionally aligned per week (chunk slice i ↔ objective i). On the
    # page-per-CO path, assert per-week length equality; on any mismatch, fall
    # back to the OFF behaviour for the whole run (disable the CO-count driver)
    # so a misaligned bind can never strand a CO under a wrong objective_id.
    if _page_per_co:
        _aligned = True
        for _wn in set(week_co_chunk_index) | set(week_co_objectives_index):
            if len(week_co_chunk_index.get(_wn, [])) != len(
                week_co_objectives_index.get(_wn, [])
            ):
                _aligned = False
                logger.warning(
                    "page-per-co: week %d per-CO index length mismatch "
                    "(chunk_slices=%d, objectives=%d) — disabling the CO-count "
                    "page driver for this run (falling back to topic-count).",
                    _wn,
                    len(week_co_chunk_index.get(_wn, [])),
                    len(week_co_objectives_index.get(_wn, [])),
                )
                break
        if not _aligned:
            _page_per_co = False
    # CO-id fan-out fix: the course-wide valid CHAPTER-objective id set. A
    # planned block's ``target_co_ids`` is filtered against this before it can
    # override the week-TO ``objective_ids`` (anti-fabrication — a hallucinated
    # CO id can never be stamped). Sourced from the flat ``chapter_objectives``
    # loaded by ``load_objectives_json`` (TERMINAL ids are intentionally
    # EXCLUDED — a block targeting only TOs falls through to the week fallback).
    _valid_co_ids: Set[str] = {
        str(o.get("id")) for o in chapter_objectives if o.get("id")
    }

    # Per-run resolution counters for the summary decision capture.
    n_blocks_resolved_from_objectives = 0
    n_blocks_fallback_to_topic = 0
    total_resolved_chunk_ids = 0
    # Fix 2A: per-run objective-scoping counters (page-level narrowing).
    _OBJ_SCOPE_MIN_CHUNKS = 2  # floor below which a page reverts to week-wide
    n_pages_objective_scoped = 0
    n_pages_week_fallback = 0

    # Page-per-CO: per-run counters + the token budget for the per-page chunk
    # cap. The budget is computed ONCE (the system-prompt lengths are measured
    # DYNAMICALLY at import so a prompt edit cannot silently invalidate it).
    # All zero/None on the OFF path → no behavioural effect.
    _ppc_emitted_co_ids: Set[str] = set()
    _ppc_pages_emitted = 0
    _ppc_chunks_kept = 0
    _ppc_chunks_dropped = 0
    _ppc_dropped_cited = 0
    _ppc_token_budget: Optional[int] = None
    _ppc_num_ctx: Optional[int] = None
    _ppc_max_chunks: Optional[int] = None
    if _page_per_co:
        from lib.generation.content_page_budget import (  # noqa: PLC0415
            resolve_content_page_num_ctx,
            resolve_content_page_max_chunks,
            _estimate_tokens as _ppc_estimate_tokens,
            page_chunk_token_budget,
        )

        _ppc_num_ctx = resolve_content_page_num_ctx()
        _ppc_max_chunks = resolve_content_page_max_chunks()
        # Measure the heavier rewrite-tier system prompt DYNAMICALLY (the
        # authoring lane that actually overflows). A failed import → fall back
        # to a conservative fixed estimate so the budget still bounds the page.
        _sys_tokens = 8000
        try:
            from Courseforge.generators._rewrite_provider import (  # noqa: PLC0415
                _REWRITE_SYSTEM_PROMPT,
            )

            _sys_tokens = _ppc_estimate_tokens(_REWRITE_SYSTEM_PROMPT)
        except Exception:  # noqa: BLE001 — keep the conservative default
            pass
        # user_fixed + max_tokens reserves: the rewrite user-prompt scaffold +
        # the 2,400-token output reservation (per the plan's measured budget).
        _ppc_token_budget = page_chunk_token_budget(
            num_ctx=_ppc_num_ctx,
            system_prompt_tokens=_sys_tokens,
            user_fixed_tokens=1200,
            max_tokens=2400,
        )
        logger.info(
            "page-per-co: num_ctx=%d rewrite_sys≈%d tok → per-page chunk "
            "token_budget=%d (max_chunks=%d).",
            _ppc_num_ctx, _sys_tokens, _ppc_token_budget, _ppc_max_chunks,
        )

    # Wave-2 Part 3 (keystone): the 70B content-aware block planner. Default
    # OFF → ``dynamic_block_plan`` stays False and every page consumes the
    # fixed ``_PAGE_TYPE_BLOCK_PLAN`` (byte-identical legacy behaviour). ON →
    # a per-TO planner chooses each week's block sequence from the catalog.
    # The provider is built ONCE (lazy hosted large-model seat); a None provider
    # (missing key / construction error) degrades each week to the fixed
    # plan inside ``plan_week_blocks`` itself.
    dynamic_block_plan = _dynamic_block_plan_enabled()
    block_planner_provider = None
    n_weeks_planner_used = 0
    n_weeks_planner_fallback = 0
    # W6.1 — cross-week cumulative retrieval. The per-TO planner is stateless, so
    # a CO taught earlier is never re-retrieved later. Accumulate the CO ids seen
    # in PRIOR weeks and, when ED4ALL_PLANNER_CROSS_WEEK_RETRIEVAL is on, schedule
    # expanding-interval cumulative-retrieval blocks over them into each week's
    # plan (only on the dynamic-planner path, where a WeekBlockPlan exists). Ships
    # dark: OFF → the accumulator is inert and every plan is byte-identical.
    _cross_week_on = _cross_week_retrieval_enabled()
    _prior_week_co_ids: List[str] = []
    _n_cross_week_blocks = 0
    # IB7.1 — thread the source-chunk HEADING into the planner digest. The
    # text-only ``chunk_text_map`` starves the planner prompt's ``[{heading}] ``
    # prefix + the content-shape detectors of the structural heading signal.
    # Load the richer per-chunk detail map (``{text, item_path, heading,
    # concept_tags}``) ONLY when the planner runs, so a non-dynamic run is
    # byte-identical (the detail map is otherwise loaded only under the
    # key-terms flag). Reuse ``_chunk_detail_map`` if the key-terms flag already
    # populated it.
    _planner_detail_map: Dict[str, Dict[str, Any]] = {}
    # Dynamic block-planner per-week resume sidecar (P4 item 4 / D5). Lives in
    # the outline OUTPUT dir alongside the per-block outline sidecar; loaded once
    # so a resumed run reuses already-planned weeks instead of re-dispatching the
    # per-week 70B plan call. Inert (empty cache, no writes) when the planner is
    # off or the family flag is disabled.
    _planner_checkpoint_path = out_dir / _BLOCK_PLANNER_CHECKPOINT_NAME
    _planner_store = _block_planner_store(_planner_checkpoint_path)
    _planner_cache = _planner_store.load()
    _planner_model = ""
    if dynamic_block_plan:
        block_planner_provider = _build_block_planner_provider(capture=capture)
        _planner_model = str(
            getattr(block_planner_provider, "_model", "")
            or getattr(block_planner_provider, "model", "")
            or os.environ.get("ED4ALL_DYNAMIC_BLOCK_PLAN_MODEL", "")
            or ""
        )
        _planner_detail_map = (
            _chunk_detail_map
            if _chunk_detail_map
            else _load_semantik_chunkset_detail_map(chunkset_path)
        )

    # ------------------------------------------------------------------ #
    # Per-week planner input builder (shared by the parallel warm-up pass
    # and the sequential loop below).
    # ------------------------------------------------------------------ #
    # The per-week planner inputs (``_week_to`` / child COs / grounded source
    # chunks) + the resume fingerprint are computed by IDENTICAL code in both
    # the warm-up pre-pass and the loop, so the warm-up's fingerprint can NEVER
    # drift from the loop's ``_planner_store.reuse(...)`` fingerprint (a drift
    # would miss the cache and double-dispatch every week). Closes over the
    # pre-built per-week indices; pure (no side effects).
    def _build_week_planner_inputs(
        _wn: int,
        _wk_objectives: List[Dict[str, Any]],
        _wk_objective_ids: Tuple[str, ...],
    ):  # type: ignore[no-untyped-def]
        from lib.generation.block_planner import (  # noqa: PLC0415
            DEFAULT_BLOCK_BUDGET,
        )

        _wk_to = (
            _wk_objectives[0]
            if _wk_objectives
            else {"id": (_wk_objective_ids[0] if _wk_objective_ids else ""),
                  "statement": ""}
        )
        _wk_cos = week_co_objectives_index.get(_wn, [])
        _wk_cids = week_chunk_id_index.get(_wn, [])
        _wk_chunks: List[Dict[str, str]] = []
        if chunkset_present:
            for _cid in _wk_cids:
                _body = chunk_text_map.get(_cid)
                if _body:
                    _heading = str(
                        (_planner_detail_map.get(_cid) or {}).get("heading")
                        or ""
                    )
                    _wk_chunks.append({"id": _cid, "text": _body,
                                       "heading": _heading})
        _wk_key = _block_planner_week_key(_wn)
        _wk_fp = _block_planner_week_fingerprint(
            week_num=_wn,
            terminal_objective=_wk_to,
            chapter_objectives=_wk_cos,
            source_chunks=_wk_chunks,
            model=_planner_model,
            budget=DEFAULT_BLOCK_BUDGET,
            course_code=course_code,
        )
        return _wk_key, _wk_fp, _wk_to, _wk_cos, _wk_chunks

    def _week_objectives_for(_wn: int):  # type: ignore[no-untyped-def]
        """Per-week (objectives, objective_ids) — the loop's 16052-16062 logic."""
        _objs = (
            list(_week_to_assignment.get(_wn, [])) if terminal_objectives else []
        )
        _oids: Tuple[str, ...] = tuple(
            str(o.get("id")) for o in _objs if o.get("id")
        )
        return _objs, _oids

    # ------------------------------------------------------------------ #
    # Parallel warm-up pre-pass (ED4ALL_DYNAMIC_BLOCK_PLAN on only).
    # ------------------------------------------------------------------ #
    # The per-week ``plan_week_blocks`` dispatches are INDEPENDENT (each depends
    # only on per-week inputs derived from the pre-built indices — no
    # loop-carried state), so instead of serializing ~15-20 min of Super-120B
    # calls one-at-a-time against a ~95%-idle seat, fan them across a bounded
    # thread pool HERE and write each result into the SAME ``_planner_store``
    # sidecar the loop reads. The loop below stays byte-identical: every week
    # now HITS ``_planner_store.reuse(...)`` and skips the inline dispatch,
    # while still running weeks 1..N sequentially (unchanged output order). OFF
    # path (dynamic_block_plan False) OR resolved concurrency <= 1 builds NO
    # pool and is byte-identical to the legacy sequential loop.
    _block_plan_concurrency = _resolve_block_plan_concurrency()
    if dynamic_block_plan and _block_plan_concurrency > 1:
        # Build each week's inputs + fingerprint; only weeks NOT already
        # checkpointed (fingerprint match from a prior interrupted run) need a
        # dispatch — an already-warmed week is skipped (no double dispatch).
        _warm_specs: List[Tuple[int, str, str, Dict[str, Any],
                                List[Dict[str, Any]], List[Dict[str, str]]]] = []
        for _wn in range(1, duration_weeks + 1):
            _w_objs, _w_oids = _week_objectives_for(_wn)
            (_w_key, _w_fp, _w_to, _w_cos,
             _w_chunks) = _build_week_planner_inputs(_wn, _w_objs, _w_oids)
            if _planner_store.reuse(
                _w_key, _w_fp, cache=_planner_cache,
            ) is not None:
                continue
            _warm_specs.append(
                (_wn, _w_key, _w_fp, _w_to, _w_cos, _w_chunks)
            )

        if _warm_specs:
            from concurrent.futures import ThreadPoolExecutor  # noqa: PLC0415
            from lib.generation.block_planner import (  # noqa: PLC0415
                plan_week_blocks as _warm_plan_week_blocks,
            )

            _warm_pool_size = min(
                _block_plan_concurrency, len(_warm_specs)
            ) or 1

            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="content_selection",
                        decision=(
                            f"Block-planner warm-up: dispatching "
                            f"{len(_warm_specs)} week plan(s) across a "
                            f"{_warm_pool_size}-thread pool before the "
                            f"sequential loop."
                        ),
                        rationale=(
                            f"COURSEFORGE_BLOCK_PLAN_CONCURRENCY resolved to "
                            f"{_block_plan_concurrency} (pool sized to "
                            f"min(knob, uncached_weeks)={_warm_pool_size}) fans "
                            f"the INDEPENDENT per-week Super-120B "
                            f"plan_week_blocks dispatch out across threads and "
                            f"warms the same {_BLOCK_PLANNER_CHECKPOINT_NAME} "
                            f"sidecar the loop reuses, so the loop makes ZERO "
                            f"inline planner calls and its output order is "
                            f"unchanged (weeks 1..{duration_weeks} still "
                            f"consumed sequentially)."
                        ),
                        ml_features={
                            "gate_id": "_run_content_generation_outline",
                            "block_plan_concurrency": _block_plan_concurrency,
                            "pool_size": _warm_pool_size,
                            "warm_weeks": len(_warm_specs),
                            "duration_weeks": duration_weeks,
                        },
                    )
                except Exception:  # noqa: BLE001 — best-effort capture
                    pass

            # Graceful stop: a pre-armed sentinel refuses the whole warm-up
            # before any future is submitted (ZERO planner dispatches). Mirrors
            # the outline-tier P3.0 pre-dispatch guard.
            check_stop("block_planner_weeks", 0)

            def _warm_one_week(_spec):  # type: ignore[no-untyped-def]
                """Dispatch ONE week's plan (fail-soft; returns STOP_MARKER when
                a mid-pool stop is armed pre-dispatch, so a not-yet-started
                worker RETURNS rather than raises — the P3.0 drain discipline)."""
                (_s_wn, _s_key, _s_fp, _s_to, _s_cos, _s_chunks) = _spec
                if stop_requested():
                    return STOP_MARKER
                try:
                    _plan = _warm_plan_week_blocks(
                        terminal_objective=_s_to,
                        chapter_objectives=_s_cos,
                        source_chunks=_s_chunks,
                        provider=block_planner_provider,
                        capture=capture,
                        course_code=course_code,
                    )
                except Exception as _warm_exc:  # noqa: BLE001
                    # plan_week_blocks fail-softs internally, but guard anyway:
                    # a worker failure must not kill the pool. Skip appending —
                    # the sequential loop then inline-dispatches this one week
                    # (correct fallback, no double-dispatch for the rest).
                    logger.warning(
                        "block-planner warm-up: week %d dispatch failed (%s); "
                        "the sequential loop will re-dispatch this week.",
                        _s_wn, _warm_exc,
                    )
                    return None
                return (_s_key, _s_fp, _plan)

            with ThreadPoolExecutor(max_workers=_warm_pool_size) as _warm_pool:
                _warm_futs = [
                    _warm_pool.submit(_warm_one_week, _spec)
                    for _spec in _warm_specs
                ]
                for _wf in _warm_futs:
                    try:
                        _wf_result = _wf.result()
                    except Exception as _wf_exc:  # noqa: BLE001
                        logger.warning(
                            "block-planner warm-up: worker raised: %s", _wf_exc,
                        )
                        continue
                    if _wf_result is STOP_MARKER or _wf_result is None:
                        # Stop-armed pre-dispatch (re-run on resume) or a
                        # fail-soft skip; neither appends.
                        continue
                    _w_key, _w_fp, _w_plan = _wf_result
                    _planner_store.append(
                        _w_key, _w_fp, _serialize_week_block_plan(_w_plan),
                    )
            # Reload so the loop's reuse(...) sees the freshly-warmed entries.
            # A mid-pool stop leaves the sentinel armed; the loop-top
            # ``check_stop("block_planner_weeks", ...)`` on week 1 raises
            # GracefulStopRequested (every warmed week is already checkpointed,
            # so nothing computed is lost).
            _planner_cache = _planner_store.load()

    for week_num in range(1, duration_weeks + 1):
        # Graceful stop (checkpoint on command): raise at the week-loop unit
        # boundary. Every prior week's block plan was appended to the planner
        # sidecar (or served from the resume cache), so a stop here loses at
        # most the in-flight week's plan. A pre-armed sentinel raises on week 1
        # (zero planner dispatches). Sequential loop → plain check_stop (no
        # STOP_MARKER; the P3.0 gather-marker pattern does not bind here).
        check_stop("block_planner_weeks", week_num - 1)
        week_topics = (
            topics_by_week[week_num - 1]
            if (week_num - 1) < len(topics_by_week)
            else []
        )
        # Secondary fix: drop topics whose heading is non-content noise
        # (donor-name / answer-key / front-matter) so they don't become
        # block IDs carrying junk like
        # ``...#objective_charles-koch-foundation_0``. The filter runs on
        # the topic's raw ``heading`` (the same text that seeds ``slug_value``
        # below), which is the correct field/stage.
        #
        # All-filtered fallback: when EVERY topic in a week is non-content
        # noise (e.g. week 1 of a textbook corpus, whose only topic is the
        # donor-acknowledgments h3), DON'T re-admit the noise verbatim —
        # that re-seeds the donor name into the block_id slug, which is the
        # exact leak observed in the live run. Instead empty the topic list
        # so the week falls through to the ``page_count = max(0, 1) = 1``
        # minimum below and emits ONE block with a neutral ``week_NN``
        # heading. The week never silently loses all its blocks (grounding
        # still comes from the week's objectives), and no donor/answer-key
        # name ever becomes a block id.
        if week_topics:
            week_topics = [
                t for t in week_topics
                if not _is_noncontent_heading((t or {}).get("heading"))
            ]
        week_objectives = []
        if terminal_objectives:
            # Finding 11: use the round-robin / ceil-stride assignment so a
            # trailing week (num_tos < duration_weeks) still gets a valid TO
            # instead of slicing the empty tail (empty objectives block).
            week_objectives = list(
                _week_to_assignment.get(week_num, [])
            )
        objective_ids: Tuple[str, ...] = tuple(
            str(o.get("id")) for o in week_objectives if o.get("id")
        )

        # ---------------------------------------------------------------- #
        # Wave-2 Part 3 (keystone): per-TO content-aware block planning.
        # ---------------------------------------------------------------- #
        # When ED4ALL_DYNAMIC_BLOCK_PLAN is on, ask the 70B (once per week /
        # TO) to choose the block sequence that best teaches THIS TO's
        # content. The returned ``WeekBlockPlan`` exposes
        # ``page_block_plan_for(page_type)`` with the SAME shape as the fixed
        # ``_page_block_plan_for`` — so the page-descriptor assembly below is
        # unchanged; only WHICH blocks land on each page differs. A None
        # provider / LLM error / unparseable response degrades inside
        # ``plan_week_blocks`` to the fixed ``_PAGE_TYPE_BLOCK_PLAN``, so the
        # build is never broken. ``week_block_plan`` stays None on the OFF
        # path, and the consumer below falls through to ``_page_block_plan_for``
        # (byte-identical legacy behaviour).
        week_block_plan = None
        if dynamic_block_plan:
            from lib.generation.block_planner import plan_week_blocks

            # Per-week planner inputs + resume fingerprint. Built by the SAME
            # helper the parallel warm-up pre-pass uses, so the fingerprint here
            # is byte-identical to the warm-up's — every warmed week HITS the
            # reuse(...) below and skips the inline dispatch. IB7.1 heading
            # signal + grounded source-chunk digest live inside the helper.
            # Resume sidecar: reuse a prior week's plan when its fingerprint
            # matches (skips the per-week 70B ``plan_week_blocks`` dispatch);
            # a mismatch / miss re-plans + checkpoints. The deterministic
            # cross-week merge below always re-runs, so a reused RAW plan stays
            # byte-equivalent. A GracefulStopRequested cannot originate here
            # (``plan_week_blocks`` never raises — it fail-softs to the fixed
            # plan), so the pause boundary is the loop-top check_stop above.
            (_planner_key, _planner_fp, _week_to, _week_cos,
             _week_chunks) = _build_week_planner_inputs(
                week_num, week_objectives, objective_ids,
            )
            _planner_reused = _planner_store.reuse(
                _planner_key, _planner_fp, cache=_planner_cache,
            )
            if _planner_reused is not None:
                week_block_plan = _deserialize_week_block_plan(_planner_reused)
            else:
                week_block_plan = plan_week_blocks(
                    terminal_objective=_week_to,
                    chapter_objectives=_week_cos,
                    source_chunks=_week_chunks,
                    provider=block_planner_provider,
                    capture=capture,
                    course_code=course_code,
                )
                _planner_store.append(
                    _planner_key, _planner_fp,
                    _serialize_week_block_plan(week_block_plan),
                )
            if week_block_plan.fallback_used:
                n_weeks_planner_fallback += 1
            else:
                n_weeks_planner_used += 1

            # W6.1 — merge cumulative cross-week retrieval blocks (over PRIOR
            # weeks' COs) into this week's plan. No-op / byte-identical when
            # ED4ALL_PLANNER_CROSS_WEEK_RETRIEVAL is off (the helper returns []).
            # Anti-fabrication: only the real prior-week CO ids accumulated so
            # far are targeted. The blocks carry page_type='self_check' so they
            # land on the week's cumulative-check page; page_plan is re-derived so
            # ``page_block_plan_for`` surfaces them.
            if _cross_week_on and _prior_week_co_ids:
                try:
                    from lib.generation.block_planner import (
                        build_cross_week_retrieval_blocks,
                        _resolve_block_types,
                        _to_page_plan,
                    )

                    _xw_blocks = build_cross_week_retrieval_blocks(
                        prior_week_co_ids=_prior_week_co_ids,
                        week_index=week_num,
                        block_types=_resolve_block_types(),
                        enabled=True,
                    )
                    if _xw_blocks:
                        week_block_plan.selected.extend(_xw_blocks)
                        week_block_plan.page_plan = _to_page_plan(
                            week_block_plan.selected
                        )
                        _n_cross_week_blocks += len(_xw_blocks)
                except Exception as _xw_exc:  # noqa: BLE001 — never break build
                    logger.warning(
                        "cross-week retrieval: week %d merge failed (%s); "
                        "skipping", week_num, _xw_exc,
                    )

        # W6.1 — accumulate THIS week's CO ids for later weeks' cumulative
        # retrieval (the prior-week CO pool). De-duplicated, order-preserving;
        # inert when the flag is off (only the merge above consumes it). Prefer
        # the week's chapter objectives (COs); fall back to the assigned terminal
        # objectives when no CO index entry exists for the week.
        _this_week_objs = (
            week_co_objectives_index.get(week_num, []) or week_objectives
        )
        for _obj in _this_week_objs:
            _oid = str(_obj.get("id") or "")
            if _oid and _oid not in _prior_week_co_ids:
                _prior_week_co_ids.append(_oid)

        # P3: FIVE page TYPES per week. Build the per-week page descriptors
        # in canonical order (overview, content_01..content_NN,
        # application, self_check, summary). ``content`` expands to one page
        # per topic (the chunking-dense, objective-scoped type); the other
        # four are emitted exactly once per week and grounded on the
        # week-wide chunk union. Each descriptor is
        # ``(page_type, content_idx, topic_or_None)``; ``content_idx`` is the
        # 1-based topic index for content pages (else 1).
        topic_count = len(week_topics)
        # Page-per-CO driver. OFF → ``max(topic_count, 1)`` verbatim (the
        # content-page count tracks parsed sections, O(sections)). ON → drive
        # the content-page count from the week's CO count (the bounded axis):
        # one content page per child CO, with a NEVER-INCREASE guard so a
        # CO-rich / topic-thin week can never emit MORE pages than today.
        _week_co_count = len(week_co_chunk_index.get(week_num, []))
        # Coverage-gap fix: the week's resolved content-page count, kept for
        # the slice-based page↔CO binding below (``_page_co_slice_bounds``).
        _week_n_content = 0
        page_descriptors: List[Tuple[str, int, Optional[Dict[str, Any]]]] = []
        for _ptype in _WEEK_PAGE_TYPES:
            if _ptype == "content":
                # OFF → ``max(topic_count, 1)`` verbatim (byte-identical). ON →
                # one content page per CO with the never-increase guard.
                _n_content = _resolve_content_page_count(
                    topic_count=topic_count,
                    co_count=_week_co_count,
                    page_per_co=_page_per_co,
                )
                _week_n_content = _n_content
                for _ci in range(_n_content):
                    _topic = week_topics[_ci] if _ci < topic_count else None
                    page_descriptors.append(("content", _ci + 1, _topic))
            else:
                page_descriptors.append((_ptype, 1, None))

        week_block_added = False
        for page_type, content_idx, topic in page_descriptors:
            # ``i`` is the positional index used for the per-CO objective-
            # scope mapping below. Only ``content`` pages carry a meaningful
            # topic→CO position (content_01 → the week's 1st CO, etc.); the
            # four singleton page types use the week-wide union (i = -1 keeps
            # them out of the per-CO slice path).
            i = (content_idx - 1) if page_type == "content" else -1
            # Page-per-CO: the content page at position ``i`` is bound to a
            # CONTIGUOUS book-order SLICE of the week's COs
            # (``_page_co_slice_bounds`` — the index builders are
            # predicate-identical, so ``week_co_objectives_index[lo:hi]`` is
            # exactly the CO run whose chunk slices ground this page). When the
            # week's page count equals its CO count the slice is a single CO —
            # byte-identical to the historical 1:1 binding. When the
            # NEVER-INCREASE page cap resolved FEWER pages than COs, the
            # trailing COs are distributed across the pages instead of
            # silently stranded (the 193/604 coverage-gap defect). Every
            # block of the page stamps the slice's CO ids (instead of falling
            # back to the week TO), which is what makes the CO→page map
            # zero-stranded: every CO lands on exactly one page.
            _page_bound_co_id: Optional[str] = None
            _page_bound_co_statement: str = ""
            _page_bound_co_ids: Tuple[str, ...] = ()
            _page_co_lo = _page_co_hi = 0
            if _page_per_co and page_type == "content":
                _wk_objs_bind = week_co_objectives_index.get(week_num, [])
                _page_co_lo, _page_co_hi = _page_co_slice_bounds(
                    page_idx=i,
                    n_pages=_week_n_content,
                    co_count=len(_wk_objs_bind),
                )
                _page_bound_co_ids = tuple(
                    _cid_bind
                    for _o in _wk_objs_bind[_page_co_lo:_page_co_hi]
                    if (_cid_bind := str(_o.get("id") or "")) in _valid_co_ids
                )
                if _page_bound_co_ids:
                    _page_bound_co_id = _page_bound_co_ids[0]
                    for _o in _wk_objs_bind[_page_co_lo:_page_co_hi]:
                        if str(_o.get("id") or "") == _page_bound_co_id:
                            _page_bound_co_statement = str(
                                _o.get("statement") or ""
                            ).strip()
                            break
            # Under page-per-CO a content page is bound 1:1 to a CO, so derive
            # its heading + slug from the BOUND CO's statement rather than the
            # positional ``topic.heading``, which routinely belongs to an
            # unrelated section. Single-sourced via
            # ``_content_page_heading_slug``; non-page-per-CO (and any content
            # page with no resolvable bound CO) keeps the topic-heading path.
            heading, slug_value = _content_page_heading_slug(
                page_bound_co_id=_page_bound_co_id,
                page_bound_co_statement=_page_bound_co_statement,
                topic=topic,
                page_type=page_type,
                week_num=week_num,
                slug_fn=_slug,
            )
            page_id = _page_id_for(week_num, page_type, content_idx)
            page_key_terms = tuple((topic or {}).get("key_terms") or [])

            # ---------------------------------------------------------- #
            # Fix 2A (improvement-map Step 2b): narrow the page's offered
            # chunk universe from week-wide to OBJECTIVE-scoped.
            # ---------------------------------------------------------- #
            # The week-wide ``week_chunk_id_index`` is the UNION of every
            # CO's chunks in the week — a "semantic grab-bag" that lets a
            # block authored for one objective cite chunks from an unrelated
            # topic on the same week. We NARROW each page to a single
            # objective's chunks via POSITIONAL page→CO mapping (page ``i``
            # → the week's ``i``-th CO), which is deterministic and needs no
            # fuzzy topic↔objective match. Both prior 1A/1B passes prune each
            # CO's chunk set upstream, so the per-CO slice we narrow to is
            # already clean.
            #
            # GRACEFUL FALLBACK (mandatory): if the per-CO slice is empty or
            # below ``_OBJ_SCOPE_MIN_CHUNKS`` (no CO at this page index, or a
            # CO grounded by < floor chunks), REVERT this page to the
            # week-wide union so a block is never starved of grounding (which
            # would regress the keystone source-chunk fix). ANTI-FABRICATION:
            # the per-CO slice is always a SUBSET of the week union (built
            # from the same ``source_refs[].chunk_ids``), so this only ever
            # NARROWS real chunk sets — it never invents an id.
            _week_union_cids = week_chunk_id_index.get(week_num, [])
            _co_slices = week_co_chunk_index.get(week_num, [])
            # Only ``content`` pages (i >= 0) map positionally to a CO; the
            # four singleton page types (overview/application/self_check/
            # summary, i == -1) always use the week-wide union. Page-per-CO
            # slice binding (coverage-gap fix): a page bound to a multi-CO
            # slice grounds on the ordered dedup UNION of its slice's per-CO
            # chunk lists (still a strict subset of the week union — no id
            # invented). A single-CO slice reduces to exactly the legacy
            # ``_co_slices[i]`` (the inner lists are already deduped).
            if _page_per_co and page_type == "content" and _page_bound_co_ids:
                _page_scoped_cids = []
                _scoped_seen: Set[str] = set()
                for _sl in _co_slices[_page_co_lo:_page_co_hi]:
                    for _sc_cid in _sl:
                        if _sc_cid not in _scoped_seen:
                            _scoped_seen.add(_sc_cid)
                            _page_scoped_cids.append(_sc_cid)
            else:
                _page_scoped_cids = (
                    _co_slices[i] if 0 <= i < len(_co_slices) else []
                )
            _page_objective_scoped = (
                len(_page_scoped_cids) >= _OBJ_SCOPE_MIN_CHUNKS
            )
            if _page_objective_scoped:
                page_chunk_cids = _page_scoped_cids
                n_pages_objective_scoped += 1
            else:
                page_chunk_cids = _week_union_cids
                n_pages_week_fallback += 1
                if _co_slices or _week_union_cids:
                    logger.info(
                        "outline phase: week %d page %s objective-scope "
                        "fallback to week-wide union (per-CO slice had %d "
                        "chunk(s) < floor %d; week union has %d) — block not "
                        "starved of grounding.",
                        week_num, page_id, len(_page_scoped_cids),
                        _OBJ_SCOPE_MIN_CHUNKS, len(_week_union_cids),
                    )

            # ---------------------------------------------------------- #
            # Page-per-CO (Phase 2): token-aware per-page top-K chunk cap.
            # ---------------------------------------------------------- #
            # Consolidating a multi-section CO's chunks onto one page makes the
            # authoring prompt fatter — it can overflow the per-call serving
            # window and silently head-truncate (fabricating citations). Bound
            # the page's offered universe to fit the window: cosine-rank by the
            # CO statement, keep at most ``min(max_chunks, budget-allows)``,
            # ALWAYS keep ≥1, kept ⊆ union (anti-fabrication: only DROPS). Only
            # applies to ``content`` pages (i >= 0) bound to a real CO; the four
            # singleton page types keep the week-wide union unchanged.
            if _page_per_co and page_type == "content" and page_chunk_cids:
                from lib.generation.content_page_budget import (  # noqa: PLC0415
                    cap_page_chunks,
                )

                _week_objs = week_co_objectives_index.get(week_num, [])
                # Slice binding: rank by the page's PRIMARY bound CO (the
                # slice head) — identical to ``i`` on the 1:1 path.
                _stmt_idx = _page_co_lo if _page_bound_co_ids else i
                _co_stmt = ""
                if 0 <= _stmt_idx < len(_week_objs):
                    _co_stmt = str(_week_objs[_stmt_idx].get("statement") or "")
                _capped_cids, _dropped_cited, _cap_stats = cap_page_chunks(
                    union_ids=page_chunk_cids,
                    cited_ids=page_chunk_cids,  # outline-tier: all cited
                    chunk_text_map=chunk_text_map,
                    statement=_co_stmt,
                    token_budget=_ppc_token_budget,
                    max_chunks=_ppc_max_chunks,
                    embed_builder=None,  # GPU-free: citation-order rank
                )
                if _capped_cids:
                    _ppc_chunks_kept += len(_capped_cids)
                    _ppc_chunks_dropped += _cap_stats.get("dropped_count", 0)
                    _ppc_dropped_cited += len(_dropped_cited)
                    if _dropped_cited:
                        logger.info(
                            "page-per-co: week %d page %s capped %d→%d chunk(s) "
                            "to fit the authoring window (%d cited dropped; "
                            "budget=%s, max_chunks=%s).",
                            week_num, page_id, len(page_chunk_cids),
                            len(_capped_cids), len(_dropped_cited),
                            _ppc_token_budget, _ppc_max_chunks,
                        )
                    page_chunk_cids = _capped_cids

            # ---------------------------------------------------------- #
            # Keystone fix (hollow-course defect): emit a block PLAN per
            # page, not a lone ``objective`` stub.
            # ---------------------------------------------------------- #
            # Pre-fix, every page emitted exactly ONE ``block_type=
            # "objective"`` stub, and the rewrite tier kept it as an
            # objective — so the published course carried the objective
            # statement and ZERO instructional prose (no explanation, no
            # worked example). The course was hollow.
            #
            # The fix emits, per page, the objective block PLUS at least
            # one prose block (``explanation`` + ``example``) that the
            # rewrite tier authors into real 7B-generated instructional
            # content. Both prose types are first-class ``BLOCK_TYPES``:
            # the OutlineProvider has bounds/schema/grammar for them
            # (``_OUTLINE_KIND_BOUNDS``), and the RewriteProvider has a
            # per-type HTML output contract (``_BLOCK_TYPE_OUTPUT_
            # CONTRACTS``) that stamps ``data-cf-content-type`` +
            # explanatory ``<p>`` paragraphs.
            #
            # W3.C validator-matrix interaction (the reason the old
            # comment retreated to ``objective``): ``explanation`` /
            # ``example`` require ``source_ref`` + ``content_type`` (NOT
            # ``curie_anchoring``). Both are satisfiable for prose:
            #   * ``content_type`` — the outline LLM emits a canonical
            #     value from ``_CONTENT_TYPE_ENUM`` (Ollama structured
            #     decoding forces it), and the rewrite contract stamps
            #     ``data-cf-content-type`` on the heading. We do NOT need
            #     ``objective``'s content-type SKIP carve-out.
            #   * ``source_ref`` — resolved from the page's grounded
            #     objectives via the SAME chunk-universe resolution the
            #     objective stub used (``_resolve_page_chunks`` below).
            #   * CURIE anchoring — moot: ``explanation`` / ``example``
            #     do not require it, and the dynamic CURIE-minting pass
            #     (``_mint_outline_curies``) still stamps minted CURIEs
            #     onto these blocks' ``key_claims`` for the audit trail.
            # Unlike ``objective`` (which carries ``escalate_immediately:
            # true`` and skips the outline tier), the prose block_types
            # DISPATCH through the outline + rewrite tiers, which is what
            # produces the 7B prose.
            # P3: the block PLAN is now PER PAGE TYPE — each of the five page
            # types contributes its own ordered block-type composition
            # (mirroring the Sonnet baseline). ``content`` keeps the rich
            # concept+explanation+example mix; the other types carry their
            # own (objectives+roadmap / scenario / self-check / recap).
            # Wave-2 Part 3: the per-page block composition comes from the
            # dynamic planner (when on + this week's plan resolved) else the
            # fixed ``_page_block_plan_for``. The planner's
            # ``WeekBlockPlan.page_block_plan_for`` returns 3-tuples
            # ``(block_type, target_bloom, target_co_ids)``; the fixed
            # ``_page_block_plan_for`` still returns 2-tuples
            # ``(block_type, target_bloom)``. The unpack below tolerates BOTH
            # arities (empty ``target_co_ids`` for the fixed path), so the
            # fixed-plan path stays byte-identical (week-TO ``objective_ids``).
            if week_block_plan is not None:
                _page_plan_specs = week_block_plan.page_block_plan_for(page_type)
                # Guardrail: a page type the planner left empty (no block
                # landed there) falls back to the fixed plan for THAT page so a
                # page is never block-less.
                if not _page_plan_specs:
                    _page_plan_specs = _page_block_plan_for(page_type)
            else:
                _page_plan_specs = _page_block_plan_for(page_type)
            page_block_specs: List[
                Tuple[str, int, str, Tuple[str, ...], Optional[str], Optional[str], Dict[str, Any]]
            ] = []
            for spec_offset, _spec in enumerate(_page_plan_specs):
                # Arity-tolerant: planner 3-tuple carries per-block
                # ``target_co_ids``; the fixed 2-tuple has none → empty. A
                # planner 4-tuple (FR-PLAN-01) also carries the selected
                # ``interaction_type``; a 5-tuple (FR-INT-01) also carries the
                # ``fade_state``. A 6-tuple's trailing dict (Track-A:
                # ED4ALL_RECALL_SELF_CHECK / ED4ALL_MISCONCEPTION_RICH) carries
                # ``recall_format`` / ``mc_named_concept`` / ``mc_predict_prompt``
                # / ``mc_reconcile``. The 2/3-tuple paths leave all None/empty.
                spec_type = _spec[0]
                spec_bloom = _spec[1]
                spec_co_ids: Tuple[str, ...] = (
                    tuple(_spec[2]) if len(_spec) > 2 and _spec[2] else ()
                )
                spec_itype: Optional[str] = (
                    str(_spec[3]) if len(_spec) > 3 and _spec[3] else None
                )
                spec_fade: Optional[str] = (
                    str(_spec[4]) if len(_spec) > 4 and _spec[4] else None
                )
                spec_extras: Dict[str, Any] = (
                    _spec[5] if len(_spec) > 5 and isinstance(_spec[5], dict) else {}
                )
                page_block_specs.append(
                    (spec_type, spec_offset, spec_bloom, spec_co_ids, spec_itype, spec_fade, spec_extras)
                )

            page_block_added = False
            for spec_type, spec_idx, spec_bloom, spec_co_ids, spec_itype, spec_fade, spec_extras in page_block_specs:
                # CO-id fan-out fix: stamp the block with the SPECIFIC CO id(s)
                # the planner targeted (filtered to the valid CO set), falling
                # back to the week-TO ``objective_ids`` when the planner gave no
                # (valid) CO target.
                #
                # Page-per-CO: when this content page is bound to a CO slice
                # and the planner gave no (valid) per-block CO target, prefer
                # the page's BOUND CO id(s) over the week-TO fallback — so a
                # CO-page's blocks always carry their slice's CO ids (zero
                # stranded COs, by construction; a single-CO slice stamps
                # exactly the historical one id). The planner's explicit
                # target still wins when present (a planner that names a
                # different valid CO is honored).
                _block_co_fallback = objective_ids
                if _page_bound_co_ids and not spec_co_ids:
                    _block_co_fallback = _page_bound_co_ids
                block_objective_ids = _resolve_block_objective_ids(
                    spec_co_ids, _block_co_fallback, _valid_co_ids
                )
                block_id = Block.stable_id(
                    page_id=page_id,
                    block_type=spec_type,
                    slug=slug_value,
                    idx=spec_idx,
                )
                try:
                    stub = Block(
                        block_id=block_id,
                        block_type=spec_type,
                        page_id=page_id,
                        sequence=spec_idx,
                        content="",
                        objective_ids=block_objective_ids,
                        key_terms=page_key_terms,
                        # Bloom-diversity fix: carry the per-template target
                        # Bloom onto the stub. The outline provider surfaces
                        # it as a per-block directive + enforces it as a
                        # floor after the LLM emits.
                        target_bloom=spec_bloom,
                        # FR-PLAN-01: carry the planner-selected interaction
                        # type (None on the fixed / flag-off path → byte-stable).
                        interaction_type=spec_itype,
                        # FR-INT-01: carry the planner-stamped fade_state for the
                        # B08 faded-practice ladder (None when flag off).
                        fade_state=spec_fade,
                        # Track-A: carry the planner-stamped recall_self_check /
                        # misconception_rich fields (all None when their flags are
                        # off → byte-stable; extras dict is empty then).
                        recall_format=spec_extras.get("recall_format"),
                        mc_named_concept=spec_extras.get("mc_named_concept"),
                        mc_predict_prompt=spec_extras.get("mc_predict_prompt"),
                        mc_reconcile=spec_extras.get("mc_reconcile"),
                    )
                except (TypeError, ValueError) as exc:
                    logger.warning(
                        "outline phase: skipping malformed Block stub "
                        "for week=%d, page=%s, type=%s: %s",
                        week_num, page_id, spec_type, exc,
                    )
                    continue
                all_blocks.append(stub)
                # Page-per-CO coverage tracking: record every VALID CO id this
                # block stamps, so the post-loop assertion can verify the union
                # of emitted CO ids == all valid CO ids (zero-stranded contract).
                if _page_per_co:
                    for _oid in block_objective_ids:
                        if _oid in _valid_co_ids:
                            _ppc_emitted_co_ids.add(_oid)
                # Resolve this block's source-chunk universe from its
                # week's grounded objectives. Only emit chunk dicts whose
                # id resolves to real text in the chunkset — NEVER
                # fabricate provenance. Each entry is a plain
                # ``{id, text, heading}`` dict (str->str) so the
                # ``outline_chunks.json`` sidecar stays JSON-serializable
                # and the rewrite tier can rehydrate it verbatim.
                # ``id`` + ``text`` are what the router prompt +
                # ``_block_source_chunk_ids`` consume. EVERY block on the
                # page shares the same page-grounded chunk universe
                # (``page_chunk_cids`` — objective-scoped when the per-CO
                # slice clears the floor, else the week-wide union), so a
                # prose block is grounded identically to its objective.
                resolved_chunks: List[Dict[str, str]] = []
                if chunkset_present:
                    # Gap #11: when ED4ALL_CHUNK_ROLE_DIVERSIFY is on, rotate the
                    # offered chunk order by a stable per-role offset so
                    # co-located blocks don't all lead with the same anchor
                    # example. The rotation is a PERMUTATION of page_chunk_cids
                    # (same chunk universe, different priority head) — no id is
                    # dropped or invented. Default OFF → identical order.
                    _block_cids = page_chunk_cids
                    if _chunk_role_diversify:
                        _role_key = (
                            f"{_teaching_role_for_block_type(spec_type)}:{spec_idx}"
                        )
                        _block_cids = _diversify_block_chunk_order(
                            page_chunk_cids, role_key=_role_key, enabled=True,
                        )
                    for cid in _block_cids:
                        body = chunk_text_map.get(cid)
                        if body:
                            resolved_chunks.append({
                                "id": cid,
                                "text": body,
                                "heading": heading,
                            })
                if resolved_chunks:
                    chunks_lookup[block_id] = resolved_chunks
                    n_blocks_resolved_from_objectives += 1
                    total_resolved_chunk_ids += len(resolved_chunks)
                else:
                    # Honest degrade: a block whose objectives resolve to
                    # zero real chunks (or no chunkset) keeps the
                    # topic-derived entry. That block may still fail-closed
                    # downstream, which is acceptable — we never fabricate
                    # an id with no text.
                    chunks_lookup[block_id] = [
                        {
                            "heading": heading,
                            "paragraphs": (topic or {}).get("paragraphs")
                            or [],
                        }
                    ]
                    n_blocks_fallback_to_topic += 1
                page_block_added = True
            if _page_per_co and page_type == "content" and page_block_added:
                _ppc_pages_emitted += 1
            week_block_added = week_block_added or page_block_added
        if week_block_added:
            weeks_with_blocks += 1

        # Feature I5 — deterministic per-TO key-terms page (opt-in). Built
        # OUTSIDE the LLM block loop above: the vocab cards carry pre-rendered
        # grounded HTML, so they bypass route_with_self_consistency entirely
        # (appended straight to outline_blocks below). No-op when the flag is
        # off (``_key_terms_blocks`` stays empty → no page emitted).
        if _key_terms_on:
            _wk_union_cids = week_chunk_id_index.get(week_num, [])
            _wk_chunk_details = [
                _chunk_detail_map[_cid]
                for _cid in _wk_union_cids
                if _cid in _chunk_detail_map
            ]
            _wk_cos = week_co_objectives_index.get(week_num, [])
            _kt_week_blocks = _build_key_terms_blocks(
                week_num=week_num,
                objective_ids=objective_ids,
                week_cos=_wk_cos,
                week_chunk_details=_wk_chunk_details,
                vocabulary=_key_terms_vocab,
                course_slug=course_slug,
                capture=capture,
            )
            _key_terms_blocks.extend(_kt_week_blocks)

        # W6.4 — deterministic per-week FAQ page (opt-in). Built OUTSIDE the LLM
        # loop; the grounded Q/A cards carry pre-rendered HTML + template_type
        # "faq" so the rewrite tier short-circuits them (appended straight to
        # outline_blocks below). Builder + renderer are owned by Lane B; this
        # lane only CALLS it, gated on ED4ALL_FAQ_PAGE (no-op / byte-identical
        # when off). Misconception seed blocks are not yet authored at plan time,
        # so the builder degrades to objective-seeded FAQs (its documented
        # fallback). Fail-soft: a builder/import error degrades the FAQ page
        # without breaking the outline phase.
        if _faq_on:
            try:
                from lib.generation.faq_page import build_faq_blocks

                _wk_union_cids = week_chunk_id_index.get(week_num, [])
                _faq_chunks: List[Dict[str, Any]] = []
                for _cid in _wk_union_cids:
                    _detail = _chunk_detail_map.get(_cid) or {}
                    _txt = chunk_text_map.get(_cid) or _detail.get("text") or ""
                    if not _txt:
                        continue
                    _faq_chunks.append({
                        "id": _cid,
                        "text": _txt,
                        "heading": str(_detail.get("heading") or ""),
                        "item_path": _detail.get("item_path"),
                    })
                _faq_page_id = _page_id_for(week_num, "faq")
                _faq_week_blocks = build_faq_blocks(
                    week_co_objectives_index.get(week_num, []),
                    [],  # misconception blocks unauthored at plan time
                    _faq_chunks,
                    course_slug=course_slug,
                    page_id=_faq_page_id,
                )
                _faq_blocks.extend(_faq_week_blocks)
            except Exception as _faq_exc:  # noqa: BLE001 — never break the phase
                logger.warning(
                    "faq_page: week %d FAQ build failed (%s); skipping FAQ page",
                    week_num, _faq_exc,
                )

    # Page-per-CO coverage assertion (review fix 2): the union of emitted CO
    # ids MUST equal the set of valid CO ids that landed in some iterated week's
    # objectives index — every such CO got its own content page (zero-stranded
    # contract). A miss means a CO group's week clamp or a predicate mismatch
    # left a CO with no page; log it loudly (fail-closed contract is a logged
    # error, not a crash — the run still ships, but the gap is recorded).
    if _page_per_co:
        _expected_co_ids: Set[str] = set()
        for _wn in range(1, duration_weeks + 1):
            for _obj in week_co_objectives_index.get(_wn, []):
                _oid = str(_obj.get("id") or "")
                if _oid in _valid_co_ids:
                    _expected_co_ids.add(_oid)
        _missing_co_ids = _expected_co_ids - _ppc_emitted_co_ids
        if _missing_co_ids:
            logger.error(
                "page-per-co: COVERAGE GAP — %d CO id(s) in an iterated week's "
                "objectives index were NOT stamped on any emitted block: %s. "
                "The clamp + predicate-identical builders should make this "
                "impossible; investigate the index alignment.",
                len(_missing_co_ids),
                sorted(_missing_co_ids)[:20],
            )
        else:
            logger.info(
                "page-per-co: coverage OK — all %d iterated-week CO id(s) "
                "stamped on an emitted page (zero stranded).",
                len(_expected_co_ids),
            )
        # Phase 3: page-per-CO decision capture (one event/run; replayable).
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Page-per-CO emit: drove the content-page count from "
                        f"the week CO count (one page/CO), emitting "
                        f"{_ppc_pages_emitted} content page(s) across "
                        f"{len(_expected_co_ids)} valid CO(s); per-page chunk "
                        f"cap kept {_ppc_chunks_kept}, dropped "
                        f"{_ppc_chunks_dropped} ({_ppc_dropped_cited} cited)."
                    ),
                    rationale=(
                        f"ED4ALL_CONTENT_PAGE_PER_CO on (two-pass): content "
                        f"pages now O(Σ COs) not O(sections). num_ctx="
                        f"{_ppc_num_ctx}, per-page token_budget="
                        f"{_ppc_token_budget}, max_chunks={_ppc_max_chunks}. "
                        f"Coverage {'OK' if not _missing_co_ids else 'GAP'}: "
                        f"{len(_expected_co_ids - _missing_co_ids)}/"
                        f"{len(_expected_co_ids)} CO(s) stamped on a page "
                        f"(missing {len(_missing_co_ids)}). Anti-fabrication: "
                        f"per-page chunks are a subset of the CO's real union "
                        f"(always-keep-≥1); no CO id or chunk invented."
                    ),
                    ml_features={
                        "page_per_co_enabled": True,
                        "content_pages_emitted": _ppc_pages_emitted,
                        "valid_co_count": len(_expected_co_ids),
                        "co_ids_stamped": len(_ppc_emitted_co_ids),
                        "co_ids_missing": len(_missing_co_ids),
                        "chunks_kept": _ppc_chunks_kept,
                        "chunks_dropped": _ppc_chunks_dropped,
                        "cited_chunks_dropped": _ppc_dropped_cited,
                        "num_ctx": _ppc_num_ctx,
                        "page_token_budget": _ppc_token_budget,
                        "max_chunks": _ppc_max_chunks,
                    },
                )
            except Exception:  # noqa: BLE001
                pass

    # Summary decision capture for grounded source-chunk resolution. One
    # event per run (per-block logging would flood). Rationale interpolates
    # the dynamic per-run counts so the capture is replayable.
    if capture is not None:
        _n_obj = n_blocks_resolved_from_objectives
        _n_topic = n_blocks_fallback_to_topic
        _mean_cids = (
            round(total_resolved_chunk_ids / _n_obj, 2) if _n_obj else 0.0
        )
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"Resolved per-block source chunks from grounded "
                    f"objectives for {_n_obj} block(s); fell back to "
                    f"topic-paragraphs for {_n_topic}. Page-scoping: "
                    f"{n_pages_objective_scoped} page(s) narrowed to a single "
                    f"objective's chunks, {n_pages_week_fallback} reverted to "
                    f"the week-wide union."
                ),
                rationale=(
                    f"Chunkset {'loaded' if chunkset_present else 'ABSENT'} "
                    f"at {chunkset_path} carrying {len(chunk_text_map)} "
                    f"chunks; {_n_obj} blocks resolved {total_resolved_chunk_ids} "
                    f"objective-grounded chunk_ids (mean {_mean_cids}/block), "
                    f"{_n_topic} blocks fell back to topic-paragraph shape "
                    f"(empty grounding → may fail-closed; never fabricated). "
                    f"Fix 2A page-level narrowing (Step 2b): "
                    f"{n_pages_objective_scoped} page(s) were objective-scoped "
                    f"(positional page→CO; per-CO slice cleared the "
                    f"{_OBJ_SCOPE_MIN_CHUNKS}-chunk floor, shrinking the "
                    f"week-wide semantic grab-bag to one topic), "
                    f"{n_pages_week_fallback} page(s) reverted to the week-wide "
                    f"union (no CO at the page index or per-CO slice below the "
                    f"floor — never starved; narrowing only ever subsets real "
                    f"chunk sets)."
                ),
                ml_features={
                    "chunkset_present": chunkset_present,
                    "chunkset_chunks_loaded": len(chunk_text_map),
                    "blocks_resolved_from_objectives": _n_obj,
                    "blocks_fallback_to_topic": _n_topic,
                    "total_resolved_chunk_ids": total_resolved_chunk_ids,
                    "mean_chunk_ids_per_resolved_block": _mean_cids,
                    "pages_objective_scoped": n_pages_objective_scoped,
                    "pages_week_fallback": n_pages_week_fallback,
                    "objective_scope_min_chunks": _OBJ_SCOPE_MIN_CHUNKS,
                    # Wave-2 Part 3 (keystone): dynamic block-plan stats.
                    "dynamic_block_plan_enabled": dynamic_block_plan,
                    "weeks_planner_used": n_weeks_planner_used,
                    "weeks_planner_fallback": n_weeks_planner_fallback,
                },
            )
        except Exception:  # noqa: BLE001
            pass

    # Worker W2: dispatch each block through
    # ``router.route_with_self_consistency`` with the resolved
    # validator chain so the inter-tier seam runs INSIDE the regen
    # budget (instead of catching failures after the fact). The chain
    # is resolved from the YAML ``inter_tier_validation`` phase via
    # ``_resolve_inter_tier_validators``; absent workflow_type (legacy
    # direct caller) returns []  → behaves identically to the prior
    # ``router.route()`` single-shot path.
    objectives_payload = [
        {"id": o.get("id"), "statement": o.get("statement")}
        for o in (terminal_objectives + chapter_objectives)
    ]

    # outline-overflow-fix-2026-07: per-block objectives filter — build the
    # TO/CO roll-up maps ONCE, then pass each outline call only the
    # objectives relevant to its block (see the module-level helpers). Falls
    # back to the full list on an empty filter (never an empty objectives
    # section).
    _objective_rollup = _build_objective_rollup(
        terminal_objectives, chapter_objectives
    )

    def _objectives_payload_for_block(block: Any) -> List[Dict[str, Any]]:
        return _filter_objectives_payload_for_block(
            getattr(block, "objective_ids", ()) or (),
            objectives_payload,
            _objective_rollup,
        )

    workflow_type = kwargs.get("workflow_type") or ""
    validators = _resolve_inter_tier_validators(workflow_type, capture)

    # Build the per-course CURIE minter ONCE (loads
    # domain_concept_vocabulary.json + compiles concept seeds a single
    # time) so a per-block ``pre_validate_hook`` can stamp minted CURIEs
    # onto each freshly-routed candidate BEFORE the in-loop
    # ``BlockCurieAnchoringValidator`` runs. Without this, a prose-corpus
    # block lands with ``content["curies"]==[]`` (the outline tier
    # regenerates curies each dispatch), the in-loop curie-anchoring gate
    # fires ``OUTLINE_BLOCK_MISSING_CURIES`` → ``regenerate``, and the
    # block re-rolls IDENTICALLY up to the budget (~3× the calls) — the
    # post-loop ``_mint_outline_curies`` mints too late to prevent it.
    # ``minter is None`` (RDF / legacy corpora, no vocabulary) → no hook
    # is threaded and the route call is byte-identical to the prior path.
    # Objective-refs-concept anchoring: build the {objective_id: statement}
    # map from the already-loaded objectives so the minter can match the
    # vocabulary over a block's declared objectives' statement text when
    # key_claims + source-chunks miss (no re-read of disk).
    _objective_statements_for_minting: Dict[str, str] = {}
    for _o in (terminal_objectives + chapter_objectives):
        _oid = _o.get("id")
        _ostmt = _o.get("statement")
        if (
            isinstance(_oid, str) and _oid
            and isinstance(_ostmt, str) and _ostmt.strip()
        ):
            _objective_statements_for_minting[_oid] = _ostmt.strip()
    _outline_minter = _build_outline_curie_minter(
        course_code=course_code, kwargs=kwargs,
        objective_statements=_objective_statements_for_minting,
    )
    _minted_curie_map = (
        _outline_minter.minted_map if _outline_minter is not None else None
    )

    def _make_mint_hook(_chunks: List[Any]) -> Optional[Callable[[Any], Any]]:
        if _outline_minter is None:
            return None

        def _hook(candidate: Any) -> Any:
            # Key the per-block source-chunk universe by the candidate's
            # OWN block_id (== the routed stub's block_id) so the minter's
            # source-chunk fallback resolves correctly regardless of the
            # enclosing loop variable.
            _chunks_by_id = (
                {candidate.block_id: _chunks} if _chunks else {}
            )
            new_block, meta = _outline_minter.mint_block(
                candidate, _chunks_by_id,
            )
            if new_block is None or meta is None:
                return candidate
            _emit_curie_minting_capture(capture, candidate, meta)
            return new_block

        return _hook

    # ------------------------------------------------------------------ #
    # Crash-resume checkpoint (append-as-you-go) for the outline tier.
    # ------------------------------------------------------------------ #
    # The per-block ``route_with_self_consistency`` dispatch below is the
    # expensive ~2h local-7B work. Append each SUCCESSFULLY-authored block to
    # ``.blocks_outline_checkpoint.jsonl`` the moment it completes (flush per
    # block), so a mid-loop kill survives. On resume, rehydrate the already-
    # authored blocks from the sidecar and SKIP their LLM dispatch. Default
    # ON; OFF (or no sidecar present) → byte-identical to the legacy emit.
    # Degraded (escalation-marker) blocks are NOT checkpointed, so a resume
    # re-attempts them — identical contract to the rewrite-tier per-block cache.
    _outline_checkpoint_on = _checkpoint_enabled(
        _COURSEFORGE_OUTLINE_CHECKPOINT_ENV
    )
    _outline_checkpoint_path = out_dir / _OUTLINE_CHECKPOINT_NAME
    # ``--force`` (courseforge-outline stage subcommand) WINS over the resume
    # sidecar: an operator-forced re-run must not silently rehydrate a prior
    # attempt's blocks, so the sidecar is CLEARED and the resume map ignored
    # (fresh blocks still checkpoint — a forced re-run keeps crash safety).
    _outline_force_rerun = bool(kwargs.get("force_rerun"))
    if _outline_force_rerun:
        _remove_block_checkpoint(_outline_checkpoint_path)
        logger.info(
            "outline phase: --force cleared the resume sidecar %s.",
            _outline_checkpoint_path,
        )
    _outline_resume_map: Dict[str, Any] = (
        _load_block_checkpoint(_outline_checkpoint_path)
        if (_outline_checkpoint_on and not _outline_force_rerun) else {}
    )
    # Per-block input fingerprints (shared llm_checkpoint discipline): a
    # sidecar entry is reused ONLY when its stamped fingerprint matches the
    # recomputed one for the same block_id (a model / chunk / objective /
    # window-knob change between resume attempts re-authors). Entries with NO
    # stamp (pre-upgrade sidecars) keep legacy block_id-only reuse.
    _outline_objectives_sha = _objectives_payload_sha(objectives_payload)

    def _outline_block_fp(_b: Any) -> str:
        return _tier_block_fingerprint(
            _b,
            tier="outline",
            chunks_lookup=chunks_lookup,
            objectives_sha=_outline_objectives_sha,
            router=router,
        )

    _n_outline_resumed = 0
    _n_outline_authored_fresh = 0

    # dispatch-resilience-2026-07: circuit-breaker state. Consecutive
    # dispatch EXCEPTIONS across blocks (a successful dispatch — even one
    # returning a semantic escalation marker — resets the counter, since the
    # endpoint is alive). At the threshold the phase halts LOUDLY instead of
    # stamping the rest of the course.
    _outline_dispatch_breaker = _resolve_outline_dispatch_breaker()
    _consecutive_dispatch_failures = 0

    # Opt-in concurrent outline dispatch (COURSEFORGE_OUTLINE_CONCURRENCY).
    # Default 1 = the EXACT sequential path below (no thread pool
    # constructed; byte-identical to the legacy behavior). > 1 fans the
    # per-block ``route_with_self_consistency`` dispatch (the expensive
    # local-7B/cloud call; its ~3 self-consistency candidates stay
    # SEQUENTIAL within a block) out across a bounded thread pool — only
    # ACROSS blocks. The shared GPU singletons (NLI/embedder, reached via
    # the inter-tier validator chain + best-of-N scoring) serialize on the
    # module-level ``Courseforge/router/router.py::_NLI_SCORE_LOCK``;
    # ``DecisionCapture`` appends serialize on the capture's in-process
    # RLock. Results are RE-ORDERED to the original block order so the
    # emitted outline is identical regardless of completion order. Read
    # ONCE at phase start; garbage / < 1 → 1 (parse-with-fallback,
    # mirroring COURSEFORGE_REWRITE_CONCURRENCY).
    _outline_concurrency = 1
    try:
        _oc_raw = int(os.environ.get("COURSEFORGE_OUTLINE_CONCURRENCY", "1"))
        if _oc_raw >= 1:
            _outline_concurrency = _oc_raw
    except (TypeError, ValueError):
        _outline_concurrency = 1

    # Shared mutable per-block worker state. The lock keeps the resume/fresh
    # tallies + the consecutive-dispatch-failure breaker counter coherent
    # under the concurrent fan-out (uncontended — byte-identical — on the
    # sequential path). ``_outline_breaker_trip`` records the first trip
    # (count + last exception class/message) so the CALLER halts the phase
    # LOUDLY (the worker cannot return the phase envelope itself).
    _outline_state_lock = threading.Lock()
    _outline_breaker_trip: Dict[str, Any] = {}

    outline_blocks: List[Any] = []

    def _process_one_outline_block(blk):  # type: ignore[no-untyped-def]
        """Author a single outline block (resume rehydrate OR fresh dispatch).

        Pure w.r.t. output ordering — returns ``STOP_MARKER`` (stop armed
        pre-dispatch; the P3.0 marker discipline shared with the rewrite
        tier: under the thread-pool path every future is pre-submitted, so
        a worker must RETURN the marker rather than raise — a raise would
        surface through ``future.result()`` and skip already-resolved
        siblings) or a ``(block_or_None, kind)`` tuple with ``kind`` in
        ``{"resumed", "fresh", "dispatch_error"}``; the caller places the
        block at the input index so output order is deterministic
        regardless of completion order. FAIL-SOFT per block: a dispatch
        exception yields an ``outline_dispatch_error``-marked block
        (exactly the sequential contract), never aborting siblings. Fresh
        blocks are appended to the resume sidecar HERE (flush per block;
        ``_append_block_checkpoint`` opens+closes per call and appends
        whole JSONL lines, and resume dedupes by block_id) so a mid-fanout
        kill is resumable.
        """
        nonlocal _consecutive_dispatch_failures
        nonlocal _n_outline_resumed, _n_outline_authored_fresh
        if stop_requested():
            return STOP_MARKER
        _blk_fp = (
            _outline_block_fp(blk) if _outline_checkpoint_on else ""
        )
        # Resume: skip the LLM dispatch for a block already checkpointed by a
        # prior interrupted attempt. A malformed checkpoint entry rehydrates
        # to None → fall through and re-author (never a duplicate: the fresh
        # author replaces the same stable block_id). A fingerprint-stamped
        # entry whose stamp mismatches the recomputed input fingerprint is
        # SKIPPED (stale inputs → re-author).
        if _outline_checkpoint_on:
            _cached = _outline_resume_map.get(blk.block_id)
            if _cached is not None and _cached.get(
                _BLOCK_CHECKPOINT_FP_KEY, _blk_fp
            ) == _blk_fp:
                _cached_blk = _block_from_checkpoint_entry(_cached)
                if _cached_blk is not None:
                    with _outline_state_lock:
                        _n_outline_resumed += 1
                    return (_cached_blk, "resumed")
        block_chunks = chunks_lookup.get(blk.block_id, [])
        # outline-overflow-fix-2026-07: pass only the objectives relevant to
        # this block (its TO(s) + rolled-up COs), falling back to the full
        # list when the filter is empty. See ``_objectives_payload_for_block``.
        _blk_objectives = _objectives_payload_for_block(blk)
        # dispatch-resilience-2026-07: bounded classify+retry around the
        # per-block dispatch. Transient errors (endpoint flap / transport /
        # 429 / 5xx / timeout) are retried in-loop with a short exponential
        # backoff; a permanent error (or exhausted transient retries) gives
        # up on the block.
        outlined = None
        _dispatch_exc: Optional[Exception] = None
        _dispatch_attempts = 0
        for _attempt in range(_OUTLINE_DISPATCH_MAX_RETRIES + 1):
            _dispatch_attempts = _attempt + 1
            try:
                outlined = router.route_with_self_consistency(
                    blk,
                    validators=validators,
                    source_chunks=block_chunks,
                    objectives=_blk_objectives,
                    minted_curie_map=_minted_curie_map,
                    pre_validate_hook=_make_mint_hook(block_chunks),
                )
                _dispatch_exc = None
                break
            except Exception as exc:  # noqa: BLE001
                _dispatch_exc = exc
                if (
                    _outline_dispatch_is_transient(exc)
                    and _attempt < _OUTLINE_DISPATCH_MAX_RETRIES
                ):
                    _backoff = _OUTLINE_DISPATCH_RETRY_BACKOFFS[
                        min(
                            _attempt,
                            len(_OUTLINE_DISPATCH_RETRY_BACKOFFS) - 1,
                        )
                    ]
                    logger.warning(
                        "outline phase: transient dispatch error for "
                        "block_id=%s (attempt %d/%d), retrying in %.0fs: %s",
                        blk.block_id, _dispatch_attempts,
                        _OUTLINE_DISPATCH_MAX_RETRIES + 1, _backoff, exc,
                    )
                    time.sleep(_backoff)
                    continue
                # Permanent, or transient retries exhausted → give up.
                break

        if _dispatch_exc is None and outlined is not None:
            # Dispatch succeeded (a returned block — even a semantically-
            # escalated one — means the endpoint is alive): reset the
            # consecutive-failure breaker counter.
            with _outline_state_lock:
                _consecutive_dispatch_failures = 0
                _n_outline_authored_fresh += 1
            # Checkpoint the freshly-authored block (NOT marker-bearing —
            # those are re-attempted on resume). Append + flush per block,
            # stamped with the INPUT fingerprint for resume validation.
            if (
                _outline_checkpoint_on
                and not getattr(outlined, "escalation_marker", None)
            ):
                _outline_entry = _block_to_snake_case_entry(outlined)
                _outline_entry[_BLOCK_CHECKPOINT_FP_KEY] = _blk_fp
                _append_block_checkpoint(
                    _outline_checkpoint_path,
                    _outline_entry,
                )
            return (outlined, "fresh")

        # --- give-up path: dispatch raised and was not recoverable ---
        with _outline_state_lock:
            _consecutive_dispatch_failures += 1
            _cdf = _consecutive_dispatch_failures
        _exc_cls = (
            type(_dispatch_exc).__name__ if _dispatch_exc else "Unknown"
        )
        _exc_msg = str(_dispatch_exc) if _dispatch_exc else ""
        _was_transient = _outline_dispatch_is_transient(_dispatch_exc)
        logger.warning(
            "outline phase: route_with_self_consistency() dispatch failed "
            "for block_id=%s after %d attempt(s) [%s]: %s (consecutive "
            "dispatch failures=%d)",
            blk.block_id, _dispatch_attempts, _exc_cls, _exc_msg,
            _cdf,
        )
        # Decision capture: dynamic rationale carries the exception class +
        # message + attempt count so a postmortem is replayable.
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Outline block {blk.block_id} stamped "
                        f"outline_dispatch_error after "
                        f"{_dispatch_attempts} dispatch attempt(s)."
                    ),
                    rationale=(
                        f"block_id={blk.block_id} (type="
                        f"{getattr(blk, 'block_type', '?')}) failed dispatch "
                        f"after {_dispatch_attempts} attempt(s): "
                        f"route_with_self_consistency raised {_exc_cls}: "
                        f"{_exc_msg[:200]!r} — classified "
                        + (
                            "transient (retries exhausted)"
                            if _was_transient else "permanent"
                        )
                        + "; stamped the canonical outline_dispatch_error "
                        f"marker (NOT outline_budget_exhausted, reserved for "
                        f"semantic regen-budget exhaustion) so postmortems "
                        f"separate endpoint/transport failures from budget "
                        f"exhaustion. Consecutive dispatch failures now "
                        f"{_cdf} (breaker="
                        f"{_outline_dispatch_breaker})."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_outline",
                        "block_id": blk.block_id,
                        "exception_class": _exc_cls,
                        "dispatch_attempts": _dispatch_attempts,
                        "transient": _was_transient,
                        "consecutive_dispatch_failures": _cdf,
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        # Circuit breaker: a persistent outage would stamp the entire
        # remaining course. Record the FIRST trip for the caller (the worker
        # cannot return the phase envelope itself); the caller halts LOUDLY.
        # Already-authored blocks stay checkpointed (the sidecar is only
        # deleted on a successful final write below), so a plain --resume
        # re-attempts the marker blocks + the never-reached blocks.
        if (
            _outline_dispatch_breaker > 0
            and _cdf >= _outline_dispatch_breaker
        ):
            with _outline_state_lock:
                if not _outline_breaker_trip:
                    _outline_breaker_trip.update(
                        consecutive=_cdf,
                        exc_cls=_exc_cls,
                        exc_msg=_exc_msg,
                    )

        # Persist a stub-with-marker so downstream sees the failure. Use the
        # canonical ``outline_dispatch_error`` marker (a ``_ESCALATION_MARKERS``
        # member) — NOT ``outline_budget_exhausted``. NOT checkpointed
        # (marker blocks re-attempt on resume).
        try:
            import dataclasses as _dc
            return (_dc.replace(
                blk, escalation_marker="outline_dispatch_error",
            ), "dispatch_error")
        except (TypeError, ValueError):
            return (None, "dispatch_error")

    def _outline_breaker_response() -> str:
        """Emit the loud circuit-breaker phase-failure envelope.

        Caller-side twin of the worker's trip record: reads the FIRST trip
        captured in ``_outline_breaker_trip`` (count + last exception) so
        the sequential path halts at exactly the legacy threshold block and
        the concurrent path halts after the drain (all futures were
        pre-submitted) with the identical envelope.
        """
        _cdf = int(_outline_breaker_trip.get("consecutive", 0))
        _exc_cls = str(_outline_breaker_trip.get("exc_cls", ""))
        _exc_msg = str(_outline_breaker_trip.get("exc_msg", ""))
        _breaker_msg = (
            f"outline dispatch circuit breaker tripped after "
            f"{_cdf} consecutive failures — "
            f"endpoint likely down (last error {_exc_cls}: "
            f"{_exc_msg[:200]})"
        )
        logger.error("outline phase: %s", _breaker_msg)
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        "Outline dispatch circuit breaker tripped; "
                        "halting phase."
                    ),
                    rationale=(
                        f"{_cdf} consecutive "
                        f"outline dispatch failures reached the "
                        f"COURSEFORGE_OUTLINE_DISPATCH_BREAKER threshold "
                        f"({_outline_dispatch_breaker}); halting rather "
                        f"than stamping the remaining "
                        f"{len(all_blocks) - len(outline_blocks)} block(s) "
                        f"so the already-authored/checkpointed blocks stay "
                        f"resumable on the next run. Last error "
                        f"{_exc_cls}."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_outline",
                        "consecutive_dispatch_failures": _cdf,
                        "breaker_threshold": _outline_dispatch_breaker,
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        return json.dumps({
            "success": False,
            "error_code": "OUTLINE_DISPATCH_CIRCUIT_BREAKER",
            "error": _breaker_msg,
        })

    if _outline_concurrency <= 1:
        # Sequential path — EXACT legacy behavior. No pool constructed.
        for blk in all_blocks:
            # Graceful stop (checkpoint on command): raise at the unit
            # boundary once a stop sentinel is armed. Every prior block has
            # already been appended to ``.blocks_outline_checkpoint.jsonl``
            # (fresh) or rehydrated from it (resume), so
            # ``len(outline_blocks)`` == the number of checkpointed/served
            # units.
            check_stop("outline_tier", len(outline_blocks))
            _outcome = _process_one_outline_block(blk)
            # Belt-and-suspenders for the tiny arm-race window: a stop armed
            # between the loop-top check and the worker's entry returns
            # STOP_MARKER — treat it as not-attempted (never a block), do
            # NOT checkpoint it, and raise before any final artifact write.
            if _outcome is STOP_MARKER:
                raise GracefulStopRequested(
                    "outline_tier", len(outline_blocks)
                )
            _result, _kind = _outcome
            if _result is not None:
                outline_blocks.append(_result)
            # Circuit breaker: trip LOUDLY at the legacy threshold block
            # instead of stamping the entire remaining course.
            if _kind == "dispatch_error" and _outline_breaker_trip:
                return _outline_breaker_response()
    else:
        # Bounded thread-pool fanout (COURSEFORGE_OUTLINE_CONCURRENCY > 1).
        # Collect into an index-keyed dict so the final list is reassembled
        # in ORIGINAL block order (deterministic output regardless of which
        # block finishes first). Per-block failure stays isolated to that
        # block (the worker returns the marked block).
        from concurrent.futures import ThreadPoolExecutor

        _pool_size = min(_outline_concurrency, len(all_blocks)) or 1
        _results_by_idx: Dict[int, Any] = {}
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Outline-tier concurrency enabled: dispatching "
                        f"{len(all_blocks)} block(s) across a "
                        f"{_pool_size}-thread pool."
                    ),
                    rationale=(
                        f"COURSEFORGE_OUTLINE_CONCURRENCY="
                        f"{_outline_concurrency} (pool sized to "
                        f"min(knob, n_blocks)={_pool_size}) fans the "
                        f"I/O-bound per-block outline LLM dispatch "
                        f"(route_with_self_consistency; self-consistency "
                        f"candidates stay SEQUENTIAL within a block) out "
                        f"across threads; shared GPU NLI/embedder + "
                        f"DecisionCapture writes serialize on internal "
                        f"locks. Output is re-ordered to the original "
                        f"block sequence so the emitted outline is "
                        f"byte-identical to the sequential path."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_outline",
                        "outline_concurrency": _outline_concurrency,
                        "pool_size": _pool_size,
                        "block_count": len(all_blocks),
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        # Graceful stop (checkpoint on command): a pre-armed sentinel
        # refuses the whole fan-out before any future is submitted (zero
        # dispatches).
        check_stop("outline_tier", len(outline_blocks))
        # P3.0 drain discipline (mirrors the rewrite pool): futures are
        # pre-submitted, so an in-flight worker that observes a mid-fanout
        # stop RETURNS ``STOP_MARKER`` (never raises). The drain loop keeps
        # collecting every NON-marker resolved future (each fresh block was
        # already checkpointed INSIDE the worker), records that a stop was
        # seen, and only AFTER draining raises ``GracefulStopRequested`` —
        # so a mid-fanout kill loses nothing already computed.
        _outline_stop_seen = False
        with ThreadPoolExecutor(max_workers=_pool_size) as _pool:
            _futs = {
                _pool.submit(_process_one_outline_block, _blk): _idx
                for _idx, _blk in enumerate(all_blocks)
            }
            for _fut in _futs:
                _idx = _futs[_fut]
                try:
                    _fut_result = _fut.result()
                    if _fut_result is STOP_MARKER:
                        # Refused pre-dispatch — not-attempted; resume
                        # re-runs it (it is not a Block, so it never enters
                        # the reorder map).
                        _outline_stop_seen = True
                        continue
                    _results_by_idx[_idx] = _fut_result
                except Exception as exc:  # noqa: BLE001
                    # Defensive: the worker already fail-softs, but a truly
                    # unexpected raise must not drop the block silently —
                    # stamp the canonical dispatch-error marker at its
                    # original index.
                    logger.warning(
                        "outline phase: concurrent worker raised for "
                        "block idx=%s: %s",
                        _idx, exc,
                    )
                    try:
                        import dataclasses as _dc
                        _results_by_idx[_idx] = (_dc.replace(
                            all_blocks[_idx],
                            escalation_marker="outline_dispatch_error",
                        ), "dispatch_error")
                    except (TypeError, ValueError):
                        _results_by_idx[_idx] = (None, "dispatch_error")
        # Raise AFTER the drain loop: every resolved worker already appended
        # its own per-block checkpoint (inside the worker), so nothing
        # already computed is lost. ``len(_results_by_idx)`` == the resolved
        # units.
        if _outline_stop_seen:
            raise GracefulStopRequested(
                "outline_tier", len(_results_by_idx)
            )
        for _idx in range(len(all_blocks)):
            _outcome = _results_by_idx.get(_idx)
            if _outcome is None:
                continue
            _result, _kind = _outcome
            if _result is not None:
                outline_blocks.append(_result)
        # Circuit breaker under the fan-out: completion-order consecutive
        # failures (all futures were pre-submitted), evaluated after the
        # drain + deterministic re-order — the halt envelope is identical
        # to the sequential path and every authored block stayed
        # checkpointed.
        if _outline_breaker_trip:
            return _outline_breaker_response()

    # Resume decision capture (dynamic rationale: units resumed / authored
    # fresh / sidecar path). Mirrors the phase_start capture in this function.
    if _outline_checkpoint_on and capture is not None and (
        _n_outline_resumed or _n_outline_authored_fresh
    ):
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"Outline crash-resume checkpoint: rehydrated "
                    f"{_n_outline_resumed} already-authored block(s) and "
                    f"authored {_n_outline_authored_fresh} fresh."
                ),
                rationale=(
                    f"Append-as-you-go sidecar "
                    f"{_outline_checkpoint_path.name} skipped the expensive "
                    f"route_with_self_consistency dispatch for "
                    f"{_n_outline_resumed} block(s) checkpointed by a prior "
                    f"interrupted attempt; {_n_outline_authored_fresh} block(s) "
                    f"were authored this run and flushed per-block so a "
                    f"mid-loop kill survives (resume is dedupe-by-block_id, "
                    f"never duplicating or fabricating a block)."
                ),
                ml_features={
                    "gate_id": "_run_content_generation_outline",
                    "blocks_resumed": _n_outline_resumed,
                    "blocks_authored_fresh": _n_outline_authored_fresh,
                    "checkpoint_sidecar": _outline_checkpoint_path.name,
                },
            )
        except Exception:  # noqa: BLE001
            pass

    # Feature I5 — append the deterministic key-terms vocab cards to the
    # outline output. They carry pre-rendered grounded HTML + the
    # ``template_type="key_terms"`` marker (so the rewrite tier short-circuits
    # the LLM), and they bypassed route_with_self_consistency entirely. The
    # downstream deterministic post-passes are safe for them: the curie minter
    # skips string content, and the objective-ref repairs only ever drop
    # NON-canonical refs (their objective_ids are the week's canonical TO ids).
    if _key_terms_blocks:
        outline_blocks.extend(_key_terms_blocks)

    # W6.4 — flush the deterministic FAQ-page blocks into the outline set (no-op
    # when ED4ALL_FAQ_PAGE is off; ``_faq_blocks`` stays empty → byte-identical).
    if _faq_blocks:
        outline_blocks.extend(_faq_blocks)

    # ------------------------------------------------------------------ #
    # FIX 2 — drop hallucinated objective refs.
    # ------------------------------------------------------------------ #
    # The 7B outline tier occasionally references an objective id that is
    # not in the canonical synthesized set (e.g. ``TO-08`` when only four
    # terminal objectives exist, or a stray ``cf:CO-36`` CURIE that leaked
    # into ``objective_refs``). Load the canonical id set EXACTLY the way
    # ``BlockPageObjectivesValidator`` does — via the gate's own
    # ``_load_canonical_objectives`` over ``synthesized_objectives.json``
    # — so the repair and the gate agree on the universe; then drop any
    # ref not in it. Never invents a ref; valid week refs preserved.
    canonical_obj_ids: Set[str] = set()
    if objectives_path:
        try:
            from Courseforge.router.inter_tier_gates import (
                _load_canonical_objectives,
            )
            canonical_obj_ids = _load_canonical_objectives(
                Path(objectives_path)
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "outline phase: failed to load canonical objectives for "
                "objective-ref repair from %s: %s",
                objectives_path, exc,
            )
    _repair_outline_objective_refs(
        outline_blocks=outline_blocks,
        canonical_ids=canonical_obj_ids,
        capture=capture,
    )

    # ------------------------------------------------------------------ #
    # Dynamic CURIE minting (v0.3.0 corpus-generalization initiative).
    # ------------------------------------------------------------------ #
    # A prose corpus (e.g. a general textbook) has zero RDF/SHACL
    # CURIEs in its text, so every outline block lands with an EMPTY
    # ``content["curies"]`` and ``BlockCurieAnchoringValidator`` 100%-
    # fails the ``OUTLINE_BLOCK_MISSING_CURIES`` gate. When the Stage-3
    # textbook-synthesis pass produced a ``domain_concept_vocabulary.json``
    # for this course, mint a per-course CURIE for every vocabulary
    # concept and stamp the matching minted CURIEs onto each outline
    # block whose ``curies`` is currently empty.
    #
    # Backward-compat contract: when NO vocabulary file exists (every
    # RDF / legacy corpus, every existing test fixture), this block is a
    # complete no-op — outline blocks are byte-identical to the
    # pre-minting emit. The absence of the vocabulary file is the
    # natural gate; no behavior flag is needed.
    _mint_outline_curies(
        outline_blocks=outline_blocks,
        course_code=course_code,
        kwargs=kwargs,
        capture=capture,
        chunks_lookup=chunks_lookup,
    )

    # ------------------------------------------------------------------ #
    # W2 §6 — deterministic block↔objective alignment pass.
    # ------------------------------------------------------------------ #
    # The outline tier emits ``objective_refs[]`` per block (Wave-27); this
    # small deterministic embedding classifier VERIFIES/REPAIRS them BEFORE
    # inter_tier_validation. It only ADDS embedding-matched refs the model
    # missed (existing refs are authoritative) and stamps a
    # ``no_objective_alignment`` structural warning on a block with zero
    # alignment — it NEVER fabricates a ref to dodge the
    # ``block_objective_delivery`` gate. Embeddings absent → pass-through
    # (the model's outline-tier refs stand).
    outline_blocks = _align_outline_blocks_to_objectives(
        outline_blocks=outline_blocks,
        objectives_payload=objectives_payload,
        capture=capture,
    )

    # FR-11 — anchored-rubric PRODUCER hook. Blocks now carry their final
    # ``objective_ids`` (the alignment pass above) and the objective dicts
    # (terminal_objectives + chapter_objectives) are in ``objectives_payload``.
    # Authors ``Block.anchored_rubric`` for Evaluate/Create scored blocks so
    # the IB3.4 AnchoredRubricValidator (a consumer with no producer) reads a
    # grounded rubric at post_rewrite_validation. Strict no-op when
    # ED4ALL_ALIGNMENT_VERB_TRIPLE is off (byte-stable). Best-effort: any
    # failure logs a warning and leaves the blocks unchanged — never aborts.
    try:
        from lib.generation.anchored_rubric import attach_anchored_rubrics
        outline_blocks = attach_anchored_rubrics(
            blocks=outline_blocks,
            objectives_payload=objectives_payload,
            capture=capture,
            course_code=course_code,
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never abort the phase
        logger.warning(
            "outline phase: anchored-rubric producer failed (%s); "
            "leaving outline blocks unchanged.", exc,
        )

    # Persist outline blocks to JSONL (one entry per Block via
    # to_jsonld_entry — same shape post_rewrite_validation consumes).
    blocks_outline_path = out_dir / "blocks_outline.jsonl"
    with blocks_outline_path.open("w", encoding="utf-8") as fh:
        for blk in outline_blocks:
            fh.write(json.dumps(
                _block_to_snake_case_entry(blk), ensure_ascii=False,
            ))
            fh.write("\n")

    # Crash-resume sidecar cleanup: the final JSONL is on disk, so the
    # interrupted-run checkpoint is no longer needed. Resume is only for an
    # INTERRUPTED run — a stale sidecar would re-feed a completed run.
    if _outline_checkpoint_on:
        _remove_block_checkpoint(_outline_checkpoint_path)
    # Symmetric cleanup for the dynamic block-planner per-week sidecar (removed
    # only on this successful final write, never on a graceful-stop pause).
    _planner_store.remove()

    # Worker W2: persist chunks_lookup + objectives_payload as sidecars
    # next to blocks_outline.jsonl so W3's rewrite phase can rehydrate
    # them without re-walking staging / synthesized_objectives. JSON
    # is canonicalised (indent=2, sort_keys=True) so on-disk diffs are
    # operator-readable.
    chunks_sidecar_path = out_dir / "outline_chunks.json"
    objectives_sidecar_path = out_dir / "outline_objectives.json"
    try:
        # W-D6 callout: ``ensure_ascii=False`` aligns with the canonical
        # ``lib.utils.write_jsonl`` default + matches the rest of the
        # JSONL emit chain (non-ASCII characters survive a tail-f read
        # instead of round-tripping through ``\uXXXX`` escapes).
        # Observable change for any sidecar carrying non-ASCII content.
        chunks_sidecar_path.write_text(
            json.dumps(chunks_lookup, indent=2, sort_keys=True, ensure_ascii=False),
            encoding="utf-8",
        )
        objectives_sidecar_path.write_text(
            json.dumps(
                objectives_payload, indent=2, sort_keys=True, ensure_ascii=False
            ),
            encoding="utf-8",
        )
    except OSError as exc:
        logger.warning(
            "outline phase: failed to persist outline sidecars at %s: %s",
            out_dir, exc,
        )

    if capture is not None:
        try:
            capture.log_decision(
                decision_type="phase_start",
                decision=(
                    f"content_generation_outline: emitted "
                    f"{len(outline_blocks)} outline-tier blocks across "
                    f"{weeks_with_blocks} weeks."
                ),
                rationale=(
                    f"Dispatched route_with_self_consistency per block "
                    f"with {len(validators)} inter-tier validators "
                    f"resolved from workflow_type={workflow_type!r}; "
                    f"persisted to {blocks_outline_path.name} for the "
                    f"inter_tier_validation phase to consume."
                ),
                ml_features={
                    "block_count": len(outline_blocks),
                    "weeks_prepared": weeks_with_blocks,
                    "tier": "outline",
                    "validator_count": len(validators),
                },
            )
        except Exception:  # noqa: BLE001
            pass

    return json.dumps({
        "success": True,
        "blocks_outline_path": str(blocks_outline_path),
        "outline_chunks_path": str(chunks_sidecar_path),
        "outline_objectives_path": str(objectives_sidecar_path),
        "project_id": project_id,
        "weeks_prepared": weeks_with_blocks,
        "block_count": len(outline_blocks),
    })


async def _run_inter_tier_validation(**kwargs) -> str:
    """Run the four shape-discriminating Block-input validators against
    outline-tier blocks loaded from ``blocks_outline_path``.

    Phase 3.5 Subtask 29. Mirrors ``_run_post_rewrite_validation`` but
    consumes the outline-tier ``blocks_outline_path`` so a failed
    outline-tier emit (CURIE / content_type / objective_ref / source_id
    drop) is caught before the rewrite tier wastes cycles authoring HTML
    against the broken outline.

    Inputs (kwargs):
        blocks_outline_path: Path to the outline-tier JSONL file emitted
            by ``_run_content_generation_outline`` (Subtask 28).
        project_id: Course project slug (used to locate the
            ``synthesized_objectives.json`` for BlockPageObjectivesValidator).

    Outputs (JSON envelope):
        blocks_validated_path: JSONL of Blocks that passed every gate.
        blocks_failed_path: JSONL of Blocks that tripped at least one gate.
        gate_results: Per-gate ``GateResult.to_dict()`` payloads.

    Decision-capture: emits one ``block_validation_action`` event per
    failed validator with ``ml_features.tier="outline"`` so postmortem
    readers can stratify outline-tier vs rewrite-tier failures.
    """
    from pathlib import Path as _Path

    blocks_outline_path_raw = kwargs.get("blocks_outline_path") or ""
    project_id = kwargs.get("project_id") or ""

    if not blocks_outline_path_raw:
        return json.dumps({
            "success": False,
            "error": "blocks_outline_path is required",
        })

    blocks_path = _Path(blocks_outline_path_raw)
    if not blocks_path.exists():
        return json.dumps({
            "success": False,
            "error": f"blocks_outline_path does not exist: {blocks_path}",
        })

    from Courseforge.scripts.blocks import Block  # type: ignore[import-not-found]
    from Courseforge.router.inter_tier_gates import (
        BlockContentTypeValidator,
        BlockCurieAnchoringValidator,
        BlockPageObjectivesValidator,
        BlockSourceRefValidator,
    )

    raw_text = blocks_path.read_text(encoding="utf-8")
    raw_entries: list = []
    try:
        if blocks_path.suffix == ".jsonl":
            for line in raw_text.splitlines():
                line = line.strip()
                if not line:
                    continue
                raw_entries.append(json.loads(line))
        else:
            parsed = json.loads(raw_text)
            if isinstance(parsed, list):
                raw_entries = parsed
            elif isinstance(parsed, dict):
                raw_entries = parsed.get("blocks", []) or []
    except json.JSONDecodeError as exc:
        return json.dumps({
            "success": False,
            "error": f"failed to parse {blocks_path}: {exc}",
        })

    def _entry_to_block(entry: dict) -> Optional["Block"]:  # type: ignore[name-defined]
        accepted = {
            "block_id", "block_type", "page_id", "sequence", "content",
            "template_type", "key_terms", "objective_ids",
            "bloom_level", "bloom_verb", "bloom_range",
            "bloom_levels", "bloom_verbs", "cognitive_domain",
            "teaching_role", "content_type_label", "purpose",
            "component", "source_ids", "source_primary",
            "source_references", "content_hash",
            "validation_attempts", "escalation_marker",
            "anchored_rubric",
            "interaction_type", "fade_state",
        }
        kwargs_clean: dict = {}
        for k, v in (entry or {}).items():
            if k not in accepted:
                continue
            if k in {
                "key_terms", "objective_ids", "bloom_levels",
                "bloom_verbs", "source_ids", "source_references",
            }:
                if isinstance(v, list):
                    v = tuple(v) if k != "source_references" else tuple(
                        dict(r) if isinstance(r, dict) else r for r in v
                    )
            kwargs_clean[k] = v
        if "block_id" not in kwargs_clean or "block_type" not in kwargs_clean:
            return None
        kwargs_clean.setdefault("page_id", kwargs_clean.get("block_id", ""))
        kwargs_clean.setdefault("sequence", 0)
        kwargs_clean.setdefault("content", "")
        _touches = _touches_from_entry(entry or {})
        if _touches:
            kwargs_clean["touched_by"] = _touches
        try:
            return Block(**kwargs_clean)
        except (TypeError, ValueError) as exc:
            logger.warning(
                "inter_tier_validation: skipping malformed block entry "
                "block_id=%r: %s",
                entry.get("block_id"),
                exc,
            )
            return None

    blocks: list = []
    for entry in raw_entries:
        if not isinstance(entry, dict):
            continue
        blk = _entry_to_block(entry)
        if blk is not None:
            blocks.append(blk)

    if not blocks:
        return json.dumps({
            "success": False,
            "error": (
                f"no blocks parseable from {blocks_path}; expected JSON-LD "
                f"shape with at least one Block-shaped entry"
            ),
        })

    # Resolve canonical objectives JSON for BlockPageObjectivesValidator.
    objectives_path: Optional[_Path] = None
    if project_id:
        candidate = (
            courseforge_exports_dir()
            / project_id
            / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        if candidate.exists():
            objectives_path = candidate

    validators = [
        ("outline_curie_anchoring", BlockCurieAnchoringValidator()),
        ("outline_content_type", BlockContentTypeValidator()),
        ("outline_page_objectives", BlockPageObjectivesValidator()),
        ("outline_source_refs", BlockSourceRefValidator()),
    ]

    inputs: dict = {"blocks": blocks}
    if objectives_path is not None:
        inputs["objectives_path"] = str(objectives_path)

    # FIX 1b: thread the per-block grounded source-chunk universe (the
    # ``outline_chunks.json`` sidecar written next to blocks_outline.jsonl
    # by _run_content_generation_outline) so BlockCurieAnchoringValidator
    # can anchor a minted CURIE via its concept's surface form appearing
    # in the block's REAL provenance, not only its key_claims prose.
    # Absent / unreadable sidecar → no-op (anchoring runs over key_claims
    # only; ungrounded blocks still fail closed).
    source_chunks_sidecar = blocks_path.parent / "outline_chunks.json"
    if source_chunks_sidecar.exists():
        try:
            sc_map = json.loads(
                source_chunks_sidecar.read_text(encoding="utf-8")
            )
            if isinstance(sc_map, dict):
                inputs["source_chunks_by_block_id"] = sc_map
        except (OSError, ValueError) as exc:
            logger.warning(
                "inter_tier_validation: failed to load outline_chunks.json "
                "sidecar at %s (%s); CURIE anchoring runs over key_claims "
                "only.",
                source_chunks_sidecar, exc,
            )

    # v0.3.0 dynamic CURIE minting: thread the per-course minted-CURIE
    # map into the gate inputs so BlockCurieAnchoringValidator can
    # anchor a minted (prose-corpus) CURIE via its vocabulary surface
    # forms. No-op when no domain_concept_vocabulary.json exists (RDF /
    # legacy corpora) — _resolve_minted_curie_map_for_validation returns
    # None and the validator runs legacy literal-token anchoring.
    minted_curie_map = _resolve_minted_curie_map_for_validation(
        project_id=project_id, kwargs=kwargs,
    )
    if minted_curie_map:
        inputs["minted_curie_map"] = minted_curie_map

    # Objective-refs-concept anchoring: thread the {objective_id: statement}
    # map so a minted CURIE anchors when its concept surface form appears in
    # a declared objective's statement. No-op when objectives_path is
    # absent / unparseable.
    _obj_statements = _load_objective_statements_from_path(objectives_path)
    if _obj_statements:
        inputs["objective_statements"] = _obj_statements

    gate_results: list = []
    failing_gate_ids: set = set()
    for gate_id, validator in validators:
        # Graceful stop (checkpoint on command): non-LLM validator loop, so a
        # stop here just pauses cleanly between validator units (no work to
        # lose). Aggregated ``gate_results`` are re-derivable on resume.
        check_stop("inter_tier_validation", len(gate_results))
        try:
            result = validator.validate({**inputs, "gate_id": gate_id})
        except Exception as exc:  # pragma: no cover — defensive
            logger.warning(
                "inter_tier_validation: validator %s raised: %s",
                gate_id, exc,
            )
            continue
        try:
            result_dict = result.to_dict()
        except Exception:  # pragma: no cover — defensive
            result_dict = {
                "gate_id": gate_id,
                "passed": getattr(result, "passed", False),
                "issues": [],
            }
        gate_results.append(result_dict)
        if not result.passed:
            failing_gate_ids.add(gate_id)

    # Decision-capture: emit per-failure block_validation_action events
    # with ml_features.tier="outline" so postmortem reader can stratify
    # outline-tier vs rewrite-tier failures (Subtask 26 surface).
    if failing_gate_ids:
        try:
            from lib.decision_capture import DecisionCapture
            capture = DecisionCapture(
                course_code=project_id or "inter_tier_validation",
                phase="inter_tier_validation",
                tool="courseforge",
                streaming=True,
            )
            for result_dict in gate_results:
                if result_dict.get("passed"):
                    continue
                gate_id = result_dict.get("gate_id", "unknown_gate")
                issues = result_dict.get("issues", []) or []
                top_issues = issues[:3]
                summary = "; ".join(
                    f"{i.get('code','?')}({i.get('severity','?')}):"
                    f"{i.get('message','')}"
                    for i in top_issues
                ) or "no_issues"
                capture.log_decision(
                    decision_type="block_validation_action",
                    decision=(
                        f"inter_tier_validation:{gate_id}:"
                        f"{result_dict.get('passed')}"
                    ),
                    rationale=(
                        f"Inter-tier gate {gate_id} returned "
                        f"passed={result_dict.get('passed')} on "
                        f"{len(blocks)} outline-tier blocks; "
                        f"top_issues=[{summary}]"
                    ),
                    ml_features={
                        "gate_id": gate_id,
                        "passed": result_dict.get("passed"),
                        "issues_count": len(issues),
                        "block_count": len(blocks),
                        # Subtask 26: tier provenance — outline-tier
                        # in-loop validator failure (vs rewrite-tier
                        # post-emit failures handled by post_rewrite_validation).
                        "tier": "outline",
                    },
                )
        except Exception as exc:  # pragma: no cover — defensive
            logger.warning(
                "inter_tier_validation: decision-capture emit failed: %s",
                exc,
            )

    out_dir = blocks_path.parent
    validated_path = out_dir / "blocks_validated.jsonl"
    failed_path = out_dir / "blocks_failed.jsonl"

    failed_block_ids: set = set()
    for result_dict in gate_results:
        if result_dict.get("passed"):
            continue
        for issue in result_dict.get("issues", []) or []:
            loc = issue.get("location") if isinstance(issue, dict) else None
            if isinstance(loc, str) and loc:
                failed_block_ids.add(loc)

    # Escalated blocks ride through to validated_path regardless of
    # validator outcome — they are marker-bearing by design (Wave-7
    # escalate_immediately) and the rewrite phase needs to see them to
    # author from scratch. Without this, blocks_validated.jsonl is empty
    # when the corpus is all-objective and the workflow halts.
    with validated_path.open("w", encoding="utf-8") as fh:
        for blk in blocks:
            if blk.block_id in failed_block_ids and blk.escalation_marker is None:
                continue
            fh.write(json.dumps(
                _block_to_snake_case_entry(blk), ensure_ascii=False,
            ))
            fh.write("\n")
    with failed_path.open("w", encoding="utf-8") as fh:
        for blk in blocks:
            if blk.block_id not in failed_block_ids:
                continue
            if blk.escalation_marker is not None:
                continue
            # Stamp a REAL failure_reason (was implicitly null) — the failing
            # gate(s) located at this block + the regen attempts consumed. For
            # a CURIE-preservation miss the gate message carries the dropped
            # tokens; for other gates the code+message head is the failure
            # class. Additive field, never breaks a reader.
            _failed_entry = _block_to_snake_case_entry(blk)
            _failed_entry["failure_reason"] = _compose_block_failure_reason(
                blk, gate_results
            )
            fh.write(json.dumps(_failed_entry, ensure_ascii=False))
            fh.write("\n")

    return json.dumps({
        "success": True,
        "blocks_validated_path": str(validated_path),
        "blocks_failed_path": str(failed_path),
        "gate_results": gate_results,
        "block_count": len(blocks),
        "failed_block_count": len(failed_block_ids),
    })


# -------------------------------------------------------------------------- #
# W3 — per-block synthesis-manifest emission                                  #
# -------------------------------------------------------------------------- #


def _build_manifest_chunk_resolver(
    dart_chunks_path: Optional[Path],
) -> Callable[[str], Optional[Dict[str, Any]]]:
    """Build the ``resolver`` ``Block.to_synthesis_manifest`` consumes (W3 §1.3).

    Reads the pinned DART chunkset ``chunks.jsonl`` and maps every outline
    ``sourceId`` (the ``dart:{slug}#{block_id}`` shape) AND every chunk
    top-level ``id`` to a resolution record::

        {"id": <chunk_id>, "char_span": [start, end]?, "html_xpath": <xpath>?}

    so the manifest's ``source_chunk_ids[]`` resolve and ``char_spans[]`` lift
    the chunk's own ``source.char_span`` / ``source.html_xpath`` (whole-chunk
    reference today; ``span_granularity="chunk"``). Mirrors the harvest contract
    of ``objective_source_refs._load_dart_chunks_universe`` (chunk ``id`` ∪
    ``source.source_references[].sourceId``) so the emit-side resolver and the
    validate-side universe agree on what resolves.

    A ``sourceId`` that isn't in the chunkset resolves to ``None`` — the
    projection keeps it verbatim in ``source_refs[]`` but omits it from
    ``source_chunk_ids[]``, and ``ManifestCompletenessValidator`` catches the
    resulting gap on a substantive block.

    Best-effort: a missing / unreadable chunkset yields an empty map (every
    sourceId resolves to ``None``); the validator's
    ``MANIFEST_RESOLUTION_UNIVERSE_EMPTY`` guard catches a vacuous universe at
    gate time.
    """
    id_to_record: Dict[str, Dict[str, Any]] = {}
    if dart_chunks_path is not None and dart_chunks_path.exists():
        try:
            with dart_chunks_path.open("r", encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        chunk = json.loads(line)
                    except ValueError:
                        continue
                    if not isinstance(chunk, dict):
                        continue
                    chunk_id = chunk.get("id")
                    if not isinstance(chunk_id, str) or not chunk_id.strip():
                        continue
                    chunk_id = chunk_id.strip()
                    source = chunk.get("source")
                    record: Dict[str, Any] = {"id": chunk_id}
                    # Capture the chunk's own concept_tags + text so the
                    # emit side can ground each block's concept_tags in its
                    # cited chunks (W3: block tags grounded in cited chunks).
                    # ONE chunkset read serves both span resolution and tags.
                    raw_tags = chunk.get("concept_tags")
                    if isinstance(raw_tags, list):
                        record["concept_tags"] = [
                            t for t in raw_tags if isinstance(t, str) and t
                        ]
                    chunk_text = chunk.get("text")
                    if isinstance(chunk_text, str) and chunk_text:
                        record["text"] = chunk_text
                    if isinstance(source, dict):
                        cspan = source.get("char_span")
                        if (
                            isinstance(cspan, (list, tuple))
                            and len(cspan) == 2
                            and all(isinstance(x, int) for x in cspan)
                        ):
                            record["char_span"] = [int(cspan[0]), int(cspan[1])]
                        xpath = source.get("html_xpath")
                        if isinstance(xpath, str) and xpath:
                            record["html_xpath"] = xpath
                    # Register under the chunk's own id...
                    id_to_record.setdefault(chunk_id, record)
                    # ...and under every dart:{slug}#{block_id} sourceId so an
                    # outline source_refs[].sourceId resolves to this chunk.
                    if isinstance(source, dict):
                        src_refs = source.get("source_references") or []
                        if isinstance(src_refs, list):
                            for ref in src_refs:
                                if not isinstance(ref, dict):
                                    continue
                                sid = ref.get("sourceId")
                                if isinstance(sid, str) and sid.strip():
                                    id_to_record.setdefault(sid.strip(), record)
        except OSError as exc:
            logger.warning(
                "block_synthesis_manifest: failed to read chunks.jsonl at "
                "%s: %s",
                dart_chunks_path,
                exc,
            )

    def _resolver(source_id: str) -> Optional[Dict[str, Any]]:
        if not isinstance(source_id, str):
            return None
        return id_to_record.get(source_id.strip())

    return _resolver


def _derive_block_concept_tags(
    cited_chunk_ids: List[str],
    resolver: Callable[[str], Optional[Dict[str, Any]]],
) -> List[str]:
    """Union the cited chunks' concept_tags (W3: block tags grounded in chunks).

    For each of a block's resolved ``source_chunk_ids``, look the chunk up via
    the resolver (built from the same chunkset — one read) and collect its
    ``concept_tags``. A cited chunk that carries no tags falls back to
    ``lib.ontology.concept_tagging.extract_concept_tags`` over the chunk's own
    ``text`` (instance-free, empty seeds), so the derived tags trace to the
    chunk's actual prose rather than being invented. The union is order-stable
    (first-seen wins), deduped, and capped at ``MAX_CONCEPT_TAGS``.

    Honest empties: a block whose cited chunks yield no taggable concept (no
    pre-tagged chunk, no taggable text) returns ``[]`` — never a fabricated
    tag.
    """
    from lib.ontology.concept_tagging import MAX_CONCEPT_TAGS, extract_concept_tags

    tags: List[str] = []
    seen: set = set()

    def _add(tag: str) -> None:
        if tag and tag not in seen:
            seen.add(tag)
            tags.append(tag)

    for cid in cited_chunk_ids:
        if not isinstance(cid, str) or not cid:
            continue
        record = resolver(cid)
        if not isinstance(record, dict):
            continue
        existing = record.get("concept_tags")
        if isinstance(existing, list) and existing:
            for t in existing:
                if isinstance(t, str):
                    _add(t)
            continue
        # No pre-computed tags on the chunk — derive them from its own text so
        # the block's tags stay grounded in the cited source (no invention).
        text = record.get("text")
        if isinstance(text, str) and text.strip():
            try:
                for t in extract_concept_tags(text, {}, ()):
                    if isinstance(t, str):
                        _add(t)
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "block_synthesis_manifest: extract_concept_tags fallback "
                    "failed for chunk_id=%s: %s",
                    cid,
                    exc,
                )

    return tags[:MAX_CONCEPT_TAGS]


def _emit_block_synthesis_manifest(
    blocks: List[Any],
    content_dir: Path,
    dart_chunks_path: Optional[Path],
    capture: Any = None,
) -> Optional[Path]:
    """Write the per-block synthesis-manifest sidecar JSONL (W3 §1.3a).

    One ``block_synthesis_manifest.jsonl`` line per finalized block, in
    emission order, at ``<content_dir>/block_synthesis_manifest.jsonl``. Each
    line is the pure ``Block.to_synthesis_manifest(resolver)`` projection — no
    LLM call, no model/provider re-log (read from the Touch chain).

    Gated by ``COURSEFORGE_EMIT_BLOCKS`` (the same flag that gates the JSON-LD
    ``blocks[]`` projection + the ``synthesisManifestRef`` pointer): when the
    flag is off the manifest is NOT written and legacy emit stays byte-stable.

    Idempotent: when the sidecar already exists (a ``--force`` re-run or a
    resumed stage subcommand) the existing file is left untouched and returned,
    mirroring the ``course.json`` emit pattern (anti-clobber).

    Returns the manifest path when written / already-present, else ``None``
    (flag off, no blocks, or write failure).
    """
    from Courseforge.scripts.blocks import _emit_blocks_enabled

    if not _emit_blocks_enabled():
        return None
    if not blocks:
        return None

    manifest_path = content_dir / "block_synthesis_manifest.jsonl"
    if manifest_path.exists():
        # Anti-clobber: a previous run already emitted the sidecar. Leave it
        # byte-identical (mirrors _project_synthesized_objectives_to_course_json).
        logger.info(
            "block_synthesis_manifest: %s already exists; leaving untouched "
            "(idempotent re-emit).",
            manifest_path,
        )
        return manifest_path

    resolver = _build_manifest_chunk_resolver(dart_chunks_path)

    lines: List[str] = []
    resolved_total = 0
    tagged_total = 0
    for blk in blocks:
        # Skip escalation-marked blocks: a block that exhausted its regen
        # budget / failed validator consensus did NOT undergo successful
        # synthesis, so it carries no complete provenance manifest to emit
        # (its touch chain is the outline draft, its content may be the raw
        # degraded dict). Emitting a partial manifest line for it would fail
        # MANIFEST_SCHEMA_INVALID (empty synthesis.tiers / malformed shape).
        # The validation report already classifies these as ``escalated``,
        # not ``failed``; the manifest mirrors that — escalated blocks are
        # excluded from the synthesized-block manifest rather than emitted
        # incomplete. (Fail-closed is preserved: a substantive block with no
        # synthesis still emits + fails; only marker-bearing escalations skip.)
        if getattr(blk, "escalation_marker", None):
            continue
        # W3: ground this block's concept_tags in its CITED chunks BEFORE the
        # projection (which reads content["concept_tags"]). Project once to
        # learn the resolved cited chunk ids, then union the cited chunks'
        # existing concept_tags (falling back to extract_concept_tags on the
        # chunk text for any cited chunk that carries none). Only thread when
        # the block hasn't already pinned its own tags — invented tags are
        # forbidden; every tag traces to a cited chunk.
        try:
            record = blk.to_synthesis_manifest(resolver)
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "block_synthesis_manifest: projection failed for block_id=%s: "
                "%s",
                getattr(blk, "block_id", "?"),
                exc,
            )
            continue
        # W3: pass derived concept_tags to the projection EXPLICITLY — rewrite-
        # tier blocks carry self.content as an HTML STRING, so the content-dict
        # threading path never fires for them. Derive from the block's already-
        # resolved cited chunks (grounded; never invented) unless the block /
        # content already pinned tags.
        if not record.get("concept_tags"):
            block_tags = _derive_block_concept_tags(
                record.get("source_chunk_ids") or [], resolver
            )
            if block_tags:
                try:
                    record = blk.to_synthesis_manifest(
                        resolver, concept_tags=block_tags
                    )
                except Exception as exc:  # noqa: BLE001
                    logger.warning(
                        "block_synthesis_manifest: re-projection failed for "
                        "block_id=%s: %s",
                        getattr(blk, "block_id", "?"),
                        exc,
                    )
        if record.get("concept_tags"):
            tagged_total += 1
        resolved_total += len(record.get("source_chunk_ids") or [])
        lines.append(json.dumps(record, ensure_ascii=False))

    if not lines:
        return None

    try:
        content_dir.mkdir(parents=True, exist_ok=True)
        manifest_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    except OSError as exc:
        logger.warning(
            "block_synthesis_manifest: failed to write %s: %s",
            manifest_path,
            exc,
        )
        return None

    if capture is not None:
        try:
            capture.log_decision(
                decision_type="block_synthesis_manifest_emitted",
                decision=(
                    f"Wrote {len(lines)} manifest line(s) to "
                    f"{manifest_path.name}."
                ),
                rationale=(
                    f"W3 per-block provenance manifest: projected "
                    f"{len(lines)} finalized block(s) into "
                    f"block_synthesis_manifest.jsonl with "
                    f"{resolved_total} resolved source_chunk_id reference(s) "
                    f"against the pinned DART chunkset; "
                    f"{tagged_total} block(s) carry chunk-grounded "
                    f"concept_tags (union of cited chunks' tags, "
                    f"extract_concept_tags fallback); sidecar consumed by "
                    f"ManifestCompletenessValidator (RESOLUTION) + W4 NLI "
                    f"(ENTAILMENT premise selection)."
                ),
            )
        except Exception:  # noqa: BLE001
            pass

    return manifest_path


def _evict_rewrite_cache_by_block_type(
    rewrite_cache: Dict[str, dict],
    outline_blocks: Sequence[Any],
    target_block_types: Set[str],
) -> int:
    """Additively evict cached rewrites whose ``block_type`` is targeted.

    Phase 5 ST 1 (``--blocks``). Deletes from ``rewrite_cache`` (keyed by
    ``block_id``) every entry belonging to an outline block whose
    ``block_type`` is in ``target_block_types``, so those blocks re-author
    this pass even after a prior successful rewrite. Returns the number of
    entries removed. An empty target set (the unset-flag default) or an
    empty cache is a no-op returning 0 — the pure failure-driven reuse path
    stays byte-identical. Purely additive: it never adds cache entries, only
    removes named-type ones, so out-of-scope blocks keep byte-identical reuse.
    """
    if not target_block_types or not rewrite_cache:
        return 0
    evicted_ids = {
        str(getattr(b, "block_id", "") or "")
        for b in outline_blocks
        if str(getattr(b, "block_type", "") or "") in target_block_types
    }
    removed = 0
    for bid in evicted_ids:
        if bid in rewrite_cache:
            del rewrite_cache[bid]
            removed += 1
    return removed


def _page_membership_match(page_id: str, token: str) -> bool:
    """True when ``token`` names ``page_id`` exactly or as its module prefix.

    Page ids are ``week_NN_<type>`` / ``week_NN_content_NN`` (see
    :func:`_page_id_for`). A ``--pages`` token matches a block when it equals
    the block's ``page_id`` (single-page scope) OR is a hyphen/underscore-
    bounded PREFIX of it (module scope — e.g. ``week_01`` matches
    ``week_01_overview`` and ``week_01_content_02`` but never ``week_010``).
    """
    if not page_id or not token:
        return False
    return page_id == token or page_id.startswith(token + "_")


def _normalize_token_list_param(value: Any) -> List[str]:
    """Normalize a rewrite-eviction token param to a list of clean tokens.

    Param-transport compat. ``WorkflowRunner._route_params`` comma-joins list
    workflow params into a single string when building phase-task params (so
    other tools such as ``pdf_paths`` keep receiving a comma-joined string).
    The three rewrite-eviction token params (``target_block_ids`` /
    ``target_block_instance_ids`` / ``target_page_ids``) therefore reach this
    consumer as a comma-joined STRING, not the original list. Iterating a
    string yields CHARACTERS (the bug that exploded one block id into
    ``['#', '-', '0', ...]``), so the token set must be rebuilt by SPLITTING on
    ',' — never by iterating the value. None of these token shapes
    (``{page_id}#{block_type}_{slug}_{idx}``, ``week_01``, ``objective``) ever
    contains a comma, so ',' is an unambiguous delimiter.

    - ``str`` → split on ',', strip each token, drop empties.
    - ``list``/``tuple``/``set`` → ``str()`` each member, strip, drop empties.
    - ``None`` (unset flag) → ``[]``.
    - any other scalar → single stripped token (defensive; never expected).
    """
    if value is None:
        return []
    if isinstance(value, str):
        return [tok.strip() for tok in value.split(",") if tok.strip()]
    if isinstance(value, (list, tuple, set)):
        out: List[str] = []
        for item in value:
            if item is None:
                continue
            tok = str(item).strip()
            if tok:
                out.append(tok)
        return out
    tok = str(value).strip()
    return [tok] if tok else []


def _evict_rewrite_cache_by_block_id(
    rewrite_cache: Dict[str, dict],
    outline_blocks: Sequence[Any],
    target_block_ids: Set[str],
) -> Tuple[int, List[str]]:
    """Additively evict cached rewrites by EXACT block-instance id.

    I4 stage 2 (``--block-ids``). Deletes from ``rewrite_cache`` (keyed by
    ``block_id``) every entry whose id is named in ``target_block_ids`` so
    that specific block re-authors this pass even after a prior successful
    rewrite. Returns ``(removed_count, unknown_ids)`` — an id not carried by
    any ``outline_blocks`` member is an UNKNOWN and is returned (sorted) in
    the second element so the caller fails LOUD instead of silently
    no-op-ing on an operator typo. An empty target set (the unset-flag
    default) short-circuits to ``(0, [])`` so the pure failure-driven reuse
    path stays byte-identical. Purely additive: it only removes named-id
    entries; out-of-scope blocks keep byte-identical reuse. Validation runs
    against the outline block universe (NOT the cache), so an unknown id is
    caught even on a first pass with no cache on disk.
    """
    if not target_block_ids:
        return 0, []
    known_ids = {
        str(getattr(b, "block_id", "") or "") for b in outline_blocks
    }
    known_ids.discard("")
    unknown = sorted(t for t in target_block_ids if t not in known_ids)
    removed = 0
    for bid in target_block_ids:
        if bid in rewrite_cache:
            del rewrite_cache[bid]
            removed += 1
    return removed, unknown


def _evict_rewrite_cache_by_page(
    rewrite_cache: Dict[str, dict],
    outline_blocks: Sequence[Any],
    target_page_ids: Set[str],
) -> Tuple[int, List[str]]:
    """Additively evict cached rewrites by page/module membership.

    I4 stage 2 (``--pages``). Deletes from ``rewrite_cache`` every entry
    belonging to an outline block whose ``page_id`` matches one of
    ``target_page_ids`` (exact page id OR module prefix — see
    :func:`_page_membership_match`), so a whole page/module re-authors this
    pass even after prior successful rewrites. Returns ``(removed_count,
    unknown_pages)`` — a page token that matches NO outline block is an
    UNKNOWN and is returned (sorted) so the caller fails LOUD. Empty target
    set → ``(0, [])`` (byte-identical failure-driven reuse). Purely
    additive; validation runs against the outline block universe.
    """
    if not target_page_ids:
        return 0, []
    known_pages = {
        str(getattr(b, "page_id", "") or "") for b in outline_blocks
    }
    known_pages.discard("")
    unknown = sorted(
        tok
        for tok in target_page_ids
        if not any(_page_membership_match(pg, tok) for pg in known_pages)
    )
    evicted_ids = {
        str(getattr(b, "block_id", "") or "")
        for b in outline_blocks
        if any(
            _page_membership_match(
                str(getattr(b, "page_id", "") or ""), tok
            )
            for tok in target_page_ids
        )
    }
    evicted_ids.discard("")
    removed = 0
    for bid in evicted_ids:
        if bid in rewrite_cache:
            del rewrite_cache[bid]
            removed += 1
    return removed, unknown


def _copy_export_assessments(
    export_dir_candidates: Sequence[Path],
    course_dir: Path,
) -> int:
    """Copy a Courseforge export's ``06_assessments/`` into the LibV2 course.

    Q4. Walks ``export_dir_candidates`` in order; the first one that has a
    real ``06_assessments/`` directory is the source. Copies every top-level
    ``.xml`` (QTI / imsdt / assignment) + ``.json`` (manifest) file into
    ``<course_dir>/06_assessments/`` so ``gui/services/quiz_service.py`` (which
    scans ``LibV2/courses/<slug>/06_assessments/*.xml``) can surface them.
    Returns the number of files copied. No candidate carries the dir (the
    assessment_synthesis phase was skipped / never ran) → returns 0 and
    writes nothing — a clean no-op, never an error.
    """
    src: Optional[Path] = None
    for cand in export_dir_candidates:
        maybe = cand / "06_assessments"
        if maybe.exists() and maybe.is_dir():
            src = maybe
            break
    if src is None:
        return 0
    dest_dir = course_dir / "06_assessments"
    dest_dir.mkdir(parents=True, exist_ok=True)
    copied = 0
    for af in sorted(src.iterdir()):
        if af.is_file() and af.suffix.lower() in (".xml", ".json"):
            try:
                shutil.copy2(af, dest_dir / af.name)
                copied += 1
            except OSError as exc:
                logger.warning(
                    "archive_to_libv2: failed to copy assessment %s: %s",
                    af, exc,
                )
    return copied


def _build_rewrite_inloop_validators() -> list:
    """Per-candidate validator chain for the rewrite best-of-N loop.

    Book-1 canary keystone fix: the deterministic prose-stutter check runs
    IN-LOOP (per candidate) so phrase-repetition slop is rejected at
    authoring time — a stuttered candidate fires ``action="regenerate"``
    and ``route_rewrite_with_remediation`` / ``route_rewrite_batch``
    re-rolls it — instead of shipping into the retrieval corpus and only
    surfacing at the (warning-severity) ``block_prose_stutter`` gate.

    Deliberately tiny: the standalone ``post_rewrite_validation`` phase
    still owns the full gate chain; only cheap, deterministic,
    high-precision candidate-rejection checks belong here. The validator
    is stateless/pure, so one shared instance is thread-safe under
    ``COURSEFORGE_REWRITE_CONCURRENCY`` fan-out. Fail-soft: an import
    failure degrades to the legacy empty chain (never blocks dispatch).
    """
    try:
        from lib.validators.prose_stutter import (  # noqa: PLC0415
            ProseStutterValidator,
        )
        return [ProseStutterValidator()]
    except Exception as exc:  # noqa: BLE001 — never break the rewrite phase
        logger.warning(
            "rewrite phase: prose-stutter in-loop validator unavailable "
            "(%s); dispatching with the legacy empty chain.", exc,
        )
        return []


async def _run_content_generation_rewrite(**kwargs) -> str:
    """Run the rewrite tier of the Phase 3 two-pass content pipeline.

    Phase 3.5 Subtask 30. Reads the validated outline-tier Blocks from
    ``blocks_validated_path`` (the inter_tier_validation phase output),
    then dispatches each block through :meth:`CourseforgeRouter.route`
    with ``tier="rewrite"``. The rewrite tier is responsible for the
    final HTML body emit; we persist both the per-block JSONL
    (``blocks_final.jsonl``, consumed by post_rewrite_validation) and
    the per-page HTML files (consumed by packaging + content_grounding).

    Inputs (kwargs):
        blocks_validated_path: JSONL of validated outline-tier blocks.
        project_id: Course project slug.
        source_module_map_path: Optional Wave 9 source-routing path.
        staging_dir: Staging directory from stage_dart_outputs.

    Outputs (JSON envelope):
        content_paths: Comma-joined string of emitted HTML paths
            (router canonical key for legacy gate-input parsers).
        page_paths: List of emitted HTML paths.
        content_dir: Directory where pages were written.
        blocks_final_path: JSONL of rewrite-tier Blocks (consumed by
            post_rewrite_validation).
        project_id: Pass-through.
    """
    from pathlib import Path as _Path

    blocks_validated_path_raw = kwargs.get("blocks_validated_path") or ""
    project_id = kwargs.get("project_id") or ""

    if not project_id:
        return json.dumps({
            "success": False,
            "error": "_run_content_generation_rewrite requires project_id",
        })
    if not blocks_validated_path_raw:
        return json.dumps({
            "success": False,
            "error": "blocks_validated_path is required",
        })

    blocks_path = _Path(blocks_validated_path_raw)
    if not blocks_path.exists():
        return json.dumps({
            "success": False,
            "error": f"blocks_validated_path does not exist: {blocks_path}",
        })

    project_path = courseforge_exports_dir() / project_id
    out_dir = project_path / "04_rewrite"
    out_dir.mkdir(parents=True, exist_ok=True)
    content_dir = project_path / "03_content_development"
    content_dir.mkdir(parents=True, exist_ok=True)

    config_path = project_path / "project_config.json"
    config: Dict[str, Any] = {}
    if config_path.exists():
        try:
            config = json.loads(config_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            config = {}
    course_code = config.get("course_name") or project_id

    from Courseforge.scripts.blocks import Block  # noqa: F401

    raw_text = blocks_path.read_text(encoding="utf-8")
    raw_entries: list = []
    try:
        if blocks_path.suffix == ".jsonl":
            for line in raw_text.splitlines():
                line = line.strip()
                if not line:
                    continue
                raw_entries.append(json.loads(line))
        else:
            parsed = json.loads(raw_text)
            if isinstance(parsed, list):
                raw_entries = parsed
            elif isinstance(parsed, dict):
                raw_entries = parsed.get("blocks", []) or []
    except json.JSONDecodeError as exc:
        return json.dumps({
            "success": False,
            "error": f"failed to parse {blocks_path}: {exc}",
        })

    def _entry_to_block(entry: dict) -> Optional["Block"]:  # type: ignore[name-defined]
        accepted = {
            "block_id", "block_type", "page_id", "sequence", "content",
            "template_type", "key_terms", "objective_ids",
            "bloom_level", "bloom_verb", "bloom_range",
            "bloom_levels", "bloom_verbs", "cognitive_domain",
            "teaching_role", "content_type_label", "purpose",
            "component", "source_ids", "source_primary",
            "source_references", "content_hash",
            "validation_attempts", "escalation_marker",
            "anchored_rubric",
            "interaction_type", "fade_state",
        }
        kwargs_clean: dict = {}
        for k, v in (entry or {}).items():
            if k not in accepted:
                continue
            if k in {
                "key_terms", "objective_ids", "bloom_levels",
                "bloom_verbs", "source_ids", "source_references",
            }:
                if isinstance(v, list):
                    v = tuple(v) if k != "source_references" else tuple(
                        dict(r) if isinstance(r, dict) else r for r in v
                    )
            kwargs_clean[k] = v
        if "block_id" not in kwargs_clean or "block_type" not in kwargs_clean:
            return None
        kwargs_clean.setdefault("page_id", kwargs_clean.get("block_id", ""))
        kwargs_clean.setdefault("sequence", 0)
        kwargs_clean.setdefault("content", "")
        # Rehydrate the touch chain so a CACHED block (resume path) carries
        # its synthesis provenance into _emit_block_synthesis_manifest; an
        # empty chain emits synthesis.tiers:[] → MANIFEST_SCHEMA_INVALID.
        _touches = _touches_from_entry(entry or {})
        if _touches:
            kwargs_clean["touched_by"] = _touches
        try:
            return Block(**kwargs_clean)
        except (TypeError, ValueError):
            return None

    outline_blocks: list = []
    for entry in raw_entries:
        if not isinstance(entry, dict):
            continue
        blk = _entry_to_block(entry)
        if blk is not None:
            outline_blocks.append(blk)

    capture = None
    try:
        from lib.decision_capture import DecisionCapture
        capture = DecisionCapture(
            course_code=course_code,
            phase="courseforge-content-generator-rewrite",
            tool="courseforge",
            streaming=True,
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "DecisionCapture init failed in content_generation_rewrite: %s",
            exc,
        )
        capture = None

    try:
        from Courseforge.router.router import CourseforgeRouter
        from Courseforge.router.policy import load_block_routing_policy
        router = CourseforgeRouter(
            capture=capture,
            policy=load_block_routing_policy(),
        )
    except Exception as exc:
        logger.exception(
            "CourseforgeRouter init failed in rewrite phase: %s", exc,
        )
        return json.dumps({
            "success": False,
            "error": f"router init failed: {exc}",
            "project_id": project_id,
        })

    # Rewrite-tier in-loop chain: the standalone post_rewrite_validation
    # phase still owns the FULL gate chain, but the cheap deterministic
    # prose-stutter check (book-1 canary keystone fix) runs per-candidate
    # via ``_build_rewrite_inloop_validators`` so phrase-repetition slop
    # re-rolls at authoring time instead of shipping into the corpus.
    # Each block is dispatched
    # through ``router.route_rewrite_with_remediation`` for its sidecar-
    # rehydrated ``source_chunks`` / ``objectives`` grounding (loaded from
    # the W2-persisted ``outline_chunks.json`` / ``outline_objectives.json``
    # next to ``blocks_outline.jsonl``; the workflow_runner threads the
    # sidecar paths in as kwargs via the YAML ``inputs_from`` block).
    _inloop_validators = _build_rewrite_inloop_validators()
    # Reconstruct the phase_outputs sub-shape the loader helpers expect
    # from the resolved path kwargs the workflow_runner threaded in.
    _phase_outputs_proxy: Dict[str, Any] = {
        "content_generation_outline": {
            "outline_chunks_path": kwargs.get("outline_chunks_path"),
            "outline_objectives_path": kwargs.get("outline_objectives_path"),
        },
    }
    chunks_lookup = _load_outline_chunks(_phase_outputs_proxy, capture)
    objectives_payload = _load_outline_objectives(
        _phase_outputs_proxy, capture,
    )

    # P0 — objective-id -> statement map, loaded ONCE from the project's
    # synthesized_objectives.json (Courseforge synthesized OR LibV2 archive
    # form). Consumed by ``_apply_str_backstops`` to render objective ``<li>``
    # bodies as the LO statement instead of the bare ``CO-NN`` id, and by the
    # per-page objectives ``<ul>`` assembly below. Empty on any read failure —
    # callers fall back to rendering the bare id (never crashes the phase).
    _objective_id_statement_map: Dict[str, str] = {}
    # Finding 9 + 18: also index the FULL objective records (not just the
    # statement) so (a) the page <h1> can be derived from the week's TO/topic
    # title and (b) the overview page can enumerate the TO + ALL its child COs
    # via ``render_objective_list``. ``_to_record_map`` / ``_co_record_map`` are
    # ``{id: {id, statement, terminal_id?, ...}}``. Empty on any read failure.
    _to_record_map: Dict[str, Dict[str, Any]] = {}
    _co_record_map: Dict[str, Dict[str, Any]] = {}
    try:
        _synth_obj_path = (
            project_path / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        if _synth_obj_path.exists():
            _synth_obj_doc = json.loads(
                _synth_obj_path.read_text(encoding="utf-8")
            )
            _objective_id_statement_map = _objective_id_to_statement(
                _synth_obj_doc
            )
            _to_record_map, _co_record_map = _index_objective_records(
                _synth_obj_doc
            )
    except Exception as _obj_exc:  # noqa: BLE001 — best-effort; bare-id fallback
        logger.warning(
            "rewrite phase: could not load objective statements from "
            "synthesized_objectives.json (%s); objective <li> bodies fall "
            "back to the bare id.", _obj_exc,
        )
        _objective_id_statement_map = {}
        _to_record_map = {}
        _co_record_map = {}

    # Resolve the LibV2 dart_chunks/chunks.jsonl for this course and build a
    # ``chunk_id -> [real dart:{module_id}#{hash} sourceId]`` map so the rewrite
    # backstop can stamp REAL, content_grounding-resolvable source refs (the
    # ids live in each chunk's source.source_references[].sourceId) instead of
    # the synthetic ``dart:{course-slug}#{chunk_id}`` mint that never resolved.
    # Hoisted here (before the backstop closure) — the same chunks.jsonl is read
    # again later for the W3 synthesis manifest (different projection).
    _course_slug_for_map = (course_code or project_id).lower().replace(
        "_", "-"
    ).replace(" ", "-")
    # DART->semantik purge Stage 3c: dual-read staged chunkset (semantik ->
    # dart -> corpus) so the rewrite-tier chunk->real-sourceId map resolves on
    # new-name courses instead of failing closed to empty (deferred) attribution.
    from lib.libv2_storage import resolve_staged_chunks_path
    _dart_chunks_path_for_map = resolve_staged_chunks_path(
        _resolve_libv2_root(kwargs.get("libv2_root"))
        / "courses"
        / _course_slug_for_map
    )
    _chunk_source_id_map = _build_chunk_source_id_map(_dart_chunks_path_for_map)
    if capture is not None:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"Built chunk_id->real-sourceId map covering "
                    f"{len(_chunk_source_id_map)} chunk(s) from "
                    f"{_dart_chunks_path_for_map.name}."
                ),
                rationale=(
                    "Rewrite-tier source-ref backstop resolves each block's "
                    "chunk universe to the REAL dart:{module_id}#{hash} "
                    "sourceIds (chunk.source.source_references[].sourceId) "
                    "that content_grounding resolves against the DART staging "
                    "HTML, instead of minting a synthetic dart:{course-slug}#"
                    "{chunk_id} that never resolves. An empty map (missing "
                    "chunkset) makes the backstop fail closed to deferred "
                    "(empty) attribution rather than fabricate a ref."
                ),
                ml_features={
                    "gate_id": "_run_content_generation_rewrite",
                    "chunk_source_id_map_size": len(_chunk_source_id_map),
                    "dart_chunks_path": str(_dart_chunks_path_for_map),
                },
            )
        except Exception:  # noqa: BLE001
            pass

    # ---- Rewrite-tier domain-CURIE minting resources ------------------
    # Build the per-course minted-CURIE map + compiled domain-concept seeds
    # ONCE (the rewrite backstop runs per-block). Mirrors the outline tier's
    # ``_mint_outline_curies`` but operates on the rewrite tier's STR HTML:
    # when the rewrite LLM authored a block with no domain CURIE in its prose
    # (and the displaced-CURIE harvest only recovered bare chunk ids, which
    # are NOT CURIEs and so do not anchor), the backstop matches the block's
    # grounded SOURCE-CHUNK text against the domain vocabulary and injects a
    # REAL minted CURIE (``{prefix}:{concept}``) as a hidden ``data-cf-curie``
    # span — exactly the prose-corpus token ``BlockCurieAnchoringValidator``'s
    # str path can extract + anchor. No vocabulary (RDF / legacy corpus) →
    # every resource is empty and the minting is a complete no-op (the legacy
    # literal-token anchoring path runs unchanged). Anti-fabrication: a block
    # whose source-chunk text matches NO vocabulary concept mints nothing.
    _rewrite_minted_map: Dict[str, Any] = {}
    _rewrite_minted_by_canonical: Dict[str, str] = {}
    _rewrite_domain_seeds: list = []
    try:
        _vocab_path = _locate_domain_concept_vocabulary(course_code, kwargs)
        if _vocab_path is not None:
            _vocabulary = json.loads(_vocab_path.read_text(encoding="utf-8"))
            from lib.ontology.curie_discovery import (
                build_minted_curie_map as _build_minted_curie_map_fn,
                minted_curie_by_canonical as _minted_by_canonical_fn,
            )
            from Trainforge.process_course import (
                compile_domain_concept_seeds as _compile_seeds_fn,
            )
            _rewrite_minted_map = _build_minted_curie_map_fn(
                _vocabulary, course_id=course_code,
            ) or {}
            if _rewrite_minted_map:
                _rewrite_minted_by_canonical = _minted_by_canonical_fn(
                    _rewrite_minted_map,
                )
                _seed_input = [
                    {"id": c.get("canonical"), "aliases": c.get("aliases") or []}
                    for c in (_vocabulary.get("concepts") or [])
                    if isinstance(c, dict) and c.get("canonical")
                ]
                _rewrite_domain_seeds = _compile_seeds_fn(_seed_input)
    except Exception as _curie_exc:  # noqa: BLE001 — best-effort; no-op on fail
        logger.warning(
            "rewrite phase: domain-CURIE minting resources unavailable "
            "(%s); rewrite-tier CURIE backstop falls back to displaced-token "
            "re-attachment only.",
            _curie_exc,
        )
        _rewrite_minted_map = {}
        _rewrite_minted_by_canonical = {}
        _rewrite_domain_seeds = []

    # COURSEFORGE_CURIE_DETERMINISTIC: register the per-course minted-CURIE
    # map on the router so every RewriteProvider it constructs bounds its
    # deterministic CURIE stamp to the vocabulary-resolvable universe (the
    # keys of this map). No-op when the flag is off; a no-op stamp when on
    # without a vocabulary (empty map ⇒ nothing stampable). Set BEFORE any
    # rewrite dispatch so the first ``_get_rewrite_provider`` sees it.
    try:
        router.set_rewrite_minted_map(_rewrite_minted_map or None)
    except Exception as _smm_exc:  # noqa: BLE001 — best-effort; never break dispatch
        logger.warning(
            "rewrite phase: set_rewrite_minted_map failed (%s); "
            "COURSEFORGE_CURIE_DETERMINISTIC stamp will find no minted "
            "tokens (falls back to the retry-ladder path when the flag is off).",
            _smm_exc,
        )

    def _mint_curie_for_str_block(block_chunks: Any) -> List[str]:
        """Mint real domain CURIEs for a rewrite STR block from its chunks.

        Matches the block's grounded SOURCE-CHUNK text against the compiled
        domain-concept seeds and returns the minted ``{prefix}:{concept}``
        CURIE tokens for every matched concept (deduped, discovery order).
        No vocabulary / no seeds / no match → empty list (fail closed, never
        fabricate). The chunk text is the block's real provenance and is
        tagged with the domain vocabulary, so a concept present there is
        genuinely the block's subject (provenance-aware, NOT a relaxation —
        identical contract to ``_mint_outline_curies``' source-chunk arm).
        """
        if not _rewrite_domain_seeds or not _rewrite_minted_by_canonical:
            return []
        if not isinstance(block_chunks, list):
            return []
        text_parts: List[str] = []
        for _entry in block_chunks:
            if isinstance(_entry, dict):
                _txt = _entry.get("text")
                if isinstance(_txt, str) and _txt.strip():
                    text_parts.append(_txt)
        if not text_parts:
            return []
        try:
            from lib.ontology.concept_tagging import (
                extract_concept_tags as _extract_concept_tags_fn,
            )
            matched = _extract_concept_tags_fn(
                "\n".join(text_parts), {}, _rewrite_domain_seeds,
            )
        except Exception:  # noqa: BLE001
            return []
        out: List[str] = []
        for _canon in matched:
            _curie = _rewrite_minted_by_canonical.get(_canon)
            if _curie and _curie not in out:
                out.append(_curie)
        return out

    def _mint_curie_for_str_block_prose(prose_text: str) -> List[str]:
        """Mint real domain CURIEs for a rewrite STR block from its OWN prose.

        Provenance-aware fallback for the source-chunk minter above: when a
        block resolves NO grounded source chunks (or its chunk text matches no
        vocabulary concept), match the block's OWN rewrite-authored,
        HTML-stripped prose against the compiled domain-concept seeds. This is
        the SAME anchoring surface ``BlockCurieAnchoringValidator``'s str path
        would accept via the threaded ``minted_curie_map`` — a concept surface
        form present in the block's published prose means the block genuinely
        discusses that concept, so minting its CURIE is honest (NOT a
        relaxation; identical to the validator's surface-form anchoring
        contract). No vocabulary / no seeds / no match → empty list (fail
        closed, never fabricate — a block whose prose names no domain concept
        mints nothing and still fails the gate honestly).
        """
        if not _rewrite_domain_seeds or not _rewrite_minted_by_canonical:
            return []
        if not isinstance(prose_text, str) or not prose_text.strip():
            return []
        try:
            from lib.ontology.concept_tagging import (
                extract_concept_tags as _extract_concept_tags_fn,
            )
            matched = _extract_concept_tags_fn(
                prose_text, {}, _rewrite_domain_seeds,
            )
        except Exception:  # noqa: BLE001
            return []
        out: List[str] = []
        for _canon in matched:
            _curie = _rewrite_minted_by_canonical.get(_canon)
            if _curie and _curie not in out:
                out.append(_curie)
        return out

    # Canonical objective id set (from the W2 outline_objectives.json sidecar,
    # a flat list of ``{id, ...}`` entries) so the rewrite_page_objectives
    # backstop can STRIP-UNKNOWN any data-cf-objective-id value the 7B
    # hallucinated (e.g. a week_27 TO-27/CO-27 not in the canonical set).
    _canonical_objective_ids: set = set()
    if isinstance(objectives_payload, list):
        for _entry in objectives_payload:
            if isinstance(_entry, dict):
                _oid = _entry.get("id") or _entry.get("objective_id")
                if isinstance(_oid, str) and _oid:
                    _canonical_objective_ids.add(_oid)

    # Load source_module_map for page-level source attribution so the
    # rewrite-phase backstop can synthesize per-block source CURIEs both
    # at the block.content level AND at the per-page section wrapper.
    _source_map: Dict[str, Any] = {}
    _source_map_path = project_path / "source_module_map.json"
    if _source_map_path.exists():
        try:
            _source_map = json.loads(
                _source_map_path.read_text(encoding="utf-8")
            )
        except (OSError, ValueError):
            _source_map = {}

    def _page_source_ids(page_id: str) -> list:
        parts = page_id.split("_")
        if len(parts) < 3:
            return []
        week_key = "_".join(parts[:2])
        rest = "_".join(parts[2:])
        week = _source_map.get(week_key, {})
        if not isinstance(week, dict):
            return []
        page_entry = week.get(rest, {})
        if not page_entry and "_" in rest:
            page_entry = week.get(rest.rsplit("_", 1)[0], {})
        if not isinstance(page_entry, dict):
            return []
        sids = list(page_entry.get("primary") or [])
        sids.extend(page_entry.get("contributing") or [])
        seen: set = set()
        out: list = []
        for sid in sids:
            if sid not in seen:
                seen.add(sid)
                out.append(sid)
        return out

    # Route EVERY block through rewrite, including marker-bearing blocks
    # (Wave-7 escalate_immediately) — the rewrite tier authors them from
    # scratch as HTML. The in-loop chain carries ONLY the deterministic
    # prose-stutter candidate check (``_inloop_validators``); the backstop
    # below post-processes the Qwen output (canonical objective IDs +
    # CURIE injection) and the post_rewrite_validation phase runs the
    # full validator chain on the corrected content.
    # Per-block rewrite cache (resume optimization). A prior attempt that was
    # killed/crashed mid-phase leaves a partial ``blocks_final.jsonl`` on disk.
    # Reuse its SUCCESSFUL rewrites (real string content, no escalation marker)
    # so a resume only re-runs the blocks that failed or never completed — not
    # the whole set. Degraded blocks are deliberately NOT cached, so they get
    # another attempt. This makes resumes cheap and stops the slow local 7B
    # from re-authoring already-good blocks.
    _blocks_final_path_cache = out_dir / "blocks_final.jsonl"
    _rewrite_cache: Dict[str, dict] = {}
    if _blocks_final_path_cache.exists():
        try:
            for _cl in _blocks_final_path_cache.read_text(
                encoding="utf-8"
            ).splitlines():
                _cl = _cl.strip()
                if not _cl:
                    continue
                _ce = json.loads(_cl)
                if not isinstance(_ce, dict):
                    continue
                _bid = _ce.get("block_id")
                if (
                    _bid
                    and not _ce.get("escalation_marker")
                    and isinstance(_ce.get("content"), str)
                    and _ce.get("content", "").strip()
                ):
                    _rewrite_cache[_bid] = _ce
        except (OSError, ValueError):
            _rewrite_cache = {}

    # ------------------------------------------------------------------ #
    # Append-as-you-go crash-resume checkpoint (rewrite tier).
    # ------------------------------------------------------------------ #
    # The existing ``_rewrite_cache`` above only resumes from the FINAL
    # ``blocks_final.jsonl`` — which is written once at the very end, so a
    # mid-loop kill leaves NOTHING to resume from. The dot-prefixed
    # ``.blocks_final_checkpoint.jsonl`` sidecar is flushed per successfully-
    # rewritten block, so an interrupted rewrite loop is also resumable.
    # Merge its successful entries into ``_rewrite_cache`` (the loop already
    # skips dispatch for every cache hit). Default ON; OFF (or no sidecar) →
    # byte-identical to the prior blocks_final.jsonl-only resume.
    _rewrite_checkpoint_on = _checkpoint_enabled(
        _COURSEFORGE_REWRITE_CHECKPOINT_ENV
    )
    _rewrite_checkpoint_path = out_dir / _REWRITE_CHECKPOINT_NAME
    # ``--force`` (courseforge-rewrite stage subcommand) WINS over the crash
    # sidecar: clear it and skip the merge so a forced re-roll never
    # rehydrates a prior attempt's blocks from the sidecar. (The separate
    # ``blocks_final.jsonl`` cache above is UNTOUCHED — the ``--blocks``
    # byte-identity contract for out-of-scope blocks depends on it.) Fresh
    # rewrites still checkpoint (crash safety on the forced run itself).
    _rewrite_force_rerun = bool(kwargs.get("force_rerun"))
    if _rewrite_force_rerun:
        _remove_block_checkpoint(_rewrite_checkpoint_path)
        logger.info(
            "rewrite phase: --force cleared the resume sidecar %s.",
            _rewrite_checkpoint_path,
        )
    # Per-block INPUT fingerprints (shared llm_checkpoint discipline). A
    # sidecar entry is merged into the reuse cache ONLY when its stamped
    # fingerprint matches the recomputed one for the same block_id — so a
    # model/provider swap, changed source chunks/objectives, or changed
    # serving-window knobs between resume attempts re-authors instead of
    # silently reusing a stale rewrite. Entries with NO stamp (pre-upgrade
    # sidecars) keep the legacy block_id-only reuse (back-compat).
    _rewrite_objectives_sha = _objectives_payload_sha(objectives_payload)
    _rewrite_fp_by_id: Dict[str, str] = {}
    if _rewrite_checkpoint_on:
        for _ob_fp in outline_blocks:
            _ob_bid = str(getattr(_ob_fp, "block_id", "") or "")
            if _ob_bid:
                _rewrite_fp_by_id[_ob_bid] = _tier_block_fingerprint(
                    _ob_fp,
                    tier="rewrite",
                    chunks_lookup=chunks_lookup,
                    objectives_sha=_rewrite_objectives_sha,
                    router=router,
                )
    _n_rewrite_checkpoint_resumed = 0
    _n_rewrite_checkpoint_stale = 0
    if _rewrite_checkpoint_on and not _rewrite_force_rerun:
        for _bid, _ce in _load_block_checkpoint(
            _rewrite_checkpoint_path
        ).items():
            if (
                not _ce.get("escalation_marker")
                and isinstance(_ce.get("content"), str)
                and _ce.get("content", "").strip()
                and _bid not in _rewrite_cache
            ):
                _stamped_fp = _ce.get(_BLOCK_CHECKPOINT_FP_KEY)
                if (
                    _stamped_fp is not None
                    and _stamped_fp != _rewrite_fp_by_id.get(_bid)
                ):
                    # Stale: inputs / model changed since the entry was
                    # written → drop it so the block re-authors.
                    _n_rewrite_checkpoint_stale += 1
                    continue
                _rewrite_cache[_bid] = _ce
                _n_rewrite_checkpoint_resumed += 1
    if _n_rewrite_checkpoint_stale:
        logger.info(
            "rewrite phase: dropped %d stale sidecar entr%s (input "
            "fingerprint mismatch — block re-authors).",
            _n_rewrite_checkpoint_stale,
            "y" if _n_rewrite_checkpoint_stale == 1 else "ies",
        )

    # Phase 5 ST 1 (--blocks) — ADDITIVE type-eviction over the
    # failure-driven reuse cache above. When ``target_block_ids`` names one
    # or more block TYPES (not ids), every cached (previously-successful)
    # block whose ``block_type`` is in the set is evicted from
    # ``_rewrite_cache`` so it re-rolls this pass; blocks of every other
    # type keep their byte-identical cache reuse. Unset (the default) → no
    # eviction → byte-identical to the pure failure-driven resume. Purely
    # additive: never widens what is reused, only forces a re-author of the
    # named types on top of the existing failed/degraded re-roll.
    # Consumer-side re-split: this param arrives comma-joined (a STRING) from
    # WorkflowRunner._route_params, or as a list on direct/mailbox calls —
    # _normalize_token_list_param handles both (never iterate the raw value).
    _target_block_types = set(
        _normalize_token_list_param(kwargs.get("target_block_ids"))
    )
    _n_evicted = _evict_rewrite_cache_by_block_type(
        _rewrite_cache, outline_blocks, _target_block_types,
    )
    if _n_evicted:
        logger.info(
            "rewrite phase: --blocks %s evicted %d cached block(s) of the "
            "named type(s); they re-author this pass (other types reused).",
            sorted(_target_block_types), _n_evicted,
        )
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"--blocks type-eviction: re-rolling {_n_evicted} "
                        f"cached block(s) of type(s) "
                        f"{sorted(_target_block_types)} despite a prior "
                        "successful rewrite."
                    ),
                    rationale=(
                        "Operator passed --blocks to force a re-author of "
                        f"the named block type(s) {sorted(_target_block_types)}"
                        "; additive eviction drops their blocks_final.jsonl "
                        "cache entries so they re-roll while every other "
                        "block stays byte-identical to the input."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "target_block_types": sorted(_target_block_types),
                        "evicted_blocks": _n_evicted,
                    },
                )
            except Exception:  # noqa: BLE001
                pass

    # I4 stage 2 (--block-ids / --pages) — ADDITIVE instance-scoped and
    # page/module-scoped eviction over the failure-driven reuse cache. Stage 1
    # (--blocks) evicts every block of a TYPE; stage 2 lets an instructor
    # re-roll ONE specific block instance or one page/module without touching
    # sibling blocks of the same type. Both are purely additive on top of the
    # type-eviction above and each other; all three unset → no eviction →
    # byte-identical failure-driven reuse. Unknown ids / pages fail LOUD (a
    # typo must not silently no-op) — validated against the outline block
    # universe so the error fires even on a first pass with no cache on disk.
    # Consumer-side re-split (see _normalize_token_list_param): both params
    # arrive comma-joined (a STRING) from WorkflowRunner._route_params, or as a
    # list on direct/mailbox calls. Never iterate the raw value — a bare string
    # would iterate into CHARACTERS.
    _target_block_instance_ids = set(
        _normalize_token_list_param(kwargs.get("target_block_instance_ids"))
    )
    _target_page_ids = set(
        _normalize_token_list_param(kwargs.get("target_page_ids"))
    )
    _n_id_evicted, _unknown_ids = _evict_rewrite_cache_by_block_id(
        _rewrite_cache, outline_blocks, _target_block_instance_ids,
    )
    _n_page_evicted, _unknown_pages = _evict_rewrite_cache_by_page(
        _rewrite_cache, outline_blocks, _target_page_ids,
    )
    if _unknown_ids or _unknown_pages:
        _err_parts = []
        if _unknown_ids:
            _err_parts.append(
                f"unknown --block-ids (not in the outline block set): "
                f"{_unknown_ids}"
            )
        if _unknown_pages:
            _err_parts.append(
                f"unknown --pages (match no outline page/module): "
                f"{_unknown_pages}"
            )
        return json.dumps({
            "success": False,
            "error": (
                "_run_content_generation_rewrite: I4 stage-2 eviction "
                "targets did not resolve — " + "; ".join(_err_parts)
            ),
        })
    if _n_id_evicted or _n_page_evicted:
        logger.info(
            "rewrite phase: I4 stage-2 evicted %d cached block(s) by "
            "--block-ids %s and %d by --pages %s; they re-author this pass "
            "(all other blocks reused).",
            _n_id_evicted, sorted(_target_block_instance_ids),
            _n_page_evicted, sorted(_target_page_ids),
        )
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"I4 stage-2 eviction: re-rolling {_n_id_evicted} "
                        f"instance(s) (--block-ids "
                        f"{sorted(_target_block_instance_ids)}) + "
                        f"{_n_page_evicted} page/module block(s) (--pages "
                        f"{sorted(_target_page_ids)}) despite prior successful "
                        "rewrites."
                    ),
                    rationale=(
                        "Operator scoped a re-author to specific block "
                        f"instance(s) {sorted(_target_block_instance_ids)} "
                        f"and/or page(s)/module(s) {sorted(_target_page_ids)}; "
                        "additive eviction drops only those blocks_final.jsonl "
                        "cache entries so they re-roll while every other block "
                        "stays byte-identical to the input."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "target_block_instance_ids": sorted(
                            _target_block_instance_ids
                        ),
                        "target_page_ids": sorted(_target_page_ids),
                        "instance_evicted_blocks": _n_id_evicted,
                        "page_evicted_blocks": _n_page_evicted,
                    },
                )
            except Exception:  # noqa: BLE001
                pass

    if _rewrite_cache and capture is not None:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"Rewrite resume: reusing {len(_rewrite_cache)} cached "
                    "rewritten block(s) from a prior attempt; only uncached / "
                    "previously-failed blocks are re-authored."
                ),
                rationale=(
                    f"Per-block rewrite cache hit ({len(_rewrite_cache)} "
                    "blocks) from the on-disk blocks_final.jsonl avoids "
                    "re-running the full block set on a resume after a "
                    "mid-phase crash/kill on the slow local model."
                ),
                ml_features={
                    "gate_id": "_run_content_generation_rewrite",
                    "cached_blocks": len(_rewrite_cache),
                },
            )
        except Exception:  # noqa: BLE001
            pass

    rewrite_blocks: list = []
    import dataclasses as _dc

    # Canonical DART slug for minting ``dart:{slug}#{chunk_id}`` source
    # refs (mirrors lib.validators.source_refs.semantik_slug_from_filename so
    # the minted ids match the staging-manifest join key + the dart_chunks
    # corpus prefix). The rewrite backstop OVERWRITES the 7B's CURIE-filled
    # ``data-cf-source-ids`` attribute with these canonical refs resolved
    # from each block's real source chunks.
    try:
        from lib.validators.source_refs import (
            semantik_slug_from_filename as _slug_for_refs,
        )
        _rewrite_source_slug = _slug_for_refs(course_code or project_id or "")
    except Exception:  # noqa: BLE001
        _rewrite_source_slug = (course_code or project_id or "").lower().replace(
            "_", "-"
        ).replace(" ", "-")

    # Page -> union of objective_ids declared by any sibling block on that
    # page. Blocks whose own ``objective_ids`` is empty (the 7B occasionally
    # drops the ref on a prose block) inherit the page's objective universe so
    # the rewrite_page_objectives gate resolves them — mirrors the per-page
    # grounding-inheritance the objective/explanation blocks already share.
    _page_objective_ids: Dict[str, list] = {}
    for _ob in outline_blocks:
        _pg = getattr(_ob, "page_id", None)
        if not _pg:
            continue
        _bucket = _page_objective_ids.setdefault(_pg, [])
        _seen_pg = set(_bucket)
        for _oid in getattr(_ob, "objective_ids", None) or ():
            if isinstance(_oid, str) and _oid and _oid not in _seen_pg:
                _bucket.append(_oid)
                _seen_pg.add(_oid)

    def _apply_str_backstops(rewritten):
        """Deterministic post-rewrite HTML backstops (NO LLM).

        Applied to BOTH freshly-rewritten blocks and per-block-cache
        hits, so a resumed run's reused blocks receive the same
        page-objectives / html-shape / source-ref repairs a fresh run
        gets. Idempotent: re-running over an already-repaired str body is
        a no-op (the bogus element is gone, block-id is present, the
        objective attribute already carries a single canonical id).
        """
        if not isinstance(rewritten.content, str):
            return rewritten
        new_content = rewritten.content
        new_content = _BOGUS_SOURCE_ID_EL_RE.sub("", new_content)

        # ---- HTML-shape repair (block-type-agnostic, deterministic) ----
        # Repair the 7B rewrite-tier PARSE-FAIL malformations (unclosed
        # span/cite/code, stray </code> closers, CURIE-as-tag pseudo-elements,
        # bogus <data-cf-block-id=...> pseudo-element) BEFORE attribute
        # injection so injectors run on parseable HTML. Idempotent: a no-op on
        # already-valid HTML. NO LLM.
        new_content = _repair_rewrite_html(new_content)

        # ---- Page-objective inheritance + strip-unknown (block-agnostic) --
        # A block (objective / explanation / example / any prose) whose own
        # objective_ids is empty inherits the page's union of sibling
        # objective_ids so rewrite_page_objectives resolves it. Promote onto
        # the immutable structural field (the gate's str path prefers it) and
        # keep canonical_oid in sync for the attribute rewrite below. The
        # page-objective universe is itself filtered to canonical ids so a
        # hallucinated sibling can't propagate via inheritance.
        if not rewritten.objective_ids:
            inherited = _page_objective_ids.get(rewritten.page_id) or []
            if _canonical_objective_ids:
                inherited = [
                    _oid for _oid in inherited
                    if _oid in _canonical_objective_ids
                ]
            if inherited:
                rewritten = _dc.replace(
                    rewritten, objective_ids=tuple(inherited),
                )
        if rewritten.objective_ids:
            canonical_oid = rewritten.objective_ids[0]
            new_content = _OBJ_ID_RE.sub(
                f'data-cf-objective-id="{canonical_oid}"',
                new_content,
            )
        elif _canonical_objective_ids:
            # STRIP-UNKNOWN: the block resolved to NO canonical objective (its
            # own + page-inherited refs were all empty or hallucinated). Drop
            # any ``data-cf-objective-id="<value>"`` whose value is not a
            # canonical objective id so rewrite_page_objectives no longer fires
            # OBJECTIVE_NOT_IN_CANONICAL on a fabricated TO-NN/CO-NN (week_27).
            # Lowest-risk repair: strip the offending attribute rather than
            # remap to a possibly-wrong id. Idempotent (re-run finds nothing).
            def _strip_unknown_obj(match: "re.Match") -> str:
                val = match.group(1).strip()
                if val and val in _canonical_objective_ids:
                    return match.group(0)
                return ""

            new_content = _OBJ_ID_RE.sub(_strip_unknown_obj, new_content)

        # Inject the universal ``data-cf-block-id`` when no PARSEABLE
        # data-cf-block-id attribute is present (mirrors the gate's
        # found_attrs scrape — a bare substring in prose / comment text does
        # NOT satisfy RewriteHtmlShapeValidator, so the substring-only guard
        # used to skip injection while the gate still failed
        # REWRITE_MISSING_REQUIRED_ATTR). Idempotent: a block that already
        # carries a real root attribute is left untouched.
        if not _html_has_block_id_attr(new_content):
            new_content = _inject_block_id_attr(
                new_content, rewritten.block_id,
            )

        # ---- Content-type stamping (component block types) -------------
        # ``BlockContentTypeValidator`` audits every non-scaffolding block
        # for a ``data-cf-content-type`` in the canonical ChunkType taxonomy.
        # The rewrite LLM stamps it on prose block types (explanation /
        # example) via their ``<h2>`` heading, but the bloom-diversity
        # component types (``self_check_question`` / ``activity``) render as
        # a component ``<div>`` carrying only component/purpose/bloom attrs —
        # so the gate fires OUTLINE_BLOCK_MISSING_CONTENT_TYPE on every one.
        # Stamp the canonical content-type for those types (idempotent — the
        # injector is a no-op when the attribute is already present). Block
        # types absent from the map keep whatever the LLM authored.
        # Fill a MISSING content-type OR REPAIR an invalid one (e.g. a rewrite-
        # LLM-authored ``data-cf-content-type="expression"`` — a domain term in
        # the content-type slot that fails BlockContentTypeValidator's enum
        # check with OUTLINE_BLOCK_INVALID_CONTENT_TYPE). Idempotent; only the
        # data-cf-content-type attr is touched.
        _ct_label = _resolve_block_content_type(rewritten.block_type)
        new_content, _ct_filled, _ct_repaired = _apply_content_type_backstop(
            new_content, rewritten.block_type,
        )
        if _ct_label and (_ct_filled or _ct_repaired):
            # Promote onto the structural field too so the str-path extractor's
            # ``content_type_label`` fallback (and any JSON-LD projection)
            # resolves without re-scraping the attribute. On a repair, overwrite
            # an existing label only when it is itself not a valid ChunkType.
            _existing_label = getattr(rewritten, "content_type_label", None)
            _needs_promote = (
                not _existing_label
                if _ct_filled
                else (
                    not isinstance(_existing_label, str)
                    or _existing_label not in _VALID_CONTENT_TYPES
                )
            )
            if _needs_promote:
                try:
                    rewritten = _dc.replace(
                        rewritten, content_type_label=_ct_label,
                    )
                except (TypeError, ValueError):
                    pass

        # ---- Canonical source-ref resolution (block-type-agnostic) -----
        # The 7B prose tier stamps ``data-cf-source-ids`` with concept CURIEs
        # (``slug:concept_name``) instead of canonical ``dart:{slug}#{chunk}``
        # refs, so the rewrite_source_refs gate fires
        # OUTLINE_BLOCK_INVALID_SOURCE_ID_SHAPE (action=block). Resolve this
        # block's REAL source chunks from the W2 sidecar (chunks_lookup) into
        # canonical dart: refs and OVERWRITE the attribute. The displaced
        # CURIEs are preserved as the curie-anchoring signal (appended hidden
        # <span data-cf-curie>), not discarded. When the block resolves to
        # zero grounded chunks we DROP the bad attribute entirely so the block
        # passes the shape check with deferred (empty) attribution rather than
        # fabricating a ref.
        block_chunks_for_refs = (
            chunks_lookup.get(rewritten.block_id, [])
            if isinstance(chunks_lookup, dict) else []
        )
        canonical_refs = _canonical_source_ids_for_chunks(
            block_chunks_for_refs,
            _rewrite_source_slug,
            chunk_source_id_map=_chunk_source_id_map,
        )
        # Harvest CURIE tokens already stamped in any data-cf-source-ids attr
        # so the curie-anchoring signal survives the overwrite. ONLY real
        # CURIE-shaped tokens (``prefix:localname`` — carry a ``:``) are kept:
        # the 7B rewrite tier sometimes stamps BARE CHUNK IDS
        # (``samplecourse_chunk_00011`` — no colon) in
        # ``data-cf-source-ids``, and re-attaching those as the curie span
        # text produced a span the str-path ``BlockCurieAnchoringValidator``
        # could not extract as a CURIE (no colon) → OUTLINE_BLOCK_MISSING_CURIES
        # despite the span being present. The bare chunk ids are still resolved
        # to canonical source refs above; they are simply not CURIEs.
        displaced_curies: List[str] = []
        _curie_seen: set = set()
        for _m in _SOURCE_IDS_ATTR_RE.finditer(new_content):
            for _tok in _m.group(1).split(","):
                _tok = _tok.strip()
                if (
                    _tok
                    and ":" in _tok
                    and not _CANONICAL_DART_SOURCE_ID_RE.match(_tok)
                    and _tok not in _curie_seen
                ):
                    displaced_curies.append(_tok)
                    _curie_seen.add(_tok)

        if canonical_refs:
            _refs_attr_value = ",".join(canonical_refs)
            if _SOURCE_IDS_ATTR_RE.search(new_content):
                new_content = _SOURCE_IDS_ATTR_RE.sub(
                    f' data-cf-source-ids="{_refs_attr_value}"',
                    new_content,
                )
            else:
                # No source-ids attribute at all — stamp it onto the first
                # start tag (same injection mechanism as data-cf-block-id).
                new_content = _inject_source_ids_attr(
                    new_content, _refs_attr_value,
                )
            # Set BOTH source_ids (HTML attr provenance) AND source_references
            # (the tuple Block.to_synthesis_manifest derives source_refs[] from
            # — it reads content["source_refs"] then self.source_references,
            # NOT source_ids). Populating source_references closes the
            # manifest_completeness MANIFEST_UNGROUNDED cascade: without it the
            # manifest projection sees zero source_refs and the completeness
            # validator flags the block ungrounded.
            _src_refs_tuple = tuple(
                {
                    "sourceId": sid,
                    "role": "primary",
                    "extractor": "synthesized",
                }
                for sid in canonical_refs
            )
            rewritten = _dc.replace(
                rewritten,
                source_ids=tuple(canonical_refs),
                source_references=_src_refs_tuple,
            )
        else:
            # No grounded chunks -> strip the bogus CURIE attribute so the
            # block fails closed with DEFERRED attribution (empty refs pass
            # the shape check) instead of a poisoned invalid-shape ref.
            new_content = _SOURCE_IDS_ATTR_RE.sub("", new_content)

        # ---- CURIE anchoring backstop ----------------------------------
        # The str-path ``BlockCurieAnchoringValidator`` extracts CURIEs
        # (``prefix:localname``) from the block's stripped HTML and fires
        # OUTLINE_BLOCK_MISSING_CURIES when it finds none. A block anchors
        # cleanly when its prose already contains a real (minted) CURIE; when
        # the rewrite LLM authored none (and only bare chunk ids were
        # displaced — already filtered out above), MINT a real domain CURIE
        # from the block's grounded SOURCE-CHUNK text (provenance-aware,
        # identical contract to the outline tier's ``_mint_outline_curies``
        # source-chunk arm) so the anchoring gate has a prose-corpus-valid
        # CURIE. Anti-fabrication: no vocabulary / no source-chunk concept
        # match → mint nothing; the block fails closed (no invented CURIE).
        # Use the gate's exact stripping + extraction so the backstop's
        # "does the body already carry an extractable CURIE?" check matches
        # what BlockCurieAnchoringValidator's str path will compute.
        try:
            from Courseforge.router.inter_tier_gates import (
                _strip_html as _strip_html_fn,
            )
            from lib.ontology.curie_extraction import (
                extract_curies as _extract_curies_fn,
            )
            _body_curies = sorted(
                _extract_curies_fn(_strip_html_fn(new_content))
            )
        except Exception:  # noqa: BLE001 — never block the backstop
            _body_curies = []

        # Strip a JUNK ``data-cf-curie`` span — one whose text content carries
        # only bare chunk ids (no extractable CURIE). A prior backstop version
        # re-attached the 7B's bare-chunk-id ``data-cf-source-ids`` tokens as
        # the curie span; those have no colon, so the gate extracts nothing and
        # still fires OUTLINE_BLOCK_MISSING_CURIES despite the span's presence.
        # Removing the junk span lets the minting path below inject a real
        # CURIE span. A span carrying a real CURIE leaves ``_body_curies``
        # non-empty (caught above) and is never stripped.
        if not _body_curies and "data-cf-curie" in new_content:
            new_content = _strip_junk_curie_spans(new_content)

        _curie_tokens: List[str] = list(displaced_curies)
        if not _body_curies and not _curie_tokens:
            for _minted in _mint_curie_for_str_block(block_chunks_for_refs):
                if _minted not in _curie_tokens:
                    _curie_tokens.append(_minted)
            # Prose fallback: when the block resolved no grounded source chunks
            # (or its chunk text matched no vocabulary concept), mint from the
            # block's OWN rewrite-authored, HTML-stripped prose. A concept
            # surface form present in the published prose is the SAME anchoring
            # surface BlockCurieAnchoringValidator's str path accepts via the
            # threaded minted_curie_map, so minting its CURIE is honest. Closes
            # the source-chunk-only gap measured on a real full-book 7B export
            # (249 shipping blocks carried no body CURIE because the
            # source-chunk match alone never fired for them).
            if not _curie_tokens:
                try:
                    from Courseforge.router.inter_tier_gates import (
                        _strip_html as _strip_html_for_mint,
                    )
                    _prose_for_mint = _strip_html_for_mint(new_content)
                except Exception:  # noqa: BLE001
                    _prose_for_mint = ""
                for _minted in _mint_curie_for_str_block_prose(_prose_for_mint):
                    if _minted not in _curie_tokens:
                        _curie_tokens.append(_minted)

        # Re-attach the CURIE tokens as the curie-anchoring signal — a hidden
        # span whose TEXT content carries the tokens (the str-path validator
        # strips tags before scraping, so attribute-borne CURIEs are invisible
        # to it; text content survives). Skip when the body already carries an
        # extractable CURIE (no double-stamp) and when a span is already
        # present (idempotent on re-run).
        if _curie_tokens and not _body_curies and "data-cf-curie" not in new_content:
            _curie_text = " ".join(_curie_tokens)
            new_content = (
                f"{new_content}"
                f'<span hidden data-cf-curie="{_curie_text}">'
                f"{_curie_text}</span>"
            )

        # P0 — VISIBLE-CURIE leak sanitizer. The minted CURIE is an anchoring
        # signal; it belongs in the hidden ``<span data-cf-curie>`` ONLY. The
        # 7B rewrite tier (and the verbatim-preserve directive) leaks the raw
        # ``prefix:localname`` token into VISIBLE prose — bare, ``<code>``-
        # wrapped, or in ``data-cf-term``. Replace each visible occurrence with
        # the concept's natural surface term (the canonical name from the
        # minted map's ``surface_forms``), leaving the hidden span intact so the
        # curie-anchoring gate still passes. No vocabulary → no-op.
        for _minted_curie, _minted_meta in _rewrite_minted_map.items():
            _surfaces = (
                _minted_meta.get("surface_forms")
                if isinstance(_minted_meta, dict) else None
            )
            _surface = (
                _surfaces[0] if isinstance(_surfaces, list) and _surfaces
                else _minted_curie.split(":", 1)[-1].replace("_", " ")
            )
            new_content = _curie_visible_to_surface(
                new_content, _minted_curie, _surface,
            )

        # P0 — objective ``<li>`` body resolution. An objective block whose
        # visible ``<li>`` body is the bare ``CO-NN`` / ``TO-NN`` id (or empty)
        # is rewritten to ``<strong>ID:</strong> {statement}`` so the learner
        # reads the objective text, not its synthetic id. No-op when the
        # statement map is empty or the body already carries real prose.
        if rewritten.block_type == "objective" and _objective_id_statement_map:
            new_content = _resolve_objective_li_statements(
                new_content, _objective_id_statement_map,
            )

        # Provenance source ids belong ONLY in the hidden
        # ``data-cf-source-ids`` attribute (stamped on the section wrapper
        # at the rewrite-tier render site). A VISIBLE
        # ``<cite class="source-attribution">`` whose body is the raw
        # ``dart:...#hash`` ids leaks machine identifiers into learner prose
        # (P0 identifier-leak defect) — no longer appended here.
        if new_content != rewritten.content:
            rewritten = _dc.replace(rewritten, content=new_content)
        return rewritten

    def _process_one_block(blk):  # type: ignore[no-untyped-def]
        """Rewrite a single outline block (cache hit OR fresh LLM dispatch).

        Pure w.r.t. ``outline_blocks`` ordering — returns the finished
        Block for this input block; the caller places it at the input
        index so output order is deterministic regardless of completion
        order under the concurrent path. FAIL-SOFT per block: a dispatch
        exception yields a ``validator_consensus_fail``-marked block
        (exactly the sequential contract), never aborting siblings.

        Reads shared-but-immutable lookups (``_rewrite_cache``,
        ``chunks_lookup``, ``objectives_payload``, the backstop closure's
        read-only maps); the only shared MUTABLE state it touches is the
        ``DecisionCapture`` (deep inside ``route``/providers) and the NLI
        singleton (best-of-N), both of which are now internally locked.

        Graceful stop (P3.0 marker discipline): under the thread-pool path
        every future is pre-submitted, so a worker that observes an armed
        stop sentinel must RETURN ``STOP_MARKER`` pre-dispatch rather than
        raise — a raise would surface through ``future.result()`` and skip
        the drain-loop checkpoint of the already-resolved (completed) blocks.
        In-flight dispatches finish; new ones are refused. The sequential
        path's loop-top ``check_stop`` normally raises first, but it also
        maps a returned marker to ``GracefulStopRequested`` (tiny arm-race
        window), so the marker return is safe on both paths.
        """
        if stop_requested():
            return STOP_MARKER
        _cached_entry = _rewrite_cache.get(blk.block_id)
        if _cached_entry is not None:
            _cached_blk = _entry_to_block(_cached_entry)
            if _cached_blk is not None:
                return _apply_str_backstops(_cached_blk)
        # Feature I5 / P4 — CONDITIONALLY short-circuit the LLM rewrite for the
        # deterministic key-terms vocab cards. They were authored grounded +
        # verbatim in the outline tier (``template_type="key_terms"``, string
        # content already the final HTML). Re-authoring a HIGH-quality card
        # (curated ``definition_hint`` or a definitional-shape source sentence)
        # with the 7B/cloud model would discard the verbatim source definition,
        # so it is passed straight through the same str backstops. A LOW-quality
        # card (a source sentence that merely MENTIONS the term — weak on the
        # exercise-dense corpus) is NOT short-circuited: it falls through to the
        # normal rewrite path so the LLM authors a real definition. Definition
        # quality is reconstructed from the rendered HTML + grounding presence
        # (``source_ids`` non-empty ⇒ source-sentence; empty ⇒ definition_hint).
        if (
            getattr(blk, "template_type", None) == _KEY_TERMS_TEMPLATE_TYPE
            and isinstance(blk.content, str)
            and blk.content.strip()
        ):
            from lib.generation import key_terms as _kt_sc  # noqa: PLC0415

            if (
                _kt_sc.block_definition_quality(
                    content=blk.content,
                    has_source_ids=bool(getattr(blk, "source_ids", ()) or ()),
                )
                == _kt_sc.DEFINITION_QUALITY_HIGH
            ):
                return _apply_str_backstops(blk)
        # W6.4 — UNCONDITIONALLY short-circuit the LLM rewrite for the
        # deterministic FAQ cards (``template_type="faq"``). Every FAQ answer
        # was LIFTED verbatim from a grounded source chunk (or a real
        # misconception correction) in the outline tier; re-authoring it with
        # the 7B/cloud model would discard that grounding, so it is passed
        # straight through the same str backstops (no LLM dispatch). No quality
        # split (unlike key-terms) — a FAQ card only exists when its answer
        # already resolved to a real chunk (anti-fabrication OMISSION upstream).
        if (
            getattr(blk, "template_type", None) == _FAQ_TEMPLATE_TYPE
            and isinstance(blk.content, str)
            and blk.content.strip()
        ):
            return _apply_str_backstops(blk)
        block_chunks = chunks_lookup.get(blk.block_id, []) if isinstance(
            chunks_lookup, dict
        ) else []
        # Lift the outline-tier dict-content objective refs onto the
        # structural Block.objective_ids BEFORE the rewrite. The 7B
        # outline tier stashes its real LO refs in
        # ``content["objective_refs"]`` / ``content["objective_ids"]``
        # (dict shape) rather than the structural field — but the rewrite
        # tier emits a STR content body, so those dict refs vanish and the
        # post_rewrite page-objectives gate reads ``objective_ids=None``
        # (then falls back to scraping whatever the LLM stamped, which is
        # often a single comma-joined attribute). Promoting them to the
        # immutable structural field makes them survive into str content
        # so the canonical-objective check resolves each id individually.
        if not blk.objective_ids and isinstance(blk.content, dict):
            _lifted: list = []
            _lifted_seen: set = set()
            for _key in ("objective_refs", "objective_ids"):
                for _oid in blk.content.get(_key) or []:
                    if isinstance(_oid, str) and _oid and _oid not in _lifted_seen:
                        _lifted.append(_oid)
                        _lifted_seen.add(_oid)
            if _lifted:
                blk = _dc.replace(blk, objective_ids=tuple(_lifted))
        try:
            rewritten = router.route_rewrite_with_remediation(
                blk,
                validators=_inloop_validators,
                source_chunks=block_chunks,
                objectives=objectives_payload,
            )
            # Backstop: scrub Qwen-invented objective IDs onto the
            # canonical Block.objective_ids, inject the required
            # data-cf-block-id, strip bogus source-id elements, and
            # attach page-level source CURIEs as <cite> text. Shared with
            # the per-block-cache reuse path (see _apply_str_backstops)
            # so resumed runs get identical repairs without re-rolling the
            # slow local model.
            return _apply_str_backstops(rewritten)
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "rewrite phase: route_rewrite_with_remediation() "
                "failed for block_id=%s: %s",
                blk.block_id, exc,
            )
            try:
                return _dc.replace(
                    blk, escalation_marker="validator_consensus_fail",
                )
            except (TypeError, ValueError):
                return None

    # Opt-in concurrent rewrite dispatch. Default 1 = the EXACT sequential
    # path below (no thread pool constructed; byte-identical to the legacy
    # behavior). COURSEFORGE_REWRITE_CONCURRENCY > 1 fans the per-block LLM
    # dispatch out across a bounded thread pool — the slow NVIDIA HTTP rewrite
    # call (~2.7s, I/O-bound, cloud) overlaps across blocks; the shared GPU
    # validators (NLI best-of-N) + DecisionCapture writes briefly serialize on
    # their own internal locks. Results are RE-ORDERED to the original block
    # order so blocks_final is identical regardless of completion order.
    # Garbage / < 1 → 1 (parse-with-fallback, mirroring ED4ALL_ANSWER_NUM_CTX).
    _rewrite_concurrency = 1
    try:
        _rc_raw = int(os.environ.get("COURSEFORGE_REWRITE_CONCURRENCY", "1"))
        if _rc_raw >= 1:
            _rewrite_concurrency = _rc_raw
    except (TypeError, ValueError):
        _rewrite_concurrency = 1

    def _checkpoint_rewrite_result(_result: Any) -> None:
        """Append a successfully-rewritten block to the resume sidecar.

        Flushed per block so a mid-loop kill is resumable. Marker-bearing /
        non-string-content blocks are NOT checkpointed (they re-attempt on
        resume — identical contract to the blocks_final.jsonl cache). Safe
        under the concurrent path: ``_append_block_checkpoint`` opens +
        closes the file per call; concurrent appends interleave whole lines
        (each result is one ``write`` of a complete JSONL line), and resume
        dedupes by block_id so an interleaved duplicate is harmless.
        """
        if not _rewrite_checkpoint_on or _result is None:
            return
        if getattr(_result, "escalation_marker", None):
            return
        _content = getattr(_result, "content", None)
        if not (isinstance(_content, str) and _content.strip()):
            return
        _cp_entry = _block_to_snake_case_entry(_result)
        # Stamp the INPUT fingerprint (computed over the outline block set
        # above) so a later resume validates inputs before reuse.
        _cp_fp = _rewrite_fp_by_id.get(
            str(getattr(_result, "block_id", "") or "")
        )
        if _cp_fp is not None:
            _cp_entry[_BLOCK_CHECKPOINT_FP_KEY] = _cp_fp
        _append_block_checkpoint(
            _rewrite_checkpoint_path,
            _cp_entry,
        )

    # Multi-block BATCHED cloud-lane path (rate-limit defeat). When
    # COURSEFORGE_REWRITE_BATCH is on (default) AND the resolved rewrite lane
    # is a hosted CLOUD endpoint, fan BATCHES (not blocks) through
    # router.route_rewrite_batch so the hosted seat's ~req/min cap is not
    # exhausted by per-block POSTs. Cache hits / key-terms short-circuits /
    # dict-objective-lift are handled per-block FIRST (identical to the
    # per-block path); only blocks needing a fresh LLM dispatch are batched.
    # An explicit COURSEFORGE_REWRITE_BATCH=0 OR a loopback (local) lane skips
    # this branch entirely → the EXACT current per-block path runs (byte-
    # stable). Concurrency auto-defaults to 2 on the cloud lane only when
    # COURSEFORGE_REWRITE_CONCURRENCY is unset (explicit value always wins).
    _use_batch = False
    try:
        from Courseforge.generators._rewrite_batch import (
            resolve_rewrite_batch_mode as _rb_mode,
            resolve_rewrite_batched_concurrency as _rb_conc,
        )
        if _rb_mode() and outline_blocks:
            _probe_spec = router._resolve_spec(outline_blocks[0], "rewrite")
            _use_batch = router._is_cloud_rewrite_lane(_probe_spec)
    except Exception as _batch_exc:  # noqa: BLE001 — fall back to per-block
        logger.warning(
            "rewrite phase: batched-lane probe failed (%s); falling back to "
            "the per-block path.", _batch_exc,
        )
        _use_batch = False

    if _use_batch:
        # --- Phase A: per-block prep (cache / key-terms / dict-lift) -------
        # A block that resolves to a finished Block here (cache hit or
        # high-quality key-terms short-circuit) is NOT batched; everything
        # else is collected (as its prepared outline Block) for batching.
        _finished_by_idx: Dict[int, Any] = {}
        _to_batch: list = []          # prepared outline Blocks for fresh dispatch
        _batch_idx_by_id: Dict[str, int] = {}   # block_id -> original index
        _chunks_for_batch: Dict[str, list] = {}
        # Graceful-stop per-round checkpoint bookkeeping: block_ids the router's
        # ``on_block_resolved`` callback has already appended to the resume
        # sidecar (so Phase C below does not double-append them).
        _batch_checkpointed_ids: set = set()
        for _idx, blk in enumerate(outline_blocks):
            _cached_entry = _rewrite_cache.get(blk.block_id)
            if _cached_entry is not None:
                _cached_blk = _entry_to_block(_cached_entry)
                if _cached_blk is not None:
                    _finished_by_idx[_idx] = _apply_str_backstops(_cached_blk)
                    continue
            # Key-terms high-quality short-circuit (mirror _process_one_block).
            if (
                getattr(blk, "template_type", None) == _KEY_TERMS_TEMPLATE_TYPE
                and isinstance(blk.content, str)
                and blk.content.strip()
            ):
                from lib.generation import key_terms as _kt_sc  # noqa: PLC0415
                if (
                    _kt_sc.block_definition_quality(
                        content=blk.content,
                        has_source_ids=bool(
                            getattr(blk, "source_ids", ()) or ()
                        ),
                    )
                    == _kt_sc.DEFINITION_QUALITY_HIGH
                ):
                    _finished_by_idx[_idx] = _apply_str_backstops(blk)
                    continue
            # FAQ unconditional short-circuit (mirror _process_one_block). The
            # grounded FAQ card is passed straight through the str backstops —
            # never batched to the LLM (its answer is already grounded verbatim).
            if (
                getattr(blk, "template_type", None) == _FAQ_TEMPLATE_TYPE
                and isinstance(blk.content, str)
                and blk.content.strip()
            ):
                _finished_by_idx[_idx] = _apply_str_backstops(blk)
                continue
            # Dict-objective lift (mirror _process_one_block) so the rewrite
            # carries the real LO refs into str content.
            if not blk.objective_ids and isinstance(blk.content, dict):
                _lifted: list = []
                _lifted_seen: set = set()
                for _key in ("objective_refs", "objective_ids"):
                    for _oid in blk.content.get(_key) or []:
                        if (
                            isinstance(_oid, str) and _oid
                            and _oid not in _lifted_seen
                        ):
                            _lifted.append(_oid)
                            _lifted_seen.add(_oid)
                if _lifted:
                    blk = _dc.replace(blk, objective_ids=tuple(_lifted))
            _block_chunks = chunks_lookup.get(blk.block_id, []) if isinstance(
                chunks_lookup, dict
            ) else []
            _to_batch.append(blk)
            _batch_idx_by_id[blk.block_id] = _idx
            _chunks_for_batch[blk.block_id] = _block_chunks

        # --- Phase B: batched fresh dispatch ------------------------------
        if _to_batch:
            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="content_selection",
                        decision=(
                            f"Rewrite-tier BATCHED cloud lane: dispatching "
                            f"{len(_to_batch)} fresh block(s) via "
                            f"route_rewrite_batch (concurrency={_rb_conc()})."
                        ),
                        rationale=(
                            f"COURSEFORGE_REWRITE_BATCH on + resolved rewrite "
                            f"lane is a hosted CLOUD endpoint "
                            f"(provider={_probe_spec.provider}, "
                            f"base_url={_probe_spec.base_url}); packing blocks "
                            f"into multi-block POSTs (round-based per-block "
                            f"validator regen) so the hosted seat's ~req/min "
                            f"cap is not exhausted by per-block POSTs. "
                            f"{len(_finished_by_idx)} block(s) were cache/key-"
                            f"terms short-circuited and not batched. Output is "
                            f"re-ordered to the original block sequence."
                        ),
                        ml_features={
                            "gate_id": "_run_content_generation_rewrite",
                            "batched_blocks": len(_to_batch),
                            "short_circuited_blocks": len(_finished_by_idx),
                            "cloud_provider": _probe_spec.provider,
                        },
                    )
                except Exception:  # noqa: BLE001
                    pass
            # Graceful stop (checkpoint on command): pre-flight check BEFORE
            # the batch dispatch so a PRE-ARMED sentinel never dispatches the
            # batch at all (zero provider calls). A stop armed DURING the router
            # call is honoured INSIDE ``route_rewrite_batch`` — it checkpoints
            # every block resolved in a completed round via the
            # ``on_block_resolved`` callback below, then raises
            # ``GracefulStopRequested`` between rounds (Wave C / D2). That raise
            # must propagate, so it is caught + re-raised ahead of the fail-soft
            # ``except Exception`` (which would otherwise stamp the whole batch
            # ``validator_consensus_fail``, mapping a pause to a fake failure).
            check_stop("rewrite_tier", len(_finished_by_idx))

            def _on_batch_block_resolved(_bid: str, _blk: Any) -> None:
                """Router per-round hook: append a validator-PASSING block the
                instant it resolves so a between-round stop loses at most the
                in-flight round. Best-effort; ids tracked to avoid a Phase-C
                double-append."""
                _checkpoint_rewrite_result(_blk)
                _rid = str(getattr(_blk, "block_id", "") or _bid or "")
                if _rid:
                    _batch_checkpointed_ids.add(_rid)

            try:
                _batch_results = router.route_rewrite_batch(
                    _to_batch,
                    source_chunks_by_block_id=_chunks_for_batch,
                    objectives=objectives_payload,
                    validators=_inloop_validators,
                    on_block_resolved=_on_batch_block_resolved,
                )
            except GracefulStopRequested:
                # Between-round stop raised from inside route_rewrite_batch:
                # completed-round blocks are already checkpointed via the
                # callback — propagate the pause, never marshal it as a batch
                # consensus-fail.
                raise
            except Exception as exc:  # noqa: BLE001 — fail-soft whole batch
                logger.warning(
                    "rewrite phase: route_rewrite_batch() failed (%s); "
                    "marking the batched blocks consensus-fail.", exc,
                )
                _batch_results = {}
                for blk in _to_batch:
                    try:
                        _batch_results[blk.block_id] = _dc.replace(
                            blk, escalation_marker="validator_consensus_fail",
                        )
                    except (TypeError, ValueError):
                        pass
            for _bid, _res in _batch_results.items():
                _idx = _batch_idx_by_id.get(_bid)
                if _idx is None or _res is None:
                    continue
                _finished_by_idx[_idx] = _apply_str_backstops(_res)

        # --- Phase C: re-order + checkpoint -------------------------------
        # Blocks resolved fresh by the router are already on disk (the
        # ``on_block_resolved`` callback checkpointed them per round); only the
        # short-circuited (cache / key-terms / FAQ) survivors still need an
        # append here. Dedupe-by-block_id makes a duplicate harmless, but the
        # id-set keeps the sidecar one-line-per-block.
        for _idx in range(len(outline_blocks)):
            _result = _finished_by_idx.get(_idx)
            if _result is not None:
                rewrite_blocks.append(_result)
                _rc_bid = str(getattr(_result, "block_id", "") or "")
                if _rc_bid not in _batch_checkpointed_ids:
                    _checkpoint_rewrite_result(_result)
    elif _rewrite_concurrency <= 1:
        # Sequential path — EXACT legacy behavior. No pool constructed.
        for blk in outline_blocks:
            # Graceful stop (checkpoint on command): raise at the unit
            # boundary. Every prior block was appended to
            # ``.blocks_final_checkpoint.jsonl`` (or served from the resume
            # cache), so ``len(rewrite_blocks)`` == checkpointed units.
            check_stop("rewrite_tier", len(rewrite_blocks))
            _result = _process_one_block(blk)
            # Belt-and-suspenders for the tiny arm-race window: a stop armed
            # between the loop-top check and ``_process_one_block``'s entry
            # returns STOP_MARKER — treat it as not-attempted (never a block),
            # do NOT checkpoint it, and raise before any final artifact write.
            if _result is STOP_MARKER:
                raise GracefulStopRequested(
                    "rewrite_tier", len(rewrite_blocks)
                )
            if _result is not None:
                rewrite_blocks.append(_result)
                _checkpoint_rewrite_result(_result)
    else:
        # Bounded thread-pool fanout. Collect into an index-keyed dict so the
        # final list is reassembled in ORIGINAL block order (deterministic
        # output regardless of which block finishes first). Per-block failure
        # stays isolated to that block (the worker returns the marked block).
        from concurrent.futures import ThreadPoolExecutor

        _pool_size = min(_rewrite_concurrency, len(outline_blocks)) or 1
        _results_by_idx: Dict[int, Any] = {}
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Rewrite-tier concurrency enabled: dispatching "
                        f"{len(outline_blocks)} block(s) across a "
                        f"{_pool_size}-thread pool."
                    ),
                    rationale=(
                        f"COURSEFORGE_REWRITE_CONCURRENCY={_rewrite_concurrency} "
                        f"(pool sized to min(knob, n_blocks)={_pool_size}) fans "
                        f"the I/O-bound per-block rewrite LLM dispatch out across "
                        f"threads; shared GPU NLI + DecisionCapture writes "
                        f"serialize on internal locks. Output is re-ordered to "
                        f"the original block sequence so blocks_final is "
                        f"byte-identical to the sequential path."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "rewrite_concurrency": _rewrite_concurrency,
                        "pool_size": _pool_size,
                        "block_count": len(outline_blocks),
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        # Graceful stop (checkpoint on command): a pre-armed sentinel refuses
        # the whole fan-out before any future is submitted (zero dispatches).
        check_stop("rewrite_tier", len(rewrite_blocks))
        # P3.0 drain discipline: futures are pre-submitted, so an in-flight
        # worker that observes a mid-fanout stop RETURNS ``STOP_MARKER`` (never
        # raises — a raise would surface through ``future.result()`` and skip
        # the checkpoint of already-resolved blocks). The drain loop keeps
        # checkpointing every NON-marker resolved future, records that a stop
        # was seen, and only AFTER draining raises ``GracefulStopRequested`` —
        # so a mid-fanout kill loses nothing already computed.
        _rewrite_stop_seen = False
        with ThreadPoolExecutor(max_workers=_pool_size) as _pool:
            _futs = {
                _pool.submit(_process_one_block, _blk): _idx
                for _idx, _blk in enumerate(outline_blocks)
            }
            for _fut in _futs:
                _idx = _futs[_fut]
                try:
                    _fut_result = _fut.result()
                    if _fut_result is STOP_MARKER:
                        # Refused pre-dispatch — not-attempted; do NOT
                        # checkpoint (resume re-runs it) and do NOT place it in
                        # the reorder map (it is not a Block).
                        _rewrite_stop_seen = True
                        continue
                    _results_by_idx[_idx] = _fut_result
                    # Checkpoint as each future resolves (flush per block) so a
                    # mid-fanout kill is resumable; resume dedupes by block_id.
                    _checkpoint_rewrite_result(_results_by_idx[_idx])
                except Exception as exc:  # noqa: BLE001
                    # Defensive: _process_one_block already fail-softs, but a
                    # truly unexpected raise must not drop the block silently —
                    # mark it consensus-fail at its original index.
                    logger.warning(
                        "rewrite phase: concurrent worker raised for "
                        "block idx=%s: %s",
                        _idx, exc,
                    )
                    try:
                        _results_by_idx[_idx] = _dc.replace(
                            outline_blocks[_idx],
                            escalation_marker="validator_consensus_fail",
                        )
                    except (TypeError, ValueError):
                        _results_by_idx[_idx] = None
        # Raise AFTER the drain loop so every already-resolved (non-marker)
        # future above was checkpointed first (R5: raise before any final
        # artifact write). ``len(_results_by_idx)`` == the checkpointed units.
        if _rewrite_stop_seen:
            raise GracefulStopRequested(
                "rewrite_tier", len(_results_by_idx)
            )
        for _idx in range(len(outline_blocks)):
            _result = _results_by_idx.get(_idx)
            if _result is not None:
                rewrite_blocks.append(_result)

    # ---- Final deterministic CURIE-anchoring sweep (calib fix) ----------
    # Belt-and-suspenders guarantee that EVERY shipping block carries a
    # gate-extractable CURIE before the post_rewrite_validation gate runs,
    # regardless of which per-block dispatch path it took (sequential /
    # concurrent / batched / cache-hit) or whether the provider's
    # ``_force_inject_curies`` / the in-loop ``_apply_str_backstops`` mint
    # actually landed a span. Root cause (seen on a calibration run): a
    # block whose outline DECLARED minted CURIEs and whose published prose
    # genuinely discusses the concept could still reach blocks_final.jsonl
    # with NO ``<span data-cf-curie>`` (the provider's pedagogical-context
    # preservation check considered the bare TERM "present" so
    # ``last_missing`` was empty → ``_force_inject_curies`` injected
    # nothing; the str-path BlockCurieAnchoringValidator then extracts ZERO
    # CURIE TOKENS and fails OUTLINE_BLOCK_MISSING_CURIES). This sweep runs
    # the SAME proven prose-mint contract as ``restamp_blocks_final_jsonl``:
    # for any STR-content shipping block whose stripped body carries no
    # extractable CURIE, mint a real domain CURIE from the block's OWN
    # published prose (a concept surface form present in the prose is the
    # exact anchoring surface the validator accepts) and append it as a
    # hidden ``<span data-cf-curie>`` whose TEXT content carries the tokens.
    # ANTI-FABRICATION: prose-mint only (no vocabulary / no surface match →
    # mint nothing; the block stays curieless and fails the gate honestly).
    # Idempotent: a body that already carries an extractable CURIE is
    # untouched. No LLM / no GPU. No-op on RDF / legacy corpora (empty
    # minter resources).
    _final_anchor_minted = 0
    if _rewrite_domain_seeds and _rewrite_minted_by_canonical:
        from Courseforge.router.inter_tier_gates import (  # noqa: PLC0415
            _strip_html as _strip_html_anchor,
            _is_unshipped_escalation_tombstone as _is_tombstone_anchor,
            _is_deterministic_template_block as _is_det_template_anchor,
        )
        from lib.ontology.curie_extraction import (  # noqa: PLC0415
            extract_curies as _extract_curies_anchor,
        )
        _swept: List[Any] = []
        for _blk in rewrite_blocks:
            _content = getattr(_blk, "content", None)
            if not isinstance(_content, str):
                _swept.append(_blk)
                continue
            # Mirror the gate's audit universe: skip exactly the blocks the
            # gate skips (unshipped tombstones + deterministic templates).
            try:
                if _is_tombstone_anchor(_blk) or _is_det_template_anchor(_blk):
                    _swept.append(_blk)
                    continue
            except Exception:  # noqa: BLE001 — never break the sweep
                _swept.append(_blk)
                continue
            try:
                _body = _extract_curies_anchor(_strip_html_anchor(_content))
            except Exception:  # noqa: BLE001
                _body = set()
            if _body:
                _swept.append(_blk)
                continue
            # No extractable CURIE — strip any junk data-cf-curie span (one
            # whose text carries no extractable CURIE) then prose-mint.
            _new_content = _content
            if "data-cf-curie" in _new_content:
                _new_content = _strip_junk_curie_spans(_new_content)
            try:
                _prose = _strip_html_anchor(_new_content)
            except Exception:  # noqa: BLE001
                _prose = ""
            _tokens = [t for t in _mint_curie_for_str_block_prose(_prose) if t]
            if _tokens and "data-cf-curie" not in _new_content:
                _txt = " ".join(_tokens)
                _new_content = (
                    f"{_new_content}"
                    f'<span hidden data-cf-curie="{_txt}">{_txt}</span>'
                )
                try:
                    _blk = _dc.replace(_blk, content=_new_content)
                    _final_anchor_minted += 1
                except (TypeError, ValueError):
                    pass
            _swept.append(_blk)
        rewrite_blocks = _swept
        if _final_anchor_minted and capture is not None:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Final CURIE-anchoring sweep minted prose CURIEs for "
                        f"{_final_anchor_minted} shipping block(s) that reached "
                        f"blocks_final without a gate-extractable CURIE."
                    ),
                    rationale=(
                        f"Deterministic prose-mint backstop (no LLM/GPU) closed "
                        f"the rewrite-tier anchoring gap for "
                        f"{_final_anchor_minted} block(s): each carried no "
                        f"extractable CURIE token despite its published prose "
                        f"discussing a domain concept, so a real "
                        f"{{prefix}}:{{concept}} CURIE was minted from the "
                        f"block's OWN prose (anti-fabrication: surface-form "
                        f"match only) and appended as a hidden data-cf-curie "
                        f"span the str-path BlockCurieAnchoringValidator can "
                        f"extract. course={course_code}."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "final_anchor_sweep_minted": _final_anchor_minted,
                        "rewrite_block_count": len(rewrite_blocks),
                    },
                )
            except Exception:  # noqa: BLE001
                pass

    # ---- Deterministic HTML tag-balance repair (default OFF) -------------
    # COURSEFORGE_REWRITE_HTML_REPAIR: repair model-emitted stray-close /
    # missing-close tag imbalances (the dominant REWRITE_HTML_PARSE_FAIL
    # class at the rewrite_html_shape gate) at emit time so blocks_final
    # self-repairs. Runs AFTER the CURIE-anchoring sweep so appended closes
    # land BEFORE the hidden data-cf-curie tail (the tail stays a top-level
    # sibling). No LLM / no text or attribute edits; flag off → rewrite_blocks
    # unchanged (byte-identical emit). Ops are recorded on each repaired
    # block's touched_by chain by the helper.
    rewrite_blocks, _n_html_repaired, _html_repair_op_counts = (
        _maybe_repair_block_html_balance(rewrite_blocks)
    )
    if _n_html_repaired and capture is not None:
        try:
            capture.log_decision(
                decision_type="content_selection",
                decision=(
                    f"HTML tag-balance repair fixed {_n_html_repaired} "
                    f"rewrite-tier block(s) before the blocks_final emit "
                    f"(ops: {_html_repair_op_counts})."
                ),
                rationale=(
                    f"Deterministic single-pass repair (no LLM/GPU) closed "
                    f"the rewrite-tier unbalanced-tag gap for "
                    f"{_n_html_repaired}/{len(rewrite_blocks)} block(s): "
                    f"stray close tags matching nothing open were dropped, "
                    f"missing closes were inserted/appended in LIFO order "
                    f"({_html_repair_op_counts}), text and attributes "
                    f"untouched, so the rewrite_html_shape gate audits the "
                    f"repaired markup instead of failing "
                    f"REWRITE_HTML_PARSE_FAIL on model tag-balance slop. "
                    f"course={course_code}."
                ),
                ml_features={
                    "gate_id": "_run_content_generation_rewrite",
                    "html_repair_blocks": _n_html_repaired,
                    "html_repair_op_counts": _html_repair_op_counts,
                    "rewrite_block_count": len(rewrite_blocks),
                },
            )
        except Exception:  # noqa: BLE001
            pass

    # Persist final blocks JSONL (consumed by post_rewrite_validation).
    blocks_final_path = out_dir / "blocks_final.jsonl"
    with blocks_final_path.open("w", encoding="utf-8") as fh:
        for blk in rewrite_blocks:
            fh.write(json.dumps(
                _block_to_snake_case_entry(blk), ensure_ascii=False,
            ))
            fh.write("\n")

    # Crash-resume sidecar cleanup + capture: the final JSONL is on disk, so
    # the interrupted-run checkpoint is no longer needed. Emit one decision
    # event (dynamic rationale: blocks resumed from the append-as-you-go
    # sidecar) mirroring the outline tier's resume capture.
    if _rewrite_checkpoint_on:
        if capture is not None and _n_rewrite_checkpoint_resumed:
            try:
                capture.log_decision(
                    decision_type="content_selection",
                    decision=(
                        f"Rewrite crash-resume checkpoint: rehydrated "
                        f"{_n_rewrite_checkpoint_resumed} block(s) from the "
                        f"append-as-you-go sidecar (beyond the "
                        f"blocks_final.jsonl cache)."
                    ),
                    rationale=(
                        f"{_rewrite_checkpoint_path.name} carried "
                        f"{_n_rewrite_checkpoint_resumed} successfully-"
                        f"rewritten block(s) flushed per-block by a prior "
                        f"interrupted attempt that never reached the final "
                        f"blocks_final.jsonl write; resume skipped their LLM "
                        f"dispatch (dedupe-by-block_id, never duplicating or "
                        f"fabricating a block)."
                    ),
                    ml_features={
                        "gate_id": "_run_content_generation_rewrite",
                        "blocks_resumed_from_checkpoint": (
                            _n_rewrite_checkpoint_resumed
                        ),
                        "checkpoint_sidecar": _rewrite_checkpoint_path.name,
                    },
                )
            except Exception:  # noqa: BLE001
                pass
        _remove_block_checkpoint(_rewrite_checkpoint_path)

    # W3 — per-block synthesis-manifest sidecar. Emit one
    # block_synthesis_manifest.jsonl line per finalized rewrite-tier block
    # (full touched_by chain present), resolving source_chunk_ids against the
    # pinned DART chunkset. Gated by COURSEFORGE_EMIT_BLOCKS so a flag-off run
    # stays byte-stable; idempotent (anti-clobber) on re-run. The
    # ManifestCompletenessValidator gate (post_rewrite_validation) consumes the
    # sidecar; W4 NLI reads it for the entailment premise set.
    _course_slug = (course_code or project_id).lower().replace(
        "_", "-"
    ).replace(" ", "-")
    # DART->semantik purge Stage 3c: dual-read staged chunkset (semantik ->
    # dart -> corpus) so block source_chunk_ids resolve on new-name courses.
    from lib.libv2_storage import resolve_staged_chunks_path
    _dart_chunks_path = resolve_staged_chunks_path(
        _resolve_libv2_root(kwargs.get("libv2_root"))
        / "courses"
        / _course_slug
    )
    try:
        _emit_block_synthesis_manifest(
            rewrite_blocks, content_dir, _dart_chunks_path, capture,
        )
    except Exception as exc:  # noqa: BLE001
        # Best-effort: a manifest-emit failure never aborts the rewrite phase
        # (the gate's anti-silent-degradation guard catches a missing manifest).
        logger.warning(
            "block_synthesis_manifest: emit failed in rewrite phase: %s", exc,
        )

    # Group blocks by page_id and emit a minimal HTML page per group.
    # The two-pass router's HTML is the rewritten Block.content (string);
    # we wrap it in the minimum semantic structure the validators
    # require (an objectives section per page, plus the body text).
    pages_by_id: Dict[str, list] = {}
    for blk in rewrite_blocks:
        pages_by_id.setdefault(blk.page_id, []).append(blk)

    page_paths: list = []
    for page_id, page_blocks in pages_by_id.items():
        page_path = content_dir / f"{page_id}.html"
        objective_ids = []
        for b in page_blocks:
            for oid in b.objective_ids or ():
                if oid not in objective_ids:
                    objective_ids.append(oid)
        # P0 — render the objective STATEMENT (not the bare id) as the visible
        # ``<li>`` body when resolvable; the id stays in the attribute. Mirrors
        # generate_course.py::_render_objectives (``<strong>ID:</strong>
        # statement``). Falls back to the bare id when no statement resolves.
        def _objective_li(oid: str) -> str:
            _stmt = _objective_id_statement_map.get(oid) or \
                _objective_id_statement_map.get(oid.upper())
            if _stmt:
                import html as _html_mod
                return (
                    f'<li data-cf-objective-id="{oid}">'
                    f"<strong>{oid}:</strong> {_html_mod.escape(_stmt)}</li>"
                )
            return f'<li data-cf-objective-id="{oid}">{oid}</li>'

        objective_lis = "".join(_objective_li(oid) for oid in objective_ids)

        # Finding 9 + 18 prep: resolve the page_type from the page_id and split
        # the page's objective ids into the week's TO records + CO records so
        # (a) the <h1> can be humanized from the leading TO statement and
        # (b) the overview page can enumerate TO + ALL its COs.
        _pt_match = _PAGE_ID_TYPE_RE.match(page_id or "")
        _page_type = (
            (_pt_match.group("ptype") or "content").lower()
            if _pt_match else "content"
        )
        _page_tos: List[Dict[str, Any]] = []
        _page_cos: List[Dict[str, Any]] = []
        for _oid in objective_ids:
            _rec = _to_record_map.get(_oid) or _to_record_map.get(_oid.upper())
            if _rec is not None:
                _page_tos.append(_rec)
                continue
            _rec = _co_record_map.get(_oid) or _co_record_map.get(_oid.upper())
            if _rec is not None:
                _page_cos.append(_rec)
        # Finding 18: the overview must list each child CO of the page's TO(s),
        # even when the overview's blocks declared only the TO id. Pull every
        # CO whose ``terminal_id`` points at one of the page's TOs.
        if _page_type == "overview" and _page_tos:
            _to_ids = {str(t.get("id")) for t in _page_tos if t.get("id")}
            _have_co = {str(c.get("id")) for c in _page_cos if c.get("id")}
            for _co in _co_record_map.values():
                _tid = _co.get("terminal_id")
                _cid = str(_co.get("id") or "")
                if _tid in _to_ids and _cid and _cid not in _have_co:
                    _page_cos.append(_co)
                    _have_co.add(_cid)

        body_parts = []
        for b in page_blocks:
            # W5: marker-bearing blocks (outline_budget_exhausted /
            # structural_unfixable / validator_consensus_fail) MUST NOT
            # ship into per-page HTML. They persist on disk in
            # blocks_final.jsonl for re-execution / audit, but they
            # never become part of the IMSCC body.
            # ``b.content`` may be a dict (degraded/escalation blocks carry the
            # outline-tier structured content, not a rewritten HTML string).
            # Guard the ``.strip()`` exactly as the body-emit branch below does,
            # else a dict content raises ``'dict' object has no attribute
            # 'strip'`` AFTER all blocks are written — failing the whole phase
            # and triggering a full 3x re-run of every block.
            _marker_content = b.content if isinstance(b.content, str) else ""
            if b.escalation_marker is not None and not _marker_content.strip():
                # Deterministic styled-template FALLBACK. The rewrite-tier model
                # exhausted its parse-retry budget (runaway repetition truncated
                # the block at max_tokens), so there is no usable rewritten HTML.
                # Rather than DROP the block (loses content + breaks the page),
                # render a concise, styled, grounded HTML body from the outline
                # block's already-concise ``content.key_claims`` using the SAME
                # styled component classes + ``data-cf-*`` metadata the success
                # path emits. Stamps ``data-cf-fallback="template"`` so the
                # fallback-rendered blocks are auditable. LLM-free.
                _fallback_sids = list(b.source_ids or ())
                if not _fallback_sids:
                    _fallback_sids = _page_source_ids(b.page_id)
                _fallback_html = _render_block_fallback_html(
                    b,
                    objective_statements=_objective_id_statement_map,
                    minted_curie_map=_rewrite_minted_map,
                    source_ids=_fallback_sids,
                )
                body_parts.append(_fallback_html)
                if capture is not None:
                    try:
                        capture.log_decision(
                            decision_type="block_template_fallback",
                            decision=(
                                f"Rendered deterministic styled template "
                                f"fallback for block_id={b.block_id} "
                                f"(block_type={b.block_type}, "
                                f"escalation_marker={b.escalation_marker})."
                            ),
                            rationale=(
                                "Rewrite tier exhausted its parse-retry budget "
                                "(runaway repetition truncated the block at "
                                f"max_tokens) so block_id={b.block_id} had no "
                                "usable HTML. Instead of dropping it (loses "
                                "grounded content + breaks the page), the "
                                "deterministic LLM-free renderer authored a "
                                "concise styled block from the outline block's "
                                f"{len(_fallback_claim_texts(b))} key_claim(s) "
                                "using the same styled component classes + "
                                "data-cf-* metadata the success path emits; "
                                "stamped data-cf-fallback=\"template\" for audit."
                            ),
                            ml_features={
                                "gate_id": "_run_content_generation_rewrite",
                                "block_id": b.block_id,
                                "block_type": b.block_type,
                                "escalation_marker": b.escalation_marker,
                                "page_id": page_id,
                                "key_claim_count": len(
                                    _fallback_claim_texts(b)
                                ),
                                "fallback": "template",
                            },
                        )
                    except Exception:  # noqa: BLE001
                        pass
                continue
            content = b.content if isinstance(b.content, str) else ""
            if not content.strip():
                continue
            # rewrite-overflow-fix-2026-06: a PARSED-but-structurally-empty
            # assessment_item (non-empty content, no escalation marker, but
            # missing the >= 2 ``<li data-cf-distractor-index="N">`` siblings
            # the CRITICAL ``rewrite_assessment_item_payload`` gate requires)
            # would BLOCK the whole run. Route it to the SAME deterministic
            # MCQ-completion fallback the escalated path uses (which emits the
            # canonical option markup) BEFORE the gate sees it, so a real 7B
            # MCQ that omitted a ``data-cf-distractor-index`` sibling can't
            # fail the run closed. Minimal + targeted: only assessment_item,
            # only when the gate WOULD fail.
            if (
                b.block_type == "assessment_item"
                and _assessment_item_payload_structurally_empty(content)
            ):
                _ai_fallback_sids = list(b.source_ids or ())
                if not _ai_fallback_sids:
                    _ai_fallback_sids = _page_source_ids(b.page_id)
                _ai_fallback_html = _render_block_fallback_html(
                    b,
                    objective_statements=_objective_id_statement_map,
                    minted_curie_map=_rewrite_minted_map,
                    source_ids=_ai_fallback_sids,
                )
                body_parts.append(_ai_fallback_html)
                if capture is not None:
                    try:
                        capture.log_decision(
                            decision_type="block_template_fallback",
                            decision=(
                                f"Repaired structurally-empty assessment_item "
                                f"MCQ for block_id={b.block_id} via the "
                                f"deterministic option-markup fallback "
                                f"(no escalation marker)."
                            ),
                            rationale=(
                                f"assessment_item block_id={b.block_id} parsed "
                                "to non-empty HTML but carried fewer than 2 "
                                "<li data-cf-distractor-index='N'> siblings, so "
                                "the CRITICAL rewrite_assessment_item_payload "
                                "gate would BLOCK the whole run. Routed it to "
                                "the deterministic LLM-free MCQ-completion "
                                "fallback (canonical <li data-cf-distractor-"
                                "index>/data-cf-correct markup) BEFORE the gate "
                                "so a real 7B MCQ missing the option markup "
                                "ships gate-valid instead of failing the run "
                                "closed; stamped data-cf-fallback=\"template\"."
                            ),
                            ml_features={
                                "gate_id": "_run_content_generation_rewrite",
                                "block_id": b.block_id,
                                "block_type": b.block_type,
                                "page_id": page_id,
                                "fallback": "assessment_item_payload_repair",
                            },
                        )
                    except Exception:  # noqa: BLE001
                        pass
                continue
            # Stamp canonical data-cf-source-ids / data-cf-objective-id
            # on the section wrapper from the Block dataclass fields,
            # falling back to the page-level source_module_map for
            # blocks whose source_ids were stripped upstream.
            block_sids = list(b.source_ids or ())
            if not block_sids:
                block_sids = _page_source_ids(b.page_id)
            source_ids_attr = ""
            # Provenance ids live ONLY in the hidden ``data-cf-source-ids``
            # attribute. A VISIBLE ``<cite class="source-attribution">`` whose
            # body is the raw ``dart:...#hash`` ids leaks machine identifiers
            # into learner prose (P0 identifier-leak defect) — the same ids the
            # attribute already carries, so the visible cite was redundant.
            cite_html = ""
            if block_sids:
                source_ids_attr = (
                    f' data-cf-source-ids="{",".join(block_sids)}"'
                )
            objective_attr = ""
            if b.objective_ids:
                objective_attr = (
                    f' data-cf-objective-id="{",".join(b.objective_ids)}"'
                )
            # P2 — thread the canonical teaching-role onto the section wrapper
            # via the (component, purpose) -> role mapper, so two-pass pages
            # carry the same pedagogical-role provenance the single-pass
            # generator emits. Prefer the Block's own teaching_role when set;
            # else resolve deterministically from the block_type.
            _role = getattr(b, "teaching_role", None) or \
                _teaching_role_for_block_type(b.block_type)
            teaching_role_attr = (
                f' data-cf-teaching-role="{_role}"' if _role else ""
            )
            # W6.6 — append the graded-B14 confidence capture + calibration-
            # comparison reveal to the assessment_item section (gated by
            # ED4ALL_REFLECTION_CALIBRATION; "" when off → byte-identical).
            _confidence_html = _assessment_confidence_capture_html(b)
            _confidence_suffix = (
                f"\n{_confidence_html}" if _confidence_html else ""
            )
            body_parts.append(
                f'<section data-cf-block-id="{b.block_id}"'
                f'{source_ids_attr}{objective_attr}{teaching_role_attr}>'
                f'{content}{cite_html}{_confidence_suffix}</section>'
            )
        # P1 — route the per-page shell through generate_course.py::_wrap_page
        # so every two-pass page inherits the FULL Courseforge stylesheet
        # (COURSEFORGE_CSS incl. the Sonnet component classes), a real document
        # ``<head>`` (charset/viewport/title) + chrome (skip-link, header,
        # footer). The objectives section + block sections become the wrapped
        # ``<main>`` body. Resolve the week number from the page_id
        # (``week_NN_...``) for the chrome banner; default 1.
        _week_num = 1
        _wk_match = re.search(r"week[_-]?(\d+)", page_id, re.IGNORECASE)
        if _wk_match:
            try:
                _week_num = int(_wk_match.group(1))
            except (TypeError, ValueError):
                _week_num = 1

        # Finding 11 + 18 — render (or OMIT) the page objectives <section> via
        # the shared pure helper. Finding 11: a page with no objectives must
        # NOT ship a blank "Objectives" heading over an empty <ul>. Finding 18:
        # an OVERVIEW page enumerates the week's TO + ALL its child COs (each
        # with its statement) via render_objective_list.
        _objectives_section = _build_objectives_section_html(
            objective_lis=objective_lis,
            page_type=_page_type,
            page_tos=_page_tos,
            page_cos=_page_cos,
        )
        _body_html = (
            f"{_objectives_section}"
            f"{''.join(body_parts)}"
        )

        # Finding 9: the page <h1> is a human title derived from the week's
        # TO/topic + page type — never the raw ``week_NN_summary`` page_id.
        _page_title = _humanize_page_title(
            page_id, _week_num, _page_type, _page_tos,
        )
        try:
            from Courseforge.scripts.generate_course import (  # noqa: PLC0415
                _wrap_page as _wrap_page_fn,
            )
            page_html = _wrap_page_fn(
                title=_page_title,
                course_code=course_code,
                week_num=_week_num,
                body_html=_body_html,
            )
        except Exception as _wrap_exc:  # noqa: BLE001 — never lose the page
            # Fallback: emit the same full <head> + <style> shell inline so the
            # page still inherits the stylesheet even if the import fails.
            from Courseforge.scripts.generate_course import (  # noqa: PLC0415
                COURSEFORGE_CSS as _CF_CSS,
            )
            logger.warning(
                "rewrite phase: _wrap_page unavailable (%s); emitting inline "
                "stylesheet shell for %s.", _wrap_exc, page_id,
            )
            import html as _html_mod
            _safe_title = _html_mod.escape(_page_title)
            page_html = (
                "<!DOCTYPE html>\n<html lang=\"en\"><head>"
                "<meta charset=\"UTF-8\">"
                "<meta name=\"viewport\" content=\"width=device-width, "
                "initial-scale=1.0\">"
                f"<title>{_safe_title}</title>"
                f"<style>{_CF_CSS}</style></head><body>"
                f'<main id="main-content" role="main">'
                f"<h1>{_safe_title}</h1>{_body_html}</main>"
                "</body></html>"
            )
        try:
            page_path.write_text(page_html, encoding="utf-8")
            page_paths.append(str(page_path))
        except OSError as exc:
            logger.warning(
                "rewrite phase: failed to write %s: %s", page_path, exc,
            )

    if capture is not None:
        try:
            capture.log_decision(
                decision_type="phase_start",
                decision=(
                    f"content_generation_rewrite: emitted "
                    f"{len(rewrite_blocks)} rewrite-tier blocks across "
                    f"{len(page_paths)} pages."
                ),
                rationale=(
                    f"Pre-filtered route() per block with tier='rewrite'; "
                    f"persisted to {blocks_final_path.name} for "
                    f"post_rewrite_validation to consume."
                ),
                ml_features={
                    "block_count": len(rewrite_blocks),
                    "page_count": len(page_paths),
                    "tier": "rewrite",
                },
            )
        except Exception:  # noqa: BLE001
            pass

    return json.dumps({
        "success": True,
        "content_paths": ",".join(page_paths),
        "page_paths": page_paths,
        "content_dir": str(content_dir),
        "blocks_final_path": str(blocks_final_path),
        "project_id": project_id,
        "block_count": len(rewrite_blocks),
    })


# =============================================================================
# Heading-judge phase (SEMANTIK_HEADING_JUDGE) — permanent pipeline wiring
# =============================================================================
# Post-conversion Super heading-level JUDGE over the GLM-OCR lane's
# ``{stem}.glmocr_layout.json`` sidecars, wired as the ``heading_judge``
# validator-only phase between ``semantik_conversion`` and ``staging``
# (routed by NAME via ``MCP/core/executor.py::_PHASE_TOOL_MAPPING``).
# Contract:
#
#   * SEMANTIK_HEADING_JUDGE is DEFAULT-ON (owner directive: the Super
#     heading-level judge must not be optional). Only an explicit falsey
#     token ({0,false,no,off}, case-insensitive) opts out -> skip-with-pass
#     (byte-identical no-op); unset / blank / garbage / truthy -> the phase
#     runs (the ED4ALL_GPU_LIFECYCLE default-ON house pattern).
#   * no ``*.glmocr_layout.json`` -> skip-with-pass (born-digital corpus).
#   * SCOPED to THIS run's own corpus (``_heading_judge_corpus_stems``): a
#     campaign shares ONE corpus directory across books, so an unscoped glob
#     judged — and copied back over — a DIFFERENT book's leftover sidecars
#     (2026-07-22 shared-corpus-dir incident). A foreign stem is never judged,
#     never copied back, and never counted. An unresolvable stem set keeps the
#     legacy unscoped behavior but logs it LOUDLY.
#   * a chapter whose pendings end 100% UNJUDGED is a REAL FAILURE: it is
#     counted (``chapters_unjudged``), logged at ERROR, and its warning names
#     the MECHANISM the judge reported (seat aborted / seat unreachable /
#     length-exhausted / empty content / parse failure) instead of the old
#     anonymous "truncation hole" phrasing that hid a killed seat.
#   * per chapter: run the standalone judge as a SUBPROCESS
#     (``python -m semantik_structure.glmocr.heading_judge_standalone
#     <layout> --apply --out <dir>`` with cwd = the SemantiK repo root) and
#     COPY BACK: judged ``{stem}_accessible.html`` OVERWRITES the conversion
#     output HTML (keeping ``.prejudge.bak``); corrected escalations
#     OVERWRITE ``<corpus>/{stem}.glmocr_escalations.jsonl`` (keeping
#     ``.bak``). ``{stem}.glmocr_layout.json`` is NEVER overwritten — the
#     judge's ``corrected_layout.json`` has a DIFFERENT shape
#     (region_provenance + heading_tree, not pages).
#   * ``.prejudge.bak`` NAMING (documented, deliberately NOT renamed — other
#     tooling and shipped artifacts depend on the name): it is the conversion
#     output as it stood BEFORE **THIS PHASE's** copy-back, NOT "before any
#     judging". SEMANTIK_HEADING_JUDGE gates the judge in TWO places — the
#     IN-LANE pass inside ``semantik_conversion`` (SemantiK
#     ``glmocr/lane.py`` step 3b) and this standalone phase — so on a normal
#     build the backup is ALREADY a judged render and a judged HTML that is
#     byte-identical to it is the CORRECT outcome of an idempotent re-judge,
#     never a dropped verdict (2026-07-22 misdiagnosis).
#   * REPORTING (2026-07-22 misdiagnosis guard): ``applied`` counts verdicts
#     RECORDED; only ``changed`` (the subset whose level actually moved) can
#     alter an emitted ``<hN>``. Both are surfaced separately in the summary
#     line, the phase output JSON (``total_applied`` / ``total_changed`` /
#     ``total_agreed`` / ``level_transitions``) and the DecisionCapture, and
#     the summary additionally reports the MEASURED render-vs-pre-judge
#     comparison (``chapters_render_unchanged`` / ``_compared``) so an
#     idempotent re-judge names itself instead of looking like a first pass.
#   * FAIL-OPEN per chapter: nonzero exit / timeout -> warning + continue
#     (the corpus keeps that chapter's pre-judge HTML); the phase always
#     completes successfully with a warnings list. Never blocks the build.
#   * graceful stop: the run-scoped stop sentinel is polled between
#     chapters (``check_stop`` — the standard phase-helper contract).
#   * OP2 metering: the subprocess env carries SEMANTIK_LLM_USAGE_PATH =
#     ``state/runs/<run_id>/llm_usage.jsonl`` + SEMANTIK_LLM_USAGE_PHASE =
#     ``heading_judge`` so each judge POST rows into the run's usage tap
#     (``semantik_structure/glmocr/heading_judge.py::_emit_usage_row``).
# =============================================================================

_HEADING_JUDGE_FLAG_ENV = "SEMANTIK_HEADING_JUDGE"
_HEADING_JUDGE_CHAPTER_TIMEOUT_ENV = "SEMANTIK_HEADING_JUDGE_CHAPTER_TIMEOUT"
_HEADING_JUDGE_CHAPTER_TIMEOUT_DEFAULT = 5400.0
_HEADING_JUDGE_FALSEY = frozenset({"0", "false", "no", "off"})

# ── Post-judge deterministic AUDIT + opt-in targeted RE-JUDGE. ───────────────
_HEADING_JUDGE_AUDIT_FLAG_ENV = "SEMANTIK_HEADING_JUDGE_AUDIT"
_HEADING_JUDGE_REJUDGE_FLAG_ENV = "SEMANTIK_HEADING_JUDGE_REJUDGE"
_HEADING_JUDGE_REJUDGE_MAX_ATTEMPTS_ENV = (
    "SEMANTIK_HEADING_JUDGE_REJUDGE_MAX_ATTEMPTS"
)
_HEADING_JUDGE_TRUTHY = frozenset({"1", "true", "yes", "on"})
#: Bounded targeted-re-run rounds over the flagged set (a re-audit runs after
#: each round). Default 1 = one re-run pass + one re-audit (the task spec).
# TODO(calibration): 1 is the conservative default — measure whether a second
# round meaningfully recovers a still-collapsed chapter before raising it.
_HEADING_JUDGE_REJUDGE_MAX_ATTEMPTS_DEFAULT = 1
#: Audit subprocess is a fast deterministic pass — a modest fixed timeout.
_HEADING_JUDGE_AUDIT_TIMEOUT = 600.0


def _heading_judge_audit_enabled() -> bool:
    """SEMANTIK_HEADING_JUDGE_AUDIT — default ON (falsey-set opt-out).

    Report-only deterministic pass; only an explicit falsey token
    ({0,false,no,off}) disables. Mirrors _heading_judge_enabled's default-ON
    parse (the ED4ALL_GPU_LIFECYCLE house pattern). Byte-identical when ``=0``.
    """
    raw = (os.environ.get(_HEADING_JUDGE_AUDIT_FLAG_ENV) or "").strip().lower()
    return raw not in _HEADING_JUDGE_FALSEY


def _heading_judge_rejudge_enabled() -> bool:
    """SEMANTIK_HEADING_JUDGE_REJUDGE — default OFF (truthy-set opt-in).

    Behaviour-changing (re-runs the judge on flagged chapters), so it follows
    the house opt-in pattern rather than the audit's default-ON. Only truthy
    ({1,true,yes,on}) enables; unset / falsey / garbage → off.
    """
    raw = (os.environ.get(_HEADING_JUDGE_REJUDGE_FLAG_ENV) or "").strip().lower()
    return raw in _HEADING_JUDGE_TRUTHY


def _heading_judge_rejudge_max_attempts() -> int:
    """Bounded per-chapter re-run rounds; parse-with-fallback → 1."""
    raw = (
        os.environ.get(_HEADING_JUDGE_REJUDGE_MAX_ATTEMPTS_ENV) or ""
    ).strip()
    if raw:
        try:
            val = int(raw)
            if val >= 1:
                return val
        except ValueError:
            pass
    return _HEADING_JUDGE_REJUDGE_MAX_ATTEMPTS_DEFAULT


def _heading_judge_pos_int_env(name: str, default: int) -> int:
    """Positive-int env parse-with-fallback (re-judge window sizing)."""
    raw = (os.environ.get(name) or "").strip()
    try:
        val = int(raw)
        return val if val > 0 else default
    except ValueError:
        return default


def _heading_judge_run_audit(
    judge_python: str,
    judge_cwd: Any,
    judge_env: Dict[str, str],
    out_dir: Path,
    timeout: float = _HEADING_JUDGE_AUDIT_TIMEOUT,
) -> Optional[Dict[str, Any]]:
    """Shell out to the deterministic audit standalone over the judged
    ``{stem}.corrected_layout.json`` sidecars in ``out_dir``; return the parsed
    report dict (with an added ``report_path``) or ``None`` on any failure.

    Best-effort by contract: the audit failing NEVER fails the phase.
    Report-only — the audit never mutates a sidecar or HTML.
    """
    import subprocess  # noqa: PLC0415

    report_path = Path(out_dir) / "heading_judge_audit.json"
    cmd = [
        judge_python,
        "-m",
        "semantik_structure.glmocr.heading_judge_audit_standalone",
        str(out_dir),
        "--out",
        str(out_dir),
    ]
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(judge_cwd),
            capture_output=True,
            text=True,
            timeout=timeout,
            env=judge_env,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        logger.warning(
            "run_heading_judge: audit subprocess could not run (non-fatal): %s",
            exc,
        )
        return None
    if proc.returncode != 0:
        logger.warning(
            "run_heading_judge: audit exited %d (non-fatal). stderr tail: %s",
            proc.returncode,
            (proc.stderr or "").strip()[-300:],
        )
        return None
    try:
        data = json.loads(report_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        logger.warning(
            "run_heading_judge: audit report unreadable (non-fatal): %s", exc
        )
        return None
    if isinstance(data, dict):
        data["report_path"] = str(report_path)
        return data
    return None


async def _heading_judge_rejudge_flagged(
    flagged_stems: List[str],
    sidecars: List[Tuple[Path, Path]],
    *,
    judge_python: str,
    judge_cwd: Any,
    judge_env: Dict[str, str],
    out_dir: Path,
    timeout: float,
) -> Dict[str, Any]:
    """Targeted re-judge of ONLY the audit-flagged chapters (Part 2).

    Re-invokes the EXISTING per-chapter judge subprocess machinery on each
    flagged ``{stem}.glmocr_layout.json`` sidecar with SMALLER windows for the
    re-run only (a reduced ``SEMANTIK_HEADING_JUDGE_MAX_TOKENS`` shrinks the
    pending-window cap AND changes the per-window cache key + digest, and a
    halved ``SEMANTIK_HEADING_JUDGE_CTX_BUDGET`` re-windows the digest). This
    matters because the judge is ``temperature=0`` — a PLAIN re-run of a
    MODE-COLLAPSED chapter would serve the same cached verdict / reproduce the
    collapse, whereas smaller windows are a genuinely different roll AND less
    collapse-prone; a transient fail-open chapter (nothing cached) benefits
    from any re-run regardless.

    Copies back each successful re-run (judged HTML over the conversion output,
    corrected escalations over the corpus sidecar — the same ``.prejudge.bak`` /
    ``.bak`` contract as the main loop). Fail-open per chapter — a re-run that
    fails leaves that chapter's prior judged output in place.
    """
    import asyncio as _asyncio  # noqa: PLC0415
    import functools as _functools  # noqa: PLC0415
    import subprocess  # noqa: PLC0415

    from lib.paths import semantik_output_dir  # noqa: PLC0415

    flagged = set(flagged_stems)
    by_stem: Dict[str, Tuple[Path, Path]] = {}
    for layout, corpus_dir in sidecars:
        s = layout.name
        for suffix in (".glmocr_layout.json", ".json"):
            if s.endswith(suffix):
                s = s[: -len(suffix)]
                break
        by_stem.setdefault(s, (layout, corpus_dir))

    # Reduced-window env: smaller windows + a fresh cache key/digest so the
    # re-run is a GENUINE re-roll (not a cache-served reproduction of the
    # collapse at temperature=0).
    rej_env = dict(judge_env)
    cur_ceiling = _heading_judge_pos_int_env(
        "SEMANTIK_HEADING_JUDGE_MAX_TOKENS", 30000
    )
    cur_ctx = _heading_judge_pos_int_env(
        "SEMANTIK_HEADING_JUDGE_CTX_BUDGET", 31500
    )
    # 0.75x ceiling floored at 22880 keeps the derived pending-window cap >= 8
    # (floor 20480 + 8*300); 0.5x ctx re-windows the digest.
    rej_env["SEMANTIK_HEADING_JUDGE_MAX_TOKENS"] = str(
        max(22880, int(cur_ceiling * 0.75))
    )
    rej_env["SEMANTIK_HEADING_JUDGE_CTX_BUDGET"] = str(
        max(8000, int(cur_ctx * 0.5))
    )

    rejudged = 0
    warnings_out: List[str] = []
    for stem in sorted(flagged):
        entry = by_stem.get(stem)
        if entry is None:
            continue
        layout, corpus_dir = entry
        cmd = [
            judge_python,
            "-m",
            "semantik_structure.glmocr.heading_judge_standalone",
            str(layout),
            "--apply",
            "--out",
            str(out_dir),
        ]
        try:
            prior_html_path = semantik_output_dir() / f"{stem}_accessible.html"
            if prior_html_path.is_file():
                cmd += ["--source-html", str(prior_html_path)]
        except Exception:  # noqa: BLE001 — path resolution must not fail phase
            pass
        attempt_cmds: List[List[str]] = [cmd]
        if "--source-html" in cmd:
            legacy_cmd = list(cmd)
            flag_at = legacy_cmd.index("--source-html")
            del legacy_cmd[flag_at:flag_at + 2]
            attempt_cmds.append(legacy_cmd)

        proc = None
        failed = False
        for attempt_idx, attempt_cmd in enumerate(attempt_cmds):
            try:
                proc = await _asyncio.to_thread(
                    _functools.partial(
                        subprocess.run,
                        attempt_cmd,
                        cwd=str(judge_cwd),
                        capture_output=True,
                        text=True,
                        timeout=timeout,
                        env=rej_env,
                    )
                )
            except (
                subprocess.TimeoutExpired,
                OSError,
                subprocess.SubprocessError,
            ) as exc:
                failed = True
                warnings_out.append(
                    f"{stem}: targeted re-judge subprocess failed ({exc}); "
                    f"prior judged output kept (fail-open)."
                )
                logger.warning("run_heading_judge: %s", warnings_out[-1])
                break
            if (
                attempt_idx == 0
                and len(attempt_cmds) > 1
                and proc.returncode == 2
                and "--source-html" in (proc.stderr or "")
            ):
                continue
            break
        if failed or proc is None:
            continue
        if proc.returncode != 0:
            warnings_out.append(
                f"{stem}: targeted re-judge exited {proc.returncode}; prior "
                f"judged output kept (fail-open)."
            )
            logger.warning("run_heading_judge: %s", warnings_out[-1])
            continue
        copy_warnings, _copy_info = _heading_judge_copy_back(
            stem, out_dir, corpus_dir
        )
        warnings_out.extend(copy_warnings)
        rejudged += 1
    return {"rejudged": rejudged, "warnings": warnings_out}


def _heading_judge_enabled() -> bool:
    """Parse-with-fallback SEMANTIK_HEADING_JUDGE — default ON (deviation).

    Owner directive: the Super heading-level judge must not be optional. Only
    an explicit falsey token ({0,false,no,off}, case-insensitive) disables;
    unset / blank / garbage / truthy -> ON (mirrors the ED4ALL_GPU_LIFECYCLE
    default-ON house pattern). The born-digital no-sidecars skip and the
    per-chapter fail-open semantics are structural and unchanged.
    """
    raw = (os.environ.get(_HEADING_JUDGE_FLAG_ENV) or "").strip().lower()
    return raw not in _HEADING_JUDGE_FALSEY


def _resolve_heading_judge_chapter_timeout() -> float:
    """Per-chapter subprocess timeout (s); parse-with-fallback to 5400."""
    raw = (os.environ.get(_HEADING_JUDGE_CHAPTER_TIMEOUT_ENV) or "").strip()
    if raw:
        try:
            val = float(raw)
            if val > 0 and val == val and val not in (
                float("inf"), float("-inf")
            ):
                return val
        except ValueError:
            pass
    return _HEADING_JUDGE_CHAPTER_TIMEOUT_DEFAULT


def _heading_judge_corpus_dirs(pdf_paths: Any) -> List[Path]:
    """Resolve the corpus dir(s) that hold ``*.glmocr_layout.json`` sidecars.

    ``SEMANTIK_GLMOCR_OUTPUT_DIR`` (when set) wins — the GLM-OCR lane wrote
    its sidecars there. Otherwise each ``pdf_paths`` token (comma-separated
    string or list, mirroring the ``semantik_conversion`` param shape)
    contributes its own directory (dir token) or its parent (file token) —
    the lane's default sidecar location is the PDF's parent. Order-preserving
    dedupe.
    """
    explicit = (os.environ.get("SEMANTIK_GLMOCR_OUTPUT_DIR") or "").strip()
    if explicit:
        return [Path(explicit)]
    if isinstance(pdf_paths, (list, tuple)):
        tokens = [str(t).strip() for t in pdf_paths if str(t).strip()]
    elif pdf_paths:
        tokens = [t.strip() for t in str(pdf_paths).split(",") if t.strip()]
    else:
        tokens = []
    dirs: List[Path] = []
    seen: Set[str] = set()
    for tok in tokens:
        p = Path(tok)
        d = p if p.is_dir() else p.parent
        key = str(d.resolve()) if d.exists() else str(d)
        if key not in seen:
            seen.add(key)
            dirs.append(d)
    return dirs


#: File extensions that name a CORPUS INPUT (the thing SemantiK converts). The
#: GLM-OCR lane names its sidecars ``{input stem}.glmocr_layout.json``, so the
#: stems of this run's own corpus inputs are exactly the sidecars it owns.
_HEADING_JUDGE_CORPUS_SUFFIXES = frozenset({
    ".pdf", ".htm", ".html", ".xhtml", ".md", ".markdown", ".txt", ".epub",
})


def _heading_judge_corpus_stems(pdf_paths: Any) -> Set[str]:
    """Stems of THIS run's own corpus inputs — the sidecar ALLOWLIST.

    Cross-book contamination guard (2026-07-22 shared-corpus-dir incident): the
    campaign points every run at ONE book inside a SHARED corpus directory
    (``--corpus <dir>/<book>.pdf``), so ``_heading_judge_corpus_dirs`` resolves
    to that shared directory and a bare ``*.glmocr_layout.json`` glob picks up
    EVERY other book's leftover sidecars. In the incident a run judged a
    FOREIGN book (105 pendings of a different title), burned the seat on it,
    and copied judged HTML + corrected escalations back over that other book's
    conversion output (its ``.glmocr_escalations.jsonl.bak`` is the fingerprint).

    A FILE token contributes its own stem; a DIRECTORY token contributes the
    stems of the corpus-input files it holds (non-recursive — the
    ``--corpus <dir>/`` shape). An EMPTY result means the stems could not be
    resolved (e.g. only ``SEMANTIK_GLMOCR_OUTPUT_DIR`` is set), and the caller
    then keeps the legacy unscoped behavior with a LOUD warning rather than
    silently judging nothing.
    """
    if isinstance(pdf_paths, (list, tuple)):
        tokens = [str(t).strip() for t in pdf_paths if str(t).strip()]
    elif pdf_paths:
        tokens = [t.strip() for t in str(pdf_paths).split(",") if t.strip()]
    else:
        tokens = []

    stems: Set[str] = set()
    for tok in tokens:
        p = Path(tok)
        if p.is_dir():
            try:
                children = sorted(p.iterdir())
            except OSError:
                continue
            for child in children:
                if (
                    child.is_file()
                    and child.suffix.lower() in _HEADING_JUDGE_CORPUS_SUFFIXES
                ):
                    stems.add(child.stem)
        else:
            # A file token (existing or not — resume paths may name a moved
            # input): its stem is authoritative for THIS run.
            if p.suffix.lower() in _HEADING_JUDGE_CORPUS_SUFFIXES:
                stems.add(p.stem)
            elif p.name:
                stems.add(p.stem or p.name)
    return stems


def _heading_judge_residual_pending(escalations_path: Path) -> int:
    """Count remaining ``heading_level_pending`` rows in a corrected
    escalations sidecar (best-effort; unreadable -> 0)."""
    count = 0
    try:
        with escalations_path.open(encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    row = json.loads(line)
                except ValueError:
                    continue
                if (
                    isinstance(row, dict)
                    and row.get("reason") == "heading_level_pending"
                ):
                    count += 1
    except OSError:
        return 0
    return count


def _heading_judge_change_counts(
    report: Dict[str, Any],
) -> Tuple[int, int, Dict[str, int]]:
    """``(changed, agreed, transitions)`` for one chapter's judge report.

    ``applied`` counts verdicts RECORDED; only the subset whose level actually
    MOVED can alter a rendered ``<hN>``. The 2026-07-22 misdiagnosis read an
    ``applied=58`` summary as "58 headings re-levelled" when 30 of those
    verdicts merely re-confirmed the level already on the region.

    Prefers the report's own ``changed``/``agreed``/``transitions`` keys; a
    LEGACY report (written before those keys existed) is reconstructed from its
    per-heading ``judgments`` map (``{"<rid>": {"from": x, "to": y}}``) rather
    than silently assumed to be all-changed.
    """
    applied = int(report.get("applied") or 0)
    if "changed" in report:
        changed = int(report.get("changed") or 0)
        agreed = int(report.get("agreed", applied - changed) or 0)
        raw = report.get("transitions") or {}
        transitions = {
            str(k): int(v) for k, v in raw.items()
            if isinstance(v, (int, float))
        } if isinstance(raw, dict) else {}
        return changed, agreed, transitions

    judgments = report.get("judgments")
    if not isinstance(judgments, dict) or not judgments:
        # Nothing to reconstruct from — report the honest unknown as 0/0 and
        # let the caller's "comparison unavailable" wording carry it.
        return 0, applied, {}
    changed = 0
    transitions: Dict[str, int] = {}
    for row in judgments.values():
        if not isinstance(row, dict):
            continue
        try:
            frm = int(row.get("from"))
            to = int(row.get("to"))
        except (TypeError, ValueError):
            continue
        if frm != to:
            changed += 1
            key = f"{frm}->{to}"
            transitions[key] = transitions.get(key, 0) + 1
    return changed, max(0, applied - changed), transitions


def _heading_judge_format_transitions(
    transitions: Dict[str, int], *, limit: int = 6
) -> str:
    """``{"3->2": 28}`` -> ``"3->2 x28"`` (busiest first, bounded). Empty -> ``""``."""
    if not transitions:
        return ""
    rows = sorted(transitions.items(), key=lambda kv: (-kv[1], kv[0]))
    out = ", ".join(f"{k} x{v}" for k, v in rows[:limit])
    if len(rows) > limit:
        out += f", +{len(rows) - limit} more"
    return out


def _heading_judge_copy_back(
    stem: str, judged_dir: Path, corpus_dir: Path
) -> Tuple[List[str], Dict[str, Any]]:
    """COPY-BACK contract (validated live): judged HTML over the conversion
    output (``.prejudge.bak`` kept), corrected escalations over the corpus
    sidecar (``.bak`` kept). NEVER touches ``{stem}.glmocr_layout.json``.

    Returns ``(warnings, info)``. Warnings (missing judged artifact / copy
    failure) never fail the phase (fail-open). ``info`` carries
    ``render_changed`` — ``True``/``False`` when the judged HTML could be
    compared byte-for-byte against the conversion output it replaces, ``None``
    when no comparison was possible (no prior file / unreadable / no judged
    HTML). That comparison is the ONLY honest signal for "did this phase
    actually change anything on disk", and it is what distinguishes a real
    first-pass re-levelling from an IDEMPOTENT RE-JUDGE of a conversion whose
    in-lane judge had already applied the same levels.
    """
    from lib.paths import semantik_output_dir  # noqa: PLC0415

    warnings_out: List[str] = []
    info: Dict[str, Any] = {"render_changed": None}

    html_src = judged_dir / f"{stem}_accessible.html"
    if html_src.is_file():
        try:
            html_dest = semantik_output_dir() / f"{stem}_accessible.html"
            html_dest.parent.mkdir(parents=True, exist_ok=True)
            merged_text: Optional[str] = None
            prior_text: Optional[str] = None
            if html_dest.exists():
                # NAMING HONESTY (2026-07-22): ``.prejudge.bak`` means "before
                # THIS PHASE's copy-back", NOT "before any judging". The judge
                # runs TWICE under one flag — once IN-LANE during
                # ``semantik_conversion`` (SemantiK .../glmocr/lane.py step 3b,
                # which is what produced this very file) and again here as the
                # standalone ``heading_judge`` phase. So on a normal build this
                # backup is ALREADY a judged render, and a judged HTML that is
                # byte-identical to it is the CORRECT result of an idempotent
                # re-judge — never evidence of a dropped verdict. The file name
                # is load-bearing for other tooling and today's artifacts, so it
                # is documented rather than renamed.
                shutil.copy2(
                    html_dest,
                    html_dest.parent / f"{html_dest.name}.prejudge.bak",
                )
                try:
                    prior_text = html_dest.read_text(encoding="utf-8")
                except (OSError, UnicodeDecodeError):
                    prior_text = None
                # Figure-enrichment preservation (belt-and-suspenders — the
                # standalone judge already merges when handed --source-html):
                # the judge re-renders from the layout sidecar, which never
                # carried the VLM alt-text enrichment, so a VLM-captioned
                # figure degrades to the sr-only "Figure." placeholder.
                # Restore degraded figure captions/alt from the enriched
                # pre-judge HTML before it is overwritten (ADD-only; the
                # judged heading levels are untouched by construction).
                try:
                    from lib.semantik.figure_enrich_merge import (  # noqa: PLC0415
                        merge_figure_enrichment,
                    )

                    judged_text = html_src.read_text(encoding="utf-8")
                    candidate, restored = merge_figure_enrichment(
                        prior_text if prior_text is not None
                        else html_dest.read_text(encoding="utf-8"),
                        judged_text,
                    )
                    if restored > 0:
                        merged_text = candidate
                        logger.info(
                            "heading_judge copy-back: restored %d degraded "
                            "figure caption(s)/alt on %s from the pre-judge "
                            "enriched HTML",
                            restored,
                            stem,
                        )
                except Exception as exc:  # noqa: BLE001 — merge is best-effort
                    warnings_out.append(
                        f"{stem}: figure-enrichment merge failed ({exc}); "
                        f"judged HTML copied unmerged"
                    )
            if merged_text is not None:
                html_dest.write_text(merged_text, encoding="utf-8")
            else:
                shutil.copy2(html_src, html_dest)
            # Did this phase actually change the shipped render? Compare the
            # bytes it just wrote against the bytes it replaced. This is a
            # MEASUREMENT, not an inference: identical bytes mean the judged
            # levels were already on disk (the in-lane judge ran during
            # conversion), so the phase re-judged idempotently.
            if prior_text is not None:
                try:
                    final_text = (
                        merged_text if merged_text is not None
                        else html_dest.read_text(encoding="utf-8")
                    )
                    info["render_changed"] = final_text != prior_text
                except (OSError, UnicodeDecodeError):
                    info["render_changed"] = None
        except OSError as exc:
            warnings_out.append(
                f"{stem}: judged-HTML copy-back failed ({exc}); "
                f"pre-judge HTML kept"
            )
    else:
        warnings_out.append(
            f"{stem}: judged HTML missing at {html_src} (re-render skipped "
            f"in the judge subprocess?); pre-judge HTML kept"
        )

    esc_src = judged_dir / f"{stem}.glmocr_escalations.jsonl"
    if esc_src.is_file():
        try:
            esc_dest = corpus_dir / f"{stem}.glmocr_escalations.jsonl"
            if esc_dest.exists():
                shutil.copy2(
                    esc_dest, esc_dest.parent / f"{esc_dest.name}.bak"
                )
            shutil.copy2(esc_src, esc_dest)
        except OSError as exc:
            warnings_out.append(
                f"{stem}: corrected-escalations copy-back failed ({exc}); "
                f"pre-judge escalations kept"
            )
    else:
        warnings_out.append(
            f"{stem}: corrected escalations missing at {esc_src}; "
            f"pre-judge escalations kept"
        )
    return warnings_out, info


def _emit_heading_judge_capture(
    course_code: str, stem: str, report: Dict[str, Any]
) -> None:
    """One ``structure_review`` DecisionCapture per successfully judged
    chapter, with the ``heading_level_judge`` metadata discriminator.
    Best-effort — a capture failure never breaks the phase."""
    try:
        from lib.decision_capture import DecisionCapture  # noqa: PLC0415

        applied = int(report.get("applied") or 0)
        kept = int(report.get("kept") or 0)
        clamped = int(report.get("clamped") or 0)
        dropped = int(report.get("dropped") or 0)
        windows = int(report.get("windows") or 0)
        n_pending = int(report.get("n_pending") or 0)
        model = str(report.get("model") or "unknown")
        # Fix-2 accounting distinction (kept == kept_judged + unjudged). A
        # legacy report without the keys treats every kept as judged-kept.
        unjudged = int(report.get("unjudged") or 0)
        kept_judged = int(report.get("kept_judged", kept - unjudged) or 0)
        # VERDICT RECORDED vs LEVEL CHANGED (2026-07-22): a legacy report
        # without the keys is reconstructed from its own per-heading
        # ``judgments`` map rather than assumed to be all-changed.
        changed, agreed, transitions = _heading_judge_change_counts(report)

        capture = DecisionCapture(
            course_code=course_code or stem or "unknown",
            phase="semantik_conversion",
            tool="semantik",
        )
        # DYNAMIC rationale (>=20 chars) — interpolates the chapter's own
        # judgment tallies + the judge model so the capture is replayable.
        rationale = (
            f"Heading-level judge ({model}) judged {n_pending} pending "
            f"heading(s) on {stem} across {windows} skeleton window(s): "
            f"{applied} verdict(s) applied, of which {changed} CHANGED a "
            f"level ({_heading_judge_format_transitions(transitions) or 'none'}) "
            f"and {agreed} AGREED with the pre-existing level (recorded, "
            f"render-invisible); {kept} kept at their "
            f"current level ({kept_judged} judged-kept, {unjudged} "
            f"UNJUDGED — no verdict ever covered them), {clamped} clamped "
            f"by the parent+1 contiguity contract, {dropped} fixed-anchor "
            f"target(s) dropped. Deterministic clamp re-stamped PENDING "
            f"headings only (levels, never text)."
        )
        capture.log_decision(
            decision_type="structure_review",
            decision=(
                f"heading_judge applied={applied} verdicts "
                f"(changed={changed}, agreed={agreed}) kept={kept} "
                f"clamped={clamped} dropped={dropped} windows={windows}"
            ),
            rationale=rationale,
            alternatives_considered=[
                {
                    "option": "keep the transform's flat level-3 default",
                    "reason_rejected": (
                        "heading_level_pending headings sit flat at level 3; "
                        "the judge re-levels them against the chapter's own "
                        "N.M spine under the no-skip clamp"
                    ),
                },
            ],
            # STRUCTURED discriminator (lands in record metadata) so
            # downstream analysis separates heading-judge rows from the
            # Stage-5d reviewer's structure_review rows on a FIELD.
            heading_level_judge=True,
            # ADDITIVE structured split so a query can filter on "actually
            # re-levelled" without re-parsing the rationale prose.
            hj_applied=applied,
            hj_changed=changed,
            hj_agreed=agreed,
        )
    except Exception as exc:  # noqa: BLE001 — best-effort; never break phase
        logger.warning(
            "heading_judge DecisionCapture failed (non-fatal) on %s: %s",
            stem,
            exc,
        )


async def _run_heading_judge(**kwargs) -> str:
    """Phase handler for the ``heading_judge`` textbook_to_course phase.

    Resolved kwargs (workflows.yaml ``inputs_from``):
        pdf_paths: the corpus param the ``semantik_conversion`` phase consumed
            (comma-separated PDF paths OR a directory) — the GLM-OCR layout
            sidecars live beside the PDFs (or in SEMANTIK_GLMOCR_OUTPUT_DIR).
        course_name: course code for DecisionCapture attribution.

    Output counts: ``chapters_judged`` (subprocess success, >=1 pending
    heading), ``chapters_skipped`` (subprocess success, zero pendings),
    ``chapters_failed`` (nonzero exit / timeout — fail-open),
    ``chapters_unjudged`` (subprocess success but 100% of that chapter's
    pendings came back UNJUDGED — a REAL failure, logged at ERROR),
    ``chapters_foreign_skipped`` / ``foreign_stems`` (leftover sidecars of
    OTHER books in a shared corpus dir, excluded from judging AND copy-back),
    plus ``total_applied`` / ``total_kept`` summed from the per-chapter
    reports and ``residual_pending`` summed from the corrected escalations.

    Verdict-vs-change accounting (2026-07-22): ``total_applied`` counts
    verdicts RECORDED — ``total_changed`` is the subset whose level actually
    MOVED (``total_applied == total_changed + total_agreed``), with
    ``level_transitions`` the ``{"3->2": 28}`` histogram over the changed
    ones. ``chapters_render_unchanged`` / ``chapters_render_compared`` report
    the MEASURED comparison of each judged HTML against the conversion output
    it replaced: all-unchanged means this phase re-judged an already-judged
    conversion idempotently (the in-lane judge ran during
    ``semantik_conversion``) and wrote nothing new — not a dropped verdict.
    """
    import asyncio as _asyncio
    import functools as _functools
    import subprocess  # noqa: PLC0415

    if not _heading_judge_enabled():
        logger.info(
            "run_heading_judge: %s explicitly off (opt-out token) — "
            "skip-with-pass (byte-identical no-op).",
            _HEADING_JUDGE_FLAG_ENV,
        )
        return json.dumps({
            "success": True,
            "skipped": True,
            "reason": "flag_off",
            "chapters_judged": 0,
            "chapters_skipped": 0,
            "chapters_failed": 0,
            "chapters_unjudged": 0,
            "chapters_foreign_skipped": 0,
            "total_applied": 0,
            "total_changed": 0,
            "total_agreed": 0,
            "level_transitions": {},
            "chapters_render_compared": 0,
            "chapters_render_unchanged": 0,
            "total_kept": 0,
            "total_kept_judged": 0,
            "total_unjudged": 0,
            "residual_pending": 0,
        })

    pdf_paths = kwargs.get("pdf_paths") or ""
    course_name = (
        kwargs.get("course_name") or kwargs.get("course_code") or ""
    )
    corpus_dirs = _heading_judge_corpus_dirs(pdf_paths)

    # SCOPE the sidecar set to THIS run's own conversion outputs. The corpus
    # dir is shared across a campaign, so an unscoped glob judges (and copies
    # back over!) other books' leftover sidecars — the 2026-07-22 cross-book
    # sweep. An unresolvable stem set keeps the legacy unscoped behavior, but
    # LOUDLY, so the degradation is never silent.
    own_stems = _heading_judge_corpus_stems(pdf_paths)
    sidecars: List[Tuple[Path, Path]] = []  # (layout_path, corpus_dir)
    foreign_stems: List[str] = []
    for d in corpus_dirs:
        try:
            layouts = sorted(d.glob("*.glmocr_layout.json"))
        except OSError:
            continue
        for layout in layouts:
            stem = layout.name[: -len(".glmocr_layout.json")]
            if own_stems and stem not in own_stems:
                foreign_stems.append(stem)
                continue
            sidecars.append((layout, d))
    if foreign_stems:
        logger.warning(
            "run_heading_judge: skipped %d FOREIGN layout sidecar(s) under %s "
            "that are not this run's corpus (%s) — a leftover sidecar from "
            "another book's run must never be judged, copied back, or counted: "
            "%s",
            len(foreign_stems),
            [str(d) for d in corpus_dirs],
            sorted(own_stems),
            foreign_stems,
        )
    if not own_stems:
        logger.warning(
            "run_heading_judge: could not resolve this run's corpus stems from "
            "pdf_paths=%r — judging EVERY *.glmocr_layout.json under %s "
            "(legacy unscoped behavior; a shared corpus dir will cross-judge "
            "other books).",
            pdf_paths,
            [str(d) for d in corpus_dirs],
        )
    if not sidecars:
        logger.info(
            "run_heading_judge: no *.glmocr_layout.json sidecars under %s — "
            "born-digital corpus; skip-with-pass.",
            [str(d) for d in corpus_dirs] or "<no corpus dirs>",
        )
        return json.dumps({
            "success": True,
            "skipped": True,
            "reason": "no_sidecars",
            "chapters_judged": 0,
            "chapters_skipped": 0,
            "chapters_failed": 0,
            "chapters_unjudged": 0,
            "chapters_foreign_skipped": len(foreign_stems),
            "total_applied": 0,
            "total_changed": 0,
            "total_agreed": 0,
            "level_transitions": {},
            "chapters_render_compared": 0,
            "chapters_render_unchanged": 0,
            "total_kept": 0,
            "total_kept_judged": 0,
            "total_unjudged": 0,
            "residual_pending": 0,
        })

    # Subprocess seat: SEMANTIK_PYTHON / SEMANTIK_RUNTIME_DIR when set (the
    # cross-venv bridge contract), else this interpreter + <repo>/SemantiK.
    from lib.paths import (  # noqa: PLC0415
        SEMANTIK_PATH,
        get_state_runs_dir,
        semantik_output_dir,
    )

    judge_python = (
        (os.environ.get(_SEMANTIK_PYTHON_ENV) or "").strip() or sys.executable
    )
    runtime_dir_raw = (
        os.environ.get(_SEMANTIK_RUNTIME_DIR_ENV) or ""
    ).strip()
    judge_cwd = Path(runtime_dir_raw) if runtime_dir_raw else SEMANTIK_PATH
    timeout = _resolve_heading_judge_chapter_timeout()

    # OP2 usage tap + judged-output dir: run-scoped when a run id resolves.
    run_id = (os.environ.get("ED4ALL_RUN_ID") or "").strip()
    usage_path: Optional[Path] = None
    out_dir: Optional[Path] = None
    if run_id:
        try:
            run_dir = get_state_runs_dir() / run_id
            usage_path = run_dir / "llm_usage.jsonl"
            out_dir = run_dir / "heading_judge"
        except Exception:  # noqa: BLE001 — path resolution must not fail phase
            usage_path = None
            out_dir = None
    if out_dir is None:
        out_dir = sidecars[0][1] / "heading_judge_out"
    out_dir.mkdir(parents=True, exist_ok=True)

    judge_env = dict(os.environ)
    judge_env[_HEADING_JUDGE_FLAG_ENV] = "1"
    if usage_path is not None:
        judge_env["SEMANTIK_LLM_USAGE_PATH"] = str(usage_path)
        judge_env["SEMANTIK_LLM_USAGE_PHASE"] = "heading_judge"

    chapters_judged = 0
    chapters_skipped = 0
    chapters_failed = 0
    #: chapters whose pendings ended 100% UNJUDGED — a real failure the old
    #: "N judged / 0 failed" summary reported as a success (2026-07-22).
    chapters_unjudged = 0
    total_applied = 0
    #: verdicts that actually MOVED a level vs verdicts that re-confirmed the
    #: level already on the region — ``total_applied == changed + agreed``.
    #: Split so an operator can never read "applied=N" as "N headings moved".
    total_changed = 0
    total_agreed = 0
    total_transitions: Dict[str, int] = {}
    #: chapters whose judged HTML could be compared byte-for-byte against the
    #: conversion output it replaced, and how many of those came out IDENTICAL
    #: (the measured idempotent-re-judge signal).
    chapters_render_compared = 0
    chapters_render_unchanged = 0
    total_kept = 0
    total_kept_judged = 0
    total_unjudged = 0
    residual_pending = 0
    warnings_list: List[str] = []

    for idx, (layout, corpus_dir) in enumerate(sidecars):
        # Graceful-stop contract: poll the run-scoped stop sentinel at every
        # chapter boundary (raises GracefulStopRequested -> the phase pauses;
        # the judge's per-window resume cache makes the resume nearly free).
        check_stop("heading_judge", idx)

        stem = layout.name
        for suffix in (".glmocr_layout.json", ".json"):
            if stem.endswith(suffix):
                stem = stem[: -len(suffix)]
                break

        cmd = [
            judge_python,
            "-m",
            "semantik_structure.glmocr.heading_judge_standalone",
            str(layout),
            "--apply",
            "--out",
            str(out_dir),
        ]
        # Figure-enrichment preservation: the layout sidecar carries the RAW
        # GLM pages only — the VLM alt-text enrichment lives solely in the
        # prior rendered conversion output — so hand the standalone judge the
        # prior HTML to restore degraded figure captions from (ADD-only; the
        # copy-back merge below is the belt-and-suspenders for older judge
        # subprocesses that ignore the flag).
        try:
            prior_html_path = (
                semantik_output_dir() / f"{stem}_accessible.html"
            )
            if prior_html_path.is_file():
                cmd += ["--source-html", str(prior_html_path)]
        except Exception:  # noqa: BLE001 — path resolution must not fail phase
            pass
        # Legacy-runtime compat: a SEMANTIK_PYTHON/SEMANTIK_RUNTIME_DIR
        # pointing at an older SemantiK checkout whose standalone judge does
        # not know --source-html would argparse-exit 2 — retry ONCE without
        # the flag (the copy-back merge below still restores the figure
        # enrichment Ed4All-side).
        attempt_cmds: List[List[str]] = [cmd]
        if "--source-html" in cmd:
            legacy_cmd = list(cmd)
            flag_at = legacy_cmd.index("--source-html")
            del legacy_cmd[flag_at:flag_at + 2]
            attempt_cmds.append(legacy_cmd)

        proc = None
        subprocess_failed = False
        for attempt_idx, attempt_cmd in enumerate(attempt_cmds):
            try:
                proc = await _asyncio.to_thread(
                    _functools.partial(
                        subprocess.run,
                        attempt_cmd,
                        cwd=str(judge_cwd),
                        capture_output=True,
                        text=True,
                        timeout=timeout,
                        env=judge_env,
                    )
                )
            except subprocess.TimeoutExpired:
                subprocess_failed = True
                warnings_list.append(
                    f"{stem}: heading judge timed out after {timeout:.0f}s; "
                    f"pre-judge HTML kept (fail-open). Raise "
                    f"{_HEADING_JUDGE_CHAPTER_TIMEOUT_ENV} if the chapter "
                    f"legitimately needs longer."
                )
                logger.warning("run_heading_judge: %s", warnings_list[-1])
                break
            except (OSError, subprocess.SubprocessError) as exc:
                subprocess_failed = True
                warnings_list.append(
                    f"{stem}: heading judge subprocess could not run "
                    f"({judge_python}): {exc}; pre-judge HTML kept "
                    f"(fail-open)."
                )
                logger.warning("run_heading_judge: %s", warnings_list[-1])
                break
            if (
                attempt_idx == 0
                and len(attempt_cmds) > 1
                and proc.returncode == 2
                and "--source-html" in (proc.stderr or "")
            ):
                logger.warning(
                    "run_heading_judge: %s — judge runtime does not know "
                    "--source-html (legacy checkout?); retrying without it "
                    "(the copy-back merge still restores figure enrichment).",
                    stem,
                )
                continue
            break
        if subprocess_failed:
            chapters_failed += 1
            continue

        if proc.returncode != 0:
            stderr_tail = (proc.stderr or "").strip()[-400:]
            chapters_failed += 1
            warnings_list.append(
                f"{stem}: heading judge exited {proc.returncode}; pre-judge "
                f"HTML kept (fail-open). stderr tail: {stderr_tail}"
            )
            logger.warning("run_heading_judge: %s", warnings_list[-1])
            continue

        # Success: COPY BACK (never the layout sidecar), then tally + capture.
        copy_warnings, copy_info = _heading_judge_copy_back(
            stem, out_dir, corpus_dir
        )
        warnings_list.extend(copy_warnings)
        render_changed = copy_info.get("render_changed")
        if render_changed is not None:
            chapters_render_compared += 1
            if not render_changed:
                chapters_render_unchanged += 1

        report: Dict[str, Any] = {}
        report_path = out_dir / f"{stem}.heading_judgments.json"
        try:
            loaded = json.loads(report_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                report = loaded
        except (OSError, ValueError):
            warnings_list.append(
                f"{stem}: heading_judgments.json unreadable at {report_path}"
            )

        if int(report.get("n_pending") or 0) > 0:
            chapters_judged += 1
        else:
            chapters_skipped += 1
        total_applied += int(report.get("applied") or 0)
        ch_changed, ch_agreed, ch_transitions = _heading_judge_change_counts(
            report
        )
        total_changed += ch_changed
        total_agreed += ch_agreed
        for _k, _v in ch_transitions.items():
            total_transitions[_k] = total_transitions.get(_k, 0) + int(_v)
        chapter_kept = int(report.get("kept") or 0)
        total_kept += chapter_kept
        # Fix-2 accounting distinction: judged-kept vs UNJUDGED (the
        # truncation hole). A legacy report without the keys counts every
        # kept as judged-kept (unjudged unknowable there → 0).
        chapter_unjudged = int(report.get("unjudged") or 0)
        total_unjudged += chapter_unjudged
        total_kept_judged += int(
            report.get("kept_judged", chapter_kept - chapter_unjudged) or 0
        )
        if chapter_unjudged > 0:
            report_meta = report.get("meta") or {}
            unjudged_ids = report_meta.get("unjudged_ids")
            # The MECHANISM is mandatory in the operator warning: before the
            # 2026-07-22 incident every non-verdict read as an anonymous
            # "truncation hole", so a seat that was stopped mid-flight looked
            # exactly like an over-deliberating model.
            mechanism = (
                report.get("unjudged_reason")
                or report_meta.get("unjudged_reason")
                or "UNKNOWN (the judge reported no failure mechanism)"
            )
            modes = (
                report.get("failure_modes")
                or report_meta.get("failure_modes")
                or []
            )
            chapter_pending = int(report.get("n_pending") or 0)
            total_hole = (
                chapter_pending > 0 and chapter_unjudged >= chapter_pending
            )
            warnings_list.append(
                f"{stem}: {chapter_unjudged} of {chapter_pending} pending "
                f"heading(s) UNJUDGED"
                + (" — 100% of this chapter's pendings; the judge produced NO "
                   "usable verdict, every pre-judge level was KEPT "
                   "(fail-open). This is a REAL FAILURE, not a judged-keep."
                   if total_hole else
                   " (no verdict ever covered them; NOT judged-kept)")
                + f" MECHANISM: {mechanism}"
                + (f" [modes: {','.join(str(m) for m in modes)}]"
                   if modes else "")
                + (f"; region ids: {unjudged_ids}" if unjudged_ids else "")
            )
            if total_hole:
                chapters_unjudged += 1
                logger.error("run_heading_judge: %s", warnings_list[-1])
            else:
                logger.warning("run_heading_judge: %s", warnings_list[-1])
        residual_pending += _heading_judge_residual_pending(
            out_dir / f"{stem}.glmocr_escalations.jsonl"
        )
        _emit_heading_judge_capture(course_name, stem, report)

    # ── Deterministic post-judge AUDIT (SEMANTIK_HEADING_JUDGE_AUDIT, default
    # ON) + opt-in targeted RE-JUDGE (SEMANTIK_HEADING_JUDGE_REJUDGE, OFF). ──
    audit_report_path: Optional[str] = None
    chapters_flagged = 0
    chapters_collapsed = 0
    inconsistent_signature_count = 0
    audit_flagged_stems: List[str] = []
    if _heading_judge_audit_enabled():
        audit_report = await _asyncio.to_thread(
            _heading_judge_run_audit, judge_python, judge_cwd, judge_env, out_dir
        )
        if audit_report is not None:
            audit_report_path = audit_report.get("report_path")
            book = audit_report.get("book") or {}
            audit_flagged_stems = [
                str(s) for s in (audit_report.get("flagged_chapters") or [])
            ]
            chapters_flagged = len(audit_flagged_stems)
            chapters_collapsed = len(book.get("collapsed_chapters") or [])
            inconsistent_signature_count = len(
                book.get("inconsistent_signatures") or []
            )
            logger.info(
                "run_heading_judge: audit flagged %d chapter(s) "
                "(%d collapsed), %d inconsistent cross-chapter signature(s) "
                "[ADVISORY]; report: %s",
                chapters_flagged,
                chapters_collapsed,
                inconsistent_signature_count,
                audit_report_path,
            )

            # ── Targeted RE-JUDGE (opt-in) of ONLY the flagged chapters. ──
            if _heading_judge_rejudge_enabled() and audit_flagged_stems:
                before_flagged = list(audit_flagged_stems)
                max_attempts = _heading_judge_rejudge_max_attempts()
                current_flagged = list(audit_flagged_stems)
                total_rejudged = 0
                attempt = 0
                while current_flagged and attempt < max_attempts:
                    attempt += 1
                    rej = await _heading_judge_rejudge_flagged(
                        current_flagged,
                        sidecars,
                        judge_python=judge_python,
                        judge_cwd=judge_cwd,
                        judge_env=judge_env,
                        out_dir=out_dir,
                        timeout=timeout,
                    )
                    warnings_list.extend(rej.get("warnings") or [])
                    total_rejudged += int(rej.get("rejudged") or 0)
                    # Re-run the audit once per round (a still-flagged chapter
                    # STAYS flagged — reported, fail-open, never blocks).
                    after_report = await _asyncio.to_thread(
                        _heading_judge_run_audit,
                        judge_python,
                        judge_cwd,
                        judge_env,
                        out_dir,
                    )
                    if after_report is None:
                        break
                    book = after_report.get("book") or {}
                    audit_report_path = after_report.get("report_path")
                    audit_flagged_stems = [
                        str(s)
                        for s in (after_report.get("flagged_chapters") or [])
                    ]
                    chapters_flagged = len(audit_flagged_stems)
                    chapters_collapsed = len(book.get("collapsed_chapters") or [])
                    inconsistent_signature_count = len(
                        book.get("inconsistent_signatures") or []
                    )
                    current_flagged = list(audit_flagged_stems)
                logger.info(
                    "run_heading_judge: targeted re-judge re-ran %d chapter(s) "
                    "over %d round(s); flagged before=%d after=%d (delta=%d) — "
                    "still-flagged chapters stay reported (fail-open, never "
                    "blocks the build)",
                    total_rejudged,
                    attempt,
                    len(before_flagged),
                    len(audit_flagged_stems),
                    len(before_flagged) - len(audit_flagged_stems),
                )

    # ── Unambiguous summary (2026-07-22 misdiagnosis guard). ─────────────
    # Two things the old one-liner conflated, both now spelled out:
    #   (1) applied=N read as "N headings re-levelled"; it counts VERDICTS
    #       RECORDED, of which only ``changed`` can move a rendered <hN>.
    #   (2) nothing said whether this was a FIRST judging pass or an
    #       IDEMPOTENT RE-JUDGE of a conversion the in-lane judge had already
    #       levelled — so byte-identical output looked like a dropped verdict.
    # The idempotency clause is MEASURED (judged HTML vs the bytes it
    # replaced), never inferred; when no comparison was possible we say so.
    transitions_str = _heading_judge_format_transitions(total_transitions)
    transitions_suffix = f" [{transitions_str}]" if transitions_str else ""

    if chapters_render_compared and (
        chapters_render_unchanged == chapters_render_compared
    ):
        render_clause = (
            "; render byte-identical to the pre-judge output on all %d "
            "chapter(s) — IDEMPOTENT RE-JUDGE (the in-lane judge had already "
            "applied these levels during semantik_conversion); this phase "
            "changed nothing on disk" % chapters_render_compared
        )
    elif chapters_render_unchanged:
        render_clause = (
            "; render byte-identical to the pre-judge output on %d of %d "
            "chapter(s) (idempotent re-judge for those)"
            % (chapters_render_unchanged, chapters_render_compared)
        )
    elif chapters_render_compared:
        render_clause = (
            "; render CHANGED on all %d chapter(s)" % chapters_render_compared
        )
    elif total_applied and not total_changed:
        render_clause = (
            "; 0 level changes (layout already judged or judge agreed) — "
            "render-vs-pre-judge comparison unavailable"
        )
    else:
        render_clause = "; render-vs-pre-judge comparison unavailable"

    summary_args = (
        chapters_judged,
        chapters_skipped,
        chapters_failed,
        chapters_unjudged,
        len(foreign_stems),
        total_applied,
        total_changed,
        total_agreed,
        transitions_suffix,
        total_kept,
        total_kept_judged,
        total_unjudged,
        residual_pending,
        render_clause,
    )
    summary_fmt = (
        "run_heading_judge: %d judged / %d zero-pending / %d failed "
        "(fail-open) / %d FULLY-UNJUDGED / %d foreign-skipped; applied=%d "
        "verdicts (%d changed level, %d agreed with the pre-existing level)%s; "
        "kept=%d (judged-kept=%d, UNJUDGED=%d) residual_pending=%d%s"
    )
    # A run where every judged chapter came back 100% unjudged is NOT a
    # success summary — surface it at ERROR so the campaign log cannot read
    # "N judged / 0 failed" over a dead seat (2026-07-22 incident).
    if chapters_unjudged:
        logger.error(summary_fmt, *summary_args)
    else:
        logger.info(summary_fmt, *summary_args)
    return json.dumps({
        "success": True,
        "chapters_judged": chapters_judged,
        "chapters_skipped": chapters_skipped,
        "chapters_failed": chapters_failed,
        "chapters_unjudged": chapters_unjudged,
        "chapters_foreign_skipped": len(foreign_stems),
        "foreign_stems": sorted(set(foreign_stems)),
        "total_applied": total_applied,
        "total_changed": total_changed,
        "total_agreed": total_agreed,
        "level_transitions": dict(total_transitions),
        "chapters_render_compared": chapters_render_compared,
        "chapters_render_unchanged": chapters_render_unchanged,
        "total_kept": total_kept,
        "total_kept_judged": total_kept_judged,
        "total_unjudged": total_unjudged,
        "residual_pending": residual_pending,
        # Deterministic post-judge AUDIT fold (SEMANTIK_HEADING_JUDGE_AUDIT;
        # None/0 when the audit is opted out or produced no report).
        "audit_report_path": audit_report_path,
        "chapters_flagged": chapters_flagged,
        "chapters_collapsed": chapters_collapsed,
        "inconsistent_signature_count": inconsistent_signature_count,
        "warnings": warnings_list,
        "judged_dir": str(out_dir),
    })


# ── Chapter-ladder reconcile (SEMANTIK_CHAPTER_LADDER_RECONCILE) — per-chunk
# module_title resolution for a MULTI-CHAPTER single-file corpus. ────────────

_ARTICLE_CHAPTER_RE = re.compile(
    r"<article\b[^>]*role=\"doc-chapter\"[^>]*>", re.IGNORECASE
)
_ARTICLE_H2_RE = re.compile(r"<h2[^>]*>([^<]+)</h2>", re.IGNORECASE)
# Dual-read: the chunker's attribute harvest admits the legacy pre-SemantiK
# block-id spelling, so the module map must too.
_BLOCK_ID_ATTR_RE = re.compile(
    r"data-(?:semantik|dart)-block-id=\"([^\"]+)\"", re.IGNORECASE
)


def _chapter_ladder_reconcile_enabled() -> bool:
    """SEMANTIK_CHAPTER_LADDER_RECONCILE — default ON (falsey-set opt-out).

    Seam-side twin of the adapter/GLM-lane resolvers (mirrors the
    SEMANTIK_TITLE_SANITIZE precedent of a SEMANTIK_* flag consumed at the
    chunking sites). Only the explicit falsey tokens disable.
    """
    val = os.getenv("SEMANTIK_CHAPTER_LADDER_RECONCILE", "").strip().lower()
    return val not in {"0", "false", "no", "off"}


def _article_module_titles_by_block_id(raw_html: str) -> Optional[Dict[str, str]]:
    """Map ``data-semantik-block-id`` → enclosing chapter-article ``<h2>`` title.

    A whole-book accessible-HTML file carries MULTIPLE ``<article
    role="doc-chapter">`` chapters, but the chunking seam stamps every chunk's
    ``source.module_title`` from the file-level document title — on the
    whole-book reference corpus all 112 chunks collapsed onto the
    (already-defective) ``"Chapter 0"`` h1, flattening the book to one
    module for retrieval metadata. This helper derives the per-ARTICLE module map so each chunk's
    module_title resolves to its real chapter.

    Returns ``None`` (byte-identical legacy path) unless the file carries ≥2
    doc-chapter articles — a per-chapter corpus file has exactly one article,
    so the historical single-chapter shape is untouched BY CONSTRUCTION.
    Block-id keyed (each provenance-stamped section belongs to exactly one
    article), so duplicate section-heading TEXT across chapters can never
    misattribute a chunk.
    """
    if not raw_html:
        return None
    import html as _html

    articles = list(_ARTICLE_CHAPTER_RE.finditer(raw_html))
    if len(articles) < 2:
        return None
    spans: List[tuple] = []  # (start, end, title)
    for i, m in enumerate(articles):
        start = m.end()
        end = articles[i + 1].start() if i + 1 < len(articles) else len(raw_html)
        h2 = _ARTICLE_H2_RE.search(raw_html, start, end)
        title = _html.unescape(h2.group(1)).strip() if h2 else ""
        spans.append((m.start(), end, title))
    mapping: Dict[str, str] = {}
    for bid_match in _BLOCK_ID_ATTR_RE.finditer(raw_html):
        pos = bid_match.start()
        for start, end, title in spans:
            if start <= pos < end and title:
                mapping[bid_match.group(1)] = title
                break
    return mapping or None


def _build_tool_registry() -> dict:
    """
    Build a tool registry mapping tool names to callable async functions.

    Imports and wraps all MCP tool functions so the TaskExecutor
    can invoke them by name.
    """
    registry = {}

    # DART tools
    async def _extract_and_convert_pdf(**kwargs):
        """Extract text from PDF and convert to clean, accessible HTML.

        Strategy:
        1. Try multi-source synthesis if combined JSON exists
        2. Extract text via pdftotext
        3. Build clean semantic HTML from the extracted text
           (strips page numbers, TOC artifacts, headers/footers)
        """
        import asyncio as _asyncio
        import functools as _functools

        from lib.paths import SEMANTIK_PATH

        # C3-1 keystone fix: the SemantiK v2 cascade (and the mirroring
        # vendor-ingest seam) is a SYNC code path that drives sync Playwright
        # for the axe-core WCAG gate. Sync Playwright raises
        # ``It looks like you are using Playwright Sync API inside the asyncio
        # loop`` the moment it detects a running event loop. This handler is an
        # ``async def`` dispatched on the ed4all asyncio loop, so calling the
        # sync cascade in-line crashes raw-PDF ``dart_conversion``. Offload the
        # sync work to a worker thread (no running loop on that thread) so the
        # sync Playwright path is happy. The bridge subprocess fallback inside
        # ``_run_semantik_v2_conversion`` is preserved (it only fires when the
        # in-process import FAILS, which is orthogonal to this offload).
        async def _to_thread(_fn, *_args, **_kwargs):
            return await _asyncio.to_thread(
                _functools.partial(_fn, *_args, **_kwargs)
            )

        pdf_path = kwargs.get("pdf_path", "")
        course_code = kwargs.get("course_code")
        output_dir_str = kwargs.get("output_dir")

        pdf = Path(pdf_path)
        out_dir = Path(output_dir_str) if output_dir_str else SEMANTIK_PATH / "output"
        out_dir.mkdir(parents=True, exist_ok=True)

        # SemantiK migration — the LIVE textbook/course PDF→HTML conversion
        # dispatch runs the SemantiK v2 cascade seam
        # ``_run_semantik_v2_conversion``. SCOPED by phase name: only the
        # ``dart_conversion`` phase (``textbook_to_course`` /
        # ``course_generation``'s PDF-ingest path, built one-task-per-PDF in
        # ``workflow_runner._create_phase_tasks``) is supported. The legacy
        # DART converter was retired with the DART subsystem, so any other
        # phase falls through to a fail-closed-clear return below.
        #
        # Fails CLOSED with a clear SemantiK reason when the cascade is
        # unprovisioned — NEVER a silent fall-through to a deleted converter.
        #
        # DART->semantik purge (task #19, Stage 3d): the phase was renamed
        # ``dart_conversion`` -> ``semantik_conversion``. Both names route to
        # the cascade seam (dual-READ) so a NEW run (declaring
        # ``semantik_conversion``) AND an old resumed task (carrying the legacy
        # phase tag) both reach the SemantiK path.
        if kwargs.get("phase") in ("semantik_conversion", "dart_conversion"):
            # SemantiK migration P3d — INPUT-TYPE detection at the conversion
            # phase. A PDF input routes to the SemantiK cascade seam; an
            # already-accessible publisher HTML input (single .html/.htm file
            # OR a directory of HTML pages with no PDF) routes to the
            # vendor-ingest seam (``_run_vendor_ingest_conversion``), which
            # produces the SAME Ed4All output contract (same
            # {stem}_accessible.html + sidecars, same JSON keys) so staging /
            # source_refs / chunking see byte-identical artifacts. Detection
            # rule: see ``_detect_conversion_input_type`` — PDF wins a mixed
            # directory; an unknown input fails closed clear (no silent ship).
            input_type = _detect_conversion_input_type(pdf)
            if input_type == "vendor":
                # Derive the canonical stem from the input (dir name or file
                # stem) so the vendor seam writes {stem}_accessible.html into
                # the conversion output dir, exactly as the PDF seam does.
                vendor_stem = pdf.name if pdf.is_dir() else pdf.stem
                vendor_stem = vendor_stem or "vendor"
                html_output = out_dir / f"{vendor_stem}_accessible.html"
                ven_result = await _to_thread(
                    _run_vendor_ingest_conversion,
                    str(pdf),
                    str(html_output),
                    doc_title=kwargs.get("doc_title"),
                    capture=kwargs.get("capture"),
                    canonical_course_code=kwargs.get("canonical_course_code"),
                    reuse_conversion=kwargs.get("reuse_conversion"),
                )
                if not ven_result.get("success"):
                    return json.dumps({
                        "success": False,
                        "error": ven_result.get(
                            "error", "vendor-ingest conversion failed"
                        ),
                        "method": ven_result.get("method", "vendor_ingest"),
                        "output_path": ven_result.get(
                            "output_path", str(html_output)
                        ),
                        "html_path": ven_result.get(
                            "html_path", str(html_output)
                        ),
                    })
                return json.dumps(ven_result)
            if input_type == "unknown":
                # Fail-closed-clear: neither a PDF nor a vendor-HTML input.
                return json.dumps({
                    "success": False,
                    "error": (
                        f"semantik_conversion: unrecognized input {pdf} — "
                        "expected a .pdf file, a .html/.htm file, or a "
                        "directory containing PDFs or accessible HTML pages."
                    ),
                    "method": "unknown",
                    "output_path": str(pdf),
                    "html_path": str(pdf),
                })

            # PDF input → SemantiK cascade seam (the existing P3c path).
            out_stem = pdf.stem
            html_output = out_dir / f"{out_stem}_accessible.html"
            sem_result = await _to_thread(
                _run_semantik_v2_conversion,
                str(pdf),
                str(html_output),
                figures_dir=kwargs.get("figures_dir"),
                capture=kwargs.get("capture"),
                canonical_course_code=kwargs.get("canonical_course_code"),
                reuse_conversion=kwargs.get("reuse_conversion"),
            )
            if not sem_result.get("success"):
                # Fail-closed-clear: surface the SemantiK reason as the
                # conversion failure. No silent DART fallback.
                return json.dumps({
                    "success": False,
                    "error": sem_result.get(
                        "error", "SemantiK v2 conversion failed"
                    ),
                    "method": sem_result.get("method", "semantik_v2"),
                    "runtime_mode": sem_result.get("runtime_mode"),
                    "output_path": sem_result.get("output_path", str(html_output)),
                    "html_path": sem_result.get("html_path", str(html_output)),
                })
            return json.dumps(sem_result)

        # SemantiK migration: the legacy DART converter
        # (``_raw_text_to_accessible_html`` + ``multi_source_interpreter`` +
        # ``pdf_converter``) was retired with the DART subsystem. The only
        # phase that reaches this tool is ``semantik_conversion`` (handled above
        # via the SemantiK cascade / vendor-ingest seams; the legacy
        # ``dart_conversion`` tag is accepted there too). Any other phase is
        # an unsupported caller — fail CLOSED with a clear reason rather than
        # silently fall through to a deleted converter.
        return json.dumps({
            "success": False,
            "error": (
                "extract_and_convert_pdf is only reachable via the "
                "'semantik_conversion' phase (SemantiK cascade); the legacy "
                f"DART converter was retired. Got phase={kwargs.get('phase')!r}."
            ),
            "method": "unsupported_phase",
            "output_path": str(pdf),
            "html_path": str(pdf),
        })

    registry["extract_and_convert_pdf"] = _extract_and_convert_pdf

    # Pipeline tools - stage_semantik_outputs
    # Registry variant now has full Wave 8 parity with the @mcp.tool() variant
    # (role-tagging, .quality.json copy, role-tagged manifest entries). The
    # MCP-tool variant remains the source of truth for the copy/role logic;
    # this wrapper just adapts kwargs into the Wave 8 staging pipeline.
    async def _stage_semantik_outputs(**kwargs):
        """Stage SemantiK outputs to Courseforge inputs with Wave 8 role-tagging.

        Stages HTML (role=content), *_synthesized.json provenance sidecars
        (role=provenance_sidecar), and *.quality.json confidence sidecars
        (role=quality_sidecar) to ``COURSEFORGE_INPUTS/{run_id}/`` and
        emits a role-tagged ``staging_manifest.json``. Kept in parity with
        the @mcp.tool() variant so pipeline-dispatch runs do not silently
        drop Wave 8 metadata (audit Q4 finding).

        Wave 74 cleanup: honours ``stage_mode`` kwarg (or ``ED4ALL_STAGE_MODE``
        env) — defaults to ``symlink`` to skip 70MB/run of duplicated DART
        output. ``copy`` preserves legacy behaviour; ``hardlink`` is a Windows
        fallback when symlinks are blocked.
        """
        run_id = kwargs.get("run_id", "")
        dart_html_paths = kwargs.get("dart_html_paths", "")
        course_name = kwargs.get("course_name", "")
        stage_mode = kwargs.get("stage_mode")

        try:
            mode = _resolve_stage_mode(stage_mode)
            staging_dir = COURSEFORGE_INPUTS / run_id
            staging_dir.mkdir(parents=True, exist_ok=True)

            staged_files: list = []
            staged_entries: list = []
            errors: list = []

            html_paths = [Path(p.strip()) for p in dart_html_paths.split(",") if p.strip()]

            for html_path in html_paths:
                if not html_path.exists():
                    errors.append(f"DART output not found: {html_path}")
                    continue

                # Stage HTML file (role=content)
                dest = staging_dir / html_path.name
                _stage_file(html_path, dest, mode)
                staged_files.append(str(dest))
                staged_entries.append({"path": html_path.name, "role": "content"})

                # Wave 19: also stage ``{stem}_figures/`` when present.
                figures_dir_src = html_path.parent / f"{html_path.stem}_figures"
                if figures_dir_src.is_dir():
                    figures_dir_dest = staging_dir / figures_dir_src.name
                    _stage_tree(figures_dir_src, figures_dir_dest, mode)
                    staged_files.append(str(figures_dir_dest))
                    staged_entries.append({
                        "path": figures_dir_src.name,
                        "role": "figures_bundle",
                    })

                # Stage accompanying JSON if it exists (DART synthesized metadata).
                json_path = html_path.with_suffix(".json")
                if json_path.exists():
                    json_dest = staging_dir / json_path.name
                    _stage_file(json_path, json_dest, mode)
                    staged_files.append(str(json_dest))
                    staged_entries.append({
                        "path": json_path.name,
                        "role": "provenance_sidecar",
                    })

                # Also check for the _synthesized.json pattern.
                synth_json_name = html_path.stem.replace("_synthesized", "") + "_synthesized.json"
                synth_json_path = html_path.parent / synth_json_name
                if synth_json_path.exists() and str(synth_json_path) != str(json_path):
                    synth_json_dest = staging_dir / synth_json_name
                    _stage_file(synth_json_path, synth_json_dest, mode)
                    staged_files.append(str(synth_json_dest))
                    staged_entries.append({
                        "path": synth_json_name,
                        "role": "provenance_sidecar",
                    })

                # Wave 8: also stage the DART quality sidecar if one exists.
                quality_name = html_path.stem + ".quality.json"
                quality_path = html_path.parent / quality_name
                if quality_path.exists():
                    quality_dest = staging_dir / quality_name
                    _stage_file(quality_path, quality_dest, mode)
                    staged_files.append(str(quality_dest))
                    staged_entries.append({
                        "path": quality_name,
                        "role": "quality_sidecar",
                    })

            if errors and not staged_files:
                return json.dumps({
                    "success": False,
                    "error": "No files staged",
                    "errors": errors,
                })

            manifest = {
                "run_id": run_id,
                "course_name": course_name,
                "staged_at": datetime.now().isoformat(),
                "staged_files": staged_files,
                "files": staged_entries,
                "errors": errors if errors else None,
            }
            manifest_path = staging_dir / "staging_manifest.json"
            with open(manifest_path, "w") as f:
                json.dump(manifest, f, indent=2)

            return json.dumps({
                "success": True,
                "staging_dir": str(staging_dir),
                "staged_files": staged_files,
                "files": staged_entries,
                "file_count": len(staged_files),
                "manifest_path": str(manifest_path),
                "stage_mode": mode,
                "warnings": errors if errors else None,
            })
        except Exception as e:
            logger.error(f"Registry _stage_semantik_outputs failed: {e}")
            return json.dumps({"error": str(e)})

    registry["stage_semantik_outputs"] = _stage_semantik_outputs
    # Legacy pre-SemantiK registry-key alias (read-compat: paused runs /
    # resume states that dispatch the old key still route here).
    registry["stage_dart_outputs"] = _stage_semantik_outputs

    # Courseforge tools
    try:
        from MCP.tools.courseforge_tools import register_courseforge_tools as _cf  # noqa: F401
        # Import the tool functions from courseforge_tools module scope
        # These are registered as MCP tools but we need direct callables

        async def _create_course_project(**kwargs):
            logger.info(f"_create_course_project called with kwargs: {list(kwargs.keys())}")
            logger.info(f"  objectives_path raw: {repr(kwargs.get('objectives_path'))}")
            course_name = kwargs.get("course_name", "")
            objectives_path = kwargs.get("objectives_path") or ""
            duration_weeks = kwargs.get("duration_weeks", 12)
            credit_hours = kwargs.get("credit_hours", 3)

            # Use the project creation logic directly
            project_id = f"PROJ-{course_name}-{datetime.now().strftime('%Y%m%d%H%M%S')}"
            project_path = courseforge_exports_dir() / project_id

            project_path.mkdir(parents=True, exist_ok=True)
            for subdir in ["00_template_analysis", "01_learning_objectives",
                           "02_course_planning", "03_content_development",
                           "04_quality_validation", "05_final_package",
                           "agent_workspaces"]:
                (project_path / subdir).mkdir(exist_ok=True)

            config_path = project_path / "project_config.json"

            # If config already exists (from a prior phase), update rather than overwrite
            if config_path.exists():
                with open(config_path) as f:
                    config_data = json.load(f)
                # Only update fields that have real values
                if course_name:
                    config_data["course_name"] = course_name
                if objectives_path:
                    config_data["objectives_path"] = str(objectives_path)
                if duration_weeks:
                    config_data["duration_weeks"] = duration_weeks
            else:
                config_data = {
                    "project_id": project_id,
                    "course_name": course_name,
                    "objectives_path": str(objectives_path) if objectives_path else None,
                    "duration_weeks": duration_weeks,
                    "credit_hours": credit_hours,
                    "created_at": datetime.now().isoformat(),
                    "status": "initialized",
                }

            with open(config_path, "w") as f:
                json.dump(config_data, f, indent=2)

            # Generate default objective IDs from course name and weeks
            duration = duration_weeks if isinstance(duration_weeks, int) else 12
            objective_ids = [
                f"{course_name}_OBJ_{i}" for i in range(1, duration + 1)
            ]

            return json.dumps({
                "success": True,
                "project_id": project_id,
                "project_path": str(project_path),
                "objective_ids": ",".join(objective_ids),
                "config": config_data,
            })

        registry["create_course_project"] = _create_course_project

        # ============================================================================
        # Wave 24: _extract_textbook_structure — replaces the textbook-ingestor's
        # pre-Wave-24 stub dispatch (which routed to create_course_project and
        # produced an empty skeleton). Runs SemanticStructureExtractor.extract()
        # over every staged DART HTML file, merges per-file chapter/section
        # hierarchies into a single textbook_structure.json, and publishes the
        # path via phase_outputs.objective_extraction.textbook_structure_path.
        # ============================================================================
        async def _extract_textbook_structure(**kwargs):
            """Extract textbook structure from staged DART HTML.

            Called during the ``objective_extraction`` phase of
            ``textbook_to_course``. Reads every HTML file under
            ``staging_dir`` (the directory produced by the prior
            ``staging`` phase), runs the mature
            ``SemanticStructureExtractor`` over each, merges chapters
            across files into a single unified structure, and writes
            ``{project_path}/01_learning_objectives/textbook_structure.json``.

            Required kwargs: ``course_name`` (used to mint / locate the
            Courseforge export dir). Optional: ``staging_dir``,
            ``duration_weeks``, ``objectives_path`` (threaded through to
            project_config.json so downstream phases see them).
            """
            from lib.semantic_structure_extractor.semantic_structure_extractor import (
                SemanticStructureExtractor,
            )

            course_name = kwargs.get("course_name", "")
            if not course_name:
                return json.dumps({
                    "error": "extract_textbook_structure requires course_name",
                })
            duration_weeks = kwargs.get("duration_weeks", 12)
            duration_explicit = bool(kwargs.get("duration_weeks_explicit", True))
            objectives_path = kwargs.get("objectives_path") or ""
            staging_kwarg = kwargs.get("staging_dir")

            # Resolve or create the project path. We reuse the
            # create_course_project layout so downstream phases (which
            # accept project_id as an input) find the same structure.
            project_id = f"PROJ-{course_name}-{datetime.now().strftime('%Y%m%d%H%M%S')}"
            project_path = courseforge_exports_dir() / project_id
            project_path.mkdir(parents=True, exist_ok=True)
            for subdir in ("00_template_analysis", "01_learning_objectives",
                           "02_course_planning", "03_content_development",
                           "04_quality_validation", "05_final_package",
                           "agent_workspaces"):
                (project_path / subdir).mkdir(exist_ok=True)

            # Persist/refresh project_config.json so course_planning + later
            # phases (content_generation, trainforge_assessment) see a real
            # objectives_path once the planner emits synthesized_objectives.json.
            config_path = project_path / "project_config.json"
            config_data: Dict[str, Any] = {
                "project_id": project_id,
                "course_name": course_name,
                "duration_weeks": int(duration_weeks) if duration_weeks else 12,
                "credit_hours": kwargs.get("credit_hours", 3),
                "created_at": datetime.now().isoformat(),
                "status": "extracting_structure",
            }
            if objectives_path:
                config_data["objectives_path"] = str(objectives_path)
            config_path.write_text(
                json.dumps(config_data, indent=2), encoding="utf-8",
            )

            # Locate staged HTML. Prefer the explicit kwarg from the
            # workflow runner; fall back to the most-recent staging
            # manifest under Courseforge/inputs/textbooks when absent.
            staging_dir: Optional[Path] = None
            if staging_kwarg:
                staging_dir = Path(staging_kwarg)
            if staging_dir is None or not staging_dir.exists():
                # Fallback: the Courseforge inputs area.
                cf_inputs = _PROJECT_ROOT / "Courseforge" / "inputs" / "textbooks"
                if cf_inputs.exists():
                    # Use the most recent subdir as staging.
                    subdirs = sorted(
                        (p for p in cf_inputs.iterdir() if p.is_dir()),
                        key=lambda p: p.stat().st_mtime,
                        reverse=True,
                    )
                    if subdirs:
                        staging_dir = subdirs[0]

            html_files: List[Path] = []
            if staging_dir and staging_dir.exists():
                html_files = sorted(staging_dir.rglob("*.html"))

            # Run the extractor across every HTML file and merge.
            extractor = SemanticStructureExtractor()
            merged_chapters: List[Dict[str, Any]] = []
            per_file_results: List[Dict[str, Any]] = []
            extraction_errors: List[Dict[str, str]] = []
            for html_path in html_files:
                try:
                    content = html_path.read_text(encoding="utf-8", errors="ignore")
                    structure = extractor.extract(content, str(html_path), format="html")
                    per_file_results.append({
                        "source_file": str(html_path),
                        "chapters_count": len(structure.get("chapters", [])),
                    })
                    for ch in structure.get("chapters", []) or []:
                        if isinstance(ch, dict):
                            # Preserve source_file for downstream routing.
                            ch.setdefault("source_file", str(html_path))
                            merged_chapters.append(ch)
                except Exception as e:  # noqa: BLE001 - best-effort merge
                    extraction_errors.append({
                        "source_file": str(html_path),
                        "error": str(e),
                    })

            # De-duplicate chapter IDs across files: append a disambiguator
            # when two files emit the same synthesized ``chN`` id.
            seen_ids: set = set()
            for ch in merged_chapters:
                base_id = str(ch.get("id") or "").strip() or "ch"
                cand = base_id
                ctr = 1
                while cand in seen_ids:
                    ctr += 1
                    cand = f"{base_id}_{ctr}"
                ch["id"] = cand
                seen_ids.add(cand)

            # WS6b — collapse re-segmentation. When the structure collapsed
            # into a single mega-chapter (the DART heading-parser failure
            # mode: 1 chapter / >40 sections), recover coherent contiguous
            # pseudo-chapters via contiguity-constrained Ward over section
            # embeddings BEFORE textbook_structure.json is written. No-op /
            # graceful pass-through when not collapsed, flag off, or the
            # numeric stack / embeddings are unavailable. Stamp the recovery
            # onto structureDiagnostics for auditability.
            resegment_diagnostics: Optional[Dict[str, Any]] = None
            try:
                from lib.semantic_structure_extractor.resegment import (
                    resegment_collapsed_structure,
                )

                pre_resegment_chapter_count = len(merged_chapters)
                pre_resegment_section_count = sum(
                    len(c.get("sections") or [])
                    for c in merged_chapters
                    if isinstance(c, dict)
                )
                resegmented = resegment_collapsed_structure(merged_chapters)
                if (
                    resegmented is not merged_chapters
                    and len(resegmented) != pre_resegment_chapter_count
                ):
                    resegment_diagnostics = {
                        "resegmented": True,
                        "method": "contiguous_ward",
                        "k": len(resegmented),
                        "original_section_count": pre_resegment_section_count,
                    }
                    merged_chapters = resegmented
            except Exception as exc:  # noqa: BLE001 - never crash extraction
                logger.warning(
                    "objective_extraction: collapse re-segmentation raised "
                    "(%s); keeping the un-resegmented chapters.",
                    exc,
                )

            # Wave 24 HIGH-6: when --weeks wasn't explicit, scale to
            # max(8, chapter_count) using the actual chapter count we
            # just extracted. Updates project_config so the planner
            # + content generator + trainforge_assessment all see the
            # same autoscaled value.
            if not duration_explicit and merged_chapters:
                auto_weeks = max(8, len(merged_chapters))
                duration_weeks = auto_weeks
                config_data["duration_weeks"] = auto_weeks
                config_path.write_text(
                    json.dumps(config_data, indent=2), encoding="utf-8",
                )

            textbook_structure = {
                "course_name": course_name,
                "source_files": [str(p) for p in html_files],
                "staging_dir": str(staging_dir) if staging_dir else "",
                "chapter_count": len(merged_chapters),
                "duration_weeks": duration_weeks,
                "duration_weeks_autoscaled": bool(
                    not duration_explicit and merged_chapters
                ),
                "chapters": merged_chapters,
                "per_file_results": per_file_results,
                "extraction_errors": extraction_errors,
                "extracted_at": datetime.now().isoformat(),
            }

            # WS6b — stamp the re-segmentation recovery onto the WS4
            # structureDiagnostics block when it fired (auditable trail).
            if resegment_diagnostics is not None:
                existing_diag = textbook_structure.get("structureDiagnostics")
                if isinstance(existing_diag, dict):
                    existing_diag.update(resegment_diagnostics)
                else:
                    textbook_structure["structureDiagnostics"] = (
                        resegment_diagnostics
                    )

            # Three-stage textbook synthesis, Wave B / Stage 1 (plan
            # §3.2): when TEXTBOOK_SYNTHESIS_PROVIDER is set, run the
            # large-LLM outline pass and fold its three enrichment keys
            # into textbook_structure BEFORE the JSON write. Default-off
            # (env unset) → byte-identical textbook_structure.json, no
            # new keys. Fail-loud on TextbookSynthesisProviderError per
            # plan §2.2 (Stage 1 is a single call → no per-chapter
            # degradation).
            if os.environ.get("TEXTBOOK_SYNTHESIS_PROVIDER", "").strip():
                from Courseforge.generators._textbook_synthesis_provider import (
                    TextbookSynthesisProvider,
                )
                from lib.decision_capture import DecisionCapture

                synthesis_capture = None
                try:
                    synthesis_capture = DecisionCapture(
                        course_code=course_name,
                        phase="textbook-ingestor",
                        tool="courseforge",
                        streaming=True,
                    )
                except Exception as exc:  # noqa: BLE001 — capture is observability
                    logger.warning(
                        "DecisionCapture init failed in "
                        "objective_extraction Stage-1 synthesis: %s",
                        exc,
                    )

                provider = TextbookSynthesisProvider(capture=synthesis_capture)
                enrichment = provider.synthesize_outline(
                    textbook_structure, course_name=course_name
                )
                textbook_structure["semantic_outline"] = enrichment[
                    "semantic_outline"
                ]
                textbook_structure["draft_terminal_objectives"] = enrichment[
                    "draft_terminal_objectives"
                ]
                textbook_structure["structure_enrichment"] = enrichment[
                    "structure_enrichment"
                ]

            structure_path = (
                project_path / "01_learning_objectives" / "textbook_structure.json"
            )
            structure_path.write_text(
                json.dumps(textbook_structure, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )

            # C6 fix: silent-degradation closure. When `_extract_textbook_structure`
            # raises on N of M files (e.g. malformed HTML, encoding error,
            # SemanticStructureExtractor crash), the surviving (M-N) files
            # would still emit a graph that downstream gates (e.g.
            # ``min_edge_count``) could clear. The phase now fails closed
            # when ``extraction_errors`` is non-empty so an operator sees
            # the partial-extraction class before it propagates.
            extraction_errors_count = len(extraction_errors)
            phase_success = extraction_errors_count == 0
            envelope: Dict[str, Any] = {
                "success": phase_success,
                "project_id": project_id,
                "project_path": str(project_path),
                "textbook_structure_path": str(structure_path),
                "chapter_count": len(merged_chapters),
                "duration_weeks": duration_weeks,
                "duration_weeks_autoscaled": bool(
                    not duration_explicit and merged_chapters
                ),
                "source_file_count": len(html_files),
                "extraction_error_count": extraction_errors_count,
                "extraction_errors_count": extraction_errors_count,
            }
            if not phase_success:
                envelope["error"] = (
                    f"objective_extraction: {extraction_errors_count} of "
                    f"{len(html_files)} HTML files failed structure "
                    f"extraction; downstream phases would consume a "
                    f"partial graph. First {min(3, extraction_errors_count)} "
                    f"errors:"
                )
                envelope["extraction_error_summaries"] = [
                    {
                        "source_file": err.get("source_file", ""),
                        "error": err.get("error", ""),
                    }
                    for err in extraction_errors[:3]
                ]
            return json.dumps(envelope)

        registry["extract_textbook_structure"] = _extract_textbook_structure

        # ============================================================================
        # Wave 24: _plan_course_structure — synthesize TO-NN / CO-NN objectives
        # from the textbook structure (produced by _extract_textbook_structure)
        # and persist them as synthesized_objectives.json. This replaces the
        # pre-Wave-24 course_planning path which only called create_course_project
        # and emitted {COURSE}_OBJ_N placeholders — a scheme disjoint from the
        # TO-NN / CO-NN IDs actually emitted to HTML pages.
        # ============================================================================
        async def _plan_course_structure(**kwargs):
            """Plan course structure: synthesize real LOs + persist.

            Required kwargs: ``project_id`` or (``course_name`` +
            implicit location). When a textbook_structure.json exists in
            the project, chapters and sections drive the synthesizer;
            otherwise we fall back to whatever staged HTML we can find.

            Writes ``{project_path}/01_learning_objectives/synthesized_objectives.json``
            with a canonical shape, populates
            ``project_config.json::objectives_path`` so downstream
            phases pick it up automatically, and returns the real TO/CO
            IDs in ``objective_ids``.
            """
            from MCP.tools import _content_gen_helpers as _cgh

            project_id = kwargs.get("project_id") or ""
            course_name = kwargs.get("course_name") or ""

            # Resolve project path. Prefer explicit project_id; otherwise
            # the most recent export matching course_name.
            project_path: Optional[Path] = None
            if project_id:
                cand = courseforge_exports_dir() / project_id
                if cand.exists():
                    project_path = cand
            if project_path is None and course_name:
                exports_dir = courseforge_exports_dir()
                if exports_dir.exists():
                    matches = sorted(
                        (p for p in exports_dir.iterdir()
                         if p.is_dir() and course_name.lower() in p.name.lower()),
                        key=lambda p: p.stat().st_mtime,
                        reverse=True,
                    )
                    if matches:
                        project_path = matches[0]
            if project_path is None:
                return json.dumps({
                    "error": "plan_course_structure could not locate project directory",
                    "project_id": project_id,
                    "course_name": course_name,
                })
            if not project_id:
                project_id = project_path.name

            # Load project config.
            config_path = project_path / "project_config.json"
            config_data: Dict[str, Any] = {}
            if config_path.exists():
                try:
                    config_data = json.loads(config_path.read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    config_data = {}
            # Wave 40: honor the auto-scaled duration_weeks persisted by
            # _extract_textbook_structure. When the CLI didn't receive an
            # explicit --weeks, the extractor already computed max(8, N) and
            # wrote it to config; the stale kwargs value (default 12) must
            # NOT shadow it. duration_weeks_explicit=False => config wins.
            duration_explicit = bool(kwargs.get("duration_weeks_explicit", True))
            if not duration_explicit and config_data.get("duration_weeks"):
                duration_weeks = int(config_data["duration_weeks"])
            else:
                duration_weeks = int(
                    kwargs.get("duration_weeks") or config_data.get("duration_weeks") or 12
                )
            course_name = course_name or config_data.get("course_name") or project_id

            # Prefer real topics from staged HTML when available.
            staging_kwarg = kwargs.get("staging_dir") or config_data.get("staging_dir")
            staging_dir = Path(staging_kwarg) if staging_kwarg else None
            html_files = _cgh.collect_staged_html(staging_dir, COURSEFORGE_INPUTS)
            topics = _cgh.parse_dart_html_files(html_files) if html_files else []

            # Provenance-aware objectives reuse (self-poisoning guard).
            #
            # Only an OPERATOR-supplied objectives pin may short-circuit
            # synthesis. The pipeline stamps
            # ``project_config.json::objectives_path`` with THIS phase's own
            # prior output (``synthesized_objectives.json``) after every
            # synthesis; treating that self-stamp as a reuse pin on a
            # re-run silently re-normalizes a possibly-degenerate prior
            # synthesis instead of re-synthesizing. We therefore:
            #   1. Honor ``kwargs["objectives_path"]`` verbatim — the
            #      operator ``--objectives`` task param.
            #   2. Honor a config-stamped pin ONLY when its provenance is
            #      operator-supplied: ``objectives_source == "operator"``,
            #      or (legacy config predating the provenance field) the
            #      pinned file's ``mint_method`` records an operator origin.
            # The documented ``--reuse-objectives`` contract is unaffected:
            # the runner short-circuits course_planning before this closure
            # ever runs (see
            # WorkflowRunner._synthesize_course_planning_reuse_output).
            _OPERATOR_OBJECTIVE_MINTS = frozenset(
                {"user_supplied_objectives_json", "reuse_objectives"}
            )

            def _config_pin_is_operator_supplied(_pin_path: Any) -> bool:
                _source = str(
                    config_data.get("objectives_source") or ""
                ).strip()
                if _source == "operator":
                    return True
                if _source == "pipeline":
                    return False
                # Legacy config (no provenance field): inspect the pinned
                # file's mint_method. Reuse ONLY when it records an
                # operator origin; a synthesis mint is this phase's own
                # prior output → re-synthesize.
                try:
                    _pin = Path(str(_pin_path))
                    if not _pin.is_file():
                        return False
                    _pin_doc = json.loads(_pin.read_text(encoding="utf-8"))
                except (OSError, ValueError, TypeError):
                    return False
                if not isinstance(_pin_doc, dict):
                    return False
                _mint = str(_pin_doc.get("mint_method") or "").strip()
                return _mint in _OPERATOR_OBJECTIVE_MINTS

            supplied_objectives = kwargs.get("objectives_path")
            if not supplied_objectives:
                _config_pin = config_data.get("objectives_path")
                if _config_pin and _config_pin_is_operator_supplied(
                    _config_pin
                ):
                    supplied_objectives = _config_pin
            supplied_terminal, supplied_chapter = (
                _cgh.load_objectives_json(supplied_objectives)
            )

            # R7 §5.4 — per-chapter Stage-2 failure isolation list.
            # Declared at function scope so it is always defined when
            # the ``synthesized`` dict is assembled below, and is a
            # truthful ``[]`` on the deterministic / user-supplied /
            # COURSEPLANNER paths where Stage-2 never runs (no stale
            # value leaks into synthesized_objectives.json).
            chapter_synthesis_failures: List[str] = []

            # Stage-2 grounding/citation-reselect counters. Declared at
            # function scope so the tool return always carries them (an empty
            # {} on the user-supplied / deterministic / COURSEPLANNER paths
            # where Stage-2 window synthesis never runs — no invented values).
            # Populated below only on the chunk_window / chapter_fallback path.
            _grounding_signals: Dict[str, Any] = {}

            if supplied_terminal or supplied_chapter:
                terminal = list(supplied_terminal)
                chapter = list(supplied_chapter)
                mint_method = "user_supplied_objectives_json"
            else:
                # W-D14: COURSEPLANNER_PROVIDER short-circuits the
                # deterministic ``synthesize_objectives_from_topics`` path
                # when the operator opts into the in-process LLM seam for
                # the course-outliner agent. Mirrors the W-D11.A
                # COURSEFORGE_PROVIDER pattern at ``_generate_course_content``.
                # Default unset => deterministic synthesizer fires
                # byte-stable for every existing run.
                _courseplanner_provider_env = os.environ.get(
                    "COURSEPLANNER_PROVIDER", ""
                ).strip()
                terminal: List[Dict[str, Any]] = []
                chapter: List[Dict[str, Any]] = []
                mint_method = ""

                # ================================================== #
                # Stage 2 — three-stage textbook synthesis (plan §5  #
                # + §6). Gated on TEXTBOOK_SYNTHESIS_PROVIDER. Runs   #
                # ABOVE the COURSEPLANNER_PROVIDER branch: when set,  #
                # it dispatches N per-chapter ``synthesize_chapter_   #
                # objectives`` calls (batched ≤10), mints globally-   #
                # sequential CO-NN ids over the FLATTENED course-     #
                # ordered list, then ONE ``reconcile_terminal_        #
                # objectives`` call to adjust the Stage-1 draft TO-NN.#
                # Default unset → deterministic path runs byte-stable.#
                # ================================================== #
                _textbook_synthesis_env = os.environ.get(
                    "TEXTBOOK_SYNTHESIS_PROVIDER", ""
                ).strip()
                if _textbook_synthesis_env:
                    import asyncio as _asyncio
                    from lib.ontology.learning_objectives import (
                        mint_lo_id as _mint_lo_id,
                    )

                    # Read textbook_structure.json off disk for the
                    # Stage-1 draft TO-NN + per-chapter chapter_text
                    # (Wave B folded both into the artifact).
                    _ts_path_local = (
                        project_path
                        / "01_learning_objectives"
                        / "textbook_structure.json"
                    )
                    _ts_structure: Dict[str, Any] = {}
                    if _ts_path_local.exists():
                        try:
                            _ts_structure = json.loads(
                                _ts_path_local.read_text(encoding="utf-8")
                            )
                        except (OSError, ValueError) as exc:
                            logger.warning(
                                "plan_course_structure: Stage-2 "
                                "textbook_structure read failed (%s); "
                                "falling back to deterministic path.",
                                exc,
                            )
                            _ts_structure = {}
                    _ts_chapters: List[Dict[str, Any]] = []
                    if isinstance(_ts_structure, dict):
                        _raw_ch = _ts_structure.get("chapters")
                        if isinstance(_raw_ch, list):
                            _ts_chapters = [
                                c for c in _raw_ch if isinstance(c, dict)
                            ]
                    _draft_tos: List[Dict[str, Any]] = []
                    if isinstance(_ts_structure, dict):
                        _raw_draft = _ts_structure.get(
                            "draft_terminal_objectives"
                        )
                        if isinstance(_raw_draft, list):
                            _draft_tos = [
                                d for d in _raw_draft if isinstance(d, dict)
                            ]

                    if not _ts_chapters:
                        # No chapter surface → Stage 2 cannot run;
                        # fall through to COURSEPLANNER/deterministic.
                        logger.warning(
                            "plan_course_structure: Stage-2 requested "
                            "(TEXTBOOK_SYNTHESIS_PROVIDER=%s) but "
                            "textbook_structure.json carries no "
                            "chapters[]; falling back.",
                            _textbook_synthesis_env,
                        )
                    else:
                        # R7: append into the function-scope
                        # ``chapter_synthesis_failures`` declared above
                        # (no local re-declaration — the list must be
                        # visible at the ``synthesized`` dict assembly).
                        chapters_synthesized = 0
                        _stage2_provider = None
                        try:
                            from Courseforge.generators._textbook_synthesis_provider import (  # noqa: E501
                                TextbookSynthesisProvider,
                                TextbookSynthesisProviderError,
                            )
                            _stage2_capture = None
                            try:
                                from lib.decision_capture import (
                                    DecisionCapture,
                                )
                                _stage2_capture = DecisionCapture(
                                    course_code=course_name,
                                    phase="course-outliner",
                                    tool="courseforge",
                                    streaming=True,
                                )
                            except Exception as exc:  # noqa: BLE001
                                logger.warning(
                                    "DecisionCapture init failed for "
                                    "Stage-2 course-outliner: %s", exc,
                                )
                            _stage2_provider = TextbookSynthesisProvider(
                                capture=_stage2_capture,
                                # Structure-aware synthesis
                                # (ED4ALL_SYNTHESIS_SKELETON): thread the parsed
                                # textbook_structure so each window's chapter
                                # heading skeleton is available to
                                # synthesize_window_objectives. No-op when the
                                # flag is off (empty skeleton, byte-identical
                                # prompt).
                                textbook_structure=_ts_structure,
                            )
                        except Exception as exc:  # noqa: BLE001
                            logger.warning(
                                "plan_course_structure: Stage-2 provider "
                                "construction failed (%s); falling back "
                                "to deterministic path.", exc,
                            )
                            _stage2_provider = None

                        if _stage2_provider is not None:
                            # W2 §1.6 — load the DART chunkset to decide the
                            # grounding mode. Present → per-WINDOW dispatch
                            # (Pass B) + Pass C (NLI filter) + Pass D (dedup);
                            # missing → fall back to per-CHAPTER dispatch
                            # (chapter_fallback) so grounding degrades
                            # gracefully (empty source_chunk_ids, Pass C
                            # pass-through-flags them).
                            _chunks_by_id, _all_chunks = (
                                _load_semantik_chunkset_for_planning(
                                    course_slug=course_name,
                                    kwargs=kwargs,
                                )
                            )
                            _grounding_mode = (
                                "chunk_window"
                                if _all_chunks
                                else "chapter_fallback"
                            )
                            logger.info(
                                "TEXTBOOK_SYNTHESIS_PROVIDER=%s; routing "
                                "course_planning Stage-2 through the "
                                "%s synthesis path (%d chapters, "
                                "%d DART chunks).",
                                _textbook_synthesis_env,
                                _grounding_mode,
                                len(_ts_chapters),
                                len(_all_chunks),
                            )

                            (
                                chapter,
                                terminal,
                                mint_method,
                                _grounding_signals,
                            ) = await _run_stage2_window_synthesis(
                                provider=_stage2_provider,
                                provider_error=(
                                    TextbookSynthesisProviderError
                                ),
                                chapters=_ts_chapters,
                                draft_tos=_draft_tos,
                                chunks_by_id=_chunks_by_id,
                                all_chunks=_all_chunks,
                                grounding_mode=_grounding_mode,
                                course_name=course_name,
                                provider_env=_textbook_synthesis_env,
                                chapter_synthesis_failures=(
                                    chapter_synthesis_failures
                                ),
                                mint_lo_id=_mint_lo_id,
                                kwargs=kwargs,
                                capture=_stage2_capture,
                                # Per-window resume sidecar in the phase OUTPUT
                                # dir (reused verbatim on --resume). Default ON;
                                # ED4ALL_OBJECTIVE_SYNTHESIS_CHECKPOINT=0 opts
                                # out. Only the chunk_window path writes/reads.
                                checkpoint_path=(
                                    project_path
                                    / "01_learning_objectives"
                                    / _STAGE2_WINDOWS_CHECKPOINT_NAME
                                ),
                            )

                            # W2 §4.4 — emit the objective_grounding_filter
                            # decision interpolating the dynamic counts
                            # (decision-capture contract; the per-window
                            # chapter_objective_call events still fired).
                            if _stage2_capture is not None and _grounding_signals:
                                try:
                                    _gs = _grounding_signals
                                    _stage2_capture.log_decision(
                                        decision_type=(
                                            "objective_grounding_filter"
                                        ),
                                        decision=(
                                            f"objective_grounding_filter:"
                                            f"{course_name}:"
                                            f"{_gs.get('grounded_count', 0)}/"
                                            f"{_gs.get('candidate_count', 0)}"
                                            f" grounded"
                                        ),
                                        rationale=(
                                            f"course={course_name}; "
                                            f"grounding_mode="
                                            f"{_gs.get('grounding_mode')}; "
                                            f"candidate_count="
                                            f"{_gs.get('candidate_count', 0)}; "
                                            f"grounded_count="
                                            f"{_gs.get('grounded_count', 0)}; "
                                            f"ungrounded_dropped="
                                            f"{_gs.get('ungrounded_dropped', 0)}; "
                                            f"reground_count="
                                            f"{_gs.get('reground_count', 0)}; "
                                            f"nli_available="
                                            f"{_gs.get('nli_available')}; "
                                            f"dedup_clusters="
                                            f"{_gs.get('dedup_clusters', 0)}; "
                                            f"max_pairwise_cosine="
                                            f"{_gs.get('max_pairwise_cosine', 0)}; "
                                            f"near_dup_pairs="
                                            f"{_gs.get('near_dup_pairs', 0)}; "
                                            f"embed_available="
                                            f"{_gs.get('embed_available')}; "
                                            f"weak_to_link_rate="
                                            f"{_gs.get('weak_to_link_rate', 0)}; "
                                            f"to_derivation="
                                            f"{_gs.get('to_derivation', 'legacy_reconcile')}; "
                                            f"cluster_count="
                                            f"{_gs.get('cluster_count', 0)}; "
                                            f"mean_intra_cluster_cosine="
                                            f"{_gs.get('mean_intra_cluster_cosine', 0)}"
                                        ),
                                        ml_features={
                                            k: v
                                            for k, v in _gs.items()
                                            if isinstance(
                                                v, (int, float, bool, str)
                                            )
                                        },
                                    )
                                except Exception:  # noqa: BLE001
                                    pass

                if (terminal or chapter):
                    pass
                elif _courseplanner_provider_env:
                    try:
                        from Courseforge.generators._outliner_provider import (
                            OutlinerProvider,
                            OutlinerProviderError,
                        )
                        # Build a textbook_structure dict from disk when
                        # the extractor has emitted one; fall back to an
                        # empty stub so the provider's prompt block
                        # surfaces "(none)" without raising. ``structure_path``
                        # below in this function is recomputed; we reference
                        # the same canonical location here so both paths see
                        # the same on-disk artifact.
                        _structure_path_local = (
                            project_path
                            / "01_learning_objectives"
                            / "textbook_structure.json"
                        )
                        outliner_structure: Dict[str, Any] = {}
                        if _structure_path_local.exists():
                            try:
                                outliner_structure = json.loads(
                                    _structure_path_local.read_text(
                                        encoding="utf-8"
                                    )
                                )
                            except (OSError, ValueError) as exc:
                                logger.warning(
                                    "plan_course_structure: "
                                    "textbook_structure read failed (%s); "
                                    "calling OutlinerProvider with empty "
                                    "chapters[]", exc,
                                )
                        outliner_capture = None
                        try:
                            from lib.decision_capture import DecisionCapture
                            outliner_capture = DecisionCapture(
                                course_code=course_name,
                                phase="course-outliner",
                                tool="courseforge",
                                streaming=True,
                            )
                        except Exception as exc:  # noqa: BLE001
                            logger.warning(
                                "DecisionCapture init failed for "
                                "course-outliner: %s", exc,
                            )
                            outliner_capture = None
                        outliner_provider = OutlinerProvider(
                            capture=outliner_capture,
                        )
                        logger.info(
                            "COURSEPLANNER_PROVIDER=%s; routing "
                            "course-outliner through in-process provider.",
                            _courseplanner_provider_env,
                        )
                        synthesised = outliner_provider.synthesize_objectives(
                            outliner_structure,
                            course_name=course_name,
                            chapter_count=len(
                                outliner_structure.get("chapters") or []
                            ),
                            weeks=duration_weeks,
                        )
                        terminal = list(
                            synthesised.get("terminal_objectives") or []
                        )
                        # Provider returns chapter_objectives in the
                        # group-of-groups shape; flatten so this
                        # function's downstream assembly stays consistent
                        # with both the user-supplied and deterministic
                        # paths (which deliver flat dicts).
                        chapter_groups = (
                            synthesised.get("chapter_objectives") or []
                        )
                        for grp in chapter_groups:
                            if not isinstance(grp, dict):
                                continue
                            for entry in grp.get("objectives") or []:
                                if isinstance(entry, dict):
                                    chapter.append(entry)
                        mint_method = synthesised.get(
                            "mint_method"
                        ) or f"courseplanner_provider:{_courseplanner_provider_env}"
                    except OutlinerProviderError as exc:
                        # LLM tier exhausted parse — fail loud rather
                        # than silently falling back so the operator's
                        # opt-in intent is honored or surfaced clearly.
                        logger.exception(
                            "OutlinerProvider exhausted (provider=%s): %s",
                            _courseplanner_provider_env, exc,
                        )
                        raise
                    except Exception as exc:
                        logger.exception(
                            "OutlinerProvider init/dispatch failed "
                            "(provider=%s): %s",
                            _courseplanner_provider_env, exc,
                        )
                        raise
                if not terminal and not chapter:
                    terminal, chapter = _cgh.synthesize_objectives_from_topics(
                        topics, duration_weeks,
                    )
                    mint_method = mint_method or (
                        "synthesize_objectives_from_topics"
                    )

            # WS5 §3.2 — TO-based dynamic week count (supersedes the Wave 1.8
            # CO-count formula). After WS1's clustering, ``terminal`` is the
            # genuine ~8-12 terminal-objective / theme count — the
            # authoritative pacing signal: one week-block per TO. The COs then
            # distribute WITHIN each TO's block via the §2.2 coverage-safe
            # ceil-stride slicer, so NO grounded CO is dropped regardless of
            # week count (the naive bare ``duration_weeks`` reduction was
            # REFUTED precisely because it dropped COs; §2.2 makes the cut
            # safe).
            #
            # ``WAVE18_COS_PER_WEEK`` is REPURPOSED to a within-theme CO
            # distribution knob (legacy fallback divisor) — it is NO LONGER the
            # primary week divisor when WS1 supplies real TOs.
            #
            # Override guards preserved VERBATIM:
            #   ``not duration_explicit`` — when ``--weeks N`` is passed the
            #     operator's pacing wins, no rescale.
            #   ``mint_method != "user_supplied_objectives_json"`` — a
            #     hand-curated ``--reuse-objectives`` LO list pre-encodes
            #     pacing that automatic re-scaling would clobber.
            objective_weeks = _ws5_resolve_objective_weeks(
                num_tos=len(terminal),
                num_cos=len(chapter),
                duration_weeks=duration_weeks,
                duration_explicit=duration_explicit,
                mint_method=mint_method,
            )
            if objective_weeks != duration_weeks:
                logger.info(
                    "WS5 re-scale duration_weeks %d -> %d "
                    "(num_tos=%d, chapter_cos=%d)",
                    duration_weeks,
                    objective_weeks,
                    len(terminal),
                    len(chapter),
                )
                duration_weeks = objective_weeks

            # Detect textbook_structure_path to record provenance.
            structure_path = (
                project_path / "01_learning_objectives" / "textbook_structure.json"
            )
            generated_from = str(structure_path) if structure_path.exists() else ""

            # Canonical on-disk shape.
            #
            # Phase 6 ST 7: pass through the optional ``abcd`` sub-object
            # when the source LO carries one. Both the synthesizer
            # (``_cgh.synthesize_objectives_from_topics`` after Phase 6
            # ST 8 — emits ABCD for every LO with a Bloom level) and a
            # user-supplied ``--reuse-objectives`` payload (preserved by
            # ``_cgh._normalize_objective_entry`` after the Phase 6 ST 7
            # widening) attach ``abcd`` per LO. The ABCD dict is
            # deep-copied so downstream mutation of ``lo_entries`` doesn't
            # leak back into the in-memory terminal/chapter lists that
            # the ``terminal_objectives`` / ``chapter_objectives`` blocks
            # below also serialize. Cross-link: ``$defs.AbcdObjective``
            # in ``schemas/knowledge/courseforge_jsonld_v1.schema.json``;
            # validated downstream by ``AbcdObjectiveValidator``
            # (Phase 6 ST 4) wired as the ``abcd_verb_alignment`` gate
            # on the ``course_planning`` phase (Phase 6 ST 4.5).
            def _clone_lo(src: Dict[str, Any], hierarchy: str) -> Dict[str, Any]:
                cloned = dict(src)
                abcd_payload = src.get("abcd")
                if isinstance(abcd_payload, dict):
                    # Deep-copy the ABCD sub-object so the per-LO entry
                    # in ``lo_entries`` is independent of the
                    # ``terminal_objectives`` / ``chapter_objectives``
                    # serialised view below. Behavior is a nested dict,
                    # so a one-level deep copy is sufficient.
                    behavior = abcd_payload.get("behavior")
                    cloned_abcd: Dict[str, Any] = dict(abcd_payload)
                    if isinstance(behavior, dict):
                        cloned_abcd["behavior"] = dict(behavior)
                    cloned["abcd"] = cloned_abcd
                cloned["hierarchy_level"] = hierarchy
                return cloned

            lo_entries: List[Dict[str, Any]] = []
            for to in terminal:
                lo_entries.append(_clone_lo(to, "terminal"))
            for co in chapter:
                lo_entries.append(_clone_lo(co, "chapter"))

            # Phase-ordering fix (Option A1): the concept-objective linker
            # pass (lib/ontology/concept_objective_linker.py) that
            # populated ``LearningObjective.keyConcepts[]`` from the
            # concept graph USED to run here, gated on a
            # ``concept_graph_path`` kwarg. It has been relocated into
            # ``_run_concept_extraction`` because that phase now runs AFTER
            # course_planning — the concept graph does not exist yet at
            # planning time, so a linker pass here would always no-op on a
            # fresh run. A ``concept_graph_path`` kwarg passed to this
            # function is now inert (preserved for back-compat callers).

            # Layer A — terminal-coverage guarantee. Prune any terminal
            # objective with ZERO chapter objectives rolling up to it
            # (CO-bearing courses only). An orphan terminal is one that
            # downstream content generation cannot cover, so it trips the
            # critical UNCOVERED_TERMINAL_OUTCOME archival gate
            # (lib/validators/libv2/packet_integrity.py). Pruning by
            # construction here makes the objectives set internally
            # consistent before it is ever written to disk; the
            # course_planning ``terminal_objective_coverage`` gate is the
            # fail-fast backstop. CO-less courses (vendor-HTML / chunk-only imports)
            # are returned untouched — their terminals are self-contained
            # teaching units whose coverage is content-driven, so they are
            # adjudicated by the gate (with the textbook structure), never
            # silently pruned here. Cross-link:
            # lib/ontology/terminal_coverage.py::prune_orphan_terminals.
            try:
                from lib.ontology.terminal_coverage import (
                    flatten_chapter_objectives as _flatten_cos,
                    prune_orphan_terminals as _prune_orphan_terminals,
                )

                _chapter_groups_for_prune = [
                    {"chapter": f"Week {idx}", "objectives": [dict(c)]}
                    for idx, c in enumerate(chapter, start=1)
                ]
                _kept_terminals, _pruned_terminal_ids = (
                    _prune_orphan_terminals(
                        terminal, _chapter_groups_for_prune,
                    )
                )
                if _pruned_terminal_ids:
                    logger.warning(
                        "Layer A: pruning %d orphan terminal(s) with no "
                        "rolling-up chapter objective from %s: %s",
                        len(_pruned_terminal_ids),
                        course_name,
                        ", ".join(_pruned_terminal_ids),
                    )
                    _pruned_set = {str(t) for t in _pruned_terminal_ids}
                    terminal = [
                        t for t in terminal
                        if str((t or {}).get("id")) not in _pruned_set
                    ]
                    # Keep lo_entries consistent with the pruned terminal
                    # set so the on-disk learning_outcomes array does not
                    # re-introduce the orphan IDs.
                    lo_entries = [
                        e for e in lo_entries
                        if not (
                            (e.get("hierarchy_level") == "terminal")
                            and str(e.get("id")) in _pruned_set
                        )
                    ]
            except Exception as exc:  # noqa: BLE001 — best-effort guarantee
                logger.warning(
                    "Layer A: terminal-coverage prune failed (%s); "
                    "proceeding without prune (the course_planning "
                    "terminal_objective_coverage gate remains the "
                    "fail-fast backstop).",
                    exc,
                )

            # Layer A (CO-less branch) — stamp a resolvable ``chapter``
            # back-pointer on every terminal of a CO-less course (empty
            # chapter_objectives). The deterministic synthesizer mints
            # terminals with no chapter back-pointer (the topic-side parser
            # frequently sees chapter_id=None even though the structure-side
            # extractor synthesized real ch1/ch2/... chapters), which leaves
            # the objectives set internally inconsistent: the CO-less
            # ``terminal_objective_coverage`` gate then critical-fails with
            # ORPHAN_TERMINAL_NO_CHAPTER_REF. Anchoring each terminal to a
            # real structure chapter here (round-robin, document order) makes
            # the set consistent BEFORE it is written — the same Layer-A
            # guarantee the prune provides for CO-bearing courses. No-op for
            # CO-bearing courses and for runs with no resolvable structure
            # chapters (the gate's TERMINAL_COVERAGE_UNVERIFIED path owns
            # that). Cross-link:
            # lib/ontology/terminal_coverage.py::attach_terminal_chapter_refs.
            try:
                from lib.ontology.terminal_coverage import (
                    attach_terminal_chapter_refs as _attach_terminal_chapter_refs,
                )

                _ts_for_attach: Dict[str, Any] = {}
                if structure_path.exists():
                    try:
                        _ts_for_attach = json.loads(
                            structure_path.read_text(encoding="utf-8")
                        )
                    except (OSError, ValueError) as exc:
                        logger.warning(
                            "Layer A (CO-less): textbook_structure read "
                            "failed (%s); skipping chapter back-pointer "
                            "attach.", exc,
                        )
                        _ts_for_attach = {}
                _chapter_groups_for_attach = [
                    {"chapter": f"Week {idx}", "objectives": [dict(c)]}
                    for idx, c in enumerate(chapter, start=1)
                ]
                _attached_terminals, _attached_ids = (
                    _attach_terminal_chapter_refs(
                        terminal,
                        _chapter_groups_for_attach,
                        textbook_structure=_ts_for_attach,
                    )
                )
                if _attached_ids:
                    logger.info(
                        "Layer A (CO-less): attached chapter back-pointer "
                        "to %d terminal(s) of %s: %s",
                        len(_attached_ids), course_name,
                        ", ".join(_attached_ids),
                    )
                    terminal = _attached_terminals
                    # Re-sync the terminal entries in lo_entries with the
                    # freshly-stamped ``chapter`` so the on-disk
                    # learning_outcomes array carries the back-pointer too.
                    _by_id = {str(t.get("id")): t for t in terminal}
                    for _e in lo_entries:
                        if _e.get("hierarchy_level") != "terminal":
                            continue
                        _src = _by_id.get(str(_e.get("id")))
                        if _src is not None and "chapter" in _src:
                            _e["chapter"] = _src["chapter"]
            except Exception as exc:  # noqa: BLE001 — best-effort guarantee
                logger.warning(
                    "Layer A (CO-less): terminal chapter back-pointer "
                    "attach failed (%s); proceeding (the course_planning "
                    "terminal_objective_coverage gate remains the "
                    "fail-fast backstop).",
                    exc,
                )

            # Grounding-safe objective-review pass (default OFF via
            # ``ED4ALL_OBJECTIVE_REVIEW_PROVIDER``). After the 7B synthesizes
            # objectives, a strong hosted model (NVIDIA Nemotron) REVIEWS and
            # ADJUSTS the synthesized objectives' QUALITY in place — improving
            # statement clarity, repairing bloom level/verb, completing abcd,
            # and making TO statements cover their child COs — with hard
            # guardrails: identity + the id SET are immutable (no add/remove/
            # reorder/re-id), ``source_refs`` are preserved VERBATIM (only
            # editable text fields merge back by id), and every CO statement
            # edit that degrades CO->TO grounding below the
            # ``co_terminal_alignment`` cosine floor is REVERTED. Fully
            # graceful: an unset key / provider error / unparseable response
            # logs a warning and keeps the original 7B objectives unchanged
            # (never fails the phase). Default-off (env unset) is a strict
            # no-op — no client constructed, objectives byte-identical.
            try:
                from lib.objectives.objective_review import (  # noqa: PLC0415
                    review_objectives as _review_objectives,
                )

                _review_capture = None
                try:
                    from lib.decision_capture import (  # noqa: PLC0415
                        DecisionCapture as _ReviewDecisionCapture,
                    )

                    _review_capture = _ReviewDecisionCapture(
                        course_code=course_name,
                        phase="course-outliner",
                        tool="courseforge",
                        streaming=True,
                    )
                except Exception as _rc_exc:  # noqa: BLE001
                    logger.warning(
                        "DecisionCapture init failed for objective-review "
                        "pass: %s", _rc_exc,
                    )

                # Wrap the flat ``chapter`` CO list in the review's group
                # shape so the merge can read each CO's parent-terminal +
                # mutate it IN PLACE (the same dicts flow into the WS5
                # week-group slicer below + the on-disk learning_outcomes).
                _review_co_group = [
                    {"chapter": "all", "objectives": chapter}
                ] if chapter else []
                _review_result = _review_objectives(
                    terminals=terminal,
                    chapter_objectives=_review_co_group,
                    course_name=course_name,
                    capture=_review_capture,
                )
                # FAIL-CLOSED: the 70B quality review MUST fully complete
                # before any downstream phase consumes the objectives. When the
                # review is ENABLED but one or more review chunks did not
                # complete (timeout / parse / provider error after the
                # per-chunk retries), the objectives are only PARTIALLY
                # reviewed — refuse to proceed rather than ship a course built
                # on un-reviewed objectives. (``applied`` is True even on a
                # PARTIAL review — ``applied = chunks_failed < chunks_attempted``
                # — so it is NOT a completeness signal; ``chunks_failed`` is.)
                _rv_failed = int(_review_result.get("chunks_failed", 0) or 0)
                if _review_result.get("enabled") and _rv_failed:
                    raise RuntimeError(
                        "objective-review incomplete: "
                        f"{_rv_failed}/"
                        f"{_review_result.get('chunks_attempted')} review "
                        f"chunks failed (provider="
                        f"{_review_result.get('provider')}, model="
                        f"{_review_result.get('model')}, note="
                        f"{_review_result.get('note')}). The quality review "
                        "must complete before downstream phases consume the "
                        "objectives — failing course_planning instead of "
                        "proceeding with un-reviewed objectives."
                    )
                if _review_result.get("applied"):
                    _rc = _review_result.get("counters", {})
                    logger.info(
                        "objective-review pass applied (provider=%s, "
                        "model=%s): %d statements adjusted, %d reverted for "
                        "grounding, %d bloom edits applied, %d rejected.",
                        _review_result.get("provider"),
                        _review_result.get("model"),
                        _rc.get("statements_adjusted", 0),
                        _rc.get("statements_reverted", 0),
                        _rc.get("bloom_edits_applied", 0),
                        _rc.get("bloom_edits_rejected", 0),
                    )
                    # Re-sync reviewed statement/bloom/abcd edits back into
                    # lo_entries (built by CLONING terminal+chapter BEFORE
                    # this hook) so the on-disk learning_outcomes array
                    # reflects the review. The review mutated terminal +
                    # chapter dicts IN PLACE; only the editable text fields
                    # are copied here (source_refs are NEVER touched, and the
                    # id set is unchanged so every lo_entry still resolves).
                    _reviewed_by_id = {
                        str(o.get("id")): o
                        for o in list(terminal) + list(chapter)
                        if isinstance(o, dict) and o.get("id")
                    }
                    for _e in lo_entries:
                        _src = _reviewed_by_id.get(str(_e.get("id")))
                        if _src is None:
                            continue
                        for _fld in (
                            "statement",
                            "bloom_level",
                            "bloom_verb",
                            "abcd",
                        ):
                            if _fld in _src:
                                _e[_fld] = _src[_fld]
            except GracefulStopRequested:
                # A graceful stop that escapes the review pass is a PAUSE, not a
                # failure — propagate it out AS-IS so the runner stamps the phase
                # ``paused`` (never convert it to the fail-closed RuntimeError
                # below). This carve-out MUST precede the broad handler.
                raise
            except Exception as _review_exc:  # noqa: BLE001
                # FAIL-CLOSED when the review is CONFIGURED: a configured
                # quality review that raises (including the deliberate
                # incomplete-review RuntimeError above, OR an unexpected crash
                # in the review block) must NOT silently fall through to
                # downstream with un-reviewed objectives — the review is a hard
                # prerequisite. Only the UNCONFIGURED case (no provider set)
                # keeps the original graceful "keep 7B objectives" posture.
                try:
                    from lib.objectives.objective_review import (  # noqa: PLC0415
                        resolve_objective_review_provider as _rorp,
                    )
                    _review_configured = bool(_rorp())
                except Exception:  # noqa: BLE001
                    _review_configured = False
                if _review_configured:
                    raise RuntimeError(
                        "objective-review pass failed while ENABLED "
                        f"({_review_exc}); failing course_planning rather than "
                        "proceeding downstream with un-reviewed objectives "
                        "(the quality review must complete before downstream)."
                    ) from _review_exc
                logger.warning(
                    "objective-review pass raised (%s); review not configured, "
                    "keeping original 7B objectives unchanged.", _review_exc,
                )

            # Finding 17 — concept / sub-objective layer. After objectives
            # are synthesized (+ optionally reviewed) and BEFORE
            # synthesized_objectives.json is written, populate each chapter
            # objective's ``sub_objectives`` list from its OWN already-grounded
            # source chunks. Default path is deterministic clustering (no LLM,
            # byte-stable when no embedder/chunks); the LLM arm is opt-in via
            # ``ED4ALL_SUB_OBJECTIVE_PROVIDER`` (default unset → off), so this
            # stays license-clean by default. Anti-fabrication is enforced by
            # the module: a sub-objective's source_chunk_ids are always a
            # strict subset of the CO's cited chunks — we only feed it chunk
            # bodies for ids the CO already references. Fully graceful: a
            # missing chunkset / embedder yields empty sub_objectives (the CO
            # is left unchanged). Mutates the ``chapter`` CO dicts in place;
            # we re-sync the populated lists back into ``lo_entries`` by id
            # (lo_entries were shallow-cloned BEFORE this hook, mirroring the
            # objective-review re-sync above).
            try:
                from lib.objectives.sub_objectives import (  # noqa: PLC0415
                    populate_sub_objectives as _populate_sub_objectives,
                    resolve_sub_objective_provider,
                )

                _so_slug = (course_name or "").lower().replace(
                    "_", "-"
                ).replace(" ", "-")
                _so_chunks_by_id: Dict[str, Any] = {}
                if _so_slug:
                    try:
                        _so_chunks_by_id, _ = _load_semantik_chunkset_for_planning(
                            course_slug=_so_slug,
                            kwargs=kwargs,
                        )
                    except Exception as _so_chunk_exc:  # noqa: BLE001
                        logger.warning(
                            "sub_objectives: chunkset load failed (%s); "
                            "CO sub_objectives will be empty.", _so_chunk_exc,
                        )
                        _so_chunks_by_id = {}

                _so_capture = None
                try:
                    from lib.decision_capture import (  # noqa: PLC0415
                        DecisionCapture as _SubObjDecisionCapture,
                    )

                    _so_capture = _SubObjDecisionCapture(
                        course_code=course_name,
                        phase="course-outliner",
                        tool="courseforge",
                        streaming=True,
                    )
                except Exception as _so_cap_exc:  # noqa: BLE001
                    logger.warning(
                        "DecisionCapture init failed for sub-objective "
                        "derivation: %s", _so_cap_exc,
                    )

                _so_provider = resolve_sub_objective_provider()
                _so_counters = _populate_sub_objectives(
                    chapter_objectives=chapter,
                    chunks_by_id=_so_chunks_by_id,
                    provider=_so_provider,
                    capture=_so_capture,
                )
                # WIRING-step decision event (dynamic signals: COs seen /
                # populated / total sub-objectives / provider). The per-CO
                # ``sub_objective_derivation`` events are emitted inside the
                # module; this one records the phase-level wiring outcome.
                if _so_capture is not None:
                    try:
                        _so_capture.log_decision(
                            decision_type="sub_objective_derivation",
                            decision=(
                                "sub_objectives:wired:"
                                f"{_so_counters.get('cos_populated', 0)}"
                                f"/{_so_counters.get('cos_seen', 0)} COs"
                            ),
                            rationale=(
                                "Finding 17 concept sub-layer wired into "
                                "course_planning: processed "
                                f"{_so_counters.get('cos_seen', 0)} chapter "
                                "objective(s), populated sub_objectives on "
                                f"{_so_counters.get('cos_populated', 0)} of them "
                                f"({_so_counters.get('sub_objectives_total', 0)} "
                                "sub-objectives total) from each CO's own cited "
                                "chunks; provider="
                                f"{_so_provider or 'deterministic'}, "
                                "chunkset_loaded="
                                f"{bool(_so_chunks_by_id)}. source_chunk_ids "
                                "stay a strict subset of the CO's grounded "
                                "chunks (anti-fabrication)."
                            ),
                        )
                    except Exception:  # noqa: BLE001 — capture must not break
                        pass
                logger.info(
                    "sub_objectives: populated %d/%d CO(s) with %d "
                    "sub-objective(s) (provider=%s).",
                    _so_counters.get("cos_populated", 0),
                    _so_counters.get("cos_seen", 0),
                    _so_counters.get("sub_objectives_total", 0),
                    _so_provider or "deterministic",
                )

                # Re-sync the populated sub_objectives back into lo_entries by
                # id (lo_entries were shallow-cloned before this hook ran).
                _so_by_id = {
                    str(c.get("id")): c
                    for c in chapter
                    if isinstance(c, dict) and c.get("id")
                }
                for _e in lo_entries:
                    _src = _so_by_id.get(str(_e.get("id")))
                    if _src is not None and _src.get("sub_objectives"):
                        _e["sub_objectives"] = list(_src["sub_objectives"])
            except GracefulStopRequested:
                # populate_sub_objectives' per-CO check_stop raised: propagate
                # the pause (never let the fail-soft handler below marshal it
                # into "leaving CO sub_objectives unchanged" + continue).
                raise
            except Exception as _so_exc:  # noqa: BLE001 — never fail the phase
                logger.warning(
                    "sub-objective derivation raised (%s); leaving CO "
                    "sub_objectives unchanged.", _so_exc,
                )

            # WS5 §2.4(A) — build the per-WEEK chapter groups that the
            # validator's allowed-set builder reads. Each group's objectives
            # are the SAME ceil-stride slice the emitter places for that week
            # (single-sourced via Courseforge/scripts/generate_course.py::
            # _slice_cos_for_week), labeled ``"Week N"`` so the validator's
            # 1:1 ``[Ww]eek N`` label-map branch resolves exactly the emitter's
            # week_chapter_cos. ``[dict(c)]`` clones each CO so the persisted
            # group is independent of the in-memory ``chapter`` list. Empty
            # ``chapter`` → empty groups (CO-less courses, byte-identical to
            # the prior empty-list-comprehension result).
            _ws5_week_chapter_groups: List[Dict[str, Any]] = []
            if chapter:
                # Single-sourced per-week CO grouping (ED4ALL_WEEK_TO_GROUPS):
                # ceil-stride by default (M5 Fix B shared placed-ids set, so the
                # PERSISTED groups never carry the same CO id in two weeks), or
                # TO-membership when the flag is on and weeks == num_tos. The
                # emit path (_generate_course_content) consumes the SAME helper,
                # so on-disk groups == emitted weeks by construction.
                _persist_week_groups = _week_co_groups(
                    chapter, terminal, duration_weeks,
                )
                for _w in range(1, duration_weeks + 1):
                    _week_cos = _persist_week_groups.get(_w, [])
                    _ws5_week_chapter_groups.append({
                        "chapter": f"Week {_w}",
                        "objectives": [dict(_c) for _c in _week_cos],
                    })

            # P2b — OBSERVABILITY: back-annotate each terminal objective with
            # the COs that roll up to it (``child_co_ids``) and the UNION of
            # those COs' cited chunks (``source_refs``). The CO→TO ``terminal_id``
            # backlink already lives on each ``chapter`` CO (set bottom-up in
            # _derive_terminals_bottom_up / by backlink_cos_to_tos), but the
            # persisted ``terminal_objectives[]`` carried EMPTY ``source_refs``
            # and no child pointer — so a TO→CO→chunk join did not exist on disk
            # and an objective-coverage audit had to reconstruct it by statement
            # matching (a covered TO then looks orphaned). Mutates ``terminal``
            # in place; we re-sync the populated fields onto the matching
            # ``lo_entries`` terminal rows by id so the on-disk
            # ``learning_outcomes`` array agrees with ``terminal_objectives``.
            # Anti-fabrication: chunk ids are a strict union of ids the child
            # COs already cite (no chunk invented); a childless TO keeps its
            # original empty ``source_refs``.
            try:
                _to_annot_counters = _annotate_terminals_with_children(
                    terminal, chapter
                )
                _to_child_by_id = {
                    str(t.get("id")): t
                    for t in terminal
                    if isinstance(t, dict) and t.get("id")
                }
                for _e in lo_entries:
                    if _e.get("hierarchy_level") != "terminal":
                        continue
                    _src_to = _to_child_by_id.get(str(_e.get("id")))
                    if _src_to is None:
                        continue
                    if "child_co_ids" in _src_to:
                        _e["child_co_ids"] = list(_src_to["child_co_ids"])
                    _src_refs = _src_to.get("source_refs")
                    if _src_refs:
                        _e["source_refs"] = [dict(r) for r in _src_refs]
                logger.info(
                    "plan_course_structure: TO back-annotation — %d/%d TO(s) "
                    "got child source_refs (%d CO(s) mapped, %d orphan TO(s)).",
                    _to_annot_counters.get("tos_annotated", 0),
                    len(terminal),
                    _to_annot_counters.get("cos_mapped", 0),
                    _to_annot_counters.get("orphan_tos", 0),
                )
                _to_annot_capture = None
                try:
                    from lib.decision_capture import (  # noqa: PLC0415
                        DecisionCapture as _ToAnnotDecisionCapture,
                    )

                    _to_annot_capture = _ToAnnotDecisionCapture(
                        course_code=course_name,
                        phase="course-outliner",
                        tool="courseforge",
                        streaming=True,
                    )
                except Exception:  # noqa: BLE001 — capture is observability
                    _to_annot_capture = None
                if _to_annot_capture is not None:
                    try:
                        _to_annot_capture.log_decision(
                            decision_type="content_selection",
                            decision=(
                                "to_child_backlink:"
                                f"{_to_annot_counters.get('tos_annotated', 0)}"
                                f"/{len(terminal)} TOs annotated"
                            ),
                            rationale=(
                                "P2b observability: back-annotated "
                                f"{_to_annot_counters.get('tos_annotated', 0)} of "
                                f"{len(terminal)} terminal objective(s) with "
                                "child_co_ids + a source_refs UNION of their "
                                "child COs' cited chunks ("
                                f"{_to_annot_counters.get('cos_mapped', 0)} CO(s) "
                                "mapped via terminal_id, "
                                f"{_to_annot_counters.get('orphan_tos', 0)} TO(s) "
                                "left childless) so the TO->CO->chunk join is "
                                "machine-readable on disk and a covered TO no "
                                "longer looks orphaned. Anti-fabrication: chunk "
                                "ids are a strict union of ids the child COs "
                                "already cite."
                            ),
                        )
                    except Exception:  # noqa: BLE001 — capture must not break
                        pass
            except Exception as _to_annot_exc:  # noqa: BLE001 — never fail phase
                logger.warning(
                    "TO child back-annotation raised (%s); terminal "
                    "objectives keep their original (empty) source_refs.",
                    _to_annot_exc,
                )

            synthesized = {
                "course_name": course_name,
                "generated_from": generated_from,
                "mint_method": mint_method,
                "duration_weeks": duration_weeks,
                "learning_outcomes": lo_entries,
                # Preserve the split-by-hierarchy shape the content
                # generator + CourseProcessor's load_objectives expect.
                "terminal_objectives": [dict(t) for t in terminal],
                # WS5 §2.4(A) — persist ONE chapter group per WEEK whose
                # objectives are exactly the emitter's ceil-stride slice for
                # that week (single-sourced via _slice_cos_for_week). The
                # validator's load_canonical_objectives takes the 1:1
                # ``"Week N"`` label-map branch over these groups, so
                # resolve_week_objectives(N) returns exactly the emitter's
                # week_chapter_cos — emit↔validator parity HOLDS BY
                # CONSTRUCTION (was per-CO ``"Week {idx}"`` groups, which only
                # agreed with the stride-`step` emitter when step==1, leaving a
                # latent LO_SPECIFICITY_VIOLATION at any duration_weeks <
                # len(chapter)).
                "chapter_objectives": _ws5_week_chapter_groups,
                # R7 §5.4 — per-chapter Stage-2 failure isolation.
                # Persisted so ChapterObjectiveCoverageValidator's
                # file-fallback (objectives.get("chapter_synthesis_
                # failures")) resolves and the expected-failure
                # cross-check is no longer dead code. Empty [] on the
                # deterministic / user-supplied / COURSEPLANNER paths.
                "chapter_synthesis_failures": list(
                    chapter_synthesis_failures
                ),
                "synthesized_at": datetime.now().isoformat(),
            }
            # ---- Write-time citation SANITIZER (default ON, deterministic). --
            # The local stage-2 synthesizer occasionally emits FABRICATED
            # citations (a descriptive topic label or the objective statement
            # echoed into source_refs / source_chunk_ids instead of a real
            # chunk id). Those ids resolve against NOTHING in the current
            # chunkset, so objective_source_refs' aggregate ORPHANED_CITATIONS
            # net fires CRITICAL and hard-blocks course_planning. This pass
            # DROPS every provably-unresolvable citation immediately before the
            # artifact is written (set-membership REMOVAL only — never invents
            # or re-points an id), converting the hard block into the benign
            # OBJECTIVE_NO_GROUNDING_SOURCE warning path on both grounding
            # gates. Universe-parity + empty-universe short-circuit mirror the
            # gate, so on a healthy corpus (nothing fabricated) OR a legacy /
            # no-chunkset run this is a byte-identical no-op regardless of the
            # flag; opt out with ED4ALL_OBJECTIVE_SANITIZE_CITATIONS=0.
            try:
                from lib.objectives.citation_sanitize import (  # noqa: PLC0415
                    build_chunk_universe as _build_chunk_universe,
                    resolve_sanitize_citations as _resolve_sanitize_citations,
                    sanitize_synthesized_objectives as _sanitize_objectives,
                )

                if _resolve_sanitize_citations():
                    _san_chunk_universe: set = set()
                    try:
                        _san_chunks_by_id, _san_all_chunks = (
                            _load_semantik_chunkset_for_planning(
                                course_slug=course_name, kwargs=kwargs,
                            )
                        )
                        _san_chunk_universe = _build_chunk_universe(
                            _san_all_chunks
                        )
                    except Exception:  # noqa: BLE001 — degrade to no universe
                        _san_chunk_universe = set()
                    _san_structure_universe: set = set()
                    try:
                        from lib.validators.objective_source_refs import (  # noqa: PLC0415
                            _load_textbook_structure_universe as _load_ts_universe,
                        )
                        _san_structure_universe = _load_ts_universe(
                            structure_path if structure_path.exists() else None
                        )
                    except Exception:  # noqa: BLE001 — degrade to no universe
                        _san_structure_universe = set()

                    _san_capture = None
                    try:
                        from lib.decision_capture import (  # noqa: PLC0415
                            DecisionCapture as _SanDecisionCapture,
                        )
                        _san_capture = _SanDecisionCapture(
                            course_code=course_name,
                            phase="course_planning",
                            tool="courseforge",
                            streaming=True,
                        )
                    except Exception:  # noqa: BLE001 — capture is observability
                        _san_capture = None

                    _san_result = _sanitize_objectives(
                        synthesized,
                        chunk_universe=_san_chunk_universe,
                        structure_universe=_san_structure_universe,
                        capture=_san_capture,
                    )
                    if _san_result.available and _san_result.los_mutated:
                        logger.info(
                            "plan_course_structure: citation sanitizer dropped "
                            "%d structured chunk_id(s), %d legacy string(s), "
                            "%d flat id(s), %d fabricated entry/entries across "
                            "%d/%d LO(s) (universe: chunks=%d, structure=%d).",
                            _san_result.structured_chunk_ids_dropped,
                            _san_result.legacy_strings_dropped,
                            _san_result.flat_chunk_ids_dropped,
                            _san_result.entries_dropped,
                            _san_result.los_mutated,
                            _san_result.los_scanned,
                            len(_san_chunk_universe),
                            len(_san_structure_universe),
                        )
            except Exception as _san_exc:  # noqa: BLE001 — never fail the phase
                logger.warning(
                    "plan_course_structure: citation sanitizer raised (%s); "
                    "writing objectives unsanitized.", _san_exc,
                )

            objectives_out_path = (
                project_path / "01_learning_objectives" / "synthesized_objectives.json"
            )
            objectives_out_path.write_text(
                json.dumps(synthesized, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )

            # W4.3 — cross-course objective-library EXEMPLARS (default OFF via
            # ``ED4ALL_OBJECTIVE_LIBRARY_EXEMPLARS``). Surface exemplar
            # objectives drawn from OTHER catalog-enabled LibV2 courses as
            # advisory, provenance-labeled SUGGESTIONS/priors — written to a
            # SEPARATE ``objective_library_exemplars.json`` sidecar. Hard
            # anti-fabrication: exemplars are advisory context only, are never
            # injected as THIS course's canonical objectives, and
            # ``synthesized_objectives.json`` (written above) is untouched.
            # Default-OFF is a strict no-op: no sidecar written, no discovery,
            # byte-identical output. Best-effort — any failure logs a warning
            # and never blocks the phase.
            try:
                from lib.objectives.library_exemplars import (  # noqa: PLC0415
                    build_query_terms as _build_exemplar_query_terms,
                    resolve_library_exemplars_enabled as _exemplars_enabled,
                    surface_exemplars as _surface_exemplars,
                )

                if _exemplars_enabled():
                    _ex_current_slug = (
                        (course_name or "")
                        .lower()
                        .replace("_", "-")
                        .replace(" ", "-")
                    )
                    _ex_query_terms = _build_exemplar_query_terms(
                        terminal, chapter
                    )
                    _ex_result = _surface_exemplars(
                        course_name=course_name,
                        query_terms=_ex_query_terms,
                        libv2_root=kwargs.get("libv2_root"),
                        current_slug=_ex_current_slug or None,
                    )
                    _ex_sidecar = (
                        project_path
                        / "01_learning_objectives"
                        / "objective_library_exemplars.json"
                    )
                    _ex_sidecar.write_text(
                        json.dumps(_ex_result, indent=2, ensure_ascii=False),
                        encoding="utf-8",
                    )
                    logger.info(
                        "objective-library exemplars surfaced: %d exemplars "
                        "from %d source course(s) (%d candidates scanned) -> %s",
                        _ex_result.get("exemplar_count", 0),
                        _ex_result.get("source_course_count", 0),
                        _ex_result.get("candidate_count", 0),
                        _ex_sidecar,
                    )
                    try:
                        from lib.decision_capture import (  # noqa: PLC0415
                            DecisionCapture as _ExDecisionCapture,
                        )

                        _ex_capture = _ExDecisionCapture(
                            course_code=course_name,
                            phase="course-outliner",
                            tool="courseforge",
                            streaming=True,
                        )
                        _ex_provs = [
                            e.get("provenance")
                            for e in _ex_result.get("exemplars", [])
                        ]
                        _ex_capture.log_decision(
                            decision_type="content_selection",
                            decision=(
                                "surfaced "
                                f"{_ex_result.get('exemplar_count', 0)} "
                                "cross-course objective exemplar(s) as advisory "
                                "priors"
                            ),
                            rationale=(
                                "ED4ALL_OBJECTIVE_LIBRARY_EXEMPLARS on: ranked "
                                f"{_ex_result.get('candidate_count', 0)} library "
                                "objective(s) by lexical overlap against "
                                f"{_ex_result.get('query_term_count', 0)} query "
                                "term(s) from this course's own grounded "
                                "objectives; kept top "
                                f"{_ex_result.get('exemplar_count', 0)} from "
                                f"{_ex_result.get('source_course_count', 0)} "
                                "source course(s) as advisory, provenance-"
                                "labeled suggestions only (never injected as "
                                "canonical); min_overlap="
                                f"{_ex_result.get('min_overlap')}, limit="
                                f"{_ex_result.get('limit')}."
                            ),
                            alternatives_considered=_ex_provs or None,
                            confidence=0.5,
                        )
                    except Exception as _ex_cap_exc:  # noqa: BLE001
                        logger.warning(
                            "objective-library exemplar DecisionCapture failed "
                            "(non-fatal): %s",
                            _ex_cap_exc,
                        )
            except Exception as _ex_exc:  # noqa: BLE001 — advisory, never fatal
                logger.warning(
                    "objective-library exemplar surfacing raised (%s); "
                    "proceeding without exemplar sidecar.",
                    _ex_exc,
                )

            # Thread the path back into project_config so
            # _generate_course_content + Trainforge's CourseProcessor
            # (_invoke_trainforge) pick it up automatically.
            config_data["objectives_path"] = str(objectives_out_path)
            config_data["synthesized_objectives_path"] = str(objectives_out_path)
            # Provenance for the self-poisoning reuse guard above: record
            # whether these objectives came from an operator pin
            # (``--objectives`` / an operator-provenance config pin) or
            # from fresh pipeline synthesis. A "pipeline" pin must NOT
            # short-circuit synthesis when this phase re-runs.
            config_data["objectives_source"] = (
                "operator"
                if mint_method in _OPERATOR_OBJECTIVE_MINTS
                else "pipeline"
            )
            config_data["course_name"] = course_name
            config_data["duration_weeks"] = duration_weeks
            config_data["project_id"] = project_id
            config_data["status"] = "planned"
            config_path.write_text(
                json.dumps(config_data, indent=2), encoding="utf-8",
            )

            # Wave2-I7 (dispatch-7 Finding 8): build ``objective_ids``
            # as a canonical ``List[str]`` so the
            # ``trainforge_assessment.inputs_from`` route resolves to a
            # non-None list when the workflow resumes from this phase's
            # checkpoint. The runner's ``_route_params`` comma-joins
            # list values on the wire (workflow_runner.py:1687-1688) so
            # downstream ``_generate_assessments`` still sees the
            # comma-string shape it already handles. Canonical order:
            # terminals first, then chapter LOs (matches the
            # ``lo_entries`` assembly above and the on-disk
            # ``learning_outcomes`` array). Defensive: read all three
            # supported ``chapter_objectives`` shapes via the
            # module-level normalizer
            # ``_normalize_chapter_objectives_to_groups`` (Wave2b —
            # adds the vendor dict-of-lists shape on top of the
            # legacy list-of-groups + flat-list shapes). Terminals are
            # read from either ``terminal_objectives`` or the LibV2
            # ``terminal_outcomes`` alias.
            def _collect_lo_ids(payload: Dict[str, Any]) -> List[str]:
                ids: List[str] = []
                terminals = (
                    payload.get("terminal_objectives")
                    or payload.get("terminal_outcomes")
                    or []
                )
                for entry in terminals:
                    if isinstance(entry, dict) and entry.get("id"):
                        ids.append(str(entry["id"]))
                chapters_raw = (
                    payload.get("chapter_objectives")
                    or payload.get("component_objectives")
                    or []
                )
                for group in _normalize_chapter_objectives_to_groups(
                    chapters_raw,
                ):
                    for entry in group.get("objectives") or []:
                        if isinstance(entry, dict) and entry.get("id"):
                            ids.append(str(entry["id"]))
                return ids

            objective_ids: List[str] = _collect_lo_ids(synthesized)
            # Fallback: if the synthesized payload's id-bearing dicts
            # were stripped en route, fall back to ``lo_entries`` (same
            # canonical order: terminal-first).
            if not objective_ids:
                objective_ids = [
                    str(e["id"]) for e in lo_entries if e.get("id")
                ]

            # Wave3-Anew3 (Finding F3): back-fill the DART chunkset's
            # ``learning_outcome_refs`` against the just-minted objective_ids.
            # ``_run_dart_chunking`` ran BEFORE this phase, so its chunks
            # carry empty LO refs by construction. Text-scan + allowlist
            # filter populates the field deterministically; existing
            # non-empty refs (legacy corpora) are preserved via union
            # semantics. Best-effort — failure logs a warning, does not
            # block the phase output.
            course_slug = (course_name or "").lower().replace("_", "-").replace(" ", "-")
            backfill_summary: Dict[str, Any] = {}
            # W1b.5 heuristic arm needs the objective STATEMENTS (not just
            # ids). Build the {id: statement} view and hand it to the
            # back-fill; the heuristic only fires under ED4ALL_CHUNK_LO_HEURISTIC
            # (default off ⇒ objectives ignored, exact-scan byte-identical).
            heuristic_objectives = [
                {"id": _oid, "statement": _stmt}
                for _oid, _stmt in _objective_id_to_statement(synthesized).items()
            ]
            if course_slug and objective_ids:
                try:
                    backfill_summary = _backfill_dart_chunk_lo_refs(
                        course_slug=course_slug,
                        objective_ids=objective_ids,
                        libv2_root=kwargs.get("libv2_root"),
                        objectives=heuristic_objectives,
                    )
                    if backfill_summary.get("chunks_updated"):
                        logger.info(
                            "Wave3-Anew3: back-filled learning_outcome_refs on "
                            "%d/%d DART chunks (+%d refs total) at %s",
                            backfill_summary["chunks_updated"],
                            backfill_summary["chunks_scanned"],
                            backfill_summary["new_refs_total"],
                            backfill_summary["chunks_path"],
                        )
                except Exception as exc:  # noqa: BLE001 — best-effort
                    logger.warning(
                        "Wave3-Anew3: DART chunk LO-ref back-fill failed "
                        "(%s); proceeding with empty refs.",
                        exc,
                    )

            return json.dumps({
                "success": True,
                "project_id": project_id,
                "project_path": str(project_path),
                "synthesized_objectives_path": str(objectives_out_path),
                "objective_ids": objective_ids,
                "terminal_count": len(terminal),
                "chapter_count": len(chapter),
                "mint_method": mint_method,
                "duration_weeks": duration_weeks,
                "dart_chunk_lo_backfill": backfill_summary,
                # Stage-2 grounding + citation-reselect counters (all-zero /
                # {} when Stage-2 window synthesis did not run). Surfaced so a
                # post-run audit can read reselect_pool_misses /
                # citations_reselected from
                # phase_outputs.course_planning.grounding_signals without
                # scraping INFO logs. Every value is a plain int/float/bool/str.
                "grounding_signals": _grounding_signals,
            })

        registry["plan_course_structure"] = _plan_course_structure

        # ============================================================================
        # BLOCK: Worker α edits ONLY below this line through the next END marker.
        # Scope: _generate_course_content replacement. See plans/pipeline-execution-
        # fixes/contracts.md § "Courseforge content-generator contract".
        # ============================================================================
        async def _generate_course_content(**kwargs):
            """Generate 5-page weekly course modules from DART outputs + objectives.

            Replaces the legacy single-page stub with a full Courseforge
            emission: overview, content, application, self_check, and
            summary pages per week. Every emitted page carries the full
            ``data-cf-*`` attribute surface and a JSON-LD
            ``CourseModule`` body that validates against
            ``schemas/knowledge/courseforge_jsonld_v1.schema.json``.

            Delegates the actual HTML rendering to
            ``Courseforge.scripts.generate_course.generate_week`` (the
            mature multi-file emitter) — this wrapper only adapts the
            pipeline's kwargs into the ``week_data`` payload that the
            emitter consumes, plus forwards the Wave 9 source-routing
            map when one is present on disk.
            """
            from Courseforge.scripts import generate_course as _gen
            from MCP.tools import _content_gen_helpers as _cgh

            project_id = kwargs.get("project_id", "")
            if not project_id:
                return json.dumps({"error": "generate_course_content requires project_id"})

            project_path = courseforge_exports_dir() / project_id
            content_dir = project_path / "03_content_development"
            content_dir.mkdir(parents=True, exist_ok=True)

            config_path = project_path / "project_config.json"
            if not config_path.exists():
                return json.dumps({"error": f"Project config not found: {config_path}"})
            with open(config_path) as f:
                config = json.load(f)

            course_code = config.get("course_name") or project_id
            # Wave 40: honor the auto-scaled duration_weeks persisted by
            # _extract_textbook_structure. Config is authoritative when the
            # CLI's --weeks wasn't explicit; only a truly explicit kwarg may
            # override the value the extractor committed to disk.
            duration_explicit = bool(kwargs.get("duration_weeks_explicit", False))
            kwarg_duration = kwargs.get("duration_weeks")
            if duration_explicit and kwarg_duration:
                duration_weeks = int(kwarg_duration)
            else:
                duration_weeks = int(config.get("duration_weeks") or kwarg_duration or 12)
            objectives_path = config.get("objectives_path") or kwargs.get("objectives_path")

            # ---------------------------------------------------------- #
            # Staged DART HTML — prefer the staging_dir passed by the    #
            # workflow runner; fall back to the most-recent staging run. #
            # ---------------------------------------------------------- #
            staging_kwarg = kwargs.get("staging_dir")
            staging_dir = Path(staging_kwarg) if staging_kwarg else None
            html_files = _cgh.collect_staged_html(staging_dir, COURSEFORGE_INPUTS)
            topics = _cgh.parse_dart_html_files(html_files)

            # ---------------------------------------------------------- #
            # Objectives: honor supplied JSON; synthesize from DART otherwise.
            # ---------------------------------------------------------- #
            terminal_objectives, chapter_objectives = _cgh.load_objectives_json(
                objectives_path
            )
            if not terminal_objectives and not chapter_objectives:
                terminal_objectives, chapter_objectives = (
                    _cgh.synthesize_objectives_from_topics(topics, duration_weeks)
                )

            all_objectives = list(terminal_objectives) + list(chapter_objectives)
            topics_by_week = _cgh._group_topics_by_week(topics, duration_weeks)

            # ---------------------------------------------------------- #
            # Source-routing map (Wave 9). Empty dict or missing file =>  #
            # backward-compat path: pages emit without sourceReferences.  #
            # ---------------------------------------------------------- #
            source_module_map: Dict[str, Any] = {}
            map_path_kwarg = kwargs.get("source_module_map_path")
            if map_path_kwarg:
                map_path = Path(map_path_kwarg)
            else:
                map_path = project_path / "source_module_map.json"
            if map_path.exists():
                try:
                    source_module_map = json.loads(
                        map_path.read_text(encoding="utf-8")
                    ) or {}
                except (OSError, ValueError):
                    source_module_map = {}

            # Wave 2 prerequisite map: each page prerequisites the prior
            # page in the 5-page week sequence.
            prerequisite_map: Dict[str, list] = {}
            for week_num in range(1, duration_weeks + 1):
                w = f"{week_num:02d}"
                prerequisite_map[f"week_{w}_application"] = [
                    f"week_{w}_overview"
                ]
                prerequisite_map[f"week_{w}_self_check"] = [
                    f"week_{w}_application"
                ]
                prerequisite_map[f"week_{w}_summary"] = [
                    f"week_{w}_self_check"
                ]

            # ---------------------------------------------------------- #
            # Decision capture — content-generator phase.                 #
            # ---------------------------------------------------------- #
            # Phase 1 ToS unblock: COURSEFORGE_PROVIDER env (anthropic /
            # together / local) opens an in-process LLM seam alongside
            # the Wave-74 subagent dispatch path. Default unset =>
            # deterministic DART-paragraph synthesis (legacy behavior).
            _courseforge_provider_env = os.environ.get(
                "COURSEFORGE_PROVIDER", ""
            ).strip()

            capture = None
            try:
                from lib.decision_capture import DecisionCapture
                capture = DecisionCapture(
                    course_code=course_code,
                    phase="content-generator",
                    tool="courseforge",
                    streaming=True,
                )
                capture.log_decision(
                    decision_type="content_structure",
                    decision=(
                        f"Emit 5-page weekly modules (overview, content, "
                        f"application, self_check, summary) for "
                        f"{duration_weeks} weeks via Courseforge generate_week."
                    ),
                    rationale=(
                        "The 5-page structure matches the Courseforge "
                        "pipeline contract (plans/pipeline-execution-fixes/"
                        "contracts.md) and ensures each weekly module "
                        "validates under the page_objectives + "
                        "content_structure gates."
                    ),
                )
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "DecisionCapture init failed in content-generator: %s", exc
                )
                capture = None

            # Instantiate the in-process LLM provider when the env var
            # is set. We fail-loud here (e.g. missing ANTHROPIC_API_KEY)
            # rather than silently falling back to deterministic so the
            # operator's intent is honored or surfaced clearly.
            content_provider = None
            if _courseforge_provider_env:
                try:
                    from Courseforge.generators._provider import (
                        ContentGeneratorProvider,
                    )
                    content_provider = ContentGeneratorProvider(
                        capture=capture,
                    )
                    logger.info(
                        "COURSEFORGE_PROVIDER=%s; routing content-generator "
                        "through in-process provider.",
                        _courseforge_provider_env,
                    )
                except Exception as exc:
                    logger.exception(
                        "ContentGeneratorProvider init failed (provider=%s): %s",
                        _courseforge_provider_env,
                        exc,
                    )
                    raise

            # Phase 3 Subtask 61: when ``COURSEFORGE_TWO_PASS=true`` is
            # set, instantiate a :class:`CourseforgeRouter` and pass it
            # through to :func:`build_week_data` so the per-page emit
            # dispatches via the two-pass outline → inter-tier validate
            # → rewrite pipeline instead of the legacy single-pass
            # ``ContentGeneratorProvider``. The router is fully additive
            # — when the flag is off, ``content_router`` stays ``None``
            # and the legacy ``content_provider`` path runs unchanged
            # (preserves Phase 1 byte-stable behavior). Construction
            # mirrors the ``content_provider`` block above: load the
            # YAML policy + DecisionCapture once at the call site, fail
            # loud on init exceptions so an operator's opt-in intent is
            # surfaced rather than silently downgraded to legacy.
            content_router = None
            if _courseforge_two_pass_enabled():
                try:
                    from Courseforge.router.router import CourseforgeRouter
                    from Courseforge.router.policy import (
                        load_block_routing_policy,
                    )
                    content_router = CourseforgeRouter(
                        capture=capture,
                        policy=load_block_routing_policy(),
                    )
                    logger.info(
                        "COURSEFORGE_TWO_PASS=true; routing "
                        "content-generator through two-pass "
                        "CourseforgeRouter (outline → validate → rewrite).",
                    )
                except Exception as exc:
                    logger.exception(
                        "CourseforgeRouter init failed under "
                        "COURSEFORGE_TWO_PASS=true: %s",
                        exc,
                    )
                    raise

            # ---------------------------------------------------------- #
            # Emit each week via generate_week.                           #
            # ---------------------------------------------------------- #
            generated_files: list = []
            weeks_prepared = 0
            # Anti-silent-template guard: per-page authorship tally folded
            # into the provenance below so a provider/router that degrades
            # to the template floor at runtime is caught (not just the
            # construct-time generator_mode).
            _authorship_stats: Dict[str, int] = {
                "llm_authored": 0, "template_fallback": 0,
            }
            # Single-sourced per-week CO grouping (ED4ALL_WEEK_TO_GROUPS):
            # computed ONCE over the flat CO list so the emitted week membership
            # matches the PERSISTED "Week N" groups (built by the same helper in
            # _plan_course_structure) — emit↔validator parity by construction.
            # Default flag-off path = the legacy ceil-stride slice with the M5
            # Fix B shared placed-ids set (a CO placed in an earlier week is
            # never re-placed later); flag-on + weeks==num_tos = TO-membership.
            _emit_week_groups = (
                _week_co_groups(
                    chapter_objectives, terminal_objectives, duration_weeks
                )
                if chapter_objectives
                else {}
            )
            # Per-week resume sidecar (P4 item 3). Lives in the content OUTPUT
            # dir; loaded once so a resumed run skips already-emitted weeks
            # instead of re-authoring them. Inert (empty cache, no writes) when
            # the family flag is disabled. ``provider_spec`` folds the authoring
            # mode into every week's fingerprint so a provider/two-pass swap
            # between resume attempts re-runs the affected weeks.
            _cg_checkpoint_path = (
                content_dir / _LEGACY_CONTENTGEN_CHECKPOINT_NAME
            )
            _cg_store = _legacy_contentgen_store(_cg_checkpoint_path)
            _cg_cache = _cg_store.load()
            _cg_provider_spec = (
                f"router={content_router is not None}|"
                f"provider={_courseforge_provider_env}|"
                f"two_pass={_courseforge_two_pass_enabled()}"
            )
            for week_num in range(1, duration_weeks + 1):
                # Graceful stop (checkpoint on command): raise at the week-loop
                # unit boundary. Every prior week was appended to the sidecar (or
                # served from the resume cache), so a stop here loses at most the
                # in-flight week. A pre-armed sentinel raises on week 1 (zero
                # weeks emitted). Sequential loop → plain check_stop.
                check_stop("content_generation_legacy", weeks_prepared)
                week_topics = (
                    topics_by_week[week_num - 1]
                    if (week_num - 1) < len(topics_by_week)
                    else []
                )
                # Per-week LO set: scope to this week's terminals + at most
                # two chapter objectives round-robin assigned by week.
                # Earlier revisions prepended ALL terminal_objectives to
                # every week, which over-connected the derived-from-
                # objective edges in the KG (O(N*D) instead of O(N)).
                # Now: each week gets only the terminal slice round-robin
                # assigned to it.
                # Read this week's COs from the pre-computed single-source
                # grouping (ceil-stride by default, TO-membership under
                # ED4ALL_WEEK_TO_GROUPS). Persist + emit call the same helper so
                # emit-week-N ids == validator-allowed-week-N ids by construction.
                week_chapter_cos = list(_emit_week_groups.get(week_num, []))

                # Scope terminals per week. With N terminals and D weeks,
                # each week claims ceil(N/D) terminals in source order.
                week_terminals: list = []
                if terminal_objectives:
                    t_step = max(
                        1,
                        (len(terminal_objectives) + duration_weeks - 1) // duration_weeks,
                    )
                    t_start = (week_num - 1) * t_step
                    week_terminals = list(
                        terminal_objectives[t_start:t_start + t_step]
                    )
                    # Guarantee at least one terminal per week when corpus
                    # has any terminals at all — round-robin fallback.
                    if not week_terminals:
                        week_terminals = [
                            terminal_objectives[(week_num - 1) % len(terminal_objectives)]
                        ]

                week_objectives = list(week_terminals) + week_chapter_cos
                seen: set = set()
                week_objectives_deduped = []
                for o in week_objectives:
                    if o["id"] in seen:
                        continue
                    seen.add(o["id"])
                    week_objectives_deduped.append(o)

                # Resume sidecar: skip a week whose fingerprint matches AND whose
                # page files all still exist on disk (re-collect them into the
                # emit list) — the expensive ``build_week_data`` authoring +
                # ``generate_week`` write are avoided. A fingerprint miss / any
                # missing page file re-emits the week fresh.
                _cg_week_key = _legacy_contentgen_week_key(week_num)
                _cg_week_fp = _legacy_contentgen_week_fingerprint(
                    week_num=week_num,
                    week_objectives=week_objectives_deduped,
                    provider_spec=_cg_provider_spec,
                    duration_weeks=duration_weeks,
                    course_code=course_code,
                )
                _cg_reused = _cg_store.reuse(
                    _cg_week_key, _cg_week_fp, cache=_cg_cache,
                )
                if _cg_reused is not None:
                    _reused_paths = [
                        str(p) for p in (_cg_reused.get("page_paths") or [])
                    ]
                    if _reused_paths and all(
                        Path(p).exists() for p in _reused_paths
                    ):
                        generated_files.extend(_reused_paths)
                        weeks_prepared += 1
                        continue

                week_data = _cgh.build_week_data(
                    week_num=week_num,
                    duration_weeks=duration_weeks,
                    week_topics=week_topics,
                    week_objectives=week_objectives_deduped,
                    all_objectives=all_objectives,
                    course_code=course_code,
                    content_provider=content_provider,
                    content_router=content_router,
                    authorship_stats=_authorship_stats,
                )

                try:
                    count, files = _gen.generate_week(
                        week_data,
                        content_dir,
                        course_code,
                        canonical_objectives=None,  # week_data already has canonical ids
                        classification=None,
                        prerequisite_map=prerequisite_map,
                        source_module_map=source_module_map or None,
                    )
                except Exception as exc:  # noqa: BLE001
                    logger.exception(
                        "generate_week failed for week %d: %s", week_num, exc
                    )
                    continue

                weeks_prepared += 1
                week_dir = content_dir / f"week_{week_num:02d}"
                _week_page_paths: list = []
                for name in files:
                    page_path = week_dir / name
                    # Post-process: ensure every page carries an
                    # objectives <section>. Overview already has one
                    # from generate_week; the other four pages don't by
                    # default but the page_objectives gate + integration
                    # test require the data-cf-objective-id attribute on
                    # every page.
                    try:
                        body = page_path.read_text(encoding="utf-8")
                        updated = _cgh.ensure_objectives_on_page(
                            body, week_objectives_deduped,
                        )
                        if updated != body:
                            page_path.write_text(updated, encoding="utf-8")
                    except OSError as exc:
                        logger.warning(
                            "Failed to post-process %s: %s", page_path, exc,
                        )
                    generated_files.append(str(page_path))
                    _week_page_paths.append(str(page_path))

                # Checkpoint the completed week (flush+fsync) so a resume skips
                # it. Appended AFTER generate_week + post-processing wrote every
                # page file — a stop at the NEXT loop-top then loses nothing.
                _cg_store.append(
                    _cg_week_key, _cg_week_fp,
                    {"page_paths": _week_page_paths},
                )

                if capture is not None:
                    try:
                        source_stems = sorted({
                            t.get("source_file", "") for t in week_topics
                            if t.get("source_file")
                        })
                        primary_heading = (
                            week_topics[0]["heading"] if week_topics else "synthetic"
                        )
                        capture.log_decision(
                            decision_type="source_selection",
                            decision=(
                                f"Week {week_num}: ground content on "
                                f"{primary_heading!r} from sources "
                                f"{source_stems or ['(no DART staging found)']}."
                            ),
                            rationale=(
                                "Selected DART-derived topics whose parsed "
                                "headings align with the week's chapter "
                                "objectives; synthesized placeholder content "
                                "only when no DART topics were available."
                            ),
                        )
                    except Exception:  # noqa: BLE001
                        # Never let decision capture crash emission.
                        pass

            # Wave 32 Deliverable C: fail the phase when every
            # generated page is an empty template skeleton. Pre-Wave-32
            # ``content_generation`` silently passed even when the
            # dispatcher returned zero actual body content — each page
            # carried only ``<h1>Week N</h1><h2>Overview</h2>`` with no
            # paragraphs ≥ 30 words. The counts showed 12/12 complete
            # and gates rubber-stamped it. This check reuses the same
            # ``NON_TRIVIAL_WORD_FLOOR`` (30) as the Wave 31
            # ContentGroundingValidator for behavioural consistency:
            # parse every emitted page, count body words in
            # ``<p>/<li>/<blockquote>/<figcaption>`` within ``<main>``
            # (or the document body when no main wrapper is present),
            # and fail the phase when zero pages clear the floor.
            empty_error = _check_content_nonempty(generated_files)
            if empty_error is not None:
                return json.dumps({
                    "success": False,
                    "error_code": "CONTENT_GENERATION_EMPTY",
                    "error": empty_error,
                    "project_id": project_id,
                    "page_paths": generated_files,
                    "content_dir": str(content_dir),
                    "weeks_prepared": weeks_prepared,
                })

            # Wave 32 Deliverable B: surface page_paths + content_dir so
            # downstream gate input routing picks them up. Pre-Wave-32
            # ``content_paths`` landed as a plain list in phase_outputs,
            # but the router's builders inspect ``content_paths`` only
            # when it's a comma-joined ``str`` and otherwise flag
            # ``page_paths`` / ``content_dir`` as missing — every live
            # re-sim showed ``content_grounding`` + ``page_objectives``
            # silently skipping with ``missing inputs: *``. The fix is
            # purely on the emit side: surface the list as
            # ``page_paths`` (the router's canonical key) and also
            # surface ``content_paths`` as a comma-joined str for the
            # legacy parsers (_all_html_paths, _find_content_dir).
            # -------------------------------------------------------- #
            # Generation provenance (anti-silent-template guard).      #
            # The deterministic ``generate_week`` template emitter must #
            # NEVER silently stand in for real LLM content authoring in #
            # a production run. Record which path actually ran so the   #
            # ContentAuthorshipValidator gate can BLOCK a template-only #
            # result when LLM authoring was the operator's intent — and #
            # warn loudly here regardless. ``generate_course_content``  #
            # stamps its own honest provenance, so an operator who runs #
            # the template tool out-of-band (e.g. to service a mailbox  #
            # agent_task) cannot launder it as LLM-authored content.    #
            # -------------------------------------------------------- #
            if content_router is not None:
                generator_mode = "two_pass_router"
            elif content_provider is not None:
                generator_mode = "llm_provider"
            else:
                generator_mode = "template_deterministic"

            # Runtime degradation: a constructed provider/router that fell
            # back to the deterministic template floor on EVERY page authored
            # zero real LLM content — treat it as a template run regardless of
            # construct-time mode. Partial degradation is surfaced as a flag.
            _llm_authored = _authorship_stats.get("llm_authored", 0)
            _template_fallback = _authorship_stats.get("template_fallback", 0)
            llm_authoring_degraded = (
                generator_mode != "template_deterministic"
                and _template_fallback > 0
            )
            if (
                generator_mode != "template_deterministic"
                and _llm_authored == 0
                and _template_fallback > 0
            ):
                # Provider/router was wired but authored nothing — this is a
                # template run in disguise.
                generator_mode = "template_deterministic"

            template_fired = generator_mode == "template_deterministic"

            def _envflag(name: str) -> bool:
                return os.environ.get(name, "").strip().lower() in (
                    "1", "true", "yes", "on"
                )

            agent_dispatch_enabled = _envflag("ED4ALL_AGENT_DISPATCH")
            allow_template = _envflag("COURSEFORGE_ALLOW_TEMPLATE_EMITTER")
            llm_authoring_intended = bool(
                _courseforge_provider_env
                or _courseforge_two_pass_enabled()
                or agent_dispatch_enabled
            )

            if template_fired:
                _msg = (
                    "TEMPLATE EMITTER FIRED for content_generation "
                    f"(course={course_code}, weeks={weeks_prepared}): the "
                    "deterministic generate_week template produced these "
                    "pages — NOT a real LLM content-generator. This should "
                    "not happen in a real run. Configure COURSEFORGE_PROVIDER "
                    "(anthropic/together/local), COURSEFORGE_TWO_PASS=true, or "
                    "service the content-generator mailbox tasks with real "
                    f"subagents. (llm_authored_pages={_llm_authored}, "
                    f"template_fallback_pages={_template_fallback})"
                )
                if llm_authoring_intended and not allow_template:
                    logger.error(
                        "%s LLM authoring was intended (provider=%r "
                        "two_pass=%s agent_dispatch=%s); the content_authorship "
                        "gate will BLOCK this run.",
                        _msg, _courseforge_provider_env,
                        _courseforge_two_pass_enabled(), agent_dispatch_enabled,
                    )
                else:
                    logger.warning("%s", _msg)
            elif llm_authoring_degraded:
                # Provider/router authored SOME pages but silently fell back
                # to the template floor on others — flag loudly even though
                # the gate won't block a partially-authored run.
                logger.warning(
                    "content_generation PARTIAL TEMPLATE FALLBACK "
                    "(course=%s): %d page(s) authored by the LLM "
                    "provider/router, %d page(s) silently degraded to the "
                    "deterministic template floor. Inspect provider health "
                    "(network / budget / parse misses).",
                    course_code, _llm_authored, _template_fallback,
                )

            generation_provenance = {
                "schema_version": "1.1",
                "generator_mode": generator_mode,
                "template_fallback_fired": template_fired,
                "llm_authored_pages": _llm_authored,
                "template_fallback_pages": _template_fallback,
                "llm_authoring_degraded": llm_authoring_degraded,
                "courseforge_provider": _courseforge_provider_env,
                "two_pass_enabled": _courseforge_two_pass_enabled(),
                "agent_dispatch_enabled": agent_dispatch_enabled,
                "llm_authoring_intended": llm_authoring_intended,
                "allow_template_emitter": allow_template,
                "weeks_prepared": weeks_prepared,
                "page_count": len(generated_files),
                "course_code": course_code,
            }
            provenance_path = project_path / "content_generation_provenance.json"
            try:
                provenance_path.write_text(
                    json.dumps(generation_provenance, indent=2), encoding="utf-8"
                )
            except OSError as exc:  # noqa: BLE001
                logger.warning(
                    "Failed to write content_generation_provenance.json: %s", exc
                )
                provenance_path = None

            # Crash-resume sidecar cleanup: every week is on disk, so the
            # interrupted-run checkpoint is no longer needed (removed only on
            # this successful final return, never on a graceful-stop pause).
            _cg_store.remove()

            content_paths_str = ",".join(generated_files)
            return json.dumps({
                "success": True,
                "project_id": project_id,
                "weeks_prepared": weeks_prepared,
                "content_paths": content_paths_str,
                "page_paths": generated_files,
                "content_dir": str(content_dir),
                "source_sections": len(topics),
                "content_selection": (
                    "source-grounded" if topics else "synthesized"
                ),
                "generator_mode": generator_mode,
                "template_fallback_fired": template_fired,
                "content_generation_provenance_path": (
                    str(provenance_path) if provenance_path else ""
                ),
            })

        registry["generate_course_content"] = _generate_course_content
        # END BLOCK: Worker α

        # Phase 3.5 Subtasks 28-30: register the three two-pass router
        # phase helpers so the executor's _PHASE_TOOL_MAPPING shim
        # (Subtask 31) can dispatch to them by phase name.
        registry["run_content_generation_outline"] = (
            _run_content_generation_outline
        )
        registry["run_inter_tier_validation"] = _run_inter_tier_validation
        registry["run_content_generation_rewrite"] = (
            _run_content_generation_rewrite
        )
        # Phase 3.5 Subtask 13 + Wave C: also register the post_rewrite_validation
        # helper so phase-name dispatch can route to it (Subtask 31).
        registry["run_post_rewrite_validation"] = _run_post_rewrite_validation

        async def _package_imscc(**kwargs):
            """Build a real IMS Common Cartridge package from generated content.

            ⚠  **Sync-parity with**
            ``MCP/tools/courseforge_tools.py::package_imscc`` (the
            ``@mcp.tool()`` variant) is required. Both wrappers delegate to
            ``Courseforge.scripts.package_multifile_imscc.package_imscc``
            and share the same JSON envelope shape. This registry variant
            omits the `project_config.status`/`package_path` side-effects
            that the MCP-decorated variant performs — phase tracking
            happens in the workflow runner here. Keep both surfaces in
            lockstep until a shared helper is extracted in a later wave.

            Wave 27 HIGH-2: delegates to the mature multi-file packager
            (``Courseforge.scripts.package_multifile_imscc.package_imscc``)
            rather than hand-rolling the ZIP. Consequences of the
            delegation:

            * Per-week ``learningObjectives`` validation runs by default
              (the mature packager refuses to build when any page's LO
              list references an out-of-week ID).
            * ``course_metadata.json`` is bundled at the zip root when
              present (the mature packager's Wave 3 REC-TAX-01 behavior).
            * Manifest uses IMS Common Cartridge v1.3 namespaces.
            * Resources are nested under per-week ``<item>`` wrappers in
              the organization tree — Brightspace / Canvas / Moodle
              render a week-grouped module list instead of a flat page
              dump.

            The legacy JSON envelope (``success``, ``package_path``,
            ``libv2_package_path``, ``html_modules``, ``package_size_bytes``)
            is preserved so callers see no contract change. LO-contract
            failure surfaces as ``{"success": false, "error": ...,
            "validation_failures": [...]}`` instead of silently falling
            through.
            """
            import sys as _sys
            from pathlib import Path as _Path

            project_id = kwargs.get("project_id", "")
            project_path = courseforge_exports_dir() / project_id
            content_dir = project_path / "03_content_development"
            final_dir = project_path / "05_final_package"
            final_dir.mkdir(parents=True, exist_ok=True)

            # Sanity: require the content dir + at least one HTML page.
            html_files = sorted(content_dir.rglob("*.html"))
            if not html_files:
                return json.dumps({
                    "error": "No HTML modules found in content directory",
                    "content_dir": str(content_dir),
                })

            config_path = project_path / "project_config.json"
            course_name = project_id
            course_title = project_id
            if config_path.exists():
                try:
                    with open(config_path) as f:
                        cfg = json.load(f)
                    course_name = cfg.get("course_name", project_id)
                    course_title = (
                        cfg.get("course_title")
                        or cfg.get("title")
                        or course_name
                    )
                except (OSError, json.JSONDecodeError):
                    pass

            # Optional: caller-provided objectives JSON used by the
            # mature packager's LO-contract validator. Falls back to the
            # packager's auto-discovery (content_dir/course.json).
            objectives_path_kw = kwargs.get("objectives_path")
            objectives_path = (
                _Path(objectives_path_kw) if objectives_path_kw else None
            )
            skip_validation = bool(kwargs.get("skip_validation", False))

            # Wave2-I3 (Finding 3, plans/dispatch-7-execution-inspection-
            # 2026-05.md): emit packaging-shaped course.json from
            # synthesized_objectives.json BEFORE the mature packager + the
            # PageObjectivesValidator gate fire. Pre-fix, no phase wrote
            # course.json at the Courseforge content root, so the
            # PageObjectivesValidator (lib/validators/page_objectives.py
            # :192-249) auto-discovery hit a missing file and fail-closed
            # critical-severity with PAGE_OBJECTIVES_PATH_MISSING — blocking
            # every textbook_to_course packaging gate. Now the synthesized
            # objectives from the course_planning phase are projected to
            # the canonical packaging shape (terminal_objectives +
            # chapter_objectives + learning_outcomes[]) at the location
            # both the mature packager and the validator auto-discover.
            # Idempotent: when course.json already exists (e.g.
            # --reuse-objectives ran or a future Trainforge phase emitted
            # one), the projection logs INFO and skips without overwrite.
            synthesized_objectives_path = (
                project_path
                / "01_learning_objectives"
                / "synthesized_objectives.json"
            )
            content_course_json_path = content_dir / "course.json"
            try:
                _project_synthesized_objectives_to_course_json(
                    synthesized_objectives_path,
                    content_course_json_path,
                    course_code=course_name,
                    course_title=course_title,
                )
            except Exception as exc:  # noqa: BLE001 — best-effort projection
                logger.warning(
                    "_package_imscc: course.json projection raised %s; "
                    "packaging will continue but PageObjectivesValidator "
                    "may fail closed downstream.",
                    exc,
                )

            package_path = final_dir / f"{course_name}.imscc"
            # W3.H sub-task H3: emit a sibling packaging_report.json
            # carrying the canonical source_coverage block. Lives at
            # ``<project_root>/05_final_package/packaging_report.json``
            # (next to the .imscc archive) per plan §W3.H.
            packaging_report_path = final_dir / "packaging_report.json"

            # Import the mature packager. The module lives under
            # ``Courseforge/scripts/`` (no ``__init__.py``) so we prepend
            # the directory to ``sys.path`` before importing. Resolve the
            # directory relative to this module's real location (NOT
            # ``_PROJECT_ROOT``, which tests may monkeypatch to a tmp
            # workspace that doesn't ship the mature packager).
            cf_scripts = (
                _Path(__file__).resolve().parents[2]
                / "Courseforge" / "scripts"
            )
            if str(cf_scripts) not in _sys.path:
                _sys.path.insert(0, str(cf_scripts))
            try:
                import package_multifile_imscc as _pkg_mod  # noqa: E402
            except ImportError as exc:
                return json.dumps({
                    "success": False,
                    "error": f"Failed to import mature packager: {exc}",
                    "project_id": project_id,
                })

            # Run in an executor so the (synchronous) packager does not
            # block the event loop. SystemExit raised by the packager on
            # LO-contract failure surfaces as a ``SystemExit`` we convert
            # into a structured error response. Any other exception is
            # surfaced the same way so the caller sees a normal JSON
            # envelope rather than a crash.
            try:
                _pkg_mod.package_imscc(
                    content_dir,
                    package_path,
                    course_name,
                    course_title,
                    objectives_path=objectives_path,
                    skip_validation=skip_validation,
                    coverage_sidecar_path=packaging_report_path,
                )
            except SystemExit as exc:
                return json.dumps({
                    "success": False,
                    "error": (
                        "IMSCC packaging refused: per-week LO contract "
                        "validation failed. See logs for per-page details."
                    ),
                    "exit_code": (
                        exc.code if isinstance(exc.code, int) else 2
                    ),
                    "project_id": project_id,
                    "packaging_report_path": str(packaging_report_path)
                    if packaging_report_path.exists() else None,
                })
            except Exception as exc:  # noqa: BLE001
                logger.exception(
                    "Mature packager raised for project %s: %s",
                    project_id, exc,
                )
                return json.dumps({
                    "success": False,
                    "error": f"Mature packager failed: {exc}",
                    "project_id": project_id,
                })

            # Wave 32 Deliverable B: surface imscc_path + content_dir
            # alongside the legacy package_path / libv2_package_path
            # aliases so the IMSCCValidator + PageObjectivesValidator
            # gate builders stop reporting ``missing inputs:
            # imscc_path / content_dir``.
            return json.dumps({
                "success": True,
                "project_id": project_id,
                "package_path": str(package_path),
                "libv2_package_path": str(package_path),
                "imscc_path": str(package_path),
                "content_dir": str(content_dir),
                "html_modules": len(html_files),
                "package_size_bytes": package_path.stat().st_size,
                "packaging_report_path": str(packaging_report_path)
                if packaging_report_path.exists() else None,
            })

        registry["package_imscc"] = _package_imscc
    except ImportError:
        pass

    # Trainforge tools
    try:
        async def _analyze_imscc_content(**kwargs):
            """Registry wrapper: real IMSCC analysis (parity with @mcp.tool() variant).

            Previously a zero-value stub (audit Q4). Now opens the zip,
            validates the manifest, counts HTML modules + existing
            assessments, and suggests assessment opportunities — matching
            the MCP variant at trainforge_tools.py:129.
            """
            import zipfile

            imscc_path = kwargs.get("imscc_path", "")
            try:
                imscc = Path(imscc_path)
                if not imscc.exists():
                    return json.dumps({"error": f"IMSCC not found: {imscc_path}"})

                analysis = {
                    "source": str(imscc),
                    "analyzed_at": datetime.now().isoformat(),
                    "content": {
                        "html_modules": 0,
                        "existing_assessments": 0,
                        "total_word_count": 0,
                    },
                    "learning_objectives": [],
                    "assessment_opportunities": [],
                }

                with zipfile.ZipFile(imscc, "r") as z:
                    if "imsmanifest.xml" not in z.namelist():
                        return json.dumps({
                            "error": (
                                f"Invalid IMSCC package: missing imsmanifest.xml "
                                f"in {imscc.name}"
                            ),
                            "hint": (
                                "A valid IMSCC package must contain an "
                                "imsmanifest.xml file"
                            ),
                        })
                    analysis["has_manifest"] = True

                    for name in z.namelist():
                        if name.endswith(".html"):
                            analysis["content"]["html_modules"] += 1
                            content = z.read(name).decode("utf-8", errors="ignore")
                            word_count = len(content.split())
                            analysis["content"]["total_word_count"] += word_count
                            if "objective" in content.lower():
                                analysis["learning_objectives"].append({
                                    "source_file": name,
                                    "detected": True,
                                })
                        elif name.endswith(".xml") and "assessment" in name.lower():
                            analysis["content"]["existing_assessments"] += 1

                if analysis["content"]["html_modules"] > 0:
                    analysis["assessment_opportunities"] = [
                        {
                            "type": "quiz",
                            "coverage": "per_module",
                            "estimated_questions": (
                                analysis["content"]["html_modules"] * 5
                            ),
                        },
                        {
                            "type": "exam",
                            "coverage": "comprehensive",
                            "estimated_questions": min(
                                50, analysis["content"]["html_modules"] * 3
                            ),
                        },
                    ]

                return json.dumps(analysis)
            except Exception as e:
                return json.dumps({"error": str(e)})

        registry["analyze_imscc_content"] = _analyze_imscc_content

        # ============================================================================
        # BLOCK: Worker β edits ONLY below this line through the next END marker.
        # Scope: _generate_assessments replacement. See plans/pipeline-execution-
        # fixes/contracts.md § "Trainforge-execution contract".
        # ============================================================================
        async def _generate_assessments(**kwargs):
            """Run Trainforge's full corpus pipeline against the IMSCC and
            generate grounded assessments.

            Concrete steps:

            1. Invoke Trainforge's :class:`CourseProcessor` (the same code
               path ``python -m Trainforge.process_course`` uses) against
               the packaged IMSCC. Produces ``corpus/chunks.jsonl``,
               ``graph/concept_graph_semantic.json``, ``manifest.json``,
               and a ``quality/`` report, validating under chunk_v4 /
               typed-edge schemas when the opt-in flags are set.
            2. Aggregate inline ``chunk["misconceptions"]`` entries into
               a first-class ``graph/misconceptions.json`` document with
               content-hash IDs (``mc_[0-9a-f]{16}``), per REC-LNK-02 and
               the ``misconception.schema.json`` shape.
            3. Run :class:`AssessmentGenerator` honoring the workflow's
               ``question_count`` / ``bloom_levels`` / ``objective_ids``
               params against the generated chunks, writing a single
               well-formed ``assessments.json`` (NOT the legacy
               jsonl-then-concat pattern that produced "Extra data"
               errors).

            Output dir: ``{project_workspace}/trainforge/`` where
            ``project_workspace`` is derived from
            ``imscc_path.parent.parent`` (the Courseforge project dir)
            or, for standalone calls, from an explicit ``project_id``
            kwarg. Colocating with the Courseforge export dir keeps all
            per-run artifacts under one tree and lets the
            libv2-archival phase locate them without a cross-tree
            lookup.
            """
            import hashlib as _hashlib
            import os as _os
            import traceback as _traceback

            course_id = kwargs.get("course_id") or kwargs.get("course_code") or ""
            question_count = int(kwargs.get("question_count", 10))
            bloom_levels_str = kwargs.get("bloom_levels", "remember,understand,apply")
            objective_ids_str = kwargs.get("objective_ids", "")
            imscc_path_str = kwargs.get("imscc_path", "")
            project_id_kw = kwargs.get("project_id", "")
            domain = kwargs.get("domain") or "general"
            division = kwargs.get("division") or "STEM"
            # Phase 8 ST 2: pre-built IMSCC chunkset path threaded
            # through from the upstream ``imscc_chunking`` workflow
            # phase (Phase 7c ST 16,
            # ``MCP/tools/pipeline_tools.py::_run_imscc_chunking``).
            # When supplied + readable, ``CourseProcessor.process``
            # short-circuits its in-process ``_chunk_content`` call
            # and consumes the canonical chunks emitted upstream at
            # ``LibV2/courses/<slug>/imscc_chunks/chunks.jsonl``.
            # Falls through to the legacy in-process build path on
            # absent / unreadable upstream chunks. Routed via
            # ``config/workflows.yaml::trainforge_assessment.inputs_from``
            # + ``MCP/core/workflow_runner.py::_LEGACY_PHASE_PARAM_ROUTING``.
            imscc_chunks_path_kw = kwargs.get("imscc_chunks_path") or ""

            # LOUD kwargs receipt — a production run's Phase 8 went silent
            # after the chunkset log line with no further output; log what
            # arrived so the next silent run is diagnosable.
            logger.info(
                "generate_assessments: received kwargs course_id=%r "
                "imscc_path=%r project_id=%r imscc_chunks_path=%r "
                "question_count=%r",
                course_id, imscc_path_str, project_id_kw,
                imscc_chunks_path_kw, question_count,
            )

            # Normalize list-ish params.
            if isinstance(bloom_levels_str, list):
                bloom_levels = [str(b).strip() for b in bloom_levels_str if str(b).strip()]
            else:
                bloom_levels = [b.strip() for b in str(bloom_levels_str).split(",") if b.strip()]
            if not bloom_levels:
                bloom_levels = ["remember", "understand", "apply"]

            if isinstance(objective_ids_str, list):
                objective_ids = [str(o).strip() for o in objective_ids_str if str(o).strip()]
            else:
                objective_ids = [o.strip() for o in str(objective_ids_str).split(",") if o.strip()]
            if not objective_ids:
                objective_ids = [f"{course_id}_OBJ_{i}" for i in range(1, 7)]

            # Locate project workspace. Standard path: imscc is under
            # Courseforge/exports/<proj>/05_final_package/, so project_dir
            # is imscc.parent.parent. Explicit project_id kwarg wins if set.
            project_dir: Optional[Path] = None
            imscc_path = Path(imscc_path_str) if imscc_path_str else None
            if project_id_kw:
                candidate = courseforge_exports_dir() / project_id_kw
                if candidate.exists():
                    project_dir = candidate
            if project_dir is None and imscc_path and imscc_path.exists():
                candidate = imscc_path.parent.parent
                if candidate.exists():
                    project_dir = candidate
            if project_dir is None:
                # Last-resort fallback: most recent export dir matching course_id.
                exports_dir = courseforge_exports_dir()
                if exports_dir.exists():
                    matches = sorted(
                        (p for p in exports_dir.iterdir()
                         if p.is_dir() and course_id and course_id.lower() in p.name.lower()),
                        key=lambda p: p.stat().st_mtime,
                        reverse=True,
                    )
                    if matches:
                        project_dir = matches[0]
            if project_dir is None:
                logger.error(
                    "generate_assessments: FAILING LOUD — cannot locate "
                    "project workspace (imscc_path=%r, course_id=%r).",
                    imscc_path_str, course_id,
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_NO_PROJECT_WORKSPACE",
                    "error": "Cannot locate project workspace for Trainforge output",
                    "imscc_path": imscc_path_str,
                    "course_id": course_id,
                })

            trainforge_dir = project_dir / "trainforge"
            # Wipe any prior run's output so a retry starts clean.
            if trainforge_dir.exists():
                shutil.rmtree(trainforge_dir, ignore_errors=True)
            trainforge_dir.mkdir(parents=True, exist_ok=True)

            if not imscc_path or not imscc_path.exists() or imscc_path.stat().st_size == 0:
                logger.error(
                    "generate_assessments: FAILING LOUD — IMSCC package "
                    "not found or empty (imscc_path=%r).", imscc_path_str,
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_IMSCC_MISSING",
                    "error": "IMSCC package not found or empty; Trainforge requires the packaging phase to complete first",
                    "imscc_path": imscc_path_str,
                })

            # Invoke CourseProcessor. Writes:
            #   <trainforge_dir>/corpus/chunks.jsonl
            #   <trainforge_dir>/graph/concept_graph.json
            #   <trainforge_dir>/graph/concept_graph_semantic.json
            #   <trainforge_dir>/graph/pedagogy_graph.json
            #   <trainforge_dir>/manifest.json
            #   <trainforge_dir>/quality/quality_report.json
            try:
                from Trainforge.process_course import CourseProcessor
            except Exception as e:
                logger.error(
                    "generate_assessments: FAILING LOUD — CourseProcessor "
                    "import failed: %s", e,
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_IMPORT_FAILED",
                    "error": f"Failed to import CourseProcessor: {e}",
                    "traceback": _traceback.format_exc(limit=4),
                })

            # Wave 24: thread objectives_path through to CourseProcessor
            # so Trainforge synthesizes self.objectives, populates
            # _build_valid_outcome_ids, and writes course.json. Before
            # Wave 24 this argument was missing, so every chunk's
            # learning_outcome_refs surfaced as broken.
            project_dir_objectives = None
            try:
                cfg_path = project_dir / "project_config.json"
                if cfg_path.exists():
                    cfg_data = json.loads(cfg_path.read_text(encoding="utf-8"))
                    project_dir_objectives = (
                        cfg_data.get("synthesized_objectives_path")
                        or cfg_data.get("objectives_path")
                    )
            except (OSError, ValueError):
                project_dir_objectives = None

            # Legacy / no-textbook path: no objectives JSON. Fall back
            # to CourseProcessor's pre-Wave-24 behavior (no course.json,
            # empty valid_outcome_ids) with a single warning log so the
            # gap is observable.
            if not project_dir_objectives:
                logger.warning(
                    "[Wave 24] CourseProcessor invoked without an "
                    "objectives_path (project %s). course.json will not "
                    "be written; chunk learning_outcome_refs may surface "
                    "as broken. Run plan_course_structure first to "
                    "populate synthesized_objectives.json.",
                    project_dir.name,
                )

            processor = CourseProcessor(
                imscc_path=str(imscc_path),
                output_dir=str(trainforge_dir),
                course_code=course_id,
                division=division,
                domain=domain,
                objectives_path=(
                    str(project_dir_objectives) if project_dir_objectives else None
                ),
                strict_mode=False,
                # Phase 8 ST 2: pass through the upstream IMSCC
                # chunkset path so ``process()`` consumes it instead
                # of re-running the chunker in-process. Empty string
                # resolves to None inside the constructor (preserves
                # backward compat with callers that don't thread the
                # path).
                imscc_chunks_path=(
                    imscc_chunks_path_kw if imscc_chunks_path_kw else None
                ),
            )

            # Wave 22 DC2: the historical strict-mode override here was a
            # landmine. process_course.py now uses the canonical phase
            # name ``"trainforge-content-analysis"`` (already fixed) and
            # Wave 22 adds the five previously-orphan decision_type
            # values (assessment_planning, question_type_selection,
            # assessment_generation, content_selection, boilerplate_strip)
            # to ``schemas/events/decision_event.schema.json``. With both
            # landmines cleared, the caller's configured strictness now
            # applies uniformly across CourseProcessor + downstream
            # AssessmentGenerator runs.
            try:
                summary = processor.process()
            except Exception as e:
                logger.exception(
                    "generate_assessments: FAILING LOUD — "
                    "CourseProcessor.process() raised."
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_PROCESS_FAILED",
                    "error": f"CourseProcessor.process() failed: {e}",
                    "traceback": _traceback.format_exc(limit=6),
                    "output_dir": str(trainforge_dir),
                })

            # Phase 7c: prefer imscc_chunks/, fall back to legacy corpus/.
            from lib.libv2_storage import resolve_imscc_chunks_path
            chunks_path = resolve_imscc_chunks_path(trainforge_dir, "chunks.jsonl")
            semantic_graph_path = trainforge_dir / "graph" / "concept_graph_semantic.json"

            if not chunks_path.exists():
                logger.error(
                    "generate_assessments: FAILING LOUD — CourseProcessor "
                    "did not produce chunks.jsonl under %s.", trainforge_dir,
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_NO_CHUNKS",
                    "error": "CourseProcessor did not produce chunks.jsonl",
                    "output_dir": str(trainforge_dir),
                })

            # Aggregate first-class misconceptions.json. Pulls inline
            # misconceptions from each chunk, dedupes by content, and
            # assigns mc_<16-hex> content-hash IDs per
            # schemas/knowledge/misconception.schema.json.
            loaded_chunks: list = []
            with open(chunks_path, encoding="utf-8") as _f:
                for _line in _f:
                    _line = _line.strip()
                    if not _line:
                        continue
                    try:
                        loaded_chunks.append(json.loads(_line))
                    except (json.JSONDecodeError, ValueError):
                        continue

            # Scaffolding suppression (observed production defect): the
            # packager's own "Learning Objectives Map" navigation page chunks
            # carry objective-list boilerplate ("Supporting chapter
            # objectives (N): CO-NN — ..."); the term extractor mined them as
            # CONTENT, producing verb-less garbage MCQ stems ("Which of the
            # following best describes Supporting chapter objectives (6):
            # ..."). Filter chunks whose provenance/section names OUR OWN
            # emitted scaffolding (the sr-scaffolding-suppression precedent:
            # our navigation markup must never become assessment content).
            # Keys on the packager's own template strings
            # (render_learning_objectives_page.py), never subject vocabulary.
            def _is_packager_scaffolding_chunk(_c: dict) -> bool:
                _sec = str(((_c.get("source") or {}).get("section_heading")
                            or "")).strip()
                if "Learning Objectives Map" in _sec:
                    return True
                _head = str(_c.get("text") or "")[:120]
                return _head.startswith("Supporting chapter objectives (")

            _n_before = len(loaded_chunks)
            loaded_chunks = [
                _c for _c in loaded_chunks
                if not _is_packager_scaffolding_chunk(_c)
            ]
            if len(loaded_chunks) != _n_before:
                logger.info(
                    "generate_assessments: filtered %d packager-scaffolding "
                    "chunk(s) (Learning Objectives Map / objective-list "
                    "boilerplate) from assessment content selection.",
                    _n_before - len(loaded_chunks),
                )

            mc_entities: list = []
            mc_seen: set = set()
            for _c in loaded_chunks:
                for _mc in _c.get("misconceptions") or []:
                    if not isinstance(_mc, dict):
                        continue
                    mtext = str(_mc.get("misconception", "")).strip()
                    ctext = str(_mc.get("correction", "")).strip()
                    if not mtext:
                        continue
                    # Correction is minLength:1 under the schema. Supply
                    # a minimal placeholder when the source didn't carry
                    # one (common with regex-extracted prose).
                    if not ctext:
                        ctext = "Correction not captured in source; review instructor materials."
                    _digest = _hashlib.sha256(
                        f"{mtext}|{ctext}".encode()
                    ).hexdigest()[:16]
                    mc_id = f"mc_{_digest}"
                    if mc_id in mc_seen:
                        continue
                    mc_seen.add(mc_id)
                    entity: dict = {
                        "id": mc_id,
                        "misconception": mtext,
                        "correction": ctext,
                    }
                    tags = _c.get("concept_tags") or []
                    if isinstance(tags, list) and tags:
                        entity["concept_id"] = str(tags[0])
                    los = _c.get("learning_outcome_refs") or []
                    if isinstance(los, list) and los:
                        entity["lo_id"] = str(los[0])
                    mc_entities.append(entity)

            # Fallback: process_course.py surfaced zero misconceptions
            # but we have real chunks — try the regex extractor on chunk
            # text. Keeps the artifact shape honest while Courseforge
            # (Worker α) is still being brought online with JSON-LD
            # misconceptions.
            if not mc_entities and loaded_chunks:
                try:
                    from Trainforge.process_course import extract_misconceptions_from_text
                    for _c in loaded_chunks:
                        text = str(_c.get("text", ""))
                        for _mc in extract_misconceptions_from_text(text):
                            mtext = _mc.get("misconception", "").strip()
                            if not mtext:
                                continue
                            ctext = _mc.get("correction") or "Correction not captured in source; review instructor materials."
                            _digest = _hashlib.sha256(
                                f"{mtext}|{ctext}".encode()
                            ).hexdigest()[:16]
                            mc_id = f"mc_{_digest}"
                            if mc_id in mc_seen:
                                continue
                            mc_seen.add(mc_id)
                            mc_entities.append({
                                "id": mc_id,
                                "misconception": mtext,
                                "correction": ctext,
                            })
                        if mc_entities:
                            break
                except Exception:
                    pass

            misconceptions_path = trainforge_dir / "graph" / "misconceptions.json"
            misconceptions_path.parent.mkdir(parents=True, exist_ok=True)
            with open(misconceptions_path, "w", encoding="utf-8") as _f:
                json.dump({"misconceptions": mc_entities}, _f, indent=2, ensure_ascii=False)

            # Run AssessmentGenerator on the Trainforge chunks. Every
            # field the ContentExtractor reads (text, concept_tags,
            # source, id) is already present in the canonical chunk
            # shape. Decision capture via create_trainforge_capture
            # writes the rationale stream.
            try:
                from Trainforge.generators.assessment_generator import AssessmentGenerator
            except Exception as e:
                logger.error(
                    "generate_assessments: FAILING LOUD — "
                    "AssessmentGenerator import failed: %s", e,
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_IMPORT_FAILED",
                    "error": f"Failed to import AssessmentGenerator: {e}",
                    "traceback": _traceback.format_exc(limit=4),
                    "chunks_path": str(chunks_path),
                })

            gen_capture = None
            try:
                from lib.trainforge_capture import create_trainforge_capture
                gen_capture = create_trainforge_capture(
                    course_code=course_id or "UNKNOWN",
                    imscc_source=str(imscc_path),
                )
            except Exception:
                gen_capture = None

            # SFT-C S6 license flow-down: thread the endpoint-registry-shaped
            # teacher-license roster into the generator so the apply-arm's
            # provider license guard refuses a barred teacher. Inert by default
            # (the guard is only consulted on the opt-in apply-arm path);
            # best-effort — a missing lib.licensing leaves teacher_roster=None,
            # byte-identical to the prior construction.
            try:
                from lib.licensing import provider_verdict_roster as _pvr
                _teacher_roster = _pvr()
            except Exception:  # noqa: BLE001 — roster is best-effort
                _teacher_roster = None
            generator = AssessmentGenerator(
                capture=gen_capture, check_leaks=True,
                teacher_roster=_teacher_roster,
            )
            try:
                assessment = generator.generate(
                    course_code=course_id,
                    objective_ids=objective_ids,
                    bloom_levels=bloom_levels,
                    question_count=question_count,
                    source_chunks=loaded_chunks,
                )
            except Exception as e:
                logger.exception(
                    "generate_assessments: FAILING LOUD — "
                    "AssessmentGenerator.generate() raised."
                )
                return json.dumps({
                    "success": False,
                    "error_code": "TRAINFORGE_GENERATE_FAILED",
                    "error": f"AssessmentGenerator.generate() failed: {e}",
                    "traceback": _traceback.format_exc(limit=6),
                    "chunks_path": str(chunks_path),
                })

            assessments_path = trainforge_dir / "assessments.json"
            assessment_doc = assessment.to_dict()

            # Generation-silence contract: zero generated questions is NEVER
            # silent. The valid,
            # empty-but-parseable assessments.json is still written below
            # (downstream gates must parse it, never crash on a missing/
            # empty file), and a LOUD warning surfaces the count + the
            # skip reasons so the operator sees WHY the generator emitted
            # nothing (leak-checked / negation-unverifiable / no content).
            if not assessment.questions:
                _skips = [
                    s.to_dict() if hasattr(s, "to_dict") else s
                    for s in (getattr(assessment, "skipped_items", []) or [])
                ]
                _skip_reasons: dict = {}
                for _s in _skips:
                    _r = (_s or {}).get("reason", "unknown") if isinstance(_s, dict) else "unknown"
                    _skip_reasons[_r] = _skip_reasons.get(_r, 0) + 1
                logger.warning(
                    "generate_assessments: ZERO questions generated for "
                    "course=%r (chunks=%d, objectives=%d, skipped_items=%d, "
                    "skip_reasons=%s). Writing a valid empty "
                    "assessments.json so downstream gates parse instead of "
                    "crashing; investigate the generator inputs.",
                    course_id, len(loaded_chunks), len(objective_ids),
                    len(_skips), _skip_reasons,
                )
            # Single write, single well-formed JSON document. The legacy
            # "Extra data" bug came from calling json.dump then appending
            # additional text to the same handle; we guard against that
            # by using a fresh open() and exactly one dump call.
            with open(assessments_path, "w", encoding="utf-8") as _f:
                json.dump(assessment_doc, _f, indent=2, ensure_ascii=False)

            # Wave 26: graft the assessment dimension onto quality_report.json
            # so a reviewer can see which questions are broken without
            # re-running validators. Best-effort: on any error we preserve
            # the existing quality report unchanged.
            try:
                from Trainforge.generators.assessment_quality_report import (
                    build_assessment_dimension,
                )
                qr_path = trainforge_dir / "quality" / "quality_report.json"
                if qr_path.exists():
                    with open(qr_path, encoding="utf-8") as _qrf:
                        qr_doc = json.load(_qrf)
                    dim = build_assessment_dimension(assessment_doc)
                    if dim is not None:
                        qr_doc["assessments"] = dim
                        with open(qr_path, "w", encoding="utf-8") as _qrf:
                            json.dump(qr_doc, _qrf, indent=2, ensure_ascii=False)
            except Exception as _qr_err:
                logger.warning(
                    "Failed to graft assessment dimension onto "
                    "quality_report.json: %s", _qr_err,
                )

            if gen_capture is not None:
                try:
                    gen_capture.log_decision(
                        decision_type="content_selection",
                        decision=(
                            f"Trainforge phase wrote {len(loaded_chunks)} chunks, "
                            f"{len(mc_entities)} misconceptions, "
                            f"{len(assessment.questions)} assessment questions "
                            f"to {trainforge_dir}"
                        ),
                        rationale=(
                            "Ran CourseProcessor against the packaged IMSCC to produce the "
                            "canonical corpus + typed-edge graph, then synthesized misconception "
                            "entities with content-hash IDs. Colocated output under the Courseforge "
                            "project dir so downstream LibV2 archival can byte-copy without a "
                            "cross-tree lookup. Honored workflow params for bloom_levels "
                            f"({','.join(bloom_levels)}) and question_count ({question_count})."
                        ),
                    )
                except Exception:
                    pass

            mc_id_out = str(misconceptions_path) if mc_entities else None
            validated = (
                _os.getenv("TRAINFORGE_VALIDATE_CHUNKS", "").lower() == "true"
            )

            # Worker W1: surface skipped-item count from the killed
            # template-fallback path so the workflow phase output keeps
            # visibility on slots the generator refused to fill.
            skipped_total = len(getattr(assessment, "skipped_items", []) or [])
            skipped_summary = [
                s.to_dict() for s in (getattr(assessment, "skipped_items", []) or [])[:3]
            ]
            return json.dumps({
                "success": True,
                "assessment_id": assessment.assessment_id,
                "question_count": len(assessment.questions),
                # Generation-silence contract: surface the zero-question case
                # in the phase-output envelope, not only in the log.
                "zero_questions_warning": (
                    "generator produced ZERO questions; empty-but-parseable "
                    "assessments.json written"
                ) if not assessment.questions else None,
                "skipped_items_count": skipped_total,
                "skipped_items_summary": skipped_summary,
                "output_path": str(assessments_path),
                "assessments_path": str(assessments_path),
                "chunks_path": str(chunks_path),
                "concept_graph_path": (
                    str(semantic_graph_path) if semantic_graph_path.exists() else None
                ),
                "misconceptions_path": mc_id_out,
                "trainforge_dir": str(trainforge_dir),
                "chunks_count": len(loaded_chunks),
                "misconceptions_count": len(mc_entities),
                "strict_chunks_validated": validated,
                "processor_summary": {
                    "course_code": summary.get("course_code"),
                    "title": summary.get("title"),
                    "stats": summary.get("stats"),
                },
            })

        registry["generate_assessments"] = _generate_assessments
        # END BLOCK: Worker β
    except Exception:
        pass

    # Wave 30 Gap 3: training_synthesis phase
    # ============================================================================
    # Wraps ``Trainforge.synthesize_training.run_synthesis`` as a pipeline phase
    # so ``textbook_to_course`` runs now materialise ``training_specs/
    # instruction_pairs.jsonl`` + ``training_specs/preference_pairs.jsonl``
    # alongside ``assessments.json``. Pre-Wave-30 the synthesizer only ran
    # when a human invoked its CLI — no textbook-to-course run ever emitted
    # SFT / DPO pairs, so ``ed4all export-training ... --format dpo`` was
    # exporting decision captures instead of real Q&A pairs.
    # ============================================================================
    async def _synthesize_training(**kwargs):
        """Generate SFT + DPO training pairs from the Trainforge corpus.

        Required inputs (accepts both shapes so both the MCP-tool and
        pipeline-dispatch variants route here cleanly):

        * ``corpus_dir`` OR ``trainforge_dir`` — the Trainforge output
          directory that already holds ``corpus/chunks.jsonl``. Derived
          from ``assessments_path`` (its parent) when neither is given.
        * ``course_code`` OR ``course_name`` OR ``course_id`` — used for
          decision capture so the run is traceable.

        Optional:

        * ``provider`` — synthesis provider. Accepted values: ``"mock"``
          (default; deterministic template factory), ``"anthropic"``
          (Anthropic SDK; requires ``ANTHROPIC_API_KEY``),
          ``"claude_session"`` (Claude Code session via LocalDispatcher),
          ``"together"`` (Together AI's OpenAI-compatible endpoint;
          default model ``meta-llama/Llama-3.3-70B-Instruct-Turbo``,
          override via ``TOGETHER_SYNTHESIS_MODEL``; requires
          ``TOGETHER_API_KEY``), or ``"local"`` (a local
          OpenAI-compatible model server: Ollama / vLLM / llama.cpp /
          LM Studio. Default base URL ``http://localhost:11434/v1``,
          override via ``LOCAL_SYNTHESIS_BASE_URL``; default model
          ``qwen2.5:7b-instruct-q4_K_M``, override via
          ``LOCAL_SYNTHESIS_MODEL``; API key optional). Together's ToS
          permits training-data generation, unlike Anthropic's; the
          local provider is fully offline and ToS-free. When ``None``
          is explicitly set AND no LLM backend is resolvable, the
          function logs a skip warning and returns an empty-results
          shell rather than crashing.
        * ``seed`` (int, default ``DEFAULT_SEED`` from
          ``synthesize_training`` so re-runs are byte-identical).

        Returns a JSON string with ``instruction_pairs_path``,
        ``preference_pairs_path``, and the ``SynthesisStats`` dict.
        """
        # Resolve the corpus directory.
        corpus_dir = (
            kwargs.get("corpus_dir")
            or kwargs.get("trainforge_dir")
            or kwargs.get("output_dir")
        )
        if not corpus_dir:
            assessments_path = kwargs.get("assessments_path")
            if assessments_path:
                corpus_dir = str(Path(assessments_path).parent)
        if not corpus_dir:
            chunks_path = kwargs.get("chunks_path")
            if chunks_path:
                # chunks.jsonl lives at {corpus_dir}/corpus/chunks.jsonl, so
                # the Trainforge root is two parents up.
                corpus_dir = str(Path(chunks_path).parent.parent)
        if not corpus_dir:
            return json.dumps({
                "error": (
                    "synthesize_training requires corpus_dir / "
                    "trainforge_dir / assessments_path / chunks_path to "
                    "locate imscc_chunks/chunks.jsonl (or legacy "
                    "corpus/chunks.jsonl)"
                ),
            })

        corpus_dir_path = Path(corpus_dir)
        # Phase 7c: prefer imscc_chunks/, fall back to legacy corpus/.
        from lib.libv2_storage import resolve_imscc_chunks_path
        chunks_path = resolve_imscc_chunks_path(corpus_dir_path, "chunks.jsonl")
        if not chunks_path.exists():
            # Skip-with-warning: downstream archival can still run, we
            # just won't have new training pairs. This is the safe
            # no-LLM-available path the audit calls out.
            logger.warning(
                "synthesize_training: chunks.jsonl missing at %s; "
                "skipping training-pair synthesis. ",
                chunks_path,
            )
            return json.dumps({
                "success": True,
                "skipped": True,
                "reason": "chunks_missing",
                "corpus_dir": str(corpus_dir_path),
            })

        course_code = (
            kwargs.get("course_code")
            or kwargs.get("course_name")
            or kwargs.get("course_id")
            or "UNKNOWN"
        )

        provider = kwargs.get("provider", "mock")
        # Seed defaults to synthesize_training's DEFAULT_SEED so re-runs
        # are byte-identical. Callers can override for test determinism.
        seed = kwargs.get("seed")

        # Wave 129: forward Wave 124-127 deterministic-generator kwargs
        # so workflow-phase dispatch + external MCP clients can trigger
        # kg_metadata / violation_detection / abstention / schema_translation
        # without the CLI. Defaults mirror run_synthesis() at
        # Trainforge/synthesize_training.py:677-685.
        with_kg_metadata = bool(kwargs.get("with_kg_metadata", False))
        kg_metadata_max_pairs = int(kwargs.get("kg_metadata_max_pairs", 2000))
        with_violation_detection = bool(
            kwargs.get("with_violation_detection", False)
        )
        violation_detection_max_pairs = kwargs.get("violation_detection_max_pairs")
        with_abstention = bool(kwargs.get("with_abstention", False))
        abstention_max_pairs = int(kwargs.get("abstention_max_pairs", 1000))
        with_schema_translation = bool(
            kwargs.get("with_schema_translation", False)
        )
        schema_translation_max_pairs = int(
            kwargs.get("schema_translation_max_pairs", 50)
        )

        try:
            from Trainforge.synthesize_training import (
                DEFAULT_SEED,
                run_synthesis,
            )
        except Exception as exc:  # pragma: no cover — dependency error
            return json.dumps({
                "error": f"Failed to import synthesize_training: {exc}",
            })

        if seed is None:
            seed = DEFAULT_SEED

        try:
            stats = run_synthesis(
                corpus_dir=corpus_dir_path,
                course_code=str(course_code),
                provider=str(provider),
                seed=int(seed),
                with_kg_metadata=with_kg_metadata,
                kg_metadata_max_pairs=kg_metadata_max_pairs,
                with_violation_detection=with_violation_detection,
                violation_detection_max_pairs=violation_detection_max_pairs,
                with_abstention=with_abstention,
                abstention_max_pairs=abstention_max_pairs,
                with_schema_translation=with_schema_translation,
                schema_translation_max_pairs=schema_translation_max_pairs,
            )
        except Exception as exc:
            return json.dumps({
                "error": f"synthesize_training failed: {exc}",
                "corpus_dir": str(corpus_dir_path),
            })

        instruction_pairs_path = (
            corpus_dir_path / "training_specs" / "instruction_pairs.jsonl"
        )
        preference_pairs_path = (
            corpus_dir_path / "training_specs" / "preference_pairs.jsonl"
        )

        return json.dumps({
            "success": True,
            "corpus_dir": str(corpus_dir_path),
            "instruction_pairs_path": str(instruction_pairs_path),
            "preference_pairs_path": str(preference_pairs_path),
            "instruction_pairs_count": stats.instruction_pairs_emitted,
            "preference_pairs_count": stats.preference_pairs_emitted,
            "chunks_eligible": stats.chunks_eligible,
            "chunks_total": stats.chunks_total,
            "stats": stats.as_dict(),
        })

    registry["synthesize_training"] = _synthesize_training

    # LibV2 archival tool
    # ============================================================================
    # BLOCK: Worker γ edits ONLY below this line through the next END marker.
    # Scope: _archive_to_libv2 extension. See plans/pipeline-execution-fixes/
    # contracts.md § "LibV2-archival contract".
    # ============================================================================
    async def _archive_to_libv2(**kwargs):
        """Archive pipeline artifacts (sources + Trainforge outputs) to LibV2.

        Parity with the ``@mcp.tool()`` variant at ``pipeline_tools.py:556-726``
        (slug computation, source copying, manifest shape, feature-flag scans)
        plus Wave 15 Trainforge output copying into
        ``corpus/`` / ``graph/`` / ``training_specs/`` / ``quality/``.

        Trainforge output lookup order (first match wins):
          1. Explicit kwargs: ``project_workspace`` (str/Path), else
             ``project_id`` → ``Courseforge/exports/{project_id}/trainforge/``.
          2. Legacy ``assessment_path`` — when it points at a directory, used
             as the Trainforge output root; when it points at a file, copied
             into ``corpus/`` (preserves the MCP-tool variant's behavior so
             existing provenance-flag tests keep passing).
          3. Heuristic fallback — scan ``Courseforge/exports/*/trainforge/``
             and ``state/runs/*/trainforge/`` for the most recently modified
             ``chunks.jsonl``. Absence is not an error — features flags fall
             back to ``false`` with a warning.

        Wave 74 fail-closed gate: when ``chunks.jsonl`` is found at the
        archive destination but doesn't carry IDs from this run's
        ``course_code`` (pattern ``^{course_code_lower}_chunk_``), the
        archival call refuses to proceed and emits ``error_code =
        TRAINFORGE_OUTPUT_STALE``. This catches the case where a prior
        run's chunks under the same slug survived into a fresh archive
        (observed today: smoke_course_chunk_* IDs leaked into the
        RDF/SHACL calibration corpus archive after trainforge_assessment
        failed). When
        Trainforge was intentionally absent (no chunks file at all), the
        archival proceeds — feature flags fall back to false with a
        warning, matching the pre-Wave-74 behaviour for DART-only runs.
        """
        # Wave 74: capture run-start mtime *before* any writes. Used as a
        # cheap second guard alongside the ID-pattern check below.
        _run_start_ts = time.time()

        course_name = (
            kwargs.get("course_name")
            or kwargs.get("course_id")
            or kwargs.get("id")
            or ""
        )
        domain = kwargs.get("domain") or "general"
        division = kwargs.get("division", "STEM")
        pdf_paths_str = kwargs.get("pdf_paths", "") or ""
        html_paths_str = kwargs.get("html_paths", "") or ""
        imscc_path_str = kwargs.get("imscc_path", "") or ""
        assessment_path_str = kwargs.get("assessment_path", "") or ""
        subdomains_str = kwargs.get("subdomains", "") or ""
        project_workspace_kw = kwargs.get("project_workspace") or ""
        project_id_kw = kwargs.get("project_id") or ""
        # Phase 6 ST 18: concept-graph hash threaded from the
        # ``concept_extraction`` phase output via the workflow runner's
        # ``inputs_from`` chain. Optional — when absent we fall back to
        # recomputing from ``concept_graph/concept_graph_semantic.json``
        # on disk under the LibV2 course dir (Worker C-J's helper writes
        # the file there at ST 12), and finally to ``None`` when no graph
        # exists (legacy / DART-only runs). Schema field is optional in
        # Phase 6 (Wave 6-D); the manifest validator is permissive (warning
        # severity) until Phase 7c promotes to critical.
        concept_graph_sha256_kw = kwargs.get("concept_graph_sha256") or ""
        # Phase 7c.5 SHIPPING BLOCKER: chunkset hashes threaded from the
        # ``chunking`` (DART) and ``imscc_chunking`` phase outputs via
        # the workflow runner's ``inputs_from`` chain. Phase 7c ST 17
        # promoted both fields to required at the validator boundary;
        # without this kwarg plumbing, every end-to-end ``ed4all run``
        # would fail validation at the ``libv2_archival`` gate. Mirrors
        # the ``concept_graph_sha256`` pattern above (Phase 6 ST 18).
        # Optional in legacy callers (no chunking phase wired) — None
        # falls through to the validator's ``MISSING_*`` critical.
        dart_chunks_sha256_kw = kwargs.get("dart_chunks_sha256") or ""
        imscc_chunks_sha256_kw = kwargs.get("imscc_chunks_sha256") or ""
        # Issue I1 (imscc_chunks archivist stale-overwrite integrity fix):
        # explicit chunkset PATHS threaded from the ``imscc_chunking`` /
        # ``chunking`` phase outputs via the workflow runner's
        # ``inputs_from`` chain. Two-pass runs write the fresh IMSCC
        # chunkset DIRECTLY to ``LibV2/courses/<slug>/imscc_chunks/`` (via
        # ``_run_imscc_chunking``), NOT into an export ``trainforge/`` dir,
        # so the mtime-driven heuristic fallback below would otherwise
        # pick a STALE same-course ``chunks.jsonl`` from a prior run's
        # export and ``shutil.copy2`` it over the fresh LibV2 file. When
        # this kwarg resolves to an existing file we point the chunks copy
        # source at THAT exact file and bypass the mtime heuristic. Absent
        # (legacy DART-only / external MCP callers) → no-op.
        imscc_chunks_path_kw = kwargs.get("imscc_chunks_path") or ""
        dart_chunks_path_kw = kwargs.get("dart_chunks_path") or ""
        # Objectives plumbing: explicit path to the course_planning-emitted
        # synthesized_objectives.json. When unset, resolved below from the
        # project export (sibling of trainforge_dir). Drives the canonical
        # archive-side objectives.json projection that the strict
        # packet-integrity gate's co_has_parent rule depends on.
        synthesized_objectives_path_kw = (
            kwargs.get("synthesized_objectives_path") or ""
        )
        # B3: optional license/attribution declarations threaded from the
        # ``--license-note`` / ``--attribution`` run flags via the
        # ``libv2_archival`` inputs_from routing. Both default absent — when
        # neither is present the manifest + course dir are byte-identical to
        # the pre-B3 layout (no ``license``/``attribution`` field, no NOTICE).
        license_field = _normalize_license_field(kwargs.get("license_note"))
        attribution_field = _normalize_attribution_field(
            kwargs.get("attribution")
        )

        if not course_name:
            return json.dumps({"error": "archive_to_libv2 requires course_name"})

        # W0.4: canonical archive-directory slug (single source of truth used by
        # the LibV2 importer) — see the parity note at the ``archive_to_libv2``
        # MCP-tool variant above.
        from lib.ontology.slugs import libv2_course_slug as _libv2_course_slug  # noqa: PLC0415
        slug = _libv2_course_slug(course_name)
        libv2_root = PROJECT_ROOT / "LibV2"
        course_dir = libv2_root / "courses" / slug

        for subdir in [
            "source/pdf", "source/html", "source/imscc",
            "corpus", "graph", "pedagogy", "training_specs", "quality"
        ]:
            (course_dir / subdir).mkdir(parents=True, exist_ok=True)

        archived = {
            "pdfs": [],
            "html": [],
            "imscc": None,
            "assessment": None,
            "objectives": None,
            "trainforge": {
                "chunks": None,
                "graph": None,
                "misconceptions": None,
                "assessments": None,
                "quality_report": None,
            },
        }

        # W2.3: opt-in fail-closed for the objectives->course.json archival
        # plumbing. Default OFF (parse-with-fallback: only the explicit truthy
        # tokens flip it on) preserves the historical best-effort behaviour;
        # when set, a no-op objectives projection refuses to write the manifest
        # (see the COURSE_JSON_OBJECTIVES_MISSING block below).
        _require_archived_objectives = (
            os.environ.get("ED4ALL_REQUIRE_ARCHIVED_OBJECTIVES", "")
            .strip().lower() in {"1", "true", "yes", "on"}
        )

        # --- Copy raw PDFs -------------------------------------------------
        if pdf_paths_str:
            for p in pdf_paths_str.split(","):
                src = Path(p.strip())
                if src.exists():
                    dest = course_dir / "source" / "pdf" / src.name
                    shutil.copy2(src, dest)
                    archived["pdfs"].append(str(dest))

        # --- Copy DART HTML outputs (+ adjacent .quality.json) -------------
        if html_paths_str:
            for p in html_paths_str.split(","):
                src = Path(p.strip())
                if src.exists():
                    dest = course_dir / "source" / "html" / src.name
                    shutil.copy2(src, dest)
                    archived["html"].append(str(dest))
                    quality_json = src.with_suffix(".quality.json")
                    if quality_json.exists():
                        shutil.copy2(
                            quality_json, course_dir / "quality" / quality_json.name
                        )
                    # Wave 19 (hotfix): archive ``{stem}_figures/`` sibling
                    # so orchestrated / CLI runs keep figure image refs
                    # intact. Mirrors the @mcp.tool() variant at L645.
                    figures_dir_src = src.parent / f"{src.stem}_figures"
                    if figures_dir_src.is_dir():
                        figures_dir_dest = (
                            course_dir / "source" / "html" / figures_dir_src.name
                        )
                        if figures_dir_dest.exists():
                            shutil.rmtree(figures_dir_dest)
                        shutil.copytree(figures_dir_src, figures_dir_dest)

        # --- Copy IMSCC package -------------------------------------------
        if imscc_path_str:
            src = Path(imscc_path_str)
            if src.exists():
                dest = course_dir / "source" / "imscc" / src.name
                shutil.copy2(src, dest)
                archived["imscc"] = str(dest)

        # --- Resolve Trainforge workspace ---------------------------------
        trainforge_dir: Optional[Path] = None

        if project_workspace_kw:
            candidate = Path(project_workspace_kw)
            if candidate.name != "trainforge":
                candidate = candidate / "trainforge"
            if candidate.exists() and candidate.is_dir():
                trainforge_dir = candidate

        if trainforge_dir is None and project_id_kw:
            candidate = (
                courseforge_exports_dir() / project_id_kw / "trainforge"
            )
            if candidate.exists() and candidate.is_dir():
                trainforge_dir = candidate

        # Legacy assessment_path handling: keep parity with the MCP-tool
        # variant so existing provenance / evidence flag tests pass
        # (they pass assessment_path=<chunks.jsonl>). If the path points at
        # a directory, treat it as the trainforge workspace root.
        if assessment_path_str:
            ap = Path(assessment_path_str)
            if ap.exists():
                if ap.is_dir():
                    if trainforge_dir is None:
                        trainforge_dir = ap
                else:
                    # Phase 7c: write to imscc_chunks/ (canonical).
                    dest = course_dir / "imscc_chunks" / ap.name
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(ap, dest)
                    archived["assessment"] = str(dest)

        # Issue I1: resolve an EXPLICIT chunks copy source from the routed
        # ``imscc_chunks_path`` / ``dart_chunks_path`` kwargs. When either
        # points at a real on-disk file, it pins the chunks copy source
        # exactly — bypassing the mtime-driven heuristic fallback below,
        # which on ``--resume`` two-pass runs can otherwise pick a STALE
        # same-course ``chunks.jsonl`` from a prior export. The IMSCC
        # chunkset is preferred (it is the archive's canonical chunkset);
        # the DART chunkset is the fallback. Absent → no-op (the legacy
        # trainforge_dir resolution + heuristic still run).
        _explicit_chunks_src: Optional[Path] = None
        for _cand_str in (imscc_chunks_path_kw, dart_chunks_path_kw):
            if not _cand_str:
                continue
            _cand = Path(_cand_str)
            if _cand.exists() and _cand.is_file():
                _explicit_chunks_src = _cand
                break

        # Heuristic fallback: scan well-known locations for chunks.jsonl.
        # Phase 7c: imscc_chunks/ is canonical; corpus/ retained for back-compat.
        # Skipped when an explicit chunks source was routed in (Issue I1):
        # the heuristic only exists to LOCATE chunks when no path is known,
        # and it is exactly the mtime-staleness vector we are closing.
        if trainforge_dir is None and _explicit_chunks_src is None:
            candidates: list[Path] = []
            exports_root = courseforge_exports_dir()
            if exports_root.exists():
                for project_dir in exports_root.iterdir():
                    if not project_dir.is_dir():
                        continue
                    tf = project_dir / "trainforge"
                    if (
                        (tf / "chunks.jsonl").exists()
                        or (tf / "imscc_chunks" / "chunks.jsonl").exists()
                        or (tf / "corpus" / "chunks.jsonl").exists()
                    ):
                        candidates.append(tf)
            runs_root = PROJECT_ROOT / "state" / "runs"
            if runs_root.exists():
                for run_dir in runs_root.iterdir():
                    if not run_dir.is_dir():
                        continue
                    tf = run_dir / "trainforge"
                    if (
                        (tf / "chunks.jsonl").exists()
                        or (tf / "imscc_chunks" / "chunks.jsonl").exists()
                        or (tf / "corpus" / "chunks.jsonl").exists()
                    ):
                        candidates.append(tf)
            if candidates:
                def _chunks_mtime(p):
                    # Support flat, new (imscc_chunks/) and legacy (corpus/) layouts.
                    new_nested = p / "imscc_chunks" / "chunks.jsonl"
                    legacy_nested = p / "corpus" / "chunks.jsonl"
                    flat = p / "chunks.jsonl"
                    if new_nested.exists():
                        return new_nested.stat().st_mtime
                    if legacy_nested.exists():
                        return legacy_nested.stat().st_mtime
                    if flat.exists():
                        return flat.stat().st_mtime
                    return 0.0
                trainforge_dir = max(candidates, key=_chunks_mtime)

        # --- Copy Courseforge assessment_synthesis artifacts --------------
        # Q4: the pre-packaging ``assessment_synthesis`` (W10) phase writes
        # loose QTI 1.2 / imsdt / assignment XML + ``manifest.json`` into
        # ``<export>/06_assessments/``. Copy that dir into the LibV2 course
        # so the learner-facing quiz surface
        # (``gui/services/quiz_service.py`` scans
        # ``LibV2/courses/<slug>/06_assessments/*.xml``) can resolve them.
        # Resolve the export dir from project_workspace / project_id /
        # trainforge_dir.parent (first with a real 06_assessments/ wins).
        # Absent (assessments skipped / not run) → no-op, never a failure.
        _export_dir_candidates: list[Path] = []
        if project_workspace_kw:
            _pw = Path(project_workspace_kw)
            _export_dir_candidates.append(
                _pw.parent if _pw.name == "trainforge" else _pw
            )
        if project_id_kw:
            _export_dir_candidates.append(
                courseforge_exports_dir() / project_id_kw
            )
        if trainforge_dir is not None:
            _export_dir_candidates.append(trainforge_dir.parent)
        _copied_assessments = _copy_export_assessments(
            _export_dir_candidates, course_dir,
        )
        if _copied_assessments:
            archived["assessments_dir"] = str(course_dir / "06_assessments")
            logger.info(
                "archive_to_libv2: copied %d assessment artifact(s) into %s",
                _copied_assessments, course_dir / "06_assessments",
            )

        # --- Copy Trainforge outputs --------------------------------------
        # Worker β writes in CourseProcessor's native nested layout
        # (trainforge/imscc_chunks/chunks.jsonl post-Phase-7c, or legacy
        # trainforge/corpus/chunks.jsonl, plus trainforge/graph/*.json).
        # We also check the flat layout for backward-compat with any
        # caller that mirrors the older stub's expected paths.
        def _pick(*candidates):
            for c in candidates:
                if c.exists() and c.is_file():
                    return c
            return None

        # Wave 74 fail-closed: never silently preserve a prior run's
        # chunks.jsonl under the same slug. If the destination already
        # exists, drop it before the copy block so we either install
        # fresh chunks below or end up with no chunks file (which is
        # the correct state for DART-only / Trainforge-skipped runs).
        # Phase 7c: clean BOTH the new imscc_chunks/ path AND the legacy
        # corpus/ path so a re-run on a partially-migrated archive
        # doesn't leave stale chunks behind in either location.
        _dest_chunks_path = course_dir / "imscc_chunks" / "chunks.jsonl"
        _legacy_dest_chunks_path = course_dir / "corpus" / "chunks.jsonl"
        _had_prior_chunks = (
            _dest_chunks_path.exists() or _legacy_dest_chunks_path.exists()
        )
        # Issue I1: when the routed explicit chunks source IS the LibV2
        # destination file (the two-pass case where ``_run_imscc_chunking``
        # wrote the fresh chunkset directly under
        # ``LibV2/courses/<slug>/imscc_chunks/``), we MUST NOT delete it —
        # it is the fresh chunkset we want to keep, not a stale prior-run
        # leftover. Resolve identity by ``samefile`` so symlink / relative
        # path differences don't defeat the guard.
        def _is_explicit_src(p: Path) -> bool:
            if _explicit_chunks_src is None:
                return False
            try:
                return p.exists() and p.samefile(_explicit_chunks_src)
            except OSError:
                return False

        for _stale in (_dest_chunks_path, _legacy_dest_chunks_path):
            if _stale.exists() and not _is_explicit_src(_stale):
                try:
                    _stale.unlink()
                except OSError as _exc:
                    logger.warning(
                        "archive_to_libv2: failed to remove prior-run "
                        "chunks.jsonl at %s: %s",
                        _stale,
                        _exc,
                    )

        # Issue I1: when an explicit chunks source was routed in, copy it
        # to the canonical LibV2 destination directly (bypassing the
        # mtime heuristic + trainforge_dir resolution for the chunks
        # artifact). If the source already IS the destination, this is a
        # no-op copy we skip. The non-chunks Trainforge artifacts (graph,
        # assessments, etc.) still come from ``trainforge_dir`` below.
        if _explicit_chunks_src is not None:
            try:
                if not _is_explicit_src(_dest_chunks_path):
                    _dest_chunks_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(_explicit_chunks_src, _dest_chunks_path)
                archived["trainforge"]["chunks"] = str(_dest_chunks_path)
            except OSError as _exc:
                logger.warning(
                    "archive_to_libv2: failed to copy routed chunks %s -> "
                    "%s: %s",
                    _explicit_chunks_src,
                    _dest_chunks_path,
                    _exc,
                )

        if trainforge_dir is not None and trainforge_dir.exists():
            copy_map = [
                # Phase 7c: prefer imscc_chunks/ in source AND destination.
                # Issue I1: when an explicit chunks source was routed in and
                # already installed above, DON'T let the trainforge_dir's
                # (possibly stale) chunks.jsonl overwrite the fresh copy.
                *([] if _explicit_chunks_src is not None else [
                    (_pick(trainforge_dir / "imscc_chunks" / "chunks.jsonl",
                           trainforge_dir / "corpus" / "chunks.jsonl",
                           trainforge_dir / "chunks.jsonl"),
                     course_dir / "imscc_chunks" / "chunks.jsonl", "chunks"),
                ]),
                (_pick(trainforge_dir / "graph" / "concept_graph_semantic.json",
                       trainforge_dir / "concept_graph_semantic.json"),
                 course_dir / "graph" / "concept_graph_semantic.json", "graph"),
                (_pick(trainforge_dir / "graph" / "misconceptions.json",
                       trainforge_dir / "misconceptions.json"),
                 course_dir / "graph" / "misconceptions.json", "misconceptions"),
                (_pick(trainforge_dir / "training_specs" / "assessments.json",
                       trainforge_dir / "assessments.json"),
                 course_dir / "training_specs" / "assessments.json", "assessments"),
                # Wave 30 Gap 3: new training_synthesis phase outputs.
                # These land under training_specs/ alongside assessments.json
                # so LibV2 archives + downstream export tooling have real
                # instruction + preference pairs to surface.
                (_pick(trainforge_dir / "training_specs" / "instruction_pairs.jsonl"),
                 course_dir / "training_specs" / "instruction_pairs.jsonl", "instruction_pairs"),
                (_pick(trainforge_dir / "training_specs" / "preference_pairs.jsonl"),
                 course_dir / "training_specs" / "preference_pairs.jsonl", "preference_pairs"),
                (_pick(trainforge_dir / "training_specs" / "dataset_config.json"),
                 course_dir / "training_specs" / "dataset_config.json", "dataset_config"),
                # Wave 30 Gap 4: course.json is now written unconditionally
                # (including an empty-LOs shell) so LibV2 retrieval + joins
                # always have a file to look at.
                (_pick(trainforge_dir / "course.json"),
                 course_dir / "course.json", "course_json"),
                (_pick(trainforge_dir / "quality" / "quality_report.json"),
                 course_dir / "quality" / "quality_report.json", "quality_report"),
            ]
            for src, dest, label in copy_map:
                if src is not None and src.exists() and src.is_file():
                    try:
                        dest.parent.mkdir(parents=True, exist_ok=True)
                        shutil.copy2(src, dest)
                        archived["trainforge"][label] = str(dest)
                    except OSError as exc:
                        logger.warning(
                            f"archive_to_libv2: failed to copy {src} -> {dest}: {exc}"
                        )
        else:
            logger.warning(
                "archive_to_libv2: no Trainforge output dir located for "
                f"course {course_name} — features flags will default to false."
            )

        # SFT-D B3/B4: normalize course_dir/graph/ so training provenance +
        # HoldoutBuilder + LibV2 retrieval all find the graphs. The modern
        # concept_extraction phase writes concept_graph_semantic.json under
        # concept_graph/ (not graph/) and never emits pedagogy_graph.json;
        # this deterministically (no LLM) copies the concept graph into
        # graph/ and re-emits pedagogy_graph.json from the chunkset. Idempotent
        # + fail-soft: a course already carrying both artifacts is untouched.
        try:
            from Trainforge.training.graph_layout import ensure_graph_layout

            _graph_report = ensure_graph_layout(course_dir)
            if _graph_report.get("concept_graph_copied") or _graph_report.get(
                "pedagogy_graph_emitted"
            ):
                logger.info(
                    "archive_to_libv2: graph-layout normalized for %s "
                    "(concept_graph_copied=%s, pedagogy_graph_emitted=%s).",
                    slug,
                    _graph_report.get("concept_graph_copied"),
                    _graph_report.get("pedagogy_graph_emitted"),
                )
        except Exception as _graph_exc:  # noqa: BLE001 - best-effort normalize
            logger.warning(
                "archive_to_libv2: graph-layout normalization failed for %s "
                "(%s); continuing.", slug, _graph_exc,
            )

        # --- Objectives plumbing: emit canonical objectives.json ----------
        # The strict packet_integrity gate's _load_objectives reads
        # archive_root / "objectives.json" FIRST (with course.json fallback),
        # and its co_has_parent rule requires every CO to carry a
        # parent_terminal resolving to a TO. The Trainforge-flattened
        # course.json drops that back-pointer, so a pipeline-built archive
        # without an objectives.json fails the gate with one
        # ORPHAN_COMPONENT_OBJECTIVE per CO. Project the canonical Worker-A
        # objectives.json from the course_planning-emitted
        # synthesized_objectives.json (which carries terminal_id per CO),
        # restoring parent_terminal via the canonical CO→TO resolver.
        # Best-effort: a missing / unparseable synthesized file logs a
        # warning and leaves the gate to fall back to course.json (no crash).
        _objectives_src: Optional[Path] = None
        if synthesized_objectives_path_kw:
            _cand = Path(synthesized_objectives_path_kw)
            if _cand.exists() and _cand.is_file():
                _objectives_src = _cand
        if _objectives_src is None:
            # Resolve from the project export. trainforge_dir is
            # <export>/trainforge/, so the synthesized objectives live at
            # <export>/01_learning_objectives/synthesized_objectives.json.
            _export_roots: list[Path] = []
            if trainforge_dir is not None:
                _export_roots.append(trainforge_dir.parent)
            if project_workspace_kw:
                _pw = Path(project_workspace_kw)
                _export_roots.append(
                    _pw.parent if _pw.name == "trainforge" else _pw
                )
            if project_id_kw:
                _export_roots.append(
                    courseforge_exports_dir() / project_id_kw
                )
            for _root in _export_roots:
                _cand = (
                    _root / "01_learning_objectives"
                    / "synthesized_objectives.json"
                )
                if _cand.exists() and _cand.is_file():
                    _objectives_src = _cand
                    break

        # W2.3: track the objectives-plumbing outcome so a silent no-op is
        # surfaced (not swallowed). The projection can no-op three ways — the
        # synthesized source never resolves (path mismatch), the projection
        # raises, or it yields an EMPTY objectives doc — and historically no
        # gate noticed because the packet-integrity validator then falls back
        # to the parent-less course.json. Each no-op now emits the distinct
        # COURSE_JSON_OBJECTIVES_MISSING code.
        _objectives_status = "archived"
        _objectives_detail = ""
        _obj_terminal_n = 0
        _obj_component_n = 0
        if _objectives_src is not None:
            try:
                from lib.libv2_storage import (
                    OBJECTIVES_ARCHIVE_FILENAME,
                    project_objectives_for_archive,
                )
                _synth = json.loads(
                    _objectives_src.read_text(encoding="utf-8")
                )
                _objectives = project_objectives_for_archive(_synth)
                _obj_terminal_n = len(
                    _objectives.get("terminal_outcomes", [])
                )
                _obj_component_n = len(
                    _objectives.get("component_objectives", [])
                )
                if _obj_terminal_n == 0 and _obj_component_n == 0:
                    # Projection ran but produced nothing archivable — a
                    # silent no-op that historically wrote an empty
                    # objectives.json and let the gate fall back to
                    # course.json. Refuse to paper over it: do NOT write an
                    # empty objectives.json.
                    _objectives_status = "empty"
                    _objectives_detail = (
                        f"projection of {_objectives_src} yielded zero "
                        f"terminal_outcomes and zero component_objectives"
                    )
                    logger.warning(
                        "archive_to_libv2: %s "
                        "(COURSE_JSON_OBJECTIVES_MISSING); the packet-"
                        "integrity gate would fall back to the (parent-less) "
                        "course.json.",
                        _objectives_detail,
                    )
                else:
                    _obj_dest = course_dir / OBJECTIVES_ARCHIVE_FILENAME
                    _obj_dest.write_text(
                        json.dumps(
                            _objectives, indent=2, ensure_ascii=False
                        ),
                        encoding="utf-8",
                    )
                    archived["objectives"] = str(_obj_dest)
                    logger.info(
                        "archive_to_libv2: projected %s -> %s "
                        "(%d terminal_outcomes + %d component_objectives).",
                        _objectives_src,
                        _obj_dest,
                        _obj_terminal_n,
                        _obj_component_n,
                    )
            except (OSError, ValueError) as _exc:
                _objectives_status = "projection_failed"
                _objectives_detail = (
                    f"failed to project {_objectives_src}: {_exc}"
                )
                logger.warning(
                    "archive_to_libv2: failed to project objectives.json "
                    "from %s (%s) (COURSE_JSON_OBJECTIVES_MISSING); "
                    "packet-integrity gate will fall back to course.json.",
                    _objectives_src, _exc,
                )
        else:
            _objectives_status = "missing_source"
            _objectives_detail = (
                f"no synthesized_objectives.json located for course "
                f"{course_name}"
            )
            logger.warning(
                "archive_to_libv2: %s (COURSE_JSON_OBJECTIVES_MISSING) — "
                "archive will lack objectives.json; the packet-integrity "
                "gate falls back to the (parent-less) course.json "
                "learning_outcomes.",
                _objectives_detail,
            )

        # W2.3: distinct warning surfaced on the return envelope + a
        # DecisionCapture on every archival-objectives decision (replayable,
        # dynamic rationale). Capture failure must never break archival.
        _archival_warnings: List[Dict[str, Any]] = []
        if _objectives_status != "archived":
            _archival_warnings.append({
                "code": "COURSE_JSON_OBJECTIVES_MISSING",
                "status": _objectives_status,
                "detail": _objectives_detail,
            })
        try:
            from lib.decision_capture import (
                DecisionCapture as _DecisionCapture,  # noqa: PLC0415
            )
            _obj_capture = _DecisionCapture(
                course_code=course_name,
                phase="libv2_archival",
                tool="pipeline",
            )
            _obj_capture.log_decision(
                decision_type="archival_objectives_projection",
                decision=f"objectives_status={_objectives_status}",
                rationale=(
                    f"archive_to_libv2 objectives plumbing for course "
                    f"{course_name}: status={_objectives_status}, "
                    f"source="
                    f"{_objectives_src if _objectives_src else 'unresolved'}, "
                    f"terminal_outcomes={_obj_terminal_n}, "
                    f"component_objectives={_obj_component_n}, "
                    f"require_archived_objectives="
                    f"{_require_archived_objectives}, "
                    f"detail={_objectives_detail or 'ok'}."
                ),
            )
        except Exception as _cap_exc:  # noqa: BLE001 — capture must not break archival
            logger.debug(
                "archival_objectives_projection decision capture failed: %s",
                _cap_exc,
            )

        # W2.3 opt-in fail-closed: when the plumbing no-op'd AND the operator
        # set ED4ALL_REQUIRE_ARCHIVED_OBJECTIVES, refuse to write the manifest
        # (mirrors the TRAINFORGE_OUTPUT_STALE fail-closed posture). Default
        # OFF keeps the historical best-effort behaviour.
        if _objectives_status != "archived" and _require_archived_objectives:
            logger.error(
                "archive_to_libv2: refusing to write manifest — objectives "
                "plumbing no-op'd (%s) for course %s and "
                "ED4ALL_REQUIRE_ARCHIVED_OBJECTIVES is set.",
                _objectives_status, course_name,
            )
            return json.dumps({
                "success": False,
                "error": (
                    f"objectives.json was not archived ({_objectives_detail}); "
                    f"the packet-integrity gate would fall back to the "
                    f"parent-less course.json"
                ),
                "error_code": "COURSE_JSON_OBJECTIVES_MISSING",
                "objectives_status": _objectives_status,
                "course_name": course_name,
                "course_slug": slug,
            })

        # --- Wave 74 fail-closed: chunks-freshness gate -------------------
        # When a chunks.jsonl exists at the archive destination, it MUST
        # carry IDs from this run's course_code. Otherwise we caught a
        # leak from a prior run under the same slug — refuse to write
        # the manifest and surface ``error_code = TRAINFORGE_OUTPUT_STALE``
        # to the caller. When the destination has no chunks file (the
        # Trainforge-intentionally-absent case — e.g. DART-only batches
        # gated by ``--no-assessments``), this check is a no-op.
        _chunks_check = _check_chunks_freshness(
            chunks_path=_dest_chunks_path,
            course_name=course_name,
            run_start_ts=_run_start_ts,
            had_prior_chunks=_had_prior_chunks,
        )
        if _chunks_check["status"] == "stale":
            logger.error(
                "archive_to_libv2: refusing to write manifest — "
                "chunks.jsonl at %s is stale for course %s (%s).",
                _dest_chunks_path,
                course_name,
                _chunks_check["reason"],
            )
            return json.dumps({
                "success": False,
                "error": _chunks_check["reason"],
                "error_code": "TRAINFORGE_OUTPUT_STALE",
                "course_name": course_name,
                "chunks_path": str(_dest_chunks_path),
                "expected_prefix": _chunks_check.get("expected_prefix"),
                "observed_prefixes": _chunks_check.get("observed_prefixes"),
            })

        # --- Issue I1 defense-in-depth: chunks SHA-drift gate -------------
        # The top-level manifest's ``imscc_chunks_sha256`` comes from the
        # routed phase-output kwarg (computed by ``_run_imscc_chunking``
        # over the FRESH chunkset), NOT re-hashed from the on-disk archive
        # file. The original bug let the on-disk file diverge from that sha
        # (a stale heuristic copy overwrote the fresh file while the
        # manifest still advertised the fresh sha). Here, when the kwarg is
        # well-formed AND a chunks.jsonl was actually installed at the
        # destination this run, we RE-HASH the dest file and FAIL CLOSED
        # (no manifest written) if it disagrees with the advertised sha.
        # Absent chunks / absent sha kwarg → no-op (legacy DART-only runs).
        import re as _re_drift
        import hashlib as _hashlib_drift

        def _sha256_file(filepath: Path) -> str:
            h = _hashlib_drift.sha256()
            with open(filepath, "rb") as fh:
                for block in iter(lambda: fh.read(8192), b""):
                    h.update(block)
            return h.hexdigest()

        _chunks_copied_this_run = (
            _explicit_chunks_src is not None
            or archived["trainforge"].get("chunks") is not None
        )
        if (
            _chunks_copied_this_run
            and imscc_chunks_sha256_kw
            and _re_drift.match(r"^[0-9a-f]{64}$", imscc_chunks_sha256_kw)
            and _dest_chunks_path.exists()
            and _dest_chunks_path.is_file()
        ):
            _on_disk_sha = _sha256_file(_dest_chunks_path)
            if _on_disk_sha != imscc_chunks_sha256_kw:
                logger.error(
                    "archive_to_libv2: refusing to write manifest — "
                    "imscc_chunks SHA drift for course %s: on-disk %s != "
                    "advertised %s at %s.",
                    course_name,
                    _on_disk_sha,
                    imscc_chunks_sha256_kw,
                    _dest_chunks_path,
                )
                return json.dumps({
                    "success": False,
                    "error": (
                        "imscc_chunks.jsonl on-disk SHA-256 does not match "
                        "the advertised imscc_chunks_sha256 — refusing to "
                        "write a manifest whose chunkset hash diverges from "
                        "the archived file (stale-overwrite integrity gate)."
                    ),
                    "error_code": "IMSCC_CHUNKS_SHA_DRIFT",
                    "course_name": course_name,
                    "chunks_path": str(_dest_chunks_path),
                    "expected_sha256": imscc_chunks_sha256_kw,
                    "observed_sha256": _on_disk_sha,
                })

        # --- Build manifest (with source_artifacts checksums) -------------
        import hashlib

        def _sha256(filepath: Path) -> str:
            h = hashlib.sha256()
            with open(filepath, "rb") as f:
                for block in iter(lambda: f.read(8192), b""):
                    h.update(block)
            return h.hexdigest()

        source_artifacts: dict = {}
        if archived["pdfs"]:
            source_artifacts["pdf"] = [
                {"path": p, "checksum": _sha256(Path(p)), "size": Path(p).stat().st_size}
                for p in archived["pdfs"]
            ]
        if archived["html"]:
            source_artifacts["html"] = [
                {"path": p, "checksum": _sha256(Path(p)), "size": Path(p).stat().st_size}
                for p in archived["html"]
            ]
        if archived["imscc"]:
            imscc_p = Path(archived["imscc"])
            source_artifacts["imscc"] = {
                "path": archived["imscc"],
                "checksum": _sha256(imscc_p),
                "size": imscc_p.stat().st_size,
            }

        # Wave 10 / Wave 11 feature flags — scan the archived files.
        source_provenance_flag = _detect_source_provenance(course_dir)
        evidence_source_provenance_flag = _detect_evidence_source_provenance(course_dir)

        # Phase 6 ST 18: resolve concept_graph_sha256 (per plan §D).
        # Resolution order:
        #   1. Explicit kwarg (workflow runner threads via inputs_from).
        #   2. Recompute from on-disk concept_graph_semantic.json under the
        #      LibV2 course's concept_graph/ subdir (Worker C-J's
        #      _run_concept_extraction writes here at ST 12).
        #   3. None — legacy archive without a concept graph (warning gate
        #      handles this in libv2_manifest validator).
        import re as _re_cg
        concept_graph_sha256_resolved: Optional[str] = None
        if concept_graph_sha256_kw and _re_cg.match(
            r"^[0-9a-f]{64}$", concept_graph_sha256_kw,
        ):
            concept_graph_sha256_resolved = concept_graph_sha256_kw
        else:
            cg_path = (
                course_dir / "concept_graph" / "concept_graph_semantic.json"
            )
            if cg_path.exists() and cg_path.is_file():
                try:
                    concept_graph_sha256_resolved = hashlib.sha256(
                        cg_path.read_bytes()
                    ).hexdigest()
                except OSError as exc:
                    logger.warning(
                        "archive_to_libv2: failed to hash concept graph "
                        "at %s: %s",
                        cg_path,
                        exc,
                    )

        manifest = {
            "libv2_version": "1.2.0",
            # OP4: stamp the on-disk course-layout contract version so
            # fsck/validators can serve an old-format course read-only + warn
            # (never silent) instead of assuming the current layout. See
            # docs/operations/library-versioning.md for the upgrade contract.
            "library_format_version": LIBRARY_FORMAT_VERSION,
            "chunker_version": _resolve_chunker_version(),
            # Chunk-TEXT extraction-contract version (orthogonal to
            # chunker_version) so a fully-archived corpus carries the same
            # provenance marker as its chunkset sidecars.
            "extraction_contract": _resolve_extraction_contract(),
            "slug": slug,
            "import_timestamp": datetime.now().isoformat(),
            "classification": {
                "division": division,
                "primary_domain": domain,
                "subdomains": [s.strip() for s in subdomains_str.split(",")]
                if subdomains_str else [],
            },
            "source_artifacts": source_artifacts,
            "provenance": {
                "source_type": "textbook_to_course_pipeline",
                "import_pipeline_version": "1.0.0",
            },
            "features": {
                "source_provenance": source_provenance_flag,
                "evidence_source_provenance": evidence_source_provenance_flag,
            },
        }
        # B3: emit the optional license/attribution blocks only when present
        # (absent == byte-identical manifest).
        if license_field:
            manifest["license"] = license_field
        if attribution_field:
            manifest["attribution"] = attribution_field
        if concept_graph_sha256_resolved is not None:
            manifest["concept_graph_sha256"] = concept_graph_sha256_resolved

        # Phase 7c.5 SHIPPING BLOCKER: persist the chunkset hashes routed
        # via the workflow runner's ``inputs_from`` chain (chunking →
        # dart_chunks_sha256, imscc_chunking → imscc_chunks_sha256). Same
        # 64-hex regex shape as ``concept_graph_sha256``; only emit when
        # the kwarg is well-formed so a malformed upstream value falls
        # through to the validator's ``MISSING_*`` critical (the
        # validator owns ``INVALID_*`` shape diagnostics) rather than
        # being silently propagated.
        if dart_chunks_sha256_kw and _re_cg.match(
            r"^[0-9a-f]{64}$", dart_chunks_sha256_kw,
        ):
            # DART->semantik purge Stage 3c: persist the ratified
            # ``semantik_chunks_sha256`` (kwarg name unchanged; schema anyOf +
            # validator dual-read accept both fields — see the @mcp.tool()
            # variant above for the full rationale).
            manifest["semantik_chunks_sha256"] = dart_chunks_sha256_kw
        if imscc_chunks_sha256_kw and _re_cg.match(
            r"^[0-9a-f]{64}$", imscc_chunks_sha256_kw,
        ):
            manifest["imscc_chunks_sha256"] = imscc_chunks_sha256_kw

        # GPT Feedback v2 (May 12 / item 3): lineage mirror.
        # Build a sorted, deduped index of every upstream source-document
        # SHA from source_artifacts. Lets an auditor read the manifest
        # alone and see the full "what bytes produced this course" list
        # without walking source_artifacts.pdf[].checksum + .imscc.checksum
        # subtrees by hand.
        _src_doc_shas: set = set()
        for entry in source_artifacts.get("pdf", []) or []:
            cs = entry.get("checksum") if isinstance(entry, dict) else None
            if isinstance(cs, str) and _re_cg.match(r"^[0-9a-f]{64}$", cs):
                _src_doc_shas.add(cs)
        for entry in source_artifacts.get("html", []) or []:
            cs = entry.get("checksum") if isinstance(entry, dict) else None
            if isinstance(cs, str) and _re_cg.match(r"^[0-9a-f]{64}$", cs):
                _src_doc_shas.add(cs)
        imscc_entry = source_artifacts.get("imscc")
        if isinstance(imscc_entry, dict):
            cs = imscc_entry.get("checksum")
            if isinstance(cs, str) and _re_cg.match(r"^[0-9a-f]{64}$", cs):
                _src_doc_shas.add(cs)
        if _src_doc_shas:
            manifest["source_documents_sha256_index"] = sorted(_src_doc_shas)

        # GPT Feedback v2 (May 12 / item 3): copy lineage fields from
        # the on-disk concept_graph_semantic.json onto the manifest.
        # Best-effort: missing / unreadable / pre-May-2026 graph → fields
        # omitted (manifest tolerates absence). The graph itself is the
        # source of truth; the manifest mirror exists so an auditor
        # reading the manifest alone sees the lineage without opening
        # the graph artifact.
        _cg_path = course_dir / "graph" / "concept_graph_semantic.json"
        if _cg_path.exists() and _cg_path.is_file():
            try:
                _cg_json = json.loads(_cg_path.read_text(encoding="utf-8"))
            except (OSError, ValueError) as _exc:
                logger.debug(
                    "archive_to_libv2: failed to read concept graph for "
                    "lineage mirror (%s); skipping.",
                    _exc,
                )
            else:
                if isinstance(_cg_json, dict):
                    _gbh = _cg_json.get("graph_build_hash")
                    if isinstance(_gbh, str) and _re_cg.match(
                        r"^[a-f0-9]{64}$", _gbh,
                    ):
                        manifest["graph_build_hash"] = _gbh
                    _rpv = _cg_json.get("rulepack_version")
                    if isinstance(_rpv, str) and _re_cg.match(
                        r"^v[0-9a-f]+$", _rpv,
                    ):
                        manifest["rulepack_version"] = _rpv
                    if "course_package_version" in _cg_json:
                        _cpv = _cg_json["course_package_version"]
                        if _cpv is None or (
                            isinstance(_cpv, str) and _cpv
                        ):
                            manifest["course_package_version"] = _cpv

        manifest_path = course_dir / "manifest.json"
        # W0.7: atomic temp-then-replace so a crash mid-write never leaves a
        # truncated course manifest (the LibV2ManifestValidator parses it).
        _atomic_write_text(manifest_path, json.dumps(manifest, indent=2))

        # B3: when a license/attribution declaration is present, also write a
        # human-readable NOTICE into the course dir (for shipped bundles).
        # No-op when neither is present (byte-identical course dir).
        _notice_path = _write_course_notice(
            course_dir, slug, course_name, license_field, attribution_field
        )
        if _notice_path is not None:
            archived["notice"] = str(_notice_path)

        # F6: register the course in the LibV2 master catalog so that
        # ``libv2 catalog list`` / ``libv2 info <slug>`` see it immediately
        # without a separate manual ``index rebuild`` step.
        try:
            from LibV2.tools.libv2.catalog import _register_course_in_catalog
            _register_course_in_catalog(slug, manifest, libv2_root)
        except Exception as _exc:
            logger.warning(
                "archive_to_libv2: catalog registration failed for %s: %s",
                slug, _exc,
            )

        return json.dumps({
            "success": True,
            "course_slug": slug,
            "course_dir": str(course_dir),
            "manifest_path": str(manifest_path),
            "archived": archived,
            "features": {
                "source_provenance": source_provenance_flag,
                "evidence_source_provenance": evidence_source_provenance_flag,
            },
            "trainforge_workspace": (
                str(trainforge_dir) if trainforge_dir is not None else None
            ),
            # W2.3: surface the objectives-plumbing outcome so a caller (and a
            # warning gate) can see a no-op instead of it being swallowed.
            "objectives_status": _objectives_status,
            "warnings": _archival_warnings,
            "artifact_counts": {
                "pdfs": len(archived["pdfs"]),
                "html_files": len(archived["html"]),
                "imscc": 1 if archived["imscc"] else 0,
                "assessment": 1 if archived["assessment"] else 0,
                "objectives": 1 if archived["objectives"] else 0,
                "trainforge": sum(
                    1 for v in archived["trainforge"].values() if v is not None
                ),
            },
        })

    registry["archive_to_libv2"] = _archive_to_libv2
    # END BLOCK: Worker γ

    async def _build_source_module_map(**kwargs):
        """Source-router (Wave 9 ``source_mapping`` phase) — real heuristic.

        Previously wrote an empty ``source_module_map.json``, which left
        every Courseforge page emitted without ``sourceReferences[]`` and
        pinned the ``source_provenance`` / ``evidence_source_provenance``
        feature flags to false (investigation Issue 7). This implementation
        routes DART source blocks to Courseforge pages via keyword-overlap
        scoring:

          1. Enumerate DART block IDs by scanning ``staging_dir`` for
             ``*_synthesized.json`` sidecars — each ``sections[]`` entry
             contributes ``section_id``, ``section_title``, and any
             keyword-bearing text in ``data`` / ``sources_used``.
          2. Load the textbook structure (when available) and the
             project's objectives to enumerate per-page target topics.
          3. For each week (1..duration_weeks) and each page role
             (overview, content_0K, application, self_check, summary),
             score DART blocks by keyword overlap with the page's
             dominant topic. Blocks above a stronger threshold become
             ``primary`` refs; blocks above a weaker threshold become
             ``contributing`` refs.
          4. Emit the map in the Wave 9 shape that
             ``Courseforge.scripts.generate_course._page_refs_for``
             consumes: ``{week_key: {page_id: {primary, contributing,
             confidence}}}`` using ``dart:{slug}#{block_id}`` source IDs.

        No LLM. Pure text overlap — imperfect but deterministic and
        better than an empty map for provenance propagation.
        """
        project_id = kwargs.get("project_id", "")
        staging_dir_kw = kwargs.get("staging_dir", "") or ""
        textbook_structure_path = kwargs.get("textbook_structure_path", "") or ""

        if not project_id:
            return json.dumps({"error": "source-router requires project_id"})

        project_path = courseforge_exports_dir() / project_id
        project_path.mkdir(parents=True, exist_ok=True)
        map_path = project_path / "source_module_map.json"

        # ------------------------------------------------------------- #
        # Load project config for duration_weeks + course_name.          #
        # ------------------------------------------------------------- #
        config_path = project_path / "project_config.json"
        duration_weeks = 12
        course_name = project_id
        objectives_path: Optional[str] = None
        if config_path.exists():
            try:
                cfg = json.loads(config_path.read_text(encoding="utf-8"))
                duration_weeks = int(cfg.get("duration_weeks") or 12)
                course_name = cfg.get("course_name") or project_id
                objectives_path = cfg.get("objectives_path") or None
            except (OSError, ValueError):
                pass

        # ------------------------------------------------------------- #
        # Enumerate DART source blocks from staging_dir sidecars.        #
        # Each entry: {block_id, slug, keywords(set[str]), title}.       #
        # ------------------------------------------------------------- #
        dart_blocks: list = []
        staging_dir = Path(staging_dir_kw) if staging_dir_kw else None
        if staging_dir is None or not staging_dir.exists():
            # Fallback: scan Courseforge inputs for any synthesized sidecars.
            staging_dir = COURSEFORGE_INPUTS

        def _tokenize(text: str) -> set:
            """Lowercase, strip punctuation, drop stopwords + short tokens."""
            if not text:
                return set()
            import re as _re
            cleaned = _re.sub(r"[^a-z0-9\s]", " ", text.lower())
            _stopwords = {
                "the", "and", "for", "with", "from", "that", "this", "are",
                "was", "were", "has", "have", "had", "but", "not", "all",
                "any", "may", "can", "one", "two", "its", "their", "they",
                "will", "been", "you", "your", "our", "his", "her", "which",
                "what", "who", "why", "how", "when", "where", "into", "out",
                "over", "such", "more", "most", "some", "about", "there",
                "these", "those", "than", "then", "also", "only", "used",
                "use", "see", "via", "per",
            }
            return {
                t for t in cleaned.split()
                if len(t) > 3 and t not in _stopwords
            }

        if staging_dir and staging_dir.exists():
            for sidecar in sorted(staging_dir.rglob("*_synthesized.json")):
                try:
                    doc = json.loads(sidecar.read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    continue
                # Wave 36: match ContentGroundingValidator + Wave 35
                # content-generator slug rules (lowercase + space→hyphen).
                # Pre-Wave-36 a staging stem like ``XYZ_201_synthesized``
                # emitted router refs as ``dart:XYZ_201#...`` while the
                # validator + content-generator lowercased, so
                # uppercase-named corpora silently failed the source_refs
                # gate.
                slug = (
                    sidecar.stem.replace("_synthesized", "")
                    .lower()
                    .replace(" ", "-")
                )
                sections = doc.get("sections") or []
                if not isinstance(sections, list):
                    continue
                for section in sections:
                    if not isinstance(section, dict):
                        continue
                    block_id = str(section.get("section_id") or "").strip()
                    if not block_id:
                        continue
                    title = str(section.get("section_title") or "").strip()
                    section_type = str(section.get("section_type") or "").strip()
                    # Gather text for keyword extraction: title + any
                    # paragraph text + key-value block labels + data keys.
                    text_bits: list = [title, section_type]
                    data = section.get("data")
                    if isinstance(data, dict):
                        for k, v in data.items():
                            text_bits.append(str(k))
                            if isinstance(v, str):
                                text_bits.append(v)
                            elif isinstance(v, list):
                                for item in v[:20]:
                                    if isinstance(item, str):
                                        text_bits.append(item)
                                    elif isinstance(item, dict):
                                        for sub_v in item.values():
                                            if isinstance(sub_v, str):
                                                text_bits.append(sub_v)
                    keywords = _tokenize(" ".join(text_bits))
                    if not keywords:
                        # Fall back to splitting the block id so at least
                        # the title contributes a scoring signal.
                        keywords = _tokenize(title) or _tokenize(slug)
                    dart_blocks.append({
                        "block_id": block_id,
                        "slug": slug,
                        "title": title,
                        "keywords": keywords,
                        "source_id": f"semantik:{slug}#{block_id}",
                    })

        # ------------------------------------------------------------- #
        # Enumerate per-week topics. Preference order:                   #
        #   1. textbook_structure_path chapters/sections                 #
        #   2. objectives_path chapter/terminal objective statements     #
        #   3. DART block titles themselves (round-robin by week)        #
        # ------------------------------------------------------------- #
        week_topics: dict = {}  # week_num -> {page_id: set[str]}

        def _set_week_page(week_num: int, page_id: str, kw: set):
            week_topics.setdefault(week_num, {})[page_id] = kw

        structure_chapters: list = []
        if textbook_structure_path:
            sp = Path(textbook_structure_path)
            if sp.exists():
                try:
                    structure_doc = json.loads(sp.read_text(encoding="utf-8"))
                    chapters = structure_doc.get("chapters") or []
                    if isinstance(chapters, list):
                        structure_chapters = chapters
                except (OSError, ValueError):
                    pass

        objective_statements: list = []
        if objectives_path:
            op = Path(objectives_path)
            if op.exists():
                try:
                    obj_doc = json.loads(op.read_text(encoding="utf-8"))
                    for group in ("chapter_objectives", "terminal_objectives",
                                  "course_objectives"):
                        for item in obj_doc.get(group, []) or []:
                            if isinstance(item, dict):
                                text = (
                                    item.get("statement")
                                    or item.get("description")
                                    or item.get("text")
                                    or ""
                                )
                                if text:
                                    objective_statements.append(text)
                except (OSError, ValueError):
                    pass

        # Assemble per-week keyword bags. Wave 24 HIGH-5 fix: page roles
        # now scale with the week's LO count via _page_roles_for_week.
        # When objectives aren't loaded yet (source-router runs before
        # course_planning in some paths), fall back to the legacy 5-tuple.
        from MCP.tools._content_gen_helpers import _page_roles_for_week  # noqa: E402
        # Derive a per-week LO count: prefer objective_statements when
        # synthesized, else use structure chapters, else default to 4
        # (yields the legacy 5-page shape via _page_roles_for_week).
        if objective_statements:
            base_lo_count = max(1, len(objective_statements) // max(1, duration_weeks))
        elif structure_chapters:
            base_lo_count = max(1, len(structure_chapters) // max(1, duration_weeks) + 1)
        else:
            base_lo_count = 4
        page_roles = _page_roles_for_week(base_lo_count)

        # Prefer chapters / objective statements when available.
        topic_pool: list = []
        for ch in structure_chapters:
            if isinstance(ch, dict):
                # SemanticStructureExtractor emits the heading under
                # ``headingText`` (only legacy callers used ``title``), plus
                # the full inter-heading prose under ``chapter_text`` /
                # ``section_text``. Reading the wrong key here silently
                # collapsed the entire router: every chapter bag tokenized
                # to ∅, so every page hit the degenerate empty-bag fallback
                # and was pinned to one alphabetically-first source file.
                ch_topics = [
                    str(ch.get("headingText") or ch.get("title") or ""),
                    str(ch.get("chapter_text") or "")[:2000],
                ]
                for sub in ch.get("sections") or []:
                    if isinstance(sub, dict):
                        ch_topics.append(
                            str(sub.get("headingText") or sub.get("title") or "")
                        )
                        ch_topics.append(str(sub.get("section_text") or "")[:1000])
                        for ss in sub.get("subsections") or []:
                            if isinstance(ss, dict):
                                ch_topics.append(
                                    str(ss.get("headingText")
                                        or ss.get("title") or "")
                                )
                    elif isinstance(sub, str):
                        ch_topics.append(sub)
                topic_pool.append(_tokenize(" ".join(ch_topics)))
        # Fall through when the structure produced NO usable keyword bags
        # (every chapter tokenized to nothing). ``not any(...)`` — not
        # ``not topic_pool`` — so a list of empty sets still degrades to the
        # objectives / DART-block signal instead of collapsing the router.
        if not any(topic_pool) and objective_statements:
            topic_pool = [_tokenize(stmt) for stmt in objective_statements]
        if not any(topic_pool) and dart_blocks:
            # Final fallback: let DART block titles/keywords drive topic
            # bags, one per block, so each week gets a real signal.
            topic_pool = [blk["keywords"] for blk in dart_blocks]

        # Distribute topic_pool across weeks by SLICING, not single-index
        # round-robin. With many chapters and few weeks, the old
        # ``topic_pool[(week-1) % len]`` only ever consumed the first
        # ``duration_weeks`` bags — clustering every week onto the opening
        # source file. Slicing unions each week's contiguous share of the
        # material so weeks track the corpus in reading order and every
        # source file contributes to some week.
        non_empty_pool = [b for b in topic_pool if b] or topic_pool
        n = len(non_empty_pool)
        per_week = (-(-n // max(1, duration_weeks))) if n else 0  # ceil div
        for week_num in range(1, duration_weeks + 1):
            if not non_empty_pool:
                primary_bag: set = set()
            else:
                start = (week_num - 1) * per_week
                week_slice = non_empty_pool[start:start + per_week]
                if not week_slice:
                    # Past the end of the pool — reuse a wrapped bag so
                    # trailing weeks still carry a real signal.
                    week_slice = [non_empty_pool[(week_num - 1) % n]]
                primary_bag = set().union(*week_slice)
            for page_id in page_roles:
                _set_week_page(week_num, page_id, set(primary_bag))

        # ------------------------------------------------------------- #
        # Score blocks per (week, page) and emit refs.                   #
        # ------------------------------------------------------------- #
        source_module_map: dict = {}
        chunk_ids: set = set()

        if dart_blocks:
            for week_num in range(1, duration_weeks + 1):
                week_key = f"week_{week_num:02d}"
                pages_for_week = week_topics.get(week_num, {})
                week_entries: dict = {}
                for page_id, target_bag in pages_for_week.items():
                    if not target_bag:
                        # Wave 84 fix: degenerate fallback (no topic bag)
                        # used to round-robin a DART block as PRIMARY at
                        # confidence 0.3. That stamped a low-confidence
                        # alphabetically-first block on every page in the
                        # course, masking actually-relevant sources from
                        # data-cf-source-ids. Now we emit it as
                        # ``contributing`` so any genuine primary from
                        # the content-generator's grounding takes precedence.
                        fallback = dart_blocks[(week_num - 1) % len(dart_blocks)]
                        week_entries[page_id] = {
                            "primary": [],
                            "contributing": [fallback["source_id"]],
                            "confidence": 0.3,
                        }
                        chunk_ids.add(fallback["source_id"])
                        continue
                    scored: list = []
                    for blk in dart_blocks:
                        overlap = len(target_bag & blk["keywords"])
                        if overlap == 0:
                            continue
                        # Jaccard-ish score for ranking stability.
                        union = max(1, len(target_bag | blk["keywords"]))
                        score = overlap / union
                        scored.append((score, overlap, blk))
                    scored.sort(reverse=True, key=lambda x: (x[0], x[1]))
                    primary_ids: list = []
                    contributing_ids: list = []
                    top_score = scored[0][0] if scored else 0.0
                    # Wave 84: only emit primary refs when the top-scoring
                    # block clears a confidence floor (0.15 Jaccard). Below
                    # that floor the router can't tell which block is
                    # primary, so it cedes the role to the content-
                    # generator's data-cf-source-primary attribute (which
                    # picks the actual source the LLM used). Lower-scoring
                    # blocks still ride along as contributing so the page
                    # has provenance breadth.
                    PRIMARY_CONFIDENCE_FLOOR = 0.15
                    for score, overlap, blk in scored:
                        if (
                            score >= max(PRIMARY_CONFIDENCE_FLOOR, top_score * 0.8)
                            and len(primary_ids) < 2
                        ):
                            primary_ids.append(blk["source_id"])
                        elif score >= 0.05 and len(contributing_ids) < 3:
                            contributing_ids.append(blk["source_id"])
                    if not primary_ids and scored:
                        # Top score is below the floor → emit the top match
                        # as CONTRIBUTING (not primary). That preserves
                        # provenance breadth without polluting the primary
                        # role with a guess.
                        candidate = scored[0][2]["source_id"]
                        if candidate not in contributing_ids and len(contributing_ids) < 3:
                            contributing_ids.append(candidate)
                    if not primary_ids and not contributing_ids:
                        # Wave 84: no overlap at all — round-robin a DART
                        # block as CONTRIBUTING (was primary) so a chunk
                        # always has some provenance for trace, but the
                        # primary slot stays open for content-generator
                        # grounding.
                        fallback = dart_blocks[(week_num - 1) % len(dart_blocks)]
                        contributing_ids.append(fallback["source_id"])
                        top_score = 0.2
                    for sid in primary_ids:
                        chunk_ids.add(sid)
                    for sid in contributing_ids:
                        chunk_ids.add(sid)
                    week_entries[page_id] = {
                        "primary": primary_ids,
                        "contributing": contributing_ids,
                        "confidence": round(max(top_score, 0.2), 2),
                    }
                if week_entries:
                    source_module_map[week_key] = week_entries

        map_path.write_text(
            json.dumps(source_module_map, indent=2),
            encoding="utf-8",
        )

        routing_mode = (
            "keyword_overlap_heuristic" if dart_blocks
            else "stub_empty_map"
        )

        # ------------------------------------------------------------- #
        # Anti-silent-degradation guard. A "collapsed" routing run is one #
        # where NO page earned a real ``primary`` ref — every page fell  #
        # back to a low-confidence round-robin ``contributing`` block,   #
        # pinning the whole course to one source file. Pre-fix this      #
        # happened silently (wrong structure key -> empty topic bags).   #
        # Also flag a thin run where almost every page lacks a primary.  #
        # ------------------------------------------------------------- #
        total_pages = sum(len(v) for v in source_module_map.values())
        pages_with_primary = sum(
            1
            for v in source_module_map.values()
            for e in v.values()
            if e.get("primary")
        )
        distinct_sources = len({
            sid.split("#", 1)[0]
            for v in source_module_map.values()
            for e in v.values()
            for sid in (list(e.get("primary") or []) + list(e.get("contributing") or []))
        })
        primary_rate = (pages_with_primary / total_pages) if total_pages else 0.0
        routing_collapsed = (
            bool(dart_blocks) and total_pages > 0 and pages_with_primary == 0
        )
        if routing_collapsed:
            logger.error(
                "SOURCE ROUTER COLLAPSE (course=%s): 0/%d pages earned a "
                "primary source ref; every page fell back to a low-confidence "
                "round-robin block, so the course will be mis-sourced. Likely "
                "cause: textbook_structure chapters carry no usable heading "
                "text (check the ``headingText`` key), or staging "
                "``*_synthesized.json`` sidecars are missing. "
                "dart_blocks_indexed=%d distinct_sources=%d.",
                course_name, total_pages, len(dart_blocks), distinct_sources,
            )
        elif total_pages and primary_rate < 0.25:
            logger.warning(
                "Source router thin coverage (course=%s): only %d/%d pages "
                "(%.0f%%) earned a primary source ref. Provenance may be weak.",
                course_name, pages_with_primary, total_pages, primary_rate * 100,
            )

        return json.dumps({
            "source_module_map_path": str(map_path),
            "source_chunk_ids": sorted(chunk_ids),
            "staging_dir": str(staging_dir) if staging_dir else "",
            "textbook_structure_path": textbook_structure_path,
            "routing_mode": routing_mode,
            "dart_blocks_indexed": len(dart_blocks),
            "weeks_routed": len(source_module_map),
            "course_name": course_name,
            "routing_collapsed": routing_collapsed,
            "routing_primary_rate": round(primary_rate, 3),
            "pages_with_primary": pages_with_primary,
            "total_pages": total_pages,
            "distinct_sources_routed": distinct_sources,
        })

    registry["build_source_module_map"] = _build_source_module_map

    # ============================================================================
    # Phase 6 Subtask 12: _run_concept_extraction — concept-graph builder
    #
    # New ``concept_extraction`` workflow phase (between ``source_mapping``
    # and ``course_planning`` per plan ST 11). The phase runs the
    # ``Trainforge.pedagogy_graph_builder.build_pedagogy_graph`` over a
    # canonical v4 chunkset (DART chunks emitted by the upstream
    # ``chunking`` phase, falling back to a minimal inline projection of
    # ``*_synthesized.json`` sidecars when the upstream chunkset is not
    # available), persists the resulting graph to
    # ``LibV2/courses/<slug>/concept_graph/concept_graph_semantic.json``
    # plus a sibling ``manifest.json``, computes the SHA-256 of the graph
    # bytes, and surfaces both the path and hash through phase outputs.
    #
    # Phase 7b ST 14.5 architectural reconciliation: when the upstream
    # ``chunking`` phase (Phase 7b ST 11, ``_run_dart_chunking``) has
    # already emitted ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl``,
    # this helper consumes that chunkset directly via the ``dart_chunks_path``
    # kwarg threaded through the workflow's ``inputs_from`` wiring. This
    # eliminates the divergence-risk surface of two parallel chunk-shaping
    # paths (the upstream chunker invokes ``Trainforge.chunker.chunk_content``
    # — the canonical surface; the legacy inline-projection here was a
    # workaround for the Phase 6 phase ordering, where no IMSCC existed
    # yet). The inline-projection path is preserved as a back-compat
    # fallback for legacy / pre-Phase-7b runs that bypass the ``chunking``
    # phase, and for unit tests that exercise ``_run_concept_extraction``
    # in isolation.
    # ============================================================================
    async def _run_concept_extraction(**kwargs):
        """Build the genuine semantic concept graph over staged DART output.

        Fix-2: this phase emits the genuine ``kind: "concept_semantic"``
        graph (``DomainConcept`` nodes + typed edges via
        ``build_semantic_graph``), replacing the prior lightweight
        ``kind: "pedagogy"`` graph from ``build_pedagogy_graph``.

        Required kwargs (resolved via inputs_from in workflows.yaml):
            project_id: Courseforge project (used only for course_name lookup)
            course_name: Canonical course name (defaults to project config)
            staging_dir: DART staging directory (sibling to objective_extraction)

        Optional kwargs (Phase 7b ST 14.5 — consume upstream chunkset):
            dart_chunks_path: Path to ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl``
                emitted by the upstream ``chunking`` phase. When provided
                and readable, this helper loads chunks from the JSONL
                file and skips the legacy inline-projection. When absent
                or unreadable, the inline-projection path runs as a
                back-compat fallback.

        Optional kwargs (objectives resolution for LO-driven typed edges):
            objectives_path: the ``--reuse-objectives`` JSON (resolution
                candidate #1; a reuse run pins the typed-edge rules to the
                operator's verbatim objectives doc).
            synthesized_objectives_path: the
                ``synthesized_objectives.json`` emitted by
                ``course_planning`` (resolution candidate #2, the
                fresh-run source). Phase-ordering fix (Option A1):
                ``concept_extraction`` now runs AFTER ``course_planning``,
                so on a fresh ``textbook_to_course`` run this candidate
                exists and gives the LO-driven typed-edge rules
                (prerequisite_from_lo_order, targets_concept_from_lo) a
                real learning-outcomes ordering. The concept-objective
                linker (relocated here from ``_plan_course_structure``)
                then enriches ``LearningObjective.key_concepts[]`` from the
                concept graph before ``build_semantic_graph`` runs, and the
                enriched key_concepts are written back to the project-export
                ``synthesized_objectives.json`` (never to a reuse path).

        Outputs (returned + persisted):
            concept_graph_path: ``LibV2/courses/<slug>/concept_graph/concept_graph_semantic.json``
            concept_graph_sha256: SHA-256 hex digest of the graph file bytes
        """
        import hashlib as _hashlib

        project_id = kwargs.get("project_id") or ""
        course_name = kwargs.get("course_name") or ""
        staging_dir_kw = kwargs.get("staging_dir") or ""
        dart_chunks_path_kw = kwargs.get("dart_chunks_path") or ""

        # Resolve project + course_name from project_config when present.
        config_data: Dict[str, Any] = {}
        project_path: Optional[Path] = None
        if project_id:
            cand = courseforge_exports_dir() / project_id
            if cand.exists():
                project_path = cand
                cfg_path = cand / "project_config.json"
                if cfg_path.exists():
                    try:
                        config_data = json.loads(
                            cfg_path.read_text(encoding="utf-8")
                        )
                    except (OSError, ValueError):
                        config_data = {}
        course_name = (
            course_name
            or config_data.get("course_name")
            or project_id
            or "UNKNOWN"
        )

        # Resolve staging dir. Honor explicit kwarg first; fall back to
        # any project-config-recorded staging dir; finally walk
        # COURSEFORGE_INPUTS for any *_synthesized.json sidecars (degraded
        # path for legacy fixtures that bypass the staging phase).
        staging_dir: Optional[Path] = None
        if staging_dir_kw:
            cand = Path(staging_dir_kw)
            if cand.exists():
                staging_dir = cand
        if staging_dir is None:
            cfg_staging = config_data.get("staging_dir")
            if cfg_staging:
                cand = Path(cfg_staging)
                if cand.exists():
                    staging_dir = cand
        if staging_dir is None and COURSEFORGE_INPUTS.exists():
            staging_dir = COURSEFORGE_INPUTS

        course_slug = course_name.lower().replace("_", "-").replace(" ", "-")
        course_code_lower = course_name.lower().replace("-", "_")
        chunks: List[Dict[str, Any]] = []
        chunk_counter = 1

        # Stage-3 per-window resume-checkpoint sidecar path. Resolved eagerly
        # (well before the graph_dir mkdir below) so ``_run_stage3_concept_synthesis``
        # can reuse completed 7B window calls on a killed / timed-out re-entry.
        # Placed in the phase's OUTPUT dir (the same
        # ``<libv2>/courses/<slug>/concept_graph/`` the graph +
        # domain_concept_vocabulary land in) so a workflow ``--resume`` finds
        # it. The append path mkdirs its parent, so this is safe even before
        # graph_dir exists.
        _concept_checkpoint_path = (
            _resolve_libv2_root(kwargs.get("libv2_root"))
            / "courses"
            / course_slug
            / "concept_graph"
            / _CONCEPT_EXTRACTION_CHECKPOINT_NAME
        )

        # M2 fix: track inline-projection drops so the phase output
        # carries a ``projection_drops_count`` and a structured
        # ``concept_projection_drop`` decision event fires per skip.
        # Pre-fix the per-section / per-sidecar drops were logger-only
        # and operators could not tell from the workflow report whether
        # extraction silently dropped concepts before
        # ``build_pedagogy_graph`` was even called.
        projection_drops: List[Dict[str, Any]] = []
        _capture_concept = None
        try:
            from lib.decision_capture import DecisionCapture as _DC_concept
            _capture_concept = _DC_concept(
                course_code=course_name.upper() or "concept_extraction",
                phase="content-analysis",
                tool="trainforge",
                streaming=True,
            )
        except Exception as exc:  # noqa: BLE001 — capture is best-effort
            logger.warning(
                "concept_extraction: DecisionCapture init failed (%s); "
                "projection drops will be tracked but not persisted.",
                exc,
            )
            _capture_concept = None

        def _record_projection_drop(reason: str, **fields: Any) -> None:
            """Append a structured drop record + emit a decision event.

            ``reason`` is a stable enum-ish slug (``malformed_sidecar``,
            ``non_list_sections``, ``non_dict_section``,
            ``missing_section_id``, ``malformed_upstream_chunk_jsonl``).
            Extra context fields are stamped onto both the drop record
            and the decision event's ``ml_features`` so a postmortem
            reader can stratify by reason without re-running.
            """
            drop_record = {"reason": reason, **fields}
            projection_drops.append(drop_record)
            if _capture_concept is None:
                return
            try:
                _capture_concept.log_decision(
                    decision_type="concept_projection_drop",
                    decision=f"dropped_section reason={reason}",
                    rationale=(
                        f"concept_extraction inline projection dropped a "
                        f"section before build_pedagogy_graph could "
                        f"consume it. reason={reason}; context={fields!r}. "
                        f"Surfaced via projection_drops_count in phase "
                        f"output so downstream operators see the silent-"
                        f"degradation class instead of relying on the "
                        f"min_edge_count gate to catch a thin graph."
                    ),
                    ml_features={"reason": reason, **{
                        k: v for k, v in fields.items()
                        if isinstance(v, (str, int, float, bool))
                    }},
                )
            except Exception as exc:  # noqa: BLE001 — best-effort
                logger.warning(
                    "concept_extraction: log_decision(concept_projection_drop) "
                    "failed (%s); drop still recorded in projection_drops.",
                    exc,
                )

        # Phase 7b ST 14.5: consume upstream DART chunkset when present.
        # The ``chunking`` phase (Phase 7b ST 11) emits
        # ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl`` via the
        # canonical ``Trainforge.chunker.chunk_content`` path; the workflow
        # YAML's ``inputs_from`` block threads that path here. When the
        # path is provided AND readable, load the canonical v4 chunks
        # and skip the legacy inline-projection below. When absent or
        # unreadable, fall through to the inline-projection so legacy
        # / pre-Phase-7b fixtures (and unit tests that exercise this
        # helper in isolation) keep working.
        upstream_chunks_loaded = False
        if dart_chunks_path_kw:
            cand_chunks_path = Path(dart_chunks_path_kw)
            if cand_chunks_path.exists() and cand_chunks_path.is_file():
                try:
                    with cand_chunks_path.open("r", encoding="utf-8") as fh:
                        for _line_no, line in enumerate(fh, start=1):
                            line = line.strip()
                            if not line:
                                continue
                            try:
                                chunks.append(json.loads(line))
                            except ValueError as _ve:
                                # M2 fix: surface the drop so the
                                # silent-skip is visible to operators.
                                _record_projection_drop(
                                    "malformed_upstream_chunk_jsonl",
                                    source=str(cand_chunks_path),
                                    line=_line_no,
                                    parse_error=str(_ve),
                                )
                                continue
                    upstream_chunks_loaded = True
                except OSError as exc:
                    logger.warning(
                        "Phase 7b ST 14.5: failed to read upstream dart_chunks_path "
                        "%s (%s); falling back to inline-projection.",
                        cand_chunks_path, exc,
                    )

        # Legacy inline-projection fallback. Builds a minimal v4 chunk
        # projection from each ``*_synthesized.json`` sidecar so the
        # co-occurrence + semantic graph builders have populated
        # ``concept_tags`` + ``source.module_id`` / ``item_path`` to walk.
        # One chunk per DART section keeps wall-time deterministic.
        # Preserved for back-compat with legacy / pre-Phase-7b runs that
        # bypass the ``chunking`` phase.
        def _tokenize_concepts(text: str, limit: int = 8) -> List[str]:
            """Lift bare-word concept slugs from a section's text bits."""
            if not text:
                return []
            import re as _re_inner
            cleaned = _re_inner.sub(r"[^a-z0-9\s]", " ", text.lower())
            stop = {
                "the", "and", "for", "with", "from", "that", "this", "are",
                "was", "were", "has", "have", "had", "but", "not", "all",
                "any", "may", "can", "one", "two", "its", "their", "they",
                "will", "been", "you", "your", "our", "into", "over", "such",
                "more", "most", "some", "about", "these", "those", "than",
                "also", "only", "used", "use", "see", "via", "per",
            }
            seen: set = set()
            out: List[str] = []
            for tok in cleaned.split():
                if len(tok) <= 4 or tok in stop or tok in seen:
                    continue
                seen.add(tok)
                out.append(tok)
                if len(out) >= limit:
                    break
            return out

        if (
            not upstream_chunks_loaded
            and staging_dir is not None
            and staging_dir.exists()
        ):
            for sidecar in sorted(staging_dir.rglob("*_synthesized.json")):
                try:
                    doc = json.loads(sidecar.read_text(encoding="utf-8"))
                except (OSError, ValueError) as _e:
                    _record_projection_drop(
                        "malformed_sidecar",
                        source=str(sidecar),
                        parse_error=str(_e),
                    )
                    continue
                slug = (
                    sidecar.stem.replace("_synthesized", "")
                    .lower()
                    .replace(" ", "-")
                )
                sections = doc.get("sections") or []
                if not isinstance(sections, list):
                    _record_projection_drop(
                        "non_list_sections",
                        source=str(sidecar),
                        sections_type=type(sections).__name__,
                    )
                    continue
                for _sec_idx, section in enumerate(sections):
                    if not isinstance(section, dict):
                        _record_projection_drop(
                            "non_dict_section",
                            source=str(sidecar),
                            section_index=_sec_idx,
                            section_type=type(section).__name__,
                        )
                        continue
                    section_id = str(section.get("section_id") or "").strip()
                    if not section_id:
                        _record_projection_drop(
                            "missing_section_id",
                            source=str(sidecar),
                            section_index=_sec_idx,
                        )
                        continue
                    title = str(section.get("section_title") or "").strip()
                    section_type = (
                        str(section.get("section_type") or "").strip().lower()
                    )
                    text_bits: List[str] = [title, section_type]
                    data = section.get("data")
                    if isinstance(data, dict):
                        for k, v in data.items():
                            text_bits.append(str(k))
                            if isinstance(v, str):
                                text_bits.append(v)
                            elif isinstance(v, list):
                                for item in v[:20]:
                                    if isinstance(item, str):
                                        text_bits.append(item)
                    chunk_text = " ".join(t for t in text_bits if t).strip()
                    concept_tags = _tokenize_concepts(chunk_text)
                    chunk_id = (
                        f"{course_code_lower}_chunk_{chunk_counter:05d}"
                    )
                    # Phase 8 ST 6: emit canonical 'id' key
                    # (build_pedagogy_graph at
                    # Trainforge/pedagogy_graph_builder.py:593 reads
                    # c.get('id'); pre-Phase-8 chunk_id-keyed emit was
                    # silently dropped). Forward path (upstream
                    # dart_chunks_path JSONL load at :6231-6243) already
                    # emits canonical id via the chunker package; this
                    # fixes the fallback path that runs when
                    # dart_chunks_path is absent or unreadable.
                    chunks.append({
                        "id": chunk_id,
                        "text": chunk_text,
                        "concept_tags": concept_tags,
                        "learning_outcome_refs": [],
                        "chunk_type": (
                            "assessment_item"
                            if section_type in ("assessment", "self_check")
                            else "content"
                        ),
                        "bloom_level": "understand",
                        "difficulty": "intermediate",
                        "source": {
                            "module_id": slug,
                            "item_path": f"{slug}#{section_id}",
                        },
                    })
                    chunk_counter += 1

        # ------------------------------------------------------------------
        # Stage-3 concept-synthesis helper (Wave C). Nested so it shares
        # the handler's ``_record_projection_drop`` / logger scope; pure
        # function of its kwargs otherwise.
        # ------------------------------------------------------------------
        async def _run_stage3_concept_synthesis(
            *,
            chunks: List[Dict[str, Any]],
            textbook_structure_path: str,
            course_name: str,
            course_slug: str,
            capture: Any,
            checkpoint_path: Optional[Path] = None,
        ) -> Optional[Dict[str, Any]]:
            """Stage 3 — synthesize a domain-concept vocabulary, re-tag
            chunks in-memory, return the vocabulary dict.

            Per plan §4.2:

            (a) read ``textbook_structure.json``, pull ``chapters[]``
                with ``chapter_text``;
            (b) WINDOW each chapter's DART chunks (parity with Stage-2
                objective windowing) and dispatch ONE
                ``synthesize_concepts`` call per WINDOW (not per chapter),
                batched ≤10 (plan §5.3) — so a mega-chapter corpus drives
                many concept calls instead of one;
            (c) UNION + de-dup the per-window concepts into a course
                vocabulary on ``canonical_slug``;
            (d) compile via ``compile_domain_concept_seeds``;
            (e) re-tag each chunk: ``extract_concept_tags(text, item,
                domain_concept_seeds=seeds)``, UNION into
                ``chunk["concept_tags"]``;
            (g) per-chapter failure isolation (plan §5.4) — one
                chapter's call failing degrades, doesn't abort; all-fail
                → empty-seed fallback.

            Returns the vocabulary dict (persisted by the caller as a
            sibling of ``concept_graph_semantic.json``), or ``None`` when
            no textbook structure / no chapters are available.
            """
            import asyncio as _asyncio

            # --- (a) read textbook_structure.json --------------------------
            ts_path: Optional[Path] = None
            if textbook_structure_path:
                cand = Path(textbook_structure_path)
                if cand.exists() and cand.is_file():
                    ts_path = cand
            if ts_path is None:
                logger.warning(
                    "concept_extraction: Stage-3 requested "
                    "(TEXTBOOK_SYNTHESIS_PROVIDER set) but no readable "
                    "textbook_structure_path (%r); skipping Stage 3.",
                    textbook_structure_path,
                )
                return None
            try:
                textbook_structure = json.loads(
                    ts_path.read_text(encoding="utf-8")
                )
            except (OSError, ValueError) as exc:
                logger.warning(
                    "concept_extraction: Stage-3 failed to parse "
                    "textbook_structure.json %s (%s); skipping Stage 3.",
                    ts_path, exc,
                )
                return None
            chapters = []
            if isinstance(textbook_structure, dict):
                raw_chapters = textbook_structure.get("chapters")
                if isinstance(raw_chapters, list):
                    chapters = [c for c in raw_chapters if isinstance(c, dict)]
            if not chapters:
                logger.warning(
                    "concept_extraction: Stage-3 textbook_structure.json "
                    "carries no chapters[]; skipping Stage 3.",
                )
                return None

            # --- construct the provider -----------------------------------
            try:
                from Courseforge.generators._textbook_synthesis_provider import (
                    TextbookSynthesisProvider,
                    TextbookSynthesisProviderError,
                )
            except Exception as exc:  # noqa: BLE001 — import failure → skip
                logger.warning(
                    "concept_extraction: Stage-3 provider import failed "
                    "(%s); skipping Stage 3.",
                    exc,
                )
                return None
            try:
                provider = TextbookSynthesisProvider(capture=capture)
            except Exception as exc:  # noqa: BLE001 — construction failure
                logger.warning(
                    "concept_extraction: Stage-3 provider construction "
                    "failed (%s); skipping Stage 3.",
                    exc,
                )
                return None

            # --- (b) N per-WINDOW calls, batched ≤10 -----------------------
            # Parity with Stage-2 (``_run_stage2_window_synthesis``): instead
            # of ONE ``synthesize_concepts`` call per chapter, group each
            # chapter's DART chunks into serving-window-sized windows
            # (``group_chunks_into_windows``, the SAME helper + ``num_ctx``
            # env knob Stage 2 uses) and dispatch ONE call per window. A
            # corpus that collapses to a single mega-chapter (the real-corpus
            # 7B failure) then drives many concept calls — not one — so the
            # vocabulary approaches the corpus's real concept count instead
            # of whatever fits a single truncated chapter_text prompt.
            from lib.objectives.chunk_window import (
                chunks_for_chapter as _chunks_for_chapter,
                group_chunks_into_windows as _group_chunks_into_windows,
            )
            from Courseforge.generators._textbook_synthesis_provider import (
                _SYNTHESIS_NUM_CTX_ENV as _CONCEPT_NUM_CTX_ENV,
                _TEXTBOOK_SYNTHESIS_SYSTEM_PROMPT as _CONCEPT_SYSTEM_PROMPT,
            )
            from lib.retrieval._prompts import (
                resolve_num_ctx as _resolve_num_ctx,
            )

            # Serving-window token budget — same resolution chain Stage-2
            # uses (TEXTBOOK_SYNTHESIS_NUM_CTX > resolve_num_ctx()).
            _num_ctx_env = os.environ.get(_CONCEPT_NUM_CTX_ENV)
            _num_ctx = _resolve_num_ctx()
            if _num_ctx_env:
                try:
                    _maybe = int(_num_ctx_env)
                    if _maybe > 0:
                        _num_ctx = _maybe
                except (TypeError, ValueError):
                    pass
            _max_tokens = int(getattr(provider, "_max_tokens", 4096) or 4096)

            # Build the flat ordered window list across every chapter. Each
            # window is packaged as a per-window PSEUDO-CHAPTER that
            # ``synthesize_concepts`` consumes unchanged: it carries the REAL
            # chapter_id (so concept ``chapter_ids`` provenance stays correct)
            # plus the joined window-chunk text as ``chapter_text`` (the field
            # ``_chapter_text_bounded`` reads). When a chapter has NO joinable
            # chunks, fall back to the chapter's own ``chapter_text`` as a
            # single window so a chunk-less chapter still synthesizes.
            window_specs: List[Dict[str, Any]] = []  # pseudo-chapter dicts
            for chapter in chapters:
                cid = str(chapter.get("id") or "")
                try:
                    chapter_chunks, join_method = _chunks_for_chapter(
                        chapter, chunks, all_chapters=chapters,
                    )
                except Exception as exc:  # noqa: BLE001 — isolate join raise
                    logger.warning(
                        "concept_extraction: Stage-3 chunk-join raised on "
                        "chapter %r (%s); using chapter_text as a single "
                        "window.", cid, exc,
                    )
                    chapter_chunks, join_method = [], "order_fallback"
                if chapter_chunks:
                    ch_windows = _group_chunks_into_windows(
                        chapter,
                        chapter_chunks,
                        num_ctx=_num_ctx,
                        system_prompt=_CONCEPT_SYSTEM_PROMPT,
                        draft_block="  (none)",
                        max_tokens=_max_tokens,
                        join_method=join_method,
                    )
                    for w in ch_windows:
                        wd = w.to_dict()
                        joined_text = "\n\n".join(
                            str(c.get("text") or "")
                            for c in (wd.get("chunks") or [])
                            if str(c.get("text") or "")
                        )
                        window_specs.append({
                            "id": cid,
                            "chapter_text": joined_text,
                            "window_index": int(wd.get("window_index") or 0),
                            "chunk_ids": list(wd.get("chunk_ids") or []),
                        })
                else:
                    # No joinable chunks — one window from chapter_text.
                    window_specs.append({
                        "id": cid,
                        "chapter_text": str(chapter.get("chapter_text") or ""),
                        "window_index": 0,
                        "chunk_ids": [],
                    })

            per_chapter_concepts: List[Dict[str, Any]] = []
            # Per-window failure isolation (mirrors Stage-2 §5.4) — recorded
            # at CHAPTER granularity (deduped) so a chapter whose window(s)
            # failed surfaces once in ``chapter_synthesis_failures`` and the
            # existing per-chapter-isolation contract still holds.
            _failed_chapter_ids: List[str] = []
            windows_synthesized = 0
            windows_failed = 0
            windows_reused = 0

            def _one_window(spec: Dict[str, Any]) -> Optional[Dict[str, Any]]:
                """Synchronous per-window call; runs in an executor.

                ``spec`` is a pseudo-chapter dict carrying the real
                chapter_id + that window's joined chunk text.
                """
                cid = str(spec.get("id") or "")
                widx = spec.get("window_index")
                # Graceful stop (P3.0 marker pattern): a stop armed WHILE this
                # batch is in flight refuses a not-yet-started window by
                # RETURNING STOP_MARKER — never raising (a raise would propagate
                # through asyncio.gather before the post-gather append loop runs,
                # losing already-completed windows in this batch).
                if stop_requested():
                    return STOP_MARKER
                try:
                    return provider.synthesize_concepts(
                        spec, course_name=course_name
                    )
                except TextbookSynthesisProviderError as exc:
                    # Plan §5.4 — per-window failure isolation. Record the
                    # failed window, continue with the rest.
                    logger.warning(
                        "concept_extraction: Stage-3 window %r#w%s concept "
                        "call exhausted (%s); degrading per §5.4.",
                        cid, widx, exc,
                    )
                    return None
                except Exception as exc:  # noqa: BLE001 — isolate any raise
                    logger.warning(
                        "concept_extraction: Stage-3 window %r#w%s concept "
                        "call raised (%s); degrading per §5.4.",
                        cid, widx, exc,
                    )
                    return None

            def _window_key(spec: Dict[str, Any]) -> Tuple[str, int]:
                try:
                    _wi = int(spec.get("window_index") or 0)
                except (TypeError, ValueError):
                    _wi = 0
                return (str(spec.get("id") or ""), _wi)

            # ---- Per-window resume checkpoint (default ON). ---------------
            # Load any prior sidecar and partition windows into REUSE
            # (fingerprint matches a completed record) vs DISPATCH. The reuse
            # splice reassembles in ORIGINAL window order so
            # per_chapter_concepts (and every downstream merge/dedup) is
            # byte-equivalent to an uninterrupted run.
            _cp_enabled = (
                checkpoint_path is not None
                and _concept_extraction_checkpoint_enabled()
            )
            _cp_model = str(getattr(provider, "_model", "") or "")
            _cp_cache = (
                _load_concept_windows_checkpoint(checkpoint_path)
                if _cp_enabled else {}
            )
            if _cp_cache:
                logger.info(
                    "concept_extraction: Stage-3 loaded %d checkpointed "
                    "window record(s) from %s.",
                    len(_cp_cache), checkpoint_path,
                )

            _fp_by_key: Dict[Tuple[str, int], str] = {}
            _reused: Dict[Tuple[str, int], List[Dict[str, Any]]] = {}
            _to_dispatch: List[Dict[str, Any]] = []
            for spec in window_specs:
                _key = _window_key(spec)
                _fp = _concept_window_fingerprint(
                    chapter_id=_key[0],
                    window_index=_key[1],
                    chunk_ids=spec.get("chunk_ids") or [],
                    chapter_text=str(spec.get("chapter_text") or ""),
                    course_name=course_name,
                    model=_cp_model,
                    num_ctx=_num_ctx,
                    max_tokens=_max_tokens,
                    system_prompt=_CONCEPT_SYSTEM_PROMPT,
                )
                _fp_by_key[_key] = _fp
                _rec = _cp_cache.get(_key) if _cp_enabled else None
                if isinstance(_rec, dict) and _rec.get("fingerprint") == _fp:
                    _reused[_key] = [
                        c
                        for c in (_rec.get("concepts") or [])
                        if isinstance(c, dict)
                    ]
                else:
                    _to_dispatch.append(spec)

            # ``batch_chapters`` is a staticmethod on the provider class
            # (generic ≤10 batch splitter); reuse it for the un-cached window
            # list so batching/concurrency stays identical to Stage 2 + the
            # legacy per-chapter path. Plan §5.3 — batches of ≤10. Each
            # completed window is appended to the sidecar AS ITS BATCH LANDS
            # (not after the full dispatch loop) so a kill / power-loss
            # mid-phase only costs the in-flight batch on resume, never the
            # whole run (mirrors the stage-2 per-batch checkpoint fix).
            _dispatched: Dict[Tuple[str, int], Optional[Dict[str, Any]]] = {}
            batches = provider.batch_chapters(_to_dispatch)
            _stop_marker_seen = False
            for batch in batches:
                # Graceful stop BETWEEN batches: every prior batch's completed
                # window is already appended to the sidecar, so this plain raise
                # loses nothing (mid-batch arming → STOP_MARKER + post-loop
                # raise below).
                check_stop("concept_windows", len(_dispatched))
                # Dispatch each batch of ≤10 windows via run_in_executor,
                # awaiting the whole batch before the next (plan §5.3 —
                # "wait for ALL batch completions before next batch").
                results = await _asyncio.gather(*[
                    _asyncio.get_running_loop().run_in_executor(
                        None, _one_window, spec
                    )
                    for spec in batch
                ])
                for spec, res in zip(batch, results):
                    _dkey = _window_key(spec)
                    if res is STOP_MARKER:
                        # Not-attempted (stop refused pre-dispatch): skip append
                        # so resume re-runs it. Do NOT record in _dispatched.
                        _stop_marker_seen = True
                        continue
                    _dispatched[_dkey] = res
                    if _cp_enabled and res is not None:
                        _append_concept_window_checkpoint(
                            checkpoint_path,
                            chapter_id=_dkey[0],
                            window_index=_dkey[1],
                            fingerprint=_fp_by_key[_dkey],
                            concepts=[
                                _c
                                for _c in (res.get("concepts") or [])
                                if isinstance(_c, dict)
                            ],
                        )
            if _stop_marker_seen:
                # A stop armed mid-batch: every window that COMPLETED before it
                # is now in _dispatched AND checkpointed; the markers were never
                # dispatched. Raise AFTER the sidecar append so resume re-runs
                # only the un-attempted windows (P3.0).
                raise GracefulStopRequested("concept_windows", len(_dispatched))

            # Reassemble concepts in ORIGINAL window order (byte-equivalent to
            # an uninterrupted run; the dispatch loop above already
            # checkpointed each freshly-dispatched window).
            for spec in window_specs:
                _key = _window_key(spec)
                cid = _key[0]
                if _key in _reused:
                    windows_synthesized += 1
                    windows_reused += 1
                    per_chapter_concepts.extend(_reused[_key])
                    continue
                res = _dispatched.get(_key)
                if res is None:
                    windows_failed += 1
                    if cid and cid not in _failed_chapter_ids:
                        _failed_chapter_ids.append(cid)
                    continue
                windows_synthesized += 1
                for concept in res.get("concepts") or []:
                    if isinstance(concept, dict):
                        per_chapter_concepts.append(concept)

            chapter_synthesis_failures: List[str] = list(_failed_chapter_ids)
            # ``chapters_synthesized`` retained for the all-fail fallback
            # check below (now counts windows that returned concepts).
            chapters_synthesized = windows_synthesized
            window_call_count = len(window_specs)

            # --- (c) merge + de-dup on canonical_slug ----------------------
            from lib.ontology.slugs import canonical_slug as _canonical_slug

            merged: Dict[str, Dict[str, Any]] = {}
            for concept in per_chapter_concepts:
                canonical_raw = str(concept.get("canonical") or "").strip()
                if not canonical_raw:
                    continue
                slug = _canonical_slug(canonical_raw)
                if not slug:
                    continue
                aliases = [
                    str(a).strip()
                    for a in (concept.get("aliases") or [])
                    if isinstance(a, str) and str(a).strip()
                ]
                # Fix-1 (merge half): preserve the LLM's raw canonical surface
                # form as an alias before it's overwritten by the slug below,
                # so the compiled seed can also match the natural-language form
                # the model emitted (e.g. "Visual Hierarchy") in prose.
                if canonical_raw and canonical_raw not in aliases:
                    aliases.append(canonical_raw)
                chapter_ids = [
                    str(c)
                    for c in (concept.get("chapter_ids") or [])
                    if isinstance(c, (str, int))
                ]
                hint = str(concept.get("definition_hint") or "").strip()
                if slug in merged:
                    existing = merged[slug]
                    for a in aliases:
                        if a not in existing["aliases"]:
                            existing["aliases"].append(a)
                    for c in chapter_ids:
                        if c not in existing["chapter_ids"]:
                            existing["chapter_ids"].append(c)
                    if not existing.get("definition_hint") and hint:
                        existing["definition_hint"] = hint
                else:
                    merged[slug] = {
                        "canonical": slug,
                        "aliases": aliases,
                        "chapter_ids": chapter_ids,
                        "definition_hint": hint,
                    }

            concepts_out = list(merged.values())
            vocabulary: Dict[str, Any] = {
                "schema_version": "v1",
                "course_id": course_name.upper(),
                "course_slug": course_slug,
                "provider": getattr(provider, "_provider", ""),
                "model": getattr(provider, "_model", "") or "",
                # Repurposed to the TOTAL synthesis CALL count (now one per
                # WINDOW, not per chapter). The schema
                # (schemas/knowledge/domain_concept_vocabulary.schema.json)
                # sets additionalProperties:false, so a distinct
                # ``window_call_count`` field can't be added without a schema
                # change; no consumer requires this to equal len(chapters)
                # (the validator never reads it), so it carries the call count.
                "chapter_call_count": window_call_count,
                "chapter_synthesis_failures": chapter_synthesis_failures,
                "concept_count": len(concepts_out),
                "concepts": concepts_out,
            }
            # Underscore-prefixed transient the persist step pops before
            # writing (the vocabulary schema is additionalProperties:false);
            # surfaced on the phase-output envelope for operator visibility.
            vocabulary["_windows_reused_from_checkpoint"] = windows_reused

            # Aggregate Stage-3 window-synthesis decision (the provider
            # already emits one ``textbook_concept_call`` per call; this
            # records the windowing roll-up with dynamic signals).
            if _capture_concept is not None:
                try:
                    _capture_concept.log_decision(
                        decision_type="textbook_concept_call",
                        decision=(
                            f"windowed Stage-3 concept synthesis over "
                            f"{len(chapters)} chapter(s) into "
                            f"{window_call_count} window(s)"
                        ),
                        rationale=(
                            f"Stage-3 concept synthesis windowed each "
                            f"chapter's DART chunks (parity with Stage-2 "
                            f"objective windowing) so a mega-chapter corpus "
                            f"drives many concept calls. chapters="
                            f"{len(chapters)}, windows={window_call_count}, "
                            f"windows_synthesized={windows_synthesized}, "
                            f"windows_failed={windows_failed}, "
                            f"windows_reused_from_checkpoint={windows_reused} "
                            f"(reused windows skipped their 7B call verbatim "
                            f"from the resume sidecar), "
                            f"failed_chapters={chapter_synthesis_failures!r}, "
                            f"concepts_after_dedup={len(concepts_out)}, "
                            f"num_ctx={_num_ctx}, "
                            f"provider={getattr(provider, '_provider', '')!r}."
                        ),
                        ml_features={
                            "chapters": len(chapters),
                            "windows": window_call_count,
                            "windows_synthesized": windows_synthesized,
                            "windows_failed": windows_failed,
                            "windows_reused_from_checkpoint": windows_reused,
                            "concepts_after_dedup": len(concepts_out),
                            "num_ctx": _num_ctx,
                        },
                    )
                except Exception as exc:  # noqa: BLE001 — best-effort
                    logger.warning(
                        "concept_extraction: log_decision("
                        "textbook_concept_window_synthesis) failed (%s).",
                        exc,
                    )

            # --- all-fail → empty-seed fallback (plan §5.4) ----------------
            if chapters_synthesized == 0 or not concepts_out:
                logger.warning(
                    "concept_extraction: Stage-3 produced no concepts "
                    "(chapters_synthesized=%d, concepts=%d); falling back "
                    "to empty seeds — graph stays at status-quo.",
                    chapters_synthesized, len(concepts_out),
                )
                # Still return the (empty) vocabulary so the artifact +
                # gate surface the degraded provenance.
                return vocabulary

            # --- (d) compile into (canonical, [regex]) seed pairs ----------
            try:
                from Trainforge.process_course import (
                    compile_domain_concept_seeds,
                )
            except Exception as exc:  # noqa: BLE001 — import failure → skip
                logger.warning(
                    "concept_extraction: Stage-3 compile_domain_concept_seeds "
                    "import failed (%s); skipping re-tag.",
                    exc,
                )
                return vocabulary
            # Fix-1: de-slug the canonical id into a surface-form alias.
            # The merge step above overwrote ``canonical`` with the
            # ``canonical_slug`` (``visual-hierarchy``), which
            # ``compile_domain_concept_seeds`` regex-escapes into a literal
            # ``\bvisual\-hierarchy\b`` pattern that never matches the spaced
            # prose form "visual hierarchy". Append the hyphen-replaced
            # surface form as an alias (mirroring the lexical path below) so
            # the compiled pattern actually fires on the textbook text. Dedupe
            # against existing aliases; skip the alias when it collapses back
            # to the id (single-word slugs like ``accessibility`` where
            # ``replace("-", " ")`` is a no-op).
            _stage3_seed_specs: List[Dict[str, Any]] = []
            for c in concepts_out:
                _cid = c["canonical"]
                _aliases = list(c.get("aliases") or [])
                _deslug = _cid.replace("-", " ")
                if _deslug != _cid and _deslug not in _aliases:
                    _aliases.append(_deslug)
                _stage3_seed_specs.append({"id": _cid, "aliases": _aliases})
            seeds = compile_domain_concept_seeds(_stage3_seed_specs)

            # --- (e) re-tag each loaded chunk in-memory --------------------
            # IN-MEMORY only — chunks.jsonl on disk is NOT rewritten, so
            # dart_chunks_sha256 stays byte-stable (plan §4.2 Risk-6a).
            try:
                from lib.ontology.concept_tagging import extract_concept_tags
            except Exception as exc:  # noqa: BLE001 — import failure → skip
                logger.warning(
                    "concept_extraction: Stage-3 extract_concept_tags "
                    "import failed (%s); skipping re-tag.",
                    exc,
                )
                return vocabulary

            retagged = 0
            for chunk in chunks:
                if not isinstance(chunk, dict):
                    continue
                text = str(chunk.get("text") or "")
                if not text:
                    continue
                try:
                    new_tags = extract_concept_tags(
                        text, chunk, domain_concept_seeds=seeds
                    )
                except Exception as exc:  # noqa: BLE001 — isolate per chunk
                    logger.warning(
                        "concept_extraction: Stage-3 re-tag raised on "
                        "chunk %r (%s); leaving its tags untouched.",
                        chunk.get("id"), exc,
                    )
                    continue
                existing = chunk.get("concept_tags")
                existing = existing if isinstance(existing, list) else []
                # UNION — preserve any tags the chunk already carried.
                union = list(existing)
                for tag in new_tags:
                    if tag not in union:
                        union.append(tag)
                if union != existing:
                    retagged += 1
                chunk["concept_tags"] = union

            # The provider already emits one ``textbook_concept_call``
            # decision event per per-chapter call (plan §7) via
            # ``_emit_per_call_decision`` — the handler does not mint an
            # additional aggregate event. ``retagged`` is surfaced in the
            # phase-output envelope below for operator visibility.
            vocabulary["_chunks_retagged"] = retagged
            return vocabulary

        # ------------------------------------------------------------------
        # Three-stage textbook synthesis — Stage 3 (Wave C).
        #
        # plan: plans/textbook-llm-synthesis-3stage-2026-05.md §4.
        #
        # When ``TEXTBOOK_SYNTHESIS_PROVIDER`` is set, dispatch N
        # per-chapter ``synthesize_concepts`` LLM calls (batched ≤10 per
        # plan §5.3) over ``chapters[].chapter_text`` from
        # ``textbook_structure.json``, merge the per-chapter concepts
        # into a course-level vocabulary de-duped on ``canonical_slug``,
        # compile it into ``(canonical, [regex])`` seed pairs, and
        # re-tag the already-loaded chunks IN-MEMORY via
        # ``extract_concept_tags(..., domain_concept_seeds=...)``. The
        # re-tag UNIONs into each chunk's ``concept_tags`` so the
        # downstream ``build_cooccurrence_graph`` emits real
        # ``DomainConcept`` nodes for general (non-RDF) textbook prose —
        # the end-to-end payoff that closes the real-corpus 0-node failure.
        #
        # CRITICAL: the re-tag is in-memory only — ``chunks.jsonl`` on
        # disk is NOT rewritten, so ``dart_chunks_sha256`` stays
        # byte-stable (plan §4.2, Risk-6a). Per-chapter failure
        # isolation (plan §5.4): one chapter's call failing degrades
        # rather than aborts; all-fail → empty-seed fallback (status
        # quo). Default-off (env unset) → this block is a no-op and the
        # phase behaves exactly as today.
        # ------------------------------------------------------------------
        domain_concept_vocabulary: Optional[Dict[str, Any]] = None
        textbook_structure_path_kw = kwargs.get("textbook_structure_path") or ""
        _ts_provider_env = os.environ.get(
            "TEXTBOOK_SYNTHESIS_PROVIDER", ""
        ).strip()
        if _ts_provider_env:
            try:
                domain_concept_vocabulary = await _run_stage3_concept_synthesis(
                    chunks=chunks,
                    textbook_structure_path=textbook_structure_path_kw,
                    course_name=course_name,
                    course_slug=course_slug,
                    capture=_capture_concept,
                    checkpoint_path=_concept_checkpoint_path,
                )
            except GracefulStopRequested:
                # A graceful stop from the Stage-3 window loop is a PAUSE, not a
                # best-effort degrade — propagate it out AS-IS so the runner
                # stamps the phase ``paused`` and resume re-runs only the
                # un-attempted windows (the per-window sidecar already holds the
                # completed ones). This carve-out MUST precede the broad handler.
                raise
            except Exception as exc:  # noqa: BLE001 — Stage 3 is best-effort
                logger.warning(
                    "concept_extraction: Stage-3 concept synthesis raised "
                    "(%s); falling back to empty seeds (status quo).",
                    exc,
                )
                domain_concept_vocabulary = None

        # ------------------------------------------------------------------
        # Lexical concept-seed fallback (TRAINFORGE_LEXICAL_CONCEPT_SEEDS).
        #
        # Corpus-generalization fix: on a general (non-RDF/SHACL) textbook
        # corpus the Stage-3 LLM vocabulary pass (TEXTBOOK_SYNTHESIS_PROVIDER)
        # frequently does not run, leaving the per-course
        # ``domain_concept_seeds`` empty. Chunk tagging then matches only the
        # pedagogy-term CONCEPT_PATTERNS, every chunk lands ~2 tags, and the
        # co-occurrence + semantic graph collapses to a degenerate ~2-node
        # graph. This block derives domain-concept seeds from the loaded
        # chunk text using LEXICAL / statistical signals ONLY (frequency,
        # acronyms, multi-word noun phrases; no embeddings — SBIR posture),
        # compiles them, and re-tags the chunks IN-MEMORY (chunks.jsonl on
        # disk is NOT rewritten, so dart_chunks_sha256 stays byte-stable)
        # before the graph build below consumes them.
        #
        # CRITICAL — fires ONLY when:
        #   (a) TRAINFORGE_LEXICAL_CONCEPT_SEEDS is truthy, AND
        #   (b) Stage-3 produced no usable concept vocabulary (the empty-seed
        #       path that yields the degenerate graph).
        # When the flag is unset (default) OR Stage-3 seeds already exist,
        # this block is a no-op and behavior is byte-identical to today — the
        # RDF/SHACL calibration corpus (which has Stage-3 seeds and does not
        # set the flag) is unaffected.
        # ------------------------------------------------------------------
        lexical_seed_count = 0
        lexical_chunks_retagged = 0
        _lexical_flag = os.environ.get(
            "TRAINFORGE_LEXICAL_CONCEPT_SEEDS", ""
        ).strip().lower() in ("1", "true", "yes", "on")
        _stage3_has_seeds = (
            isinstance(domain_concept_vocabulary, dict)
            and int(domain_concept_vocabulary.get("concept_count", 0) or 0) > 0
        )
        if _lexical_flag and not _stage3_has_seeds:
            try:
                from lib.ontology.lexical_concept_seeds import (
                    derive_lexical_concept_seeds,
                )
                from Trainforge.process_course import (
                    compile_domain_concept_seeds,
                )
                from lib.ontology.concept_tagging import extract_concept_tags
            except Exception as exc:  # noqa: BLE001 — import failure → skip
                logger.warning(
                    "concept_extraction: lexical-seed fallback import failed "
                    "(%s); leaving chunks un-retagged (status quo).",
                    exc,
                )
            else:
                lexical_seeds = derive_lexical_concept_seeds(chunks)
                lexical_seed_count = len(lexical_seeds)
                if lexical_seeds:
                    compiled = compile_domain_concept_seeds([
                        {"id": s, "aliases": [s.replace("-", " ")]}
                        for s in lexical_seeds
                    ])
                    for chunk in chunks:
                        if not isinstance(chunk, dict):
                            continue
                        text = str(chunk.get("text") or "")
                        if not text:
                            continue
                        try:
                            new_tags = extract_concept_tags(
                                text, chunk, domain_concept_seeds=compiled
                            )
                        except Exception as exc:  # noqa: BLE001 — per-chunk
                            logger.warning(
                                "concept_extraction: lexical re-tag raised on "
                                "chunk %r (%s); leaving its tags untouched.",
                                chunk.get("id"), exc,
                            )
                            continue
                        existing = chunk.get("concept_tags")
                        existing = existing if isinstance(existing, list) else []
                        union = list(existing)
                        for tag in new_tags:
                            if tag not in union:
                                union.append(tag)
                        if union != existing:
                            lexical_chunks_retagged += 1
                        chunk["concept_tags"] = union
                if _capture_concept is not None:
                    try:
                        _capture_concept.log_decision(
                            decision_type="content_selection",
                            decision=(
                                f"lexical_concept_seed_fallback "
                                f"seeds={lexical_seed_count} "
                                f"retagged={lexical_chunks_retagged}"
                            ),
                            rationale=(
                                f"TRAINFORGE_LEXICAL_CONCEPT_SEEDS is on and "
                                f"Stage-3 produced no domain_concept_vocabulary "
                                f"seeds (the empty-seed path that yields a "
                                f"degenerate concept graph on general corpora). "
                                f"Derived {lexical_seed_count} domain-concept "
                                f"seeds from {len(chunks)} chunks via lexical / "
                                f"statistical signals only (frequency + "
                                f"acronyms + multi-word noun phrases; no "
                                f"embeddings per SBIR posture) and re-tagged "
                                f"{lexical_chunks_retagged} chunks in-memory "
                                f"before the co-occurrence graph build."
                            ),
                            alternatives_considered=[
                                "leave seeds empty (status-quo degenerate graph)",
                                "run Stage-3 LLM vocabulary synthesis",
                            ],
                        )
                    except Exception as exc:  # noqa: BLE001 — best-effort
                        logger.warning(
                            "concept_extraction: lexical-seed decision-capture "
                            "log_decision failed (%s).",
                            exc,
                        )

        # ------------------------------------------------------------------
        # Fix-2: emit the genuine ``kind: "concept_semantic"`` graph.
        #
        # Pre-Fix-2 this phase called ``build_pedagogy_graph`` and wrote a
        # ``kind: "pedagogy"`` graph to a file *named*
        # ``concept_graph_semantic.json`` — the file name lied about its
        # content. The genuine semantic graph (``DomainConcept`` nodes +
        # typed edges) was rebuilt only later inside
        # ``process_course.py::_generate_semantic_concept_graph``.
        #
        # Now the phase: (1) builds the co-occurrence concept graph from the
        # loaded chunks' ``concept_tags`` via the instance-free
        # ``build_cooccurrence_graph`` helper, then (2) feeds it to
        # ``build_semantic_graph`` (whose ``_build_nodes`` copies its node
        # set verbatim from the co-occurrence graph). ``course=None`` is
        # explicitly supported; ``objectives_metadata=None`` is fine
        # (Risk 1 — only the deferred ``targets-concept`` edge rule is
        # inert, an accepted gap). ``misconceptions`` / ``questions`` are
        # derived inline below, mirroring
        # ``process_course.py::_build_misconceptions_for_graph`` /
        # ``_build_questions_for_graph`` — this phase has no
        # ``CourseProcessor`` instance.
        # ------------------------------------------------------------------
        def _empty_semantic_shell() -> Dict[str, Any]:
            """A ``kind: "concept_semantic"`` empty-graph shell.

            Fix-2: the empty-input shell is no longer a pedagogy graph.
            """
            return {
                "kind": "concept_semantic",
                "course_id": course_name.upper(),
                "nodes": [],
                "edges": [],
                "generated_at": datetime.now().isoformat(),
                "stats": {
                    "node_count": 0,
                    "edge_count": 0,
                    "nodes_by_class": {},
                    "edges_by_relation": {},
                },
            }

        def _derive_misconceptions(
            chunk_list: List[Dict[str, Any]],
        ) -> List[Dict[str, Any]]:
            """Mirror ``CourseProcessor._build_misconceptions_for_graph``.

            Derives misconception entities from chunk ``misconceptions[]``
            so the ``misconception-of`` rule can fire. Concept routing
            precedence: explicit ``concept_id`` → token-overlap match →
            (implicitly) none.
            """
            try:
                from Trainforge.rag.typed_edge_inference import _make_concept_id
                from Trainforge.process_course import _route_misconception_to_tag
                from lib.ontology.misconception_id import canonical_mc_id
            except Exception:  # noqa: BLE001 — best-effort; rule self-skips on []
                return []
            entities: List[Dict[str, Any]] = []
            seen: set = set()
            cid_course = course_name.upper() or ""
            for chunk in chunk_list:
                raw = chunk.get("misconceptions") or []
                if not raw:
                    continue
                tags = [t for t in (chunk.get("concept_tags") or []) if t]
                for entry in raw:
                    if isinstance(entry, dict):
                        statement = (entry.get("misconception") or "").strip()
                        correction = (entry.get("correction") or "").strip()
                        explicit_cid = (
                            (entry.get("concept_id") or "").strip() or None
                        )
                        bloom_level = (
                            (entry.get("bloom_level") or "").strip().lower()
                        )
                        cognitive_domain = (
                            entry.get("cognitive_domain") or ""
                        ).strip()
                    elif isinstance(entry, str):
                        statement = entry.strip()
                        correction = ""
                        explicit_cid = None
                        bloom_level = ""
                        cognitive_domain = ""
                    else:
                        continue
                    if not statement:
                        continue
                    mc_id = canonical_mc_id(statement, correction, bloom_level)
                    if mc_id in seen:
                        continue
                    seen.add(mc_id)
                    entity: Dict[str, Any] = {
                        "id": mc_id,
                        "misconception": statement,
                        "correction": correction or statement,
                    }
                    if bloom_level:
                        entity["bloom_level"] = bloom_level
                    if cognitive_domain:
                        entity["cognitive_domain"] = cognitive_domain
                    concept_id = explicit_cid
                    if not concept_id and tags:
                        routed_tag = _route_misconception_to_tag(
                            statement, tags
                        )
                        if routed_tag:
                            concept_id = _make_concept_id(
                                routed_tag, cid_course
                            )
                    if concept_id:
                        entity["concept_id"] = concept_id
                    entities.append(entity)
            return entities

        def _derive_questions(
            chunk_list: List[Dict[str, Any]],
        ) -> List[Dict[str, Any]]:
            """Mirror ``CourseProcessor._build_questions_for_graph``.

            One question entity per ``learning_outcome_ref`` on every
            ``assessment_item`` chunk so the ``assesses`` rule can fire.
            """
            questions: List[Dict[str, Any]] = []
            for chunk in chunk_list:
                if chunk.get("chunk_type") != "assessment_item":
                    continue
                chunk_id = chunk.get("id")
                if not chunk_id:
                    continue
                for ref in chunk.get("learning_outcome_refs") or []:
                    if not ref:
                        continue
                    questions.append({
                        "id": f"q_{chunk_id}_{ref}",
                        "objective_id": ref,
                        "source_chunk_id": chunk_id,
                    })
            return questions

        # ------------------------------------------------------------------
        # NVIDIA-KG item 1: thread the synthesized course objectives into
        # the typed-edge build. Passing ``course=None`` +
        # ``objectives_metadata=None`` makes the LO-dependent rules
        # (``prerequisite_from_lo_order``, ``targets_concept_from_lo``)
        # early-return with zero edges on every course, so the graph builds
        # with no prerequisite edges at all.
        # Resolution chain: explicit ``objectives_path`` kwarg (routed
        # from the ``reuse_objectives_path`` workflow param) → project
        # export ``01_learning_objectives/synthesized_objectives.json``
        # → project export ``03_content_development/course.json`` →
        # ``LibV2/courses/<slug>/course.json``. Missing objectives
        # degrade to the legacy ``course=None`` path with a warning —
        # never fail the phase. Deterministic (pure file reads, no LLM).
        # ------------------------------------------------------------------
        course_for_graph: Optional[Dict[str, Any]] = None
        objectives_meta_for_graph: Optional[List[Dict[str, Any]]] = None
        objectives_source = ""
        # Phase-ordering fix (Option A1): count of LOs the relocated
        # concept-objective linker enriched with key_concepts[] (0 until
        # the linker runs below; surfaced in the envelope).
        key_concepts_linked = 0
        try:
            course_for_graph, objectives_meta_for_graph, objectives_source = (
                _resolve_course_objectives_for_graph(
                    objectives_path_kw=str(
                        kwargs.get("objectives_path") or ""
                    ),
                    # Phase-ordering fix (Option A1): the fresh-run
                    # objectives source, routed from course_planning's
                    # synthesized_objectives_path (this phase now runs
                    # AFTER course_planning). Candidate #2 — the reuse
                    # kwarg above still wins when supplied.
                    synthesized_objectives_path_kw=str(
                        kwargs.get("synthesized_objectives_path") or ""
                    ),
                    project_path=project_path,
                    libv2_course_dir=(
                        _resolve_libv2_root(kwargs.get("libv2_root"))
                        / "courses"
                        / course_slug
                    ),
                    course_code=course_name.upper(),
                )
            )
        except Exception as exc:  # noqa: BLE001 — resolution is best-effort
            logger.warning(
                "concept_extraction: objectives resolution raised (%s); "
                "degrading to course=None.",
                exc,
            )
        if course_for_graph is None:
            logger.warning(
                "concept_extraction: no synthesized objectives resolvable "
                "for course %s (reuse objectives_path kwarg / "
                "course_planning synthesized_objectives_path / project "
                "export / LibV2 course.json all missing); LO-driven "
                "typed-edge rules (prerequisite_from_lo_order, "
                "targets_concept_from_lo) will emit zero edges. Phase-"
                "ordering fix (Option A1) makes course_planning run BEFORE "
                "this phase, so on a fresh textbook_to_course run this "
                "indicates course_planning did NOT emit objectives "
                "(synthesized_objectives.json missing/empty) — investigate "
                "the upstream phase rather than treating this as expected.",
                course_name,
            )
        else:
            logger.info(
                "concept_extraction: resolved %d learning outcomes from %s "
                "(+%d targets-concept metadata entries) for the typed-edge "
                "build.",
                len(course_for_graph.get("learning_outcomes") or []),
                objectives_source,
                len(objectives_meta_for_graph or []),
            )

        # ------------------------------------------------------------------
        # Fix-2: seed the resolved objectives' key_concepts into the chunk
        # retag BEFORE the co-occurrence graph build.
        #
        # The synthesized objectives carry per-LO ``key_concepts`` as slugs
        # (``design-system``, ``visual-hierarchy``, ...). Those slugs drive
        # the ``targets_concept_from_lo`` typed-edge rule, whose target
        # endpoint is the SAME slug. When that slug isn't already a real
        # co-occurrence node, ``_materialize_endpoint_nodes`` mints a
        # ``frequency=0, node_provenance="lo_key_concept"`` orphan — a node
        # with NO chunk anchoring, which drags down the chunk-anchored
        # coverage floor. By compiling each key_concept slug (with its
        # de-slugged surface-form alias, mirroring the Stage-3 / lexical
        # paths) into a domain-concept seed and union-retagging the in-memory
        # chunks here, a key_concept that actually appears in prose lands in
        # ≥2 chunks → mints a real co-occurrence node → the targets-concept
        # edge resolves to a grounded node instead of a frequency=0 orphan.
        # A key_concept ABSENT from the prose still falls through to the
        # legacy lo_key_concept materialization (behavior preserved).
        #
        # IN-MEMORY only — chunks.jsonl on disk is NOT rewritten (same
        # contract as the Stage-3 / lexical retag blocks above), so
        # dart_chunks_sha256 stays byte-stable.
        # ------------------------------------------------------------------
        lo_key_concept_seed_count = 0
        lo_key_concept_chunks_retagged = 0
        if course_for_graph is not None:
            try:
                from Trainforge.process_course import (
                    compile_domain_concept_seeds as _compile_lo_seeds,
                )
                from lib.ontology.concept_tagging import (
                    extract_concept_tags as _extract_lo_tags,
                )
                from lib.ontology.slugs import canonical_slug as _kc_slug
            except Exception as exc:  # noqa: BLE001 — import failure → skip
                logger.warning(
                    "concept_extraction: LO key_concept seed import failed "
                    "(%s); skipping LO-concept retag.",
                    exc,
                )
            else:
                _kc_slugs: List[str] = []
                _seen_kc: set = set()
                for _lo in course_for_graph.get("learning_outcomes") or []:
                    if not isinstance(_lo, dict):
                        continue
                    _kcs = _lo.get("key_concepts") or _lo.get("keyConcepts")
                    if not isinstance(_kcs, list):
                        continue
                    for _kc in _kcs:
                        if not isinstance(_kc, str):
                            continue
                        _slug = _kc_slug(_kc)
                        if _slug and _slug not in _seen_kc:
                            _seen_kc.add(_slug)
                            _kc_slugs.append(_slug)
                if _kc_slugs:
                    _lo_seed_specs: List[Dict[str, Any]] = []
                    for _slug in _kc_slugs:
                        _aliases = []
                        _deslug = _slug.replace("-", " ")
                        if _deslug != _slug:
                            _aliases.append(_deslug)
                        _lo_seed_specs.append(
                            {"id": _slug, "aliases": _aliases}
                        )
                    try:
                        _lo_seeds = _compile_lo_seeds(_lo_seed_specs)
                    except Exception as exc:  # noqa: BLE001 — compile failure
                        logger.warning(
                            "concept_extraction: LO key_concept seed compile "
                            "failed (%s); skipping LO-concept retag.",
                            exc,
                        )
                        _lo_seeds = []
                    lo_key_concept_seed_count = len(_lo_seeds)
                    for _chunk in chunks:
                        if not isinstance(_chunk, dict):
                            continue
                        _text = str(_chunk.get("text") or "")
                        if not _text or not _lo_seeds:
                            continue
                        try:
                            _new_tags = _extract_lo_tags(
                                _text, _chunk, domain_concept_seeds=_lo_seeds
                            )
                        except Exception as exc:  # noqa: BLE001 — per-chunk
                            logger.warning(
                                "concept_extraction: LO key_concept retag "
                                "raised on chunk %r (%s); leaving its tags "
                                "untouched.",
                                _chunk.get("id"), exc,
                            )
                            continue
                        _existing = _chunk.get("concept_tags")
                        _existing = (
                            _existing if isinstance(_existing, list) else []
                        )
                        _union = list(_existing)
                        for _tag in _new_tags:
                            if _tag not in _union:
                                _union.append(_tag)
                        if _union != _existing:
                            lo_key_concept_chunks_retagged += 1
                        _chunk["concept_tags"] = _union
                    if lo_key_concept_seed_count:
                        logger.info(
                            "concept_extraction: LO key_concept retag seeded "
                            "%d key_concepts and re-tagged %d chunks in-memory "
                            "before the co-occurrence graph build.",
                            lo_key_concept_seed_count,
                            lo_key_concept_chunks_retagged,
                        )

        try:
            from lib.ontology.cooccurrence_graph import build_cooccurrence_graph
            from Trainforge.rag.typed_edge_inference import build_semantic_graph
        except Exception as exc:  # noqa: BLE001 — import failures shouldn't crash phase
            logger.warning(
                "concept_extraction: semantic-graph builder import failed "
                "(%s); emitting empty concept_semantic graph shell.",
                exc,
            )
            graph: Dict[str, Any] = _empty_semantic_shell()
        else:
            try:
                # W3 page-aggregation: regroup the cooccurrence pair-counting
                # unit from chunk to page/section. Default "page" for the
                # generalized textbook_to_course / course_generation runs (set
                # by _apply_corpus_generalization_defaults); "chunk" when the
                # env is unset for byte-stable legacy library calls. Node
                # frequency + occurrences stay chunk-level either way.
                cooccurrence_group_by = (
                    os.environ.get("TRAINFORGE_COOCCURRENCE_GROUP_BY", "").strip()
                    or "chunk"
                )
                cooccurrence_graph = build_cooccurrence_graph(
                    chunks,
                    course_name.upper() or "",
                    graph_kind="concept",
                    group_by=cooccurrence_group_by,
                )

                # Phase-ordering fix (Option A1): concept-objective linker
                # pass (relocated here from _plan_course_structure). With
                # this phase now running AFTER course_planning, the concept
                # graph (cooccurrence_graph) exists at the SAME time as the
                # synthesized objectives, so the linker can populate each
                # LO's key_concepts[] from concept-graph nodes BEFORE
                # build_semantic_graph runs — which lets the
                # targets_concept_from_lo typed-edge rule (driven off the
                # objectives_metadata derived from key_concepts) emit real
                # edges on a fresh run. We then re-normalize the enriched
                # LO list so course_for_graph + objectives_meta_for_graph
                # reflect the linked key_concepts. Fail-soft: a linker
                # error leaves the un-enriched objectives in place.
                if course_for_graph is not None:
                    try:
                        from lib.ontology.concept_objective_linker import (
                            link_concepts_to_objectives,
                        )

                        _enriched_los = link_concepts_to_objectives(
                            course_for_graph.get("learning_outcomes") or [],
                            cooccurrence_graph,
                        )
                        _relinked_course, _relinked_meta = (
                            _normalize_objectives_payload_to_course(
                                {
                                    "learning_outcomes": _enriched_los,
                                    "course_code": course_name.upper(),
                                },
                                course_name.upper(),
                            )
                        )
                        if _relinked_course is not None:
                            course_for_graph = _relinked_course
                            objectives_meta_for_graph = _relinked_meta
                            key_concepts_linked = sum(
                                1
                                for _lo in _enriched_los
                                if (
                                    _lo.get("key_concepts")
                                    or _lo.get("keyConcepts")
                                )
                            )
                            logger.info(
                                "concept_extraction: concept-objective "
                                "linker enriched key_concepts on %d/%d "
                                "learning outcomes from the concept graph.",
                                key_concepts_linked,
                                len(_enriched_los),
                            )
                    except Exception as exc:  # noqa: BLE001 — fail-soft
                        logger.warning(
                            "concept_extraction: concept-objective linker "
                            "pass failed (%s); proceeding with un-enriched "
                            "objectives.",
                            exc,
                        )

                misconceptions = _derive_misconceptions(chunks)
                questions = _derive_questions(chunks)

                # W3.1 content-dependency prerequisite rule
                # (prerequisite_from_definition_mention). Default-OFF and
                # gated on TRAINFORGE_PREREQ_DEFINITION_MENTION: when off we
                # pass NEITHER the decision_capture NOR the terminal-objective
                # set, so build_semantic_graph is byte-identical to the legacy
                # call (decision_capture feeds the per-node/edge run_id
                # fallback, so passing it unconditionally would change the
                # graph bytes even off). When on, we thread the real synthesized
                # TERMINAL objectives (pins the canonical TO-NN id form the
                # rule emits) + the phase DecisionCapture (one
                # typed_edge_inference event per edge-producing call). The rule
                # is CONDITIONALLY registered inside build_semantic_graph on the
                # same flag so rule_versions / concept_graph_sha256 stay
                # byte-identical when off. Fail-soft: any error resolving the
                # flag or filtering the terminal set degrades to the legacy call.
                _prereq_def_mention_capture = None
                _prereq_terminal_objectives = None
                try:
                    from lib.generation.prerequisite_from_definition_mention import (
                        resolve_prereq_definition_mention as _resolve_prereq_dm,
                    )

                    if _resolve_prereq_dm():
                        _prereq_def_mention_capture = _capture_concept
                        if course_for_graph is not None:
                            from lib.ontology.learning_objectives import (
                                hierarchy_from_id,
                                validate_lo_id,
                            )

                            _terminals: List[Dict[str, Any]] = []
                            for _lo in (
                                course_for_graph.get("learning_outcomes") or []
                            ):
                                if not isinstance(_lo, dict):
                                    continue
                                _lid = _lo.get("id")
                                if not isinstance(_lid, str) or not validate_lo_id(
                                    _lid.strip().upper()
                                ):
                                    continue
                                try:
                                    _is_terminal = (
                                        hierarchy_from_id(_lid.strip().upper())
                                        == "terminal"
                                    )
                                except ValueError:
                                    _is_terminal = False
                                if _is_terminal:
                                    _terminals.append(_lo)
                            _prereq_terminal_objectives = _terminals or None
                except Exception as exc:  # noqa: BLE001 — fail-soft
                    logger.warning(
                        "concept_extraction: prereq-definition-mention wiring "
                        "resolve failed (%s); running the legacy graph build.",
                        exc,
                    )
                    _prereq_def_mention_capture = None
                    _prereq_terminal_objectives = None

                graph = build_semantic_graph(
                    chunks,
                    course=course_for_graph,
                    concept_graph=cooccurrence_graph,
                    misconceptions=misconceptions or None,
                    questions=questions or None,
                    objectives_metadata=objectives_meta_for_graph,
                    terminal_objectives=_prereq_terminal_objectives,
                    decision_capture=_prereq_def_mention_capture,
                )
                # ``build_semantic_graph`` stamps ``kind: "concept_semantic"``;
                # add ``course_id`` for parity with the legacy shell shape.
                if isinstance(graph, dict):
                    graph.setdefault("course_id", course_name.upper())

                # KG-quality post-build passes (all default-OFF for byte
                # stability). Order is load-bearing: scaffolding-node prune
                # (Change B) already ran upstream at co-occurrence build
                # time; here we (C) merge duplicate concept nodes, then
                # (A) cap related-to fan-out on the post-merge edge set.
                # Each is an independent, fail-soft dict->dict rewrite.
                if isinstance(graph, dict):
                    if os.getenv(
                        "TRAINFORGE_MERGE_DUPLICATE_CONCEPTS", ""
                    ).lower() == "true":
                        try:
                            from lib.ontology.concept_node_merge import (
                                merge_duplicate_concept_nodes,
                            )
                            graph = merge_duplicate_concept_nodes(graph)
                        except Exception as exc:  # noqa: BLE001 — fail-soft
                            logger.warning(
                                "concept_extraction: concept-merge pass "
                                "failed (%s); leaving graph unmerged.", exc,
                            )
                    # Intra-chunk concept linking (after merge, before cap):
                    # connect concepts co-located in the same chunk with a
                    # low-confidence related-to, so single-section topics
                    # (e.g. LangGraph) don't shatter into degree-1 singletons.
                    if os.getenv(
                        "TRAINFORGE_INTRA_CHUNK_LINKS", ""
                    ).lower() == "true":
                        try:
                            from lib.ontology.intra_chunk_linker import (
                                link_intra_chunk_concepts,
                            )
                            graph = link_intra_chunk_concepts(graph)
                        except Exception as exc:  # noqa: BLE001 — fail-soft
                            logger.warning(
                                "concept_extraction: intra-chunk linking pass "
                                "failed (%s); leaving graph unlinked.", exc,
                            )
                    _fanout_k = os.getenv(
                        "TRAINFORGE_RELATED_FANOUT_CAP", ""
                    ).strip()
                    if _fanout_k.isdigit() and int(_fanout_k) > 0:
                        try:
                            from lib.ontology.related_edge_cap import (
                                cap_related_fanout,
                            )
                            graph = cap_related_fanout(graph, int(_fanout_k))
                        except Exception as exc:  # noqa: BLE001 — fail-soft
                            logger.warning(
                                "concept_extraction: related-to fan-out cap "
                                "failed (%s); leaving edges uncapped.", exc,
                            )
            except Exception as exc:  # noqa: BLE001 — fail-soft on builder error
                logger.warning(
                    "concept_extraction: build_semantic_graph raised (%s); "
                    "emitting empty concept_semantic graph shell.",
                    exc,
                )
                graph = _empty_semantic_shell()

        # Phase-ordering fix (Option A1): write the linker-enriched
        # key_concepts back to the project-export synthesized_objectives.json
        # so the persisted LO doc carries the same keyConcepts the
        # _plan_course_structure linker used to write before the phase move.
        # Guard rails:
        #   * Only when the linker actually enriched something
        #     (key_concepts_linked > 0) and a course was resolved.
        #   * NEVER mutate the reuse kwarg path (a user-supplied file) — we
        #     only write back when objectives_source resolved to the project
        #     export's synthesized_objectives.json (i.e. NOT the
        #     reuse_objectives_path).
        # Best-effort: a merge/write error logs a warning and does not fail
        # the phase.
        reuse_objectives_kwarg = str(kwargs.get("objectives_path") or "")
        if (
            key_concepts_linked > 0
            and course_for_graph is not None
            and objectives_source
            and objectives_source.endswith("synthesized_objectives.json")
            and objectives_source != reuse_objectives_kwarg
        ):
            try:
                _enriched_by_id = {
                    str(lo.get("id")): lo
                    for lo in (course_for_graph.get("learning_outcomes") or [])
                    if isinstance(lo, dict) and lo.get("id")
                }
                _src_path = Path(objectives_source)
                _doc = json.loads(_src_path.read_text(encoding="utf-8"))
                _merged = 0
                for _disk_lo in (_doc.get("learning_outcomes") or []):
                    if not isinstance(_disk_lo, dict):
                        continue
                    _enr = _enriched_by_id.get(str(_disk_lo.get("id")))
                    if _enr is None:
                        continue
                    _kc = _enr.get("key_concepts") or _enr.get("keyConcepts")
                    if isinstance(_kc, list) and _kc:
                        # Preserve the disk LO's existing casing if present,
                        # else default to key_concepts (the runtime form
                        # _plan_course_structure emits).
                        _field = (
                            "keyConcepts"
                            if "keyConcepts" in _disk_lo
                            else "key_concepts"
                        )
                        _disk_lo[_field] = list(_kc)
                        _merged += 1
                if _merged:
                    _src_path.write_text(
                        json.dumps(_doc, indent=2, ensure_ascii=False),
                        encoding="utf-8",
                    )
                    logger.info(
                        "concept_extraction: merged linker-enriched "
                        "key_concepts back into %d LO entries of %s.",
                        _merged, _src_path,
                    )
            except Exception as exc:  # noqa: BLE001 — fail-soft
                logger.warning(
                    "concept_extraction: key_concepts write-back to "
                    "synthesized_objectives.json failed (%s); the on-disk "
                    "objectives doc keeps its prior key_concepts.", exc,
                )

        # Edge-consensus stamping (GPT-fb-12-may item 2). Runs
        # UNCONDITIONALLY — not behind a behavior flag — because the
        # root CLAUDE.md § Aggregators documents EdgeConsensusAggregator
        # as the source of the per-edge ``edge_status`` +
        # ``consensus_signals[]`` fields on the SEMANTIC graph. Pre-fix,
        # this aggregator only ran post-loop in workflow_runner for the
        # ``graph/`` artifact (process_course path) and was NEVER wired
        # into the ``concept_extraction`` phase, so every course archived
        # via the textbook_to_course pipeline shipped a
        # concept_graph_semantic.json with edge_status=None on all edges
        # and no sibling edge_consensus_report.json (verified on a
        # calibration corpus: 982 edges, all edge_status=None, no report).
        # Stamping here — at the authoring point — closes the silent gap
        # for every course rather than patching one corpus. Deterministic
        # (cross-rule matrix only; no LLM, no NLI unless TRAINFORGE_EDGE_NLI),
        # so the graph stays byte-reproducible for fixed inputs. Fail-soft:
        # a stamping error leaves the graph un-stamped rather than failing
        # the phase, matching the best-effort posture of the post-loop
        # aggregators in workflow_runner.
        edge_consensus_report_path: str = ""
        if isinstance(graph, dict) and graph.get("edges"):
            try:
                from lib.aggregators.edge_consensus import (
                    EdgeConsensusAggregator,
                    chunk_text_lookup_from_chunks,
                )

                _run_id = (
                    kwargs.get("run_id")
                    or os.getenv("ED4ALL_RUN_ID", "")
                    or ""
                )
                # TRAINFORGE_EDGE_NLI: thread the in-memory chunk text so the
                # NLI extension can score chunk-anchored edges. None when the
                # flag is off / chunks carry no text → extension no-ops.
                _nli_lookup = chunk_text_lookup_from_chunks(chunks)
                _consensus = EdgeConsensusAggregator(
                    semantic_graph_path=None,
                    course_slug=course_slug,
                    run_id=str(_run_id),
                    chunk_text_lookup=_nli_lookup,
                )
                # Stamp edge_status + consensus_signals[] in place on the
                # freshly-built graph dict before it is serialized.
                _consensus.apply_to_graph(graph)
            except Exception as exc:  # noqa: BLE001 — fail-soft
                logger.warning(
                    "concept_extraction: edge-consensus stamping failed "
                    "(%s); graph edges left without edge_status.", exc,
                )

        # KG-quality stamping (NVIDIA-KG item 2). Runs AFTER edge-consensus
        # stamping (above) so the consistency axis's
        # (1 - contradiction_rate) attenuation reads the freshly-stamped
        # per-edge ``edge_status`` — composing with, not duplicating, the
        # gate-time attenuation that ``KGQualityValidator.validate`` applies
        # via the EdgeConsensusAggregator. Pre-fix, every textbook_to_course
        # corpus shipped a concept_graph_semantic.json with kg_quality=None
        # (verified on a calibration corpus: 197 nodes / 982 edges, kg_quality
        # null, no sibling quality/ report) because the KG-quality reporter
        # only ran as a gate at libv2_archival and never stamped the field
        # at authoring time. Uses the report-less ``compute_metrics_only``
        # entry point — no SHACL ValidationReport (none exists at this
        # phase), no LLM, deterministic. Fail-soft: any error logs a warning
        # and leaves ``kg_quality`` null, matching the consensus-stamping
        # posture (never fails the phase). The report dict is captured here
        # and written to ``quality/kg_quality_report.json`` after the LibV2
        # course dir is resolved below.
        kg_quality_report: Optional[Dict[str, Any]] = None
        if isinstance(graph, dict):
            try:
                from Trainforge.rag.kg_quality_report import KGQualityReporter

                _run_id_kgq = (
                    kwargs.get("run_id")
                    or os.getenv("ED4ALL_RUN_ID", "")
                    or ""
                )
                _kgq_reporter = KGQualityReporter(
                    course_slug=course_slug,
                    run_id=str(_run_id_kgq),
                    output_dir=Path("."),  # overridden at write time below
                )
                kg_quality_report = _kgq_reporter.compute_metrics_only(graph)
                # Stamp the compact four-dimension score block onto the
                # graph so the in-graph kg_quality field is no longer null.
                _kgq_dims = kg_quality_report.get("dimensions") or {}
                graph["kg_quality"] = {
                    dim: float(
                        (_kgq_dims.get(dim) or {}).get("score", 0.0)
                    )
                    for dim in (
                        "completeness", "consistency", "accuracy", "coverage"
                    )
                }
            except Exception as exc:  # noqa: BLE001 — fail-soft
                logger.warning(
                    "concept_extraction: kg-quality computation failed "
                    "(%s); graph kg_quality left null.", exc,
                )

        # Persist graph to LibV2/courses/<slug>/concept_graph/.
        # Phase 8 ST 3: route through `_resolve_libv2_root` so ops
        # topologies that mount LibV2 at a non-default location can
        # override via `ED4ALL_LIBV2_ROOT` env var or per-call
        # `libv2_root` kwarg threaded by the workflow runner.
        course_dir = (
            _resolve_libv2_root(kwargs.get("libv2_root"))
            / "courses"
            / course_slug
        )
        graph_dir = course_dir / "concept_graph"
        graph_dir.mkdir(parents=True, exist_ok=True)
        graph_path = graph_dir / "concept_graph_semantic.json"
        graph_bytes = json.dumps(graph, indent=2, ensure_ascii=False).encode(
            "utf-8"
        )
        graph_path.write_bytes(graph_bytes)
        sha256 = _hashlib.sha256(graph_bytes).hexdigest()

        # Sibling manifest.json with provenance fields the LibV2 manifest
        # validator can later cross-check (Phase 6 ST 17 wires the field
        # into the canonical course manifest schema; ST 12 emits it here
        # eagerly so the per-phase output is self-describing).
        manifest = {
            "course_id": course_name.upper(),
            "course_slug": course_slug,
            "concept_graph_path": str(graph_path),
            "concept_graph_sha256": sha256,
            "generated_at": datetime.now().isoformat(),
            "source_chunks": len(chunks),
            "phase": "concept_extraction",
        }
        manifest_path = graph_dir / "manifest.json"
        # W0.7: atomic temp-then-replace manifest write.
        _atomic_write_text(
            manifest_path,
            json.dumps(manifest, indent=2, ensure_ascii=False),
        )

        # Sibling edge_consensus_report.json (GPT-fb-12-may item 2). Written
        # next to the just-serialized concept_graph_semantic.json so a LibV2
        # audit can read the corpus-wide consensus rollup (per-rule
        # confirmed/contradicted/pending counts + contradiction_rate) without
        # re-walking the edge list. Reads from the on-disk graph (which now
        # carries the stamped edge_status) so the report and the graph agree.
        # Best-effort: a report-write failure does not fail the phase.
        if isinstance(graph, dict) and graph.get("edges"):
            try:
                from lib.aggregators.edge_consensus import (
                    EdgeConsensusAggregator,
                    chunk_text_lookup_from_chunks,
                )

                _run_id = (
                    kwargs.get("run_id")
                    or os.getenv("ED4ALL_RUN_ID", "")
                    or ""
                )
                # Same chunk-text lookup as the authoring apply_to_graph above
                # so the report's retracted counts agree with the stamped graph
                # when TRAINFORGE_EDGE_NLI is on.
                _nli_lookup = chunk_text_lookup_from_chunks(chunks)
                _report_path = graph_dir / "edge_consensus_report.json"
                EdgeConsensusAggregator(
                    semantic_graph_path=graph_path,
                    course_slug=course_slug,
                    run_id=str(_run_id),
                    chunk_text_lookup=_nli_lookup,
                ).write(_report_path)
                edge_consensus_report_path = str(_report_path)
            except Exception as exc:  # noqa: BLE001 — fail-soft
                logger.warning(
                    "concept_extraction: edge_consensus_report.json write "
                    "failed (%s); the consensus rollup was not persisted "
                    "(the graph's per-edge edge_status is unaffected).", exc,
                )

        # Sibling kg_quality_report.json under the LibV2 course's quality/
        # dir (NVIDIA-KG item 2). Follows the dir convention documented in
        # root CLAUDE.md § Aggregators for the assessment aggregator
        # (``<libv2_course>/quality/trainforge_assessment_quality_report.json``).
        # The full four-dimension report (computed above via
        # compute_metrics_only) is persisted here so a LibV2 audit reads the
        # numerator/denominator + contradiction_rate detail without
        # re-walking the graph. Best-effort: a write failure does not fail
        # the phase, and the in-graph kg_quality block is unaffected.
        kg_quality_report_path: str = ""
        if kg_quality_report is not None:
            try:
                quality_dir = course_dir / "quality"
                quality_dir.mkdir(parents=True, exist_ok=True)
                _kgq_path = quality_dir / "kg_quality_report.json"
                _kgq_path.write_text(
                    json.dumps(
                        kg_quality_report, indent=2, ensure_ascii=False
                    ),
                    encoding="utf-8",
                )
                kg_quality_report_path = str(_kgq_path)
            except Exception as exc:  # noqa: BLE001 — fail-soft
                logger.warning(
                    "concept_extraction: kg_quality_report.json write failed "
                    "(%s); the KG-quality rollup was not persisted (the "
                    "graph's kg_quality block is unaffected).", exc,
                )

        # Three-stage textbook synthesis — Stage 3 (Wave C, plan §4.3).
        # Persist the merged domain-concept vocabulary as a sibling of
        # concept_graph_semantic.json. Written only when Stage 3 ran
        # (TEXTBOOK_SYNTHESIS_PROVIDER set + a usable textbook structure)
        # — a default-off run leaves no domain_concept_vocabulary.json,
        # and the domain_concept_vocabulary gate skips-with-pass.
        domain_concept_vocabulary_path: str = ""
        domain_concept_count: int = 0
        chunks_retagged: int = 0
        concept_windows_reused: int = 0
        if isinstance(domain_concept_vocabulary, dict):
            chunks_retagged = int(
                domain_concept_vocabulary.pop("_chunks_retagged", 0) or 0
            )
            # Pop the transient reuse counter before persist (the vocabulary
            # schema is additionalProperties:false); surface it on the phase
            # envelope so operators see how many Stage-3 7B window calls a
            # resume skipped from the checkpoint sidecar.
            concept_windows_reused = int(
                domain_concept_vocabulary.pop(
                    "_windows_reused_from_checkpoint", 0
                ) or 0
            )
            domain_concept_count = int(
                domain_concept_vocabulary.get("concept_count", 0) or 0
            )
            vocab_path = graph_dir / "domain_concept_vocabulary.json"
            try:
                vocab_path.write_text(
                    json.dumps(
                        domain_concept_vocabulary,
                        indent=2,
                        ensure_ascii=False,
                    ),
                    encoding="utf-8",
                )
                domain_concept_vocabulary_path = str(vocab_path)
            except OSError as exc:
                logger.warning(
                    "concept_extraction: failed to persist "
                    "domain_concept_vocabulary.json (%s); the Stage-3 "
                    "vocabulary artifact was not written.",
                    exc,
                )

        envelope: Dict[str, Any] = {
            "success": True,
            "concept_graph_path": str(graph_path),
            "concept_graph_sha256": sha256,
            "manifest_path": str(manifest_path),
            "course_slug": course_slug,
            "chunk_count": len(chunks),
            "node_count": len(graph.get("nodes") or []),
            "edge_count": len(graph.get("edges") or []),
            # M2 fix: surface inline-projection drop counts so workflow
            # consumers see the silent-degradation signal without parsing
            # logs. ``projection_drops`` carries the first 10 drop records
            # for postmortem readability; the count is authoritative.
            "projection_drops_count": len(projection_drops),
            "projection_drops": projection_drops[:10],
            # NVIDIA-KG item 1: surface where the LO ordering came from
            # (empty string = course=None degraded path) so operators can
            # tell from the phase output whether the LO-driven typed-edge
            # rules had a chance to fire.
            "objectives_source": objectives_source,
            "learning_outcome_count": len(
                (course_for_graph or {}).get("learning_outcomes") or []
            ),
            # Phase-ordering fix (Option A1): how many LOs the relocated
            # concept-objective linker enriched with key_concepts[] from
            # the concept graph this run.
            "key_concepts_linked": key_concepts_linked,
            # Merge-vs-LO-edges fix: count of graph nodes materialized by
            # typed_edge_inference._materialize_endpoint_nodes for an
            # unresolved targets-concept (LO key_concepts) target. > 0 means
            # the LO author named concepts the corpus chunks never tagged, now
            # carried as provenance-flagged DomainConcept nodes instead of
            # dropped targets-concept edges.
            "lo_concept_nodes_materialized": sum(
                1
                for n in (graph.get("nodes") or [])
                if isinstance(n, dict)
                and n.get("node_provenance") == "lo_key_concept"
            ),
        }
        # Edge-consensus rollup sibling (GPT-fb-12-may item 2). Present
        # whenever the graph carried edges and the report wrote cleanly.
        if edge_consensus_report_path:
            envelope["edge_consensus_report_path"] = (
                edge_consensus_report_path
            )
        # KG-quality rollup sibling (NVIDIA-KG item 2). Present whenever the
        # report computed + wrote cleanly.
        if kg_quality_report_path:
            envelope["kg_quality_report_path"] = kg_quality_report_path
        # Stage-3 (Wave C) output keys. Empty / zero on a default-off run.
        if domain_concept_vocabulary_path:
            envelope["domain_concept_vocabulary_path"] = (
                domain_concept_vocabulary_path
            )
            envelope["domain_concept_count"] = domain_concept_count
            envelope["chunks_retagged"] = chunks_retagged
            # Per-window resume-checkpoint reuse counter (0 on a fresh /
            # uninterrupted run; > 0 when a resume skipped completed 7B
            # window calls from the sidecar).
            envelope["concept_windows_reused_from_checkpoint"] = (
                concept_windows_reused
            )
        # Lexical-seed fallback output keys (TRAINFORGE_LEXICAL_CONCEPT_SEEDS).
        # Present only when the flag fired (off by default → absent).
        if lexical_seed_count:
            envelope["lexical_concept_seed_count"] = lexical_seed_count
            envelope["lexical_chunks_retagged"] = lexical_chunks_retagged
        # Fix-2 LO key_concept retag output keys. Present only when the
        # resolved objectives carried key_concepts to seed (absent otherwise).
        if lo_key_concept_seed_count:
            envelope["lo_key_concept_seed_count"] = lo_key_concept_seed_count
            envelope["lo_key_concept_chunks_retagged"] = (
                lo_key_concept_chunks_retagged
            )
        return json.dumps(envelope)

    registry["run_concept_extraction"] = _run_concept_extraction

    # ============================================================================
    # Phase 7b Subtask 11: _run_dart_chunking — DART chunkset emit
    #
    # New ``chunking`` workflow phase (between ``staging`` and
    # ``objective_extraction`` per Phase 7b ST 10). The phase invokes
    # ``Trainforge.chunker.chunk_content`` over staged DART HTML files,
    # persists the resulting chunks to
    # ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl`` plus a sibling
    # ``manifest.json`` (matching the canonical
    # ``schemas/library/chunkset_manifest.schema.json`` shape), computes
    # the SHA-256 of the chunks file, and surfaces both the path and
    # hash through phase outputs.
    #
    # Mirrors the ``_run_concept_extraction`` template above (Phase 6
    # ST 12 commit ``e0ea640``): async helper, ``**kwargs`` resolved via
    # the workflow YAML's ``inputs_from``, registered in
    # ``_build_tool_registry`` as ``registry["run_dart_chunking"]``,
    # returns a JSON envelope with ``dart_chunks_path`` +
    # ``dart_chunks_sha256`` keys for downstream phase consumption.
    #
    # Unlike ``_run_concept_extraction`` (which inline-projects v4 chunks
    # for ``build_pedagogy_graph`` because no IMSCC exists at that
    # phase), this helper goes through the canonical
    # ``Trainforge.chunker.chunk_content`` path. DART HTML is parsed via
    # ``Trainforge/parsers/html_content_parser.HTMLContentParser`` into
    # ``ContentSection`` objects (the same shape Trainforge's IMSCC path
    # consumes), wrapped into a parsed-item dict, and threaded into the
    # chunker with a thin ``ChunkerContext`` whose ``create_chunk``
    # callback emits a minimal-but-canonical v4 chunk dict (no
    # CourseProcessor instance state — concept_tags / objective_refs are
    # empty here; downstream alignment / tagging is the synthesis
    # surface's responsibility).
    #
    # Per the Phase 7b ST 14.5 reconciliation plan, the upstream
    # ``concept_extraction`` phase will refactor to consume this
    # chunkset (eliminating the inline projection above). For now both
    # surfaces coexist — Phase 7b lands the producer; ST 14.5 lands the
    # consumer-side refactor.
    # ============================================================================
    async def _run_dart_chunking(**kwargs):
        """Run the canonical chunker over staged DART HTML.

        Required kwargs (resolved via ``inputs_from`` in workflows.yaml's
        ``chunking`` phase):
            course_name: Canonical course name (used for course slug + chunk-ID prefix).
            staging_dir: DART staging directory (sibling to objective_extraction).

        Outputs (returned as JSON envelope + persisted):
            dart_chunks_path: ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl``
            dart_chunks_sha256: SHA-256 hex digest of the chunks file bytes

        Sibling ``manifest.json`` is also emitted at the same directory,
        carrying the canonical ``chunkset_manifest`` schema shape (per
        Phase 7b ST 12) so the ``ChunksetManifestValidator`` (ST 13)
        gate has something to validate against.
        """
        import hashlib as _hashlib

        course_name = kwargs.get("course_name") or ""
        staging_dir_kw = kwargs.get("staging_dir") or ""

        course_name = course_name or "UNKNOWN"
        course_slug = course_name.lower().replace("_", "-").replace(" ", "-")
        # W0.6: normalise the chunk-ID course_code WITH the space→underscore
        # replacement (the bare ``.upper().replace("-", "_")`` omitted it, so a
        # space-bearing course name leaked whitespace into every chunk id).
        course_code = _normalize_chunk_course_code(course_name)

        # Honest IRT difficulty-calibration scaffold
        # (TRAINFORGE_IRT_DIFFICULTY_SCAFFOLD). Build the calibrated-difficulty
        # map ONCE per run from the optional learner-response seam; threaded
        # into the chunk-emit site below so these chunks get difficulty
        # provenance parity with the IMSCC (process_course) path. Empty +
        # no-op when the flag is off (byte-identical legacy emit) or no
        # response file exists.
        _irt_enabled = False
        _irt_calibrated_map: Dict[str, Any] = {}
        _irt_response_present = False
        try:
            from lib.assessment.irt_difficulty import (
                irt_scaffold_enabled as _irt_scaffold_enabled,
                load_calibrated_difficulty as _irt_load_calibrated,
                resolve_response_data_path as _irt_resolve_responses,
                tag_chunk_difficulty_provenance as _irt_tag_chunk,
            )
            _irt_enabled = _irt_scaffold_enabled()
            if _irt_enabled:
                _irt_resp_path = _irt_resolve_responses(
                    course_slug, libv2_root=kwargs.get("libv2_root")
                )
                _irt_response_present = _irt_resp_path is not None
                _irt_calibrated_map = _irt_load_calibrated(_irt_resp_path)
        except Exception as _irt_exc:  # noqa: BLE001 — scaffold never breaks chunking
            logger.warning("IRT difficulty scaffold setup failed: %s", _irt_exc)
            _irt_enabled = False

        # Resolve staging dir from the explicit kwarg only. We deliberately
        # do NOT fall back to the global COURSEFORGE_INPUTS dir: on a
        # workflow resume that drops the carried-forward staging path, that
        # fallback resolved to a non-empty cross-course aggregate and made
        # the Wave1-I2 preserve-or-fail-closed guard unreachable, silently
        # overwriting this course's chunks.jsonl. An unresolvable/empty
        # staging input must route to the Wave1-I2 guard below.
        staging_dir: Optional[Path] = None
        if staging_dir_kw:
            cand = Path(staging_dir_kw)
            if cand.exists():
                staging_dir = cand

        # Walk staging_dir for DART HTML files. Filter out
        # ``*_synthesized.json`` neighbours (those are sidecars, not the
        # canonical HTML the chunker consumes).
        html_files: List[Path] = []
        if staging_dir is not None and staging_dir.exists():
            html_files = sorted(staging_dir.rglob("*.html"))

        # Wave1-I2: resume-safety guard. If we have no real input to
        # chunk (no staging_dir resolved, OR staging_dir exists but
        # produced zero HTML files), do NOT overwrite a previously-emitted
        # chunks.jsonl with an empty-bytes shell. On a workflow resume
        # that drops the input path from carried-forward phase context,
        # the prior fail-soft empty-shell behaviour silently destroyed
        # real chunks (see plans/dispatch-7-execution-inspection-2026-05.md
        # Finding 2; cost ~92 chunks during a real 2026-05 full-book run).
        # Preserve when an existing artifact is found; fail-closed when
        # there's nothing to preserve.
        if not html_files:
            # DART->semantik purge Stage 3c: the current emitter writes
            # ``semantik_chunks/``; a resume across the 3c boundary may still
            # carry a pre-3c ``dart_chunks/`` emit. Prefer semantik, fall back
            # to dart (DART-lineage specific — do NOT resolve an imscc sibling).
            _course_root = (
                _resolve_libv2_root(kwargs.get("libv2_root"))
                / "courses"
                / course_slug
            )
            _semantik_existing = (
                _course_root / "semantik_chunks" / "chunks.jsonl"
            )
            _dart_existing = _course_root / "dart_chunks" / "chunks.jsonl"
            existing_chunks_path = (
                _semantik_existing
                if _semantik_existing.exists()
                else _dart_existing
            )
            if existing_chunks_path.exists():
                existing_sha = _hashlib.sha256(
                    existing_chunks_path.read_bytes()
                ).hexdigest()
                existing_count = sum(
                    1
                    for line in existing_chunks_path.read_text(
                        encoding="utf-8"
                    ).splitlines()
                    if line.strip()
                )
                logger.warning(
                    "Wave1-I2: _run_dart_chunking input missing or empty "
                    "(staging_dir_kw=%r, resolved=%r); preserving existing "
                    "chunks.jsonl at %s (%d chunks, sha256=%s) instead of "
                    "overwriting with empty shell.",
                    staging_dir_kw,
                    str(staging_dir) if staging_dir else None,
                    existing_chunks_path,
                    existing_count,
                    existing_sha,
                )
                manifest_path = existing_chunks_path.parent / "manifest.json"
                return json.dumps({
                    "success": True,
                    "preserved_existing": True,
                    "semantik_chunks_path": str(existing_chunks_path),
                    "semantik_chunks_sha256": existing_sha,
                    "manifest_path": str(manifest_path),
                    "course_slug": course_slug,
                    "chunks_count": existing_count,
                    "source_html_count": 0,
                    "chunker_version": _resolve_chunker_version(),
                })
            raise RuntimeError(
                "Wave1-I2: _run_dart_chunking refusing to emit empty "
                "chunks.jsonl shell — no DART HTML input found "
                f"(staging_dir_kw={staging_dir_kw!r}, "
                f"resolved={str(staging_dir) if staging_dir else None!r}) "
                f"and no pre-existing artifact at {existing_chunks_path}. "
                "On a workflow resume, ensure the staging_dir kwarg is "
                "carried forward via phase_outputs."
            )

        # Compute aggregated source SHA-256 over the staged SemantiK HTML inputs.
        # Per the schema's ``source_semantik_html_sha256`` description, we
        # emit a deterministic merkle-ish digest: sort by filename,
        # concatenate per-file SHA-256 bytes, then SHA-256 the
        # concatenation. Stable across re-runs as long as the input
        # filename + content tuple is stable.
        def _file_sha256(p: Path) -> bytes:
            h = _hashlib.sha256()
            try:
                with p.open("rb") as fh:
                    for blk in iter(lambda: fh.read(65536), b""):
                        h.update(blk)
            except OSError:
                # Unreadable file — record a zero-bytes sentinel so the
                # aggregate still computes deterministically rather than
                # crashing the phase.
                return b"\x00" * 32
            return h.digest()

        if html_files:
            agg = _hashlib.sha256()
            for f in html_files:
                agg.update(_file_sha256(f))
            source_semantik_html_sha256 = agg.hexdigest()
        else:
            # Empty-input shell: SHA of empty bytes. Schema-valid
            # (64-char lowercase hex) and deterministic. Lets a
            # pre-staging dry-run still emit a manifest.
            source_semantik_html_sha256 = _hashlib.sha256(b"").hexdigest()

        # SemantiK migration §4 — doc-level conversion signals threaded into
        # the inline chunk emit. Mirrors the P2b
        # ``CourseProcessor._stamp_semantik_chunk_enrichment`` doc-level arm
        # (theta semantic_preservation_score + Stage-13 certification_status),
        # which reads them off instance attributes set by the seam. The inline
        # ``_run_dart_chunking`` path has no CourseProcessor instance, so we
        # read the signals here from the SemantiK ``{stem}.quality.json``
        # sidecar that sits next to each staged DART HTML file (the seam's
        # ``_run_semantik_v2_conversion`` writes it) and thread the SAME value
        # onto every chunk (same-per-doc, mirrors ``source_document_sha256``).
        # Omit-when-absent: a legacy / non-SemantiK corpus has no quality
        # sidecar → both stay unset → chunks byte-identical (back-compat). When
        # multiple staged HTML files carry quality sidecars we take the FIRST
        # resolvable pair (a single chunking phase covers one converted doc in
        # the common case; conflicting sidecars keep the first seen).
        _doc_semantic_preservation_score: Optional[float] = None
        _doc_certification_status: Optional[str] = None
        _SEMANTIK_CERT_STATUSES = frozenset(
            {"certified", "flagged", "non_certified"}
        )
        for _hf in html_files:
            _q_path = _hf.with_suffix(".quality.json")
            if not _q_path.is_file():
                continue
            try:
                _q = json.loads(_q_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            if _doc_semantic_preservation_score is None:
                _theta = _q.get("theta_score")
                if isinstance(_theta, (int, float)) and not isinstance(
                    _theta, bool
                ):
                    _theta_f = float(_theta)
                    if 0.0 <= _theta_f <= 1.0:
                        _doc_semantic_preservation_score = _theta_f
            if _doc_certification_status is None:
                _cert = _q.get("certification_status")
                if (
                    isinstance(_cert, str)
                    and _cert.strip() in _SEMANTIK_CERT_STATUSES
                ):
                    _doc_certification_status = _cert.strip()
            if (
                _doc_semantic_preservation_score is not None
                and _doc_certification_status is not None
            ):
                break

        # Parse DART HTML into ContentSection-bearing parsed_items.
        # Trainforge's HTMLContentParser produces the duck-typed
        # ContentSection objects ``Trainforge.chunker.chunk_content`` walks
        # via the ``merge_small_sections`` path. Lazy import keeps this
        # helper's import-time cost low.
        parsed_items: List[Dict[str, Any]] = []
        try:
            from Trainforge.parsers.html_content_parser import HTMLContentParser
        except Exception as exc:  # noqa: BLE001 — import failures shouldn't crash phase
            logger.warning(
                "Phase 7b ST 11: HTMLContentParser import failed (%s); "
                "emitting empty chunks shell.",
                exc,
            )
            html_parser = None
        else:
            html_parser = HTMLContentParser()

        if html_parser is not None:
            for idx, html_path in enumerate(html_files):
                # Graceful stop (checkpoint on command): deterministic non-LLM
                # per-file parse loop — a stop just pauses cleanly between
                # files (the chunker re-parses from scratch on resume).
                check_stop("dart_chunking", idx)
                try:
                    html_text = html_path.read_text(encoding="utf-8")
                except OSError as exc:
                    logger.warning(
                        "Phase 7b ST 11: failed to read %s (%s); skipping.",
                        html_path, exc,
                    )
                    continue
                try:
                    parsed = html_parser.parse(html_text)
                except Exception as exc:  # noqa: BLE001 — parser errors fail soft
                    logger.warning(
                        "Phase 7b ST 11: HTML parse failed for %s (%s); "
                        "skipping.",
                        html_path, exc,
                    )
                    continue
                slug = html_path.stem.lower().replace(" ", "-")
                # The chunker reads ``module_id``, ``item_id``,
                # ``raw_html``, ``resource_type``, ``sections``,
                # ``title``, ``misconceptions`` off each item. Other
                # keys are read defensively via ``.get(...)`` so a
                # minimal payload works.
                parsed_items.append({
                    "item_id": slug,
                    "item_path": str(html_path.relative_to(staging_dir))
                    if staging_dir and html_path.is_relative_to(staging_dir)
                    else html_path.name,
                    "title": parsed.title or slug,
                    "resource_type": "page",
                    "module_id": slug,
                    "module_title": parsed.title or slug,
                    "week_num": 0,
                    "word_count": parsed.word_count,
                    "sections": parsed.sections,
                    "learning_objectives": parsed.learning_objectives,
                    "key_concepts": parsed.key_concepts,
                    "interactive_components": parsed.interactive_components,
                    "raw_html": html_text,
                    "page_id": parsed.page_id,
                    "misconceptions": parsed.misconceptions,
                    "suggested_assessment_types": parsed.suggested_assessment_types,
                    "courseforge_metadata": parsed.metadata.get("courseforge"),
                    "objective_refs": parsed.objective_refs,
                    "source_references": parsed.source_references,
                })

        # TRAINFORGE_PAGE_CONCEPT_FALLBACK (default OFF): the GLM-OCR
        # accessible-HTML lane emits NO <strong>/<b>/<dt> markup, so
        # HTMLContentParser harvests ZERO page-level ``key_concepts`` and
        # every chunk of the page ends up with empty ``concept_tags`` — where
        # a publisher-HTML course, whose bold/dt markup feeds the parser, gets
        # a full tag set. When ON, derive a PAGE-LEVEL
        # key-concept list from each markup-less page's OWN text (lexical /
        # statistical only — no embeddings, no LLM) and assign it to
        # ``item["key_concepts"]`` so the EXISTING page-level tagging path
        # (``extract_concept_tags`` below) fires unchanged and all chunks of
        # the page share the same tag set (the vendor semantics — deliberately
        # PAGE-level, NOT chunk-local, since chunk-local tags fragment the KG).
        # Only fills EMPTY key_concepts — a page with real parser-harvested
        # concepts is untouched. Best-effort: a derivation failure must not
        # abort the chunking phase.
        try:
            from lib.ontology.page_concept_fallback import (
                apply_page_concept_fallback as _apply_page_concept_fallback,
            )
            _page_concepts_filled = _apply_page_concept_fallback(parsed_items)
            if _page_concepts_filled:
                logger.info(
                    "Phase 7b ST 11: TRAINFORGE_PAGE_CONCEPT_FALLBACK derived "
                    "page-level key_concepts on %d markup-less page(s).",
                    _page_concepts_filled,
                )
        except Exception:  # noqa: BLE001 — page-concept fallback is best-effort
            logger.warning(
                "Phase 7b ST 11: page-concept fallback failed; keeping parser "
                "key_concepts",
                exc_info=True,
            )

        # Minimal create_chunk callback — emits a v4-shaped chunk dict
        # without CourseProcessor's deep instance state. The chunker
        # delegates per-chunk materialisation here so the surface
        # parameters (chunk_id, text, html, item, section_heading,
        # chunk_type, follows_chunk_id, position_in_module, html_xpath,
        # char_span, section_source_ids, merged_headings) are all that
        # we have to thread through.
        #
        # ``concept_tags`` IS populated here (previously ``[]``): the
        # empty-tag substrate starved the downstream concept-graph +
        # CURIE machinery, which has nothing to work from when DART
        # chunks carry no concept tags. The instance-free
        # ``lib.ontology.concept_tagging.extract_concept_tags`` helper
        # (the same logic ``CourseProcessor._extract_concept_tags``
        # delegates to) tags from the chunk text + the HTML parser's
        # ``key_concepts``. ``domain_concept_seeds`` is empty here: the
        # ``chunking`` phase runs before ``course_planning``, so no
        # synthesized objectives (the source of per-course seeds) exist
        # yet — the pedagogy-pattern + tech-anchor + key-concept paths
        # carry the load. objective-ref enrichment remains the synthesis
        # surface's responsibility downstream.
        from lib.ontology.concept_tagging import extract_concept_tags
        from Trainforge.chunker import (
            extract_learning_outcome_refs as _extract_learning_outcome_refs,
        )

        # FIX #3c: chunk-local concept_tags. Default-OFF behind
        # ``TRAINFORGE_CHUNK_LOCAL_TAGS``. When OFF, every chunk on a page
        # tags from the SAME page-level ``item["key_concepts"]`` set, so
        # all chunks of a page collapse onto a byte-identical tag list
        # (legacy behaviour, byte-stable). When ON, each chunk's
        # ``concept_tags`` derive from ITS OWN text: the page-level
        # ``key_concepts`` are filtered down to those whose surface form
        # actually appears in THIS chunk's text, and the text-pattern
        # signals in ``extract_concept_tags`` fire on the chunk's own text.
        # We re-route through ``extract_concept_tags`` (not around it) so
        # the ``TRAINFORGE_PRUNE_SCAFFOLDING_CONCEPTS`` droppable-class +
        # scaffolding-noise filtering still applies to chunk-local tags.
        chunk_local_tags = (
            os.getenv("TRAINFORGE_CHUNK_LOCAL_TAGS", "").lower() == "true"
        )
        # FIX #3c (extract, not just filter): when the chunk-local flag is
        # ON, the per-chunk tag set is the UNION of (a) the filtered
        # page-level key_concepts that survive ``extract_concept_tags`` and
        # (b) concepts EXTRACTED from THIS chunk's own text via the shared
        # lexical machinery (``derive_lexical_concept_seeds`` — multi-word
        # noun phrases + acronyms, frequency/fragment/function-word filtered,
        # no embeddings). The filter-only path thinned coverage: a content-
        # rich chunk whose page-level key_concepts didn't surface in its text
        # ended up with one or zero tags, starving the concept graph. Adding
        # the chunk-local extraction recovers per-chunk coverage while
        # staying chunk-LOCAL (the seeds come from the chunk's own text).
        # Default-OFF preserves byte-identical legacy emit.
        _CHUNK_LOCAL_TAG_CAP = 12
        if chunk_local_tags:
            from lib.ontology.lexical_concept_seeds import (
                derive_lexical_concept_seeds as _derive_lexical_concept_seeds,
                is_fragment_phrase as _is_fragment_phrase,
            )
            from lib.ontology.concept_classifier import (
                is_scaffolding_noise as _is_scaffolding_noise,
            )

            def _chunk_local_extracted_tags(text: str) -> List[str]:
                """Extract chunk-local concept-tag slugs from ``text`` only.

                Routes the chunk text through the shared lexical seed
                deriver (``min_doc_freq=1`` so a single-chunk corpus still
                yields multi-word phrases; the function's built-in
                function-word / generic / denylist filters still apply),
                then re-applies the same quality gates the rest of the
                pipeline uses: ``is_fragment_phrase`` on multi-word slugs
                (sentence-fragment reject) and ``is_scaffolding_noise``
                (domain-agnostic scaffolding-noise reject). Deterministic:
                ``derive_lexical_concept_seeds`` already returns a stable
                ``(-doc_freq, slug)`` ordering, preserved here.
                """
                if not text:
                    return []
                try:
                    seeds = _derive_lexical_concept_seeds(
                        [{"text": text}], min_doc_freq=1
                    )
                except Exception:  # noqa: BLE001 — extraction is best-effort
                    return []
                out: List[str] = []
                for slug in seeds:
                    if not slug:
                        continue
                    # Multi-word slugs get the sentence-fragment gate; the
                    # deriver's own n-gram filter already drops most junk,
                    # but is_fragment_phrase is the canonical filter the
                    # bold-span harvest uses, so apply it for parity.
                    if "-" in slug and _is_fragment_phrase(
                        slug.replace("-", " ")
                    ):
                        continue
                    if _is_scaffolding_noise(slug):
                        continue
                    out.append(slug)
                return out
        # Tokeniser for chunk-local key-concept membership: split a concept
        # surface form into alphanumeric tokens (keeps internal hyphens /
        # apostrophes glued) so "Knowledge Base" -> ["knowledge", "base"].
        _CONCEPT_TOKEN_RE = re.compile(r"[a-z0-9]+(?:[-'][a-z0-9]+)*")

        def _key_concept_in_text(concept: str, text_lower: str) -> bool:
            """True iff every alphanumeric token of ``concept`` appears in
            ``text_lower`` (case-insensitive). Tokenises on non-alphanumeric
            runs so "Knowledge Base" matches "...the knowledge base stores...".
            A concept with no alphanumeric tokens never matches.
            """
            toks = [t for t in _CONCEPT_TOKEN_RE.findall(concept.lower()) if t]
            if not toks:
                return False
            return all(t in text_lower for t in toks)

        def _filter_item_key_concepts(
            item: Dict[str, Any], text: str
        ) -> Dict[str, Any]:
            """Return a shallow-copied ``item`` whose ``key_concepts`` is
            restricted to concepts whose words appear in ``text``. Other
            keys are shared by reference (read-only downstream)."""
            page_concepts = item.get("key_concepts") or []
            if not page_concepts:
                return item
            text_lower = (text or "").lower()
            local_concepts = [
                c for c in page_concepts
                if _key_concept_in_text(str(c), text_lower)
            ]
            local_item = dict(item)
            local_item["key_concepts"] = local_concepts
            return local_item

        # Chapter-ladder reconcile (SEMANTIK_CHAPTER_LADDER_RECONCILE, default
        # ON): per-item block-id → chapter-article-title module maps for
        # MULTI-chapter single-file corpora (a whole-book PDF). ``None`` per
        # item unless the file carries ≥2 <article role="doc-chapter">
        # chapters, so per-chapter corpora stay byte-identical. Best-effort:
        # a map failure degrades to the legacy file-level module_title.
        _article_module_maps: Dict[str, Optional[Dict[str, str]]] = {}
        if _chapter_ladder_reconcile_enabled():
            for _pi in parsed_items:
                try:
                    _article_module_maps[str(_pi.get("item_id") or "")] = (
                        _article_module_titles_by_block_id(
                            str(_pi.get("raw_html") or "")
                        )
                    )
                except Exception:  # noqa: BLE001 — module map is best-effort
                    logger.warning(
                        "chapter-ladder module map failed for item %s; "
                        "keeping file-level module_title",
                        _pi.get("item_id"),
                        exc_info=True,
                    )

        def _create_chunk(
            *,
            chunk_id: str,
            text: str,
            html: str,
            item: Dict[str, Any],
            section_heading: str,
            chunk_type: str,
            follows_chunk_id: Optional[str] = None,
            position_in_module: int = 0,
            html_xpath: Optional[str] = None,
            char_span: Optional[List[int]] = None,
            section_source_ids: Optional[List[str]] = None,
            merged_headings: Optional[List[str]] = None,
            dart_source_refs: Optional[List[Dict[str, Any]]] = None,
            composite_unit: Optional[str] = None,
            unit_roles: Optional[List[str]] = None,
            unit_subclass: Optional[str] = None,
        ) -> Dict[str, Any]:
            words = text.split()
            word_count = len(words)
            tokens_estimate = int(word_count * 1.3)
            # Defensive heading-sanity filter (TRAINFORGE_HEADING_SANITY_FILTER,
            # default OFF → byte-identical legacy). When a chunk's
            # ``section_heading`` is detected as upstream heading-classifier
            # noise (answer-key/exercise-prose/numeric), repair it to the
            # nearest clean ancestor heading (merged_headings breadcrumb, then
            # page title) — the original noise text stays in ``text``/``html``.
            # No clean ancestor → leave as-is + stamp ``heading_suspect``.
            _heading_to_stamp = section_heading
            _heading_suspect_flag = False
            try:
                from lib.chunk_heading_sanity import (
                    is_heading_sanity_filter_enabled as _hs_enabled,
                    repair_section_heading as _hs_repair,
                )
                if _hs_enabled():
                    _hs = _hs_repair(
                        section_heading,
                        item=item,
                        merged_headings=merged_headings,
                    )
                    _heading_to_stamp = _hs["heading"]
                    _heading_suspect_flag = _hs["suspect"] and not _hs["repaired"]
            except Exception:  # noqa: BLE001 — sanity filter is best-effort
                logger.warning(
                    "heading-sanity filter failed for chunk %s; keeping "
                    "original section_heading",
                    chunk_id,
                    exc_info=True,
                )
                _heading_to_stamp = section_heading
                _heading_suspect_flag = False
            # Title sanitizer (SEMANTIK_TITLE_SANITIZE, default OFF →
            # byte-identical). Scanned-textbook OCR fuses the chapter title
            # with the running header + page number + first content word
            # ("Chapter 1 Foundations 83 ✓ Solution"); left un-sanitized that
            # furniture lands on every chunk's provenance title (144/185 chunks
            # on a real 3-chapter scan). Strip it to the clean chapter title.
            _module_title = item.get("module_title") or ""
            _lesson_title = item.get("title") or ""
            # Chapter-ladder reconcile (SEMANTIK_CHAPTER_LADDER_RECONCILE):
            # on a MULTI-chapter single-file corpus (≥2 doc-chapter articles
            # → a non-None per-item map), resolve this chunk's module_title
            # to its ENCLOSING chapter-article <h2> via the chunk's own
            # block-id refs — instead of the file-level document title that
            # flattened a whole book onto one module (reference corpus: all 112
            # chunks stamped "Chapter 0"). A chunk with no resolvable ref
            # keeps the file-level title; per-chapter corpora never build a
            # map (byte-identical).
            _mod_map = _article_module_maps.get(str(item.get("item_id") or ""))
            if _mod_map:
                for _ref in (dart_source_refs or []):
                    _sid = str(
                        _ref.get("sourceId") or _ref.get("block_id") or ""
                    )
                    _bid = _sid.rsplit("#", 1)[-1] if "#" in _sid else _sid
                    _art_title = _mod_map.get(_bid)
                    if _art_title:
                        _module_title = _art_title
                        break
            _module_title_base = _module_title
            _lesson_title_base = _lesson_title
            try:
                from lib.textbook_title_sanitize import (
                    sanitize_running_header_title as _san_title,
                    title_sanitize_enabled as _san_enabled,
                )
                if _san_enabled():
                    _module_title = _san_title(_module_title)
                    _lesson_title = _san_title(_lesson_title)
            except Exception:  # noqa: BLE001 — sanitizer is best-effort
                _module_title = _module_title_base
                _lesson_title = _lesson_title_base
            source: Dict[str, Any] = {
                "course_id": course_code,
                "module_id": item.get("module_id") or "",
                "module_title": _module_title,
                "lesson_id": item.get("item_id") or "",
                "lesson_title": _lesson_title,
                "resource_type": item.get("resource_type") or "page",
                "section_heading": _heading_to_stamp,
                "position_in_module": position_in_module,
            }
            if _heading_suspect_flag:
                source["heading_suspect"] = True
            if html_xpath:
                source["html_xpath"] = html_xpath
            if char_span is not None:
                source["char_span"] = list(char_span)
            if item.get("item_path"):
                source["item_path"] = item["item_path"]
            # GPT Feedback v2 (May 12 / item 3): thread the aggregate
            # source-document SHA from the sidecar manifest into every
            # chunk's source block. Same value across every chunk from
            # this chunking run; gives downstream consumers a byte-stable
            # join key from chunk → upstream-source without a sidecar
            # lookup. See schemas/knowledge/chunk_v4.schema.json::
            # $defs.Source.source_document_sha256.
            if source_semantik_html_sha256:
                source["source_document_sha256"] = source_semantik_html_sha256
            # B1+B2: mint canonical source_references[] from the
            # ``{block_id, pages}`` pairs the chunker harvested off
            # ``data-dart-block-id`` / ``data-dart-pages`` on the source
            # HTML. sourceId = ``dart:{slug}#{block_id}`` where the slug is
            # the staged-HTML file stem (``item["item_id"]``, already in the
            # ``path.stem.lower().replace(" ", "-")`` form the source_refs
            # validator + source-router key on). Role auto-assigns to
            # ``primary`` (a DART block IS the source for a chunk built from
            # it). Empty/absent on HTML without ``data-dart-*`` attributes
            # (legacy corpora keep ``source_references`` unset, byte-stable).
            dart_refs = _semantik_block_source_references(
                dart_source_refs, item.get("item_id") or ""
            )
            if dart_refs:
                source["source_references"] = dart_refs
            # Wave3-Anew2: bloom_level + difficulty resolution via the
            # canonical JSON-LD > data-cf > heuristic cascade.
            bloom_level, bloom_source = _resolve_chunk_bloom_level(item, text)
            difficulty = _resolve_chunk_difficulty(item, text, bloom_level)
            # Real domain-concept tags from the chunk text + the HTML
            # parser's bold-term / definition ``key_concepts``. No
            # per-course domain seeds at this phase (objectives not yet
            # synthesized); helper defaults ``domain_concept_seeds`` to
            # empty. Defensive: a tagging failure must not abort the
            # chunking phase — fall back to ``[]`` (legacy behaviour).
            try:
                tag_item = (
                    _filter_item_key_concepts(item, text)
                    if chunk_local_tags
                    else item
                )
                concept_tags = extract_concept_tags(text, tag_item)
                if chunk_local_tags:
                    # Union (a) filtered page-level tags (above) with (b)
                    # tags extracted from THIS chunk's own text. First-seen-
                    # stable ordering (page-level survivors first, then
                    # chunk-local extractions); deduped; capped so a long
                    # chunk can't explode the tag list.
                    seen = set(concept_tags)
                    merged = list(concept_tags)
                    for slug in _chunk_local_extracted_tags(text):
                        if slug not in seen:
                            seen.add(slug)
                            merged.append(slug)
                    concept_tags = merged[:_CHUNK_LOCAL_TAG_CAP]
            except Exception:  # noqa: BLE001 — tagging is best-effort
                logger.warning(
                    "concept-tag extraction failed for chunk %s; "
                    "emitting empty concept_tags",
                    chunk_id,
                    exc_info=True,
                )
                concept_tags = []
            # LO-anchoring fix: harvest the LO ids the source page carried
            # (JSON-LD learningObjectives[].id + section data-cf-objective-id
            # / -ref) and anchor this chunk to its section's LOs. DART HTML
            # without LO metadata yields [] (byte-identical to the prior
            # hardcoded behaviour). Best-effort: a harvest failure must not
            # abort the chunking phase.
            try:
                lo_refs = _extract_learning_outcome_refs(item, section_heading)
            except Exception:  # noqa: BLE001 — LO harvest is best-effort
                logger.warning(
                    "learning_outcome_refs extraction failed for chunk %s; "
                    "emitting empty learning_outcome_refs",
                    chunk_id,
                    exc_info=True,
                )
                lo_refs = []
            chunk: Dict[str, Any] = {
                "id": chunk_id,
                "schema_version": "v4",
                "chunk_type": chunk_type,
                "text": text,
                "html": html,
                "follows_chunk": follows_chunk_id,
                "source": source,
                "concept_tags": concept_tags,
                "learning_outcome_refs": lo_refs,
                "difficulty": difficulty,
                "tokens_estimate": tokens_estimate,
                "word_count": word_count,
                "bloom_level": bloom_level,
            }
            # Per the schema's bloom_level_source contract: only emit the
            # provenance tag on low-confidence sources (verbs / default).
            if bloom_source in ("verbs", "default"):
                chunk["bloom_level_source"] = bloom_source

            # Task #26: source page-number provenance. Union the page numbers
            # the composing DART/SemantiK blocks carried (``data-semantik-pages``
            # / ``data-dart-pages``, harvested into each ref's ``pages``) into
            # the additive top-level ``source_pages`` field for retrieval-citation
            # display. Derived from the RAW ``dart_source_refs`` harvest (NOT the
            # minted ``source_references[]``), so page provenance survives even a
            # chunk whose block_id fails sourceId minting. Omitted when the union
            # is empty → legacy / attr-less corpora stay byte-identical.
            _src_pages = _union_source_pages(dart_source_refs)
            if _src_pages:
                chunk["source_pages"] = _src_pages

            # IRT difficulty-calibration scaffold: stamp provenance (+ optional
            # IRT block from real responses). No-op + byte-identical when off.
            if _irt_enabled:
                try:
                    _irt_tag_chunk(chunk, _irt_calibrated_map)
                except Exception:  # noqa: BLE001 — never break chunk emit
                    logger.warning("IRT chunk tagging failed for %s", chunk.get("id"))

            # SemantiK migration §4 — chunk-accompanying provenance enrichment.
            # The INLINE mirror of the P2b
            # ``CourseProcessor._stamp_semantik_chunk_enrichment`` 6-field
            # stamp. All omit-when-absent (no null-filled fields on legacy
            # corpora — mirrors source_document_sha256):
            #   * 3 HTML-harvested (source_block_role / -confidence /
            #     wcag_block_status): from this chunk's resolved
            #     ``dart_source_refs`` (the harvest helpers in
            #     ``Trainforge/chunker/helpers.py`` already pair block_role /
            #     confidence / wcag_status off the SAME element as
            #     data-dart-block-id). When a chunk spans several DART blocks
            #     the FIRST (document order) supplies the values.
            #   * figure_alt: DOM-side recovery of <figcaption>/<img alt>.
            #   * 2 doc-level (semantic_preservation_score /
            #     certification_status): the SemantiK theta + exit signals read
            #     once per chunking phase from the {stem}.quality.json sidecar
            #     and threaded in via closure (same value across every chunk of
            #     a doc, mirrors source_document_sha256).
            _first_ref: Optional[Dict[str, Any]] = None
            for _ref in dart_source_refs or []:
                if isinstance(_ref, dict):
                    _first_ref = _ref
                    break
            if _first_ref is not None:
                _role = _first_ref.get("block_role")
                if isinstance(_role, str) and _role.strip():
                    chunk["source_block_role"] = _role.strip()
                _conf = _first_ref.get("confidence")
                if isinstance(_conf, (int, float)) and not isinstance(
                    _conf, bool
                ):
                    _conf_f = float(_conf)
                    if 0.0 <= _conf_f <= 1.0:
                        chunk["source_block_confidence"] = _conf_f
                _wcag = _first_ref.get("wcag_status")
                if (
                    isinstance(_wcag, str)
                    and _wcag.strip() in _SEMANTIK_WCAG_BLOCK_STATUSES
                ):
                    chunk["wcag_block_status"] = _wcag.strip()
            if chunk_type == "figure" or (html and "<figure" in html.lower()):
                _alt = _recover_figure_alt(html)
                if _alt:
                    chunk["figure_alt"] = _alt
            if _doc_semantic_preservation_score is not None:
                chunk["semantic_preservation_score"] = (
                    _doc_semantic_preservation_score
                )
            if _doc_certification_status is not None:
                chunk["certification_status"] = _doc_certification_status

            # Wave #22 quick-wins: additive pedagogical-role metadata (harvested
            # from data-dart-unit / data-dart-flow / data-dart-opener by the
            # parser + chunker). Omit-when-absent so legacy / non-SemantiK
            # corpora stay byte-identical (mirrors source_block_role).
            if composite_unit:
                chunk["composite_unit"] = composite_unit
            if unit_roles:
                chunk["unit_roles"] = list(unit_roles)
            # Build #23 Tier-3: the composite-unit subclass (rides the unit).
            if unit_subclass:
                chunk["unit_subclass"] = unit_subclass

            return chunk

        # W3.H sub-task H1: count blocks_seen + per-reason drops BEFORE
        # dispatching to the chunker so we can emit the canonical
        # source_coverage block in the manifest. Walk parsed_items and
        # tally one "block" per ContentSection (or one per item when
        # the item has no sections); attribute drops via lightweight
        # heuristics applied to the same fields the chunker reads
        # (text content + section html). The numbers are conservative:
        # the chunker may also collapse short adjacent sections via
        # merge_small_sections, which is captured under the `dedup`
        # bucket below as the difference between attributable drops
        # and total dropped blocks.
        import re as _re
        blocks_seen = 0
        drop_boilerplate = 0
        drop_image_only = 0
        for _it in parsed_items:
            sections_list = _it.get("sections") or []
            if not sections_list:
                # Item with no sections counts as a single block emitted
                # via the unsectioned chunk_text_block path.
                blocks_seen += 1
                _raw_html = (_it.get("raw_html") or "").strip()
                _text_probe = _raw_html
                # Strip tags for a coarse "is there any text" probe.
                _text_probe = _re.sub(r"<[^>]+>", " ", _text_probe).strip()
                if _raw_html and not _text_probe and (
                    "<img" in _raw_html.lower()
                    or "<figure" in _raw_html.lower()
                ):
                    drop_image_only += 1
                continue
            for section in sections_list:
                blocks_seen += 1
                _content = (
                    getattr(section, "content", None)
                    if not isinstance(section, dict)
                    else section.get("content")
                ) or ""
                _wc = (
                    getattr(section, "word_count", None)
                    if not isinstance(section, dict)
                    else section.get("word_count")
                ) or 0
                _components = (
                    getattr(section, "components", None)
                    if not isinstance(section, dict)
                    else section.get("components")
                ) or []
                _content_str = str(_content).strip()
                if not _content_str and _components:
                    # Section that carries only an interactive component
                    # (image / figure / flip-card) without textual prose:
                    # the chunker's `if not text.strip(): continue` drops
                    # it.
                    drop_image_only += 1

        # Dispatch to the canonical chunker. ``chunk_content`` is
        # fail-soft on empty input (returns empty result, no ctx
        # required); for non-empty input it requires ``ctx`` per the
        # ChunkerContextRequired contract.
        chunks: List[Dict[str, Any]] = []
        chunker_version = _resolve_chunker_version()
        try:
            from Trainforge.chunker import ChunkerContext, chunk_content
        except Exception as exc:  # noqa: BLE001 — import failures shouldn't crash phase
            logger.warning(
                "Phase 7b ST 11: Trainforge.chunker import failed (%s); "
                "emitting empty chunks shell.",
                exc,
            )
        else:
            try:
                ctx = ChunkerContext(create_chunk=_create_chunk) if parsed_items else None
                result = chunk_content(
                    parsed_items,
                    course_code,
                    boilerplate_spans=None,
                    ctx=ctx,
                )
                chunks = list(result.chunks)
            except Exception as exc:  # noqa: BLE001 — fail-soft on chunker error
                logger.warning(
                    "Phase 7b ST 11: chunk_content raised (%s); emitting "
                    "empty chunks shell.",
                    exc,
                )
                chunks = []

        # M1: front-matter / donor / marketing contamination filter. A
        # full-textbook PDF's head carries the cover/title page, the
        # author+copyright+ISBN+Creative-Commons block, donor acknowledgements,
        # the Table of Contents, and the "Key Features"/"Additional Resources"
        # preface — none of which is course content, yet they get CITED by
        # synthesized objectives and pollute grounding. Default-off for bare
        # library calls (byte-stable legacy emit); auto-on for pipeline runs via
        # ``_apply_corpus_generalization_defaults`` (TRAINFORGE_DROP_FRONTMATTER).
        # Each dropped chunk emits a decision-capture event whose rationale
        # interpolates the matched signatures + chunk id (deterministic prune,
        # still audit-captured per the contamination-control contract).
        if (
            chunks
            and os.getenv("TRAINFORGE_DROP_FRONTMATTER", "").lower() == "true"
        ):
            try:
                from Trainforge.chunker.frontmatter import partition_frontmatter

                kept_chunks, dropped_verdicts = partition_frontmatter(chunks)
            except Exception as exc:  # noqa: BLE001 — filter is best-effort
                logger.warning(
                    "M1: front-matter filter raised (%s); keeping all "
                    "%d chunks unfiltered.",
                    exc,
                    len(chunks),
                )
            else:
                if dropped_verdicts:
                    logger.info(
                        "M1: dropped %d front-matter/donor/marketing chunk(s) "
                        "of %d for course %s: %s",
                        len(dropped_verdicts),
                        len(chunks),
                        course_slug,
                        ", ".join(v.chunk_id for v in dropped_verdicts),
                    )
                    _fm_capture = None
                    try:
                        from lib.decision_capture import DecisionCapture

                        _fm_capture = DecisionCapture(
                            course_code=course_code,
                            phase="textbook-ingestor",
                            tool="trainforge",
                        )
                    except Exception as _exc:  # noqa: BLE001 — capture best-effort
                        logger.debug(
                            "M1: DecisionCapture init failed (%s); "
                            "continuing without capture.",
                            _exc,
                        )
                    if _fm_capture is not None:
                        for verdict in dropped_verdicts:
                            try:
                                _fm_capture.log_decision(
                                    decision_type="frontmatter_chunk_drop",
                                    decision=(
                                        f"drop chunk {verdict.chunk_id} "
                                        f"(front-matter contamination)"
                                    ),
                                    rationale=verdict.rationale(),
                                    alternatives_considered=[
                                        {
                                            "option": "retain chunk",
                                            "reason_rejected": (
                                                "legacy default-off behaviour; "
                                                "front-matter pollutes "
                                                "objective citation + grounding"
                                            ),
                                        },
                                        {
                                            "option": (
                                                "flag is_frontmatter=true but "
                                                "keep in chunkset"
                                            ),
                                            "reason_rejected": (
                                                "downstream consumers do not "
                                                "yet filter on the flag; "
                                                "dropping is the contract"
                                            ),
                                        },
                                    ],
                                )
                            except Exception as _exc:  # noqa: BLE001
                                logger.debug(
                                    "M1: log_decision failed for %s (%s)",
                                    verdict.chunk_id,
                                    _exc,
                                )
                chunks = kept_chunks

        # Apparatus-dump filter (TRAINFORGE_DROP_APPARATUS_DUMPS, default OFF →
        # byte-identical legacy emit). Sibling to the front-matter filter, but
        # for MID-corpus non-instructional noise the cover-region front-matter
        # pass can't see: OCR'd end-of-chapter ANSWER-KEY runs
        # ("46. 550 47. 22,335 ...") and chapter-outline / Table-of-Contents
        # chunks ("Chapter Outline 1.2 Use the Language of Algebra ..."). Both
        # get cited by synthesized objectives and poison grounding. High
        # precision: only unambiguous answer-key runs (dominant "N. <number>"
        # pairs) + explicit outline/ToC headers are dropped; math-dense
        # exercise/example chunks (LaTeX + legitimate numbers) are never
        # touched. Each drop emits a decision-capture event.
        if (
            chunks
            and os.getenv("TRAINFORGE_DROP_APPARATUS_DUMPS", "").lower() == "true"
        ):
            try:
                from Trainforge.chunker.apparatus_dumps import (
                    partition_apparatus_dumps,
                )

                kept_chunks, dropped_verdicts = partition_apparatus_dumps(chunks)
            except Exception as exc:  # noqa: BLE001 — filter is best-effort
                logger.warning(
                    "apparatus-dump filter raised (%s); keeping all %d chunks "
                    "unfiltered.",
                    exc,
                    len(chunks),
                )
            else:
                if dropped_verdicts:
                    logger.info(
                        "apparatus-dump: dropped %d answer-key/ToC chunk(s) of "
                        "%d for course %s: %s",
                        len(dropped_verdicts),
                        len(chunks),
                        course_slug,
                        ", ".join(v.chunk_id for v in dropped_verdicts),
                    )
                    _ap_capture = None
                    try:
                        from lib.decision_capture import DecisionCapture

                        _ap_capture = DecisionCapture(
                            course_code=course_code,
                            phase="textbook-ingestor",
                            tool="trainforge",
                        )
                    except Exception as _exc:  # noqa: BLE001 — capture best-effort
                        logger.debug(
                            "apparatus-dump: DecisionCapture init failed (%s); "
                            "continuing without capture.",
                            _exc,
                        )
                    if _ap_capture is not None:
                        for verdict in dropped_verdicts:
                            try:
                                _ap_capture.log_decision(
                                    decision_type="apparatus_chunk_drop",
                                    decision=(
                                        f"drop chunk {verdict.chunk_id} "
                                        f"(answer-key/ToC apparatus dump)"
                                    ),
                                    rationale=verdict.rationale(),
                                    alternatives_considered=[
                                        {
                                            "option": "retain chunk",
                                            "reason_rejected": (
                                                "answer-key/ToC layout pollutes "
                                                "objective citation + grounding"
                                            ),
                                        },
                                    ],
                                )
                            except Exception as _exc:  # noqa: BLE001
                                logger.debug(
                                    "apparatus-dump: log_decision failed for "
                                    "%s (%s)",
                                    verdict.chunk_id,
                                    _exc,
                                )
                chunks = kept_chunks

        # Relocate stranded next-section heading tails
        # (TRAINFORGE_RELOCATE_STRANDED_HEADINGS, default OFF; auto-on for
        # pipeline runs via _apply_corpus_generalization_defaults). In the
        # GLM-OCR lane the opener of the FOLLOWING section can be glued onto
        # the TAIL of the prior section's last chunk; this deterministic
        # post-pass moves a standalone "N.M <SECTION-MARKER>" onto the next
        # SAME-FLOW chunk. Text-only mutation (html untouched). MUST run after
        # every drop/filter pass so relocation is between the FINAL emitted
        # chunks.
        if chunks:
            try:
                from Trainforge.chunker import (
                    relocate_stranded_heading_tails,
                    resolve_relocate_stranded_headings,
                )

                if resolve_relocate_stranded_headings():
                    chunks = relocate_stranded_heading_tails(chunks)
            except Exception as exc:  # noqa: BLE001 — post-pass is best-effort
                logger.warning(
                    "stranded-heading-tail relocation raised (%s); keeping "
                    "all %d chunks unmodified.",
                    exc,
                    len(chunks),
                )

        # Track K: optional verbatim chunk overlap. When
        # ``TRAINFORGE_CHUNK_OVERLAP_WORDS`` > 0, prepend the verbatim
        # trailing N words of each chunk's prior EMITTED chunk onto the
        # next so boundary content that split across a chunk break is
        # recoverable at retrieval time (anti-fabrication — never
        # synthesized). Default 0 → no-op, byte-identical legacy emit.
        # Applied AFTER every drop/filter pass so overlap bleeds only
        # between the FINAL emitted chunks; recorded in the manifest for
        # replay below.
        _overlap_words = _resolve_chunk_overlap_words()
        if _overlap_words > 0:
            chunks = _apply_chunk_overlap(chunks, _overlap_words)

        # IRT difficulty-calibration scaffold: emit ONE difficulty_calibration
        # decision event per run (parity with process_course's chunk-emit
        # path). Guarded by _irt_enabled → byte-stable no-op when the flag is
        # off. Uses the gathered response-present + calibrated-map signals.
        if _irt_enabled:
            _emit_irt_difficulty_calibration_event(
                chunks=chunks,
                course_code=course_code,
                phase="textbook-ingestor",
                calibrated_map=_irt_calibrated_map,
                response_present=_irt_response_present,
            )

        # Persist chunks + manifest to LibV2/courses/<slug>/semantik_chunks/,
        # routed through `_resolve_libv2_root` (see helper docstring for the
        # resolution chain). Only NEW conversions land under
        # ``semantik_chunks/``; readers dual-resolve via
        # ``lib.libv2_storage.resolve_imscc_chunks_dir`` (semantik -> dart ->
        # corpus) so un-migrated archives still holding ``dart_chunks/`` keep
        # resolving.
        from lib.libv2_storage import SEMANTIK_CHUNKS_DIRNAME
        course_dir = (
            _resolve_libv2_root(kwargs.get("libv2_root"))
            / "courses"
            / course_slug
        )
        chunks_dir = course_dir / SEMANTIK_CHUNKS_DIRNAME
        chunks_dir.mkdir(parents=True, exist_ok=True)
        chunks_path = chunks_dir / "chunks.jsonl"

        # Stream chunks as JSONL (one chunk per line). Use a hashing
        # writer pattern so the SHA-256 reflects exactly the bytes on
        # disk (no double-read).
        chunks_sha = _hashlib.sha256()
        with chunks_path.open("wb") as fh:
            for chunk in chunks:
                line = (json.dumps(chunk, ensure_ascii=False) + "\n").encode(
                    "utf-8"
                )
                fh.write(line)
                chunks_sha.update(line)
        chunks_sha256 = chunks_sha.hexdigest()

        # W3.H sub-task H1: build the canonical source_coverage block.
        # consumed_count = blocks_seen, emitted_count = len(chunks).
        # Per-reason histogram pulls from the heuristics tracked above
        # (boilerplate / image_only). Any remaining drop delta —
        # blocks merged into adjacent sections via merge_small_sections,
        # or empty after sentence-splitting — falls into the
        # `merged_small_sections` bucket (renamed from the misleading
        # `dedup`: these artifacts were NOT de-duplicated, they were
        # MERGED into an adjacent section). The build_source_coverage
        # helper enforces the
        # dropped_count == sum(drop_reasons.values()) invariant and
        # fires INTERNAL_DROP_REASON_MISSING when the math doesn't
        # balance (silent-gaming check).
        from lib.governance.source_coverage import build_source_coverage
        _attributable_drops = drop_boilerplate + drop_image_only
        _dropped_total = max(0, blocks_seen - len(chunks))
        _drop_reasons: Dict[str, int] = {}
        if drop_boilerplate:
            _drop_reasons["boilerplate"] = drop_boilerplate
        if drop_image_only:
            _drop_reasons["image_only"] = drop_image_only
        _dedup_delta = max(0, _dropped_total - _attributable_drops)
        if _dedup_delta:
            _drop_reasons["merged_small_sections"] = _dedup_delta
        source_coverage_block = build_source_coverage(
            consumed_count=blocks_seen,
            emitted_count=len(chunks),
            drop_reasons=_drop_reasons,
            dropped_count=_dropped_total,
            label="dart_chunking",
        )

        # W0.6 emit-time tripwire: no emitted chunk id may carry whitespace
        # (the course_code normalisation above prevents it; this catches any
        # future regression). Log loudly + stamp the manifest so the defect is
        # observable post-hoc instead of silently breaking the id-prefix gate.
        _ws_chunk_ids = _assert_no_whitespace_chunk_ids(chunks)
        if _ws_chunk_ids:
            logger.warning(
                "W0.6: %d DART chunk id(s) contain whitespace for course_code=%r "
                "(e.g. %r); the id-prefix grounding gate will not match.",
                len(_ws_chunk_ids), course_code, _ws_chunk_ids[0],
            )

        # Sibling manifest.json — must validate against
        # ``schemas/library/chunkset_manifest.schema.json`` per ST 12.
        # Required: chunks_sha256, chunker_version, chunkset_kind,
        # source_semantik_html_sha256 (conditional on chunkset_kind=semantik).
        # Optional: chunks_count, generated_at, source_coverage (W3.H H1).
        # DART->semantik naming purge (task #19): this emitter now writes the
        # ratified ``chunkset_kind="semantik"`` + ``source_semantik_html_sha256``
        # (the schema ratified both at Stage 1; the read side — validators,
        # lib/libv2_storage.py, chunkset_manifest gate, S2 migrator — is
        # dual-read and still accepts the legacy ``dart`` shape).
        manifest = {
            "chunks_sha256": chunks_sha256,
            "chunker_version": chunker_version,
            # Chunk-TEXT extraction-contract version (orthogonal to
            # chunker_version's emit shape). Lets a provenance consumer tell
            # this corpus was chunked under the CURRENT HTMLTextExtractor
            # contract even for chunk-only --stop-after slices that never get
            # a course_manifest.json.
            "extraction_contract": _resolve_extraction_contract(),
            "chunkset_kind": "semantik",
            "source_semantik_html_sha256": source_semantik_html_sha256,
            "chunks_count": len(chunks),
            "generated_at": datetime.utcnow().isoformat() + "Z",
            "source_coverage": source_coverage_block,
        }
        # Track K: record the overlap budget for replay (omitted when off
        # so the manifest stays byte-identical to the legacy emit).
        if _overlap_words > 0:
            manifest["overlap_words"] = _overlap_words
        # W1b.5: honest learning-outcome-linkage marker. The DART chunking
        # phase emits chunks BEFORE course-planning mints the TO-NN/CO-NN id
        # set (``_backfill_dart_chunk_lo_refs`` runs later against the on-disk
        # chunks), so a fresh dart_chunks manifest legitimately advertises that
        # linkage was skipped. Stamp ONLY when every chunk's
        # ``learning_outcome_refs`` is empty (mirrors the whitespace-warning
        # "stamp only on the gap" precedent); a populated / back-filled
        # chunkset omits the field → byte-identical legacy emit.
        if chunks and not any(
            (c.get("learning_outcome_refs") or []) for c in chunks
        ):
            manifest["lo_linkage"] = "skipped"
            manifest["lo_refs_unpopulated"] = True
        # W0.6: surface the whitespace-id defect in the manifest (omitted when
        # clean so the manifest stays byte-identical to the legacy emit).
        if _ws_chunk_ids:
            manifest["chunk_id_whitespace_warning"] = {
                "count": len(_ws_chunk_ids),
                "sample_ids": _ws_chunk_ids[:5],
            }
        manifest_path = chunks_dir / "manifest.json"
        # W0.7: atomic temp-then-replace manifest write.
        _atomic_write_text(
            manifest_path,
            json.dumps(manifest, indent=2, ensure_ascii=False),
        )

        # DART->semantik purge Stage 3c: the phase-output envelope keys flip to
        # ``semantik_chunks_path`` / ``semantik_chunks_sha256`` (matching the
        # ratified emit dir). Routed consumers still receive the value under the
        # stable ``dart_chunks_path`` kwarg (the workflow-runner ``inputs_from``
        # ``param:`` name is unchanged); only DIRECT phase_outputs readers that
        # name the key dual-read (``semantik_chunks_path`` then legacy
        # ``dart_chunks_path``) for resume-checkpoint compatibility.
        return json.dumps({
            "success": True,
            "semantik_chunks_path": str(chunks_path),
            "semantik_chunks_sha256": chunks_sha256,
            "manifest_path": str(manifest_path),
            "course_slug": course_slug,
            "chunks_count": len(chunks),
            "source_html_count": len(html_files),
            "chunker_version": chunker_version,
        })

    registry["run_dart_chunking"] = _run_dart_chunking

    # heading_judge phase handler (SEMANTIK_HEADING_JUDGE permanent wiring;
    # registry-only — NOT an @mcp.tool; dispatched by phase NAME via
    # MCP/core/executor.py::_PHASE_TOOL_MAPPING['heading_judge']).
    registry["run_heading_judge"] = _run_heading_judge

    # ============================================================================
    # W10 Phase 2: _run_assessment_synthesis — PRODUCT assessment surface
    #
    # A new ``assessment_synthesis`` workflow phase that runs BEFORE
    # ``packaging`` (spec §2.4 Option A) so the packager picks up the
    # learner-facing QTI quizzes / discussions / assignments it discovers
    # under ``<export>/06_assessments/``. DART-chunk-rooted (the
    # ``chunking`` phase already emitted ``dart_chunks/chunks.jsonl``) and
    # pre-packaging — keeps the post-package ``trainforge_assessment`` phase
    # (training-data-oriented) UNCHANGED.
    #
    # - Objective quiz items REUSE ``AssessmentGenerator`` (no reinvent),
    #   grouped per week / terminal objective.
    # - Assignment (per CO-cluster) + discussion (per TERMINAL objective)
    #   PROSE route through the same provider seat as the Trainforge
    #   assessment generator (``AssessmentGeneratorProvider``, env
    #   ``TRAINFORGE_ASSESSMENT_PROVIDER``); each carries ``objective_id``
    #   so the grounding gate fires unchanged.
    # - XML emit via the already-landed ``Courseforge/scripts/qti_emitter.py``.
    #
    # PRODUCT content (learner-facing), NOT training pairs → no hard
    # licensing gate (mirrors ``COURSEFORGE_PROVIDER`` /
    # ``ED4ALL_OBJECTIVE_REVIEW_PROVIDER`` posture). New flag:
    #   ``ED4ALL_ASSESSMENT_PROSE_PROVIDER`` (default unset → no prose-tier
    #   LLM; objective quiz items still emit). When set, selects the prose
    #   seat backend (``local`` / ``together`` / any registered
    #   OpenAI-compatible provider) for the assignment/discussion prose.
    #   PRODUCT content → NO docs/LICENSING.md row required (this comment
    #   satisfies the maintenance contract for the flag).
    #
    # Anti-fabrication (hard): every emitted item's ``objective_id`` comes
    # from the real synthesized-objectives universe and its grounding from
    # real chunk ids; phantom-objective items are DROPPED, never emitted.
    # Graceful: provider error / no key / empty input → log + emit whatever
    # objective items succeeded (or a clean empty 06_assessments with an
    # empty manifest); never abort the run.
    # ============================================================================
    async def _run_assessment_synthesis(**kwargs):
        """Synthesize learner-facing QTI quizzes + discussions + assignments.

        Required kwargs (resolved via ``inputs_from`` in the
        ``assessment_synthesis`` workflow phase):
            project_id: Courseforge project export dir name.

        Optional kwargs:
            course_name / course_code: overrides the project config value.
            dart_chunks_path: ``LibV2/courses/<slug>/dart_chunks/chunks.jsonl``
                from the upstream ``chunking`` phase. Falls back to the
                LibV2 default location when absent.
            synthesized_objectives_path: overrides the default
                ``01_learning_objectives/synthesized_objectives.json``.
            question_count: per-week quiz item budget (default 5).
            bloom_levels: comma-separated Bloom levels (default
                "remember,understand,apply").

        Output dir: ``<export>/06_assessments/`` carrying ``<name>.xml``
        files + a ``manifest.json`` matching the packager's pinned contract.
        """
        import traceback as _traceback

        # ---- LOUD kwargs receipt -----------------------------------------
        # A production run lost project_id across a
        # course_planning fail-open + resume, and the resulting
        # {"error": ...} envelope (no ``success`` key) was treated as a
        # COMPLETED task by the executor — a <100ms silent no-op that left
        # 06_assessments/ missing for packaging. Log exactly what arrived so
        # the next such run is diagnosable from the log alone.
        logger.info(
            "run_assessment_synthesis: received kwargs project_id=%r "
            "course_code=%r course_name=%r dart_chunks_path=%r "
            "synthesized_objectives_path=%r",
            kwargs.get("project_id"),
            kwargs.get("course_code"),
            kwargs.get("course_name"),
            kwargs.get("dart_chunks_path"),
            kwargs.get("synthesized_objectives_path"),
        )

        project_id = kwargs.get("project_id") or ""
        if not project_id:
            # Defensive fallback (courseforge-rewrite subcommand precedent —
            # MCP/core/workflow_runner.py::_resolve_stage_project_dir):
            # resolve the NEWEST Courseforge/exports/PROJ-<course>-* export
            # for this course instead of silently erroring out.
            _fallback_course = str(
                kwargs.get("course_code") or kwargs.get("course_name") or ""
            ).strip()
            if _fallback_course:
                _exports_root = courseforge_exports_dir()
                _prefix = f"PROJ-{_fallback_course}-"
                _cands = []
                if _exports_root.is_dir():
                    for _cand in _exports_root.iterdir():
                        if _cand.is_dir() and _cand.name.startswith(_prefix):
                            try:
                                _cands.append((_cand.stat().st_mtime, _cand))
                            except OSError:
                                continue
                if _cands:
                    _cands.sort(reverse=True)
                    project_id = _cands[0][1].name
                    logger.warning(
                        "run_assessment_synthesis: project_id kwarg was "
                        "missing/None (upstream phase_outputs did not carry "
                        "it — e.g. a course_planning fail-open resume); "
                        "defensively resolved to the newest export %r "
                        "(most recent of %d candidates matching %r).",
                        project_id, len(_cands), _prefix,
                    )
                else:
                    logger.error(
                        "run_assessment_synthesis: project_id kwarg missing "
                        "AND no export dir under %s matches prefix %r — "
                        "cannot emit 06_assessments.",
                        _exports_root, _prefix,
                    )
        if not project_id:
            logger.error(
                "run_assessment_synthesis: FAILING LOUD — no project_id "
                "received and none resolvable from course=%r. Received "
                "kwargs keys: %s",
                kwargs.get("course_code") or kwargs.get("course_name"),
                sorted(kwargs.keys()),
            )
            return json.dumps({
                "success": False,
                "error_code": "ASSESSMENT_SYNTHESIS_NO_PROJECT_ID",
                "error": (
                    "run_assessment_synthesis requires project_id (none "
                    "received; newest-export fallback found no "
                    "PROJ-<course>-* dir)"
                ),
            })

        project_path = courseforge_exports_dir() / project_id
        if not project_path.exists():
            logger.error(
                "run_assessment_synthesis: FAILING LOUD — project export "
                "dir not found: %s", project_path,
            )
            return json.dumps({
                "success": False,
                "error_code": "ASSESSMENT_SYNTHESIS_PROJECT_DIR_MISSING",
                "error": f"Project export dir not found: {project_path}",
            })

        out_dir = project_path / "06_assessments"

        # ---- per-unit resume checkpoint (P4) -----------------------------
        # ONE sidecar keyed on (kind, terminal_id); default ON (family flag).
        # Removed only AFTER the manifest end-write succeeds; a graceful stop
        # raises before that write, so the sidecar survives for the resume.
        _assessments_ckpt_path = out_dir / _ASSESSMENTS_CHECKPOINT_NAME
        _assessments_store_obj = _assessments_store(_assessments_ckpt_path)
        _assessments_cache = _assessments_store_obj.load()
        _assessment_units_done = 0

        # ---- course code -------------------------------------------------
        course_code = (
            kwargs.get("course_code")
            or kwargs.get("course_name")
            or ""
        )
        if not course_code:
            try:
                cfg = json.loads(
                    (project_path / "project_config.json").read_text(
                        encoding="utf-8"
                    )
                )
                course_code = cfg.get("course_name") or project_id
            except (OSError, ValueError):
                course_code = project_id

        # ---- synthesized-objectives universe (anti-fabrication) ----------
        obj_path_kw = kwargs.get("synthesized_objectives_path") or ""
        obj_path = (
            Path(obj_path_kw)
            if obj_path_kw
            else project_path / "01_learning_objectives"
            / "synthesized_objectives.json"
        )
        objectives_doc: Dict[str, Any] = {}
        if obj_path.exists():
            try:
                objectives_doc = json.loads(obj_path.read_text(encoding="utf-8"))
            except (OSError, ValueError):
                objectives_doc = {}
        to_map, co_map = _index_objective_records(objectives_doc)
        valid_objective_ids = set(to_map) | set(co_map)
        id_to_statement = _objective_id_to_statement(objectives_doc)

        if not valid_objective_ids:
            # No grounded objective universe → emit a clean empty surface
            # rather than fabricating items (never abort the run).
            logger.warning(
                "run_assessment_synthesis: no synthesized objectives at %s; "
                "emitting an empty 06_assessments/manifest.json.",
                obj_path,
            )
            manifest = _write_assessment_artifacts(out_dir, [])
            return json.dumps({
                "success": True,
                "assessments_dir": str(out_dir),
                "manifest_path": str(out_dir / "manifest.json"),
                "assessment_count": 0,
                "quiz_count": 0,
                "discussion_count": 0,
                "assignment_count": 0,
                "reason": "no_objectives",
            })

        # ---- DART chunks -------------------------------------------------
        course_slug = str(course_code).lower().replace("_", "-").replace(" ", "-")
        dart_chunks_kw = kwargs.get("dart_chunks_path") or ""
        if dart_chunks_kw:
            dart_chunks_path = Path(dart_chunks_kw)
        else:
            # DART->semantik purge Stage 3c: dual-read staged chunkset
            # (semantik -> dart -> corpus) when no explicit path was threaded.
            from lib.libv2_storage import resolve_staged_chunks_path
            dart_chunks_path = resolve_staged_chunks_path(
                _resolve_libv2_root(kwargs.get("libv2_root"))
                / "courses" / course_slug
            )
        loaded_chunks: List[Dict[str, Any]] = []
        if dart_chunks_path.exists():
            try:
                with dart_chunks_path.open(encoding="utf-8") as _fh:
                    for _line in _fh:
                        _line = _line.strip()
                        if not _line:
                            continue
                        try:
                            _c = json.loads(_line)
                        except ValueError:
                            continue
                        if isinstance(_c, dict):
                            loaded_chunks.append(_c)
            except OSError:
                loaded_chunks = []

        # Chunkset fingerprint axis (shared by every unit): a re-chunk that
        # changes the grounding re-runs the affected units on resume.
        _assessment_chunkset_sha_val = _assessment_chunkset_sha(loaded_chunks)

        # ---- params ------------------------------------------------------
        question_count = int(kwargs.get("question_count", 5) or 5)
        bloom_raw = kwargs.get("bloom_levels", "remember,understand,apply")
        if isinstance(bloom_raw, list):
            bloom_levels = [str(b).strip() for b in bloom_raw if str(b).strip()]
        else:
            bloom_levels = [
                b.strip() for b in str(bloom_raw).split(",") if b.strip()
            ]
        if not bloom_levels:
            bloom_levels = ["remember", "understand", "apply"]

        # ---- decision capture handle -------------------------------------
        capture = None
        try:
            from lib.decision_capture import DecisionCapture
            capture = DecisionCapture(
                course_code=str(course_code) or "UNKNOWN",
                phase="trainforge-assessment",
                tool="trainforge",
            )
        except Exception:
            capture = None

        # ---- map COs -> their parent TO (for per-TO grouping) ------------
        # Each chapter-objective row may carry a ``terminal_id`` backlink.
        co_to_terminal: Dict[str, str] = {}
        for _cid, _co in co_map.items():
            _tid = _co.get("terminal_id") or _co.get("terminal_objective_id")
            if isinstance(_tid, str) and _tid.strip():
                co_to_terminal[_cid] = _tid.strip()

        # Group CO ids per terminal objective; assign a week index per TO so
        # the manifest carries a clean ``week`` for LMS nav. TOs are ordered
        # by id; week = index+1.
        terminal_ids = sorted(to_map.keys())
        if not terminal_ids:
            # No TO layer → treat every CO as one flat group (week 1).
            terminal_ids = ["_FLAT_"]
            cos_by_terminal: Dict[str, List[str]] = {"_FLAT_": sorted(co_map.keys())}
        else:
            cos_by_terminal = {tid: [] for tid in terminal_ids}
            for _cid in sorted(co_map.keys()):
                _tid = co_to_terminal.get(_cid)
                if _tid in cos_by_terminal:
                    cos_by_terminal[_tid].append(_cid)
                else:
                    # Orphan CO → attach to first TO so it still gets quizzed.
                    cos_by_terminal[terminal_ids[0]].append(_cid)

        # ============================================================== #
        # 1. OBJECTIVE QUIZ ITEMS — reuse AssessmentGenerator per TO.     #
        # ============================================================== #
        try:
            from Trainforge.generators.assessment_generator import (
                AssessmentGenerator,
            )
        except Exception as exc:
            logger.warning(
                "run_assessment_synthesis: AssessmentGenerator import "
                "failed (%s); emitting empty 06_assessments.", exc,
            )
            manifest = _write_assessment_artifacts(out_dir, [])
            return json.dumps({
                "success": True,
                "assessments_dir": str(out_dir),
                "manifest_path": str(out_dir / "manifest.json"),
                "assessment_count": 0,
                "error": f"AssessmentGenerator import failed: {exc}",
            })

        # SFT-C S6 license flow-down (see the trainforge_assessment site above):
        # thread the teacher-license roster so the apply-arm's provider license
        # guard refuses a barred teacher. Inert by default (apply-arm opt-in);
        # best-effort → teacher_roster=None is byte-identical to the prior call.
        try:
            from lib.licensing import provider_verdict_roster as _pvr
            _teacher_roster = _pvr()
        except Exception:  # noqa: BLE001 — roster is best-effort
            _teacher_roster = None
        generator = AssessmentGenerator(
            capture=capture, check_leaks=False, teacher_roster=_teacher_roster,
        )
        built_assessments: List[Any] = []

        # Assessment-quality overhaul (ITEM 2): the deterministic DIVERSIFIED
        # tier (multiple-response / error-analysis / numeric-FIB / matching /
        # ordering / two-tier / written short_answer + extended_response, each
        # with per-item chunk-grounded rubrics) is opt-in behind
        # ED4ALL_ASSESSMENT_DIVERSIFIED. Default OFF → the byte-identical legacy
        # ``generate()`` MC/TF path. When ON the W10 quiz population comes from
        # ``generate_diversified()`` (item_subtype + per-distractor misconception
        # notes flow through to the emitter + answer key); per-CO coverage still
        # holds (``ensure_objective_coverage=True``). Folded into the quiz-unit
        # fingerprint knobs so a mid-run flip invalidates the resume sidecars.
        _diversified_on = os.environ.get(
            "ED4ALL_ASSESSMENT_DIVERSIFIED", ""
        ).strip().lower() in {"1", "true", "yes", "on"}

        # Per-CO coverage support: index the loaded chunks by id once so each
        # objective's cited
        # ``source_chunk_ids`` can scope its item's grounding. Anti-
        # fabrication: only chunks that actually exist in the loaded
        # chunkset are ever handed to the generator.
        _chunk_by_id: Dict[str, Dict[str, Any]] = {}
        for _c in loaded_chunks:
            _cid_key = _c.get("id") or _c.get("chunk_id")
            if isinstance(_cid_key, str) and _cid_key.strip():
                _chunk_by_id.setdefault(_cid_key.strip(), _c)

        def _cited_chunks_for_objective(obj_id: str) -> List[Dict[str, Any]]:
            record = co_map.get(obj_id) or to_map.get(obj_id) or {}
            cited: List[Dict[str, Any]] = []
            for _cid in record.get("source_chunk_ids") or []:
                if isinstance(_cid, str) and _cid.strip() in _chunk_by_id:
                    cited.append(_chunk_by_id[_cid.strip()])
            return cited

        for week_idx, tid in enumerate(terminal_ids, start=1):
            # Graceful stop at the unit boundary (sequential loop → plain
            # check_stop). Every completed unit is already checkpointed, so this
            # raises BEFORE the final manifest write with zero loss.
            check_stop("assessment_synthesis", _assessment_units_done)
            group_co_ids = cos_by_terminal.get(tid) or []
            # Quiz the TO + its child COs. A flat group quizzes the COs.
            obj_ids = (
                ([tid] if tid != "_FLAT_" else []) + list(group_co_ids)
            )
            obj_ids = [o for o in obj_ids if o in valid_objective_ids]
            if not obj_ids:
                continue
            # Per-CO coverage: the effective item budget grows to at least
            # one item per objective (TO + every child CO) so the strict
            # archival gate (OBJECTIVE_NO_ASSESSMENT / UNCOVERED_TERMINAL_
            # OUTCOME) sees every objective assessed.
            _q_effective_count = max(question_count, len(obj_ids))
            # ---- resume checkpoint: replay a completed quiz unit ----------
            # ``cov=per_co_v1`` in the knobs deliberately invalidates pre-
            # coverage sidecar units so a resumed run re-rolls quizzes under
            # the per-CO contract instead of replaying TO-only ones.
            _q_fp = _assessment_unit_fingerprint(
                kind="quiz",
                terminal_id=tid,
                statement=" \x1e ".join(
                    id_to_statement.get(o, o) for o in obj_ids
                ),
                chunkset_sha=_assessment_chunkset_sha_val,
                provider="assessment_generator",
                model="",
                prompt_version=_ASSESSMENT_PROMPT_VERSION,
                knobs=(
                    f"bloom={','.join(bloom_levels)};qc={question_count};"
                    f"cov=per_co_v1"
                    + (";div=1" if _diversified_on else "")
                ),
            )
            _q_key = _assessment_unit_key("quiz", tid)
            _q_reused = _assessments_store_obj.reuse(
                _q_key, _q_fp, cache=_assessments_cache
            )
            if _q_reused is not None:
                _cached = _q_reused.get("assessment")
                if isinstance(_cached, dict):
                    # The dict form flows through
                    # _build_assessment_artifacts_from_data /
                    # assessment_to_qti identically to the live dataclass.
                    built_assessments.append(_cached)
                    _assessment_units_done += 1
                continue
            try:
                _gen_fn = (
                    generator.generate_diversified
                    if _diversified_on
                    else generator.generate
                )
                assessment = _gen_fn(
                    course_code=str(course_code),
                    objective_ids=obj_ids,
                    bloom_levels=bloom_levels,
                    question_count=_q_effective_count,
                    source_chunks=loaded_chunks or None,
                    ensure_objective_coverage=True,
                    chunks_by_objective={
                        o: cited
                        for o in obj_ids
                        if (cited := _cited_chunks_for_objective(o))
                    },
                )
            except Exception as exc:
                logger.warning(
                    "run_assessment_synthesis: quiz generation failed for "
                    "TO %s (week %d): %s", tid, week_idx, exc,
                )
                continue
            # Anti-fabrication: drop any question whose objective_id is not
            # in the real universe (never emit a phantom-grounded item).
            kept, dropped = _filter_questions_to_objective_universe(
                assessment.questions, valid_objective_ids
            )
            assessment.questions = kept
            if dropped:
                logger.warning(
                    "run_assessment_synthesis: dropped %d quiz item(s) with "
                    "out-of-universe objective_id (week %d).",
                    len(dropped), week_idx,
                )
            if not kept:
                continue
            # Stamp a week for clean manifest nav.
            try:
                setattr(assessment, "week", week_idx)
            except Exception:
                pass
            if not getattr(assessment, "title", None):
                assessment.title = f"Week {week_idx} Quiz"
            else:
                assessment.title = f"Week {week_idx} Quiz"
            built_assessments.append(assessment)
            # Checkpoint the completed unit (to_dict() + week for the emit).
            try:
                _q_payload = dict(assessment.to_dict())
            except Exception:
                _q_payload = {
                    "assessment_id": getattr(assessment, "assessment_id", ""),
                    "title": getattr(assessment, "title", ""),
                    "questions": [],
                }
            _q_payload["week"] = week_idx
            _q_payload["title"] = assessment.title
            _assessments_store_obj.append(
                _q_key, _q_fp,
                {"kind": "quiz", "terminal_id": tid, "assessment": _q_payload},
            )
            _assessment_units_done += 1

        # ---- cross-quiz exact-duplicate stem guard (pre-emit) ------------
        # Deterministic: collapse exact-duplicate stems across the WHOLE quiz
        # set (first occurrence wins, later duplicates dropped, emptied
        # quizzes removed). Runs over the FINAL assembled list — fresh AND
        # checkpoint-replayed units alike — so the result is identical on a
        # resume. Honest count reduction beats salad duplication; any
        # objective whose only item(s) were duplicates is REPORTED loudly.
        built_assessments, _dedup_report = _dedup_assessment_stems(
            built_assessments
        )
        if _dedup_report["duplicates_removed"]:
            logger.warning(
                "run_assessment_synthesis: cross-quiz stem dedup collapsed "
                "%d exact-duplicate item(s) across %d duplicate group(s) "
                "(%d -> %d items; %d quiz(zes) emptied and dropped). "
                "Objectives losing all coverage to dedup: %s. The generator "
                "could not mint enough distinct stems from the chunk "
                "content — honest count reduction beats duplication.",
                _dedup_report["duplicates_removed"],
                _dedup_report["duplicate_groups"],
                _dedup_report["total_before"],
                _dedup_report["total_after"],
                len(_dedup_report["dropped_assessments"]),
                _dedup_report["objectives_losing_coverage"] or "none",
            )
        if capture is not None:
            try:
                capture.log_decision(
                    decision_type="assessment_stem_dedup",
                    decision=(
                        f"collapsed {_dedup_report['duplicates_removed']} "
                        f"duplicate stems: "
                        f"{_dedup_report['total_before']} -> "
                        f"{_dedup_report['total_after']} items"
                    ),
                    rationale=(
                        f"deterministic cross-quiz exact-stem dedup over "
                        f"{len(terminal_ids)} per-TO quizzes; "
                        f"duplicate_groups="
                        f"{_dedup_report['duplicate_groups']}; "
                        f"dropped_quizzes="
                        f"{_dedup_report['dropped_assessments']}; "
                        f"objectives_losing_coverage="
                        f"{_dedup_report['objectives_losing_coverage']}; "
                        f"chunkset_sha={_assessment_chunkset_sha_val[:12]}"
                    ),
                )
            except Exception:
                pass

        # ============================================================== #
        # 2. ASSIGNMENT + DISCUSSION PROSE — optional LLM prose seat.     #
        #    Grounded in real chunk ids; carry objective_id so the        #
        #    grounding gate fires unchanged. Graceful when no provider.   #
        # ============================================================== #
        discussions: List[Dict[str, Any]] = []
        assignments: List[Dict[str, Any]] = []

        prose_provider_name = os.environ.get(
            "ED4ALL_ASSESSMENT_PROSE_PROVIDER", ""
        ).strip()
        prose_provider = None
        if prose_provider_name:
            try:
                from Trainforge.generators._assessment_provider import (
                    AssessmentGeneratorProvider,
                )
                prose_provider = AssessmentGeneratorProvider(
                    provider=prose_provider_name,
                    capture=capture,
                )
            except Exception as exc:
                logger.warning(
                    "run_assessment_synthesis: prose provider %r "
                    "construction failed (%s); skipping assignment/"
                    "discussion prose (objective quizzes still emit).",
                    prose_provider_name, exc,
                )
                prose_provider = None

        # Resolve a small set of grounded chunk ids for an objective from
        # the loaded chunks (anti-fabrication: only real chunk ids).
        def _grounded_chunk_ids_for(obj_id: str, limit: int = 3) -> List[str]:
            ids: List[str] = []
            for _c in loaded_chunks:
                refs = _c.get("learning_outcome_refs") or []
                if isinstance(refs, list) and obj_id in {str(r) for r in refs}:
                    cid = _c.get("id") or _c.get("chunk_id")
                    if isinstance(cid, str) and cid.strip():
                        ids.append(cid.strip())
                if len(ids) >= limit:
                    break
            return ids

        # The prose model resolution (for the decision-capture rationale).
        prose_model = (
            getattr(prose_provider, "_model", None) if prose_provider else None
        )

        # 2a. One discussion per TERMINAL objective.
        for week_idx, tid in enumerate(terminal_ids, start=1):
            # Graceful stop at the unit boundary (sequential loop).
            check_stop("assessment_synthesis", _assessment_units_done)
            if tid == "_FLAT_" or tid not in to_map:
                continue
            statement = id_to_statement.get(tid, tid)
            # ---- resume checkpoint: replay a completed discussion unit ----
            _d_fp = _assessment_unit_fingerprint(
                kind="discussion",
                terminal_id=tid,
                statement=statement,
                chunkset_sha=_assessment_chunkset_sha_val,
                provider=prose_provider_name or "deterministic",
                model=str(prose_model or ""),
                prompt_version=_ASSESSMENT_PROMPT_VERSION,
            )
            _d_key = _assessment_unit_key("discussion", tid)
            _d_reused = _assessments_store_obj.reuse(
                _d_key, _d_fp, cache=_assessments_cache
            )
            if _d_reused is not None:
                _cd = _d_reused.get("discussion")
                if isinstance(_cd, dict):
                    discussions.append(_cd)
                    _assessment_units_done += 1
                continue
            grounded = _grounded_chunk_ids_for(tid)
            prompt_text = ""
            if prose_provider is not None:
                try:
                    prompt_text = _synthesize_prose_prompt(
                        prose_provider,
                        kind="discussion",
                        objective_id=tid,
                        statement=statement,
                        chunks=loaded_chunks,
                        grounded_chunk_ids=grounded,
                    )
                except Exception as exc:
                    logger.warning(
                        "run_assessment_synthesis: discussion prose failed "
                        "for %s: %s", tid, exc,
                    )
                    prompt_text = ""
            if not prompt_text:
                # Deterministic fallback prompt grounded in the objective
                # statement (never fabricates source content).
                prompt_text = (
                    f"Discuss how the ideas in this objective apply to a "
                    f"real situation: {statement}"
                )
            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="discussion_prompt_synthesis",
                        decision=f"discussion:{tid}:week_{week_idx}",
                        rationale=(
                            f"objective_id={tid}; "
                            f"source_chunk_ids={grounded}; "
                            f"provider={prose_provider_name or 'deterministic'}; "
                            f"model={prose_model}; "
                            f"n_grounded_chunks={len(grounded)}"
                        ),
                    )
                except Exception:
                    pass
            discussions.append({
                "discussion_id": f"DISC-{tid}",
                "objective_id": tid,
                "title": f"Week {week_idx} Discussion",
                "text": prompt_text,
                "week": week_idx,
            })
            _assessments_store_obj.append(
                _d_key, _d_fp,
                {
                    "kind": "discussion",
                    "terminal_id": tid,
                    "discussion": discussions[-1],
                },
            )
            _assessment_units_done += 1

        # 2b. One assignment per CO-cluster (per TO's child-CO group).
        for week_idx, tid in enumerate(terminal_ids, start=1):
            # Graceful stop at the unit boundary (sequential loop).
            check_stop("assessment_synthesis", _assessment_units_done)
            group_co_ids = [
                c for c in (cos_by_terminal.get(tid) or [])
                if c in valid_objective_ids
            ]
            if not group_co_ids:
                continue
            # Anchor the assignment on the first CO of the cluster.
            anchor = group_co_ids[0]
            statement = id_to_statement.get(anchor, anchor)
            # ---- resume checkpoint: replay a completed assignment unit ----
            _a_fp = _assessment_unit_fingerprint(
                kind="assignment",
                terminal_id=tid,
                statement=statement,
                chunkset_sha=_assessment_chunkset_sha_val,
                provider=prose_provider_name or "deterministic",
                model=str(prose_model or ""),
                prompt_version=_ASSESSMENT_PROMPT_VERSION,
                knobs=f"anchor={anchor}",
            )
            _a_key = _assessment_unit_key("assignment", tid)
            _a_reused = _assessments_store_obj.reuse(
                _a_key, _a_fp, cache=_assessments_cache
            )
            if _a_reused is not None:
                _ca = _a_reused.get("assignment")
                if isinstance(_ca, dict):
                    assignments.append(_ca)
                    _assessment_units_done += 1
                continue
            grounded = _grounded_chunk_ids_for(anchor)
            task_text = ""
            if prose_provider is not None:
                try:
                    task_text = _synthesize_prose_prompt(
                        prose_provider,
                        kind="assignment",
                        objective_id=anchor,
                        statement=statement,
                        chunks=loaded_chunks,
                        grounded_chunk_ids=grounded,
                    )
                except Exception as exc:
                    logger.warning(
                        "run_assessment_synthesis: assignment prose failed "
                        "for %s: %s", anchor, exc,
                    )
                    task_text = ""
            if not task_text:
                task_text = (
                    f"Complete a short task demonstrating this objective: "
                    f"{statement}"
                )
            if capture is not None:
                try:
                    capture.log_decision(
                        decision_type="assignment_prompt_synthesis",
                        decision=f"assignment:{anchor}:week_{week_idx}",
                        rationale=(
                            f"objective_id={anchor}; "
                            f"source_chunk_ids={grounded}; "
                            f"provider={prose_provider_name or 'deterministic'}; "
                            f"model={prose_model}; "
                            f"n_grounded_chunks={len(grounded)}"
                        ),
                    )
                except Exception:
                    pass
            assignments.append({
                "assignment_id": f"ASGN-{anchor}",
                "objective_id": anchor,
                "title": f"Week {week_idx} Assignment",
                "text": task_text,
                "points": 10,
                "week": week_idx,
            })
            _assessments_store_obj.append(
                _a_key, _a_fp,
                {
                    "kind": "assignment",
                    "terminal_id": tid,
                    "assignment": assignments[-1],
                },
            )
            _assessment_units_done += 1

        # ============================================================== #
        # 3. EMIT — XML + manifest via the pure helpers.                 #
        # ============================================================== #
        try:
            artifacts = _build_assessment_artifacts_from_data(
                built_assessments, discussions, assignments
            )
        except Exception as exc:
            logger.warning(
                "run_assessment_synthesis: XML emit failed (%s); writing "
                "empty manifest.", exc,
            )
            artifacts = []
        manifest = _write_assessment_artifacts(out_dir, artifacts)

        # ---- QTI item BANK sidecar (question-library surface) --------------- #
        # The per-week `<assessment>` documents above are fixed EXAMS. The bank
        # is the reusable question-LIBRARY: one QTI 1.2 `<objectbank>` carrying
        # every emitted item with queryable per-item qtimetadata (objective id,
        # Bloom level, item subtype, question type), so a consumer can SELECT
        # items by objective/Bloom instead of re-parsing prose.
        #
        # Deliberately a SIDECAR, recorded under its own top-level manifest key
        # rather than inside `assessments[]`: an objectbank document's root tag
        # is `questestinterop`, which the packager's root-tag map
        # (package_multifile_imscc.py) resolves to the `qti` resource type — so
        # listing it in assessments[] would ship the whole item bank into the
        # cartridge AS AN EXAM. The sidecar keeps it out of the LMS resource
        # set while remaining available as a course artifact.
        if _item_bank_enabled():
            try:
                from Courseforge.scripts.qti_emitter import (  # noqa: PLC0415
                    assessment_to_objectbank,
                )
                _bank_questions: List[Any] = []
                for _a in built_assessments:
                    _ad = _a.to_dict() if hasattr(_a, "to_dict") else _a
                    if isinstance(_ad, dict):
                        _bank_questions.extend(_ad.get("questions") or [])
                if _bank_questions:
                    # course_name is NOT a local here — this handler takes
                    # **kwargs (mirrors the project_id fallback above).
                    _bank_course = str(
                        kwargs.get("course_code")
                        or kwargs.get("course_name")
                        or "course"
                    ).strip() or "course"
                    _bank_xml = assessment_to_objectbank({
                        "bank_id": f"BANK-{_bank_course}",
                        "title": f"{_bank_course} — Item Bank",
                        "questions": _bank_questions,
                    })
                    (out_dir / "item_bank.xml").write_text(
                        _bank_xml, encoding="utf-8"
                    )
                    manifest["item_bank"] = {
                        "file": "item_bank.xml",
                        "kind": "objectbank",
                        "item_count": len(_bank_questions),
                        "packaged": False,
                    }
                    (out_dir / "manifest.json").write_text(
                        json.dumps(manifest, indent=2, ensure_ascii=False),
                        encoding="utf-8",
                    )
                    logger.info(
                        "run_assessment_synthesis: wrote item_bank.xml "
                        "(%d items, sidecar — not packaged).",
                        len(_bank_questions),
                    )
            except Exception as exc:  # noqa: BLE001 — sidecar is best-effort
                logger.warning(
                    "run_assessment_synthesis: item-bank emit failed (%s); "
                    "per-week quizzes are unaffected.", exc,
                )

        # ---- Instructor answer key (assessment-quality overhaul C.2) -------- #
        # A deterministic, grounded sidecar carrying everything the six CC QTI
        # primitives cannot transport: worked solutions (each citing the chunk
        # ids the generator stamped), per-distractor misconception rationale,
        # and Bloom-derived rubric scaffolds for the essay / discussion /
        # assignment surfaces. Emitted whenever ANY graded item exists; wired
        # into manifest.json as a new assessments[] row type="answer_key" whose
        # answer_key.html ships as a CC webcontent resource. Best-effort: an
        # emit failure logs a warning and never aborts the phase.
        _has_answer_key = False
        if built_assessments or discussions or assignments:
            try:
                from Courseforge.scripts.answer_key_emitter import emit_answer_key
                _ak_entry = emit_answer_key(
                    out_dir,
                    assessments=built_assessments,
                    discussions=discussions,
                    assignments=assignments,
                    objective_text=id_to_statement,
                    course_code=str(course_code),
                    course_title=f"{course_code} — Instructor Answer Key",
                )
                manifest.setdefault("assessments", []).append(_ak_entry)
                (out_dir / "manifest.json").write_text(
                    json.dumps(manifest, indent=2, ensure_ascii=False),
                    encoding="utf-8",
                )
                _has_answer_key = True
            except Exception as exc:  # noqa: BLE001 — never abort the phase
                logger.warning(
                    "run_assessment_synthesis: answer-key emit failed (%s); "
                    "quizzes/prose still emitted.", exc,
                )

        # Resume is only for an INTERRUPTED run: drop the sidecar now that the
        # final manifest write has succeeded (mirrors the tier sidecars).
        _assessments_store_obj.remove()

        quiz_n = sum(1 for e in manifest["assessments"] if e.get("type") == "qti")
        disc_n = sum(
            1 for e in manifest["assessments"] if e.get("type") == "discussion"
        )
        asgn_n = sum(
            1 for e in manifest["assessments"] if e.get("type") == "assignment"
        )
        return json.dumps({
            "success": True,
            "assessments_dir": str(out_dir),
            "manifest_path": str(out_dir / "manifest.json"),
            "assessment_count": len(manifest["assessments"]),
            "quiz_count": quiz_n,
            "discussion_count": disc_n,
            "assignment_count": asgn_n,
            "prose_provider": prose_provider_name or None,
            "answer_key": _has_answer_key,
        })

    registry["run_assessment_synthesis"] = _run_assessment_synthesis

    # ============================================================================
    # Phase 7c Subtask 16: _run_imscc_chunking — IMSCC chunkset emit
    #
    # New ``imscc_chunking`` workflow phase (between ``packaging`` and
    # ``training_synthesis`` per Phase 7c ST 16). The phase invokes
    # ``Trainforge.chunker.chunk_content`` over the HTML files extracted from
    # the packaged IMSCC zip emitted by the upstream ``packaging`` phase,
    # persists the resulting chunks to
    # ``LibV2/courses/<slug>/imscc_chunks/chunks.jsonl`` plus a sibling
    # ``manifest.json`` (matching the canonical
    # ``schemas/library/chunkset_manifest.schema.json`` shape with
    # ``chunkset_kind="imscc"``), computes the SHA-256 of the chunks file,
    # and surfaces both the path and hash through phase outputs.
    #
    # Mirrors the ``_run_dart_chunking`` template above (Phase 7b
    # ST 11 commit ``5ccbf0c``); the structural differences are:
    #
    # - Source artifact: a packaged ``.imscc`` zip (``imscc_path`` kwarg
    #   resolved from ``phase_outputs.packaging.package_path``) rather
    #   than a staging directory of loose HTML files.
    # - ``source_imscc_sha256`` (SHA-256 of the .imscc archive bytes)
    #   replaces ``source_semantik_html_sha256`` in the manifest emit.
    # - ``chunkset_kind="imscc"`` discriminates downstream consumers
    #   (the schema's conditional source-SHA branch fires accordingly).
    # - HTML files are read from inside the zip in-memory via
    #   ``zipfile.ZipFile`` (no on-disk extraction required).
    #
    # Per Phase 7c ST 15 (commit ``090d286``), the directory was renamed
    # from ``corpus/`` to ``imscc_chunks/`` symmetrically with the new
    # ``dart_chunks/`` directory. Trainforge's in-process chunker
    # invocation in ``Trainforge/process_course.py`` is preserved for
    # legacy callers (no churn this subtask) — this phase provides a
    # workflow-level entry point that downstream orchestrator runs use
    # in lieu of re-running the in-process chunker.
    # ============================================================================
    async def _run_imscc_chunking(**kwargs):
        """Run the canonical chunker over the packaged IMSCC archive.

        Required kwargs (resolved via ``inputs_from`` in workflows.yaml's
        ``imscc_chunking`` phase):
            course_name: Canonical course name (used for course slug).
            imscc_path: Path to the packaged ``.imscc`` archive emitted by
                the upstream ``packaging`` phase
                (``phase_outputs.packaging.package_path``).

        Outputs (returned as JSON envelope + persisted):
            imscc_chunks_path: ``LibV2/courses/<slug>/imscc_chunks/chunks.jsonl``
            imscc_chunks_sha256: SHA-256 hex digest of the chunks file bytes

        Sibling ``manifest.json`` is also emitted at the same directory,
        carrying the canonical ``chunkset_manifest`` schema shape
        (``chunkset_kind="imscc"``, ``source_imscc_sha256``) so the
        ``ChunksetManifestValidator`` gate has something to validate
        against.
        """
        import hashlib as _hashlib
        import zipfile as _zipfile

        course_name = kwargs.get("course_name") or ""
        imscc_path_kw = kwargs.get("imscc_path") or kwargs.get("package_path") or ""

        course_name = course_name or "UNKNOWN"
        course_slug = course_name.lower().replace("_", "-").replace(" ", "-")
        # W0.6: normalise the chunk-ID course_code WITH the space→underscore
        # replacement (the bare ``.upper().replace("-", "_")`` omitted it, so a
        # space-bearing course name leaked whitespace into every chunk id).
        course_code = _normalize_chunk_course_code(course_name)

        # Honest IRT difficulty-calibration scaffold
        # (TRAINFORGE_IRT_DIFFICULTY_SCAFFOLD). Build the calibrated-difficulty
        # map ONCE per run from the optional learner-response seam; threaded
        # into the chunk-emit site below so these chunks get difficulty
        # provenance parity with the IMSCC (process_course) path. Empty +
        # no-op when the flag is off (byte-identical legacy emit) or no
        # response file exists.
        _irt_enabled = False
        _irt_calibrated_map: Dict[str, Any] = {}
        _irt_response_present = False
        try:
            from lib.assessment.irt_difficulty import (
                irt_scaffold_enabled as _irt_scaffold_enabled,
                load_calibrated_difficulty as _irt_load_calibrated,
                resolve_response_data_path as _irt_resolve_responses,
                tag_chunk_difficulty_provenance as _irt_tag_chunk,
            )
            _irt_enabled = _irt_scaffold_enabled()
            if _irt_enabled:
                _irt_resp_path = _irt_resolve_responses(
                    course_slug, libv2_root=kwargs.get("libv2_root")
                )
                _irt_response_present = _irt_resp_path is not None
                _irt_calibrated_map = _irt_load_calibrated(_irt_resp_path)
        except Exception as _irt_exc:  # noqa: BLE001 — scaffold never breaks chunking
            logger.warning("IRT difficulty scaffold setup failed: %s", _irt_exc)
            _irt_enabled = False

        # Resolve IMSCC path. Honor explicit kwarg first; emit an empty
        # shell + log a warning when the upstream phase didn't surface
        # a real path so the manifest is still schema-valid (mirroring
        # ``_run_dart_chunking``'s fail-soft empty-input shell).
        imscc_path: Optional[Path] = None
        if imscc_path_kw:
            cand = Path(imscc_path_kw)
            if cand.exists() and cand.is_file():
                imscc_path = cand

        if imscc_path is None:
            # Wave1-I2: resume-safety guard. Do NOT overwrite a
            # previously-emitted chunks.jsonl with an empty-bytes shell
            # on a workflow resume that drops imscc_path from carried-
            # forward phase context. The prior fail-soft empty-shell
            # behaviour silently destroyed real chunks (see
            # plans/dispatch-7-execution-inspection-2026-05.md Finding 2;
            # cost ~92 chunks during a real 2026-05 full-book run).
            # Preserve when an existing artifact is found; fail-closed
            # when there's nothing to preserve.
            existing_chunks_path = (
                _resolve_libv2_root(kwargs.get("libv2_root"))
                / "courses"
                / course_slug
                / "imscc_chunks"
                / "chunks.jsonl"
            )
            if existing_chunks_path.exists():
                existing_sha = _hashlib.sha256(
                    existing_chunks_path.read_bytes()
                ).hexdigest()
                existing_count = sum(
                    1
                    for line in existing_chunks_path.read_text(
                        encoding="utf-8"
                    ).splitlines()
                    if line.strip()
                )
                logger.warning(
                    "Wave1-I2: _run_imscc_chunking imscc_path %r missing "
                    "or not a file; preserving existing chunks.jsonl at "
                    "%s (%d chunks, sha256=%s) instead of overwriting "
                    "with empty shell.",
                    imscc_path_kw,
                    existing_chunks_path,
                    existing_count,
                    existing_sha,
                )
                manifest_path = existing_chunks_path.parent / "manifest.json"
                # Read source_imscc_sha256 from the existing manifest if
                # available; otherwise emit None so callers know it's
                # not derivable without the archive on hand.
                preserved_source_sha: Optional[str] = None
                if manifest_path.exists():
                    try:
                        preserved_manifest = json.loads(
                            manifest_path.read_text(encoding="utf-8")
                        )
                        preserved_source_sha = preserved_manifest.get(
                            "source_imscc_sha256"
                        )
                    except (OSError, json.JSONDecodeError):
                        preserved_source_sha = None
                return json.dumps({
                    "success": True,
                    "preserved_existing": True,
                    "imscc_chunks_path": str(existing_chunks_path),
                    "imscc_chunks_sha256": existing_sha,
                    "manifest_path": str(manifest_path),
                    "course_slug": course_slug,
                    "chunks_count": existing_count,
                    "source_html_count": 0,
                    "source_imscc_sha256": preserved_source_sha,
                    "chunker_version": _resolve_chunker_version(),
                })
            raise RuntimeError(
                "Wave1-I2: _run_imscc_chunking refusing to emit empty "
                "chunks.jsonl shell — imscc_path "
                f"{imscc_path_kw!r} is missing or not a file, and no "
                f"pre-existing artifact at {existing_chunks_path}. "
                "On a workflow resume, ensure imscc_path is carried "
                "forward via phase_outputs.packaging.package_path."
            )

        # Compute source SHA-256 over the .imscc archive bytes. Per
        # the schema's ``source_imscc_sha256`` description: a single
        # SHA-256 over the zip bytes (the archive is one file, unlike
        # the multi-file DART HTML aggregate). Empty input shell uses
        # SHA of empty bytes for determinism.
        if imscc_path is not None:
            agg = _hashlib.sha256()
            try:
                with imscc_path.open("rb") as fh:
                    for blk in iter(lambda: fh.read(65536), b""):
                        agg.update(blk)
                source_imscc_sha256 = agg.hexdigest()
            except OSError as exc:
                logger.warning(
                    "Phase 7c ST 16: failed to read imscc %s (%s); "
                    "using empty-bytes SHA sentinel.",
                    imscc_path, exc,
                )
                source_imscc_sha256 = _hashlib.sha256(b"").hexdigest()
        else:
            source_imscc_sha256 = _hashlib.sha256(b"").hexdigest()

        # Extract HTML files from inside the IMSCC zip. We walk the
        # archive in-memory rather than calling
        # ``IMSCCParser.extract_to_directory`` so the helper has no
        # filesystem side effects beyond the ``imscc_chunks/`` write.
        html_entries: List[Dict[str, str]] = []  # [{"path": ..., "content": ...}, ...]
        # W10 per-CO coverage: also collect the packaged assessment XML
        # (``06_assessments/*.xml`` — QTI quizzes + imsdt discussions +
        # assignments; non-QTI roots are filtered later by the harvest
        # helper) so per-item ``assessment_item`` chunks can be minted.
        qti_entries: List[Dict[str, str]] = []
        if imscc_path is not None:
            try:
                with _zipfile.ZipFile(imscc_path, "r") as zf:
                    for name in sorted(zf.namelist()):
                        if name.endswith(".html") or name.endswith(".htm"):
                            # Instructor-only sidecars under 06_assessments/
                            # (e.g. answer_key.html — correct answers + worked
                            # solutions) are NOT learner content and must never
                            # enter the retrieval corpus (answer-key leakage).
                            # The QTI XML in the same dir is separately harvested
                            # into assessment_item chunks via qti_entries.
                            if "06_assessments/" in name:
                                continue
                            try:
                                content = zf.read(name).decode(
                                    "utf-8", errors="ignore"
                                )
                            except Exception as exc:  # noqa: BLE001
                                logger.warning(
                                    "Phase 7c ST 16: failed to read %s "
                                    "from imscc (%s); skipping.",
                                    name, exc,
                                )
                                continue
                            html_entries.append({"path": name, "content": content})
                        elif name.endswith(".xml") and (
                            "06_assessments/" in name
                        ):
                            try:
                                content = zf.read(name).decode(
                                    "utf-8", errors="ignore"
                                )
                            except Exception as exc:  # noqa: BLE001
                                logger.warning(
                                    "W10 per-CO coverage: failed to read "
                                    "assessment XML %s from imscc (%s); "
                                    "skipping.",
                                    name, exc,
                                )
                                continue
                            qti_entries.append({"path": name, "content": content})
            except _zipfile.BadZipFile as exc:
                logger.warning(
                    "Phase 7c ST 16: %s is not a valid zip (%s); "
                    "emitting empty chunks shell.",
                    imscc_path, exc,
                )
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "Phase 7c ST 16: zip-walk failed on %s (%s); "
                    "emitting empty chunks shell.",
                    imscc_path, exc,
                )

        # Parse each HTML payload via Trainforge's HTMLContentParser
        # into ContentSection-bearing parsed_items shaped exactly like
        # the IMSCC consumer in ``Trainforge/process_course.py``.
        parsed_items: List[Dict[str, Any]] = []
        try:
            from Trainforge.parsers.html_content_parser import HTMLContentParser
        except Exception as exc:  # noqa: BLE001 — import failures shouldn't crash phase
            logger.warning(
                "Phase 7c ST 16: HTMLContentParser import failed (%s); "
                "emitting empty chunks shell.",
                exc,
            )
            html_parser = None
        else:
            html_parser = HTMLContentParser()

        if html_parser is not None and html_entries:
            for entry in html_entries:
                html_text = entry["content"]
                inner_path = entry["path"]
                try:
                    parsed = html_parser.parse(html_text)
                except Exception as exc:  # noqa: BLE001 — parser errors fail soft
                    logger.warning(
                        "Phase 7c ST 16: HTML parse failed for %s (%s); "
                        "skipping.",
                        inner_path, exc,
                    )
                    continue
                slug = Path(inner_path).stem.lower().replace(" ", "-")
                parsed_items.append({
                    "item_id": slug,
                    "item_path": inner_path,
                    "title": parsed.title or slug,
                    "resource_type": "page",
                    "module_id": slug,
                    "module_title": parsed.title or slug,
                    "week_num": 0,
                    "word_count": parsed.word_count,
                    "sections": parsed.sections,
                    "learning_objectives": parsed.learning_objectives,
                    "key_concepts": parsed.key_concepts,
                    "interactive_components": parsed.interactive_components,
                    "raw_html": html_text,
                    "page_id": parsed.page_id,
                    "misconceptions": parsed.misconceptions,
                    "suggested_assessment_types": parsed.suggested_assessment_types,
                    "courseforge_metadata": parsed.metadata.get("courseforge"),
                    "objective_refs": parsed.objective_refs,
                    "source_references": parsed.source_references,
                })

        # ``concept_tags`` IS populated here (previously hardcoded ``[]``):
        # the empty-tag substrate starved every downstream concept-graph +
        # CURIE consumer (the IMSCC chunkset feeds the same machinery the
        # DART chunkset does). Mirror ``_run_dart_chunking`` exactly: tag
        # from the chunk text + the HTML parser's bold-term / definition
        # ``key_concepts`` via the instance-free
        # ``lib.ontology.concept_tagging.extract_concept_tags`` helper (the
        # same logic ``CourseProcessor._extract_concept_tags`` delegates
        # to). ``extract_concept_tags`` honors the
        # ``TRAINFORGE_SEED_TECH_CONCEPTS`` (tech-anchor seeding) and
        # ``TRAINFORGE_PRUNE_SCAFFOLDING_CONCEPTS`` (scaffolding prune)
        # flags internally; the fragment-filter
        # (``TRAINFORGE_FILTER_FRAGMENT_CONCEPTS``) + content-aware
        # chunk_type (``TRAINFORGE_CHUNK_TYPE_CONTENT_AWARE``) flags fire in
        # the parser / chunker the IMSCC path already routes through.
        # ``domain_concept_seeds`` is empty here (post-packaging IMSCC
        # chunking carries no per-course seed compiler instance), matching
        # the DART path's default-empty seeds.
        from lib.ontology.concept_tagging import extract_concept_tags
        from Trainforge.chunker import (
            extract_learning_outcome_refs as _extract_learning_outcome_refs,
        )

        # FIX #3c (mirrored from ``_run_dart_chunking``): chunk-local
        # concept_tags behind ``TRAINFORGE_CHUNK_LOCAL_TAGS``. When OFF
        # (default), every chunk on a page tags from the SAME page-level
        # ``item["key_concepts"]`` set. When ON, each chunk's tags derive
        # from ITS OWN text: page-level ``key_concepts`` are filtered to
        # those whose surface form appears in this chunk, unioned with
        # concepts extracted from the chunk's own text via the shared
        # lexical-seed machinery (re-routed through ``extract_concept_tags``
        # so scaffolding-noise filtering still applies).
        chunk_local_tags = (
            os.getenv("TRAINFORGE_CHUNK_LOCAL_TAGS", "").lower() == "true"
        )
        _CHUNK_LOCAL_TAG_CAP = 12
        if chunk_local_tags:
            from lib.ontology.lexical_concept_seeds import (
                derive_lexical_concept_seeds as _derive_lexical_concept_seeds,
                is_fragment_phrase as _is_fragment_phrase,
            )
            from lib.ontology.concept_classifier import (
                is_scaffolding_noise as _is_scaffolding_noise,
            )

            def _chunk_local_extracted_tags(text: str) -> List[str]:
                """Extract chunk-local concept-tag slugs from ``text`` only.

                Routes the chunk text through the shared lexical seed
                deriver (``min_doc_freq=1`` so a single-chunk corpus still
                yields multi-word phrases), then re-applies the same
                quality gates the rest of the pipeline uses
                (``is_fragment_phrase`` + ``is_scaffolding_noise``).
                """
                if not text:
                    return []
                try:
                    seeds = _derive_lexical_concept_seeds(
                        [{"text": text}], min_doc_freq=1
                    )
                except Exception:  # noqa: BLE001 — extraction is best-effort
                    return []
                out: List[str] = []
                for slug in seeds:
                    if not slug:
                        continue
                    if "-" in slug and _is_fragment_phrase(
                        slug.replace("-", " ")
                    ):
                        continue
                    if _is_scaffolding_noise(slug):
                        continue
                    out.append(slug)
                return out

        # Tokeniser for chunk-local key-concept membership (mirrors
        # ``_run_dart_chunking``): split a concept surface form into
        # alphanumeric tokens so "Knowledge Base" -> ["knowledge", "base"].
        _CONCEPT_TOKEN_RE = re.compile(r"[a-z0-9]+(?:[-'][a-z0-9]+)*")

        def _key_concept_in_text(concept: str, text_lower: str) -> bool:
            """True iff every alphanumeric token of ``concept`` appears in
            ``text_lower`` (case-insensitive)."""
            toks = [t for t in _CONCEPT_TOKEN_RE.findall(concept.lower()) if t]
            if not toks:
                return False
            return all(t in text_lower for t in toks)

        def _filter_item_key_concepts(
            item: Dict[str, Any], text: str
        ) -> Dict[str, Any]:
            """Return a shallow-copied ``item`` whose ``key_concepts`` is
            restricted to concepts whose words appear in ``text``."""
            page_concepts = item.get("key_concepts") or []
            if not page_concepts:
                return item
            text_lower = (text or "").lower()
            local_concepts = [
                c for c in page_concepts
                if _key_concept_in_text(str(c), text_lower)
            ]
            local_item = dict(item)
            local_item["key_concepts"] = local_concepts
            return local_item

        # Minimal create_chunk callback — emits a v4-shaped chunk dict
        # without CourseProcessor's deep instance state. Mirrors
        # ``_run_dart_chunking``'s callback exactly so DART + IMSCC
        # chunks share a single chunk shape (the same v4 contract).
        def _create_chunk(
            *,
            chunk_id: str,
            text: str,
            html: str,
            item: Dict[str, Any],
            section_heading: str,
            chunk_type: str,
            follows_chunk_id: Optional[str] = None,
            position_in_module: int = 0,
            html_xpath: Optional[str] = None,
            char_span: Optional[List[int]] = None,
            section_source_ids: Optional[List[str]] = None,
            merged_headings: Optional[List[str]] = None,
            dart_source_refs: Optional[List[Dict[str, Any]]] = None,
            composite_unit: Optional[str] = None,
            unit_roles: Optional[List[str]] = None,
            unit_subclass: Optional[str] = None,
        ) -> Dict[str, Any]:
            words = text.split()
            word_count = len(words)
            tokens_estimate = int(word_count * 1.3)
            # Defensive heading-sanity filter (TRAINFORGE_HEADING_SANITY_FILTER,
            # default OFF → byte-identical legacy). When a chunk's
            # ``section_heading`` is detected as upstream heading-classifier
            # noise (answer-key/exercise-prose/numeric), repair it to the
            # nearest clean ancestor heading (merged_headings breadcrumb, then
            # page title) — the original noise text stays in ``text``/``html``.
            # No clean ancestor → leave as-is + stamp ``heading_suspect``.
            _heading_to_stamp = section_heading
            _heading_suspect_flag = False
            try:
                from lib.chunk_heading_sanity import (
                    is_heading_sanity_filter_enabled as _hs_enabled,
                    repair_section_heading as _hs_repair,
                )
                if _hs_enabled():
                    _hs = _hs_repair(
                        section_heading,
                        item=item,
                        merged_headings=merged_headings,
                    )
                    _heading_to_stamp = _hs["heading"]
                    _heading_suspect_flag = _hs["suspect"] and not _hs["repaired"]
            except Exception:  # noqa: BLE001 — sanity filter is best-effort
                logger.warning(
                    "heading-sanity filter failed for chunk %s; keeping "
                    "original section_heading",
                    chunk_id,
                    exc_info=True,
                )
                _heading_to_stamp = section_heading
                _heading_suspect_flag = False
            # Title sanitizer (SEMANTIK_TITLE_SANITIZE, default OFF →
            # byte-identical). Scanned-textbook OCR fuses the chapter title
            # with the running header + page number + first content word
            # ("Chapter 1 Foundations 83 ✓ Solution"); left un-sanitized that
            # furniture lands on every chunk's provenance title (144/185 chunks
            # on a real 3-chapter scan). Strip it to the clean chapter title.
            _module_title = item.get("module_title") or ""
            _lesson_title = item.get("title") or ""
            try:
                from lib.textbook_title_sanitize import (
                    sanitize_running_header_title as _san_title,
                    title_sanitize_enabled as _san_enabled,
                )
                if _san_enabled():
                    _module_title = _san_title(_module_title)
                    _lesson_title = _san_title(_lesson_title)
            except Exception:  # noqa: BLE001 — sanitizer is best-effort
                _module_title = item.get("module_title") or ""
                _lesson_title = item.get("title") or ""
            source: Dict[str, Any] = {
                "course_id": course_code,
                "module_id": item.get("module_id") or "",
                "module_title": _module_title,
                "lesson_id": item.get("item_id") or "",
                "lesson_title": _lesson_title,
                "resource_type": item.get("resource_type") or "page",
                "section_heading": _heading_to_stamp,
                "position_in_module": position_in_module,
            }
            if _heading_suspect_flag:
                source["heading_suspect"] = True
            if html_xpath:
                source["html_xpath"] = html_xpath
            if char_span is not None:
                source["char_span"] = list(char_span)
            if item.get("item_path"):
                source["item_path"] = item["item_path"]
            # GPT Feedback v2 (May 12 / item 3): thread the aggregate
            # IMSCC zip SHA from the sidecar manifest into every chunk's
            # source block. See schemas/knowledge/chunk_v4.schema.json::
            # $defs.Source.source_document_sha256.
            if source_imscc_sha256:
                source["source_document_sha256"] = source_imscc_sha256
            # B1+B2 parity with the DART path: when an imscc-chunked page
            # happens to carry DART provenance attributes, mint the same
            # canonical source_references[]. No-op for ordinary IMSCC /
            # Courseforge HTML (no ``data-dart-*`` attrs → harvest is empty).
            dart_refs = _semantik_block_source_references(
                dart_source_refs, item.get("item_id") or ""
            )
            if dart_refs:
                source["source_references"] = dart_refs
            # Wave3-Anew2: bloom_level + difficulty resolution via the
            # canonical JSON-LD > data-cf > heuristic cascade.
            bloom_level, bloom_source = _resolve_chunk_bloom_level(item, text)
            difficulty = _resolve_chunk_difficulty(item, text, bloom_level)
            # Real domain-concept tags from the chunk text + the HTML
            # parser's bold-term / definition ``key_concepts`` (previously
            # hardcoded ``[]``, which starved every downstream concept
            # consumer). Mirrors ``_run_dart_chunking`` exactly: empty
            # per-course ``domain_concept_seeds``; honors the chunk-local
            # flag. Defensive: a tagging failure must not abort the chunking
            # phase — fall back to ``[]`` (legacy behaviour).
            try:
                tag_item = (
                    _filter_item_key_concepts(item, text)
                    if chunk_local_tags
                    else item
                )
                concept_tags = extract_concept_tags(text, tag_item)
                if chunk_local_tags:
                    seen = set(concept_tags)
                    merged = list(concept_tags)
                    for slug in _chunk_local_extracted_tags(text):
                        if slug not in seen:
                            seen.add(slug)
                            merged.append(slug)
                    concept_tags = merged[:_CHUNK_LOCAL_TAG_CAP]
            except Exception:  # noqa: BLE001 — tagging is best-effort
                logger.warning(
                    "concept-tag extraction failed for chunk %s; "
                    "emitting empty concept_tags",
                    chunk_id,
                    exc_info=True,
                )
                concept_tags = []
            # LO-anchoring fix: harvest the LO ids the source page carried
            # (JSON-LD learningObjectives[].id + section data-cf-objective-id
            # / -ref) and anchor this chunk to its section's LOs. Empty for
            # legacy / non-Courseforge IMSCC pages (byte-identical to the
            # prior hardcoded []). Best-effort: a harvest failure must not
            # abort the chunking phase.
            try:
                lo_refs = _extract_learning_outcome_refs(item, section_heading)
            except Exception:  # noqa: BLE001 — LO harvest is best-effort
                logger.warning(
                    "learning_outcome_refs extraction failed for chunk %s; "
                    "emitting empty learning_outcome_refs",
                    chunk_id,
                    exc_info=True,
                )
                lo_refs = []
            chunk: Dict[str, Any] = {
                "id": chunk_id,
                "schema_version": "v4",
                "chunk_type": chunk_type,
                "text": text,
                "html": html,
                "follows_chunk": follows_chunk_id,
                "source": source,
                "concept_tags": concept_tags,
                "learning_outcome_refs": lo_refs,
                "difficulty": difficulty,
                "tokens_estimate": tokens_estimate,
                "word_count": word_count,
                "bloom_level": bloom_level,
            }
            if bloom_source in ("verbs", "default"):
                chunk["bloom_level_source"] = bloom_source
            # IRT difficulty-calibration scaffold: stamp provenance (+ optional
            # IRT block from real responses). No-op + byte-identical when off.
            if _irt_enabled:
                try:
                    _irt_tag_chunk(chunk, _irt_calibrated_map)
                except Exception:  # noqa: BLE001 — never break chunk emit
                    logger.warning("IRT chunk tagging failed for %s", chunk.get("id"))
            # Wave #22 quick-wins: additive pedagogical-role metadata (empty on
            # non-SemantiK IMSCC → byte-identical; present when a converted DART
            # IMSCC carries data-dart-unit / -flow / -opener).
            if composite_unit:
                chunk["composite_unit"] = composite_unit
            if unit_roles:
                chunk["unit_roles"] = list(unit_roles)
            return chunk

        # Dispatch to the canonical chunker. ``chunk_content`` is
        # fail-soft on empty input.
        chunks: List[Dict[str, Any]] = []
        chunker_version = _resolve_chunker_version()
        try:
            from Trainforge.chunker import ChunkerContext, chunk_content
        except Exception as exc:  # noqa: BLE001 — import failures shouldn't crash phase
            logger.warning(
                "Phase 7c ST 16: Trainforge.chunker import failed (%s); "
                "emitting empty chunks shell.",
                exc,
            )
        else:
            try:
                ctx = ChunkerContext(create_chunk=_create_chunk) if parsed_items else None
                # ED4ALL_IMSCC_MAX_CHUNK_SIZE: per-IMSCC override of the chunker's
                # MAX_CHUNK_SIZE (words). Lets the operator chunk finer (e.g. 350)
                # so heading-rich Courseforge pages sub-divide into more retrieval
                # chunks WITHOUT touching the global constant or the DART/corpus
                # chunking. Unset → byte-identical legacy default (800). Parse-
                # with-fallback (mirrors the other ED4ALL_* numeric knobs); the
                # target size tracks at ~0.7x so sentence-splitting stays sane.
                _imscc_chunk_kwargs: Dict[str, Any] = {}
                _imscc_max_raw = os.getenv("ED4ALL_IMSCC_MAX_CHUNK_SIZE")
                if _imscc_max_raw:
                    try:
                        _imscc_max_v = int(_imscc_max_raw)
                        if _imscc_max_v > 0:
                            _imscc_chunk_kwargs["max_chunk_size"] = _imscc_max_v
                            _imscc_chunk_kwargs["target_chunk_size"] = max(
                                1, int(_imscc_max_v * 0.7)
                            )
                    except (TypeError, ValueError):
                        pass
                result = chunk_content(
                    parsed_items,
                    course_code,
                    boilerplate_spans=None,
                    ctx=ctx,
                    **_imscc_chunk_kwargs,
                )
                chunks = list(result.chunks)
            except Exception as exc:  # noqa: BLE001 — fail-soft on chunker error
                logger.warning(
                    "Phase 7c ST 16: chunk_content raised (%s); emitting "
                    "empty chunks shell.",
                    exc,
                )
                chunks = []

        # Track K: optional verbatim chunk overlap (mirrors the DART
        # path). When ``TRAINFORGE_CHUNK_OVERLAP_WORDS`` > 0, prepend the
        # verbatim trailing N words of each chunk's prior EMITTED chunk
        # onto the next (anti-fabrication — never synthesized). Default
        # 0 → no-op, byte-identical legacy emit; recorded in the manifest.
        _overlap_words = _resolve_chunk_overlap_words()
        if _overlap_words > 0:
            chunks = _apply_chunk_overlap(chunks, _overlap_words)

        # Per-CO coverage: mint one ``assessment_item`` chunk per
        # objective-anchored QTI item found in
        # the packaged ``06_assessments/`` XML, so the strict archival gate
        # (OBJECTIVE_NO_ASSESSMENT / UNCOVERED_TERMINAL_OUTCOME) sees every
        # TO/CO's quiz item as a chunk with harvestable
        # ``learning_outcome_refs``. Runs AFTER the overlap pass (quiz text
        # must never bleed into prose-overlap prefixes and vice versa).
        # Fail-soft: a harvest failure keeps the HTML chunkset intact — the
        # archival coverage gate downstream will surface the gap loudly.
        _qti_assessment_chunks: List[Dict[str, Any]] = []
        if qti_entries:
            try:
                _qti_assessment_chunks = _harvest_qti_assessment_chunks(
                    qti_entries,
                    create_chunk=_create_chunk,
                    existing_chunks=chunks,
                    course_code=course_code,
                )
            except Exception as exc:  # noqa: BLE001 — never break chunking
                logger.warning(
                    "W10 per-CO coverage: QTI assessment-chunk harvest "
                    "failed (%s); emitting HTML-derived chunks only.",
                    exc,
                )
                _qti_assessment_chunks = []
            if _qti_assessment_chunks:
                chunks.extend(_qti_assessment_chunks)
                logger.info(
                    "W10 per-CO coverage: harvested %d assessment_item "
                    "chunk(s) from %d packaged assessment XML doc(s).",
                    len(_qti_assessment_chunks), len(qti_entries),
                )

        # IRT difficulty-calibration scaffold: emit ONE difficulty_calibration
        # decision event per run (parity with process_course's chunk-emit
        # path). Guarded by _irt_enabled → byte-stable no-op when the flag is
        # off. Uses the gathered response-present + calibrated-map signals.
        if _irt_enabled:
            _emit_irt_difficulty_calibration_event(
                chunks=chunks,
                course_code=course_code,
                phase="trainforge-content-analysis",
                calibrated_map=_irt_calibrated_map,
                response_present=_irt_response_present,
            )

        # Persist chunks + manifest to LibV2/courses/<slug>/imscc_chunks/.
        # Phase 8 ST 3: route through `_resolve_libv2_root` (see helper
        # docstring for resolution chain). Default behaviour unchanged.
        course_dir = (
            _resolve_libv2_root(kwargs.get("libv2_root"))
            / "courses"
            / course_slug
        )
        chunks_dir = course_dir / "imscc_chunks"
        chunks_dir.mkdir(parents=True, exist_ok=True)
        chunks_path = chunks_dir / "chunks.jsonl"

        # Stream chunks as JSONL with hashing writer pattern so the
        # SHA-256 reflects exactly the bytes on disk.
        chunks_sha = _hashlib.sha256()
        with chunks_path.open("wb") as fh:
            for chunk in chunks:
                line = (json.dumps(chunk, ensure_ascii=False) + "\n").encode(
                    "utf-8"
                )
                fh.write(line)
                chunks_sha.update(line)
        chunks_sha256 = chunks_sha.hexdigest()

        # W3.H sub-task H1 (mirrored to IMSCC chunkset for symmetry):
        # build the canonical source_coverage block. Same heuristics
        # as the DART path — count one block per ContentSection (or
        # one block per item with no sections) and attribute drops via
        # boilerplate / image_only checks; remaining drop delta lands
        # in the `dedup` bucket. Symmetric so a downstream consumer
        # (W3.G master aggregator) sees the same shape regardless of
        # chunkset_kind.
        import re as _re_imscc
        from lib.governance.source_coverage import (
            build_source_coverage as _build_source_coverage_imscc,
        )
        _imscc_blocks_seen = 0
        _imscc_drop_boilerplate = 0
        _imscc_drop_image_only = 0
        for _it in parsed_items:
            sections_list = _it.get("sections") or []
            if not sections_list:
                _imscc_blocks_seen += 1
                _raw_html = (_it.get("raw_html") or "").strip()
                _text_probe = _re_imscc.sub(r"<[^>]+>", " ", _raw_html).strip()
                if _raw_html and not _text_probe and (
                    "<img" in _raw_html.lower()
                    or "<figure" in _raw_html.lower()
                ):
                    _imscc_drop_image_only += 1
                continue
            for section in sections_list:
                _imscc_blocks_seen += 1
                _content = (
                    getattr(section, "content", None)
                    if not isinstance(section, dict)
                    else section.get("content")
                ) or ""
                _components = (
                    getattr(section, "components", None)
                    if not isinstance(section, dict)
                    else section.get("components")
                ) or []
                if not str(_content).strip() and _components:
                    _imscc_drop_image_only += 1
        _imscc_attributable = _imscc_drop_boilerplate + _imscc_drop_image_only
        # W10 per-CO coverage: the QTI-derived assessment chunks are NOT
        # emitted from the HTML source blocks counted above, so exclude them
        # from the coverage-emit tally — including them would deflate
        # ``dropped_total`` and hide real HTML-block drops.
        _imscc_html_emitted = len(chunks) - len(_qti_assessment_chunks)
        _imscc_dropped_total = max(0, _imscc_blocks_seen - _imscc_html_emitted)
        _imscc_drop_reasons: Dict[str, int] = {}
        if _imscc_drop_boilerplate:
            _imscc_drop_reasons["boilerplate"] = _imscc_drop_boilerplate
        if _imscc_drop_image_only:
            _imscc_drop_reasons["image_only"] = _imscc_drop_image_only
        _imscc_dedup_delta = max(0, _imscc_dropped_total - _imscc_attributable)
        if _imscc_dedup_delta:
            _imscc_drop_reasons["merged_small_sections"] = _imscc_dedup_delta
        _imscc_source_coverage = _build_source_coverage_imscc(
            consumed_count=_imscc_blocks_seen,
            emitted_count=_imscc_html_emitted,
            drop_reasons=_imscc_drop_reasons,
            dropped_count=_imscc_dropped_total,
            label="imscc_chunking",
        )

        # Sibling manifest.json — must validate against
        # ``schemas/library/chunkset_manifest.schema.json`` per Phase
        # 7b ST 12 (symmetric across DART + IMSCC). Required:
        # chunks_sha256, chunker_version, chunkset_kind,
        # source_imscc_sha256 (conditional on chunkset_kind=imscc).
        # Optional: chunks_count, generated_at, source_coverage (W3.H H1).
        # W0.6 emit-time tripwire (mirrors the DART path): scan emitted chunk
        # ids for whitespace, log loudly, and stamp the manifest.
        _ws_chunk_ids = _assert_no_whitespace_chunk_ids(chunks)
        if _ws_chunk_ids:
            logger.warning(
                "W0.6: %d IMSCC chunk id(s) contain whitespace for "
                "course_code=%r (e.g. %r); the id-prefix grounding gate will "
                "not match.",
                len(_ws_chunk_ids), course_code, _ws_chunk_ids[0],
            )
        manifest = {
            "chunks_sha256": chunks_sha256,
            "chunker_version": chunker_version,
            # Chunk-TEXT extraction-contract version (orthogonal to
            # chunker_version's emit shape). See the DART emit for rationale.
            "extraction_contract": _resolve_extraction_contract(),
            "chunkset_kind": "imscc",
            "source_imscc_sha256": source_imscc_sha256,
            "chunks_count": len(chunks),
            "generated_at": datetime.utcnow().isoformat() + "Z",
            "source_coverage": _imscc_source_coverage,
        }
        # Track K: record the overlap budget for replay (omitted when off
        # so the manifest stays byte-identical to the legacy emit).
        if _overlap_words > 0:
            manifest["overlap_words"] = _overlap_words
        # W0.6: surface the whitespace-id defect in the manifest (omitted when
        # clean so the manifest stays byte-identical to the legacy emit).
        if _ws_chunk_ids:
            manifest["chunk_id_whitespace_warning"] = {
                "count": len(_ws_chunk_ids),
                "sample_ids": _ws_chunk_ids[:5],
            }
        manifest_path = chunks_dir / "manifest.json"
        # W0.7: atomic temp-then-replace manifest write.
        _atomic_write_text(
            manifest_path,
            json.dumps(manifest, indent=2, ensure_ascii=False),
        )

        return json.dumps({
            "success": True,
            "imscc_chunks_path": str(chunks_path),
            "imscc_chunks_sha256": chunks_sha256,
            "manifest_path": str(manifest_path),
            "course_slug": course_slug,
            "chunks_count": len(chunks),
            "source_html_count": len(html_entries),
            "qti_assessment_chunks_count": len(_qti_assessment_chunks),
            "source_imscc_sha256": source_imscc_sha256,
            "chunker_version": chunker_version,
        })

    registry["run_imscc_chunking"] = _run_imscc_chunking

    # ============================================================================
    # WS2 — run_vector_indexing: deterministic on-device vector-index build.
    #
    # Backs the ``rag-indexer`` agent (``rag_training`` ``indexing`` phase) via
    # the AGENT_TOOL_MAPPING flip from ``analyze_imscc_content`` (which only
    # counted HTML files and never produced an index) to this real tool.
    #
    # Deterministic transformation (no LLM dispatch, no DecisionCapture
    # obligation — precedent: ``_run_dart_chunking``). It resolves the course
    # dir under the LibV2 root, builds an EmbeddingClient from the env-configured
    # provider, embeds the resolved chunkset, and persists
    # ``vector_index/{embeddings.npy,id_map.json,manifest.json}``.
    #
    # FAIL-CLOSED CONTRACT (anti-silent-degradation): when the embedding
    # backend is unavailable (weights not cached, server down, extras missing)
    # the tool returns ``{"success": false, "error": ...}`` and the phase FAILS.
    # There is NO file-counting / lexical fallback — the indexing phase can no
    # longer "succeed" without an actual index.
    # ============================================================================
    async def _run_vector_indexing(**kwargs):
        """Build the per-course vector index. Fail-closed; deterministic.

        Resolved kwargs (workflows.yaml ``inputs_from`` / param mapping):
            course_name (aliases: course / name / course_code): the course
                whose chunkset is embedded (resolves the LibV2 course slug).
            chunkset (optional): ``imscc`` | ``dart`` | ``corpus-legacy`` pin;
                defaults to the canonical resolver precedence.
            provider (optional): embedding provider registry key; defaults to
                ``ED4ALL_EMBEDDING_PROVIDER`` or ``st``.
            model (optional): embedding model id override.
            text_field_policy (optional): defaults to ``text+heading``.
            force (optional): rebuild a still-fresh index.
            libv2_root (optional): LibV2 root override.

        Envelope (success):
            {"success": true, "manifest_path", "embeddings_path",
             "id_map_path", "vector_index_dir", "model_fingerprint",
             "embedding_model_id", "embedding_provider", "embedding_dim",
             "chunks_count", "chunkset_kind", "source_chunks_sha256",
             "course_slug"}

        Envelope (fail-closed): {"success": false, "error", "error_type",
            "course_slug"} — the phase fails; no partial index, no fallback.
        """
        course_name = (
            kwargs.get("course_name")
            or kwargs.get("course")
            or kwargs.get("name")
            or kwargs.get("course_code")
            or ""
        )
        course_name = course_name or "UNKNOWN"
        course_slug = course_name.lower().replace("_", "-").replace(" ", "-")

        chunkset = kwargs.get("chunkset") or None
        provider = kwargs.get("provider") or None
        model_id = kwargs.get("model") or kwargs.get("model_id") or None
        text_field_policy = kwargs.get("text_field_policy") or "text+heading"
        force = bool(kwargs.get("force", False))

        # W2.4: anti-poisoning — a ``fake``-provider index carries
        # non-semantic vectors and must never masquerade as a real index on
        # a production read path. Mirror the read-side ``FakeIndexRefused``
        # guard at BUILD time, reusing the existing ED4ALL_EMBEDDING_ALLOW_FAKE
        # flag (parse-with-fallback: only the explicit truthy tokens allow it).
        _allow_fake = (
            os.environ.get("ED4ALL_EMBEDDING_ALLOW_FAKE", "")
            .strip().lower() in {"1", "true", "yes", "on"}
        )

        def _emit_index_decision(strategy: str, detail: str) -> None:
            """W2.4: best-effort DecisionCapture for the (re)index strategy
            (``built`` / ``idempotent_reuse`` / ``fake_provider_refused``).
            Capture failure must never break the indexing phase."""
            try:
                from lib.decision_capture import (
                    DecisionCapture as _DecisionCapture,  # noqa: PLC0415
                )
                _cap = _DecisionCapture(
                    course_code=course_name,
                    phase="vector_indexing",
                    tool="pipeline",
                )
                _cap.log_decision(
                    decision_type="index_strategy",
                    decision=f"index_strategy={strategy}",
                    rationale=(
                        f"run_vector_indexing for course {course_slug}: "
                        f"strategy={strategy}, provider={provider or 'env'}, "
                        f"model={model_id or 'default'}, force={force}, "
                        f"allow_fake={_allow_fake}, detail={detail}."
                    ),
                )
            except Exception as _cap_exc:  # noqa: BLE001 — capture must not break indexing
                logger.debug(
                    "index_strategy decision capture failed: %s", _cap_exc
                )

        course_dir = (
            _resolve_libv2_root(kwargs.get("libv2_root"))
            / "courses"
            / course_slug
        )

        # Lazy imports so this module has no import-time coupling to the
        # embedding / index packages (slim installs stay importable).
        try:
            from lib.embedding.providers import (
                EmbeddingBackendUnavailable,
                build_embedding_client,
            )
            from LibV2.tools.libv2.vector_index import (
                SemanticIndexMissing,
                VectorIndexManifest,
                build_vector_index,
            )
        except Exception as exc:  # noqa: BLE001 — missing index/embedding deps
            return json.dumps({
                "success": False,
                "error": (
                    f"vector-index dependencies unavailable: {exc}. Install the "
                    f"[embedding] extra and ensure LibV2 is on the path."
                ),
                "error_type": "dependency_missing",
                "course_slug": course_slug,
            })

        if not course_dir.exists():
            return json.dumps({
                "success": False,
                "error": (
                    f"course directory not found at {course_dir}; archive the "
                    f"course to LibV2 (and run the chunking phase) before "
                    f"indexing."
                ),
                "error_type": "course_missing",
                "course_slug": course_slug,
            })

        # Build the embedding client from the env-configured provider. The
        # build path is provision-time, so offline=False (a real provider may
        # download weights here — never on the query path).
        _index_strategy = "built"
        try:
            client = build_embedding_client(
                provider, model_id, offline=False
            )
            # W2.4: refuse to WRITE a fake-provider index into a production
            # course dir unless ED4ALL_EMBEDDING_ALLOW_FAKE is set. Checked
            # BEFORE build_vector_index so no poisoned index is written to
            # disk (the read path already refuses to load one).
            _client_provider = ""
            try:
                _client_provider = str(
                    dict(client.model_fingerprint()).get("provider_name")
                    or ""
                )
            except Exception:  # noqa: BLE001 — fingerprint probe best-effort
                _client_provider = ""
            if _client_provider == "fake" and not _allow_fake:
                _emit_index_decision(
                    "fake_provider_refused",
                    "fake provider resolved and ED4ALL_EMBEDDING_ALLOW_FAKE "
                    "unset — refused before build",
                )
                return json.dumps({
                    "success": False,
                    "error": (
                        f"refusing to build a fake-provider vector index for "
                        f"{course_slug}: the deterministic 'fake' embedding "
                        f"provider produces non-semantic vectors. Set "
                        f"ED4ALL_EMBEDDING_ALLOW_FAKE=true to permit it "
                        f"(tests only), or select a real embedding provider."
                    ),
                    "error_type": "fake_provider_refused",
                    "error_code": "FAKE_INDEX_REFUSED",
                    "course_slug": course_slug,
                })
            manifest = build_vector_index(
                course_dir,
                client=client,
                chunkset=chunkset,
                text_field_policy=text_field_policy,
                force=force,
            )
        except EmbeddingBackendUnavailable as exc:
            # Honest fail-closed: NO file-counting fallback.
            return json.dumps({
                "success": False,
                "error": (
                    f"embedding backend unavailable; the indexing phase fails "
                    f"closed (no lexical/file-count fallback): {exc}"
                ),
                "error_type": "embedding_backend_unavailable",
                "course_slug": course_slug,
            })
        except SemanticIndexMissing as exc:
            return json.dumps({
                "success": False,
                "error": str(exc),
                "error_type": "chunkset_missing",
                "course_slug": course_slug,
            })
        except FileExistsError as exc:
            # W2.4 idempotency: a still-fresh pre-existing index is NOT a
            # phase failure. Re-running the indexing phase over an
            # already-current index (its source_chunks_sha256 still matches
            # the live chunkset) is a clean no-op — load the existing
            # manifest and return success. A forced rebuild that still hit
            # FileExistsError would be a genuine surprise (force bypasses the
            # freshness guard), so surface it.
            if force:
                return json.dumps({
                    "success": False,
                    "error": str(exc),
                    "error_type": "fresh_index_exists",
                    "course_slug": course_slug,
                })
            try:
                manifest = VectorIndexManifest.from_file(
                    course_dir / "vector_index" / "manifest.json"
                )
            except Exception as _load_exc:  # noqa: BLE001 — manifest re-read
                return json.dumps({
                    "success": False,
                    "error": (
                        f"a fresh vector index exists at {course_dir}/"
                        f"vector_index but its manifest could not be re-loaded "
                        f"for idempotent success: {_load_exc}"
                    ),
                    "error_type": "build_error",
                    "course_slug": course_slug,
                })
            # W2.4: even on the idempotent path, an on-disk fake index must
            # not report success unless explicitly allowed (it may have been
            # built earlier under ED4ALL_EMBEDDING_ALLOW_FAKE).
            if (
                str(getattr(manifest, "embedding_provider", "")) == "fake"
                and not _allow_fake
            ):
                _emit_index_decision(
                    "fake_provider_refused",
                    "existing fresh index is fake-provider and "
                    "ED4ALL_EMBEDDING_ALLOW_FAKE unset",
                )
                return json.dumps({
                    "success": False,
                    "error": (
                        f"a fresh vector index exists for {course_slug} but "
                        f"was built with the 'fake' embedding provider; set "
                        f"ED4ALL_EMBEDDING_ALLOW_FAKE=true or rebuild with a "
                        f"real provider (--force)."
                    ),
                    "error_type": "fake_provider_refused",
                    "error_code": "FAKE_INDEX_REFUSED",
                    "course_slug": course_slug,
                })
            _index_strategy = "idempotent_reuse"
        except GracefulStopRequested:
            # A pre-encode / pre-write stop check raised: propagate the pause
            # (GracefulStopRequested subclasses RuntimeError, so the broad
            # handler below would otherwise marshal it as a build_error).
            raise
        except Exception as exc:  # noqa: BLE001 — surface, never silently degrade
            return json.dumps({
                "success": False,
                "error": f"vector-index build failed: {exc}",
                "error_type": "build_error",
                "course_slug": course_slug,
            })

        _emit_index_decision(
            _index_strategy,
            f"chunks_count={getattr(manifest, 'chunks_count', '?')}, "
            f"provider={getattr(manifest, 'embedding_provider', '?')}",
        )
        index_dir = course_dir / "vector_index"
        try:
            fingerprint = dict(client.model_fingerprint())
        except Exception:  # noqa: BLE001 — fingerprint is best-effort surface
            fingerprint = {}

        return json.dumps({
            "success": True,
            "vector_index_dir": str(index_dir),
            "manifest_path": str(index_dir / "manifest.json"),
            "embeddings_path": str(index_dir / "embeddings.npy"),
            "id_map_path": str(index_dir / "id_map.json"),
            "model_fingerprint": fingerprint,
            "embedding_model_id": manifest.embedding_model_id,
            "embedding_provider": manifest.embedding_provider,
            "embedding_dim": manifest.embedding_dim,
            "chunks_count": manifest.chunks_count,
            "chunkset_kind": manifest.chunkset_kind,
            "source_chunks_sha256": manifest.source_chunks_sha256,
            "course_slug": course_slug,
            # W2.4: "built" on a fresh build, "idempotent_reuse" when a
            # still-fresh index was re-used instead of failing the phase.
            "index_strategy": _index_strategy,
        })

    registry["run_vector_indexing"] = _run_vector_indexing

    # ================================================================= #
    # Runtime registry stubs for the 7 tools that AGENT_TOOL_MAPPING     #
    # routes but _build_tool_registry previously skipped (MCP audit      #
    # Q1 critical finding). Each wrapper imports the @mcp.tool()         #
    # implementation at call time (register_* functions create closures  #
    # — we extract them into a capturing MCP stand-in the same way       #
    # test_stage_dart_outputs.py::_CapturingMCP does).                   #
    # ================================================================= #
    class _CapturingMCP:
        """Minimal stand-in for FastMCP: captures decorated tools by name."""
        def __init__(self) -> None:
            self.tools: dict = {}

        def tool(self):  # noqa: D401 - mimics FastMCP's .tool() decorator
            def _decorator(fn):
                self.tools[fn.__name__] = fn
                return fn
            return _decorator

    def _capture_courseforge_tools() -> dict:
        try:
            from MCP.tools.courseforge_tools import register_courseforge_tools
        except Exception as exc:  # noqa: BLE001
            logger.warning(f"Courseforge tool capture failed: {exc}")
            return {}
        mcp_cap = _CapturingMCP()
        register_courseforge_tools(mcp_cap)
        return mcp_cap.tools

    def _capture_trainforge_tools() -> dict:
        try:
            from MCP.tools.trainforge_tools import register_trainforge_tools
        except Exception as exc:  # noqa: BLE001
            logger.warning(f"Trainforge tool capture failed: {exc}")
            return {}
        mcp_cap = _CapturingMCP()
        register_trainforge_tools(mcp_cap)
        return mcp_cap.tools

    async def _get_courseforge_status(**kwargs):
        """Registry wrapper: delegates to courseforge_tools.get_courseforge_status."""
        tools = _capture_courseforge_tools()
        tool = tools.get("get_courseforge_status")
        if tool is None:
            return json.dumps({"error": "get_courseforge_status tool unavailable"})
        return await tool()

    registry["get_courseforge_status"] = _get_courseforge_status

    async def _intake_imscc_package(**kwargs):
        """Registry wrapper: delegates to courseforge_tools.intake_imscc_package."""
        imscc_path = kwargs.get("imscc_path") or kwargs.get("package") or ""
        output_dir = kwargs.get("output_dir") or kwargs.get("extract_to") or ""
        remediate = kwargs.get("remediate", True)
        tools = _capture_courseforge_tools()
        tool = tools.get("intake_imscc_package")
        if tool is None:
            return json.dumps({"error": "intake_imscc_package tool unavailable"})
        return await tool(
            imscc_path=imscc_path,
            output_dir=output_dir,
            remediate=remediate,
        )

    registry["intake_imscc_package"] = _intake_imscc_package

    async def _remediate_course_content(**kwargs):
        """Registry wrapper: delegates to courseforge_tools.remediate_course_content."""
        project_id = kwargs.get("project_id") or ""
        remediation_types = kwargs.get("remediation_types")
        tools = _capture_courseforge_tools()
        tool = tools.get("remediate_course_content")
        if tool is None:
            return json.dumps({"error": "remediate_course_content tool unavailable"})
        return await tool(
            project_id=project_id,
            remediation_types=remediation_types,
        )

    registry["remediate_course_content"] = _remediate_course_content

    async def _validate_assessment(**kwargs):
        """Registry wrapper: delegates to trainforge_tools.validate_assessment."""
        assessment_id = (
            kwargs.get("assessment_id")
            or kwargs.get("assessment")
            or kwargs.get("id")
            or ""
        )
        tools = _capture_trainforge_tools()
        tool = tools.get("validate_assessment")
        if tool is None:
            return json.dumps({"error": "validate_assessment tool unavailable"})
        return await tool(assessment_id=assessment_id)

    registry["validate_assessment"] = _validate_assessment

    return registry


def _get_phase_status(workflow: dict, phase_name: str) -> dict:
    """Extract status for a specific phase from workflow tasks."""
    tasks = workflow.get("tasks", [])

    # Map phase names to agent types. The conversion phase is declared
    # ``semantik_conversion`` (task #19 Stage 3d); the legacy ``dart_conversion``
    # key is kept for status lookups on old workflows. Both resolve to the same
    # converter agents (new ``semantik-converter`` + legacy ``dart-converter``).
    phase_agents = {
        "semantik_conversion": ["semantik-converter", "dart-converter"],
        "dart_conversion": ["semantik-converter", "dart-converter"],
        "staging": ["textbook-stager"],
        "objective_extraction": ["textbook-ingestor"],
        "source_mapping": ["source-router"],
        # Phase 6 ST 11: concept_extraction phase backed by
        # pedagogy-graph-builder agent.
        "concept_extraction": ["pedagogy-graph-builder"],
        "course_planning": ["course-outliner"],
        "content_generation": ["content-generator"],
        "packaging": ["brightspace-packager"],
        "trainforge_assessment": ["assessment-generator"],
        "libv2_archival": ["libv2-archivist"],
        "finalization": ["brightspace-packager"]
    }

    agents = phase_agents.get(phase_name, [])

    phase_tasks = [t for t in tasks if t.get("agent_type") in agents]

    if not phase_tasks:
        return {"status": "PENDING", "tasks": 0}

    statuses = [t.get("status") for t in phase_tasks]

    if all(s == "COMPLETE" for s in statuses):
        phase_status = "COMPLETE"
    elif any(s == "ERROR" for s in statuses):
        phase_status = "ERROR"
    elif any(s == "IN_PROGRESS" for s in statuses):
        phase_status = "IN_PROGRESS"
    else:
        phase_status = "PENDING"

    return {
        "status": phase_status,
        "tasks": len(phase_tasks),
        "completed": sum(1 for s in statuses if s == "COMPLETE"),
        "errors": sum(1 for s in statuses if s == "ERROR")
    }
